#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <string.h>

/*
 * Raspberry Pi 4 Model B – DFRobot Soil Moisture Sensor v2.0 via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND  (Pin 6)
 *   MCP3008 DGND -> GND  (Pin 6)
 *   MCP3008 CLK  -> GPIO11 (SCLK, Pin 23)
 *   MCP3008 DOUT -> GPIO9  (MISO, Pin 21)
 *   MCP3008 DIN  -> GPIO10 (MOSI, Pin 19)
 *   MCP3008 CS   -> GPIO8  (CE0,  Pin 24)
 *   MCP3008 CH0  -> DFRobot Soil Moisture Sensor v2.0 analog output
 *
 * The sensor's analog output is a voltage that varies with moisture
 * content. The MCP3008 ADC reads this voltage and converts it to a
 * 10-bit digital value (0–1023).
 */

#define SPI_CHANNEL 0          /* CE0 (GPIO8) */
#define SPI_SPEED   1000000    /* 1 MHz – well within MCP3008 3.3 V limit */
#define ADC_CHANNEL 0          /* MCP3008 single-ended channel 0 */
#define SAMPLE_PERIOD_US 1000000 /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 read                                                        */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 single-ended read (3-byte transfer):
 *   TX[0] = 0x01                       (start bit)
 *   TX[1] = (0x08 | channel) << 4      (single-ended + channel, upper nibble)
 *   TX[2] = 0x00                       (clock out remaining bits)
 *
 * Result:
 *   RX[1] bits 1..0  -> upper 2 data bits
 *   RX[2]           -> lower 8 data bits
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d (must be 0–7)\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio ------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 ----------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers ------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Soil Moisture Sensor (MCP3008 CH0) – sampling every 1 s\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);

        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed – continuing\n");
        } else {
            time_t now = time(NULL);
            char time_buf[32];
            strftime(time_buf, sizeof(time_buf), "%Y-%m-%d %H:%M:%S",
                     localtime(&now));
            printf("[%s] Moisture ADC: %4d\n", time_buf, adc_value);
            fflush(stdout);
        }

        /* Sleep 1 s, but wake early on signal */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup ---------------------------------------------------- */
    printf("\nShutting down...\n");
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

