#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADS1115 I2C address when ADDR pin is tied to GND */
#define ADS1115_ADDR 0x48

/* ADS1115 register addresses */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG     0x01

/*
 * Config register bits (16-bit, big-endian on the bus):
 *   [15]    OS       = 1  (begin single conversion)
 *   [14:12] MUX      = 100 (AIN0 single-ended)
 *   [11:9]  PGA      = 001 (+/-4.096 V)
 *   [8]     MODE     = 1  (single-shot)
 *   [7:5]   DR       = 100 (128 SPS)
 *   [4]     COMP_MODE= 0
 *   [3]     COMP_POL = 0
 *   [2]     COMP_LAT = 0
 *   [1:0]   COMP_QUE = 11 (disable comparator)
 * => 0xC283
 */
#define ADS1115_CONFIG 0xC283

/* Full-scale range for PGA = +/-4.096 V */
#define ADS1115_PGA_4096 4.096f

/* Conversion time at 128 SPS (~7.8 ms; use 10 ms for safety) */
#define ADS1115_CONV_MS 10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Trigger a single-shot conversion on the given channel (0-3) and
 * return the raw 16-bit signed result.  Returns 0 on success, -1 on error.
 */
static int ads1115_read_channel(int handle, uint8_t channel, int16_t *out)
{
    if (channel > 3) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    /*
     * Config register bits:
     *   MUX = channel (000=AIN0, 001=AIN1, 010=AIN2, 011=AIN3)
     *   PGA = 001 (+/-4.096 V)
     *   DR  = 100 (128 SPS)
     *   MODE= 1 (single-shot)
     *   OS  = 1 (start conversion)
     */
    uint16_t mux_bits = (uint16_t)(channel << 12);
    uint16_t config = 0x8000 | mux_bits | 0x0200 | 0x0080 | 0x0003;

    char cfg_buf[3];
    cfg_buf[0] = ADS1115_REG_CONFIG;
    cfg_buf[1] = (char)((config >> 8) & 0xFF);
    cfg_buf[2] = (char)(config & 0xFF);

    if (i2cWriteDevice(handle, cfg_buf, 3) < 0) {
        fprintf(stderr, "Error writing ADS1115 config register\n");
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(ADS1115_CONV_MS * 1000);

    char reg_buf[1] = { ADS1115_REG_CONVERSION };
    if (i2cWriteDevice(handle, reg_buf, 1) < 0) {
        fprintf(stderr, "Error selecting ADS1115 conversion register\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion register\n");
        return -1;
    }

    /* ADS1115 returns big-endian: MSB first */
    *out = (int16_t)(((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1]);
    return 0;
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the ADS1115 address */
    g_i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n",
                ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("MLX91219 current sensor reader via ADS1115\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int16_t raw;
        if (ads1115_read_channel(g_i2c_handle, 0, &raw) != 0) {
            fprintf(stderr, "Sensor read failed; continuing\n");
            gpioDelay(500000);
            continue;
        }

        /* Convert raw ADC count to voltage, then to current (amperes) */
        float voltage = (float)raw * ADS1115_PGA_4096 / 32768.0f;
        /*
         * MLX91219 transfer function: current (A) = voltage (V) / 1000.
         * Adjust the divisor if your sensor uses a different transfer curve.
         */
        float current = voltage / 1000.0f;

        printf("Current: %.4f A\n", current);
        fflush(stdout);

        gpioDelay(500000); /* 500 ms */
    }

    /* Clean up */
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

