/*
 * Raspberry Pi 3 Model B+ — KY-026 Flame Sensor + MCP3008 ADC
 *
 * Wiring:
 *   KY-026 D0  -> GPIO4  (BCM) — digital flame output
 *   MCP3008 VDD -> 3.3 V
 *   MCP3008 VREF -> 3.3 V
 *   MCP3008 AGND/DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (BCM, SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (BCM, SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (BCM, SPI0 MOSI)
 *   MCP3008 CS/SHDN -> GPIO8 (BCM, SPI0 CE0)
 *   MCP3008 CH0  -> KY-026 A0 (analog output)
 *
 * Build: gcc -O2 -Wall -o flame_logger flame_logger.c -lpigpio -lrt
 * Run:   sudo ./flame_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4    /* BCM GPIO4  — KY-026 D0 */
#define SPI_CHANNEL      0    /* SPI0 CE0  — BCM GPIO8  */
#define SPI_SPEED        1000000  /* 1 MHz */
#define SPI_FLAGS        0    /* Mode 0, active-low CE */
#define ADC_CHANNEL      0    /* MCP3008 single-ended CH0 */
#define LOG_FILE         "flame_data.csv"
#define SAMPLE_PERIOD_S  1

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 10-bit value from MCP3008 (single-ended, 0–7).                 */
/* Returns 0–1023 on success, -1 on SPI error.                        */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3-byte transfer, Mode 0, MSB-first):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
     *   tx[2] = 0x00                       (clock out low bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value.
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
static float adc_to_temperature(int adc_value)
{
    /*
     * Approximate temperature from ADC value.
     * KY-026 A0 output is proportional to ambient temperature.
     * This linear approximation is a placeholder — calibrate for your
     * specific module and environment.
     */
    return (float)adc_value * 0.1f;
}

/* ------------------------------------------------------------------ */
static void log_data(int flame_detected, float temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%d,%.2f\n", ts, flame_detected, temperature);
    } else {
        fprintf(fp, "1970-01-01 00:00:00,%d,%.2f\n", flame_detected, temperature);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- flame sensor pin as input --------------------------------- */
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_DOWN);

    /* --- SPI open --------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
