/*
 * Fire Detection System — Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - Keyes KY-026 Flame Sensor  -> GPIO4  (BCM) — digital input
 *   - LM393 Heat Sensor           -> ADS1115 on I2C bus 1, channel AIN0
 *   - Active-high buzzer          -> GPIO27 (BCM)
 *
 * Behavior:
 *   Polls both sensors every 100 ms.  When both sensors indicate a fire
 *   (flame + temperature > 60 °C) the buzzer sounds for 2 s and a timestamped
 *   event is appended to fire_log.txt.  If only the flame sensor is active,
 *   "Flame detected!" is logged.  If only the temperature exceeds 60 °C, the
 *   reading is logged.  I2C errors and missing sensors are logged and the
 *   application continues.  SIGINT triggers a clean shutdown.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o fire_detect fire_detect.c -lpigpio -lrt
 *   (pigpio must be installed and the daemon started: sudo pigpiod)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define FLAME_SENSOR_PIN    4          /* BCM GPIO4  — KY-026 digital out */
#define BUZZER_PIN          27         /* BCM GPIO27 — active-high buzzer */
#define I2C_BUS             1          /* /dev/i2c-1 on RPi 3B+ */
#define ADS1115_ADDR        0x48       /* A0->GND, A1->GND, A2->GND */
#define ADS1115_REG_CONV    0x00
#define ADS1115_REG_CONFIG  0x01
#define TEMP_THRESHOLD      60.0f      /* °C */
#define POLL_INTERVAL_US    100000     /* 100 ms */
#define DEBOUNCE_DELAY_US   50000      /* 50 ms  */
#define BUZZER_DURATION_US  2000000    /* 2 s    */

/* ADS1115 config: single-shot, AIN0 single-ended, ±4.096 V, 128 SPS,
 * continuous mode disabled (single-shot requires bit 8 cleared). */
#define ADS1115_CFG_BASE    0x8000     /* OS bit */
#define ADS1115_CFG_MUX_A0  0x4000     /* MUX[14:12] = 100 — AIN0 single-ended */
#define ADS1115_CFG_PGA_4V  0x0200     /* PGA[11:9] = 001 — ±4.096 V */
#define ADS1115_CFG_DR_128  0x0080     /* DR[7:5] = 100 — 128 SPS */
#define ADS1115_CFG_CQUE_NONE 0x0003   /* Disable comparator */
#define ADS1115_CFG        (ADS1115_CFG_BASE | ADS1115_CFG_MUX_A0 | \
                           ADS1115_CFG_PGA_4V | ADS1115_CFG_DR_128 | \
                           ADS1115_CFG_CQUE_NONE)

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;
static int   g_i2c_handle = -1;

/* --------------------------- Function prototypes -------------------------- */
static void signal_handler(int sig);
static int  init_gpio(void);
static int  init_i2c(void);
static int  read_flame_sensor(void);
static float read_temperature(void);
static void activate_buzzer(void);
static void log_event(const char *msg);
static void cleanup(void);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- GPIO init ------------------------------- */
static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                FLAME_SENSOR_PIN);
        return -1;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n",
                BUZZER_PIN);
        return -1;
    }

    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise buzzer state.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------- I2C init -------------------------------- */
static int init_i2c(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed on bus %d addr 0x%02X "
                        "(code %d).\n", I2C_BUS, ADS1115_ADDR,
                        g_i2c_handle);
        return -1;
    }

    /* Write config register to start continuous conversion. */
    uint16_t cfg = ADS1115_CFG;
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (char)(cfg >> 8);
    buf[2] = (char)(cfg & 0xFF);

    if (i2cWriteDevice(g_i2c_handle, buf, 3) < 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config register.\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    return 0;
}

/* --------------------------- Flame sensor read --------------------------- */
static int read_flame_sensor(void)
{
    static int last_state = 0;
    static uint32_t last_change_tick = 0;
    uint32_t now = gpioTick();

    int raw = gpioRead(FLAME_SENSOR_PIN);
    if (raw < 0) {
        fprintf(stderr, "Warning: gpioRead failed on flame sensor pin.\n");
        return 0;
    }

    if (raw != last_state) {
        if ((now - last_change_tick) > DEBOUNCE_DELAY_US) {
            last_state = raw;
            last_change_tick = now;
        }
    }

    return last_state;
}

/* --------------------------- Temperature read ---------------------------- */
static float read_temperature(void)
{
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Warning: I2C handle invalid — cannot read temperature.\n");
        return -1000.0f;
    }

    /* Trigger a single-shot conversion by writing the config register. */
    uint16_t cfg = ADS1115_CFG;
    char cfg_buf[3];
    cfg_buf[0] = ADS1115_REG_CONFIG;
    cfg_buf[1] = (char)(cfg >> 8);
    cfg_buf[2] = (char)(cfg & 0xFF);

    if (i2cWriteDevice(g_i2c_handle, cfg_buf, 3) < 0) {
        fprintf(stderr, "Warning: failed to trigger ADS1115 conversion.\n");
        return -1000.0f;
    }

    /* Wait for conversion to complete (~8 ms at 128 SPS). */
    gpioDelay(10000);

    /* Point to the conversion register and read 2 bytes. */
    char reg_buf[1] = { ADS1115_REG_CONV };
    if (i2cWriteDevice(g_i2c_handle, reg_buf, 1) < 0) {
        fprintf(stderr, "Warning: failed to set ADS1115 read pointer.\n");
        return -1000.0f;
    }

    char data[2];
    if (i2cReadDevice(g_i2c_handle, data, 2) < 0) {
        fprintf(stderr, "Warning: failed to read ADS1115 conversion register.\n");
        return -1000.0f;
    }

    int16_t raw = (int16_t)(((uint16_t)(uint8_t)data[0] << 8) |
                            (uint8_t)data[1]);

    /* ±4.096 V range, 16-bit signed → 1 bit = 125 µV.
     * LM393 outputs 10 mV/°C → raw / 80 ≈ °C. */
    float temperature = (float)raw / 80.0f;
    return temperature;
}

/* ------------------------------- Buzzer ---------------------------------- */
static void activate_buzzer(void)
{
    if (gpioWrite(BUZZER_PIN, 1) < 0) {
        fprintf(stderr, "Warning: failed to activate buzzer.\n");
        return;
    }
    gpioDelay(BUZZER_DURATION_US);
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to deactivate buzzer.\n");
    }
}

/* ------------------------------- Logging --------------------------------- */
static void log_event(const char *msg)
{
    if (g_log_file == NULL) {
        fprintf(stderr, "Warning: log file not open — event lost: %s\n", msg);
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Warning: localtime_r failed.\n");
        return;
    }

    fprintf(g_log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(g_log_file);
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    /* Ensure buzzer is off before terminating pigpio. */
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }

    if (init_gpio() < 0) {
        return 1;
    }

    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    g_log_file = fopen("fire_log.txt", "a");
    if (g_log_file == NULL) {
        perror("fopen(fire_log.txt)");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int flame = read_flame_sensor();
        float temp = read_temperature();

        if (flame && temp > TEMP_THRESHOLD) {
            activate_buzzer();
            log_event("Fire detected!");
        } else if (flame) {
            log_event("Flame detected!");
        } else if (temp > TEMP_THRESHOLD) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Temperature: %.2f C", temp);
            log_event(msg);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

