    cfg_buf[1] = (char)(cfg >> 8);
    cfg_buf[2] = (char)(cfg & 0xFF);

    if (i2cWriteDevice(g_i2c_handle, cfg_buf, 3) < 0) {
        fprintf(stderr, "Warning: failed to trigger ADS1115 conversion.\n");
        return -1000.0f;
    }

    /* Wait for conversion to complete (~8 ms at 128 SPS). */
    gpioDelay(10000);

    /* Point to the conversion register and read 2 bytes. */
    char reg_buf[1] = { ADS1115_REG_CONV };
    if (i2cWriteDevice(g_i2c_handle, reg_buf, 1) < 0) {
        fprintf(stderr, "Warning: failed to set ADS1115 read pointer.\n");
        return -1000.0f;
    }

    char data[2];
    if (i2cReadDevice(g_i2c_handle, data, 2) < 0) {
        fprintf(stderr, "Warning: failed to read ADS1115 conversion register.\n");
        return -1000.0f;
    }

    int16_t raw = (int16_t)(((uint16_t)(uint8_t)data[0] << 8) |
                            (uint8_t)data[1]);

    /* ±4.096 V range, 16-bit signed → 1 bit = 125 µV.
     * LM393 outputs 10 mV/°C → raw / 80 ≈ °C. */
    float temperature = (float)raw / 80.0f;
    return temperature;
}

/* ------------------------------- Buzzer ---------------------------------- */
static void activate_buzzer(void)
{
    if (gpioWrite(BUZZER_PIN, 1) < 0) {
        fprintf(stderr, "Warning: failed to activate buzzer.\n");
        return;
    }
    gpioDelay(BUZZER_DURATION_US);
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to deactivate buzzer.\n");
    }
}

/* ------------------------------- Logging --------------------------------- */
static void log_event(const char *msg)
{
    if (g_log_file == NULL) {
        fprintf(stderr, "Warning: log file not open — event lost: %s\n", msg);
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Warning: localtime_r failed.\n");
        return;
    }

    fprintf(g_log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(g_log_file);
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    /* Ensure buzzer is off before terminating pigpio. */
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }

    if (init_gpio() < 0) {
        return 1;
    }

    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    g_log_file = fopen("fire_log.txt", "a");
    if (g_log_file == NULL) {
        perror("fopen(fire_log.txt)");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        gpioTerminate();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int flame = read_flame_sensor();
        float temp = read_temperature();

        if (flame && temp > TEMP_THRESHOLD) {
            activate_buzzer();
            log_event("Fire detected!");
        } else if (flame) {
            log_event("Flame detected!");
        } else if (temp > TEMP_THRESHOLD) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Temperature: %.2f C", temp);
            log_event(msg);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

