#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>
#include <unistd.h>

/* Configuration */
#define I2C_BUS 1
#define I2C_ADDR 0x48 /* Example I2C address for ADS1115 */
#define LOG_FILE "co_log.txt"
#define SAMPLE_INTERVAL 5 /* seconds */

/* ADS1115 Registers */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

/* ADS1115 Config: AIN0 single-ended, +/-4.096V, 128 SPS, continuous */
#define ADS1115_CONFIG_BASE 0x8000 /* OS bit */
#define ADS1115_CONFIG_MUX_AIN0 0x4000
#define ADS1115_CONFIG_PGA_4_096V 0x0200
#define ADS1115_CONFIG_MODE_CONT 0x0000
#define ADS1115_CONFIG_DR_128SPS 0x0080
#define ADS1115_CONFIG_CQUE_NONE 0x0003

#define ADS1115_CONFIG (ADS1115_CONFIG_BASE | ADS1115_CONFIG_MUX_AIN0 | \
                        ADS1115_CONFIG_PGA_4_096V | ADS1115_CONFIG_MODE_CONT | \
                        ADS1115_CONFIG_DR_128SPS | ADS1115_CONFIG_CQUE_NONE)

/* Calibration parameters (example values, must be calibrated for your specific sensor) */
#define R0 10000.0 /* Sensor resistance in clean air (Ohms) */
#define RL 10000.0 /* Load resistance (Ohms) */
#define A 100000.0 /* Calibration constant A */
#define B 100.0    /* Calibration constant B */

/* Global variables */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int initialize_i2c(void);
static int read_adc_raw(int16_t *raw_value);
static float calculate_ppm(int16_t raw_value);
static int log_data(float ppm);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* Initialize I2C and ADS1115 */
static int initialize_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", I2C_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }

    /* Write config to ADS1115 to start continuous conversion */
    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (ADS1115_CONFIG >> 8) & 0xFF;
    config_buf[2] = ADS1115_CONFIG & 0xFF;

    if (i2cWriteDevice(i2c_handle, config_buf, 3) < 0) {
        fprintf(stderr, "Failed to write ADS1115 config\n");
        i2cClose(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Read raw ADC value from ADS1115 */
static int read_adc_raw(int16_t *raw_value) {
    char reg_buf[1] = {ADS1115_REG_CONVERSION};
    char data_buf[2];

    /* Point to conversion register */
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) < 0) {
        return -1;
    }

    /* Read 2 bytes */
    if (i2cReadDevice(i2c_handle, data_buf, 2) != 2) {
        return -1;
    }

    *raw_value = (int16_t)((data_buf[0] << 8) | data_buf[1]);
    return 0;
}

/* Calculate CO concentration in ppm */
static float calculate_ppm(int16_t raw_value) {
    /* Convert raw ADC value to voltage (assuming +/-4.096V range, 16-bit signed) */
    float voltage = (raw_value / 32767.0) * 4.096;

    /* Calculate sensor resistance (Rs) */
    float rs = (RL * (4.096 - voltage)) / voltage;

    /* Calculate ratio of sensor resistance to clean air resistance (Rs/R0) */
    float ratio = rs / R0;

    /* Calculate CO concentration using logarithmic calibration curve */
    float ppm = A * pow(ratio, -B);

    return ppm;
}

/* Log data to file */
static int log_data(float ppm) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(log_file, "%s, %.2f ppm\n", timestamp, ppm) < 0) {
        fprintf(stderr, "Failed to write to log file\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register signal handler");
        return 1;
    }

    /* Initialize I2C */
    if (initialize_i2c() != 0) {
        return 1;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    printf("CO monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        int16_t raw_value;

        if (read_adc_raw(&raw_value) != 0) {
            fprintf(stderr, "Failed to read ADC value. Check I2C connection.\n");
            /* Attempt to re-initialize I2C on failure */
            i2cClose(i2c_handle);
            i2c_handle = -1;
            if (initialize_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break;
            }
            continue;
        }

        float ppm = calculate_ppm(raw_value);

        if (log_data(ppm) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        printf("CO concentration: %.2f ppm\n", ppm);

        /* Wait for the next sample interval */
        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL, 0);
    }

    /* Cleanup */
    cleanup();
    printf("CO monitoring stopped.\n");

    return 0;
}

