/*
 * Raspberry Pi 3 Model B+ — KY-026 Flame Sensor + MCP3008 ADC
 *
 * Wiring:
 *   KY-026 D0  -> GPIO 4  (BCM) — digital flame output
 *   MCP3008 VDD-> 3.3 V
 *   MCP3008 VREF-> 3.3 V
 *   MCP3008 AGND-> GND
 *   MCP3008 DGND-> GND
 *   MCP3008 CLK  -> GPIO 11 (BCM, SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO 9  (BCM, SPI0 MISO)
 *   MCP3008 DIN  -> GPIO 10 (BCM, SPI0 MOSI)
 *   MCP3008 CS   -> GPIO 8  (BCM, SPI0 CE0)
 *   MCP3008 CH0  -> KY-026 A0 analog output
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define SPI_CHANNEL      0          /* CE0 on GPIO 8 */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CS */
#define ADC_CHANNEL      0          /* MCP3008 CH0 */
#define LOG_FILE         "flame_data.csv"
#define SAMPLE_PERIOD_US 1000000    /* 1 second */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* Returns 0–1023 on success, -1 on SPI error.                         */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3-byte transfer, Mode 0):
     *   Byte 0: 0x01                       (start bit)
     *   Byte 1: (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
     *   Byte 2: 0x00                       (clock out remaining bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in lower nibble
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(int flame_detected, int temperature)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d\n", timestamp, flame_detected, temperature) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- flame sensor pin as input --------------------------------- */
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLAME_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- SPI open --------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        int flame_detected = gpioRead(FLAME_SENSOR_PIN);
        if (flame_detected < 0) {
            fprintf(stderr, "gpioRead failed on pin %d\n", FLAME_SENSOR_PIN);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        int temperature = read_mcp3008(ADC_CHANNEL);
        if (temperature < 0) {
            fprintf(stderr, "ADC read failed — skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (log_data(flame_detected, temperature) != 0) {
            fprintf(stderr, "Logging failed — continuing\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

