#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define MICS4514_ADDR 0x04
#define CO_THRESHOLD 25.0
#define LOG_FILE "co_log.txt"
#define ALERT_FILE "alert_log.txt"
#define READ_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mics4514(int handle, uint16_t *ox, uint16_t *red) {
    char buf[4];
    int bytes = i2cReadDevice(handle, buf, 4);
    if (bytes != 4) {
        fprintf(stderr, "I2C read failed: expected 4 bytes, got %d\n", bytes);
        return -1;
    }
    *ox = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *red = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];
    return 0;
}

static float calculate_co_ppm(uint16_t ox) {
    return (float)ox * 0.1f;
}

static int log_data(float co_ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening " LOG_FILE);
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    fclose(fp);
    return 0;
}

static int log_alert(float co_ppm) {
    FILE *fp = fopen(ALERT_FILE, "a");
    if (!fp) {
        perror("Error opening " ALERT_FILE);
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, CO: %.2f ppm - ALERT!\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MICS4514_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", MICS4514_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    printf("MICS-4514 CO monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        uint16_t ox, red;
        if (read_mics4514(i2c_handle, &ox, &red) != 0) {
            fprintf(stderr, "Sensor read error, retrying in %d seconds...\n", READ_INTERVAL_SEC);
