/*
 * IMP23ABSU dual-channel sound-pressure-level logger for Raspberry Pi 4.
 *
 * The IMP23ABSU has an analog OUT pin; we bit-bang I2C on bus 1 using
 * GPIO2 (SDA) and GPIO3 (SCL) so the Pi can read the analog voltage
 * without requiring an I2C-capable MEMS driver.
 *
 * Build:  gcc -O2 -Wall -o audio_logger audio_logger.c -lpigpio -lrt
 * Run:    sudo ./audio_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS             1
#define SDA_PIN             2       /* BCM 2 */
#define SCL_PIN             3       /* BCM 3 */
#define SAMPLE_PERIOD_US    100000  /* 100 ms */
#define LOG_FILE            "audio_log.txt"
#define ERROR_VALUE         (-999.0f)

/* ---- I2C bit-bang primitives (open-collector style) ---- */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read one byte from the IMP23ABSU at the given 7-bit I2C address.
 * Returns 0..255 on success, or -1 on failure.
 */
static int imp23abs_read_byte(uint8_t addr)
{
    uint8_t data = 0;

    /* Start condition: pull SDA low while SCL is high (idle). */
    gpioSetMode(SDA_PIN, PI_OUTPUT);
    gpioSetMode(SCL_PIN, PI_OUTPUT);
    gpioWrite(SDA_PIN, 1);
    gpioWrite(SCL_PIN, 1);
    gpioDelay(5);
    gpioWrite(SDA_PIN, 0);
    gpioDelay(5);
    gpioWrite(SCL_PIN, 0);
    gpioDelay(5);

    /* Send 7-bit slave address, MSB first, with R/W=1 (read). */
    for (int i = 7; i >= 0; i--) {
        gpioWrite(SDA_PIN, (addr >> i) & 1);
        gpioDelay(5);
        gpioWrite(SCL_PIN, 1);
        gpioDelay(5);
        gpioWrite(SCL_PIN, 0);
        gpioDelay(5);
    }

    /* ACK: slave pulls SDA low. */
    gpioSetMode(SDA_PIN, PI_INPUT);
    gpioDelay(5);
    if (gpioRead(SDA_PIN)) {
        /* NACK — device not present or not responding. */
        gpioWrite(SCL_PIN, 1);
        gpioDelay(5);
        gpioWrite(SCL_PIN, 0);
        gpioDelay(5);
        return -1;
    }

    /* Read 8 data bits, MSB first. */
    for (int i = 7; i >= 0; i--) {
        gpioWrite(SCL_PIN, 1);
        gpioDelay(5);
        data = (data << 1) | (uint8_t)gpioRead(SDA_PIN);
        gpioWrite(SCL_PIN, 0);
        gpioDelay(5);
    }

    /* ACK: release SDA (idle high) and generate stop. */
    gpioSetMode(SDA_PIN, PI_OUTPUT);
    gpioWrite(SDA_PIN, 1);
    gpioDelay(5);
    gpioWrite(SCL_PIN, 1);
    gpioDelay(5);
    gpioWrite(SCL_PIN, 0);
    gpioDelay(5);

    return (int)data;
}

/*
 * Read sound-pressure level from an IMP23ABSU.
 * Returns the measured dB value, or ERROR_VALUE on failure.
 */
static float read_sound_pressure_level(uint8_t addr)
{
    int raw = imp23abs_read_byte(addr);
    if (raw < 0)
        return ERROR_VALUE;

    /*
     * Convert raw ADC value to dB.
     * The IMP23ABSU outputs a voltage proportional to the square root
     * of the sound pressure level, so dB = 20 * log10(V / Vref).
     * We approximate: dB = 20 * log10(raw / 255).
     */
    float voltage = (float)raw / 255.0f;
    if (voltage <= 0.0f)
        return ERROR_VALUE;

    return 20.0f * log10f(voltage);
}

/*
 * Append a timestamped average to the log file.
 */
static void log_audio_data(float avg)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[64];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f\n", ts, avg);
    } else {
        fprintf(fp, "1970-01-01 00:00:00,%.2f\n", avg);
    }

    fclose(fp);
}

int main(void)
{
    /* Install signal handlers for clean shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure bit-banged I2C pins as inputs. */
    gpioSetMode(SDA_PIN, PI_INPUT);
    gpioSetMode(SCL_PIN, PI_INPUT);
    gpioSetPullUpDown(SDA_PIN, PI_PUD_UP);
    gpioSetPullUpDown(SCL_PIN, PI_PUD_UP);

    /*
     * IMP23ABSU I2C addresses are 7-bit: 0x40..0x7F.
     * The exact address depends on the A0/A1 pins; here we use 0x40.
     */
    uint8_t addr1 = 0x40;
    uint8_t addr2 = 0x41;

    printf("IMP23ABSU dual-channel logger started.  Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        float l1 = read_sound_pressure_level(addr1);
        float l2 = read_sound_pressure_level(addr2);

        float avg = (l1 + l2) / 2.0f;
        log_audio_data(avg);

        printf("L1=%.2f dB  L2=%.2f dB  Avg=%.2f dB\n", l1, l2, avg);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown. */
    gpioWrite(SDA_PIN, 1);
    gpioWrite(SCL_PIN, 1);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

