/*
 * Raspberry Pi 4 Model B – Dual ADMP401 MEMS Microphone Sampler
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 (CE0 = GPIO8, CE1 = GPIO9)
 *   - MISO = GPIO9, MOSI = GPIO10, SCLK = GPIO11
 *   - ADMP401 #1 connected to MCP3008 channel 0
 *   - ADMP401 #2 connected to MCP3008 channel 1
 *   - LED on GPIO27 (BCM)
 *
 * Behavior:
 *   Samples one ADC sample per channel every 1 ms for a 100 ms window
 *   (100 samples).  Computes RMS for each channel, logs timestamp + RMS
 *   values to audio_events.csv, and lights the LED for 500 ms whenever
 *   either RMS exceeds HIGH_THRESHOLD.  Cleanly exits on SIGINT.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE_0   "/dev/spidev0.0"
#define SPI_DEVICE_1   "/dev/spidev0.1"
#define SPI_SPEED_HZ   1000000U
#define SPI_BITS        8
#define SPI_DELAY_US    0

#define LED_PIN         27
#define HIGH_THRESHOLD  0.8f
#define SAMPLE_PERIOD_US 1000U
#define WINDOW_MS       100
#define NUM_SAMPLES     (WINDOW_MS * 1000U / SAMPLE_PERIOD_US)
#define LED_ON_MS       500

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd0 = -1;
static int g_spi_fd1 = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0–1023 on success, -1 on error.
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = SPI_DELAY_US;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed on channel %u: %s\n",
                channel, strerror(errno));
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_rms(const int *samples, int n)
{
    double sum_sq = 0.0;
    for (int i = 0; i < n; i++)
        sum_sq += (double)samples[i] * (double)samples[i];
    return (float)sqrt(sum_sq / (double)n);
}

static void log_event(FILE *fp, float rms1, float rms2)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.4f,%.4f\n", ts, rms1, rms2) < 0)
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    if (fflush(fp) != 0)
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
}

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- LED pin --- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* --- SPI0 (CE0) --- */
    g_spi_fd0 = open(SPI_DEVICE_0, O_RDWR);
    if (g_spi_fd0 < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE_0, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd0, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto fail_spi0;
    }
    if (ioctl(g_spi_fd0, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto fail_spi0;
    }
    if (ioctl(g_spi_fd0, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto fail_spi0;
    }

    /* --- SPI1 (CE1) --- */
    g_spi_fd1 = open(SPI_DEVICE_1, O_RDWR);
    if (g_spi_fd1 < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE_1, strerror(errno));
        goto fail_spi0;
    }
    if (ioctl(g_spi_fd1, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE (fd1) failed: %s\n", strerror(errno));
        goto fail_spi1;
    }
    if (ioctl(g_spi_fd1, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD (fd1) failed: %s\n", strerror(errno));
        goto fail_spi1;
