    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd0, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto fail_spi0;
    }
    if (ioctl(g_spi_fd0, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto fail_spi0;
    }
    if (ioctl(g_spi_fd0, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto fail_spi0;
    }

    /* --- SPI1 (CE1) --- */
    g_spi_fd1 = open(SPI_DEVICE_1, O_RDWR);
    if (g_spi_fd1 < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE_1, strerror(errno));
        goto fail_spi0;
    }
    if (ioctl(g_spi_fd1, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE (fd1) failed: %s\n", strerror(errno));
        goto fail_spi1;
    }
    if (ioctl(g_spi_fd1, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD (fd1) failed: %s\n", strerror(errno));
        goto fail_spi1;
    }
    if (ioctl(g_spi_fd1, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ (fd1) failed: %s\n", strerror(errno));
        goto fail_spi1;
    }

    /* --- Log file --- */
    FILE *fp = fopen("audio_events.csv", "a");
    if (!fp) {
        fprintf(stderr, "Cannot open audio_events.csv: %s\n", strerror(errno));
        goto fail_spi1;
    }

    /* Write CSV header if file is empty */
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,rms_mic1,rms_mic2\n");
        fflush(fp);
    }

    /* --- Signal handling --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto fail_file;
    }

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    int mic1_samples[NUM_SAMPLES];
    int mic2_samples[NUM_SAMPLES];
    int sample_idx = 0;

    while (g_running) {
        int v1 = mcp3008_read(g_spi_fd0, 0);
        int v2 = mcp3008_read(g_spi_fd1, 1);

        if (v1 < 0 || v2 < 0) {
            fprintf(stderr, "SPI read error – skipping sample\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        mic1_samples[sample_idx] = v1;
        mic2_samples[sample_idx] = v2;
        sample_idx++;

        if (sample_idx >= NUM_SAMPLES) {
            float rms1 = calculate_rms(mic1_samples, NUM_SAMPLES);
            float rms2 = calculate_rms(mic2_samples, NUM_SAMPLES);

            log_event(fp, rms1, rms2);

            if (rms1 > HIGH_THRESHOLD || rms2 > HIGH_THRESHOLD) {
                gpioWrite(LED_PIN, 1);
                gpioDelay(LED_ON_MS * 1000U);
                gpioWrite(LED_PIN, 0);
            }

            sample_idx = 0;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    gpioWrite(LED_PIN, 0);
    fclose(fp);
    if (g_spi_fd1 >= 0) close(g_spi_fd1);
    if (g_spi_fd0 >= 0) close(g_spi_fd0);
    gpioTerminate();
    return EXIT_SUCCESS;

fail_file:
    fclose(fp);
fail_spi1:
    close(g_spi_fd1);
    g_spi_fd1 = -1;
fail_spi0:
    close(g_spi_fd0);
