#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Configuration */
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define LED_GPIO 17
#define SAMPLE_RATE_HZ 10
#define BUFFER_SIZE 100
#define CURRENT_THRESHOLD 50.0f
#define SENSITIVITY 0.1f
#define MAX_CONSECUTIVE_ERRORS 10

/* ADS1115 Registers */
#define ADS1115_REG_CONVERSION 0x00
#define ADS1115_REG_CONFIG 0x01

/* ADS1115 Config bits */
#define ADS1115_CFG_OS_BEGIN (1 << 15)
#define ADS1115_CFG_MUX_A0 (0x4000)
#define ADS1115_CFG_PGA_4_096V (0x0200)
#define ADS1115_CFG_MODE_SINGLE (0x0100)
#define ADS1115_CFG_DR_128SPS (0x0080)
#define ADS1115_CFG_CQUE_NONE (0x0003)

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;
static float current_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

/* Function prototypes */
static int initialize_i2c(void);
static int read_ads1115(int16_t *raw_value);
static float convert_to_current(int16_t raw_value);
static void add_to_buffer(float current);
static float calculate_average(void);
static void control_led(float average_current);
static void signal_handler(int signal);
static void cleanup(void);

/* Initialize I2C communication with the ADS1115 */
static int initialize_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, ADS1115_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

/* Read raw 16-bit value from ADS1115 channel A0 in single-shot mode */
static int read_ads1115(int16_t *raw_value) {
    if (raw_value == NULL) {
        return -1;
    }

    /* Write config: single-shot, A0 single-ended, PGA 4.096V, 128 SPS, no comparator */
    uint16_t config = ADS1115_CFG_OS_BEGIN | ADS1115_CFG_MUX_A0 | ADS1115_CFG_PGA_4_096V |
                      ADS1115_CFG_MODE_SINGLE | ADS1115_CFG_DR_128SPS | ADS1115_CFG_CQUE_NONE;

    char config_buf[3];
    config_buf[0] = ADS1115_REG_CONFIG;
    config_buf[1] = (config >> 8) & 0xFF;
    config_buf[2] = config & 0xFF;

    if (i2cWriteDevice(i2c_handle, config_buf, 3) < 0) {
        fprintf(stderr, "Error writing ADS1115 config register\n");
        return -1;
    }

    /* Wait for conversion to complete (~8 ms at 128 SPS) */
    gpioDelay(10000);

    /* Read conversion register (2 bytes) */
    char reg_buf[1] = {ADS1115_REG_CONVERSION};
    if (i2cWriteDevice(i2c_handle, reg_buf, 1) < 0) {
        fprintf(stderr, "Error selecting ADS1115 conversion register\n");
        return -1;
    }

    char data_buf[2];
    if (i2cReadDevice(i2c_handle, data_buf, 2) != 2) {
        fprintf(stderr, "Error reading ADS1115 conversion register\n");
        return -1;
    }

    *raw_value = (int16_t)((data_buf[0] << 8) | data_buf[1]);
    return 0;
}

/* Convert raw ADC value to current (Amperes) */
static float convert_to_current(int16_t raw_value) {
    return (float)raw_value * SENSITIVITY;
}

/* Add current reading to circular buffer */
static void add_to_buffer(float current) {
    current_buffer[buffer_index] = current;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

/* Calculate average current from buffered readings */
static float calculate_average(void) {
    if (buffer_count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < buffer_count; i++) {
        sum += current_buffer[i];
    }
    return sum / (float)buffer_count;
}

/* Control LED based on average current */
static void control_led(float average_current) {
    if (average_current > CURRENT_THRESHOLD) {
        gpioWrite(LED_GPIO, 1);
    } else {
        gpioWrite(LED_GPIO, 0);
    }
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set LED GPIO as output and ensure it is off */
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    /* Initialize I2C */
    if (initialize_i2c() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    int consecutive_errors = 0;

    while (program_running) {
        int16_t raw_value = 0;

        if (read_ads1115(&raw_value) == 0) {
            consecutive_errors = 0;
            float current = convert_to_current(raw_value);
            add_to_buffer(current);
            float average_current = calculate_average();
            control_led(average_current);
            printf("Raw: %d, Current: %.2f A, Average: %.2f A\n", raw_value, current, average_current);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Error reading sensor data (consecutive: %d)\n", consecutive_errors);
            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "Max consecutive errors reached. Aborting.\n");
                break;
            }
        }

        gpioDelay(1000000 / SAMPLE_RATE_HZ);
    }

    cleanup();
    printf("Current monitoring stopped.\n");
    return EXIT_SUCCESS;
}

