#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* TCS34725 I2C address (ADDR pin tied to GND) */
#define TCS34725_ADDRESS 0x29

/* TCS34725 register addresses */
#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_ID      0x12
#define TCS34725_CDATA   0x14
#define TCS34725_RDATA   0x16
#define TCS34725_GDATA   0x18
#define TCS34725_BDATA   0x1A

/* Expected ID value for TCS34725 (0x44 = 0100 0100 = TCS34725, TCS34727) */
#define TCS34725_ID_VALUE 0x44

/* Enable register bits */
#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02

/* Integration time: 2.4 ms (0xFF) */
#define TCS34725_ATIME_2_4MS 0xFF

/* Global resources for signal handler cleanup */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint8_t reg, uint16_t *value)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    /* TCS34725 returns data in little-endian byte order */
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* TCS34725 driver (minimal)                                           */
/* ------------------------------------------------------------------ */

static int tcs34725_init(int fd)
{
    uint8_t id = 0;

    /* Power on */
    if (i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) < 0)
        return -1;
    usleep(3000); /* power-on delay >= 2.4 ms */

    /* Enable RGBC ADC */
    if (i2c_write_byte(fd, TCS34725_ENABLE,
                       TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0)
        return -1;

    /* Set integration time to 2.4 ms */
    if (i2c_write_byte(fd, TCS34725_ATIME, TCS34725_ATIME_2_4MS) < 0)
        return -1;

    /* Verify device ID */
    if (i2c_read_byte(fd, TCS34725_ID, &id) < 0)
        return -1;

    if (id != TCS34725_ID_VALUE) {
        fprintf(stderr, "TCS34725 not detected (ID=0x%02X, expected 0x%02X)\n",
                id, TCS34725_ID_VALUE);
        return -1;
    }

    return 0;
}

static int tcs34725_read_rgbc(int fd, uint16_t *r, uint16_t *g,
                              uint16_t *b, uint16_t *c)
{
    if (i2c_read_word(fd, TCS34725_CDATA, c) < 0) return -1;
    if (i2c_read_word(fd, TCS34725_RDATA, r) < 0) return -1;
    if (i2c_read_word(fd, TCS34725_GDATA, g) < 0) return -1;
    if (i2c_read_word(fd, TCS34725_BDATA, b) < 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */

static int log_open(const char *filename)
{
    /* Check if file exists / is non-empty to decide on header */
    int need_header = 1;
    FILE *check = fopen(filename, "r");
    if (check) {
        fseek(check, 0, SEEK_END);
        if (ftell(check) > 0)
            need_header = 0;
        fclose(check);
    }

    g_log_file = fopen(filename, "a");
    if (!g_log_file) {
        fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }
    if (need_header)
        fprintf(g_log_file, "timestamp,clear,red,green,blue\n");
    return 0;
}

static void log_data(uint16_t c, uint16_t r, uint16_t g, uint16_t b)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (!g_log_file) return;

    localtime_r(&now, &tm_info);
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);
    fprintf(g_log_file, "%s,%u,%u,%u,%u\n", ts, c, r, g, b);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    const char *i2c_dev = "/dev/i2c-1";
    const char *log_file = "color_log.csv";
    int consecutive_errors = 0;

    /* Open I2C bus */
    g_i2c_fd = open(i2c_dev, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", i2c_dev, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                TCS34725_ADDRESS, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (tcs34725_init(g_i2c_fd) < 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Open log file */
    if (log_open(log_file) < 0) {
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("TCS34725 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t r, g, b, c;

        if (tcs34725_read_rgbc(g_i2c_fd, &r, &g, &b, &c) == 0) {
            log_data(c, r, g, b);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            if (consecutive_errors >= 3) {
                fprintf(stderr, "Too many consecutive I2C errors, exiting.\n");
                break;
            }
        }

        /* Sleep 1 second using nanosleep so signals are caught promptly */
        struct timespec ts = { .tv_sec = 1, .tv_nsec = 0 };
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR && g_running) {
            /* interrupted by signal, loop to re-check g_running */
        }
    }

    /* Cleanup */
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
    }
    if (g_i2c_fd >= 0) {
        /* Power down sensor */
        i2c_write_byte(g_i2c_fd, TCS34725_ENABLE, 0x00);
        close(g_i2c_fd);
    }

    printf("Program finished.\n");
    return EXIT_SUCCESS;
}

