/*
 * Raspberry Pi 4 Model B - MLX91211 Current Sensor Monitor
 *
 * Hardware:
 *   - MCP3008 ADC on SPI0 (CE0=GPIO8, SCLK=GPIO11, MOSI=GPIO10, MISO=GPIO9)
 *   - MLX91211 analog output -> MCP3008 CH0
 *   - Motor shutdown control -> GPIO17 (BCM)
 *
 * Behavior:
 *   Samples current once per second, logs to current_log.csv.
 *   If current exceeds 10.0 A, disables motor for 1 s, then re-enables.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        0

#define MCP3008_CHANNEL 0
#define ADC_MAX_VALUE   1023.0f

#define MOTOR_SHUTDOWN_PIN 17
#define CURRENT_THRESHOLD  10.0f
#define LOG_FILE           "current_log.csv"
#define SAMPLE_INTERVAL_S  1
#define OVERCURRENT_HOLD_S 1
#define MAX_SPI_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_log_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

/*
 * MCP3008 single-ended read.
 * Protocol (3 bytes):
 *   tx[0] = 0x01  (start bit)
 *   tx[1] = (0x08 | channel) << 4  (single-ended + channel)
 *   tx[2] = 0x00  (don't care)
 * Result: 10-bit value assembled from rx[1] (low 2 bits) and rx[2] (8 bits).
 */
static int mcp3008_read(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; attempt++) {
        if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 0) {
            int value = ((rx[1] & 0x03) << 8) | rx[2];
            return value;
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %s\n",
                attempt + 1, MAX_SPI_RETRIES, strerror(errno));
        if (attempt < MAX_SPI_RETRIES - 1)
            usleep(10000);
    }

    return -1;
}

static float adc_to_current(int adc_value)
{
    /*
     * MLX91211 is a ratiometric Hall-effect sensor.
     * Current (I) is proportional to the ADC voltage (V).
     * V = (adc_value / ADC_MAX_VALUE) * Vref
     * I = (V / R_sense) * gain
     *
     * Placeholder conversion: 100 mV/V sensitivity, 1000 Ohm sense resistor.
     * Adjust R_SENSE and GAIN per your sensor/calibration.
     */
    const float VREF = 3.3f;
    const float R_SENSE = 1000.0f;
    const float GAIN = 100.0f;

    float voltage = (adc_value / ADC_MAX_VALUE) * VREF;
    float current = (voltage / R_SENSE) * GAIN;
    return current;
}

static int log_open(const char *path)
{
    int fd = open(path, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (fd < 0) {
        perror("open(" LOG_FILE ")");
        return -1;
    }

    /* Write header if file is empty */
    off_t pos = lseek(fd, 0, SEEK_END);
    if (pos < 0) {
        perror("lseek");
        close(fd);
        return -1;
    }
    if (pos == 0) {
        const char *hdr = "timestamp,current_amperes\n";
        ssize_t wr = write(fd, hdr, strlen(hdr));
        if (wr < 0 || (size_t)wr != strlen(hdr)) {
            perror("write header");
            close(fd);
            return -1;
        }
    }
    return fd;
}

static int log_current(int log_fd, float current)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        perror("localtime_r");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    char line[128];
    int len = snprintf(line, sizeof(line), "%s,%.3f\n", ts, current);
    if (len < 0 || len >= (int)sizeof(line)) {
        fprintf(stderr, "snprintf failed\n");
        return -1;
    }

    ssize_t wr = write(log_fd, line, (size_t)len);
    if (wr < 0) {
        perror("write(log)");
        return -1;
    }
    if (wr != len) {
        fprintf(stderr, "Short write to log: %zd/%d\n", wr, len);
        return -1;
    }

    if (fsync(log_fd) < 0) {
        perror("fsync");
        return -1;
    }
    return 0;
}

static void motor_control(int enable)
{
    if (gpioWrite(MOTOR_SHUTDOWN_PIN, enable ? 1 : 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed\n", MOTOR_SHUTDOWN_PIN, enable);
    }
}

static void cleanup(void)
{
    if (g_log_fd >= 0) {
        close(g_log_fd);
        g_log_fd = -1;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    /* Ensure motor is disabled on exit */
    gpioWrite(MOTOR_SHUTDOWN_PIN, 0);
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", MOTOR_SHUTDOWN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    motor_control(0); /* Start with motor disabled */

    if (spi_init() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fd = log_open(LOG_FILE);
    if (g_log_fd < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc = mcp3008_read(MCP3008_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed; retrying next cycle\n");
            sleep(SAMPLE_INTERVAL_S);
            continue;
        }

        float current = adc_to_current(adc);

        if (log_current(g_log_fd, current) < 0) {
            fprintf(stderr, "Logging failed; continuing\n");
        }

        printf("Current: %.3f A\n", current);

        if (current > CURRENT_THRESHOLD) {
            printf("OVERCURRENT DETECTED! Current: %.3f A > %.1f A\n",
                   current, CURRENT_THRESHOLD);
            motor_control(0); /* Disable motor */
            sleep(OVERCURRENT_HOLD_S);
            motor_control(1); /* Re-enable motor */
            printf("Motor re-enabled.\n");
        }

        sleep(SAMPLE_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

