/*
 * Raspberry Pi 4 Model B – MLX90834 pressure sensor via ADS1115 ADC
 *
 * Wiring:
 *   MLX90834 SENT line  -> ADS1115 AIN0 (single-ended)
 *   MLX90834 NTC line   -> ADS1115 AIN1 (single-ended)
 *   ADS1115 SDA         -> GPIO2 (I2C bus 1)
 *   ADS1115 SCL         -> GPIO3 (I2C bus 1)
 *   ADS1115 ADDR        -> GND  (I2C address 0x48)
 *   Warning LED + 330 Ω -> GPIO17 -> GND
 *
 * Build:  gcc -O2 -Wall -o mlx90834 mlx90834.c -lpigpio -lrt -lm
 * Run:    sudo ./mlx90834
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS            1
#define ADS1115_ADDR       0x48

#define ADS1115_REG_CONV   0x00
#define ADS1115_REG_CONFIG 0x01

/* Config word: single-shot, AIN0/GND, PGA ±4.096 V, 128 SPS, no comp */
#define ADS1115_CFG_BASE   0x8000  /* OS bit */
#define ADS1115_CFG_MUX0   0x4000  /* AIN0 single-ended */
#define ADS1115_CFG_MUX1   0x5000  /* AIN1 single-ended */
#define ADS1115_CFG_PGA    0x0200  /* ±4.096 V */
#define ADS1115_CFG_MODE   0x0100  /* single-shot */
#define ADS1115_CFG_DR     0x0080  /* 128 SPS */
#define ADS1115_CFG_CQUE   0x0003  /* disable comparator */

#define ADS1115_CFG_AIN0   (ADS1115_CFG_BASE | ADS1115_CFG_MUX0 | ADS1115_CFG_PGA | ADS1115_CFG_MODE | ADS1115_CFG_DR | ADS1115_CFG_CQUE)
#define ADS1115_CFG_AIN1   (ADS1115_CFG_BASE | ADS1115_CFG_MUX1 | ADS1115_CFG_PGA | ADS1115_CFG_MODE | ADS1115_CFG_DR | ADS1115_CFG_CQUE)

#define WARNING_LED_PIN    17
#define PRESSURE_THRESHOLD 105.0   /* kPa */
#define SAMPLE_PERIOD_US   1000000 /* 1 s */
#define MAX_RETRIES        3

/* ADS1115 ±4.096 V range => 16-bit signed => 1 LSB = 125 µV */
#define ADS1115_LSB_UV     125.0
#define ADS1115_VREF       4.096

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- ADS1115 helpers ---- */
static int ads1115_write_config(uint16_t config)
{
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (char)(config >> 8);
    buf[2] = (char)(config & 0xFF);
    return i2cWriteDevice(g_i2c_handle, buf, 3);
}

static int ads1115_read_conversion(int16_t *out)
{
    char reg = ADS1115_REG_CONV;
    char buf[2];

    if (i2cWriteDevice(g_i2c_handle, &reg, 1) < 0)
        return -1;
    if (i2cReadDevice(g_i2c_handle, buf, 2) != 2)
        return -1;

    *out = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    return 0;
}

/*
 * Read a single-ended channel from the ADS1115.
 * Returns 0 on success and stores voltage in *volts.
 * Returns -1 on persistent I2C failure.
 */
static int ads1115_read_channel(uint16_t mux_config, double *volts)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (ads1115_write_config(mux_config) < 0) {
            fprintf(stderr, "[ADS1115] config write failed (attempt %d/%d)\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(10000);
            continue;
        }

        /* Wait for conversion to complete (~8 ms at 128 SPS) */
        gpioDelay(10000);

        int16_t raw;
        if (ads1115_read_conversion(&raw) < 0) {
            fprintf(stderr, "[ADS1115] conversion read failed (attempt %d/%d)\n",
                    attempt + 1, MAX_RETRIES);
            gpioDelay(10000);
            continue;
        }

        *volts = (double)raw * ADS1115_LSB_UV / 1000000.0;
        return 0;
    }

    fprintf(stderr, "[ADS1115] channel read failed after %d attempts\n", MAX_RETRIES);
    return -1;
}

/* ---- Sensor conversion ---- */
static double voltage_to_pressure(double v)
{
    /*
     * Placeholder linear mapping.
     * Replace with the actual SENT decoding per the MLX90834
     * datasheet / application note.
     */
    return v * 100.0;
}

static double voltage_to_temperature(double v)
{
    /*
     * Placeholder NTC-to-Celsius conversion.
     * Replace with the actual NTC curve from your calibration.
     */
    double r_ntc = 10000.0 * v / (ADS1115_VREF - v);
    if (r_ntc <= 0.0)
        return -273.15;
    double ln_r = log(r_ntc);
    return 1.0 / (0.001129148 + (0.000234125 + (0.0000000876741 * ln_r) * ln_r) * ln_r);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(WARNING_LED_PIN, 0);
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus to ADS1115 */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure warning LED */
    if (gpioSetMode(WARNING_LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", WARNING_LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(WARNING_LED_PIN, 0);

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90834 pressure monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        double v_pressure = 0.0, v_temp = 0.0;

        if (ads1115_read_channel(ADS1115_CFG_AIN0, &v_pressure) < 0) {
            fprintf(stderr, "Pressure sensor read failed – skipping cycle\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (ads1115_read_channel(ADS1115_CFG_AIN1, &v_temp) < 0) {
            fprintf(stderr, "Temperature sensor read failed – skipping cycle\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double pressure = voltage_to_pressure(v_pressure);
        double temp     = voltage_to_temperature(v_temp);

        printf("Pressure: %.2f kPa | Temperature: %.2f °C\n", pressure, temp);

        if (pressure > PRESSURE_THRESHOLD) {
            gpioWrite(WARNING_LED_PIN, 1);
            printf("WARNING: Pressure exceeds threshold (%.2f kPa > %.2f kPa)\n",
                   pressure, PRESSURE_THRESHOLD);
        } else {
            gpioWrite(WARNING_LED_PIN, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

