                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure warning LED */
    if (gpioSetMode(WARNING_LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", WARNING_LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(WARNING_LED_PIN, 0);

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90834 pressure monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        double v_pressure = 0.0, v_temp = 0.0;

        if (ads1115_read_channel(ADS1115_CFG_AIN0, &v_pressure) < 0) {
            fprintf(stderr, "Pressure sensor read failed – skipping cycle\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (ads1115_read_channel(ADS1115_CFG_AIN1, &v_temp) < 0) {
            fprintf(stderr, "Temperature sensor read failed – skipping cycle\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double pressure = voltage_to_pressure(v_pressure);
        double temp     = voltage_to_temperature(v_temp);

        printf("Pressure: %.2f kPa | Temperature: %.2f °C\n", pressure, temp);

        if (pressure > PRESSURE_THRESHOLD) {
            gpioWrite(WARNING_LED_PIN, 1);
            printf("WARNING: Pressure exceeds threshold (%.2f kPa > %.2f kPa)\n",
                   pressure, PRESSURE_THRESHOLD);
        } else {
            gpioWrite(WARNING_LED_PIN, 0);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

