#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* SPI0 CE0 (BCM GPIO8)  */
#define SPI_SPEED        1000000    /* 1 MHz                 */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */
#define ADC_CHANNEL      0          /* MCP3008 single-ended channel 0 */
#define OVERCURRENT_THRESHOLD 10.0f /* Amperes               */
#define MOTOR_SHUTDOWN_PIN 27       /* BCM GPIO27            */
#define LOG_FILE         "current_log.txt"
#define SAMPLE_PERIOD_US 100000     /* 100 ms                */
#define ADC_MAX_VALUE    1023       /* 10-bit ADC            */
#define ADC_VREF         3.3f       /* MCP3008 VREF = 3.3 V  */
#define SENSOR_VSUPPLY   5.0f       /* Sensor supply V       */
#define SENSOR_SENSITIVITY 0.001f   /* V/A                   */

/* ------------------------------- Globals --------------------------------- */
static int      spi_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* --------------------------- Function prototypes ------------------------- */
static int  read_mcp3008(int channel, int *adc_value);
static float adc_to_current(int adc_value);
static int  log_current(float current);
static void shutdown_motor(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- read_mcp3008 ----------------------------- */
/*
 * Read a single-ended channel from the MCP3008.
 * Returns 0 on success (adc_value set), -1 on SPI transfer error.
 */
static int read_mcp3008(int channel, int *adc_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    if (adc_value == NULL) {
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n",
                ret, strerror(errno));
        return -1;
    }

    *adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

/* ----------------------------- adc_to_current ----------------------------- */
/*
 * Convert a 10-bit ADC reading to a current value (Amperes).
 *
 * MLX91209 analog output:
 *   Vout = VSUPPLY * (I / SENSITIVITY)
 *   I = (Vout / VSUPPLY) * SENSITIVITY
 *
 * MCP3008: 10-bit, VREF = 3.3 V.
 *   ADC code = (Vout / VREF) * 1023
 *   => I = ((ADC / 1023) * VREF / VSUPPLY) * SENSITIVITY
 */
static float adc_to_current(int adc_value)
{
    if (adc_value < 0 || adc_value > ADC_MAX_VALUE) {
        return 0.0f;
    }
    float voltage = ((float)adc_value / (float)ADC_MAX_VALUE) * ADC_VREF;
    return (voltage / SENSOR_VSUPPLY) * SENSOR_SENSITIVITY;
}

/* ------------------------------- log_current ------------------------------ */
/*
 * Append a timestamped current reading to the log file.
 * Returns 0 on success, -1 on error.
 */
static int log_current(float current)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s, Current: %.3f A\n", timestamp, current) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------ shutdown_motor ---------------------------- */
static void shutdown_motor(void)
{
    if (gpioWrite(MOTOR_SHUTDOWN_PIN, 1) != 0) {
        fprintf(stderr, "Warning: failed to set motor shutdown pin HIGH\n");
    }
    printf("Motor shutdown signal sent to GPIO%d\n", MOTOR_SHUTDOWN_PIN);
}

/* ------------------------------- cleanup ---------------------------------- */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Reset shutdown pin to a safe LOW state */
    gpioWrite(MOTOR_SHUTDOWN_PIN, 0);
    gpioTerminate();
}

/* ----------------------------- signal_handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* --------------------------------- main ----------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor shutdown pin as output, initially LOW */
    if (gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", MOTOR_SHUTDOWN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(MOTOR_SHUTDOWN_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise GPIO%d LOW\n", MOTOR_SHUTDOWN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open SPI bus */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz): %s\n",
                SPI_CHANNEL, SPI_SPEED, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Current monitoring started. Logging to '%s'. Press Ctrl+C to exit.\n",
           LOG_FILE);

    /* Main sampling loop */
    while (!terminate) {
        int adc_value = 0;

        if (read_mcp3008(ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "ADC read error; retrying in 100 ms...\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float current = adc_to_current(adc_value);

        if (log_current(current) != 0) {
            fprintf(stderr, "Logging error; continuing...\n");
        }

        if (current > OVERCURRENT_THRESHOLD) {
            printf("OVERCURRENT DETECTED: %.3f A > %.1f A\n",
                   current, OVERCURRENT_THRESHOLD);
            log_current(current);
            shutdown_motor();
            break;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Graceful cleanup */
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

