#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* Configuration */
#define SPI_CHANNEL      0          /* SPI0 CE0 (GPIO 8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */
#define ADC_CHANNEL      0          /* MCP3008 channel 0 */
#define ADC_RESOLUTION   1024       /* 10-bit */
#define ADC_VREF         3.3        /* Reference voltage */
#define ALARM_GPIO       4          /* BCM 4 */
#define THRESHOLD_VOLTAGE 2.5       /* Alarm threshold in volts */
#define LOG_FILE         "co_log.txt"
#define SAMPLE_INTERVAL  1          /* Seconds between samples */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Read MCP3008 single-ended channel; returns 0-1023 or -1 on error */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 SPI protocol: 3 bytes
     * Byte 0: 0x01 (start bit)
     * Byte 1: (0x08 | channel) << 4  -> single-ended + channel select
     * Byte 2: 0x00 (don't care, clocked out to read low byte)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits)
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* Convert ADC value to voltage */
static float adc_to_voltage(int adc_value) {
    return ((float)adc_value / (float)(ADC_RESOLUTION - 1)) * ADC_VREF;
}

/* Log data to file */
static void log_data(float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "localtime() failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,Voltage: %.2f V\n", timestamp, voltage) < 0) {
        fprintf(stderr, "Error writing to log file\n");
    }
    fflush(log_file);
}

/* Control alarm */
static void control_alarm(float voltage) {
    if (voltage > THRESHOLD_VOLTAGE) {
        gpioWrite(ALARM_GPIO, 1);
    } else {
        gpioWrite(ALARM_GPIO, 0);
    }
}

/* Cleanup resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure alarm is off before terminating pigpio */
    gpioWrite(ALARM_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure alarm GPIO */
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", ALARM_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(ALARM_GPIO, 0);

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error, retrying in %d second...\n", SAMPLE_INTERVAL);
            gpioWrite(ALARM_GPIO, 0);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        log_data(voltage);
        control_alarm(voltage);

        printf("Voltage: %.2f V\n", voltage);

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

