/*
 * methane_monitor.c — Raspberry Pi 4 Model B
 *
 * Continuously reads a Honeywell MICROpeL Model 41000-020 combustible gas
 * sensor (analog output) via an MCP3008 10-bit ADC on SPI bus 0, channel 0.
 *
 * Wiring:
 *   MCP3008 VDD  -> Pi 3.3 V (pin 1)
 *   MCP3008 VREF -> Pi 3.3 V (pin 1)
 *   MCP3008 AGND -> Pi GND  (pin 6)
 *   MCP3008 DGND -> Pi GND  (pin 6)
 *   MCP3008 CLK  -> GPIO11 (SCLK, BCM)
 *   MCP3008 DOUT -> GPIO9  (MISO, BCM)
 *   MCP3008 DIN  -> GPIO10 (MOSI, BCM)
 *   MCP3008 CS   -> GPIO8  (CE0,  BCM)
 *   MCP3008 CH0  -> Sensor analog output
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o methane_monitor methane_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./methane_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 on BCM GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CS */
#define ADC_CHANNEL    0          /* MCP3008 channel 0 */
#define ADC_MAX_VALUE  1023       /* 10-bit ADC */
#define VREF           3.3f       /* Reference voltage */
#define THRESHOLD_PPM  1000.0f    /* Alarm threshold */
#define LOG_FILE       "methane_log.txt"
#define SAMPLE_PERIOD  1          /* seconds between readings */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 read via pigpio SPI                                         */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 single-ended read sequence (3 bytes):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
}

/* ------------------------------------------------------------------ */
/* Sensor conversion                                                   */
/* ------------------------------------------------------------------ */
/*
 * Placeholder linear conversion.
 * Replace with the sensor's actual calibration curve (load resistor,
 * sensor resistance, etc.) from the Honeywell MICROpeL 41000-020
 * datasheet.
 */
static float adc_to_ppm(int adc_value)
{
    if (adc_value < 0) return 0.0f;
    if (adc_value > ADC_MAX_VALUE) adc_value = ADC_MAX_VALUE;

    float voltage = (float)adc_value * VREF / (float)ADC_MAX_VALUE;
    float resistance = 10.0f * voltage / (VREF - voltage);   /* 10 kΩ load */
    float sensor_resistance = 100.0f;                       /* example */
    float ratio = resistance / sensor_resistance;
    float ppm = 100.0f * ratio;                              /* example */
    return ppm;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_reading(float ppm)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f ppm\n", ts, ppm);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Alarm                                                               */
/* ------------------------------------------------------------------ */
static void check_threshold(float ppm)
{
    if (ppm > THRESHOLD_PPM) {
        fprintf(stderr, "ALARM: Methane concentration %.2f ppm exceeds threshold %.2f ppm\n",
                ppm, THRESHOLD_PPM);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signals ---------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error: sigaction failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Methane monitoring started. Press Ctrl+C to exit.\n");

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        int adc = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "Warning: ADC read failed, skipping sample\n");
        } else {
            float ppm = adc_to_ppm(adc);
            log_reading(ppm);
            check_threshold(ppm);
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

