code:
/*
 * Raspberry Pi 4 Model B – MLX90830 pressure sensor via ADS1115 ADC
 *
 * Wiring:
 *   MLX90830 VOUT -> ADS1115 AIN0
 *   MLX90830 VCC  -> 3.3 V (Pi pin 1)
 *   MLX90830 GND  -> GND  (Pi pin 9)
 *   ADS1115 SDA   -> GPIO2 (Pi pin 3, I2C bus 1)
 *   ADS1115 SCL   -> GPIO3 (Pi pin 5, I2C bus 1)
 *   ADS1115 VDD   -> 3.3 V
 *   ADS1115 GND   -> GND
 *   ADS1115 ADDR  -> GND  (I2C address 0x48)
 *
 * Build: gcc -O2 -Wall -o pressure_logger pressure_logger.c -lpigpio -lrt
 * Run:   sudo ./pressure_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS            1
#define ADS1115_ADDR       0x48

/* ADS1115 registers */
#define ADS1115_REG_CONV   0x00
#define ADS1115_REG_CONFIG 0x01

/* Config word: single-shot, AIN0 single-ended, PGA ±4.096 V, 128 SPS, no comp */
#define ADS1115_CFG_BASE   0x8000  /* OS bit */
#define ADS1115_CFG_MUX    0x4000  /* AIN0 single-ended */
#define ADS1115_CFG_PGA    0x0200  /* ±4.096 V */
#define ADS1115_CFG_MODE   0x0100  /* single-shot */
#define ADS1115_CFG_DR     0x0080  /* 128 SPS */
#define ADS1115_CFG        (ADS1115_CFG_BASE | ADS1115_CFG_MUX | ADS1115_CFG_PGA | ADS1115_CFG_MODE | ADS1115_CFG_DR)

#define LOG_FILE           "pressure_log.txt"
#define SAMPLE_PERIOD_US   1000000  /* 1 Hz */
#define CONV_WAIT_US       10000    /* 10 ms (128 SPS -> ~7.8 ms; 10 ms is safe) */
#define MAX_RETRIES        3

/* MLX90830 transfer function (example – calibrate for your sensor) */
#define VREF_MV            4096.0   /* ±4.096 V PGA */
#define P_MIN_KPA          0.0
#define P_MAX_KPA          100.0

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Write 16-bit config to ADS1115 ---- */
static int ads1115_write_config(int handle, uint16_t config)
{
    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (char)(config >> 8);
    buf[2] = (char)(config & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (config) failed\n");
        return -1;
    }
    return 0;
}

/* ---- Read 16-bit conversion result ---- */
static int ads1115_read_conversion(int handle, int16_t *out)
{
    char reg = ADS1115_REG_CONV;
    char buf[2];

    if (i2cWriteDevice(handle, &reg, 1) != 1) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (reg select) failed\n");
        return -1;
    }
    if (i2cReadDevice(handle, buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice (conversion) failed\n");
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | (uint8_t)buf[1]);
    return 0;
}

/* ---- Trigger conversion and read raw value ---- */
static int ads1115_read_raw(int handle, int16_t *raw)
{
    if (ads1115_write_config(handle, ADS1115_CFG) != 0)
        return -1;

    gpioDelay(CONV_WAIT_US);

    if (ads1115_read_conversion(handle, raw) != 0)
        return -1;

    return 0;
}

/* ---- Convert raw ADC count to pressure (kPa) ---- */
static double raw_to_pressure(int16_t raw)
{
    double voltage_mv = (double)raw * VREF_MV / 32768.0;
    double pressure = (voltage_mv / 1000.0) * 10.0;  /* Example scaling */
    if (pressure < P_MIN_KPA) pressure = P_MIN_KPA;
    if (pressure > P_MAX_KPA) pressure = P_MAX_KPA;
    return pressure;
}

/* ---- Log pressure with ISO-8601 timestamp ---- */
static int log_pressure(double pressure)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[ERROR] localtime_r");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[ERROR] strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, %.2f kPa\n", ts, pressure) < 0) {
        perror("[ERROR] fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("[ERROR] fclose");
        return -1;
    }
    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify ADS1115 is present by reading config register */
    char reg = ADS1115_REG_CONFIG;
    if (i2cWriteDevice(g_i2c_handle, &reg, 1) != 1) {
