/*
 * Raspberry Pi 3 Model B+ - HIH-4602-A Humidity Sensor Logger
 *
 * Hardware:
 *   - MCP3208 12-bit ADC on SPI0 (CE0 = GPIO8, SCLK = GPIO11, MOSI = GPIO10, MISO = GPIO9)
 *   - HIH-4602-A analog sensor connected to MCP3208 channel 0
 *
 * Build:
 *   gcc -O2 -Wall -o humidity_logger humidity_logger.c -lm
 *
 * Run:
 *   ./humidity_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_DELAY_US    0

#define HUMIDITY_CHANNEL 0
#define TEMPERATURE_CHANNEL 1

#define HUMIDITY_THRESHOLD 80.0f
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/*
 * MCP3208 single-ended read.
 * 3-byte transfer: [start bit] [SGL/DIFF + D2 D1 D0 + 0x00] [0x00]
 * Result: 12-bit value assembled from rx[1] (lower 4 bits) and rx[2] (8 bits).
 */
static int mcp3208_read(int fd, uint8_t channel) {
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = SPI_DELAY_US,
        .cs_change = 0,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    return ((rx[1] & 0x0F) << 8) | rx[2];
}

static float convert_humidity(int adc_value) {
    if (adc_value < 0) return -1.0f;
    return 100.0f - ((float)adc_value / 4095.0f) * 100.0f;
}

static float convert_temperature(int adc_value) {
    if (adc_value < 0) return -1000.0f;
    return (float)adc_value / 4095.0f * 165.0f - 40.0f;
}

static int log_data(float humidity, float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Failed to open log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%.2f\n", timestamp, humidity, temperature) < 0) {
        perror("Failed to write to log file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Failed to close log file");
        return -1;
    }

    return 0;
}

static int send_email_alert(float humidity) {
    char command[512];
    snprintf(command, sizeof(command),
             "echo \"Subject: Humidity Alert\\n\\nHumidity exceeded threshold: %.2f%%\" | ssmtp %s",
             humidity, EMAIL_RECIPIENT);

    int status = system(command);
    if (status == -1) {
        perror("system() failed for email");
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "ssmtp exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
    return 0;
}

static int initialize_spi(void) {
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI max speed");
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    if (initialize_spi() < 0) {
        return EXIT_FAILURE;
    }

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int humidity_adc = mcp3208_read(g_spi_fd, HUMIDITY_CHANNEL);
        int temperature_adc = mcp3208_read(g_spi_fd, TEMPERATURE_CHANNEL);

        if (humidity_adc < 0 || temperature_adc < 0) {
            fprintf(stderr, "Error reading ADC values. Retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        float humidity = convert_humidity(humidity_adc);
        float temperature = convert_temperature(temperature_adc);

        if (log_data(humidity, temperature) < 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        if (humidity > HUMIDITY_THRESHOLD) {
            printf("Humidity threshold exceeded! Sending email alert...\n");
            if (send_email_alert(humidity) < 0) {
                fprintf(stderr, "Error sending email alert.\n");
            }
        }

        printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);

        sleep(5);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

