            printf("Humidity threshold exceeded! Sending email alert...\n");
            if (send_email_alert(humidity) < 0) {
                fprintf(stderr, "Error sending email alert.\n");
            }
        }

        printf("Humidity: %.2f%%, Temperature: %.2f°C\n", humidity, temperature);

        sleep(5);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

