#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8

#define MCP3008_X_CHANNEL 0
#define MCP3008_Y_CHANNEL 1
#define MCP3008_Z_CHANNEL 2

#define IMPACT_THRESHOLD 800
#define SAMPLE_DELAY_US  10000

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int spi_read_channel(uint8_t channel, uint16_t *out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }
    if (out == NULL) {
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    *out = ((uint16_t)(rx[1] & 0x03) << 8) | rx[2];
    return 0;
}

static int log_data(uint16_t x, uint16_t y, uint16_t z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_fp, "%s,%u,%u,%u\n", timestamp, x, y, z) < 0) {
        perror("fprintf(log)");
        return -1;
    }
    fflush(g_log_fp);
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("impact_log.txt", "a");
    if (g_log_fp == NULL) {
        perror("fopen(impact_log.txt)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t x_val = 0, y_val = 0, z_val = 0;
        int rc;

        rc = spi_read_channel(MCP3008_X_CHANNEL, &x_val);
        if (rc < 0) { goto loop_error; }
        rc = spi_read_channel(MCP3008_Y_CHANNEL, &y_val);
        if (rc < 0) { goto loop_error; }
        rc = spi_read_channel(MCP3008_Z_CHANNEL, &z_val);
        if (rc < 0) { goto loop_error; }

        if (log_data(x_val, y_val, z_val) < 0) {
            goto loop_error;
        }

        if (x_val > IMPACT_THRESHOLD || y_val > IMPACT_THRESHOLD || z_val > IMPACT_THRESHOLD) {
            time_t rawtime;
            struct tm timeinfo;
            char timestamp[32];

            time(&rawtime);
            localtime_r(&rawtime, &timeinfo);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

            if (fprintf(g_log_fp, "%s,IMPACT DETECTED\n", timestamp) < 0) {
                perror("fprintf(impact)");
                goto loop_error;
            }
            fflush(g_log_fp);
            printf("Impact detected at %s\n", timestamp);
        }

        gpioDelay(SAMPLE_DELAY_US);
        continue;

    loop_error:
        fprintf(stderr, "Error during data acquisition. Exiting.\n");
        break;
    }

    cleanup();
    return EXIT_SUCCESS;
}

