    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(g_log_fp, "%s,%u,%u,%u\n", timestamp, x, y, z) < 0) {
        perror("fprintf(log)");
        return -1;
    }
    fflush(g_log_fp);
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("impact_log.txt", "a");
    if (g_log_fp == NULL) {
        perror("fopen(impact_log.txt)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Impact detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t x_val = 0, y_val = 0, z_val = 0;
        int rc;

        rc = spi_read_channel(MCP3008_X_CHANNEL, &x_val);
        if (rc < 0) { goto loop_error; }
        rc = spi_read_channel(MCP3008_Y_CHANNEL, &y_val);
        if (rc < 0) { goto loop_error; }
        rc = spi_read_channel(MCP3008_Z_CHANNEL, &z_val);
        if (rc < 0) { goto loop_error; }

        if (log_data(x_val, y_val, z_val) < 0) {
            goto loop_error;
        }

        if (x_val > IMPACT_THRESHOLD || y_val > IMPACT_THRESHOLD || z_val > IMPACT_THRESHOLD) {
            time_t rawtime;
            struct tm timeinfo;
            char timestamp[32];

            time(&rawtime);
            localtime_r(&rawtime, &timeinfo);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

            if (fprintf(g_log_fp, "%s,IMPACT DETECTED\n", timestamp) < 0) {
                perror("fprintf(impact)");
                goto loop_error;
            }
            fflush(g_log_fp);
            printf("Impact detected at %s\n", timestamp);
        }

        gpioDelay(SAMPLE_DELAY_US);
        continue;

    loop_error:
        fprintf(stderr, "Error during data acquisition. Exiting.\n");
        break;
    }

    cleanup();
    return EXIT_SUCCESS;
}

