/*
 * Raspberry Pi 4 Model B – Honeywell SpiroQuant A+ (ES1-005) via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> SpiroQuant A+ analog output
 *
 * Build:
 *   gcc -O2 -Wall -o flow_logger flow_logger.c -lpigpio -lrt
 * Run:
 *   sudo ./flow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 CH0 */
#define ADC_MAX        1023       /* 10-bit ADC */
#define VREF           3.3f       /* Reference voltage */
#define MIN_FLOW_RATE  0.0f       /* L/min */
#define MAX_FLOW_RATE  5.0f       /* L/min */
#define LOG_FILE       "flow_log.csv"
#define SAMPLE_PERIOD  1          /* seconds between samples */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 single-ended read                                           */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01                       (start bit)
     *   Byte 1: (0x08 | channel) << 4      (single-ended + channel)
     *   Byte 2: 0x00                       (clock out remaining bits)
     *
     * Response:
     *   rx[0] = don't care
     *   rx[1] = [null bit][b9 b8] in lower nibble
     *   rx[2] = b7..b0
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value to flow rate (L/min)                              */
/* ------------------------------------------------------------------ */
static float adc_to_flow_rate(int adc_value)
{
    /*
     * SpiroQuant A+ (ES1-005) flow curve:
     *   0 L/min  -> 0.5 V
     *   5 L/min  -> 2.5 V
     *
     * Linear interpolation:  flow = (adc / 1023) * (5.0 - 0.0) + 0.0
     */
    return ((float)adc_value / (float)ADC_MAX) * (MAX_FLOW_RATE - MIN_FLOW_RATE) + MIN_FLOW_RATE;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        snprintf(buf, len, "1970-01-01 00:00:00.000000");
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t used = strlen(buf);
    snprintf(buf + used, len - used, ".%06ld", ts.tv_nsec / 1000);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_flow_rate(float flow_rate)
{
    char ts[40];
    get_timestamp(ts, sizeof(ts));
    fprintf(g_log_file, "%s,%.4f\n", ts, flow_rate);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI open --------------------------------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file --------------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error: fopen(" LOG_FILE ")");
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signals ---------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Flow logger started. Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            /* SPI error already reported; wait and retry */
            sleep(SAMPLE_PERIOD);
            continue;
        }

        /* Sensor-absent / fault detection */
        if (adc_value == 0 || adc_value == ADC_MAX) {
            fprintf(stderr, "Warning: ADC saturated (value=%d) – sensor absent or wiring fault\n", adc_value);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        float flow_rate = adc_to_flow_rate(adc_value);

        if (flow_rate < MIN_FLOW_RATE || flow_rate > MAX_FLOW_RATE) {
            fprintf(stderr, "Warning: flow rate %.4f L/min out of range [%.1f, %.1f] L/min\n",
                    flow_rate, MIN_FLOW_RATE, MAX_FLOW_RATE);
        }

        log_flow_rate(flow_rate);
        sleep(SAMPLE_PERIOD);
    }

    /* --- Graceful shutdown ----------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

