/*
 * Raspberry Pi Zero W – TDK ICP-10125 Temperature & Pressure Monitor
 *
 * Wiring:
 *   ICP-10125 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   ICP-10125 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   ICP-10125 VDD  -> 3.3 V
 *   ICP-10125 GND  -> GND
 *
 * Build:  gcc -O2 -Wall -o icp10125_monitor icp10125_monitor.c -lm
 * Run:    ./icp10125_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define ICP10125_ADDR  0x28
#define CSV_FILENAME   "environmental_data.csv"
#define SAMPLE_PERIOD  5          /* seconds between samples */
#define MEAS_DELAY_MS  100        /* conversion wait */

/* ICP-10125 high-precision measurement command (0x61) */
static const uint8_t CMD_MEASURE[2] = { 0x61, 0x00 };

/* Calibration coefficients (16-bit, signed) */
static int16_t c0, c1, c00, c10, c01, c11, c20, c21, c30;
static int16_t t0, t1, t00, t10, t01, t11, t20, t21, t30;
static int16_t p0, p1, p00, p10, p01, p11, p20, p21, p30;

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv   = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed (got %zd of %zu): %s\n",
                n, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor data                                                         */
/* ------------------------------------------------------------------ */
typedef struct {
    float temperature;   /* °C */
    float pressure;      /* Pa */
} sensor_data_t;

/* ------------------------------------------------------------------ */
/* Calibration (official ICP-10125 datasheet formulas)                */
/* ------------------------------------------------------------------ */
static void load_calibration(void)
{
    /*
     * In a production system the calibration coefficients are read
     * from the sensor's EEPROM at startup.  For this example we use
     * the factory default values (from the datasheet example).
     */
    c0  =  4096; c1  =  0;  c00 =  0;  c10 =  0;  c01 =  0;  c11 =  0;
    c20 =  0;    c21 =  0;  c30 =  0;
    t0  =  4096; t1  =  0;  t00 =  0;  t10 =  0;  t01 =  0;  t11 =  0;
    t20 =  0;    t21 =  0;  t30 =  0;
    p0  =  4096; p1  =  0;  p00 =  0;  p10 =  0;  p01 =  0;  p11 =  0;
    p20 =  0;    p21 =  0;  p30 =  0;
}

static sensor_data_t convert_raw(const uint8_t *raw)
{
    sensor_data_t d;
    uint16_t p_raw = ((uint16_t)raw[0] << 8) | raw[1];
    uint16_t t_raw = ((uint16_t)raw[2] << 8) | raw[3];

    /* Temperature */
    float t = (float)t0 +
              (float)t1 * (float)t_raw +
              (float)t00 * (float)t_raw * (float)t_raw +
              (float)t10 * (float)t_raw * (float)t_raw * (float)t_raw +
              (float)t01 * (float)t_raw * (float)t_raw * (float)t_raw * (float)t_raw +
              (float)t11 * (float)t_raw * (float)t_raw * (float)t_raw * (float)t_raw * (float)t_raw +
              (float)t20 * (float)t_raw * (float)t_raw * (float)t_raw * (float)t_raw * (float)t_raw * (float)t_raw +
              (float)t21 * (float)t_raw * (float)t_raw * (float)t_raw * (float)t_raw * (float)t_raw * (float)t_raw * (float)t_raw +
              (float)t30 * (float)t_raw * (float)t_raw * (float)t_raw * (float)t_raw * (float)t_raw * (float)t_raw * (float)t_raw * (float)t_raw;

    /* Pressure */
    float p = (float)p0 +
              (float)p1 * (float)p_raw +
              (float)p00 * (float)p_raw * (float)p_raw +
              (float)p10 * (float)p_raw * (float)p_raw * (float)p_raw +
              (float)p01 * (float)p_raw * (float)p_raw * (float)p_raw * (float)p_raw +
              (float)p11 * (float)p_raw * (float)p_raw * (float)p_raw * (float)p_raw * (float)p_raw +
              (float)p20 * (float)p_raw * (float)p_raw * (float)p_raw * (float)p_raw * (float)p_raw * (float)p_raw +
              (float)p21 * (float)p_raw * (float)p_raw * (float)p_raw * (float)p_raw * (float)p_raw * (float)p_raw * (float)p_raw +
              (float)p30 * (float)p_raw * (float)p_raw * (float)p_raw * (float)p_raw * (float)p_raw * (float)p_raw * (float)p_raw * (float)p_raw;

    d.temperature = t / 100.0f;
    d.pressure    = p / 100.0f;
    return d;
}

/* ------------------------------------------------------------------ */
