    load_calibration();

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, ICP10125_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                ICP10125_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open CSV file (append mode) */
    g_csv = fopen(CSV_FILENAME, "a");
    if (!g_csv) {
        fprintf(stderr, "Cannot open %s: %s\n", CSV_FILENAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_csv) == 0) {
        fprintf(g_csv, "timestamp,temperature_c,pressure_pa\n");
        fflush(g_csv);
    }

    printf("ICP-10125 monitoring started.  Press Ctrl+C to stop.\n");

    while (g_running) {
        uint8_t raw[6];

        /* Trigger high-precision measurement */
        if (i2c_write_cmd(g_i2c_fd, CMD_MEASURE, sizeof(CMD_MEASURE)) != 0) {
            sleep(SAMPLE_PERIOD);
            continue;
        }

        /* Wait for conversion to complete */
        usleep(MEAS_DELAY_MS * 1000);

        /* Read 6 bytes: pressure(2) + temperature(2) + CRC(2) */
        if (i2c_read_bytes(g_i2c_fd, raw, sizeof(raw)) != 0) {
            sleep(SAMPLE_PERIOD);
            continue;
        }

        sensor_data_t d = convert_raw(raw);

        if (log_data(g_csv, d.temperature, d.pressure) != 0) {
            /* Non-fatal: keep running */
        }

        printf("Temperature: %.2f °C  |  Pressure: %.2f Pa\n",
               d.temperature, d.pressure);

        /* Sleep for the remainder of the sample period */
        sleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

