/*
 * Dual-channel MP23ABS1 MEMS microphone sampler via MCP3008 ADC.
 *
 * Hardware:
 *   - Raspberry Pi 3 Model B+
 *   - MCP3008 ADC on SPI0 (CE0 / GPIO8), SPI clock 1 MHz, mode 0
 *   - MP23ABS1 #1 on MCP3008 channel 0
 *   - MP23ABS1 #2 on MCP3008 channel 1
 *
 * Build:
 *   gcc -O2 -Wall -o mic_dual mic_dual.c -lm
 *
 * Run:
 *   ./mic_dual <gain1> <gain2>
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define NUM_CHANNELS    2
#define ADC_CHANNELS    {0, 1}
#define SAMPLE_DELAY_US 1000
#define MAX_SPI_RETRIES 3

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* SPI helpers                                                         */
/* ------------------------------------------------------------------ */

static int spi_open(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * MCP3008 single-ended read.
 * Protocol (3 bytes):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (single-ended + channel)
 *   tx[2] = 0x00                       (clock out low bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    for (int attempt = 0; attempt < MAX_SPI_RETRIES; ++attempt) {
        int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &tr);
        if (ret >= 0) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer attempt %d/%d failed: %s\n",
                attempt + 1, MAX_SPI_RETRIES, strerror(errno));
        usleep(1000);
    }

    return -1;
}

/* ------------------------------------------------------------------ */
/* Noise cancellation                                                  */
/* ------------------------------------------------------------------ */

static int16_t apply_gain(int adc_value, float gain)
{
    float scaled = (float)adc_value * gain;
    if (scaled > 32767.0f)  scaled = 32767.0f;
    if (scaled < -32768.0f) scaled = -32768.0f;
    return (int16_t)scaled;
}

static int16_t noise_cancellation(int16_t ch1, int16_t ch2)
{
    /*
     * Simple DC offset cancellation: subtract the DC bias from each
     * channel, then recombine.  A more sophisticated algorithm could
     * use a running average or a more elaborate FFT-based approach.
     */
    float avg1 = (float)ch1;
    float avg2 = (float)ch2;
    return (int16_t)(avg1 - avg2);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */

int main(int argc, char *argv[])
{
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <gain1> <gain2>\n", argv[0]);
        return EXIT_FAILURE;
    }

    float gain1 = atof(argv[1]);
    float gain2 = atof(argv[2]);

    if (gain1 <= 0.0f || gain2 <= 0.0f) {
        fprintf(stderr, "Gain values must be positive.\n");
        return EXIT_FAILURE;
    }

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT): %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    int spi_fd = spi_open(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    const uint8_t channels[NUM_CHANNELS] = ADC_CHANNELS;

    printf("Sampling MP23ABS1 on MCP3008 channels 0 and 1 (gain1=%.2f, gain2=%.2f)...\n",
           gain1, gain2);
    printf("Press Ctrl+C to stop.\n");

    while (g_running) {
        int adc[NUM_CHANNELS];
        bool read_ok = true;

        for (int i = 0; i < NUM_CHANNELS; ++i) {
            adc[i] = mcp3008_read(spi_fd, channels[i]);
            if (adc[i] < 0) {
                fprintf(stderr, "ADC read failed on channel %u\n", channels[i]);
                read_ok = false;
                break;
            }
        }

        if (!read_ok) {
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        int16_t ch1 = apply_gain(adc[0], gain1);
        int16_t ch2 = apply_gain(adc[1], gain2);
        int16_t out = noise_cancellation(ch1, ch2);

        printf("%d,%d,%d\n", ch1, ch2, out);
        fflush(stdout);

        usleep(SAMPLE_DELAY_US);
    }

    /* Clean shutdown */
    if (close(spi_fd) < 0) {
        fprintf(stderr, "close(spi_fd): %s\n", strerror(errno));
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

