#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define ADC_CHANNEL 0        /* MCP3008 channel 0 */
#define LOG_FILE    "moisture_log.txt"
#define SAMPLE_INTERVAL_S 60

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a single-ended sample from the MCP3008                         */
/* Returns 0–1023 on success, -1 on error.                             */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d): %s\n",
                ret, strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the log file                        */
/* ------------------------------------------------------------------ */
static int log_moisture(int adc_value)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&t, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s,%d\n", ts, adc_value) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio ----------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 ----------------------------- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers ----------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VH400 soil moisture logger started. Logging to %s every %d s.\n",
           LOG_FILE, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop ---------------------------------------- */
    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error — skipping sample\n");
        } else if (adc_value > 1023) {
            fprintf(stderr, "ADC value %d out of range — skipping sample\n",
                    adc_value);
        } else {
            if (log_moisture(adc_value) != 0) {
                fprintf(stderr, "Logging failed for ADC value %d\n",
                        adc_value);
            } else {
                printf("Logged: %d\n", adc_value);
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    /* --- Clean shutdown -------------------------------------------- */
    printf("\nShutting down...\n");
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
    }
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

