#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define MCP3008_CHANNEL 0
#define BUZZER_GPIO     18
#define LOG_FILE        "flame_log.txt"
#define TEMP_FILE       "ambient_temp.txt"
#define SAMPLE_DELAY_US 500000
#define MAX_RETRIES     3

static volatile sig_atomic_t running = 1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_ambient_temperature(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: cannot open %s: %s\n", TEMP_FILE, strerror(errno));
        return 250;
    }
    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Warning: invalid temperature in %s\n", TEMP_FILE);
        fclose(fp);
        return 250;
    }
    fclose(fp);
    return temp;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }
    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };
    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    int adc = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc < 0 || adc > 1023) {
        fprintf(stderr, "ADC value out of range: %d\n", adc);
        return -1;
    }
    return adc;
}

static void log_data(FILE *fp, int raw, float voltage, float comp, int temp, int flame) {
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d,%.2f,%.2f,%.2f,%d,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            raw, voltage, comp, (float)temp / 10.0f, flame);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        gpioWrite(BUZZER_GPIO, 0);
        gpioTerminate();
        return 1;
    }
    unsigned char mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Cannot set SPI mode: %s\n", strerror(errno));
        close(fd);
        gpioWrite(BUZZER_GPIO, 0);
        gpioTerminate();
        return 1;
    }
    unsigned char bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Cannot set SPI bits: %s\n", strerror(errno));
        close(fd);
        gpioWrite(BUZZER_GPIO, 0);
        gpioTerminate();
        return 1;
    }
    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Cannot set SPI speed: %s\n", strerror(errno));
        close(fd);
        gpioWrite(BUZZER_GPIO, 0);
        gpioTerminate();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        gpioWrite(BUZZER_GPIO, 0);
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw = -1;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            raw = read_mcp3008(fd, MCP3008_CHANNEL);
            if (raw >= 0) break;
            if (attempt < MAX_RETRIES - 1) {
                fprintf(stderr, "Retrying ADC read (%d/%d)...\n", attempt + 1, MAX_RETRIES);
                usleep(100000);
            }
        }
        if (raw < 0) {
            fprintf(stderr, "ADC read failed after %d attempts; skipping iteration.\n", MAX_RETRIES);
            gpioWrite(BUZZER_GPIO, 0);
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        float voltage = (float)raw * 3.3f / 1023.0f;
        int temp_raw = read_ambient_temperature();
        float temp_c = (float)temp_raw / 10.0f;
        float compensation = voltage * (25.0f / temp_c);
        int flame = (raw > 500) ? 1 : 0;

        gpioWrite(BUZZER_GPIO, flame ? 1 : 0);
        log_data(log_fp, raw, voltage, compensation, temp_raw, flame);

        printf("Raw: %d, V: %.2f, Comp: %.2f, Temp: %.1f C, Flame: %s\n",
               raw, voltage, compensation, temp_c, flame ? "YES" : "NO");

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(BUZZER_GPIO, 0);
    if (log_fp) fclose(log_fp);
    close(fd);
    gpioTerminate();
    return 0;
}

