    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d,%.2f,%.2f,%.2f,%d,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            raw, voltage, comp, (float)temp / 10.0f, flame);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", SPI_DEVICE, strerror(errno));
        gpioWrite(BUZZER_GPIO, 0);
        gpioTerminate();
        return 1;
    }
    unsigned char mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Cannot set SPI mode: %s\n", strerror(errno));
        close(fd);
        gpioWrite(BUZZER_GPIO, 0);
        gpioTerminate();
        return 1;
    }
    unsigned char bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Cannot set SPI bits: %s\n", strerror(errno));
        close(fd);
        gpioWrite(BUZZER_GPIO, 0);
        gpioTerminate();
        return 1;
    }
    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Cannot set SPI speed: %s\n", strerror(errno));
        close(fd);
        gpioWrite(BUZZER_GPIO, 0);
        gpioTerminate();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(fd);
        gpioWrite(BUZZER_GPIO, 0);
        gpioTerminate();
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int raw = -1;
        for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
            raw = read_mcp3008(fd, MCP3008_CHANNEL);
            if (raw >= 0) break;
            if (attempt < MAX_RETRIES - 1) {
                fprintf(stderr, "Retrying ADC read (%d/%d)...\n", attempt + 1, MAX_RETRIES);
                usleep(100000);
            }
        }
        if (raw < 0) {
            fprintf(stderr, "ADC read failed after %d attempts; skipping iteration.\n", MAX_RETRIES);
            gpioWrite(BUZZER_GPIO, 0);
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        float voltage = (float)raw * 3.3f / 1023.0f;
        int temp_raw = read_ambient_temperature();
        float temp_c = (float)temp_raw / 10.0f;
        float compensation = voltage * (25.0f / temp_c);
        int flame = (raw > 500) ? 1 : 0;

        gpioWrite(BUZZER_GPIO, flame ? 1 : 0);
        log_data(log_fp, raw, voltage, compensation, temp_raw, flame);

        printf("Raw: %d, V: %.2f, Comp: %.2f, Temp: %.1f C, Flame: %s\n",
               raw, voltage, compensation, temp_c, flame ? "YES" : "NO");

        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(BUZZER_GPIO, 0);
    if (log_fp) fclose(log_fp);
    close(fd);
    gpioTerminate();
    return 0;
}

