#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   1000000
#define SPI_FLAGS   0
#define LED_PIN     17
#define HIGH_THRESHOLD 75.0
#define LOW_THRESHOLD  70.0
#define SAMPLE_INTERVAL_US 5000000
#define SAMPLE_DELAY_US    100000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *json_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static double adc_to_percentage(int adc_value) {
    return (double)adc_value / 1023.0 * 100.0;
}

static void get_timestamp(char *buf, size_t len) {
    struct timespec ts;
    struct tm tm_info;
    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%03ldZ", ts.tv_nsec / 1000000);
}

static void log_water_level(double percentage) {
    char timestamp[32];
    get_timestamp(timestamp, sizeof(timestamp));

    if (json_file) {
        fprintf(json_file, "{\"timestamp\":\"%s\",\"water_level\":%.2f},\n", timestamp, percentage);
        fflush(json_file);
    }
}

static void control_led(double percentage) {
    if (percentage > HIGH_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else if (percentage < LOW_THRESHOLD) {
        gpioWrite(LED_PIN, 0);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin %d as output\n", LED_PIN);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    json_file = fopen("water_levels.json", "w");
    if (!json_file) {
        fprintf(stderr, "Error opening water_levels.json for writing\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    fprintf(json_file, "[\n");
    fflush(json_file);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value, skipping sample\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        double percentage = adc_to_percentage(adc_value);
        log_water_level(percentage);
        control_led(percentage);

        printf("Water Level: %.2f%%\n", percentage);

        for (int i = 0; i < 50 && running; i++) {
            gpioDelay(SAMPLE_DELAY_US);
        }
    }

    fprintf(stderr, "\nShutting down...\n");

    if (json_file) {
        fseek(json_file, -2, SEEK_END);
        fprintf(json_file, "\n]\n");
        fclose(json_file);
        json_file = NULL;
    }

    gpioWrite(LED_PIN, 0);
    spiClose(spi_handle);
    spi_handle = -1;
    gpioTerminate();

    return EXIT_SUCCESS;
}

