/*
 * Raspberry Pi Zero W - Honeywell AWM7300V Airflow Logger
 *
 * Hardware:
 *   - MCP3008 10-bit ADC on SPI0 (CE0 / physical pin 24)
 *   - SCLK  / physical pin 23
 *   - MOSI  / physical pin 19
 *   - MISO  / physical pin 21
 *   - AWM7300V analog output -> MCP3008 CH0
 *
 * Build:
 *   gcc -O2 -Wall -o airflow_logger airflow_logger.c -lpigpio -lrt
 * Run:
 *   sudo ./airflow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL      0          /* CE0 (physical pin 24) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* Mode 0, active-low CE */
#define ADC_CHANNEL      0          /* MCP3008 CH0 */
#define SAMPLE_PERIOD_US 100000     /* 100 ms */
#define LOG_FILE         "airflow_log.csv"

/*
 * AWM7300V transfer function (example parameters - calibrate for your sensor).
 * Raw ADC value (0-1023) -> Liters Per Minute.
 */
#define ADC_MAX          1023.0f
#define FLOW_MIN_LPM     0.0f
#define FLOW_MAX_LPM     100.0f

static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* MCP3008 read (single-ended mode)                                    */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed (ret=%d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC value to Liters Per Minute                             */
/* ------------------------------------------------------------------ */
static float adc_to_flow_lpm(int adc_value)
{
    if (adc_value < 0)   return FLOW_MIN_LPM;
    if (adc_value > 1023) return FLOW_MAX_LPM;

    return FLOW_MIN_LPM +
           ((float)adc_value / ADC_MAX) * (FLOW_MAX_LPM - FLOW_MIN_LPM);
}

/* ------------------------------------------------------------------ */
/* Timestamp helper (ISO 8601)                                        */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm timeinfo;

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &timeinfo);
}

/* ------------------------------------------------------------------ */
/* Log a reading to the CSV file                                       */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, float flow_lpm)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    if (fprintf(fp, "%s,%.2f\n", ts, flow_lpm) < 0) {
        fprintf(stderr, "Error: failed to write to log file\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: failed to flush log file\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI bus --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file (append mode) --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,flow_lpm\n");
        fflush(g_log_file);
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Airflow logger started. Logging to '%s'. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Warning: ADC read failed, skipping sample\n");
        } else {
            float flow_lpm = adc_to_flow_lpm(adc_value);
            if (log_data(g_log_file, flow_lpm) != 0) {
                fprintf(stderr, "Warning: logging failed\n");
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

