    /* --- Open SPI bus --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle=%d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file (append mode) --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,flow_lpm\n");
        fflush(g_log_file);
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Airflow logger started. Logging to '%s'. Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Warning: ADC read failed, skipping sample\n");
        } else {
            float flow_lpm = adc_to_flow_lpm(adc_value);
            if (log_data(g_log_file, flow_lpm) != 0) {
                fprintf(stderr, "Warning: logging failed\n");
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

