#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>

#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_ADC_CHANNEL 0
#define DEFAULT_MIN_CALIBRATION_VALUE 300
#define DEFAULT_MAX_CALIBRATION_VALUE 700
#define DEFAULT_MOISTURE_THRESHOLD 30
#define DEFAULT_LOGGING_INTERVAL 60
#define DEFAULT_EMAIL_RECIPIENT "recipient@example.com"
#define DEFAULT_MSMTP_CONFIG "/etc/msmtprc"
#define DEFAULT_LOG_FILE "plant_data.txt"
#define SPI_SPEED 500000
#define SPI_FLAGS 0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static float calculate_moisture_percentage(int adc_value, int min_calibration_value, int max_calibration_value) {
    if (adc_value < 0) return -1.0f;
    if (min_calibration_value >= max_calibration_value) return -1.0f;
    return 100.0f - ((float)(adc_value - min_calibration_value) / (float)(max_calibration_value - min_calibration_value) * 100.0f);
}

static int log_data(const char *filename, float moisture_percentage) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.2f\n", timestamp, moisture_percentage);
    fclose(fp);
    return 0;
}

static int send_email_alert(const char *recipient, const char *email_body, const char *msmtp_config) {
    char command[512];
    snprintf(command, sizeof(command), "msmtp -C %s -t %s", msmtp_config, recipient);

    FILE *fp = popen(command, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not execute msmtp: %s\n", strerror(errno));
        return -1;
    }

    if (fputs(email_body, fp) == EOF) {
        fprintf(stderr, "Error: Could not write to msmtp pipe\n");
        pclose(fp);
        return -1;
    }

    int status = pclose(fp);
    if (status == -1) {
        fprintf(stderr, "Error: pclose failed: %s\n", strerror(errno));
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        return 0;
    } else {
        fprintf(stderr, "Error: msmtp exited with status %d\n", WEXITSTATUS(status));
        return -1;
    }
}

int main(int argc, char *argv[]) {
    int spi_channel = DEFAULT_SPI_CHANNEL;
    int adc_channel = DEFAULT_ADC_CHANNEL;
    int min_calibration_value = DEFAULT_MIN_CALIBRATION_VALUE;
    int max_calibration_value = DEFAULT_MAX_CALIBRATION_VALUE;
    int moisture_threshold = DEFAULT_MOISTURE_THRESHOLD;
    int logging_interval = DEFAULT_LOGGING_INTERVAL;
    const char *email_recipient = DEFAULT_EMAIL_RECIPIENT;
    const char *msmtp_config = DEFAULT_MSMTP_CONFIG;
    const char *log_file = DEFAULT_LOG_FILE;

    int opt;
    while ((opt = getopt(argc, argv, "c:a:m:M:t:i:e:s:l:")) != -1) {
        switch (opt) {
            case 'c': spi_channel = atoi(optarg); break;
            case 'a': adc_channel = atoi(optarg); break;
            case 'm': min_calibration_value = atoi(optarg); break;
            case 'M': max_calibration_value = atoi(optarg); break;
            case 't': moisture_threshold = atoi(optarg); break;
            case 'i': logging_interval = atoi(optarg); break;
            case 'e': email_recipient = optarg; break;
            case 's': msmtp_config = optarg; break;
            case 'l': log_file = optarg; break;
            default:
                fprintf(stderr, "Usage: %s [-c spi_channel] [-a adc_channel] [-m min_calibration] [-M max_calibration] [-t moisture_threshold] [-i logging_interval] [-e email_recipient] [-s msmtp_config] [-l log_file]\n", argv[0]);
                return 1;
        }
    }

    if (min_calibration_value >= max_calibration_value) {
        fprintf(stderr, "Error: min_calibration_value must be less than max_calibration_value\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(spi_channel, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed for channel %d: %s\n", spi_channel, pigpio_error(spi_handle));
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Plant monitoring started. Logging to %s every %d seconds.\n", log_file, logging_interval);

    while (running) {
        int adc_value = read_mcp3008(adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
        } else {
            float moisture_percentage = calculate_moisture_percentage(adc_value, min_calibration_value, max_calibration_value);
            if (moisture_percentage < 0.0f) {
                fprintf(stderr, "Error: Invalid calibration values\n");
            } else {
                if (log_data(log_file, moisture_percentage) != 0) {
                    fprintf(stderr, "Error: Failed to log data\n");
                }

                if (moisture_percentage < moisture_threshold) {
                    time_t t = time(NULL);
                    struct tm *tm = localtime(&t);
                    char timestamp[64];
                    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

                    char email_body[256];
                    snprintf(email_body, sizeof(email_body),
                             "Subject: Plant Moisture Alert\n\n"
                             "Plant moisture is below threshold!\n"
                             "Timestamp: %s\n"
                             "Moisture: %.2f%%\n",
                             timestamp, moisture_percentage);

                    if (send_email_alert(email_recipient, email_body, msmtp_config) != 0) {
                        fprintf(stderr, "Error: Failed to send email alert\n");
                    }
                }
            }
        }

        for (int i = 0; i < logging_interval && running; i++) {
            sleep(1);
        }
    }

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("Plant monitoring stopped.\n");
    return 0;
}

