#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define MCP3008_CHANNEL 0
#define SAMPLE_INTERVAL 5

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(const char *device)
{
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

static int read_mcp3008(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   Byte 0: 0x01  (start bit)
     *   Byte 1: (0x08 | channel) << 4  (single-ended + channel select)
     *   Byte 2: 0x00  (don't care, clocked out to read low byte)
     *
     * Response:
     *   rx[0] = ignored
     *   rx[1] = [null bit][b9 b8] in lower nibble
     *   rx[2] = b7..b0
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float calculate_moisture(int adc_value)
{
    /*
     * DFRobot Soil Moisture Sensor v2.0:
     *   - Dry  soil: ~300 ADC
     *   - Wet  soil: ~700 ADC
     *   - Linear mapping: moisture = (adc - 300) / (700 - 300) * 100
     */
    const int dry_adc  = 300;
    const int wet_adc  = 700;
    const int range    = wet_adc - dry_adc;

    if (range == 0) {
        return 0.0f;
    }

    float moisture = ((float)(adc_value - dry_adc) / (float)range) * 100.0f;
    if (moisture < 0.0f) {
        moisture = 0.0f;
    }
    if (moisture > 100.0f) {
        moisture = 100.0f;
    }
    return moisture;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    int spi_fd = spi_init(SPI_DEVICE);
    if (spi_fd < 0) {
        return EXIT_FAILURE;
    }

    printf("Soil Moisture Sensor Data Acquisition\n");
    printf("SPI device: %s | Speed: %d Hz | Mode: %d | Channel: %d\n",
           SPI_DEVICE, SPI_SPEED_HZ, SPI_MODE, MCP3008_CHANNEL);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int adc_value = read_mcp3008(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value. Retrying in %d seconds.\n",
                    SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float moisture = calculate_moisture(adc_value);

        printf("ADC Value: %4d | Moisture: %5.2f%%\n", adc_value, moisture);
        fflush(stdout);

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down and releasing SPI resources...\n");
    if (close(spi_fd) < 0) {
        fprintf(stderr, "Error closing SPI device: %s\n", strerror(errno));
    }

    return EXIT_SUCCESS;
}

