/*
 * MLX90823 pressure sensor reader via MCP3008 ADC on Raspberry Pi 4.
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SCLK, BCM 11)
 *   MCP3008 DOUT -> GPIO9  (MISO,  BCM 9)
 *   MCP3008 DIN  -> GPIO10 (MOSI,  BCM 10)
 *   MCP3008 CS   -> GPIO8  (CE0,   BCM 8)
 *   MCP3008 CH0  -> MLX90823 analog output
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mlx90823 mlx90823.c -lpigpio -lrt
 * Run:
 *   sudo ./mlx90823
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 CH0 */
#define SAMPLE_PERIOD  1          /* seconds between readings */
#define ADC_MAX        1023       /* 10-bit ADC full-scale */
#define VREF           3.3f       /* MCP3008 reference voltage */
#define ZERO_VOLT_THRESHOLD 0.05f /* V below 0.05 V => sensor absent */
#define VCC_THRESHOLD  3.25f      /* V above 3.25 V => sensor absent */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* MCP3008 read                                                        */
/* ------------------------------------------------------------------ */
/*
 * MCP3008 single-ended read sequence (3 bytes):
 *   TX: 0x01, (0x80 | (channel << 4)), 0x00
 *   RX: [don't care], [don't care], [low 2 bits in upper nibble + 8 LSBs]
 */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx[3] = { 0x01, (char)(0x80 | (channel << 4)), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Sensor validation                                                   */
/* ------------------------------------------------------------------ */
static bool sensor_absent(int adc_value)
{
    float voltage = (float)adc_value * VREF / (float)ADC_MAX;
    return (voltage < ZERO_VOLT_THRESHOLD) || (voltage > VCC_THRESHOLD);
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "1970-01-01T00:00:00");
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    install_signal_handlers();

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MLX90823 pressure sensor reader started.\n");
    printf("SPI channel %d, ADC channel %d, %d Hz.\n",
           SPI_CHANNEL, ADC_CHANNEL, SPI_SPEED);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int adc_value = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: ADC read failed; retrying next cycle.\n");
            sleep(SAMPLE_PERIOD);
            continue;
        }

        if (adc_value > ADC_MAX) {
            fprintf(stderr, "Error: ADC value %d out of range (0-%d).\n",
                    adc_value, ADC_MAX);
            sleep(SAMPLE_PERIOD);
            continue;
        }

        if (sensor_absent(adc_value)) {
            fprintf(stderr, "Warning: sensor absent or disconnected "
                            "(ADC=%d, V=%.3f V).\n",
                    adc_value, (float)adc_value * VREF / (float)ADC_MAX);
        } else {
            float voltage = (float)adc_value * VREF / (float)ADC_MAX;
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            printf("%s  ADC=%4d  V=%.3f V\n", ts, adc_value, voltage);
        }

        sleep(SAMPLE_PERIOD);
    }

    /* Clean shutdown */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioTerminate();

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

