/*
 * Raspberry Pi Zero W – Capacitive Soil Moisture Sensor (SEN0193)
 * ADC: MCP3008 on SPI0 (CE0), 1 MHz, mode 0
 * Sensor analog out -> MCP3008 CH0
 *
 * Build: gcc -O2 -Wall -o soil_moisture soil_moisture.c
 * Run:   sudo ./soil_moisture
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0

#define MCP3008_CHANNEL 0
#define SAMPLE_PERIOD_S 5

#define ADC_MIN 0
#define ADC_MAX 1023
#define ADC_STUCK_THRESHOLD 10  /* consecutive stuck readings before warning */

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * MCP3008 single-ended read (3-byte transfer):
 *   tx[0] = 0x01                       (start bit)
 *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0 = channel)
 *   tx[2] = 0x00                       (clock out remaining bits)
 * Result: 10-bit value in ((rx[1] & 0x03) << 8) | rx[2]
 */
static int mcp3008_read(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = sizeof(tx);
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 1) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static void log_reading(int adc_value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
    } else {
        snprintf(timestamp, sizeof(timestamp), "UNKNOWN");
    }

    printf("[%s] ADC Value: %4d  (0x%03X)  %s\n",
           timestamp, adc_value, adc_value,
           (adc_value == ADC_MIN || adc_value == ADC_MAX)
               ? "[WARNING: possible sensor-absent or wiring fault]"
               : "");
    fflush(stdout);
}

int main(void)
{
    int spi_fd = -1;
    int consecutive_stuck = 0;
    int last_adc = -1;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    /* Open SPI device */
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return EXIT_FAILURE;
    }

    /* Configure SPI mode */
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("SPI_IOC_WR_MODE");
        goto cleanup;
    }

    /* Configure bits per word */
    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("SPI_IOC_WR_BITS_PER_WORD");
        goto cleanup;
    }

    /* Configure max speed */
    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("SPI_IOC_WR_MAX_SPEED_HZ");
        goto cleanup;
    }

    printf("Soil Moisture Sensor Monitoring (MCP3008 CH0, SPI0 CE0)\n");
    printf("Sampling every %d seconds. Press Ctrl+C to exit.\n", SAMPLE_PERIOD_S);
    fflush(stdout);

    while (g_running) {
        int adc_value = mcp3008_read(spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "SPI read error – continuing\n");
            sleep(SAMPLE_PERIOD_S);
            continue;
        }

        /* Detect stuck-at-end-of-range readings (sensor absent / wiring fault) */
        if (adc_value == last_adc) {
            consecutive_stuck++;
            if (consecutive_stuck >= ADC_STUCK_THRESHOLD) {
                fprintf(stderr,
                        "[WARNING] ADC value %d repeated %d times – "
                        "possible sensor-absent or wiring fault\n",
                        adc_value, consecutive_stuck);
            }
        } else {
            consecutive_stuck = 0;
        }
        last_adc = adc_value;

        log_reading(adc_value);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_PERIOD_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nExiting gracefully...\n");

cleanup:
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    return EXIT_SUCCESS;
}

