#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL        0          /* CE0 on bus 0 */
#define SPI_SPEED          1000000    /* 1 MHz */
#define SPI_FLAGS          0          /* Mode 0, active-low CE */
#define MCP3008_CHANNEL    0          /* VH400 analog out wired here */
#define PUMP_GPIO          17         /* BCM 17 */
#define MOISTURE_LOW       300        /* below this -> pump ON  */
#define MOISTURE_HIGH      600        /* above this -> pump OFF */
#define SAMPLE_INTERVAL_S  5          /* seconds */
#define BUFFER_SIZE        20
#define LOG_MSG_LEN        128

/* ------------------------------- Globals --------------------------------- */
static int spi_handle = -1;
static volatile sig_atomic_t running = 1;

/* --------------------------- Circular Buffer ----------------------------- */
typedef struct {
    char message[LOG_MSG_LEN];
    time_t timestamp;
} LogEntry;

static LogEntry log_buffer[BUFFER_SIZE];
static int buffer_head = 0;
static int buffer_count = 0;

/* --------------------------- Function Prototypes ------------------------- */
static int  read_mcp3008(int channel);
static void control_pump(int moisture_level);
static void log_message(const char *msg);
static void print_buffer(void);
static void cleanup(void);
static void signal_handler(int sig);

/* ------------------------------- SPI Read -------------------------------- */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ----------------------------- Pump Control ------------------------------- */
static void control_pump(int moisture_level)
{
    static bool pump_on = false;

    if (moisture_level < MOISTURE_LOW && !pump_on) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            pump_on = true;
            log_message("Pump turned ON");
        } else {
            log_message("ERROR: Failed to turn pump ON");
        }
    } else if (moisture_level > MOISTURE_HIGH && pump_on) {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            pump_on = false;
            log_message("Pump turned OFF");
        } else {
            log_message("ERROR: Failed to turn pump OFF");
        }
    }
}

/* ------------------------------- Logging --------------------------------- */
static void log_message(const char *msg)
{
    time(&log_buffer[buffer_head].timestamp);
    snprintf(log_buffer[buffer_head].message, LOG_MSG_LEN, "%s", msg);

    buffer_head = (buffer_head + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;

    print_buffer();
}

static void print_buffer(void)
{
    printf("\n--- Log Buffer ---\n");
    int start = (buffer_count == BUFFER_SIZE) ? buffer_head : 0;
    for (int i = 0; i < buffer_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char time_str[32];
        struct tm *tm_info = localtime(&log_buffer[idx].timestamp);
        if (tm_info) {
            strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm_info);
        } else {
            snprintf(time_str, sizeof(time_str), "<unknown>");
        }
        printf("[%s] %s\n", time_str, log_buffer[idx].message);
    }
    printf("------------------\n");
    fflush(stdout);
}

/* ----------------------------- Cleanup / Signals -------------------------- */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------- Timer CB -------------------------------- */
static void sample_moisture(void *userdata)
{
    (void)userdata;
    int moisture = read_mcp3008(MCP3008_CHANNEL);
    if (moisture < 0) {
        log_message("ERROR: Failed to read moisture level");
    } else {
        char msg[LOG_MSG_LEN];
        snprintf(msg, sizeof(msg), "Moisture level: %d", moisture);
        log_message(msg);
        control_pump(moisture);
    }
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", PUMP_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetTimerFuncEx(0, SAMPLE_INTERVAL_S * 1000, sample_moisture, NULL) != 0) {
        fprintf(stderr, "Failed to set timer function\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        sleep(1);
    }

    gpioSetTimerFuncEx(0, 0, NULL, NULL); /* stop timer */
    cleanup();
    return EXIT_SUCCESS;
}

