int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* spiOpen flags: 0 = mode 0, active-low CE, 8 bits/word, MSB first */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("fopen");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Write header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,Channel,Voltage\n");
        fflush(log_file);
    }

    int channels[NUM_CHANNELS] = {0, 1, 2};
    char timestamp[32];

    while (running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int adc = read_mcp3008(channels[i]);
            if (adc < 0) {
                fprintf(stderr, "Error reading channel %d\n", channels[i]);
                continue;
            }
            float voltage = adc_to_voltage(adc);
            get_timestamp(timestamp, sizeof(timestamp));
            if (log_data(timestamp, channels[i], voltage) != 0) {
                fprintf(stderr, "Error logging data for channel %d\n", channels[i]);
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

