#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define BUZZER_GPIO 24
#define THRESHOLD 500
#define SAMPLE_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int set_buzzer(int state) {
    if (gpioWrite(BUZZER_GPIO, state) != 0) {
        fprintf(stderr, "Failed to write GPIO %d\n", BUZZER_GPIO);
        return -1;
    }
    return 0;
}

