    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure buzzer GPIO as output and ensure it starts OFF */
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", BUZZER_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (set_buzzer(0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to open SPI channel %d\n", SPI_CHANNEL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("MQ-2 gas sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value\n");
            break;
