#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADS1115_ADDR   0x48
#define RELAY_GPIO     17
#define REED_GPIO      27
#define LOG_FILE       "/var/log/door_events.log"
#define SAMPLE_MS      200
#define CALIB_SAMPLES  10
#define CALIB_DELAY_MS 50
#define RELAY_PULSE_MS 3000
#define ADC_MAX        32767.0f
#define ADC_VREF       4.096f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val) {
    uint8_t buf[3] = { reg, (uint8_t)(val >> 8), (uint8_t)(val & 0xFF) };
    struct i2c_msg msg = { .addr = ADS1115_ADDR, .flags = 0, .len = 3, .buf = buf };
    struct i2c_rdwr_ioctl_data data = { .msgs = &msg, .nmsgs = 1 };
    if (ioctl(fd, I2C_RDWR, &data) < 0) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out) {
    uint8_t wbuf[1] = { reg };
    uint8_t rbuf[2] = {0};
    struct i2c_msg msgs[2] = {
        { .addr = ADS1115_ADDR, .flags = 0,           .len = 1, .buf = wbuf },
        { .addr = ADS1115_ADDR, .flags = I2C_M_RD,    .len = 2, .buf = rbuf }
    };
    struct i2c_rdwr_ioctl_data data = { .msgs = msgs, .nmsgs = 2 };
    if (ioctl(fd, I2C_RDWR, &data) < 0) return -1;
    *out = ((uint16_t)rbuf[0] << 8) | rbuf[1];
    return 0;
}

static int ads1115_read(int fd, float *voltage) {
    uint16_t cfg = 0xC083; /* A0 single-ended, 4.096V, single-shot, 128 SPS */
    if (i2c_write_reg16(fd, 0x01, cfg) < 0) return -1;
    usleep(10000);
    uint16_t raw;
    if (i2c_read_reg16(fd, 0x00, &raw) < 0) return -1;
    *voltage = (float)raw * ADC_VREF / ADC_MAX;
    return 0;
}

static float calibrate(int fd) {
    float sum = 0.0f;
    for (int i = 0; i < CALIB_SAMPLES; i++) {
        float v;
        if (ads1115_read(fd, &v) < 0) {
            fprintf(stderr, "Calibration read %d failed: %s\n", i, strerror(errno));
            return -1.0f;
        }
        sum += v;
        usleep(CALIB_DELAY_MS * 1000);
    }
    return sum / CALIB_SAMPLES;
}

static void log_event(const char *msg) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return;
    }
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s.%03ld: %s\n", tbuf, ts.tv_nsec / 1000000, msg);
    fclose(fp);
}

static void pulse_relay(int gpio, int duration_ms) {
    if (gpioWrite(gpio, 1) < 0) {
        fprintf(stderr, "gpioWrite(%d, 1) failed\n", gpio);
        return;
    }
    usleep(duration_ms * 1000);
    if (gpioWrite(gpio, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", gpio);
    }
}

int main(void) {
    struct sigaction sa = { .sa_handler = sig_handler };
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(RELAY) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(REED_GPIO, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(REED) failed\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(REED_GPIO, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(REED) failed\n");
        gpioTerminate();
        return 1;
    }
    gpioWrite(RELAY_GPIO, 0);

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s): %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X: %s\n", ADS1115_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }

    float baseline = calibrate(g_i2c_fd);
    if (baseline < 0.0f) {
        fprintf(stderr, "Calibration failed; aborting.\n");
        close(g_i2c_fd);
        gpioTerminate();
        return 1;
    }
    printf("Baseline: %.3f V\n", baseline);

    while (g_running) {
        float v;
        if (ads1115_read(g_i2c_fd, &v) < 0) {
            fprintf(stderr, "ADC read failed: %s\n", strerror(errno));
            usleep(SAMPLE_MS * 1000);
            continue;
        }
        if (v < baseline) {
            printf("Distance below threshold (%.3f < %.3f)\n", v, baseline);
            pulse_relay(RELAY_GPIO, RELAY_PULSE_MS);
            int reed = gpioRead(REED_GPIO);
            if (reed < 0) {
                fprintf(stderr, "gpioRead(REED) failed\n");
            } else if (reed == 0) {
                log_event("door opened");
            } else {
                log_event("door not opened");
            }
        }
        usleep(SAMPLE_MS * 1000);
    }

    gpioWrite(RELAY_GPIO, 0);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    gpioTerminate();
    printf("Exiting cleanly.\n");
    return 0;
}

