#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PUMP_GPIO 18
#define DEFAULT_THRESHOLD 30
#define DEFAULT_PUMP_DURATION 10
#define DEFAULT_SLEEP_INTERVAL 60
#define MAX_RETRIES 3
#define ADC_MAX_VALUE 1023
#define ADC_VREF 3.3

static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int result = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (result == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %d\n", attempt + 1, MAX_RETRIES, result);
        gpioDelay(100000);
    }
    return -1;
}

static void log_event(const char *message) {
    FILE *fp = fopen("irrigation.log", "a");
    if (!fp) {
        perror("Error opening irrigation.log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) < 0) {
        fprintf(stderr, "Failed to write to pump GPIO %d\n", PUMP_GPIO);
    }
}

int main(int argc, char *argv[]) {
    int threshold = DEFAULT_THRESHOLD;
    int pump_duration = DEFAULT_PUMP_DURATION;
    int sleep_interval = DEFAULT_SLEEP_INTERVAL;
    int opt;

    while ((opt = getopt(argc, argv, "t:d:s:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atoi(optarg);
                if (threshold < 0 || threshold > 100) {
                    fprintf(stderr, "Threshold must be between 0 and 100\n");
                    return 1;
                }
                break;
            case 'd':
                pump_duration = atoi(optarg);
                if (pump_duration <= 0) {
                    fprintf(stderr, "Pump duration must be positive\n");
                    return 1;
                }
                break;
            case 's':
                sleep_interval = atoi(optarg);
                if (sleep_interval <= 0) {
                    fprintf(stderr, "Sleep interval must be positive\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold] [-d pump_duration] [-s sleep_interval]\n", argv[0]);
                return 1;
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set pump GPIO %d as output\n", PUMP_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }
    control_pump(0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Irrigation system started. Threshold: %d%%, Pump Duration: %ds, Sleep Interval: %ds\n",
           threshold, pump_duration, sleep_interval);

    while (!terminate) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries, skipping cycle\n", MAX_RETRIES);
            log_event("Error: ADC read failed, skipping irrigation cycle");
            for (int i = 0; i < sleep_interval && !terminate; i++) {
                gpioDelay(1000000);
            }
            continue;
        }

        float voltage = (adc_value / (float)ADC_MAX_VALUE) * ADC_VREF;
        float moisture_percentage = (voltage / ADC_VREF) * 100.0f;

        char log_message[256];
        snprintf(log_message, sizeof(log_message),
                 "Moisture: %.2f%% (ADC: %d, V: %.3f)", moisture_percentage, adc_value, voltage);
        log_event(log_message);

        if (moisture_percentage < threshold) {
            printf("Moisture level below threshold (%.2f%% < %d%%), activating pump\n", moisture_percentage, threshold);
            log_event("Moisture below threshold, activating pump");
            control_pump(1);

            for (int i = 0; i < pump_duration && !terminate; i++) {
                gpioDelay(1000000);
            }

            control_pump(0);
            log_event("Pump deactivated");
        }

        for (int i = 0; i < sleep_interval && !terminate; i++) {
            gpioDelay(1000000);
        }
    }

    printf("\nShutting down...\n");
    control_pump(0);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

