#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define LOG_FILE "/var/log/sound_events.log"
#define SAMPLE_INTERVAL_US 10000
#define INITIAL_THRESHOLD 500
#define THRESHOLD_ADJUSTMENT 10
#define SAMPLES_FOR_AVG 10

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int detect_peak(int value, int threshold) {
    return (value > threshold) ? 1 : 0;
}

static void log_event(int value) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file != NULL) {
        if (fprintf(log_file, "%s - Sound level: %d\n", timestamp, value) < 0) {
            fprintf(stderr, "Failed to write to log file\n");
        }
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file not opened\n");
    }
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int threshold = INITIAL_THRESHOLD;
    int samples[SAMPLES_FOR_AVG];
    int sample_count = 0;
    int sum = 0;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to set signal handlers\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Sound event detection started. Press Ctrl+C to exit.\n");

    while (running) {
        int value = read_mcp3008(MCP3008_CHANNEL);
        if (value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (sample_count < SAMPLES_FOR_AVG) {
            samples[sample_count] = value;
            sum += value;
            sample_count++;
        } else {
            sum -= samples[0];
            for (int i = 0; i < SAMPLES_FOR_AVG - 1; i++) {
                samples[i] = samples[i + 1];
            }
            samples[SAMPLES_FOR_AVG - 1] = value;
            sum += value;
        }

        int avg = sum / SAMPLES_FOR_AVG;

        if (detect_peak(avg, threshold)) {
            log_event(avg);
            threshold += THRESHOLD_ADJUSTMENT;
        } else {
            threshold -= THRESHOLD_ADJUSTMENT;
            if (threshold < INITIAL_THRESHOLD) {
                threshold = INITIAL_THRESHOLD;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

