#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define PCF8591_ADDR   0x48
#define PCF8591_CTRL   0x00   /* single-ended, AIN0, auto-increment off */
#define SAMPLE_US      100000 /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_byte(int fd, uint8_t *byte)
{
    ssize_t n = read(fd, byte, 1);
    if (n != 1) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int fd = -1;
    int rc = EXIT_FAILURE;

    /* Install SIGINT handler for clean shutdown on Ctrl-C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the I2C bus */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire the PCF8591 slave address */
    if (ioctl(fd, I2C_SLAVE, PCF8591_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                PCF8591_ADDR, strerror(errno));
        goto cleanup;
    }

    /*
     * PCF8591 is a 2-byte device: the first write selects the control
     * byte (channel + mode), and the second read returns the result of
     * the *previous* conversion.  A dummy read discards that stale byte.
     */
    uint8_t dummy;
    if (i2c_read_byte(fd, &dummy) != 0) {
        fprintf(stderr, "Dummy read failed (device may be absent or bus error)\n");
        goto cleanup;
    }

    /* Main sampling loop */
    while (g_running) {
        /* Select AIN0 single-ended, no auto-increment */
        if (i2c_write_byte(fd, PCF8591_CTRL) != 0) {
            goto cleanup;
        }

        /*
         * Small delay so the PCF8591 has time to complete the
         * conversion before the next read returns the stale result.
         */
        usleep(1000);

        /* Read the current 8-bit sample (0-255) */
        uint8_t sample;
        if (i2c_read_byte(fd, &sample) != 0) {
            goto cleanup;
        }

        printf("AIN0: %u\n", (unsigned)sample);
        fflush(stdout);

        usleep(SAMPLE_US);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fd >= 0) {
        close(fd);
    }
    return rc;
}

