#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <syslog.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48
#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01

/*
 * Config word (16-bit, big-endian on the bus):
 *   Bit 15    OS       = 1  (begin single conversion)
 *   Bits14:12 MUX      = 100 (AIN0 single-ended)
 *   Bits11:9  PGA      = 001 (+/-4.096 V)
 *   Bit 8     MODE     = 1  (single-shot)
 *   Bits7:5   DR       = 100 (128 SPS)
 *   Bit 4     COMP_MODE= 0
 *   Bit 3     COMP_POL = 0
 *   Bit 2     COMP_LAT = 0
 *   Bits1:0   COMP_QUE = 11 (disable comparator)
 * => 0xC183
 */
#define ADS1115_CONFIG       0xC183

#define MOTOR_SHUTDOWN_PIN   27
#define THRESHOLD_GAUSS      500.0f
#define BUFFER_SIZE          10
#define SAMPLE_PERIOD_US     1000000  /* 1 Hz */
#define ADC_MAX_COUNT        32767.0f /* 16-bit signed, single-ended */
#define ADC_VREF             4.096f   /* PGA full-scale for +/-4.096 V */
#define SENSOR_VSUPPLY       3.3f     /* SS49E supply rail */
#define SENSOR_SENSITIVITY   0.0001f  /* V/Gauss (example calibration) */

/* ----------------------------- Globals ----------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static int  init_ads1115(void);
static int  read_ads1115(int16_t *raw_out);
static float voltage_to_gauss(float voltage);
static void buffer_add(float value);
static float buffer_average(void);
static void motor_shutdown(void);
static void cleanup(void);

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- ADS1115 init ------------------------------- */
static int init_ads1115(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (g_i2c_handle < 0) {
        syslog(LOG_ERR, "i2cOpen failed (bus=%d, addr=0x%02X): %d",
               I2C_BUS, ADS1115_ADDR, g_i2c_handle);
        return -1;
    }

    /* Write config: single-shot, AIN0, +/-4.096 V, 128 SPS, comparator off */
    char cfg[3] = {
        ADS1115_REG_CONFIG,
        (char)((ADS1115_CONFIG >> 8) & 0xFF),
        (char)(ADS1115_CONFIG & 0xFF)
    };
    if (i2cWriteDevice(g_i2c_handle, cfg, 3) < 0) {
        syslog(LOG_ERR, "Failed to write ADS1115 config register");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    syslog(LOG_INFO, "ADS1115 initialized (I2C handle %d)", g_i2c_handle);
    return 0;
}

/* ----------------------------- ADS1115 read ------------------------------- */
static int read_ads1115(int16_t *raw_out)
{
    char reg = ADS1115_REG_CONV;
    if (i2cWriteDevice(g_i2c_handle, &reg, 1) < 0) {
        syslog(LOG_ERR, "Failed to select ADS1115 conversion register");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(g_i2c_handle, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read ADS1115 conversion data");
        return -1;
    }

    /* ADS1115 returns big-endian: MSB first */
    *raw_out = (int16_t)(((uint16_t)(uint8_t)data[0] << 8) |
                         (uint16_t)(uint8_t)data[1]);
    return 0;
}

/* ----------------------------- Voltage -> Gauss ---------------------------- */
static float voltage_to_gauss(float voltage)
{
    /*
     * SS49E is a linear Hall sensor.  The output voltage is proportional
     * to the magnetic field strength.  The sensitivity is given in V/Gauss.
     *
     *   Gauss = voltage / SENSOR_SENSITIVITY
     *
     * Clamp to 0 Gauss for negative voltages (sensor output is always >= 0).
     */
    if (voltage < 0.0f) {
        return 0.0f;
    }
    return voltage / SENSOR_SENSITIVITY;
}

/* ----------------------------- Circular buffer ---------------------------- */
static float g_buffer[BUFFER_SIZE];
static int   g_buf_idx = 0;
static int   g_buf_count = 0;

static void buffer_add(float value)
{
    g_buffer[g_buf_idx] = value;
    g_buf_idx = (g_buf_idx + 1) % BUFFER_SIZE;
    if (g_buf_count < BUFFER_SIZE) {
        g_buf_count++;
    }
}

static float buffer_average(void)
{
    if (g_buf_count == 0) {
        return 0.0f;
    }
    float sum = 0.0f;
    for (int i = 0; i < g_buf_count; i++) {
        sum += g_buffer[i];
    }
    return sum / (float)g_buf_count;
}

/* ----------------------------- Motor shutdown ----------------------------- */
static void motor_shutdown(void)
{
    if (gpioWrite(MOTOR_SHUTDOWN_PIN, 1) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d HIGH", MOTOR_SHUTDOWN_PIN);
        return;
    }
    syslog(LOG_CRIT, "Threshold exceeded (%.2f Gauss > %.2f Gauss). "
                    "Motor shutdown activated on GPIO%d.",
           buffer_average(), THRESHOLD_GAUSS, MOTOR_SHUTDOWN_PIN);
}

/* ----------------------------- Cleanup ------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(MOTOR_SHUTDOWN_PIN, 0);
    gpioTerminate();
    closelog();
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    openlog("hall_sensor_monitor", LOG_PID | LOG_CONS, LOG_USER);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /* Configure motor shutdown pin as output, initially LOW */
    if (gpioSetMode(MOTOR_SHUTDOWN_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as output", MOTOR_SHUTDOWN_PIN);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(MOTOR_SHUTDOWN_PIN, 0);

    /* Initialize ADS1115 */
    if (init_ads1115() != 0) {
        syslog(LOG_ERR, "ADS1115 initialization failed. Exiting.");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Monitoring started. Sampling at 1 Hz.");

    while (g_running) {
        int16_t raw;
        if (read_ads1115(&raw) != 0) {
            /* I2C/ADC read failure: skip this sample, keep running */
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Convert raw ADC count to voltage */
        float voltage = ((float)raw / ADC_MAX_COUNT) * ADC_VREF;

        /* Sanity-check: sensor output is never negative */
        if (voltage < 0.0f) {
            syslog(LOG_WARNING, "Negative voltage (%.4f V) from ADC; skipping sample",
                   voltage);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Convert voltage to Gauss */
        float gauss = voltage_to_gauss(voltage);

        /* Store in circular buffer */
        buffer_add(gauss);

        /* Log the reading */
        syslog(LOG_INFO, "Raw=%d  Voltage=%.4f V  Field=%.2f Gauss  Avg=%.2f Gauss",
               raw, voltage, gauss, buffer_average());

        /* Check threshold */
        if (buffer_average() > THRESHOLD_GAUSS) {
            motor_shutdown();
            /*
             * Keep motor shutdown active.  In a real application you might
             * want to poll the sensor or use a separate watchdog thread.
             */
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    syslog(LOG_INFO, "Shutting down gracefully.");
