#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8

#define ADC_CHANNEL     0
#define MOISTURE_THRESHOLD 300
#define PUMP_GPIO       18
#define WATERING_DURATION_SEC 10
#define SAMPLE_INTERVAL_SEC 60
#define LOG_FILE        "watering_events.txt"
#define MAX_ADC_VALUE   1023
#define INVALID_ADC_VALUE (-1)

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_pump_gpio_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }

    return fd;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return INVALID_ADC_VALUE;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((channel & 0x07) << 4) | 0x80,
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
        .tx_nbits = 0,
        .rx_nbits = 0,
        .pad = 0
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return INVALID_ADC_VALUE;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc_value < 0 || adc_value > MAX_ADC_VALUE) {
        fprintf(stderr, "ADC value out of range: %d\n", adc_value);
        return INVALID_ADC_VALUE;
    }
    return adc_value;
}

static int pump_init(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    g_pump_gpio_initialized = 1;

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", PUMP_GPIO);
        return -1;
    }

    if (gpioWrite(PUMP_GPIO, 0) < 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", PUMP_GPIO);
        return -1;
    }
    return 0;
}

static void pump_on(void) {
    if (g_pump_gpio_initialized) {
        gpioWrite(PUMP_GPIO, 1);
    }
}

static void pump_off(void) {
    if (g_pump_gpio_initialized) {
        gpioWrite(PUMP_GPIO, 0);
    }
}

static void log_event(int moisture_level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Moisture Level: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, moisture_level);
    fclose(fp);
}

static void cleanup(void) {
    pump_off();
    if (g_pump_gpio_initialized) {
        gpioTerminate();
        g_pump_gpio_initialized = 0;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return 1;
    }

    if (pump_init() < 0) {
        cleanup();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int moisture_level = read_mcp3008(g_spi_fd, ADC_CHANNEL);
        if (moisture_level == INVALID_ADC_VALUE) {
            fprintf(stderr, "Error reading moisture level. Skipping watering cycle.\n");
        } else {
            printf("Moisture Level: %d\n", moisture_level);

            if (moisture_level < MOISTURE_THRESHOLD) {
                printf("Moisture level below threshold. Activating pump.\n");
                pump_on();
                log_event(moisture_level);

                for (int i = 0; i < WATERING_DURATION_SEC && g_running; i++) {
                    sleep(1);
                }

                pump_off();
                printf("Pump deactivated.\n");
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && g_running; i++) {
            sleep(1);
        }
    }

    cleanup();
    printf("Exiting.\n");
    return 0;
}

