#define SPI_CHANNEL    0          /* SPI0 CE0 (BCM GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define PWM_PIN        18         /* BCM GPIO18 */
#define PWM_FREQ       1000       /* 1 kHz */
#define PWM_RANGE      1023       /* Duty-cycle range 0-1023 */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define SAMPLE_US      100000     /* 100 ms between samples */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample from the MCP3008 (single-ended, 10-bit)             */
/* Returns 0-1023 on success, -1 on error.                             */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int handle, int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read sequence (3 bytes):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Set PWM duty cycle (0-1023)                                        */
/* ------------------------------------------------------------------ */
static void set_pwm(int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(PWM_PIN, duty);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop PWM output */
    gpioPWM(PWM_PIN, 0);

    /* Close SPI handle if open */
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure PWM pin */
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", PWM_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioSetPWMfrequency(PWM_PIN, PWM_FREQ);
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Potentiometer-controlled motor speed\n");
    printf("SPI: channel %d, speed %d Hz, mode 0\n", SPI_CHANNEL, SPI_SPEED);
    printf("PWM: pin %d, freq %d Hz, range %d\n", PWM_PIN, PWM_FREQ, PWM_RANGE);
    printf("ADC: channel %d (single-ended, 10-bit)\n", ADC_CHANNEL);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main loop */
    while (g_running) {
        int adc = read_mcp3008(g_spi_handle, ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read error — skipping cycle\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        set_pwm(adc);
        printf("ADC: %4d  PWM: %4d\n", adc, adc);
        fflush(stdout);

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

