code:
/*
 * Raspberry Pi 4 Model B - Honeywell SS49E Hall-Effect Sensor Monitor
 *
 * Hardware:
 *   - Honeywell SS49E (linear) sensor -> ADS1115 AIN0
 *   - ADS1115 ADC on I2C bus 1, address 0x48
 *   - LED on GPIO17 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -o hall_monitor hall_monitor.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./hall_monitor [-t threshold_gauss]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ----------------------------- Constants ----------------------------- */
#define I2C_BUS              1
#define ADS1115_ADDR         0x48

#define ADS1115_REG_CONV     0x00
#define ADS1115_REG_CONFIG   0x01

/* Config register bits (16-bit, big-endian on the bus) */
#define ADS1115_CFG_OS       0x8000  /* Operational status / single-shot start */
#define ADS1115_CFG_MUX_AIN0 0x4000  /* AIN0 single-ended */
#define ADS1115_CFG_PGA_4096 0x0200  /* PGA gain = 4.096 V */
#define ADS1115_CFG_MODE_SS  0x0100  /* Single-shot mode */
#define ADS1115_CFG_DR_128   0x0080  /* 128 SPS */
#define ADS1115_CFG_CQUE_NONE 0x0003 /* Disable comparator */

#define LED_PIN              17
#define SAMPLE_PERIOD_US     100000  /* 100 ms */
#define BLINK_DURATION_US    1000000 /* 1 second */
#define BLINK_HALF_US        50000   /* 50 ms */

#define DEFAULT_THRESHOLD_GAUSS 100.0

/* --------------------------- Global State ---------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------- Function Prototypes ----------------------- */
static void signal_handler(int sig);
static int  ads1115_init(void);
static int  ads1115_read_raw(int16_t *raw_out);
static double raw_to_gauss(int16_t raw);
static void blink_led(int duration_us);

/* ------------------------------ Signal Handler ----------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- ADS1115 Helpers -------------------------- */
static int ads1115_init(void)
{
    /*
     * Config word: single-shot, AIN0 single-ended, PGA 4.096 V,
     * 128 SPS, no comparator.
     */
    uint16_t config = ADS1115_CFG_OS
                    | ADS1115_CFG_MUX_AIN0
                    | ADS1115_CFG_PGA_4096
                    | ADS1115_CFG_MODE_SS
                    | ADS1115_CFG_DR_128
                    | ADS1115_CFG_CQUE_NONE;

    char buf[3];
    buf[0] = ADS1115_REG_CONFIG;
    buf[1] = (char)((config >> 8) & 0xFF);
    buf[2] = (char)(config & 0xFF);

    if (i2cWriteDevice(g_i2c_handle, buf, 3) < 0) {
        fprintf(stderr, "Error: failed to write ADS1115 config register\n");
        return -1;
    }
    return 0;
}

static int ads1115_read_raw(int16_t *raw_out)
{
    char reg = ADS1115_REG_CONV;

    /* Point to the conversion register */
    if (i2cWriteDevice(g_i2c_handle, &reg, 1) < 0) {
        fprintf(stderr, "Error: failed to select ADS1115 conversion register\n");
        return -1;
    }

    char data[2];
    if (i2cReadDevice(g_i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error: failed to read ADS1115 conversion data\n");
        return -1;
    }

    *raw_out = (int16_t)(((uint16_t)(uint8_t)data[0] << 8) |
                         (uint16_t)(uint8_t)data[1]);
    return 0;
}

static double raw_to_gauss(int16_t raw)
{
    /*
     * PGA = 4.096 V, 16-bit signed => LSB = 125 µV.
     * SS49E output: 0.12 V (120 mGauss) at 1000 Gauss.
     * => 120 mGauss / 1000 Gauss = 0.00012 V/Gauss.
     * raw * 4.096 / 32768 * 0.00012 / 0.001 = Gauss.
     */
    const double pga_v = 4.096;
    const double lsb_v = pga_v / 32768.0;
    const double v_per_gauss = 0.00012;
    const double mA_per_gauss = 1000.0;

    double voltage = (double)raw * lsb_v;
    double gauss = (voltage / v_per_gauss) * mA_per_gauss;
    return gauss;
}

/* ------------------------------- LED Blink --------------------------- */
static void blink_led(int duration_us)
{
    uint32_t start = gpioTick();
    while (g_running && (gpioTick() - start) < (uint32_t)duration_us) {
        gpioWrite(LED_PIN, 1);
        gpioDelay(BLINK_HALF_US);
        gpioWrite(LED_PIN, 0);
        gpioDelay(BLINK_HALF_US);
    }
}

/* --------------------------------- Main ------------------------------ */
int main(int argc, char *argv[])
{
    double threshold_gauss = DEFAULT_THRESHOLD_GAUSS;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
        case 't':
            threshold_gauss = atof(optarg);
            if (threshold_gauss <= 0.0) {
                fprintf(stderr, "Error: threshold must be positive\n");
                return EXIT_FAILURE;
            }
            break;
        default:
