#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>
#include <mosquitto.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define PUMP_GPIO 17
#define MOISTURE_THRESHOLD_LOW 30
#define MOISTURE_THRESHOLD_HIGH 35
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "soil_moisture"
#define MQTT_CONTROL_TOPIC "pump_control"
#define SAMPLE_INTERVAL 60
#define ADC_MAX_VALUE 1023
#define ADC_MIN_VALUE 0

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;
static struct mosquitto *mosq = NULL;
static int pump_state = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid ADC channel: %d", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, tx, rx, 3) != 3) {
        syslog(LOG_ERR, "SPI transfer failed");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    if (adc_value < ADC_MIN_VALUE || adc_value > ADC_MAX_VALUE) {
        syslog(LOG_ERR, "ADC value out of range: %d", adc_value);
        return -1;
    }
    return adc_value;
}

static int calculate_moisture_percentage(int adc_value) {
    if (adc_value < ADC_MIN_VALUE || adc_value > ADC_MAX_VALUE) {
        return -1;
    }
    return (int)(((float)(adc_value - ADC_MIN_VALUE) / (ADC_MAX_VALUE - ADC_MIN_VALUE)) * 100.0);
}

static int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) != 0) {
        syslog(LOG_ERR, "Failed to write to pump GPIO");
        return -1;
    }
    pump_state = state;
    syslog(LOG_INFO, "Pump %s", state ? "ON" : "OFF");
    return 0;
}

static void mqtt_connect_callback(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "MQTT connected");
        if (mosquitto_subscribe(m, NULL, MQTT_CONTROL_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to %s", MQTT_CONTROL_TOPIC);
        }
    } else {
        syslog(LOG_ERR, "MQTT connection error: %s", mosquitto_strerror(result));
    }
}

static void mqtt_disconnect_callback(struct mosquitto *m, void *userdata, int rc) {
    (void)m; (void)userdata;
    if (rc != 0) {
        syslog(LOG_ERR, "MQTT disconnected unexpectedly: %s", mosquitto_strerror(rc));
    }
}

static void mqtt_message_callback(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m; (void)userdata;
    if (message->payloadlen > 0) {
        char payload[32];
        int len = message->payloadlen < (int)sizeof(payload) - 1 ? message->payloadlen : (int)sizeof(payload) - 1;
        memcpy(payload, message->payload, len);
        payload[len] = '\0';

        if (strcmp(message->topic, MQTT_CONTROL_TOPIC) == 0) {
            if (strcmp(payload, "pump_on") == 0) {
                control_pump(1);
            } else if (strcmp(payload, "pump_off") == 0) {
                control_pump(0);
            } else {
                syslog(LOG_WARNING, "Unknown pump control command: %s", payload);
            }
        }
    }
}

int main(void) {
    openlog("soil_moisture_monitor", LOG_PID | LOG_CONS, LOG_USER);

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        syslog(LOG_ERR, "Failed to set pump GPIO mode");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        syslog(LOG_ERR, "SPI initialisation failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "MQTT new instance failed");
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect error: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        spiClose(spi_handle);
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    syslog(LOG_INFO, "Starting soil moisture monitoring");

    while (running) {
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            syslog(LOG_ERR, "Failed to read ADC value");
        } else {
            int moisture = calculate_moisture_percentage(adc_value);
            if (moisture < 0) {
                syslog(LOG_ERR, "Failed to calculate moisture percentage");
            } else {
                syslog(LOG_INFO, "Moisture: %d%%", moisture);

                if (mosquitto_publish(mosq, NULL, MQTT_TOPIC, strlen(MQTT_TOPIC), MQTT_TOPIC, 0, false) != MOSQ_ERR_SUCCESS) {
                    syslog(LOG_ERR, "Failed to publish moisture reading");
                }

                if (moisture < MOISTURE_THRESHOLD_LOW && pump_state == 0) {
                    control_pump(1);
                } else if (moisture > MOISTURE_THRESHOLD_HIGH && pump_state == 1) {
                    control_pump(0);
                }
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down");
    control_pump(0);

    if (spi_handle >= 0) spiClose(spi_handle);
    if (mosq) mosquitto_disconnect(mosq);
    if (mosq) mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

