            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down");
    control_pump(0);

    if (spi_handle >= 0) spiClose(spi_handle);
    if (mosq) mosquitto_disconnect(mosq);
    if (mosq) mosquitto_destroy(mosq);
    mosquitto_lib_cleanup();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

