#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define VREF 3.3
#define NUM_CHANNELS 3
#define CSV_FILENAME "sensor_data.csv"
#define SAMPLE_INTERVAL_SEC 5

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, config byte, dummy byte */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: SPI transfer failed on channel %d (ret=%d)\n", channel, ret);
        return -1;
    }

    /* 10-bit result: low 2 bits of rx[1] << 8 | rx[2] */
    return ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
}

static double adc_to_voltage(int adc_value) {
    return ((double)adc_value / 1023.0) * VREF;
}

static int log_data(double v0, double v1, double v2) {
    FILE *fp = fopen(CSV_FILENAME, "a");
    if (!fp) {
        perror("Error opening " CSV_FILENAME);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("Error getting local time");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.3f,%.3f,%.3f\n", timestamp, v0, v1, v2) < 0) {
        perror("Error writing to CSV file");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("Error closing CSV file");
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error installing SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error installing SIGTERM handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("MCP3008 data logger started. Logging to %s every %d seconds.\n",
           CSV_FILENAME, SAMPLE_INTERVAL_SEC);
    printf("Press Ctrl+C to stop.\n");

    while (running) {
        int adc[NUM_CHANNELS];
        double voltage[NUM_CHANNELS];
        int error = 0;

        for (int i = 0; i < NUM_CHANNELS; i++) {
            adc[i] = read_mcp3008(i);
            if (adc[i] < 0) {
                error = 1;
                break;
            }
            voltage[i] = adc_to_voltage(adc[i]);
        }

        if (error) {
            fprintf(stderr, "Error: Failed to read one or more ADC channels. Retrying in %d seconds.\n",
                    SAMPLE_INTERVAL_SEC);
        } else {
            if (log_data(voltage[0], voltage[1], voltage[2]) != 0) {
                fprintf(stderr, "Error: Failed to log data. Retrying in %d seconds.\n",
                        SAMPLE_INTERVAL_SEC);
            } else {
                printf("Logged: %.3f V, %.3f V, %.3f V\n", voltage[0], voltage[1], voltage[2]);
            }
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    printf("Cleanup complete.\n");
    return 0;
}

