#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_BITS 8
#define SPI_MODE 0

#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27
#define PWM_PERIOD_NS 10000000  /* 100 Hz */
#define NOISE_THRESHOLD 500
#define SAMPLE_INTERVAL_US 10000 /* 10 ms */

static volatile sig_atomic_t program_running = 1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI max speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("Error sending SPI message");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static void set_motor_pwm(int gpio, int duty_percent) {
    if (duty_percent < 0) duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;

    int duty_ns = (PWM_PERIOD_NS * duty_percent) / 100;
    int period_ns = PWM_PERIOD_NS;

    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/period", gpio);
    FILE *fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "%d", period_ns);
        fclose(fp);
    } else {
        perror("Error setting PWM period");
        return;
    }

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/duty_cycle", gpio);
    fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "%d", duty_ns);
        fclose(fp);
    } else {
        perror("Error setting PWM duty cycle");
        return;
    }

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip0/pwm%d/enable", gpio);
    fp = fopen(path, "w");
    if (fp) {
        fprintf(fp, "1");
        fclose(fp);
    } else {
        perror("Error enabling PWM");
    }
}

static void stop_motor(int gpio) {
    set_motor_pwm(gpio, 0);
}

static void log_event(const char *message) {
    FILE *fp = fopen("vibration_log.txt", "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static void cleanup(void) {
    stop_motor(MOTOR1_GPIO);
    stop_motor(MOTOR2_GPIO);
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Error setting SIGINT handler");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Error setting SIGTERM handler");
        return 1;
    }

    if (spi_init() < 0) {
        log_event("SPI initialization failed. Exiting.");
        return 1;
    }

    log_event("Program started.");

    while (program_running) {
        int adc_value = read_adc(0);
        if (adc_value < 0) {
            log_event("ADC read error. Skipping iteration.");
            usleep(SAMPLE_INTERVAL_US);
            continue;
        }

        int duty1 = 0, duty2 = 0;
        if (adc_value > NOISE_THRESHOLD) {
            duty1 = 50;
            duty2 = 50;
            char msg[128];
            snprintf(msg, sizeof(msg), "Vibration event detected: ADC=%d", adc_value);
            log_event(msg);
        }

        set_motor_pwm(MOTOR1_GPIO, duty1);
        set_motor_pwm(MOTOR2_GPIO, duty2);

        usleep(SAMPLE_INTERVAL_US);
    }

    log_event("Program shutting down.");
    cleanup();
    return 0;
}

