    if (adc_value < 0) return -1.0;
    float voltage = (adc_value / ADC_MAX_VALUE) * ADC_VREF;
    if (voltage < 0.001) return -100.0;
    return 20.0 * log10(voltage);
}

float calculate_light_level(int raw_value) {
    if (raw_value < 0) return -1.0;
    return (float)raw_value / 1.2;
}

int log_data(float sound_level, float light_level, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, sound_level, light_level, error_code) < 0) {
