    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (init_spi() != 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    log_file = fopen(CSV_FILE, "a");
    if (!log_file) {
        perror("Failed to open CSV file");
        cleanup();
        return 1;
    }

    while (running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        int light_raw = read_bh1750();
        int error_code = 0;

        if (adc_value < 0) {
            fprintf(stderr, "ADC read error\n");
            error_code |= 1;
        }
        if (light_raw < 0) {
            fprintf(stderr, "BH1750 read error\n");
            error_code |= 2;
        }

        float sound_level = (adc_value >= 0) ? calculate_sound_level(adc_value) : -1.0;
        float light_level = (light_raw >= 0) ? calculate_light_level(light_raw) : -1.0;

        if (log_data(sound_level, light_level, error_code) != 0) {
            fprintf(stderr, "Logging failed\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return 0;
}

