#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL      0
#define SPI_SPEED        1000000  /* 1 MHz */
#define SPI_FLAGS        0        /* Mode 0, active-low CE */
#define PUMP_GPIO        17
#define MOISTURE_THRESHOLD 30.0f
#define SAMPLE_INTERVAL  60       /* seconds */
#define MAX_RETRIES      3

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended channel (0–7) from the MCP3008.
 * Returns 0–1023 on success, -1 on error.
 */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9–8 in rx[1] (masked 0x03), bits 7–0 in rx[2].
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

static float adc_to_moisture(int adc_value)
{
    /*
     * VH400 0–3 V output -> 0–1023 ADC.
     * Map 0 V (dry) -> 0 % and 3 V (wet) -> 100 %.
     */
    return ((float)adc_value / 1023.0f) * 100.0f;
}

static void control_pump(float moisture_level)
{
    if (moisture_level < MOISTURE_THRESHOLD) {
        if (gpioWrite(PUMP_GPIO, 1) == 0) {
            printf("Moisture level %.2f%% below threshold %.2f%%. Turning pump ON.\n",
                   moisture_level, MOISTURE_THRESHOLD);
        } else {
            fprintf(stderr, "Failed to turn pump ON.\n");
        }
    } else {
        if (gpioWrite(PUMP_GPIO, 0) == 0) {
            printf("Moisture level %.2f%% above threshold %.2f%%. Turning pump OFF.\n",
                   moisture_level, MOISTURE_THRESHOLD);
        } else {
            fprintf(stderr, "Failed to turn pump OFF.\n");
        }
    }
}

static void log_data(float moisture_level)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    printf("[%s] Moisture Level: %.2f%%\n", timestamp, moisture_level);
}

static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(PUMP_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure pump GPIO --- */
    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output.\n", PUMP_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(PUMP_GPIO, 0);  /* ensure pump is off at start */

    /* --- Open SPI bus --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d).\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil Moisture Monitoring System started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc_value = -1;
        int retries = 0;

        /* Retry loop for transient SPI errors */
        while (retries < MAX_RETRIES && g_running) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                fprintf(stderr, "Read attempt %d/%d failed. Retrying in 5 s...\n",
                        retries, MAX_RETRIES);
                sleep(5);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d attempts. Skipping cycle.\n",
                    MAX_RETRIES);
        } else {
            float moisture_level = adc_to_moisture(adc_value);
            log_data(moisture_level);
            control_pump(moisture_level);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

