            fprintf(stderr, "Error reading ADC value, retrying in %d seconds...\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        float co2_ppm = estimate_co2_ppm(adc_value);
        control_fan(co2_ppm);
        int fan_state = gpioRead(FAN_GPIO);
        log_data(co2_ppm, fan_state);

        printf("CO2: %.2f ppm, Fan: %s\n", co2_ppm, fan_state ? "ON" : "OFF");
        sleep(SAMPLE_INTERVAL);
