static int read_mcp3008(int channel, int *out_value)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }
    if (out_value == NULL) {
        return -1;
    }

    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int bytes = spiXfer(g_spi_handle, tx, rx, 3);
    if (bytes != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", bytes);
        return -1;
    }

    *out_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return 0;
}

/* --------------------------- Distance conversion -------------------------- */
/*
 * GP2Y0A21YK0F transfer function (approximate):
 *   distance_cm = 27.0 / (adc_value / 1023.0 + 0.5)
 *   Valid range ~5 cm to ~80 cm.  Below ~5 cm the sensor saturates.
 */
static float adc_to_distance(int adc_value)
{
    if (adc_value < 0) adc_value = 0;
    if (adc_value > ADC_MAX_VALUE) adc_value = ADC_MAX_VALUE;

    float v = (float)adc_value / (float)ADC_MAX_VALUE;
    if (v < 0.005f) {
        return 999.0f;  /* out of range */
    }
    return 27.0f / (v + 0.5f);
}

/* ------------------------------- Event logging ---------------------------- */
static int log_event(float distance_cm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return -1;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        perror("localtime_r()");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s - Distance: %.2f cm\n", ts, distance_cm) < 0) {
        perror("fprintf()");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        perror("fflush()");
        return -1;
    }
    return 0;
}

/* ------------------------------- Cleanup ---------------------------------- */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure relay is off before terminating pigpio */
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* --------------------------- Signal handling ------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI bus */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "spiOpen() failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d) failed\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_GPIO, 0) != 0) {
        fprintf(stderr, "gpioWrite(%d, 0) failed\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Door trigger system started.  Ctrl+C to exit.\n");

    time_t last_trigger = 0;

    while (g_running) {
        int adc_value = 0;
        if (read_mcp3008(ADC_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "ADC read error – sensor absent or bus fault\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        float distance = adc_to_distance(adc_value);

        if (distance < DISTANCE_THRESHOLD_CM) {
            time_t now = time(NULL);
            if (now == (time_t)-1) {
                perror("time()");
            } else if (difftime(now, last_trigger) >= DEBOUNCE_SEC) {
                printf("Distance: %.2f cm – triggering relay\n", distance);

                if (gpioWrite(RELAY_GPIO, 1) != 0) {
                    fprintf(stderr, "gpioWrite(%d, 1) failed\n", RELAY_GPIO);
                } else {
                    if (log_event(distance) != 0) {
                        fprintf(stderr, "Failed to log event\n");
                    }
                    last_trigger = now;
                }

                /* Keep relay on for 1 second, checking for shutdown */
                for (int i = 0; i < 10 && g_running; i++) {
                    gpioDelay(100000);  /* 100 ms */
                }
                if (gpioWrite(RELAY_GPIO, 0) != 0) {
                    fprintf(stderr, "gpioWrite(%d, 0) failed\n", RELAY_GPIO);
                }
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

