#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8

#define VALVE_GPIO      17
#define PWM_FREQ_HZ     100
#define PWM_RANGE       100
#define SAMPLE_COUNT    3
#define SAMPLE_DELAY_US 100000
#define LOG_INTERVAL_S  5

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd   = -1;
static FILE *g_log_fp  = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(g_spi_fd); g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int set_valve_position(int position)
{
    if (position < 0 || position > 100) {
        fprintf(stderr, "Invalid valve position %d (must be 0-100)\n", position);
        return -1;
    }
    if (gpioPWM(VALVE_GPIO, position) < 0) {
        fprintf(stderr, "gpioPWM failed for GPIO %d\n", VALVE_GPIO);
        return -1;
    }
    return 0;
}

static void log_data(int s1, int s2, int s3, float avg, int pos)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_fp, "%s, S1=%d, S2=%d, S3=%d, Avg=%.2f, Valve=%d\n",
            ts, s1, s2, s3, avg, pos);
    fflush(g_log_fp);
}

static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(VALVE_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", VALVE_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed for GPIO %d\n", VALVE_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(VALVE_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed for GPIO %d\n", VALVE_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (spi_init() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("irrigation.log", "a");
    if (!g_log_fp) {
        perror("fopen(irrigation.log)");
        close(g_spi_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Irrigation system started. Logging to irrigation.log every %d s.\n",
           LOG_INTERVAL_S);

    while (g_running) {
        int readings[SAMPLE_COUNT];
        int valid = 0;

        for (int i = 0; i < SAMPLE_COUNT; i++) {
            int v = read_mcp3008(0);
            if (v < 0) {
                fprintf(stderr, "SPI read failed on sample %d\n", i + 1);
            } else {
                readings[valid++] = v;
            }
            if (i < SAMPLE_COUNT - 1) {
                gpioDelay(SAMPLE_DELAY_US);
            }
        }

        if (valid == 0) {
            fprintf(stderr, "All SPI reads failed; skipping cycle.\n");
            gpioDelay(LOG_INTERVAL_S * 1000000);
            continue;
        }

        float sum = 0.0f;
        for (int i = 0; i < valid; i++) {
            sum += readings[i];
        }
        float avg = sum / (float)valid;

        int pos = (int)(avg / 1023.0f * 100.0f);
        if (pos < 0)   pos = 0;
        if (pos > 100) pos = 100;

        if (set_valve_position(pos) < 0) {
            fprintf(stderr, "Failed to set valve position\n");
        }

        log_data(readings[0], readings[1], readings[2], avg, pos);

        for (int s = 0; s < LOG_INTERVAL_S && g_running; s++) {
            gpioDelay(1000000);
        }
    }

    printf("\nShutting down...\n");
    set_valve_position(0);
    cleanup();
    return EXIT_SUCCESS;
}

