#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define LOG_FILE "soil_data.txt"
#define SAMPLE_INTERVAL 5
#define MAX_RETRIES 5
#define RETRY_DELAY_MS 100

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_moisture(int adc_value) {
    if (adc_value < 0) adc_value = 0;
    if (adc_value > 1023) adc_value = 1023;
    return ((float)adc_value / 1023.0f) * 100.0f;
}

static void log_data(float moisture, const char *status) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s, Moisture: %.2f%%, Status: %s\n", timestamp, moisture, status);
    } else {
        fprintf(fp, "Timestamp error, Moisture: %.2f%%, Status: %s\n", moisture, status);
    }

    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc_value = -1;
        int retries = 0;
        int delay_ms = RETRY_DELAY_MS;

        while (retries < MAX_RETRIES && running) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value >= 0) {
                break;
            }
