#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <sys/mman.h>
#include <sys/stat.h>

#define CONFIG_FILE "theremin_config.txt"
#define PWM_EXPORT_PATH "/sys/class/pwm/pwmchip0/export"
#define PWM_UNEXPORT_PATH "/sys/class/pwm/pwmchip0/unexport"
#define PWM_PERIOD_PATH "/sys/class/pwm/pwmchip0/pwm0/period"
#define PWM_DUTY_CYCLE_PATH "/sys/class/pwm/pwmchip0/pwm0/duty_cycle"
#define PWM_ENABLE_PATH "/sys/class/pwm/pwmchip0/pwm0/enable"

#define TRIG_PIN 23
#define ECHO_PIN 24
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000

#define MIN_DISTANCE_CM 2.0
#define MAX_DISTANCE_CM 400.0
#define MIN_FREQUENCY_HZ 20.0
#define MAX_FREQUENCY_HZ 2000.0
#define MIN_VOLUME 0.0
#define MAX_VOLUME 1.0

#define SPEED_OF_SOUND_CM_PER_S 34300.0

volatile sig_atomic_t program_running = 1;
float last_valid_distance = 50.0;
float last_valid_volume = 0.5;

typedef struct {
    float min_distance;
    float max_distance;
    float min_frequency;
    float max_frequency;
    float min_volume;
    float max_volume;
} Config;

Config config = {
    MIN_DISTANCE_CM, MAX_DISTANCE_CM,
    MIN_FREQUENCY_HZ, MAX_FREQUENCY_HZ,
    MIN_VOLUME, MAX_VOLUME
};

void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

int write_sysfs(const char *path, const char *value) {
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, value, strlen(value)) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

int read_sysfs(const char *path, char *buf, size_t buf_size) {
    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    ssize_t bytes = read(fd, buf, buf_size - 1);
    if (bytes < 0) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    buf[bytes] = '\0';
    close(fd);
    return 0;
}

int pwm_init() {
    if (write_sysfs(PWM_EXPORT_PATH, "0") < 0) return -1;
    usleep(100000);
    if (write_sysfs(PWM_PERIOD_PATH, "1000000") < 0) return -1;
    if (write_sysfs(PWM_DUTY_CYCLE_PATH, "0") < 0) return -1;
    if (write_sysfs(PWM_ENABLE_PATH, "1") < 0) return -1;
    return 0;
}

void pwm_cleanup() {
    write_sysfs(PWM_ENABLE_PATH, "0");
    write_sysfs(PWM_DUTY_CYCLE_PATH, "0");
    write_sysfs(PWM_UNEXPORT_PATH, "0");
}

void pwm_set_duty_cycle(float duty) {
    if (duty < 0.0) duty = 0.0;
    if (duty > 1.0) duty = 1.0;
    char buf[32];
    snprintf(buf, sizeof(buf), "%d", (int)(duty * 1000000));
    write_sysfs(PWM_DUTY_CYCLE_PATH, buf);
}

int spi_init(int *fd) {
    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }
    int mode = SPI_MODE_0;
    if (ioctl(*fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }
    int bits = 8;
    if (ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }
    int speed = SPI_SPEED;
    if (ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI speed: %s\n", strerror(errno));
        close(*fd);
        return -1;
    }
    return 0;
}

int read_ldr(int spi_fd, int *ldr_value) {
    unsigned char tx[3] = {0x01, 0x80, 0x00};
    unsigned char rx[3] = {0};
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
        .delay_usecs = 0
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }
    *ldr_value = ((rx[1] & 0x03) << 8) + rx[2];
    return 0;
}

float read_distance(int trig_pin, int echo_pin) {
    char buf[64];
    char path[128];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", trig_pin);
    if (write_sysfs(path, "1") < 0) return -1.0;
    usleep(10);
    if (write_sysfs(path, "0") < 0) return -1.0;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", echo_pin);
    struct timespec start, end;
    int timeout = 0;
    while (1) {
        if (read_sysfs(path, buf, sizeof(buf)) < 0) return -1.0;
        if (buf[0] == '1') {
            clock_gettime(CLOCK_MONOTONIC, &start);
            break;
        }
        usleep(10);
        if (++timeout > 100000) return -1.0;
    }
    timeout = 0;
    while (1) {
        if (read_sysfs(path, buf, sizeof(buf)) < 0) return -1.0;
        if (buf[0] == '0') {
            clock_gettime(CLOCK_MONOTONIC, &end);
            break;
        }
        usleep(10);
        if (++timeout > 200000) return -1.0;
    }
    double elapsed = (end.tv_sec - start.tv_sec) + (end.tv_nsec - start.tv_nsec) / 1000000000.0;
    return (elapsed * SPEED_OF_SOUND_CM_PER_S) / 2.0;
}

float map_distance_to_frequency(float distance) {
    if (distance < config.min_distance) distance = config.min_distance;
    if (distance > config.max_distance) distance = config.max_distance;
    return config.min_frequency + (distance - config.min_distance) * (config.max_frequency - config.min_frequency) / (config.max_distance - config.min_distance);
}

float map_ldr_to_volume(int ldr_value) {
    float volume = (float)ldr_value / 1023.0;
    if (volume < config.min_volume) volume = config.min_volume;
    if (volume > config.max_volume) volume = config.max_volume;
    return volume;
}

void save_config() {
    FILE *fp = fopen(CONFIG_FILE, "w");
    if (!fp) {
        fprintf(stderr, "Error opening config file for writing: %s\n", strerror(errno));
        return;
    }
    fprintf(fp, "%f,%f,%f,%f,%f,%f\n", config.min_distance, config.max_distance, config.min_frequency, config.max_frequency, config.min_volume, config.max_volume);
    fclose(fp);
}

void load_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) return;
    if (fscanf(fp, "%f,%f,%f,%f,%f,%f", &config.min_distance, &config.max_distance, &config.min_frequency, &config.max_frequency, &config.min_volume, &config.max_volume) != 6) {
        fprintf(stderr, "Error reading config file, using defaults.\n");
    }
    fclose(fp);
}

int main() {
    signal(SIGINT, signal_handler);
    load_config();

    int spi_fd;
    if (spi_init(&spi_fd) < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    if (pwm_init() < 0) {
        fprintf(stderr, "PWM initialization failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    char buf[64];
    char path[128];
    snprintf(path, sizeof(path), "/sys/class/gpio/export");
    if (write_sysfs(path, "23") < 0) {
        fprintf(stderr, "Failed to export TRIG_PIN. Exiting.\n");
        pwm_cleanup();
        close(spi_fd);
        return 1;
    }
    snprintf(path, sizeof(path), "/sys/class/gpio/export");
    if (write_sysfs(path, "24") < 0) {
        fprintf(stderr, "Failed to export ECHO_PIN. Exiting.\n");
        write_sysfs("/sys/class/gpio/unexport", "23");
        pwm_cleanup();
        close(spi_fd);
        return 1;
    }
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", TRIG_PIN);
    if (write_sysfs(path, "out") < 0) {
        fprintf(stderr, "Failed to set TRIG_PIN direction. Exiting.\n");
        write_sysfs("/sys/class/gpio/unexport", "23");
        write_sysfs("/sys/class/gpio/unexport", "24");
        pwm_cleanup();
        close(spi_fd);
        return 1;
    }
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", ECHO_PIN);
    if (write_sysfs(path, "in") < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN direction. Exiting.\n");
        write_sysfs("/sys/class/gpio/unexport", "23");
        write_sysfs("/sys/class/gpio/unexport", "24");
        pwm_cleanup();
        close(spi_fd);
        return 1;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float distance = read_distance(TRIG_PIN, ECHO_PIN);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance. Using last valid value.\n");
            distance = last_valid_distance;
        } else {
            last_valid_distance = distance;
        }

        int ldr_value;
        if (read_ldr(spi_fd, &ldr_value) < 0) {
            fprintf(stderr, "Error reading LDR. Using last valid value.\n");
            ldr_value = (int)(last_valid_volume * 1023.0);
        }
        float volume = map_ldr_to_volume(ldr_value);
        last_valid_volume = volume;

        float frequency = map_distance_to_frequency(distance);
        float duty = volume;
        pwm_set_duty_cycle(duty);

        printf("Distance: %.2f cm, Volume: %.2f, Frequency: %.2f Hz\n", distance, volume, frequency);
        usleep(50000);
    }

    printf("\nCleaning up...\n");
    write_sysfs("/sys/class/gpio/unexport", "23");
    write_sysfs("/sys/class/gpio/unexport", "24");
    pwm_cleanup();
    close(spi_fd);
    save_config();
    printf("Exiting.\n");
    return 0;
}

