void load_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) return;
    if (fscanf(fp, "%f,%f,%f,%f,%f,%f", &config.min_distance, &config.max_distance, &config.min_frequency, &config.max_frequency, &config.min_volume, &config.max_volume) != 6) {
        fprintf(stderr, "Error reading config file, using defaults.\n");
    }
    fclose(fp);
}

int main() {
    signal(SIGINT, signal_handler);
    load_config();

    int spi_fd;
    if (spi_init(&spi_fd) < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    if (pwm_init() < 0) {
        fprintf(stderr, "PWM initialization failed. Exiting.\n");
        close(spi_fd);
        return 1;
    }

    char buf[64];
    char path[128];
    snprintf(path, sizeof(path), "/sys/class/gpio/export");
    if (write_sysfs(path, "23") < 0) {
        fprintf(stderr, "Failed to export TRIG_PIN. Exiting.\n");
        pwm_cleanup();
        close(spi_fd);
        return 1;
    }
    snprintf(path, sizeof(path), "/sys/class/gpio/export");
    if (write_sysfs(path, "24") < 0) {
        fprintf(stderr, "Failed to export ECHO_PIN. Exiting.\n");
        write_sysfs("/sys/class/gpio/unexport", "23");
        pwm_cleanup();
        close(spi_fd);
        return 1;
    }
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", TRIG_PIN);
    if (write_sysfs(path, "out") < 0) {
        fprintf(stderr, "Failed to set TRIG_PIN direction. Exiting.\n");
        write_sysfs("/sys/class/gpio/unexport", "23");
        write_sysfs("/sys/class/gpio/unexport", "24");
        pwm_cleanup();
        close(spi_fd);
        return 1;
    }
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", ECHO_PIN);
    if (write_sysfs(path, "in") < 0) {
        fprintf(stderr, "Failed to set ECHO_PIN direction. Exiting.\n");
        write_sysfs("/sys/class/gpio/unexport", "23");
        write_sysfs("/sys/class/gpio/unexport", "24");
        pwm_cleanup();
        close(spi_fd);
        return 1;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (program_running) {
        float distance = read_distance(TRIG_PIN, ECHO_PIN);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance. Using last valid value.\n");
            distance = last_valid_distance;
        } else {
            last_valid_distance = distance;
        }

        int ldr_value;
        if (read_ldr(spi_fd, &ldr_value) < 0) {
            fprintf(stderr, "Error reading LDR. Using last valid value.\n");
            ldr_value = (int)(last_valid_volume * 1023.0);
        }
        float volume = map_ldr_to_volume(ldr_value);
        last_valid_volume = volume;

        float frequency = map_distance_to_frequency(distance);
        float duty = volume;
        pwm_set_duty_cycle(duty);

        printf("Distance: %.2f cm, Volume: %.2f, Frequency: %.2f Hz\n", distance, volume, frequency);
        usleep(50000);
    }

    printf("\nCleaning up...\n");
    write_sysfs("/sys/class/gpio/unexport", "23");
    write_sysfs("/sys/class/gpio/unexport", "24");
    pwm_cleanup();
    close(spi_fd);
    save_config();
    printf("Exiting.\n");
    return 0;
}

