#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define FAN_GPIO 18
#define AQI_THRESHOLD 100
#define LOG_FILE "air_quality.log"
#define SPI_RETRY_COUNT 3
#define SPI_RETRY_DELAY 1
#define SAMPLE_INTERVAL 5

static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    for (int attempt = 0; attempt < SPI_RETRY_COUNT; attempt++) {
        int result = spiXfer(spi_handle, (char *)tx, (char *)rx, 3);
        if (result == 3) {
            return ((rx[1] & 0x03) << 8) | rx[2];
        }
        fprintf(stderr, "SPI transfer failed (attempt %d/%d): %d\n", attempt + 1, SPI_RETRY_COUNT, result);
        if (attempt < SPI_RETRY_COUNT - 1) {
            sleep(SPI_RETRY_DELAY);
        }
    }

    fprintf(stderr, "SPI communication failed after %d retries. Re-initializing SPI.\n", SPI_RETRY_COUNT);
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Failed to re-initialize SPI: %d\n", spi_handle);
        return -1;
    }
    return -1;
}

static int calculate_aqi(int sensor_value) {
    if (sensor_value < 0 || sensor_value > 1023) {
        fprintf(stderr, "Invalid sensor value: %d\n", sensor_value);
        return -1;
    }
    return (int)((float)sensor_value / 1023.0 * 500.0);
}

static void log_data(int aqi) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, AQI: %d\n", timestamp, aqi);
        fflush(log_file);
    } else {
        fprintf(stderr, "Log file is not open.\n");
    }
}

static void control_fan(int aqi) {
    if (aqi > AQI_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1);
        printf("AQI %d > %d. Fan ON.\n", aqi, AQI_THRESHOLD);
    } else {
        gpioWrite(FAN_GPIO, 0);
        printf("AQI %d <= %d. Fan OFF.\n", aqi, AQI_THRESHOLD);
    }
}

static void cleanup(void) {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(FAN_GPIO, 0);
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        cleanup();
        return 1;
    }
    gpioWrite(FAN_GPIO, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int sensor_value = read_mcp3008(0);
        if (sensor_value < 0) {
            fprintf(stderr, "Failed to read sensor value. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        int aqi = calculate_aqi(sensor_value);
        if (aqi < 0) {
            fprintf(stderr, "Failed to calculate AQI. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        log_data(aqi);
        control_fan(aqi);

        sleep(SAMPLE_INTERVAL);
    }

    cleanup();
    return 0;
}

