#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define MCP3008_CHANNEL 0
#define LOG_FILE        "alcohol_log.txt"
#define SAMPLE_INTERVAL 1
#define MAX_RETRIES     3
#define RETRY_DELAY_US  100000
#define ADC_MAX         1023
#define ADC_MIN         0
#define ADC_STUCK_THRESHOLD 10

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_init(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    unsigned char mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    unsigned char bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting SPI bits per word: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    unsigned int speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting SPI max speed: %s\n", strerror(errno));
        close(g_spi_fd);
        g_spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = {
        0x01,
        (unsigned char)((0x08 | channel) << 4),
        0x00
    };
    unsigned char rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static float adc_to_voltage(int adc_value)
{
    return (float)adc_value * 3.3f / (float)ADC_MAX;
}

static float voltage_to_ppm(float voltage)
{
    return voltage * 100.0f;
}

static void log_data(float ppm)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    time(&rawtime);
    gmtime_r(&rawtime, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_info);

    fprintf(g_log_fp, "%s, %.2f ppm\n", timestamp, ppm);
    fflush(g_log_fp);
}

static void classify_and_print(float ppm)
{
    if (ppm > 50.0f) {
        printf("Alcohol detected! Limit exceeded. (%.2f ppm)\n", ppm);
    } else if (ppm < 20.0f) {
        printf("Sobriety confirmed. (%.2f ppm)\n", ppm);
    } else {
        printf("Alcohol level within acceptable range. (%.2f ppm)\n", ppm);
    }
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioTerminate();
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return 1;
    }

    printf("Alcohol sensor monitoring started. Press Ctrl+C to exit.\n");

    int stuck_count = 0;
    int last_adc = -1;

    while (g_running) {
        int adc_value = -1;
        int retries = 0;

        while (retries < MAX_RETRIES && g_running) {
            adc_value = read_mcp3008(MCP3008_CHANNEL);
            if (adc_value >= 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                usleep(RETRY_DELAY_US);
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC after %d retries.\n", MAX_RETRIES);
            time_t rawtime;
            struct tm tm_info;
            char timestamp[32];
            time(&rawtime);
            gmtime_r(&rawtime, &tm_info);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm_info);
            fprintf(g_log_fp, "%s, ERROR: ADC read failed\n", timestamp);
            fflush(g_log_fp);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        if (adc_value == ADC_MIN || adc_value == ADC_MAX) {
            if (adc_value == last_adc) {
                stuck_count++;
                if (stuck_count >= ADC_STUCK_THRESHOLD) {
                    fprintf(stderr, "Warning: ADC stuck at %d for %d samples (sensor absent?).\n",
                            adc_value, stuck_count);
                }
            } else {
                stuck_count = 1;
                last_adc = adc_value;
            }
        } else {
            stuck_count = 0;
            last_adc = adc_value;
        }

        float voltage = adc_to_voltage(adc_value);
        float ppm = voltage_to_ppm(voltage);

        log_data(ppm);
        classify_and_print(ppm);

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return 0;
}

