/*
 * Raspberry Pi 4 Model B – Dual Potentiometer-Driven Motor Controller
 *
 * Hardware:
 *   - MCP3008 ADC on SPI channel 0 (CE0 = GPIO8, SCLK = GPIO11, MOSI = GPIO10, MISO = GPIO9)
 *   - 2x Adafruit Mini DC Motor with wires (Product ID 155)
 *     Motor 1: Enable = GPIO18, Direction = GPIO23
 *     Motor 2: Enable = GPIO24, Direction = GPIO25
 *
 * Behavior:
 *   1. Read two potentiometers via SPI.
 *   2. Map readings to PWM duty cycles (0–100%).
 *   3. Accelerate both motors to the set speed, hold 2 s, decelerate to 0.
 *   4. Pause 5 s.
 *   5. Reverse direction of both motors.
 *   6. Repeat.
 *
 * Build: gcc -O2 -Wall -o motor_control motor_control.c -lpigpio -lrt
 * Run:   sudo ./motor_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments ---- */
#define SPI_CHANNEL    0
#define SPI_SPEED      1000000          /* 1 MHz */
#define SPI_FLAGS      0                /* Mode 0, active-low CE */

#define MOTOR1_ENABLE  18
#define MOTOR1_DIR     23
#define MOTOR2_ENABLE  24
#define MOTOR2_DIR     25

/* ---- PWM parameters ---- */
#define PWM_RANGE      1000             /* 0–1000 → 0–100 % */
#define PWM_FREQ       1000             /* 1 kHz */

/* ---- Timing ---- */
#define ACCEL_DELAY_US 10000            /* 10 ms per acceleration step */
#define HOLD_SEC       2
#define PAUSE_SEC      5

/* ---- Globals for cleanup ---- */
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a single-ended channel (0–7) from the MCP3008.
 * Returns 0–1023 on success, -1 on SPI error. */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer.
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 in rx[1] (low 2 bits) and rx[2] (8 bits). */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n",
                channel, ret);
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc;
}

/* ------------------------------------------------------------------ */
static int map_adc_to_speed(int adc)
{
    if (adc < 0)   adc = 0;
    if (adc > 1023) adc = 1023;
    return (adc * 100) / 1023;          /* 0–100 % */
}

/* ------------------------------------------------------------------ */
static void motor_set(int enable_pin, int dir_pin, int speed)
{
    if (speed < 0)   speed = 0;
    if (speed > 100) speed = 100;

    gpioPWM(enable_pin, speed);
    gpioWrite(dir_pin, (speed > 0) ? 1 : 0);
}

/* ------------------------------------------------------------------ */
static void motor_stop(int enable_pin, int dir_pin)
{
    gpioPWM(enable_pin, 0);
    gpioWrite(dir_pin, 0);
}

/* ------------------------------------------------------------------ */
static void reverse_motors(void)
{
    int d1 = gpioRead(MOTOR1_DIR);
    int d2 = gpioRead(MOTOR2_DIR);
    gpioWrite(MOTOR1_DIR, d2);
    gpioWrite(MOTOR2_DIR, d1);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Stop motors and release PWM */
    motor_stop(MOTOR1_ENABLE, MOTOR1_DIR);
    motor_stop(MOTOR2_ENABLE, MOTOR2_DIR);
    gpioPWM(MOTOR1_ENABLE, 0);
    gpioPWM(MOTOR2_ENABLE, 0);

    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure motor GPIOs ---- */
    int motor_pins[] = { MOTOR1_ENABLE, MOTOR1_DIR, MOTOR2_ENABLE, MOTOR2_DIR };
    for (size_t i = 0; i < sizeof(motor_pins) / sizeof(motor_pins[0]); ++i) {
        if (gpioSetMode(motor_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", motor_pins[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    /* ---- Configure PWM ---- */
    if (gpioSetPWMrange(MOTOR1_ENABLE, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR2_ENABLE, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(MOTOR1_ENABLE, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(MOTOR2_ENABLE, PWM_FREQ) < 0) {
        fprintf(stderr, "Failed to set PWM frequency\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open SPI ---- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Motor control started. Press Ctrl+C to exit.\n");

    /* ---- Main loop ---- */
    while (!terminate) {
        int adc1 = read_mcp3008(0);
        int adc2 = read_mcp3008(1);

        if (adc1 < 0 || adc2 < 0) {
            fprintf(stderr, "SPI read error – aborting cycle\n");
            break;
        }

        int speed1 = map_adc_to_speed(adc1);
        int speed2 = map_adc_to_speed(adc2);

        printf("ADC1=%4d  ADC2=%4d  Speed1=%3d%%  Speed2=%3d%%\n",
               adc1, adc2, speed1, speed2);

        /* Accelerate to speed */
        for (int s = 0; s <= speed1 && !terminate; s += 1) {
            motor_set(MOTOR1_ENABLE, MOTOR1_DIR, s);
            gpioDelay(ACCEL_DELAY_US);
        }
        for (int s = 0; s <= speed2 && !terminate; s += 1) {
            motor_set(MOTOR2_ENABLE, MOTOR2_DIR, s);
            gpioDelay(ACCEL_DELAY_US);
        }

        /* Hold at constant speed */
        if (!terminate) {
            printf("Holding at speed for %d s\n", HOLD_SEC);
            gpioDelay(HOLD_SEC * 1000000);
        }

        /* Decelerate to zero */
        for (int s = speed1; s >= 0 && !terminate; s -= 1) {
            motor_set(MOTOR1_ENABLE, MOTOR1_DIR, s);
            gpioDelay(ACCEL_DELAY_US);
        }
        for (int s = speed2; s >= 0 && !terminate; s -= 1) {
            motor_set(MOTOR2_ENABLE, MOTOR2_DIR, s);
            gpioDelay(ACCEL_DELAY_US);
        }

        /* Pause */
        if (!terminate) {
            printf("Pausing for %d s\n", PAUSE_SEC);
            gpioDelay(PAUSE_SEC * 1000000);
        }

        /* Reverse direction */
        if (!terminate) {
            printf("Reversing direction\n");
            reverse_motors();
            gpioDelay(500000);            /* 0.5 s to let motors settle */
        }
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

