#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LED_PIN 17
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define MCP3008_CHANNEL 0
#define CALIBRATION_TIME 5
#define DEBOUNCE_DELAY_US 10000
#define SAMPLE_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char tx[3] = { 0x01, (unsigned char)((0x08 | channel) << 4), 0x00 };
    unsigned char rx[3] = { 0 };

    if (spiXfer(spi_handle, (char *)tx, (char *)rx, 3) != 3) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int calibrate_noise_level(int duration_seconds) {
    int sum = 0;
    int count = 0;
    time_t start_time = time(NULL);

    printf("Calibrating noise level for %d seconds...\n", duration_seconds);

    while (running && (time(NULL) - start_time) < duration_seconds) {
        int val = read_mcp3008(MCP3008_CHANNEL);
        if (val < 0) {
            fprintf(stderr, "Error reading MCP3008 during calibration\n");
            return -1;
        }
        sum += val;
        count++;
        gpioDelay(SAMPLE_DELAY_US);
    }

    if (!running) {
        return -1;
    }

    if (count == 0) {
        fprintf(stderr, "No samples taken during calibration\n");
        return -1;
    }

    return sum / count;
}

static void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    control_led(0);

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int baseline = calibrate_noise_level(CALIBRATION_TIME);
    if (baseline < 0) {
        fprintf(stderr, "Calibration failed or interrupted\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Baseline noise level: %d\n", baseline);

    int led_state = 0;
    uint32_t last_trigger_tick = 0;

    while (running) {
        int val = read_mcp3008(MCP3008_CHANNEL);
        if (val < 0) {
            fprintf(stderr, "Error reading MCP3008\n");
            gpioDelay(SAMPLE_DELAY_US);
            continue;
        }

        if (val > baseline) {
            uint32_t now = gpioTick();
            if (now - last_trigger_tick > DEBOUNCE_DELAY_US) {
                if (led_state == 0) {
                    control_led(1);
                    led_state = 1;
                    last_trigger_tick = now;
                }
            }
        } else {
            if (led_state == 1) {
                control_led(0);
                led_state = 0;
            }
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    control_led(0);
    spiClose(spi_handle);
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

