/*
 * audio_logger.c — Sample ADMP401 MEMS mic via MCP3008 ADC on Raspberry Pi Zero W
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (pin 1)
 *   MCP3008 VREF -> 3.3 V (pin 1)
 *   MCP3008 AGND -> GND  (pin 6)
 *   MCP3008 DGND -> GND  (pin 6)
 *   MCP3008 CLK  -> GPIO11 (SCLK, pin 23)
 *   MCP3008 DOUT -> GPIO9  (MISO, pin 21)
 *   MCP3008 DIN  -> GPIO10 (MOSI, pin 19)
 *   MCP3008 CS   -> GPIO8  (CE0,  pin 24)
 *   MCP3008 CH0  -> ADMP401 OUT (pin 1)
 *   ADMP401 VDD  -> 3.3 V
 *   ADMP401 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o audio_logger audio_logger.c -lrt
 *
 * Run:
 *   ./audio_logger
