#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/gpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define LOG_FILE        "audio_log.txt"
#define SAMPLE_RATE_HZ  1000
#define SAMPLE_PERIOD_NS (1000000000L / SAMPLE_RATE_HZ)

/* GPIO lines (BCM numbering) */
#define GPIO_CHIP       "/dev/gpiochip0"
#define GPIO_CS_LINE    8   /* CE0 */

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd   = -1;
static int  g_gpio_fd  = -1;
static FILE *g_log_fp  = NULL;

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int setup_signals(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int spi_open(void)
{
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }

    uint32_t speed = 1000000; /* 1 MHz */
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }

    return fd;
}

/* ------------------------------------------------------------------ */
static int gpio_open_and_request_cs(void)
{
    int fd = open(GPIO_CHIP, O_RDWR);
    if (fd < 0) {
        perror("open(" GPIO_CHIP ")");
        return -1;
    }

    struct gpiohandle_request req;
    memset(&req, 0, sizeof(req));
    req.lineoffsets[0] = GPIO_CS_LINE;
    req.flags          = GPIOHANDLE_REQUEST_OUTPUT;
    req.default_values[0] = 1; /* CS idle high */
    req.lines = 1;
    req.consumer_label = "audio_logger";

    if (ioctl(fd, GPIO_GET_LINEHANDLE_IOCTL, &req) < 0) {
        perror("ioctl(GPIO_GET_LINEHANDLE_IOCTL)");
        close(fd);
        return -1;
    }

