    g_gpio_fd = fd;
    return 0;
}

/* ------------------------------------------------------------------ */
static void gpio_release_cs(void)
{
    if (g_gpio_fd >= 0) {
        /* Drive CS high (inactive) */
        struct gpiohandle_data data;
        memset(&data, 0, sizeof(data));
        data.values[0] = 1;
        if (ioctl(g_gpio_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
            perror("ioctl(GPIOHANDLE_SET_LINE_VALUES_IOCTL, high)");
        }
        close(g_gpio_fd);
        g_gpio_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
static int read_mcp3008_channel(int fd, uint8_t channel)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid channel %u\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, then 4 don't-care)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: 10-bit value in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = 1000000;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

