    struct gpiohandle_data data;
    memset(&data, 0, sizeof(data));
    data.values[0] = 0;
    if (ioctl(g_gpio_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
        perror("ioctl(GPIOHANDLE_SET_LINE_VALUES_IOCTL, low)");
        return -1;
    }

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        /* Ensure CS is released on error */
        gpio_release_cs();
        return -1;
    }

    /* Deassert CS high */
    data.values[0] = 1;
    if (ioctl(g_gpio_fd, GPIOHANDLE_SET_LINE_VALUES_IOCTL, &data) < 0) {
        perror("ioctl(GPIOHANDLE_SET_LINE_VALUES_IOCTL, high)");
        return -1;
    }

    int adc = ((rx[1] & 0x03) << 8) | rx[2];
    return adc;
}

/* ------------------------------------------------------------------ */
static int log_sample(FILE *fp, long timestamp_ns, int adc_value)
{
    if (fprintf(fp, "%ld|%d\n", timestamp_ns, adc_value) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    gpio_release_cs();
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    if (setup_signals() != 0) {
        return EXIT_FAILURE;
    }

    g_spi_fd = spi_open();
    if (g_spi_fd < 0) {
        return EXIT_FAILURE;
    }

    if (gpio_open_and_request_cs() != 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "w");
    if (!g_log_fp) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Audio logging started. Press Ctrl+C to stop.\n");

    struct timespec next;
    clock_gettime(CLOCK_MONOTONIC_RAW, &next);

    while (g_running) {
        int adc = read_mcp3008_channel(g_spi_fd, 0);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed; continuing.\n");
        } else {
            struct timespec ts;
            if (clock_gettime(CLOCK_MONOTONIC_RAW, &ts) == 0) {
                long ts_ns = (long)ts.tv_sec * 1000000000L + ts.tv_nsec;
                if (log_sample(g_log_fp, ts_ns, adc) != 0) {
                    fprintf(stderr, "Logging failed; aborting.\n");
                    break;
                }
            } else {
                perror("clock_gettime");
            }
        }

        next.tv_nsec += SAMPLE_PERIOD_NS;
        if (next.tv_nsec >= 1000000000L) {
            next.tv_nsec -= 1000000000L;
            next.tv_sec++;
        }

        struct timespec now;
        clock_gettime(CLOCK_MONOTONIC_RAW, &now);
        if (next.tv_sec > now.tv_sec ||
            (next.tv_sec == now.tv_sec && next.tv_nsec > now.tv_nsec)) {
            struct timespec sleep_ts = {
                .tv_sec  = next.tv_sec - now.tv_sec,
                .tv_nsec = next.tv_nsec - now.tv_nsec
            };
            if (sleep_ts.tv_nsec < 0) {
                sleep_ts.tv_sec--;
                sleep_ts.tv_nsec += 1000000000L;
            }
            nanosleep(&sleep_ts, NULL);
        } else {
            /* Fall back to a short sleep if we're behind */
            struct timespec short_sleep = { 0, 1000000 }; /* 1 ms */
            nanosleep(&short_sleep, NULL);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

