#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

/* Configuration */
#define SPI_CHANNEL 0          /* CE0 */
#define SPI_SPEED 1000000      /* 1 MHz */
#define MCP3008_CHANNEL 0      /* Single-ended channel 0 */
#define VREF 3.3               /* Reference voltage */
#define LOG_FILE "gas_log.txt"
#define SAMPLE_INTERVAL_US 1000000 /* 1 second */
#define ADC_RETRY_DELAY_US 100000  /* 100 ms */

/* Global variables */
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int read_mcp3008(int channel);
static float adc_to_voltage(int adc_value);
static float calculate_ppm(float voltage);
static void log_data(float voltage, float ppm);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* Function to read from MCP3008 ADC via SPI */
static int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    /* MCP3008 SPI protocol: 3 bytes
     * Byte 0: Start bit (0x01)
     * Byte 1: Single-ended mode (0x80) | channel << 4
     * Byte 2: Don't care (0x00)
     */
    char tx_buffer[3] = { 0x01, (char)(0x80 | (channel << 4)), 0x00 };
    char rx_buffer[3] = { 0 };

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d)\n", result);
        return -1;
    }

    /* Extract 10-bit ADC value from the last 2 bits of rx_buffer[1] and rx_buffer[2] */
    int adc_value = ((rx_buffer[1] & 0x03) << 8) | (rx_buffer[2] & 0xFF);
    return adc_value;
}

/* Function to convert ADC value to voltage */
static float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0f) * VREF;
}

/* Function to calculate PPM value (placeholder) */
static float calculate_ppm(float voltage) {
    /*
     * NOTE: The MP-741 is a combustible gas sensor and does NOT output
     * a proportional PPM value directly.  This is a placeholder that
     * scales the voltage linearly to a PPM value for demonstration
     * purposes only.  A real implementation requires calibration with
     * known gas concentrations.
     */
    return voltage * 100.0f;
}

/* Function to log data to file */
static void log_data(float voltage, float ppm) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Voltage: %.3f V, PPM: %.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            voltage, ppm);

    fclose(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel (mode 0, active low CS) */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle %d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler\n");
    }

    printf("Propane Leak Detector running. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, retrying in 100ms...\n");
            gpioDelay(ADC_RETRY_DELAY_US);
            continue;
        }

        float voltage = adc_to_voltage(adc_value);
        float ppm = calculate_ppm(voltage);

        printf("Voltage: %.3f V, PPM: %.2f\n", voltage, ppm);
        log_data(voltage, ppm);

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    cleanup();
    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

