/*
 * ADXL335 via MCP3008 SPI ADC on Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADXL335 X-out -> MCP3008 CH0
 *   ADXL335 Y-out -> MCP3008 CH1
 *   ADXL335 Z-out -> MCP3008 CH2
 *   MCP3008 CS    -> GPIO8  (BCM)
 *   MCP3008 DIN   -> GPIO10 (BCM, MOSI)
 *   MCP3008 DOUT  -> GPIO9  (BCM, MISO)
 *   MCP3008 CLK   -> GPIO11 (BCM, SCLK)
 *   MCP3008 VDD   -> 3.3 V
 *   MCP3008 VREF  -> 3.3 V
 *   MCP3008 AGND  -> GND
 *   MCP3008 DGND  -> GND
 *   ADXL335 VCC   -> 3.3 V
 *   ADXL335 GND   -> GND
 *
 * Build: gcc -O2 -Wall -o adxl335_mcp3008 adxl335_mcp3008.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- Pin / SPI configuration ---- */
#define SPI_CHANNEL    0          /* CE0 on GPIO8 */
#define SPI_BAUD       1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CS */

#define ADC_CHANNELS   3
#define ADC_MAX_VALUE  1023       /* 10-bit ADC */
#define VREF           3.3f

/* ---- Sampling ---- */
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

/* ---- Kalman filter parameters ---- */
#define Q 0.001f   /* Process noise covariance */
#define R 0.1f     /* Measurement noise covariance */

/* ---- Globals for cleanup ---- */
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float x, y, z;
} AccelData;

typedef struct {
    float x, y, z;
    float Pxx, Pxy, Pxz;
    float Pyx, Pyy, Pyz;
    float Pzx, Pzy, Pzz;
} KalmanState;

static KalmanState kstate = {0};

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read one single-ended channel from the MCP3008.
 * Returns 0..1023 on success, -1 on SPI error. */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: 3-byte transfer
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed on channel %d (ret=%d)\n",
                channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (uint8_t)rx[2];
    return adc_value;
}

/* ------------------------------------------------------------------ */
static AccelData read_accelerometer(void)
{
    AccelData d;
    d.x = (float)read_mcp3008(0);
    d.y = (float)read_mcp3008(1);
    d.z = (float)read_mcp3008(2);
    return d;
}

/* ------------------------------------------------------------------ */
static float convert_to_g(int adc_value)
{
    if (adc_value < 0) return 0.0f;
    float voltage = ((float)adc_value / (float)ADC_MAX_VALUE) * VREF;
    /* ADXL335 sensitivity: 3.3 V / 100 mV/g = 33 g full-scale */
    return (voltage - 1.65f) * 33.0f;
}

/* ------------------------------------------------------------------ */
static AccelData kalman_filter(AccelData raw)
{
    AccelData filtered;

    /* Predict step */
    float Pxx_p = kstate.Pxx + Q;
    float Pxy_p = kstate.Pxy;
    float Pxz_p = kstate.Pxz;
    float Pyx_p = kstate.Pyx;
    float Pyy_p = kstate.Pyy + Q;
    float Pyz_p = kstate.Pyz;
    float Pzx_p = kstate.Pzx;
    float Pzy_p = kstate.Pzy;
    float Pzz_p = kstate.Pzz + Q;

    /* Update step (no control input) */
    float Kx = Pxx_p / (Pxx_p + R);
    float Ky = Pyy_p / (Pyy_p + R);
    float Kz = Pzz_p / (Pzz_p + R);

    filtered.x = kstate.x + Kx * (raw.x - kstate.x);
    filtered.y = kstate.y + Ky * (raw.y - kstate.y);
    filtered.z = kstate.z + Kz * (raw.z - kstate.z);

    /* Update covariance */
    kstate.Pxx = (1.0f - Kx) * Pxx_p;
    kstate.Pxy = (1.0f - Kx) * Pxy_p;
    kstate.Pxz = (1.0f - Kx) * Pxz_p;
    kstate.Pyx = (1.0f - Ky) * Pyx_p;
    kstate.Pyy = (1.0f - Ky) * Pyy_p;
    kstate.Pyz = (1.0f - Ky) * Pyz_p;
    kstate.Pzx = (1.0f - Kz) * Pzx_p;
    kstate.Pzy = (1.0f - Kz) * Pzy_p;
    kstate.Pzz = (1.0f - Kz) * Pzz_p;

    kstate.x = filtered.x;
    kstate.y = filtered.y;
    kstate.z = filtered.z;

    return filtered;
}

/* ------------------------------------------------------------------ */
static void print_accelerometer(AccelData d)
{
    printf("X: %+.2f g  Y: %+.2f g  Z: %+.2f g\n", d.x, d.y, d.z);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI bus */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADXL335 via MCP3008 on Raspberry Pi 4 Model B\n");
    printf("SPI channel %d, %d Hz, %d channels\n",
           SPI_CHANNEL, SPI_BAUD, ADC_CHANNELS);
    printf("Press Ctrl+C to exit.\n\n");

    /* Main loop */
    while (!terminate) {
        AccelData raw = read_accelerometer();

        /* Check for SPI errors (ADC reads returned -1) */
        if (raw.x < 0.0f || raw.y < 0.0f || raw.z < 0.0f) {
            fprintf(stderr, "ADC read error — sensor absent or bus fault\n");
            break;
        }

        AccelData g = {
            .x = convert_to_g((int)raw.x),
            .y = convert_to_g((int)raw.y),
            .z = convert_to_g((int)raw.z)
        };

        AccelData filtered = kalman_filter(g);
        print_accelerometer(filtered);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    printf("\nProgram terminated.\n");
    return EXIT_SUCCESS;
}

