#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

/* DRV5055VA Hall-effect sensor digital output mapping to BCM GPIO pins */
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

/* Magnetic field strength range in millitesla */
#define MIN_MILLITESLA -100.0f
#define MAX_MILLITESLA 100.0f

/* Sampling interval in milliseconds */
#define SAMPLE_INTERVAL_MS 100

/* Log file path */
#define LOG_FILE "magnetic_log.txt"

/* Global flag for graceful shutdown */
static volatile sig_atomic_t program_running = 1;

/* Signal handler for SIGINT (Ctrl-C) */
static void signal_handler(int signum) {
    (void)signum;
    program_running = 0;
}

/*
 * Reads the digital state of a GPIO pin.
 * Returns 0 or 1 on success, -1 on error.
 */
static int read_gpio(int gpio_pin) {
    char command[128];
    char result[16];
    FILE *fp;

    snprintf(command, sizeof(command),
             "cat /sys/class/gpio/gpio%d/value 2>/dev/null", gpio_pin);

    fp = popen(command, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening pipe for GPIO %d: %s\n",
                gpio_pin, strerror(errno));
        return -1;
    }

    if (fgets(result, sizeof(result), fp) == NULL) {
        fprintf(stderr, "Error reading GPIO %d value: %s\n",
                gpio_pin, strerror(errno));
        pclose(fp);
        return -1;
    }

    pclose(fp);

    /* Strip trailing newline */
    result[strcspn(result, "\r\n")] = '\0';

    return atoi(result);
}

/*
 * Converts a digital sensor reading to a magnetic field strength in mT.
 * HIGH (1) -> 3.3 V -> +100 mT, LOW (0) -> 0.0 V -> -100 mT.
 */
static float convert_to_millitesla(int sensor_value) {
    return (sensor_value == 1) ? MAX_MILLITESLA : MIN_MILLITESLA;
}

/*
 * Logs the magnetic field strengths to a file.
 * Returns 0 on success, -1 on error.
 */
static int log_data(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp;

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    int sensor1_value, sensor2_value, sensor3_value;
    float sensor1_mT, sensor2_mT, sensor3_mT;
    struct timespec sleep_time;

    /* Register signal handler for SIGINT */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error registering signal handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set up sleep interval */
    sleep_time.tv_sec = SAMPLE_INTERVAL_MS / 1000;
    sleep_time.tv_nsec = (SAMPLE_INTERVAL_MS % 1000) * 1000000L;

    printf("Starting magnetic field monitoring on Raspberry Pi 3 Model B+...\n");
    printf("Sensors: GPIO%d, GPIO%d, GPIO%d\n", SENSOR1_GPIO, SENSOR2_GPIO, SENSOR3_GPIO);
    printf("Logging to: %s\n", LOG_FILE);
    printf("Press Ctrl-C to stop.\n\n");

    while (program_running) {
        /* Read sensor values */
        sensor1_value = read_gpio(SENSOR1_GPIO);
        sensor2_value = read_gpio(SENSOR2_GPIO);
        sensor3_value = read_gpio(SENSOR3_GPIO);

        /* Check for read errors */
        if (sensor1_value < 0 || sensor2_value < 0 || sensor3_value < 0) {
            fprintf(stderr, "Error reading sensor values. Skipping logging.\n");
            nanosleep(&sleep_time, NULL);
            continue;
        }

        /* Convert sensor values to magnetic field strengths */
        sensor1_mT = convert_to_millitesla(sensor1_value);
        sensor2_mT = convert_to_millitesla(sensor2_value);
        sensor3_mT = convert_to_millitesla(sensor3_value);

        /* Log the data */
        if (log_data(sensor1_mT, sensor2_mT, sensor3_mT) != 0) {
            fprintf(stderr, "Error logging data. Continuing...\n");
        }

        /* Check for out-of-range values */
        if (sensor1_mT < MIN_MILLITESLA || sensor1_mT > MAX_MILLITESLA ||
            sensor2_mT < MIN_MILLITESLA || sensor2_mT > MAX_MILLITESLA ||
            sensor3_mT < MIN_MILLITESLA || sensor3_mT > MAX_MILLITESLA) {
            fprintf(stderr,
                    "Warning: Magnetic field out of range! "
                    "sensor1=%.2f mT, sensor2=%.2f mT, sensor3=%.2f mT\n",
                    sensor1_mT, sensor2_mT, sensor3_mT);
        }

        /* Sleep for the specified interval */
        nanosleep(&sleep_time, NULL);
    }

    printf("\nExiting gracefully...\n");
    return EXIT_SUCCESS;
}

