#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    500000
#define SPI_MODE        0
#define SPI_BITS        8

#define PUMP_GPIO       17
#define MOISTURE_THRESHOLD 30
#define SAMPLE_INTERVAL_S 60
#define LOG_FILE        "watering.log"

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static int g_pump_state = 0;

static void log_event(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(log)");
        return;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[unknown time] %s\n", message);
    }
    fclose(fp);
}

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open(SPI_DEVICE)");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }

    return fd;
}

static int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        log_event("Invalid MCP3008 channel requested");
        return -1;
    }

    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

static int map_adc_to_moisture(int adc_value) {
    if (adc_value < 0) return -1;
    if (adc_value < 200) return 100;
    if (adc_value > 800) return 0;
    return 100 - ((adc_value - 200) * 100 / 600);
}

static int control_pump(int state) {
    if (gpioWrite(PUMP_GPIO, state) < 0) {
        log_event("Failed to write PUMP_GPIO");
        return -1;
    }
    g_pump_state = state;
    return 0;
}

static void cleanup(void) {
    if (g_pump_state) {
        control_pump(0);
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(PUMP_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set PUMP_GPIO mode\n");
        gpioTerminate();
        return 1;
    }
    if (control_pump(0) < 0) {
        gpioTerminate();
        return 1;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        gpioTerminate();
        return 1;
    }

    log_event("Program started");

    while (g_running) {
        int adc_value = read_mcp3008(g_spi_fd, 0);
        if (adc_value < 0) {
            log_event("Error reading ADC value");
        } else {
            int moisture = map_adc_to_moisture(adc_value);
            char msg[128];
            snprintf(msg, sizeof(msg), "Moisture level: %d%% (ADC: %d)", moisture, adc_value);
            log_event(msg);

            if (moisture < MOISTURE_THRESHOLD && g_pump_state == 0) {
                if (control_pump(1) == 0) {
                    log_event("Pump turned ON");
                }
            } else if (moisture >= MOISTURE_THRESHOLD && g_pump_state == 1) {
                if (control_pump(0) == 0) {
                    log_event("Pump turned OFF");
                }
            }
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    log_event("Program terminated");
    cleanup();
    return 0;
}

