#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <stdbool.h>
#include <pigpio.h>
#include <cjson/cJSON.h>
#include <mosquitto.h>

#define MQTT_HOST "mqtt.eclipseprojects.io"
#define MQTT_PORT 1883
#define MQTT_TOPIC "home/led_control"
#define MQTT_CLIENT_ID "rpi_led_control"
#define LED_GPIO 17
#define MAX_RECONNECT_DELAY 60
#define INITIAL_RECONNECT_DELAY 1

static struct mosquitto *mosq = NULL;
static volatile sig_atomic_t running = 1;
static int reconnect_delay = INITIAL_RECONNECT_DELAY;

static void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] %s\n", timestamp, message);
}

static void on_connect(struct mosquitto *m, void *userdata, int result) {
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        log_message("Connected to MQTT broker.");
        int rc = mosquitto_subscribe(m, NULL, MQTT_TOPIC, 0);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_message("Failed to subscribe to topic.");
        }
    } else {
        log_message("Connection failed.");
    }
}

static void on_disconnect(struct mosquitto *m, void *userdata, int rc) {
    (void)m;
    (void)userdata;
    if (rc != 0) {
        log_message("Unexpected disconnection.");
    }
}

static void on_message(struct mosquitto *m, void *userdata, const struct mosquitto_message *message) {
    (void)m;
    (void)userdata;

    if (message->payloadlen <= 0) {
        log_message("Empty message received.");
        return;
    }

    char *payload = (char *)message->payload;
    cJSON *json = cJSON_Parse(payload);
    if (!json) {
        log_message("JSON parsing failed.");
        return;
    }

    cJSON *led_state = cJSON_GetObjectItemCaseSensitive(json, "led_state");
    if (!cJSON_IsBool(led_state)) {
        log_message("Invalid or missing 'led_state' key.");
        cJSON_Delete(json);
        return;
    }

    if (cJSON_GetArraySize(json) != 1) {
        log_message("Unexpected JSON keys.");
        cJSON_Delete(json);
        return;
    }

    if (led_state->valueint) {
        if (gpioWrite(LED_GPIO, 1) != 0) {
            log_message("Failed to turn LED on.");
        } else {
            log_message("LED turned ON.");
        }
    } else {
        if (gpioWrite(LED_GPIO, 0) != 0) {
            log_message("Failed to turn LED off.");
        } else {
            log_message("LED turned OFF.");
        }
    }

    cJSON_Delete(json);
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int setup_gpio(void) {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed.");
        return -1;
    }
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        log_message("Failed to set GPIO mode.");
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(LED_GPIO, 0) != 0) {
        log_message("Failed to initialize LED state.");
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int setup_mqtt(void) {
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        log_message("Failed to create MQTT client.");
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_connect_callback_set(mosq, on_connect);
    mosquitto_disconnect_callback_set(mosq, on_disconnect);
    mosquitto_message_callback_set(mosq, on_message);

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        log_message("Failed to connect to MQTT broker.");
        mosquitto_destroy(mosq);
        mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (mosq) {
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
    }
    mosquitto_lib_cleanup();
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (setup_gpio() != 0) {
        return EXIT_FAILURE;
    }

    if (setup_mqtt() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int rc = mosquitto_loop(mosq, 1000, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            log_message("MQTT loop error. Attempting to reconnect...");
            sleep(reconnect_delay);
            reconnect_delay = (reconnect_delay * 2 > MAX_RECONNECT_DELAY) ? MAX_RECONNECT_DELAY : reconnect_delay * 2;
            rc = mosquitto_reconnect(mosq);
            if (rc != MOSQ_ERR_SUCCESS) {
                log_message("Reconnect failed.");
            } else {
                reconnect_delay = INITIAL_RECONNECT_DELAY;
            }
        } else {
            reconnect_delay = INITIAL_RECONNECT_DELAY;
        }
    }

    log_message("Shutting down...");
    cleanup();
    return EXIT_SUCCESS;
}

