/*
 * KY-038 Sound Sensor Alarm Monitor
 * Board:  Raspberry Pi 4 Model B
 * Library: libgpiod (modern Linux GPIO character-device API)
 *
 * Wiring:
 *   KY-038 VCC  -> 3.3 V (Pin 1)
 *   KY-038 GND  -> GND   (Pin 9)
 *   KY-038 DO   -> GPIO17 (Pin 11, BCM 17)
 *   Alarm LED   -> GPIO18 (Pin 12, BCM 18) via 330 Ω resistor
 *
 * Behavior:
 *   - Polls the DO pin every 100 ms.
 *   - When DO reads LOW (sound exceeds threshold), lights the alarm LED
 *     for 1 s, then turns it off.
 *   - Handles SIGINT / SIGTERM for clean shutdown.
 *   - On any GPIO error, prints a message and exits.
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <gpiod.h>

#define SOUND_SENSOR_PIN 17   /* BCM 17 */
#define ALARM_LED_PIN    18   /* BCM 18 */
#define POLL_DELAY_MS    100
#define ALARM_ON_MS      1000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *sound_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Pi 4) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    /* Get the sound sensor line (DO) */
    sound_line = gpiod_chip_get_line(chip, SOUND_SENSOR_PIN);
    if (sound_line == NULL) {
        perror("gpiod_chip_get_line(sound)");
        goto cleanup;
    }

    /* Get the alarm LED line */
    led_line = gpiod_chip_get_line(chip, ALARM_LED_PIN);
    if (led_line == NULL) {
        perror("gpiod_chip_get_line(led)");
        goto cleanup;
    }

    /* Request sound sensor line as input */
    if (gpiod_line_request_input(sound_line, "ky038-sound") < 0) {
        perror("gpiod_line_request_input(sound)");
        goto cleanup;
    }

    /* Request LED line as output, initial value LOW */
    if (gpiod_line_request_output(led_line, "ky038-alarm", 0) < 0) {
        perror("gpiod_line_request_output(led)");
        goto cleanup;
    }

    printf("KY-038 sound sensor monitoring started.\n");
    printf("  DO pin : BCM %d\n", SOUND_SENSOR_PIN);
    printf("  LED pin: BCM %d\n", ALARM_LED_PIN);
    printf("Press Ctrl-C to exit.\n");

    while (g_running) {
        int val = gpiod_line_get_value(sound_line);
        if (val < 0) {
            perror("gpiod_line_get_value(sound)");
            goto cleanup;
        }

        /* KY-038 DO goes LOW when sound exceeds the onboard threshold */
        if (val == 0) {
            printf("Sound detected! Activating alarm.\n");
            fflush(stdout);

            if (gpiod_line_set_value(led_line, 1) < 0) {
                perror("gpiod_line_set_value(led, 1)");
                goto cleanup;
            }

            /* Keep LED on for 1 s, checking for shutdown signal */
            for (int i = 0; i < ALARM_ON_MS / POLL_DELAY_MS && g_running; i++) {
                usleep(POLL_DELAY_MS * 1000);
            }

            if (gpiod_line_set_value(led_line, 0) < 0) {
                perror("gpiod_line_set_value(led, 0)");
                goto cleanup;
            }
        }

        /* Poll delay */
        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down cleanly.\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on every exit path */
    if (led_line != NULL) {
        gpiod_line_release(led_line);
    }
    if (sound_line != NULL) {
        gpiod_line_release(sound_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return ret;
}

