#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define GPIO_CHIP_NAME      "/dev/gpiochip0"
#define GPIO_LINE_OFFSET    17
#define LOG_FILE            "/var/log/vibration_shutdown.log"
#define CONSUMER_LABEL      "vibration-monitor"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s: %s\n", timestamp, message) < 0) {
        perror("fprintf");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose");
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    int chip_fd = open(GPIO_CHIP_NAME, O_RDWR);
    if (chip_fd < 0) {
        perror("open(" GPIO_CHIP_NAME ")");
        return EXIT_FAILURE;
    }

    struct gpio_line_request_config line_cfg;
    memset(&line_cfg, 0, sizeof(line_cfg));
    line_cfg.consumer_label = CONSUMER_LABEL;
    line_cfg.request_type   = GPIO_LINE_REQUEST_EVENT_FALLING_EDGE;
    line_cfg.flags          = 0;

    if (ioctl(chip_fd, GPIO_GET_LINE_IOCTL_NUM, &(unsigned int){GPIO_LINE_OFFSET}) < 0) {
        perror("ioctl(GPIO_GET_LINE_IOCTL_NUM)");
        close(chip_fd);
        return EXIT_FAILURE;
    }

    if (ioctl(chip_fd, GPIO_GET_LINE_HANDLE_IOCTL, &line_cfg) < 0) {
        perror("ioctl(GPIO_GET_LINE_HANDLE_IOCTL)");
        close(chip_fd);
        return EXIT_FAILURE;
    }

    printf("Monitoring SW-420 vibration sensor on GPIO%d (BCM). Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    while (program_running) {
        struct gpio_event_data event;
        ssize_t ret = read(chip_fd, &event, sizeof(event));

        if (ret < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("read(gpio_event)");
            break;
        }

        if (ret == 0) {
            continue;
        }

        if (event.event_type != GPIO_EVENT_FALLING_EDGE) {
            continue;
        }

        printf("Vibration detected! Shutting down...\n");

        if (log_event("Vibration detected! Shutting down...") != 0) {
            fprintf(stderr, "Failed to log event.\n");
        }

        int rc = system("sudo shutdown -h now");
        if (rc == -1) {
            perror("system(sudo shutdown)");
        }

        break;
    }

    if (close(chip_fd) != 0) {
        perror("close(chip_fd)");
    }

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

