 *
 * Build:
 *   gcc -O2 -Wall -o bmp280_alt bmp280_alt.c -lpigpio -lrt -lm
 * Run:
 *   sudo ./bmp280_alt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ---- BMP280 constants (datasheet rev 1.26) ---- */
#define BMP280_I2C_ADDR        0x76
#define BMP280_CHIP_ID_REG     0xD0
#define BMP280_CHIP_ID         0x58
#define BMP280_RESET_REG       0xE0
#define BMP280_RESET_CMD       0xB6
#define BMP280_CTRL_MEAS_REG   0xF4
#define BMP280_CTRL_HUMIDITY   0xF2
#define BMP280_CONFIG_REG      0xF5
#define BMP280_PRESS_MSB_REG   0xF7
#define BMP280_TEMP_MSB_REG    0xFA
#define BMP280_CALIB_START     0x88
#define BMP280_CALIB_LEN       24

/* Oversampling: x1 for both temp and pressure */
#define OVERSAMPLING_TEMP      1
#define OVERSAMPLING_PRESS     1

/* Filter: IIR filter off (bits = 0) */
#define FILTER_COEFF           0

/* Standby: 500 ms (bits = 010) */
#define STANDBY_TIME           0x02

/* ---- Globals for cleanup ---- */
static int           g_i2c_handle = -1;
static FILE         *g_log_file   = NULL;
static volatile sig_atomic_t g_terminate = 0;

/* ---- Calibration coefficients ---- */
typedef struct {
    uint16_t dig_T1;
    int16_t  dig_T2;
    int16_t  dig_T3;
    uint16_t dig_P1;
    int16_t  dig_P2;
    int16_t  dig_P3;
    int16_t  dig_P4;
    int16_t  dig_P5;
    int16_t  dig_P6;
    int16_t  dig_P7;
    int16_t  dig_P8;
    int16_t  dig_P9;
} bmp280_calib_t;

static bmp280_calib_t g_cal;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ---- Low-level I2C helpers ---- */
static int i2c_read_reg(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    if (i2cWriteByte(handle, reg) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(reg=0x%02X) failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%02X, len=%u) failed\n", reg, len);
        return -1;
    }
    return 0;
}

static int i2c_write_reg(int handle, uint8_t reg, uint8_t val)
{
    if (i2cWriteByteData(handle, reg, val) < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed\n", reg, val);
        return -1;
    }
    return 0;
}

/* ---- Read calibration coefficients ---- */
static int read_calibration(int handle)
{
    uint8_t buf[BMP280_CALIB_LEN];
    if (i2c_read_reg(handle, BMP280_CALIB_START, buf, sizeof(buf)) != 0)
        return -1;

    g_cal.dig_T1 = (uint16_t)(buf[0]  | (buf[1]  << 8));
    g_cal.dig_T2 = (int16_t)(buf[2]  | (buf[3]  << 8));
    g_cal.dig_T3 = (int16_t)(buf[4]  | (buf[5]  << 8));
    g_cal.dig_P1 = (uint16_t)(buf[6]  | (buf[7]  << 8));
    g_cal.dig_P2 = (int16_t)(buf[8]  | (buf[9]  << 8));
    g_cal.dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    g_cal.dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    g_cal.dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    g_cal.dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    g_cal.dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    g_cal.dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    g_cal.dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));

    return 0;
}

/* ---- Initialize BMP280 ---- */
static int init_bmp280(int handle)
{
    uint8_t chip_id = 0;

    /* Verify chip ID */
    if (i2c_read_reg(handle, BMP280_CHIP_ID_REG, &chip_id, 1) != 0) {
        fprintf(stderr, "[ERROR] Cannot read chip ID — sensor absent or bus error\n");
        return -1;
    }
    if (chip_id != BMP280_CHIP_ID) {
        fprintf(stderr, "[ERROR] Unexpected chip ID 0x%02X (expected 0x%02X)\n",
                chip_id, BMP280_CHIP_ID);
        return -1;
    }
    printf("[INFO] BMP280 detected (chip ID 0x%02X)\n", chip_id);

    /* Soft reset */
    if (i2c_write_reg(handle, BMP280_RESET_REG, BMP280_RESET_CMD) != 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    /* Read calibration */
    if (read_calibration(handle) != 0) {
        fprintf(stderr, "[ERROR] Failed to read calibration data\n");
        return -1;
    }

    /* Config: t_sb = 500 ms, filter off */
    uint8_t config = (STANDBY_TIME << 5) | (FILTER_COEFF << 2);
    if (i2c_write_reg(handle, BMP280_CONFIG_REG, config) != 0)
        return -1;

    /* Ctrl_meas: osrs_t=x1, osrs_p=x1, normal mode */
    uint8_t ctrl_meas = (OVERSAMPLING_TEMP << 5) |
                        (OVERSAMPLING_PRESS << 2) |
                        0x03;
    if (i2c_write_reg(handle, BMP280_CTRL_MEAS_REG, ctrl_meas) != 0)
        return -1;

    return 0;
}

/* ---- Read raw temperature and pressure ---- */
static int read_raw(int handle, int32_t *raw_t, int32_t *raw_p)
{
    uint8_t buf[6];
    if (i2c_read_reg(handle, BMP280_PRESS_MSB_REG, buf, 6) != 0)
        return -1;

    *raw_p = ((int32_t)buf[0] << 12) | ((int32_t)buf[1] << 4) | (buf[2] >> 4);
    *raw_t = ((int32_t)buf[3] << 12) | ((int32_t)buf[4] << 4) | (buf[5] >> 4);
    return 0;
}

/* ---- Compensation (datasheet rev 1.26) ---- */
static double compensate_temperature(int32_t raw_t, double *t_fine_out)
{
    double v1 = ((double)raw_t / 16384.0 - (double)g_cal.dig_T1 / 1024.0) * g_cal.dig_T2;
    double v2 = ((double)raw_t / 131072.0 - (double)g_cal.dig_T1 / 8192.0) *
                ((double)raw_t / 131072.0 - (double)g_cal.dig_T1 / 8192.0) * g_cal.dig_T3;
    double t_fine = v1 + v2;
    if (t_fine_out)
        *t_fine_out = t_fine;
    return t_fine / 5120.0;
}

static double compensate_pressure(int32_t raw_p, double t_fine)
{
    double v1 = t_fine / 2.0 - 64000.0;
    double v2 = v1 * v1 * g_cal.dig_P6 / 32768.0;
    v2 = v2 + v1 * g_cal.dig_P5 * 2.0;
    v2 = v2 / 4.0 + g_cal.dig_P4 * 65536.0;
    v1 = (g_cal.dig_P3 * v1 * v1 / 524288.0 + g_cal.dig_P2 * v1) / 524288.0;
    v1 = (1.0 + v1 / 32768.0) * g_cal.dig_P1;
    if (v1 == 0.0)
        return 0.0;

    double p = 1048576.0 - (double)raw_p;
    p = (p - v2 / 4096.0) * 6250.0 / v1;
    v1 = g_cal.dig_P9 * p * p / 2147483648.0;
    v2 = p * g_cal.dig_P8 / 32768.0;
    p = p + (v1 + v2 + g_cal.dig_P7) / 16.0;
    return p;
}

static double calculate_altitude(double pressure_pa)
{
    return 44330.0 * (1.0 - pow(pressure_pa / 101325.0, 0.1903));
}

/* ---- Logging ---- */
static int log_data(FILE *fp, double altitude, const char *timestamp)
{
    if (fprintf(fp, "%s,%.2f\n", timestamp, altitude) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed\n");
        return -1;
    }
    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at BMP280 address */
    g_i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (init_bmp280(g_i2c_handle) != 0) {
        fprintf(stderr, "[ERROR] BMP280 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("altitude_log.txt", "a");
    if (!g_log_file) {
        fprintf(stderr, "[ERROR] Cannot open altitude_log.txt for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Logging altitude every 5 s. Press Ctrl-C to stop.\n");

    while (!g_terminate) {
        int32_t raw_t = 0, raw_p = 0;

        if (read_raw(g_i2c_handle, &raw_t, &raw_p) != 0) {
            fprintf(stderr, "[WARN] Read failed — skipping cycle\n");
            sleep(5);
            continue;
        }

        double t_fine = 0.0;
        double temp_c = compensate_temperature(raw_t, &t_fine);
        double press_pa = compensate_pressure(raw_p, t_fine);
        double altitude = calculate_altitude(press_pa);

        time_t now = time(NULL);
        struct tm tm_info;
        char ts[32];
        if (localtime_r(&now, &tm_info) &&
            strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S%z", &tm_info) > 0) {
            if (log_data(g_log_file, altitude, ts) != 0)
                fprintf(stderr, "[WARN] Logging failed for this sample\n");
        } else {
            fprintf(stderr, "[WARN] Timestamp formatting failed\n");
        }

        printf("%s  T=%.2f C  P=%.2f hPa  Alt=%.2f m\n",
               ts, temp_c, press_pa / 100.0, altitude);

        sleep(5);
    }

    printf("\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

