/*
 * Raspberry Pi Zero W - TMP36 Temperature Sensor -> MCP4725 DAC
 *
 * Hardware:
 *   - TMP36 analog temperature sensor -> MCP3008 ADC channel 0
 *   - MCP3008 SPI ADC on /dev/spidev0.0 (CE0, 500 kHz, mode 0)
 *   - MCP4725 DAC on I2C bus 1 (address 0x62)
 *
 * Build: gcc -o temp_dac temp_dac.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <linux/i2c-dev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define I2C_DEVICE      "/dev/i2c-1"
#define MCP4725_ADDR    0x62
#define MCP4725_WRITE   0x40
#define VREF            3.3f
#define ADC_MAX         1023.0f
#define TEMP_OFFSET     0.0f
#define TEMP_SCALE      100.0f
#define DAC_VREF        3.3f
#define DAC_MAX         4095
#define LOG_FILE        "temperature_log.txt"
#define SAMPLE_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl SPI_IOC_WR_MODE");
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl SPI_IOC_WR_BITS_PER_WORD");
        close(spi_fd); spi_fd = -1; return -1;
    }

    uint32_t speed = 500000;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl SPI_IOC_WR_MAX_SPEED_HZ");
        close(spi_fd); spi_fd = -1; return -1;
    }

    return 0;
}

static int i2c_init(void) {
    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MCP4725_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd); i2c_fd = -1; return -1;
    }

    return 0;
}

static int read_mcp3008(uint8_t channel) {
    if (channel > 7) return -1;

    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = 3,
        .speed_hz = 500000,
        .bits_per_word = 8,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI_IOC_MESSAGE");
        return -1;
    }

    return ((rx[1] & 0x03) << 8) | rx[2];
}

static int write_mcp4725(uint16_t value) {
    if (value > 4095) return -1;

    uint8_t buf[2] = { (uint8_t)(MCP4725_WRITE | ((value >> 8) & 0x0F)), (uint8_t)(value & 0xFF) };

    if (write(i2c_fd, buf, 2) != 2) {
        perror("I2C write");
        return -1;
    }
    return 0;
}

static float adc_to_celsius(int adc) {
    float v = (adc / ADC_MAX) * VREF;
    return (v - 0.5f) * 100.0f;
}

static int celsius_to_dac_code(float celsius) {
    float v = (celsius / TEMP_SCALE) * VREF;
    if (v < 0.0f) v = 0.0f;
    if (v > VREF) v = VREF;
    return (int)((v / VREF) * DAC_MAX);
}

static void log_data(int adc, float temp, float dac_voltage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_fp, "%s, ADC: %d, Temp: %.2f C, DAC: %.3f V\n", ts, adc, temp, dac_voltage);
    fflush(log_fp);
    printf("%s, ADC: %d, Temp: %.2f C, DAC: %.3f V\n", ts, adc, temp, dac_voltage);
}

static void cleanup(void) {
    if (spi_fd >= 0) { close(spi_fd); spi_fd = -1; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
    if (log_fp) { fclose(log_fp); log_fp = NULL; }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (spi_init() < 0) { cleanup(); return 1; }
    if (i2c_init() < 0) { cleanup(); return 1; }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log file");
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        float temp = adc_to_celsius(adc);
        int dac_code = celsius_to_dac_code(temp);
        float dac_voltage = (dac_code / (float)DAC_MAX) * DAC_VREF;

        if (write_mcp4725((uint16_t)dac_code) < 0) {
            fprintf(stderr, "Error writing to DAC, retrying...\n");
        }

        log_data(adc, temp, dac_voltage);
        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

