static void log_data(int adc, float temp, float dac_voltage) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_fp, "%s, ADC: %d, Temp: %.2f C, DAC: %.3f V\n", ts, adc, temp, dac_voltage);
    fflush(log_fp);
    printf("%s, ADC: %d, Temp: %.2f C, DAC: %.3f V\n", ts, adc, temp, dac_voltage);
}

static void cleanup(void) {
    if (spi_fd >= 0) { close(spi_fd); spi_fd = -1; }
    if (i2c_fd >= 0) { close(i2c_fd); i2c_fd = -1; }
    if (log_fp) { fclose(log_fp); log_fp = NULL; }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    if (spi_init() < 0) { cleanup(); return 1; }
    if (i2c_init() < 0) { cleanup(); return 1; }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen log file");
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int adc = read_mcp3008(0);
        if (adc < 0) {
            fprintf(stderr, "Error reading ADC, retrying...\n");
            usleep(SAMPLE_DELAY_US);
            continue;
        }

        float temp = adc_to_celsius(adc);
        int dac_code = celsius_to_dac_code(temp);
        float dac_voltage = (dac_code / (float)DAC_MAX) * DAC_VREF;

        if (write_mcp4725((uint16_t)dac_code) < 0) {
            fprintf(stderr, "Error writing to DAC, retrying...\n");
        }

        log_data(adc, temp, dac_voltage);
        usleep(SAMPLE_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

