#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MCP3008 SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* mode 0, active-low CE */

/* Sensor channel assignments */
#define SENSOR1_CHANNEL 0
#define SENSOR2_CHANNEL 1
#define SENSOR3_CHANNEL 2

/* Sampling interval */
#define SAMPLE_INTERVAL_SEC 60

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a single-ended channel from the MCP3008                        */
/* Returns 0–1023 on success, -1 on error.                             */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read sequence (3 bytes):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 are in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "Error: spiXfer failed on channel %d (ret=%d)\n",
                channel, ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the log file                        */
/* ------------------------------------------------------------------ */
static void log_reading(int sensor_id, int adc_value)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s,Sensor%d,%d\n",
                timestamp, sensor_id, adc_value) < 0) {
        fprintf(stderr, "Error: writing to log file failed\n");
    }
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Open SPI bus */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Open log file in append mode */
    log_file = fopen("soil_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open soil_data.txt for appending\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (!terminate) {
        int v1 = read_mcp3008(SENSOR1_CHANNEL);
        int v2 = read_mcp3008(SENSOR2_CHANNEL);
        int v3 = read_mcp3008(SENSOR3_CHANNEL);

        if (v1 >= 0) log_reading(1, v1);
        if (v2 >= 0) log_reading(2, v2);
        if (v3 >= 0) log_reading(3, v3);

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_SEC && !terminate; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

