/*
 * Light sequencer for Raspberry Pi 3 Model B+
 * Four Songle SRD-05VDC-SL relay modules on BCM pins 17, 22, 23, 24.
 * Relays are assumed to be active-high (active = HIGH).
 *
 * Build:  gcc -O2 -Wall -Wextra -o light_seq light_seq.c -lgpiod
 * Run:    sudo ./light_seq   (or ensure user is in the 'gpio' group)
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_RELAYS 4
static const unsigned int relay_pins[NUM_RELAYS] = {17, 22, 23, 24};

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly.            */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Deactivate all relays and release the chip.                         */
/* ------------------------------------------------------------------ */
static void cleanup(struct gpiod_chip *chip, struct gpiod_line *lines[],
                    int num_lines)
{
    for (int i = 0; i < num_lines; i++) {
        if (lines[i]) {
            (void)gpiod_line_set_value(lines[i], 0);   /* best-effort */
            gpiod_line_release(lines[i]);
            lines[i] = NULL;
        }
    }
    if (chip)
        gpiod_chip_close(chip);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS] = {NULL};
    int rc = EXIT_FAILURE;

    /* ---- Install signal handlers for clean shutdown ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Open the default gpiochip (gpiochip0 on Pi 3 B+) ---- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    /* ---- Acquire and configure each relay line ---- */
    for (int i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (!lines[i]) {
            fprintf(stderr, "gpiod_chip_get_line failed for BCM %u\n",
                    relay_pins[i]);
            cleanup(chip, lines, i);
            return EXIT_FAILURE;
        }

        if (gpiod_line_request_output(lines[i], "light_seq", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for BCM %u\n",
                    relay_pins[i]);
            cleanup(chip, lines, i);
            return EXIT_FAILURE;
        }
    }

    printf("Light sequencer started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- Main loop: activate one relay, wait, deactivate ---- */
    while (g_running) {
        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            if (gpiod_line_set_value(lines[i], 1) < 0) {
                fprintf(stderr, "Failed to activate relay %d (BCM %u)\n",
                        i + 1, relay_pins[i]);
                cleanup(chip, lines, NUM_RELAYS);
                return EXIT_FAILURE;
            }
            printf("Relay %d (BCM %u) ON\n", i + 1, relay_pins[i]);
            fflush(stdout);

            sleep(1);
            if (!g_running)
                break;

            if (gpiod_line_set_value(lines[i], 0) < 0) {
                fprintf(stderr, "Failed to deactivate relay %d (BCM %u)\n",
                        i + 1, relay_pins[i]);
                cleanup(chip, lines, NUM_RELAYS);
                return EXIT_FAILURE;
            }
            printf("Relay %d (BCM %u) OFF\n", i + 1, relay_pins[i]);
            fflush(stdout);

            sleep(1);
        }
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup(chip, lines, NUM_RELAYS);
    rc = EXIT_SUCCESS;
    return rc;
}

