#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ADC_PIN        26          /* BCM GPIO26 - physical pin 37 */
#define LED_PIN        16          /* BCM GPIO16 - physical pin 36 */
#define DEBOUNCE_US    50000       /* 50 ms debounce window          */
#define LED_ON_US      500000      /* 500 ms LED on-time             */
#define SAMPLE_US      100         /* 100 us between samples         */
#define THRESHOLD      100         /* ADC threshold for clap         */
#define SAMPLES        100         /* Samples per ADC read           */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read 10-bit ADC value on BCM GPIO26 via bit-banging                 */
/* Returns 0-1023 on success, -1 on error.                             */
/* ------------------------------------------------------------------ */
static int read_adc(void)
{
    int value = 0;

    for (int i = 0; i < SAMPLES; i++) {
        if (gpioWrite(ADC_PIN, 1) < 0) {
            fprintf(stderr, "Error: failed to set ADC pin high\n");
            return -1;
        }
        gpioDelay(SAMPLE_US);

        int bit = gpioRead(ADC_PIN);
        if (bit < 0) {
            fprintf(stderr, "Error: failed to read ADC pin\n");
            return -1;
        }

        value = (value << 1) | bit;

        if (gpioWrite(ADC_PIN, 0) < 0) {
            fprintf(stderr, "Error: failed to set ADC pin low\n");
            return -1;
        }
        gpioDelay(SAMPLE_US);
    }

    return value;
}

/* ------------------------------------------------------------------ */
/* Detect a clap: ADC value exceeds threshold for DEBOUNCE_US         */
/* ------------------------------------------------------------------ */
static bool detect_clap(int adc_value)
{
    static uint32_t last_trigger_tick = 0;
    uint32_t now = gpioTick();

    if (adc_value > THRESHOLD) {
        if ((now - last_trigger_tick) > DEBOUNCE_US) {
            last_trigger_tick = now;
            return true;
        }
    }
    return false;
}

/* ------------------------------------------------------------------ */
/* Activate LED for LED_ON_US                                          */
/* ------------------------------------------------------------------ */
static void activate_led(void)
{
    if (gpioWrite(LED_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to turn on LED\n");
        return;
    }
    gpioDelay(LED_ON_US);
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to turn off LED\n");
    }
}

/* ------------------------------------------------------------------ */
/* Print timestamped detection message                                 */
/* ------------------------------------------------------------------ */
static void log_detection(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
        printf("[%s] Clap detected!\n", timestamp);
        fflush(stdout);
    } else {
        printf("[unknown] Clap detected!\n");
        fflush(stdout);
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure ADC pin as input */
    if (gpioSetMode(ADC_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set ADC pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED pin as output and ensure it is off */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize LED state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler\n");
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Clap detector running. Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main loop */
    while (g_running) {
        int adc_value = read_adc();
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error - continuing\n");
            gpioDelay(100000); /* 100 ms backoff on error */
            continue;
        }

        if (detect_clap(adc_value)) {
            activate_led();
            log_detection();
        }

        gpioDelay(10000); /* 10 ms loop delay */
    }

    /* Cleanup */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

