#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define GPIO_PIN 17
#define DISTANCE_THRESHOLD 200
#define LOG_FILE "distance_log.txt"
#define GPIO_PATH "/sys/class/gpio"
#define GPIO_EXPORT_PATH GPIO_PATH "/export"
#define GPIO_UNEXPORT_PATH GPIO_PATH "/unexport"
#define GPIO_VALUE_PATH GPIO_PATH "/gpio%d/value"
#define GPIO_DIRECTION_PATH GPIO_PATH "/gpio%d/direction"
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_to_file(const char *path, const char *value) {
    FILE *fp = fopen(path, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%s", value) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_from_file(const char *path, char *buffer, size_t buf_size) {
    FILE *fp = fopen(path, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (!fgets(buffer, (int)buf_size, fp)) {
        fprintf(stderr, "Error reading from %s: %s\n", path, strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", path, strerror(errno));
        return -1;
    }
    return 0;
}

static int export_gpio(int pin) {
    char pin_str[4];
    snprintf(pin_str, sizeof(pin_str), "%d", pin);
    if (write_to_file(GPIO_EXPORT_PATH, pin_str) != 0) {
        return -1;
    }
    usleep(100000);
    return 0;
}

static int unexport_gpio(int pin) {
    char pin_str[4];
    snprintf(pin_str, sizeof(pin_str), "%d", pin);
    return write_to_file(GPIO_UNEXPORT_PATH, pin_str);
}

static int set_gpio_direction(int pin, const char *direction) {
    char path[64];
    snprintf(path, sizeof(path), GPIO_DIRECTION_PATH, pin);
    return write_to_file(path, direction);
}

static int read_gpio_value(int pin, int *value) {
    char path[64];
    char buffer[4];
    snprintf(path, sizeof(path), GPIO_VALUE_PATH, pin);
    if (read_from_file(path, buffer, sizeof(buffer)) != 0) {
        return -1;
    }
    if (strcmp(buffer, "0\n") == 0) {
        *value = 0;
    } else if (strcmp(buffer, "1\n") == 0) {
        *value = 1;
    } else {
        fprintf(stderr, "Unexpected GPIO value: %s", buffer);
        return -1;
    }
    return 0;
}

static int log_distance(int distance) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm;
    if (!localtime_r(&t, &tm)) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Distance: %d mm\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, distance);
    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    if (export_gpio(GPIO_PIN) != 0) {
        fprintf(stderr, "Failed to export GPIO%d\n", GPIO_PIN);
        return 1;
    }

    if (set_gpio_direction(GPIO_PIN, "in") != 0) {
        fprintf(stderr, "Failed to set GPIO%d direction\n", GPIO_PIN);
        unexport_gpio(GPIO_PIN);
        return 1;
    }

    printf("Monitoring distance on GPIO%d... (Ctrl+C to exit)\n", GPIO_PIN);

    while (running) {
        int value;
        if (read_gpio_value(GPIO_PIN, &value) != 0) {
            fprintf(stderr, "Error reading GPIO%d value, retrying in %d second(s)...\n",
                    GPIO_PIN, POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int distance = value * 100;

        if (log_distance(distance) != 0) {
            fprintf(stderr, "Error logging distance\n");
        }

        if (distance < DISTANCE_THRESHOLD) {
            printf("Feeder Activated\n");
        } else {
            printf("Feeder Idle\n");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nCleaning up and exiting...\n");
    unexport_gpio(GPIO_PIN);
    return 0;
}

