}

static int spi_init(int *fd)
{
    *fd = open(SPI_DEVICE, O_RDWR);
    if (*fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(*fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(*fd);
        *fd = -1;
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(*fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(*fd);
        *fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(*fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(*fd);
        *fd = -1;
        return -1;
    }

    return 0;
}

static int mcp3008_read(int spi_fd, uint8_t channel, uint16_t *out)
{
    if (channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %u\n", channel);
        return -1;
    }

    /* MCP3008 single-ended read: start bit, SGL/DIFF=1, D2 D1 D0 */
    uint8_t tx[3] = {
        0x01,
        (uint8_t)((0x08 | channel) << 4),
        0x00
    };
    uint8_t rx[3] = {0};

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = 3;
