{
    int spi_fd = -1;
    FILE *log_fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *cs_line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        goto cleanup;
    }

    /* Open log file */
    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    /* Open SPI */
    if (spi_init(&spi_fd) != 0) {
        goto cleanup;
    }

    /* Open gpiochip0 and request CS/SHDN line (GPIO8, BCM) as output, idle high */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        goto cleanup;
    }
    cs_line = gpiod_chip_get_line(chip, 8);
    if (!cs_line) {
        perror("gpiod_chip_get_line(8)");
        goto cleanup;
    }
    if (gpiod_line_request_output(cs_line, "drv5055-mcp3008", 1) < 0) {
        perror("gpiod_line_request_output");
        goto cleanup;
    }

    printf("DRV5055-A1 magnetic field logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        uint16_t adc_value = 0;

        /* Assert CS (active low) */
        if (gpiod_line_set_value(cs_line, 0) < 0) {
            perror("gpiod_line_set_value(0)");
            break;
        }

        if (mcp3008_read(spi_fd, MCP3008_CHANNEL, &adc_value) != 0) {
            fprintf(stderr, "ADC read failed; skipping sample.\n");
            gpiod_line_set_value(cs_line, 1);
            usleep(SAMPLE_DELAY_MS * 1000);
            continue;
        }

        /* Deassert CS */
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("gpiod_line_set_value(1)");
            break;
        }

        float magnetic_field = adc_to_magnetic_field(adc_value);
        time_t epoch = time(NULL);

        printf("Magnetic Field: %.2f mT\n", magnetic_field);

        if (log_data(log_fp, epoch, magnetic_field) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        usleep(SAMPLE_DELAY_MS * 1000);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (cs_line) {
        gpiod_line_release(cs_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
    if (log_fp) {
        fclose(log_fp);
    }
    return ret;
}

