#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/*
 * Raspberry Pi Zero W – DRV5055VA Hall-effect sensor via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> 3.3 V (Pin 1)
 *   MCP3008 VREF -> 3.3 V (Pin 1)
 *   MCP3008 AGND -> GND
 *   MCP3008 DGND -> GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> DRV5055VA analog output
 *   LED + 330 Ω  -> BCM GPIO21 -> GND
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o hall_sensor hall_sensor.c -lpigpio -lrt
 * Run:
 *   sudo ./hall_sensor
 */

#define SPI_CHANNEL    0          /* SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* Mode 0, active-low CE */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define LED_PIN        21         /* BCM GPIO21 */
#define THRESHOLD_MT   10.0       /* Magnetic field threshold in mT */
#define LOG_FILE       "magnetic_log.txt"
#define SAMPLE_US      100000     /* 100 ms */
#define ADC_MAX        1023       /* 10-bit ADC */
#define VREF           3.3        /* MCP3008 reference voltage */

static volatile sig_atomic_t g_running = 1;
static int g_spi_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler – set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read one sample from the MCP3008 (single-ended, 10-bit)             */
/* Returns 0–1023 on success, -1 on error.                             */
/* ------------------------------------------------------------------ */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (3 bytes):
     *   Byte 0: 0x01                       (start bit)
     *   Byte 1: (0x08 | channel) << 4      (single-ended + channel)
     *   Byte 2: 0x00                       (clock out remaining bits)
     *
     * Response:
     *   rx[0] – ignored
     *   rx[1] – bits 9..2 in lower nibble
     *   rx[2] – bits 1..0 in upper nibble
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(g_spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return adc_value;
}

/* ------------------------------------------------------------------ */
/* Convert ADC count to magnetic field strength (mT)                   */
/* ------------------------------------------------------------------ */
static float adc_to_magnetic_field(int adc_value)
{
    /*
     * DRV5055VA outputs a voltage proportional to the magnetic field.
     * A simple linear approximation:  V_out = 0.5 + 0.01 * B (mT).
     * Solve for B:  B = (V_out - 0.5) / 0.01.
     */
    float voltage = (float)adc_value * VREF / (float)ADC_MAX;
    return (voltage - 0.5f) / 0.01f;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the log file                        */
/* ------------------------------------------------------------------ */
static int log_data(float magnetic_field)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r failed");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %.2f mT\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, magnetic_field);

    if (fclose(fp) != 0) {
        perror("Error closing log file");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Control the LED based on the magnetic field threshold               */
/* ------------------------------------------------------------------ */
static void control_led(float magnetic_field)
{
    if (magnetic_field > THRESHOLD_MT) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup – release all resources                                    */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pin */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* Open SPI0 CE0 at 1 MHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle %d)\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM) failed");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Hall-effect sensor monitoring started.\n");
    printf("SPI channel %d, ADC channel %d, threshold %.1f mT, LED on GPIO %d.\n",
           SPI_CHANNEL, ADC_CHANNEL, THRESHOLD_MT, LED_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* Main sampling loop */
    while (g_running) {
        int adc_value = read_mcp3008(ADC_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "ADC read error – skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float magnetic_field = adc_to_magnetic_field(adc_value);

        if (log_data(magnetic_field) != 0) {
            fprintf(stderr, "Warning: failed to log data\n");
        }

        control_led(magnetic_field);

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

