        close(g_spi_fd); g_spi_fd = -1;
        gpioWrite(GPIO_POWER, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Current monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        int adc = read_mcp3008(ADC_CHANNEL);
        if (adc < 0) {
            fprintf(stderr, "ADC read failed; continuing.\n");
