#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * Raspberry Pi Zero W – MLX91211 current sensor logger via MCP3008 ADC
 *
 * Wiring:
 *   MCP3008 VDD  -> Pi 5V (pin 2 or 4)
 *   MCP3008 VREF -> Pi 5V
 *   MCP3008 AGND -> Pi GND
 *   MCP3008 DGND -> Pi GND
 *   MCP3008 CLK  -> GPIO11 (SPI0 SCLK)
 *   MCP3008 DOUT -> GPIO9  (SPI0 MISO)
 *   MCP3008 DIN  -> GPIO10 (SPI0 MOSI)
 *   MCP3008 CS   -> GPIO8  (SPI0 CE0)
 *   MCP3008 CH0  -> MLX91211 VOUT
 *   MLX91211 VDD -> Pi 5V
 *   MLX91211 GND -> Pi GND
 *
 * Build:
 *   gcc -O2 -Wall -o current_logger current_logger.c -lpigpio -lrt
 * Run:
 *   sudo ./current_logger
 */

#define SPI_CHANNEL    0          /* MCP3008 on SPI0 CE0 (GPIO8) */
#define SPI_SPEED      1000000    /* 1 MHz, mode 0 */
#define ADC_CHANNEL    0          /* MCP3008 single-ended channel 0 */
#define ADC_MAX        1023       /* 10-bit ADC */
#define VREF           5.0        /* MCP3008 VREF tied to 5V */
#define LOG_FILE       "current_log.txt"
#define SAMPLE_US      100000     /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single-ended sample from the MCP3008.
 * Returns 0 on success (adc_out set), -1 on SPI transfer error.
 */
static int read_mcp3008(int spi_handle, int channel, int *adc_out)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 single-ended read (3-byte transfer):
     *   tx[0] = 0x01                       (start bit)
     *   tx[1] = (0x08 | channel) << 4      (SGL/DIFF=1, D2 D1 D0, padded)
     *   tx[2] = 0x00                       (clock out remaining bits)
     * Result: bits 9..0 in rx[1] (low 2 bits) and rx[2] (8 bits).
     */
    char tx[3] = { 0x01, (char)((0x08 | channel) << 4), 0x00 };
    char rx[3] = { 0 };

    int ret = spiXfer(spi_handle, tx, rx, 3);
    if (ret != 3) {
        fprintf(stderr, "SPI transfer failed (returned %d)\n", ret);
        return -1;
    }

    *adc_out = ((rx[1] & 0x03) << 8) | (rx[2] & 0xFF);
    return 0;
}

static void log_current(FILE *fp, float current)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(fp, "%s %.2f A\n", ts, current) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
    }
}

int main(void)
{
    int spi_handle = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        goto cleanup_gpio;
    }

    /* --- Open log file --- */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup_spi;
    }

    printf("Logging MLX91211 current to %s (Ctrl+C to stop)\n", LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc = 0;

        if (read_mcp3008(spi_handle, ADC_CHANNEL, &adc) != 0) {
            fprintf(stderr, "ADC read error – skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float voltage = (float)adc * VREF / (float)ADC_MAX;
        if (voltage < 0.0f || voltage > VREF) {
            fprintf(stderr, "Voltage out of range: %.3f V – skipping sample\n", voltage);
            gpioDelay(SAMPLE_US);
            continue;
        }

        /*
         * MLX91211 transfer function (example):
         *   current (A) = (voltage (V) - 0.5) * 10.0
         * Adjust the gain/offset per your sensor datasheet.
         */
        float current = (voltage - 0.5f) * 10.0f;

        log_current(fp, current);
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    rc = EXIT_SUCCESS;

    /* --- Cleanup --- */
    if (fp) {
        fclose(fp);
    }
cleanup_spi:
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
cleanup_gpio:
    gpioTerminate();
    return rc;
}

