    if (fprintf(fp, "%s %.2f A\n", ts, current) < 0) {
        fprintf(stderr, "fprintf to log failed\n");
        return;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed\n");
    }
}

int main(void)
{
    int spi_handle = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open SPI0 CE0 at 1 MHz, mode 0 --- */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (handle %d)\n", spi_handle);
        goto cleanup_gpio;
    }

    /* --- Open log file --- */
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup_spi;
    }

    printf("Logging MLX91211 current to %s (Ctrl+C to stop)\n", LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        int adc = 0;

        if (read_mcp3008(spi_handle, ADC_CHANNEL, &adc) != 0) {
            fprintf(stderr, "ADC read error – skipping sample\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        float voltage = (float)adc * VREF / (float)ADC_MAX;
        if (voltage < 0.0f || voltage > VREF) {
            fprintf(stderr, "Voltage out of range: %.3f V – skipping sample\n", voltage);
            gpioDelay(SAMPLE_US);
            continue;
        }

        /*
         * MLX91211 transfer function (example):
         *   current (A) = (voltage (V) - 0.5) * 10.0
         * Adjust the gain/offset per your sensor datasheet.
         */
        float current = (voltage - 0.5f) * 10.0f;

        log_current(fp, current);
        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    rc = EXIT_SUCCESS;

    /* --- Cleanup --- */
    if (fp) {
        fclose(fp);
    }
cleanup_spi:
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
cleanup_gpio:
    gpioTerminate();
    return rc;
}

