    if (mkdir(path, 0755) != 0) {
        syslog(LOG_ERR, "mkdir failed for '%s': %s", path, strerror(errno));
        return -1;
    }
    syslog(LOG_INFO, "Created directory: %s", path);
    return 0;
}

static int capture_image(const char *filename) {
    char command[MAX_CMD];
    int needed = snprintf(command, sizeof(command),
        "libcamera-still -o %s --width 640 --height 480 --nopreview", filename);
    if (needed < 0 || (size_t)needed >= sizeof(command)) {
        syslog(LOG_ERR, "Command buffer too small for filename: %s", filename);
        return -1;
    }

    pid_t pid = fork();
    if (pid < 0) {
        syslog(LOG_ERR, "fork failed: %s", strerror(errno));
        return -1;
    }

    if (pid == 0) {
        char *argv[] = { "libcamera-still", "-o", (char *)filename,
                         "--width", "640", "--height", "480", "--nopreview", NULL };
        execvp("libcamera-still", argv);
        syslog(LOG_ERR, "execvp failed: %s", strerror(errno));
        _exit(127);
    }

    int status = 0;
    if (waitpid(pid, &status, 0) < 0) {
        syslog(LOG_ERR, "waitpid failed: %s", strerror(errno));
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) == 0) {
        syslog(LOG_INFO, "Image captured successfully: %s", filename);
        return 0;
    }

    syslog(LOG_ERR, "libcamera-still failed (status=%d)", status);
    return -1;
}

int main(void) {
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting security camera application");

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        syslog(LOG_ERR, "Failed to register SIGINT handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        syslog(LOG_ERR, "Failed to register SIGTERM handler: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_GPIO, PI_INPUT) != 0) {
        syslog(LOG_ERR, "Failed to set GPIO%d as input", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN) != 0) {
        syslog(LOG_ERR, "Failed to set pull-down on GPIO%d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    if (ensure_directory(IMAGE_DIR) != 0) {
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Monitoring PIR sensor on GPIO%d", PIR_GPIO);

    int last_state = gpioRead(PIR_GPIO);
    if (last_state < 0) {
        syslog(LOG_ERR, "Failed to read initial state of GPIO%d", PIR_GPIO);
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    while (program_running) {
        int current_state = gpioRead(PIR_GPIO);
        if (current_state < 0) {
            syslog(LOG_ERR, "Failed to read GPIO%d", PIR_GPIO);
            break;
        }

        if (current_state != last_state) {
            syslog(LOG_INFO, "PIR state changed: %d", current_state);
            last_state = current_state;

            if (current_state == 1) {
                syslog(LOG_INFO, "Motion detected!");
                gpioDelay(DEBOUNCE_DELAY_MS * 1000);

                int confirmed = gpioRead(PIR_GPIO);
                if (confirmed < 0) {
                    syslog(LOG_ERR, "Failed to confirm motion on GPIO%d", PIR_GPIO);
                    break;
                }

                if (confirmed == 1) {
                    time_t rawtime;
                    struct tm timeinfo;
                    char timestamp[32];
                    char filepath[MAX_PATH];

                    time(&rawtime);
                    if (localtime_r(&rawtime, &timeinfo) == NULL) {
                        syslog(LOG_ERR, "localtime_r failed");
                        break;
                    }

                    if (strftime(timestamp, sizeof(timestamp),
                                 "%Y%m%d_%H%M%S", &timeinfo) == 0) {
                        syslog(LOG_ERR, "strftime failed");
                        break;
                    }

                    if (snprintf(filepath, sizeof(filepath),
                                 "%smotion_%s.jpg", IMAGE_DIR, timestamp)
                        >= (int)sizeof(filepath)) {
                        syslog(LOG_ERR, "Filepath buffer too small");
                        break;
                    }

                    if (capture_image(filepath) == 0) {
                        syslog(LOG_INFO, "Motion event recorded: %s", filepath);
                    } else {
                        syslog(LOG_ERR, "Failed to capture image for motion event");
                    }
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down security camera application");
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

