    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (xioctl(*fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("VIDIOC_S_FMT");
        close(*fd);
        return -1;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_MJPEG) {
        fprintf(stderr, "Device does not support MJPEG format\n");
        close(*fd);
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = FRAME_BUF_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(*fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("VIDIOC_REQBUFS");
        close(*fd);
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(*fd);
        return -1;
    }

    return 0;
}

static int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("VIDIOC_STREAMON");
        return -1;
    }
    return 0;
}

static int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("VIDIOC_STREAMOFF");
        return -1;
    }
    return 0;
}

static int mmap_buffers(int fd, struct v4l2_buffer *buffers) {
    for (unsigned int i = 0; i < FRAME_BUF_COUNT; i++) {
        memset(&buffers[i], 0, sizeof(struct v4l2_buffer));
        buffers[i].type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buffers[i].memory = V4L2_MEMORY_MMAP;
        buffers[i].index = i;

        if (xioctl(fd, VIDIOC_QUERYBUF, &buffers[i]) < 0) {
            perror("VIDIOC_QUERYBUF");
            return -1;
        }

        buffers[i].m.userptr = (unsigned long)NULL;
        buffers[i].length = buffers[i].m.length;

        void *map = mmap(NULL, buffers[i].length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buffers[i].m.offset);
        if (map == MAP_FAILED) {
            perror("mmap");
            return -1;
        }
        buffers[i].m.mem_offset = (unsigned long)map;
    }
    return 0;
}

static int enqueue_buffer(int fd, unsigned int index) {
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = index;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("VIDIOC_QBUF");
        return -1;
    }
    return 0;
}

static int dequeue_buffer(int fd, struct v4l2_buffer *buf) {
    memset(buf, 0, sizeof(*buf));
    buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf->memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, buf) < 0) {
        perror("VIDIOC_DQBUF");
        return -1;
    }
    return 0;
}

static int log_timestamp(const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        perror("fopen(" filename ")");
        return -1;
    }

    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) < 0) {
        perror("clock_gettime");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%ld.%06ld\n", ts.tv_sec, ts.tv_nsec / 1000);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int fd = -1;
    struct v4l2_buffer buffers[FRAME_BUF_COUNT];
    int buffers_mapped = 0;
    int streaming_started = 0;

    if (init_device(&fd) < 0) {
        return EXIT_FAILURE;
    }
    buffers_mapped = 1;

    if (mmap_buffers(fd, buffers) < 0) {
        goto cleanup;
    }

    if (start_streaming(fd) < 0) {
        goto cleanup;
    }
    streaming_started = 1;

    for (unsigned int i = 0; i < FRAME_BUF_COUNT; i++) {
        if (enqueue_buffer(fd, i) < 0) {
            goto cleanup;
        }
    }

    printf("Capturing MJPEG stream from %s. Press Ctrl+C to exit.\n", DEVICE_NAME);

    while (g_running) {
        fd_set fds;
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        struct timeval tv;
        tv.tv_sec = SELECT_TIMEOUT_SEC;
        tv.tv_usec = 0;

        int r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r < 0) {
            if (errno == EINTR) {
                continue;
            }
            perror("select");
            break;
        }
        if (r == 0) {
            continue;
        }

        struct v4l2_buffer buf;
        if (dequeue_buffer(fd, &buf) < 0) {
            break;
        }

        if (log_timestamp(LOG_FILE) < 0) {
            fprintf(stderr, "Failed to log timestamp\n");
        }

        if (enqueue_buffer(fd, buf.index) < 0) {
            break;
        }
    }

cleanup:
    if (streaming_started) {
        stop_streaming(fd);
    }
    if (buffers_mapped) {
        for (unsigned int i = 0; i < FRAME_BUF_COUNT; i++) {
            if (buffers[i].m.mem_offset != 0 && buffers[i].m.mem_offset != (unsigned long)-1) {
                munmap((void *)buffers[i].m.mem_offset, buffers[i].length);
            }
        }
    }
    if (fd >= 0) {
        close(fd);
    }

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

