#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN      4
#define TILT_SERVO_PIN     5
#define TILT_UP_PIN        6
#define TILT_DOWN_PIN      7
#define PAN_LEFT_PIN       8
#define PAN_RIGHT_PIN      9

#define PWM_FREQUENCY      50          /* 50 Hz -> 20 ms period */
#define PWM_RANGE          1000        /* 1 ms -> 2 ms pulse width */
#define MIN_PULSE_WIDTH    50          /* 1 ms */
#define MAX_PULSE_WIDTH    100         /* 2 ms */
#define MID_PULSE_WIDTH    75          /* 1.5 ms -> mid-position */
#define MIN_POSITION       25
#define MAX_POSITION       125
#define STEP_SIZE          5
#define POLL_DELAY_US      50000       /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Set the servo pulse width for the given pin.
 * Returns 0 on success, -1 on failure.
 */
static int set_servo_pulse(int pin, int pulse_width)
{
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: pulse width %d out of range [%d, %d]\n",
                pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
        return -1;
    }

    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d (pulse=%d)\n",
                pin, pulse_width);
        return -1;
    }
    return 0;
}

/*
 * Read the button state. Returns 1 if pressed (active-low), 0 if released,
 * -1 on read error.
 */
static int read_button(int pin)
{
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d\n", pin);
        return -1;
    }
    return (level == 0) ? 1 : 0;
}

/*
 * Adjust the pan or tilt position by the given delta, clamping to valid range.
 * Returns the new position.
 */
static int adjust_position(int current, int delta)
{
    int new_pos = current + delta;
    if (new_pos < MIN_POSITION) new_pos = MIN_POSITION;
    if (new_pos > MAX_POSITION) new_pos = MAX_POSITION;
    return new_pos;
}

int main(void)
{
    int pan_position  = MID_PULSE_WIDTH;
    int tilt_position = MID_PULSE_WIDTH;
    int rc;

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure button pins as inputs with internal pull-ups --- */
    int button_pins[] = {TILT_UP_PIN, TILT_DOWN_PIN, PAN_LEFT_PIN, PAN_RIGHT_PIN};
    for (size_t i = 0; i < sizeof(button_pins) / sizeof(button_pins[0]); i++) {
        if (gpioSetMode(button_pins[i], PI_INPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", button_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(button_pins[i], PI_PUD_UP) < 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed on pin %d\n", button_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* --- Configure servo pins as outputs --- */
    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Set PWM frequency and range for both servos --- */
    if (gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed on pin %d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed on pin %d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed on pin %d\n", PAN_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed on pin %d\n", TILT_SERVO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Initialize servos to mid-position --- */
    if (set_servo_pulse(PAN_SERVO_PIN, pan_position) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (set_servo_pulse(TILT_SERVO_PIN, tilt_position) < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pan-tilt mount control started.\n");
    printf("Pan: GPIO%d, Tilt: GPIO%d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("Tilt Up: GPIO%d, Tilt Down: GPIO%d\n", TILT_UP_PIN, TILT_DOWN_PIN);
    printf("Pan Left: GPIO%d, Pan Right: GPIO%d\n", PAN_LEFT_PIN, PAN_RIGHT_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main control loop --- */
    while (g_running) {
        int tilt_up, tilt_down, pan_left, pan_right;

        tilt_up   = read_button(TILT_UP_PIN);
        tilt_down = read_button(TILT_DOWN_PIN);
        pan_left  = read_button(PAN_LEFT_PIN);
        pan_right = read_button(PAN_RIGHT_PIN);

        /* Tilt adjustment */
        if (tilt_up == 1) {
            tilt_position = adjust_position(tilt_position,  STEP_SIZE);
            if (set_servo_pulse(TILT_SERVO_PIN, tilt_position) < 0) {
                fprintf(stderr, "Warning: failed to set tilt position\n");
            }
            /* Debounce: wait for button release */
            while (read_button(TILT_UP_PIN) == 1 && g_running) {
                gpioDelay(POLL_DELAY_US);
            }
        } else if (tilt_down == 1) {
            tilt_position = adjust_position(tilt_position, -STEP_SIZE);
            if (set_servo_pulse(TILT_SERVO_PIN, tilt_position) < 0) {
                fprintf(stderr, "Warning: failed to set tilt position\n");
            }
            while (read_button(TILT_DOWN_PIN) == 1 && g_running) {
                gpioDelay(POLL_DELAY_US);
            }
        }

        /* Pan adjustment */
        if (pan_left == 1) {
            pan_position = adjust_position(pan_position, -STEP_SIZE);
            if (set_servo_pulse(PAN_SERVO_PIN, pan_position) < 0) {
                fprintf(stderr, "Warning: failed to set pan position\n");
            }
            while (read_button(PAN_LEFT_PIN) == 1 && g_running) {
                gpioDelay(POLL_DELAY_US);
            }
        } else if (pan_right == 1) {
            pan_position = adjust_position(pan_position,  STEP_SIZE);
            if (set_servo_pulse(PAN_SERVO_PIN, pan_position) < 0) {
                fprintf(stderr, "Warning: failed to set pan position\n");
            }
            while (read_button(PAN_RIGHT_PIN) == 1 && g_running) {
                gpioDelay(POLL_DELAY_US);
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioServo(PAN_SERVO_PIN, 0);   /* Stop PWM pulses */
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    printf("Pan-tilt mount control stopped.\n");
    return EXIT_SUCCESS;
}

