/*
 * capture_and_blur.c — Capture a USB camera frame, blur it, and save as JPEG.
 *
 * Build:  gcc -O2 -Wall -Wextra -o capture_and_blur capture_and_blur.c \
 *            -ljpeg -luvc -lpthread
 *
 * Hardware: Raspberry Pi with a USB camera (e.g. Logitech C920) connected.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <sys/select.h>
#include <linux/videodev2.h>
#include <jpeglib.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH       640
#define HEIGHT      480
#define NUM_BUFS    4
#define JPEG_QUAL   75

static volatile sig_atomic_t g_stop = 0;

static void sigint_handler(int sig)
{
    (void)sig;
    g_stop = 1;
}

/* ------------------------------------------------------------------ */
/* V4L2 helpers                                                        */
/* ------------------------------------------------------------------ */

static int xioctl(int fd, unsigned long request, void *arg)
{
    int r;
    do {
        r = ioctl(fd, request, arg);
    } while (r == -1 && errno == EINTR);
    return r;
}

static int init_camera(int *fd_out)
{
    int fd = open(DEVICE_NAME, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    struct v4l2_capability cap;
    memset(&cap, 0, sizeof(cap));
    if (xioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "VIDIOC_QUERYCAP: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(fd);
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type                = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width       = WIDTH;
    fmt.fmt.pix.height      = HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field       = V4L2_FIELD_NONE;

    if (xioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "VIDIOC_S_FMT: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (fmt.fmt.pix.pixelformat != V4L2_PIX_FMT_YUYV) {
        fprintf(stderr, "Camera did not accept YUYV format\n");
        close(fd);
        return -1;
    }

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count  = NUM_BUFS;
    req.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "VIDIOC_REQBUFS: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        return -1;
    }

    *fd_out = fd;
    return 0;
}

static int start_streaming(int fd)
{
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMON: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int stop_streaming(int fd)
{
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (xioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        fprintf(stderr, "VIDIOC_STREAMOFF: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int qbuf(int fd, unsigned int index)
{
    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index  = index;

    if (xioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        fprintf(stderr, "VIDIOC_QBUF: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int dqbuf(int fd, struct v4l2_buffer *buf)
{
    memset(buf, 0, sizeof(*buf));
    buf->type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf->memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_DQBUF, buf) < 0) {
        fprintf(stderr, "VIDIOC_DQBUF: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* YUYV -> RGB24 conversion                                            */
/* ------------------------------------------------------------------ */

static void yuyv_to_rgb24(const unsigned char *yuyv, unsigned char *rgb,
                          int width, int height)
{
    int i;
    for (i = 0; i < width * height * 2; i += 4) {
        int y0  = yuyv[i];
        int u   = yuyv[i + 1];
        int y1  = yuyv[i + 2];
        int v   = yuyv[i + 3];

        int c  = y0 - 16;
        int d  = u - 128;
        int e  = v - 128;

        int r0 = (298 * c + 409 * e + 128) >> 8;
        int g0 = (298 * c - 100 * d - 208 * e + 128) >> 8;
        int b0 = (298 * c + 516 * d + 128) >> 8;

        int r1 = (298 * y1 + 409 * e + 128) >> 8;
        int g1 = (298 * y1 - 100 * d - 208 * e + 128) >> 8;
        int b1 = (298 * y1 + 516 * d + 128) >> 8;

        if (r0 < 0) r0 = 0; if (r0 > 255) r0 = 255;
        if (g0 < 0) g0 = 0; if (g0 > 255) g0 = 255;
        if (b0 < 0) b0 = 0; if (b0 > 255) b0 = 255;
        if (r1 < 0) r1 = 0; if (r1 > 255) r1 = 255;
        if (g1 < 0) g1 = 0; if (g1 > 255) g1 = 255;
        if (b1 < 0) b1 = 0; if (b1 > 255) b1 = 255;

        rgb[i]     = (unsigned char)r0;
        rgb[i + 1] = (unsigned char)g0;
        rgb[i + 2] = (unsigned char)b0;
        rgb[i + 3] = (unsigned char)r1;
        rgb[i + 4] = (unsigned char)g1;
        rgb[i + 5] = (unsigned char)b1;
    }
}

/* ------------------------------------------------------------------ */
/* Simple blur filter                                                  */
/* ------------------------------------------------------------------ */

static void blur_filter(unsigned char *rgb, int width, int height)
{
    unsigned char *tmp = malloc((size_t)width * height * 3);
    if (!tmp) {
        fprintf(stderr, "malloc failed in blur_filter\n");
        return;
    }

    int i, j;
    for (i = 1; i < height - 1; i++) {
        for (j = 1; j < width - 1; j++) {
            int idx = (i * width + j) * 3;
            int r = 0, g = 0, b = 0;
            int k, l;
            for (k = -1; k <= 1; k++) {
                for (l = -1; l <= 1; l++) {
                    int nidx = ((i + k) * width + (j + l)) * 3;
                    r += rgb[nidx];
                    g += rgb[nidx + 1];
                    b += rgb[nidx + 2];
                }
            }
            tmp[idx]     = (unsigned char)(r / 9);
            tmp[idx + 1] = (unsigned char)(g / 9);
            tmp[idx + 2] = (unsigned char)(b / 9);
        }
    }

    memcpy(rgb, tmp, (size_t)width * height * 3);
    free(tmp);
}

/* ------------------------------------------------------------------ */
/* JPEG encoding                                                       */
/* ------------------------------------------------------------------ */

static int encode_jpeg(const unsigned char *rgb, int width, int height,
                       const char *filename)
{
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr       jerr;

    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);

    FILE *outfile = fopen(filename, "wb");
    if (!outfile) {
        fprintf(stderr, "fopen(%s): %s\n", filename, strerror(errno));
        jpeg_destroy_compress(&cinfo);
        return -1;
    }

    jpeg_stdio_dest(&cinfo, outfile);

    cinfo.image_width      = width;
    cinfo.image_height     = height;
    cinfo.input_components = 3;
    cinfo.in_color_space   = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, JPEG_QUAL, TRUE);
    jpeg_start_compress(&cinfo, TRUE);

    JSAMPROW row[1];
    int row_stride = width * 3;

    while (cinfo.next_scanline < cinfo.image_height) {
        row[0] = &rgb[cinfo.next_scanline * row_stride];
        jpeg_write_scanlines(&cinfo, row, 1);
    }

    jpeg_finish_compress(&cinfo);
    fclose(outfile);
    jpeg_destroy_compress(&cinfo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction: %s\n", strerror(errno));
        return 1;
    }

    int fd = -1;
    if (init_camera(&fd) < 0)
        return 1;

    struct v4l2_buffer buf;
    memset(&buf, 0, sizeof(buf));
    buf.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.length = WIDTH * HEIGHT * 2;

    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count  = NUM_BUFS;
    req.type   = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (xioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        close(fd);
        return 1;
    }

    struct v4l2_buffer *buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        fprintf(stderr, "calloc failed\n");
        close(fd);
        return 1;
    }

    unsigned char *buffer_start = NULL;
    size_t         buffer_length = 0;

    for (unsigned int i = 0; i < req.count; i++) {
        buf.index = i;
        if (xioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            free(buffers);
            close(fd);
            return 1;
        }
        buffers[i] = buf;

        if (i == 0) {
            buffer_length = buf.length;
            buffer_start  = mmap(NULL, buf.length, PROT_READ | PROT_WRITE,
                                 MAP_SHARED, fd, buf.m.offset);
            if (buffer_start == MAP_FAILED) {
                fprintf(stderr, "mmap: %s\n", strerror(errno));
                free(buffers);
                close(fd);
                return 1;
            }
        }
    }

    if (start_streaming(fd) < 0) {
        munmap(buffer_start, buffer_length);
        free(buffers);
        close(fd);
        return 1;
    }

    for (unsigned int i = 0; i < req.count; i++) {
        if (qbuf(fd, i) < 0) {
            stop_streaming(fd);
            munmap(buffer_start, buffer_length);
            free(buffers);
            close(fd);
            return 1;
        }
    }

    fd_set fds;
    struct timeval tv;
    int r;

    while (!g_stop) {
        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec  = 2;
        tv.tv_usec = 0;

        r = select(fd + 1, &fds, NULL, NULL, &tv);
        if (r == -1) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "select: %s\n", strerror(errno));
            break;
        }
        if (r == 0) {
            fprintf(stderr, "select timeout — no frame within 2 s\n");
            break;
        }

        if (dqbuf(fd, &buf) < 0)
            break;

        if (buf.index >= req.count) {
            fprintf(stderr, "dqbuf returned invalid index %u\n", buf.index);
            break;
        }

        break;
    }

    if (stop_streaming(fd) < 0)
        ;

    for (unsigned int i = 0; i < req.count; i++) {
        if (munmap(buffer_start, buffer_length) < 0) {
            fprintf(stderr, "munmap: %s\n", strerror(errno));
            break;
        }
    }

    free(buffers);

    if (g_stop) {
        fprintf(stderr, "Interrupted — exiting cleanly.\n");
        close(fd);
        return 0;
    }

    if (r <= 0) {
        close(fd);
        return 1;
    }

    unsigned char *rgb = malloc((size_t)WIDTH * HEIGHT * 3);
    if (!rgb) {
        fprintf(stderr, "malloc failed for RGB buffer\n");
        close(fd);
        return 1;
    }

    yuyv_to_rgb24(buffer_start, rgb, WIDTH, HEIGHT);
    blur_filter(rgb, WIDTH, HEIGHT);

    time_t rawtime;
    time(&rawtime);
    struct tm *timeinfo = localtime(&rawtime);
    char filename[64];
    strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

    if (encode_jpeg(rgb, WIDTH, HEIGHT, filename) < 0) {
        fprintf(stderr, "Failed to encode JPEG\n");
        free(rgb);
        close(fd);
        return 1;
    }

    printf("Saved %s\n", filename);
    free(rgb);
    close(fd);
    return 0;
}

