        int e  = v - 128;

        int r0 = (298 * c + 409 * e + 128) >> 8;
        int g0 = (298 * c - 100 * d - 208 * e + 128) >> 8;
        int b0 = (298 * c + 516 * d + 128) >> 8;

        int r1 = (298 * y1 + 409 * e + 128) >> 8;
        int g1 = (298 * y1 - 100 * d - 208 * e + 128) >> 8;
        int b1 = (298 * y1 + 516 * d + 128) >> 8;

        if (r0 < 0) r0 = 0; if (r0 > 255) r0 = 255;
        if (g0 < 0) g0 = 0; if (g0 > 255) g0 = 255;
        if (b0 < 0) b0 = 0; if (b0 > 255) b0 = 255;
        if (r1 < 0) r1 = 0; if (r1 > 255) r1 = 255;
        if (g1 < 0) g1 = 0; if (g1 > 255) g1 = 255;
