        rgb[i]     = (unsigned char)r0;
        rgb[i + 1] = (unsigned char)g0;
        rgb[i + 2] = (unsigned char)b0;
        rgb[i + 3] = (unsigned char)r1;
        rgb[i + 4] = (unsigned char)g1;
        rgb[i + 5] = (unsigned char)b1;
    }
