/* ------------------------------------------------------------------ */
/* JPEG encoding                                                       */
/* ------------------------------------------------------------------ */

static int encode_jpeg(const unsigned char *rgb, int width, int height,
                       const char *filename)
{
    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr       jerr;

