#define CLEAR(x) memset(&(x), 0, sizeof(x))

static void print_frmsize(const struct v4l2_frmsizeenum *f)
{
    printf("    %ux%u", f->width, f->height);
    if (f->stepwise)
        printf(" (stepwise: %ux%u .. %ux%u, %u steps)",
               f->min_width, f->min_height,
               f->max_width, f->max_height,
               f->step_width);
    else
        printf(" (discrete)");
    printf("\n");
}

static void print_frmival(const struct v4l2_frmivalenum *f)
{
