#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN  4
#define TILT_SERVO_PIN 5

#define BUTTON_UP_PIN    6
#define BUTTON_DOWN_PIN  7
#define BUTTON_LEFT_PIN  8
#define BUTTON_RIGHT_PIN 9

#define SERVO_MIN_PULSE_WIDTH  1000
#define SERVO_MAX_PULSE_WIDTH  2000
#define SERVO_CENTER_PULSE_WIDTH 1500
#define SERVO_PULSE_STEP 10
#define LOOP_DELAY_US 50000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int clamp_pulse_width(int pw)
{
    if (pw < SERVO_MIN_PULSE_WIDTH) return SERVO_MIN_PULSE_WIDTH;
    if (pw > SERVO_MAX_PULSE_WIDTH) return SERVO_MAX_PULSE_WIDTH;
    return pw;
}

int main(void)
{
    int pan_pw  = SERVO_CENTER_PULSE_WIDTH;
    int tilt_pw = SERVO_CENTER_PULSE_WIDTH;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install signal handlers.\n");
    }

    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(BUTTON_UP_PIN, PI_INPUT);
    gpioSetMode(BUTTON_DOWN_PIN, PI_INPUT);
    gpioSetMode(BUTTON_LEFT_PIN, PI_INPUT);
    gpioSetMode(BUTTON_RIGHT_PIN, PI_INPUT);

    gpioSetPullUpDown(BUTTON_UP_PIN, PI_PUD_UP);
    gpioSetPullUpDown(BUTTON_DOWN_PIN, PI_PUD_UP);
    gpioSetPullUpDown(BUTTON_LEFT_PIN, PI_PUD_UP);
    gpioSetPullUpDown(BUTTON_RIGHT_PIN, PI_PUD_UP);

    if (gpioServo(PAN_SERVO_PIN, pan_pw) < 0) {
        fprintf(stderr, "Error: failed to start PWM on pan servo pin.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioServo(TILT_SERVO_PIN, tilt_pw) < 0) {
        fprintf(stderr, "Error: failed to start PWM on tilt servo pin.\n");
        gpioServo(PAN_SERVO_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Pan-Tilt Servo Control (pigpio)\n");
    printf("Pan: GPIO%d  Tilt: GPIO%d\n", PAN_SERVO_PIN, TILT_SERVO_PIN);
    printf("Buttons: UP=GPIO%d  DOWN=GPIO%d  LEFT=GPIO%d  RIGHT=GPIO%d\n",
           BUTTON_UP_PIN, BUTTON_DOWN_PIN, BUTTON_LEFT_PIN, BUTTON_RIGHT_PIN);
    printf("Center position: %d us  Range: %d-%d us  Step: %d us\n",
           SERVO_CENTER_PULSE_WIDTH, SERVO_MIN_PULSE_WIDTH,
           SERVO_MAX_PULSE_WIDTH, SERVO_PULSE_STEP);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        if (gpioRead(BUTTON_UP_PIN) == 0) {
            tilt_pw = clamp_pulse_width(tilt_pw - SERVO_PULSE_STEP);
            gpioServo(TILT_SERVO_PIN, tilt_pw);
            usleep(100000);
        }
        if (gpioRead(BUTTON_DOWN_PIN) == 0) {
            tilt_pw = clamp_pulse_width(tilt_pw + SERVO_PULSE_STEP);
            gpioServo(TILT_SERVO_PIN, tilt_pw);
            usleep(100000);
        }
        if (gpioRead(BUTTON_LEFT_PIN) == 0) {
            pan_pw = clamp_pulse_width(pan_pw - SERVO_PULSE_STEP);
            gpioServo(PAN_SERVO_PIN, pan_pw);
            usleep(100000);
        }
        if (gpioRead(BUTTON_RIGHT_PIN) == 0) {
            pan_pw = clamp_pulse_width(pan_pw + SERVO_PULSE_STEP);
            gpioServo(PAN_SERVO_PIN, pan_pw);
            usleep(100000);
        }
        usleep(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    gpioServo(PAN_SERVO_PIN, 0);
    gpioServo(TILT_SERVO_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

