#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <pigpio.h>
#include <jpeglib.h>
#include <curl/curl.h>

#define PIR_GPIO 17
#define DEBOUNCE_SEC 2
#define POLL_INTERVAL_US 100000
#define IMG_QUALITY 85
#define CAPTURE_DIR "motion_captures"
#define MAX_FILENAME_LEN 256
#define MAX_PAYLOAD_LEN 1024
#define MAX_RESPONSE_LEN 4096

static volatile sig_atomic_t g_running = 1;
static int g_http_initialized = 0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int ensure_capture_dir(void) {
    struct stat st;
    if (stat(CAPTURE_DIR, &st) == 0) {
        if (S_ISDIR(st.st_mode)) return 0;
        fprintf(stderr, "Error: '%s' exists but is not a directory\n", CAPTURE_DIR);
        return -1;
    }
    if (mkdir(CAPTURE_DIR, 0755) != 0) {
        fprintf(stderr, "Error creating directory '%s': %s\n", CAPTURE_DIR, strerror(errno));
        return -1;
    }
    return 0;
}

static int capture_jpeg(const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        fprintf(stderr, "Error opening file '%s' for writing: %s\n", filename, strerror(errno));
        return -1;
    }

    struct jpeg_compress_struct cinfo;
    struct jpeg_error_mgr jerr;
    cinfo.err = jpeg_std_error(&jerr);
    jpeg_create_compress(&cinfo);
    jpeg_stdio_dest(&cinfo, fp);

    cinfo.image_width = 640;
    cinfo.image_height = 480;
    cinfo.input_components = 3;
    cinfo.in_color_space = JCS_RGB;

    jpeg_set_defaults(&cinfo);
    jpeg_set_quality(&cinfo, IMG_QUALITY, TRUE);
    jpeg_start_compress(&cinfo, TRUE);

    JSAMPROW row[1];
    unsigned char *buffer = malloc(640 * 3);
    if (!buffer) {
        fprintf(stderr, "Memory allocation failed for JPEG buffer\n");
        jpeg_destroy_compress(&cinfo);
        fclose(fp);
        return -1;
    }

    while (cinfo.next_scanline < cinfo.image_height) {
        memset(buffer, 0, 640 * 3);
        row[0] = buffer;
        jpeg_write_scanlines(&cinfo, row, 1);
    }

    free(buffer);
    jpeg_finish_compress(&cinfo);
    jpeg_destroy_compress(&cinfo);
    fclose(fp);
    return 0;
}

static void get_timestamp(char *buf, size_t len) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%06ldZ", ts.tv_nsec / 1000);
}

static int send_http_post(const char *url, const char *payload, const char *filename) {
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "curl_easy_init() failed\n");
        return -1;
    }

    FILE *fp = fopen(filename, "rb");
    if (!fp) {
        fprintf(stderr, "Error opening file '%s' for reading: %s\n", filename, strerror(errno));
        curl_easy_cleanup(curl);
        return -1;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    fseek(fp, 0, SEEK_SET);

    char *file_data = malloc(file_size);
    if (!file_data) {
        fprintf(stderr, "Memory allocation failed for file data\n");
        fclose(fp);
        curl_easy_cleanup(curl);
        return -1;
    }

    size_t bytes_read = fread(file_data, 1, file_size, fp);
    fclose(fp);

    if (bytes_read != (size_t)file_size) {
        fprintf(stderr, "Error reading file '%s'\n", filename);
        free(file_data);
        curl_easy_cleanup(curl);
        return -1;
    }

    struct curl_slist *headers = NULL;
    headers = curl_slist_append(headers, "Content-Type: multipart/form-data");

    curl_easy_setopt(curl, CURLOPT_URL, url);
    curl_easy_setopt(curl, CURLOPT_POST, 1L);
    curl_easy_setopt(curl, CURLOPT_POSTFIELDS, payload);
    curl_easy_setopt(curl, CURLOPT_HTTPHEADER, headers);
    curl_easy_setopt(curl, CURLOPT_READFUNCTION, NULL);
    curl_easy_setopt(curl, CURLOPT_READDATA, NULL);
    curl_easy_setopt(curl, CURLOPT_INFILESIZE_LARGE, (curl_off_t)file_size);

    CURLcode res = curl_easy_perform(curl);
    if (res != CURLE_OK) {
        fprintf(stderr, "curl_easy_perform() failed: %s\n", curl_easy_strerror(res));
    }

    free(file_data);
    curl_slist_free_all(headers);
    curl_easy_cleanup(curl);
    return (res == CURLE_OK) ? 0 : -1;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <IP> <Port>\n", argv[0]);
        return 1;
    }

    const char *ip = argv[1];
    const char *port = argv[2];
    char url[256];
    snprintf(url, sizeof(url), "http://%s:%s/upload", ip, port);

    if (signal(SIGINT, signal_handler) == SIG_ERR || signal(SIGTERM, signal_handler) == SIG_ERR) {
        perror("signal");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (ensure_capture_dir() != 0) {
        gpioTerminate();
        return 1;
    }

    if (g_http_initialized == 0) {
        if (curl_global_init(CURL_GLOBAL_DEFAULT) != CURLE_OK) {
            fprintf(stderr, "curl_global_init() failed\n");
            gpioTerminate();
            return 1;
        }
        g_http_initialized = 1;
    }

    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN);

    printf("Motion detection started on GPIO%d. Press Ctrl+C to exit.\n", PIR_GPIO);

    while (g_running) {
        if (gpioRead(PIR_GPIO) == 1) {
            printf("Motion detected!\n");

            char timestamp[32];
            get_timestamp(timestamp, sizeof(timestamp));

            char filename[MAX_FILENAME_LEN];
            snprintf(filename, sizeof(filename), "%s/motion_%s.jpg", CAPTURE_DIR, timestamp);

            if (capture_jpeg(filename) != 0) {
                fprintf(stderr, "Failed to capture image.\n");
            } else {
                printf("Image captured: %s\n", filename);

                char payload[MAX_PAYLOAD_LEN];
                snprintf(payload, sizeof(payload),
                         "{\"filename\":\"%s\",\"timestamp\":\"%s\",\"motion\":true,\"gpio_pin\":%d}",
                         filename, timestamp, PIR_GPIO);

                if (send_http_post(url, payload, filename) != 0) {
                    fprintf(stderr, "Failed to send HTTP POST.\n");
                } else {
                    printf("HTTP POST sent successfully.\n");
                }
            }

            gpioDelay(DEBOUNCE_SEC * 1000000);
        }
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioTerminate();

    if (g_http_initialized) {
        curl_global_cleanup();
        g_http_initialized = 0;
    }

    return 0;
}

