/*
 * motion_capture.c — Raspberry Pi Zero W
 *
 * Monitors an HC-SR501 PIR sensor on GPIO17 (BCM, physical pin 11) for
 * edge-falling events, debounces with a 50 ms timeout, and invokes the
 * libcamera-jpeg capture utility to save a timestamped JPEG in
 * /home/pi/images.  All events and errors are logged to
 * /home/pi/motion_capture.log.
 *
 * Build:  gcc -O2 -Wall -Wextra -o motion_capture motion_capture.c -lgpiod
 * Run:    sudo ./motion_capture
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME      "gpiochip0"
#define PIR_PIN             17          /* BCM 17, physical pin 11 */
#define IMAGE_DIR           "/home/pi/images"
#define LOG_FILE            "/home/pi/motion_capture.log"
#define DEBOUNCE_MS         50
#define POLL_TIMEOUT_MS     1000
#define FILENAME_LEN        64
#define PATH_LEN            256
#define CMD_LEN             512
#define LOG_MSG_LEN         512

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) != NULL)
        strftime(buf, len, "%Y%m%d_%H%M%S", &tm_info);
    else
        snprintf(buf, len, "UNKNOWN");
}

/* ------------------------------------------------------------------ */
static void log_event(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s: %s\n", ts, msg);
        fclose(fp);
    } else {
        fprintf(stderr, "%s: %s (log open failed: %s)\n",
                ts, msg, strerror(errno));
    }
}

/* ------------------------------------------------------------------ */
static int capture_image(const char *filename)
{
    char command[CMD_LEN];
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    snprintf(command, sizeof(command),
             "libcamera-jpeg -o %s -w 640 -h 480 -q 85 "
             "--timeout 2000 --nopreview", filename);

    int status = system(command);
    if (status == -1) {
        char msg[LOG_MSG_LEN];
        snprintf(msg, sizeof(msg),
                 "ERROR: system() failed to launch capture: %s",
                 strerror(errno));
        log_event(msg);
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        char msg[LOG_MSG_LEN];
        snprintf(msg, sizeof(msg),
                 "ERROR: capture exited with status %d",
                 WIFEXITED(status) ? WEXITSTATUS(status) : -1);
        log_event(msg);
        return -1;
    }

    char msg[LOG_MSG_LEN];
    snprintf(msg, sizeof(msg), "Motion detected: image saved as %s", filename);
    log_event(msg);
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ------------------------------------------ */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip and claim the PIR line -------------------- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, PIR_PIN);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                PIR_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request edge-falling events so we only act on real motion. */
    if (gpiod_line_request_falling_edge_events(line, "motion_capture") < 0) {
        fprintf(stderr, "Failed to request falling-edge events on GPIO %d: %s\n",
                PIR_PIN, strerror(errno));
        goto cleanup;
    }

    log_event("Motion detection service started");

    /* ---- Main loop: poll for events with debounce ----------------- */
    while (g_running) {
        struct timespec ts = { 0, POLL_TIMEOUT_MS * 1000000L };
        int ev = gpiod_line_event_wait(line, &ts);

        if (ev < 0) {
            if (errno == EINTR)
                continue;
            char msg[LOG_MSG_LEN];
            snprintf(msg, sizeof(msg),
                     "ERROR: gpiod_line_event_wait failed: %s",
                     strerror(errno));
            log_event(msg);
            break;
        }
        if (ev == 0)
            continue;                 /* timeout, no event */

        /* Drain any queued events so we don't re-trigger on bounce. */
        while (gpiod_line_event_read(line, NULL) == 0)
            ;

        /* Debounce: wait for the line to return to LOW. */
        struct timespec debounce = { 0, DEBOUNCE_MS * 1000000L };
        while (g_running) {
            int val = gpiod_line_get_value(line);
            if (val < 0) {
                char msg[LOG_MSG_LEN];
                snprintf(msg, sizeof(msg),
                         "ERROR: gpiod_line_get_value failed: %s",
                         strerror(errno));
                log_event(msg);
                break;
            }
            if (val == 0)
                break;                 /* debounced, motion ended */
            nanosleep(&debounce, NULL);
        }

        if (!g_running)
            break;

        /* ---- Valid motion: capture image --------------------------- */
        char ts_str[32];
        get_timestamp(ts_str, sizeof(ts_str));

        char filename[FILENAME_LEN];
        char filepath[PATH_LEN];
        snprintf(filename, sizeof(filename), "%s_%s_mmm.jpg",
                 ts_str, "motion");
        snprintf(filepath, sizeof(filepath), "%s/%s", IMAGE_DIR, filename);

        if (capture_image(filepath) != 0) {
            char msg[LOG_MSG_LEN];
            snprintf(msg, sizeof(msg),
                     "ERROR: capture_image failed for %s", filepath);
            log_event(msg);
        }
    }

    log_event("Motion detection service stopped");
    ret = EXIT_SUCCESS;

cleanup:
    if (line)
        gpiod_line_release(line);
    if (chip)
        gpiod_chip_close(chip);
    return ret;
}

