#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PAN_SERVO_PIN  17
#define TILT_SERVO_PIN 18

#define NEUTRAL_PULSEWIDTH 1500
#define MIN_PULSEWIDTH     1000
#define MAX_PULSEWIDTH     2000

#define MIN_ANGLE 0
#define MAX_ANGLE 180

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int angle_to_pulsewidth(int angle)
{
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d out of range [%d, %d].\n",
                angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }
    return MIN_PULSEWIDTH +
           (int)((long)(angle - MIN_ANGLE) *
                 (MAX_PULSEWIDTH - MIN_PULSEWIDTH) /
                 (MAX_ANGLE - MIN_ANGLE));
}

static int set_servo_angle(int pin, int angle)
{
    int pw = angle_to_pulsewidth(angle);
    if (pw < 0)
        return -1;
    if (gpioServo(pin, pw) < 0) {
        fprintf(stderr, "Error: gpioServo failed on pin %d (pw=%d).\n", pin, pw);
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Return both servos to neutral before releasing hardware PWM. */
    gpioServo(PAN_SERVO_PIN, NEUTRAL_PULSEWIDTH);
    gpioServo(TILT_SERVO_PIN, NEUTRAL_PULSEWIDTH);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Register signal handler for clean shutdown on Ctrl+C. */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    /* Set both servo pins to output mode (pigpio handles PWM via gpioServo). */
    if (gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed on pin %d.\n", PAN_SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed on pin %d.\n", TILT_SERVO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Start both servos at neutral position. */
    if (set_servo_angle(PAN_SERVO_PIN, 90) < 0 ||
        set_servo_angle(TILT_SERVO_PIN, 90) < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    int pan_angle  = 90;
    int tilt_angle = 90;

    printf("Pan-Tilt Servo Control (GPIO17=pan, GPIO18=tilt)\n");
    printf("Press arrow keys to move, 'q' to quit.\n");
    fflush(stdout);

    while (g_running) {
        int c = getchar();
        if (c == EOF)
            break;

        switch (c) {
        case 'q':
        case 'Q':
            g_running = 0;
            break;
        case 'a':
        case 'A':
            if (pan_angle > MIN_ANGLE) {
                pan_angle -= 5;
                if (set_servo_angle(PAN_SERVO_PIN, pan_angle) < 0)
                    g_running = 0;
            }
            break;
        case 'd':
        case 'D':
            if (pan_angle < MAX_ANGLE) {
                pan_angle += 5;
                if (set_servo_angle(PAN_SERVO_PIN, pan_angle) < 0)
                    g_running = 0;
            }
            break;
        case 'w':
        case 'W':
            if (tilt_angle > MIN_ANGLE) {
                tilt_angle -= 5;
                if (set_servo_angle(TILT_SERVO_PIN, tilt_angle) < 0)
                    g_running = 0;
            }
            break;
        case 's':
        case 'S':
            if (tilt_angle < MAX_ANGLE) {
                tilt_angle += 5;
                if (set_servo_angle(TILT_SERVO_PIN, tilt_angle) < 0)
                    g_running = 0;
            }
            break;
        default:
            break;
        }

        if (g_running)
            usleep(100000); /* 100 ms */
    }

    cleanup();
    return EXIT_SUCCESS;
}

