#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>

#define OLED_WIDTH 128
#define OLED_HEIGHT 64
#define OLED_I2C_ADDR 0x3C
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write(int fd, const unsigned char *buf, size_t len) {
    if (write(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int oled_command(int fd, unsigned char cmd) {
    unsigned char buf[2] = {0x00, cmd};
    return i2c_write(fd, buf, 2);
}

static int oled_data(int fd, const unsigned char *data, size_t len) {
    unsigned char buf[len + 1];
    buf[0] = 0x40;
    memcpy(buf + 1, data, len);
    return i2c_write(fd, buf, len + 1);
}

static int oled_init(int fd) {
    if (oled_command(fd, 0xAE) < 0) return -1;
    if (oled_command(fd, 0xD5) < 0) return -1;
    if (oled_command(fd, 0x80) < 0) return -1;
    if (oled_command(fd, 0xA8) < 0) return -1;
    if (oled_command(fd, 0x3F) < 0) return -1;
    if (oled_command(fd, 0xD3) < 0) return -1;
    if (oled_command(fd, 0x00) < 0) return -1;
    if (oled_command(fd, 0x40) < 0) return -1;
    if (oled_command(fd, 0x8D) < 0) return -1;
    if (oled_command(fd, 0x14) < 0) return -1;
    if (oled_command(fd, 0x20) < 0) return -1;
    if (oled_command(fd, 0x00) < 0) return -1;
    if (oled_command(fd, 0xA1) < 0) return -1;
    if (oled_command(fd, 0xC8) < 0) return -1;
    if (oled_command(fd, 0xDA) < 0) return -1;
    if (oled_command(fd, 0x12) < 0) return -1;
    if (oled_command(fd, 0x81) < 0) return -1;
    if (oled_command(fd, 0xCF) < 0) return -1;
    if (oled_command(fd, 0xD9) < 0) return -1;
    if (oled_command(fd, 0xF1) < 0) return -1;
    if (oled_command(fd, 0xDB) < 0) return -1;
    if (oled_command(fd, 0x40) < 0) return -1;
    if (oled_command(fd, 0xA4) < 0) return -1;
    if (oled_command(fd, 0xA6) < 0) return -1;
    if (oled_command(fd, 0xAF) < 0) return -1;
    return 0;
}

static int oled_clear(int fd) {
    unsigned char buf[OLED_WIDTH];
    memset(buf, 0x00, OLED_WIDTH);
    for (int page = 0; page < 8; page++) {
        if (oled_command(fd, 0xB0 + page) < 0) return -1;
        if (oled_command(fd, 0x00) < 0) return -1;
        if (oled_command(fd, 0x10) < 0) return -1;
        if (oled_data(fd, buf, OLED_WIDTH) < 0) return -1;
    }
    return 0;
}

static int read_cpu_temp(void) {
