            memcpy(char_data, font5x7[idx], 5);
            if (oled_command(fd, 0xB0 + (y / 8)) < 0) return -1;
            if (oled_command(fd, 0x00 + (x / 8)) < 0) return -1;
            if (oled_command(fd, 0x10 + ((x / 8) & 0x0F)) < 0) return -1;
            if (oled_data(fd, char_data, 5) < 0) return -1;
        }
        x += char_width;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigaction(SIGINT, &sa, NULL);

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s\n", strerror(errno));
        return 1;
    }
    if (ioctl(fd, I2C_SLAVE, OLED_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(fd);
        return 1;
    }
    if (oled_init(fd) < 0) {
        fprintf(stderr, "OLED init failed\n");
        close(fd);
        return 1;
    }
    if (oled_clear(fd) < 0) {
        fprintf(stderr, "OLED clear failed\n");
        close(fd);
        return 1;
    }

    while (running) {
        int cpu_temp = read_cpu_temp();
        int cpu_usage = read_cpu_usage();
        char temp_str[16];
        char usage_str[16];
        char error_str[64];

        if (cpu_temp < 0) {
            snprintf(error_str, sizeof(error_str), "Temp Read Error");
            cpu_temp = 0;
        } else {
            snprintf(temp_str, sizeof(temp_str), "CPU Temp: %d C", cpu_temp);
        }

        if (cpu_usage < 0) {
            snprintf(error_str, sizeof(error_str), "Usage Read Error");
            cpu_usage = 0;
        } else {
            snprintf(usage_str, sizeof(usage_str), "CPU Usage: %d%%", cpu_usage);
        }

        if (oled_clear(fd) < 0) {
            fprintf(stderr, "OLED clear failed in loop\n");
            break;
        }

        if (cpu_temp >= 0) {
            if (draw_string(fd, 0, 0, temp_str) < 0) {
                fprintf(stderr, "Failed to draw temp string\n");
                break;
            }
        } else {
            if (draw_string(fd, 0, 0, error_str) < 0) {
                fprintf(stderr, "Failed to draw error string\n");
                break;
            }
        }

        if (cpu_usage >= 0) {
            if (draw_string(fd, 0, 20, usage_str) < 0) {
                fprintf(stderr, "Failed to draw usage string\n");
                break;
            }
        } else {
            if (draw_string(fd, 0, 20, error_str) < 0) {
                fprintf(stderr, "Failed to draw error string\n");
                break;
            }
        }

        sleep(1);
    }

    oled_clear(fd);
    close(fd);
    return 0;
}

