#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>

// Configuration
#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04
#define PULSE_PER_LITER 100.0 // Example value, adjust based on your sensor
#define SAMPLE_INTERVAL 1.0   // seconds

// Global variables
static volatile sig_atomic_t running = 1;
static double total_volume = 0.0;
static double last_pulse_time = 0.0;
static int i2c_handle = -1;

// Function prototypes
void signal_handler(int signal);
void flow_sensor_callback(int gpio, int level, uint32_t tick, void *userdata);
double calculate_flow_rate(double current_time, double last_time);
void update_total_volume(double flow_rate, double time_elapsed);
void log_data(double flow_rate, double total_volume);
void lcd_init();
void lcd_send_byte(int bits, int mode);
void lcd_send_command(int cmd);
void lcd_send_data(char data);
void lcd_clear();
void lcd_set_cursor(int line);
void lcd_print(const char *str);
void lcd_update(double flow_rate, double total_volume);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

// Flow sensor callback function
void flow_sensor_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 1) { // Rising edge
        double current_time = (double)tick / 1000000.0; // Convert to seconds
        double flow_rate = calculate_flow_rate(current_time, last_pulse_time);
        update_total_volume(flow_rate, current_time - last_pulse_time);
        last_pulse_time = current_time;
    }
}

// Calculate flow rate in liters per second
double calculate_flow_rate(double current_time, double last_time) {
    if (last_time == 0.0) return 0.0;
    double time_elapsed = current_time - last_time;
    if (time_elapsed <= 0.0) return 0.0;
    return 1.0 / (time_elapsed / PULSE_PER_LITER);
}

// Update total volume
void update_total_volume(double flow_rate, double time_elapsed) {
    total_volume += flow_rate * time_elapsed;
}

// Log data to console
void log_data(double flow_rate, double total_volume) {
    printf("Flow Rate: %.2f L/s, Total Volume: %.2f L\n", flow_rate, total_volume);
}

// LCD functions
void lcd_init() {
    i2c_handle = i2cOpen(I2C_BUS, LCD_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        running = 0;
        return;
    }
    gpioDelay(50000); // Wait for LCD to power up
    lcd_send_command(0x33); // Initialize
    lcd_send_command(0x32); // Initialize
    lcd_send_command(0x06); // Cursor move direction
    lcd_send_command(0x0C); // Turn cursor off
    lcd_send_command(0x28); // 4-bit mode, 2 lines, 5x8 font
    lcd_send_command(0x01); // Clear display
    gpioDelay(2000); // Wait for clear
}

void lcd_send_byte(int bits, int mode) {
    int bits_high = mode | (bits & 0xF0) | LCD_BACKLIGHT;
    int bits_low = mode | ((bits << 4) & 0xF0) | LCD_BACKLIGHT;

    if (i2cWriteByte(i2c_handle, bits_high) < 0) {
        fprintf(stderr, "I2C write error (high): %d\n", i2cWriteByte(i2c_handle, bits_high));
        running = 0;
        return;
    }
    lcd_send_byte_enable(bits_high);

    if (i2cWriteByte(i2c_handle, bits_low) < 0) {
        fprintf(stderr, "I2C write error (low): %d\n", i2cWriteByte(i2c_handle, bits_low));
        running = 0;
        return;
    }
    lcd_send_byte_enable(bits_low);
}

void lcd_send_byte_enable(int data) {
    gpioWrite(FLOW_SENSOR_GPIO, 1); // Enable pin high
    gpioDelay(1000); // Enable pulse width >= 450ns
    gpioWrite(FLOW_SENSOR_GPIO, 0); // Enable pin low
    gpioDelay(1000); // Enable pulse width >= 450ns
}

void lcd_send_command(int cmd) {
    lcd_send_byte(cmd, LCD_CMD);
}

void lcd_send_data(char data) {
    lcd_send_byte(data, LCD_CHR);
}

void lcd_clear() {
    lcd_send_command(0x01);
    gpioDelay(2000);
}

void lcd_set_cursor(int line) {
    lcd_send_command(line);
}

void lcd_print(const char *str) {
    while (*str) {
        lcd_send_data(*str++);
    }
}

void lcd_update(double flow_rate, double total_volume) {
    char buffer[20];
    lcd_clear();
    lcd_set_cursor(LCD_LINE_1);
    snprintf(buffer, sizeof(buffer), "Flow: %.2f L/s", flow_rate);
    lcd_print(buffer);
    lcd_set_cursor(LCD_LINE_2);
    snprintf(buffer, sizeof(buffer), "Vol: %.2f L", total_volume);
    lcd_print(buffer);
}

// Cleanup function
void cleanup() {
    printf("\nCleaning up...\n");
    if (i2c_handle >= 0) {
        lcd_clear();
        lcd_send_command(0x01);
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input with pull-down resistor
    gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_DOWN);

    // Initialize LCD
    lcd_init();
    if (!running) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C and termination
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    // Set up interrupt handler for flow sensor
    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, flow_sensor_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for GPIO %d\n", FLOW_SENSOR_GPIO);
        cleanup();
        return 1;
    }

    time_t last_lcd_update = time(NULL);
    double last_flow_rate = 0.0;

    // Main loop
    while (running) {
        time_t current_time = time(NULL);
        double current_time_sec = (double)current_time;

        // Calculate flow rate for logging
        double flow_rate = calculate_flow_rate(current_time_sec, last_pulse_time);

        // Log data every second
        if (difftime(current_time, last_pulse_time) >= 1.0) {
            log_data(flow_rate, total_volume);
            last_pulse_time = current_time_sec;
        }

        // Update LCD every 10 seconds
        if (difftime(current_time, last_lcd_update) >= 10.0) {
            lcd_update(flow_rate, total_volume);
            last_lcd_update = current_time;
        }

        gpioDelay(100000); // 100ms delay to reduce CPU usage
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

