        g_pulse_count = 0;
        g_last_tick = gpioTick();

        /* Wait for sample interval */
        uint32_t start = gpioTick();
        while (g_running && (gpioTick() - start) < SAMPLE_INTERVAL_US) {
            gpioDelay(10000); /* 10 ms */
        }
        if (!g_running) break;

