    gpioSetISRFuncEx(ANEMOMETER_PIN, RISING_EDGE, 0, NULL, NULL); /* unregister ISR */
    lcd_clear();
    lcd_string("Shutting down");
    cleanup();
    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

