/* ---- Pin / bus definitions ---- */
#define ANEMOMETER_PIN 17          /* BCM GPIO17 - interrupt input */
#define I2C_BUS        1           /* /dev/i2c-1 */
#define LCD_ADDR       0x27        /* PCF8574 I2C address */
#define SPI_DEVICE     "/dev/spidev0.0" /* SPI0 CE0 */
#define SPI_SPEED_HZ   1000000     /* 1 MHz */
#define SPI_MODE       0

/* ---- Timing ---- */
#define SAMPLE_INTERVAL_US 500000  /* 500 ms */
#define DEBOUNCE_US        1000     /* 1 ms debounce */

/* ---- Globals for ISR ---- */
static volatile int g_pulse_count = 0;
static volatile uint32_t g_last_tick = 0;
static volatile sig_atomic_t g_running = 1;

/* ---- Resources ---- */
static int g_spi_fd = -1;
static int g_i2c_fd = -1;

/* ---- Function prototypes ---- */
static void anemometer_isr(int gpio, int level, uint32_t tick, void *userdata);
static int  read_mcp3008(int channel);
static int  lcd_init(void);
static void lcd_send_nibble(uint8_t nibble, uint8_t rs);
static void lcd_send_byte(uint8_t val, uint8_t rs);
static void lcd_command(uint8_t cmd);
static void lcd_data(uint8_t data);
static void lcd_string(const char *str);
static void lcd_clear(void);
static void lcd_set_cursor(int row, int col);
static void display_data(float wind_speed, int wind_dir);
static void cleanup(void);
static void signal_handler(int sig);

/* ---- ISR: rising edge, debounce ---- */
static void anemometer_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level != 1) return;                       /* only rising edge */
    if (tick - g_last_tick < DEBOUNCE_US) return;  /* debounce */
    g_last_tick = tick;
    g_pulse_count++;
}

/* ---- Read MCP3008 single-ended channel ---- */
static int read_mcp3008(int channel)
{
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    /*
     * MCP3008 SPI protocol (mode 0, MSB first):
     *   tx[0] = 0x01                 (start bit)
     *   tx[1] = (0x08 | channel)<<4  (single-ended + channel)
     *   tx[2] = 0x00                 (clock out remaining bits)
     * Result: rx[1] low 2 bits + rx[2] 8 bits = 10-bit value
     */
    uint8_t tx[3] = { 0x01, (uint8_t)((0x08 | channel) << 4), 0x00 };
    uint8_t rx[3] = { 0 };

    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 3;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = 8;
    tr.delay_usecs   = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }

    int adc_value = ((rx[1] & 0x03) << 8) | rx[2];
    return adc_value;
}

/* ---- LCD helpers (PCF8574 backpack) ---- */
static void lcd_send_nibble(uint8_t nibble, uint8_t rs)
{
    uint8_t data = (nibble & 0xF0) | (rs ? 0x01 : 0x00) | 0x04; /* EN=1 */
    if (write(g_i2c_fd, &data, 1) != 1)
        fprintf(stderr, "I2C write failed (EN high): %s\n", strerror(errno));
    gpioDelay(1);
    data &= ~0x04; /* EN=0 */
    if (write(g_i2c_fd, &data, 1) != 1)
        fprintf(stderr, "I2C write failed (EN low): %s\n", strerror(errno));
    gpioDelay(100); /* command execution time */
}

static void lcd_send_byte(uint8_t val, uint8_t rs)
{
    lcd_send_nibble(val >> 4, rs);
    lcd_send_nibble(val & 0x0F, rs);
}

static void lcd_command(uint8_t cmd)
{
    lcd_send_byte(cmd, 0);
}

static void lcd_data(uint8_t data)
{
    lcd_send_byte(data, 1);
}

static void lcd_string(const char *str)
{
    while (*str) lcd_data((uint8_t)*str++);
}

static void lcd_clear(void)
{
    lcd_command(0x01);
    gpioDelay(2000);
}

static void lcd_set_cursor(int row, int col)
{
    uint8_t addr = (row == 0) ? (0x00 + col) : (0x40 + col);
    lcd_command(0x80 | addr);
}

static int lcd_init(void)
{
    /* PCF8574 requires at least 40 us high time; pigpio I2C write is fast enough */
    gpioDelay(50000); /* 50 ms */

    /* Force 4-bit mode (HD44780 init sequence) */
    lcd_send_nibble(0x03, 0);
    gpioDelay(5000);
    lcd_send_nibble(0x03, 0);
    gpioDelay(1000);
    lcd_send_nibble(0x03, 0);
    gpioDelay(1000);
    lcd_send_nibble(0x02, 0); /* switch to 4-bit */
    gpioDelay(1000);

    lcd_command(0x28); /* 4-bit, 2-line, 5x8 font */
    lcd_command(0x0C); /* display on, cursor off, blink off */
    lcd_command(0x06); /* entry mode: increment, no shift */
    lcd_clear();
    return 0;
}

/* ---- Display wind speed and direction ---- */
static void display_data(float wind_speed, int wind_dir)
{
    char line1[17];
    char line2[17];

    snprintf(line1, sizeof(line1), "Spd: %.2f m/s", wind_speed);
    snprintf(line2, sizeof(line2), "Dir: %d deg", wind_dir);

    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_string(line1);
    lcd_set_cursor(1, 0);
    lcd_string(line2);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
}

