#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#define FLOW_SENSOR_GPIO 17
#define I2C_BUS 1
#define LCD_ADDR 0x27
#define LCD_WIDTH 16

#define LCD_CHR 1
#define LCD_CMD 0
#define LCD_LINE_1 0x80
#define LCD_LINE_2 0xC0
#define LCD_BACKLIGHT 0x08
#define ENABLE 0x04

static volatile sig_atomic_t running = 1;
static volatile int pulse_count = 0;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)tick; (void)userdata;
    if (level == 1) {
        pulse_count++;
    }
}

static int lcd_write_byte(uint8_t bits) {
    uint8_t buf[4];
    buf[0] = bits | LCD_BACKLIGHT;
    buf[1] = (bits | LCD_BACKLIGHT) | ENABLE;
    buf[2] = bits | LCD_BACKLIGHT;
    buf[3] = (bits | LCD_BACKLIGHT) & ~ENABLE;
    if (write(i2c_fd, buf, 4) != 4) {
        return -1;
    }
    usleep(1000);
    return 0;
}

static int lcd_send_byte(uint8_t val, uint8_t mode) {
    uint8_t high = mode | (val & 0xF0);
    uint8_t low = mode | ((val << 4) & 0xF0);
    if (lcd_write_byte(high) != 0) return -1;
    if (lcd_write_byte(low) != 0) return -1;
    return 0;
}

static int lcd_init(void) {
    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, LCD_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    usleep(50000);
    if (lcd_send_byte(0x33, LCD_CMD) != 0) return -1;
    if (lcd_send_byte(0x32, LCD_CMD) != 0) return -1;
    if (lcd_send_byte(0x28, LCD_CMD) != 0) return -1;
    if (lcd_send_byte(0x0C, LCD_CMD) != 0) return -1;
    if (lcd_send_byte(0x06, LCD_CMD) != 0) return -1;
    if (lcd_send_byte(0x01, LCD_CMD) != 0) return -1;
    usleep(2000);
    return 0;
}

static void lcd_clear(void) {
    lcd_send_byte(0x01, LCD_CMD);
    usleep(2000);
}

static void lcd_set_cursor(int row, int col) {
    uint8_t addr = (row == 0) ? LCD_LINE_1 : LCD_LINE_2;
    addr += col;
    lcd_send_byte(addr, LCD_CMD);
}

static void lcd_print(const char *str) {
    for (int i = 0; str[i] != '\0'; i++) {
        if (lcd_send_byte((uint8_t)str[i], LCD_CHR) != 0) {
            fprintf(stderr, "LCD write error at position %d\n", i);
            break;
        }
    }
}

static void display_flow_rate(float flow_rate) {
    char buffer[LCD_WIDTH + 1];
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_print("Flow Rate:");
    lcd_set_cursor(1, 0);
    snprintf(buffer, sizeof(buffer), "%.2f L/min", flow_rate);
    lcd_print(buffer);
}

static void display_error(const char *message) {
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_print("Error:");
    lcd_set_cursor(1, 0);
    lcd_print(message);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handlers");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    if (lcd_init() != 0) {
        fprintf(stderr, "LCD initialization failed\n");
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(FLOW_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", FLOW_SENSOR_GPIO);
        display_error("GPIO Init");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO %d\n", FLOW_SENSOR_GPIO);
        display_error("GPIO Pull");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFuncEx(FLOW_SENSOR_GPIO, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function on GPIO %d\n", FLOW_SENSOR_GPIO);
        display_error("GPIO Alert");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");
    display_flow_rate(0.0);

    int no_pulse_count = 0;
    const int no_pulse_threshold = 10;

    while (running) {
        pulse_count = 0;
        sleep(1);

        int count = pulse_count;
        float flow_rate = (float)count * 60.0;

        if (count == 0) {
            no_pulse_count++;
            if (no_pulse_count >= no_pulse_threshold) {
                display_error("Sensor Absent");
                fprintf(stderr, "Warning: No pulses detected for %d seconds. Sensor may be absent.\n", no_pulse_threshold);
            }
        } else {
            no_pulse_count = 0;
            display_flow_rate(flow_rate);
            printf("Flow Rate: %.2f L/min\n", flow_rate);
        }
    }

    printf("\nShutting down...\n");
    lcd_clear();
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    gpioTerminate();
    return 0;
}

