/*
 * 8x8 Common-Anode LED Matrix Wave Animation
 * Board: Raspberry Pi (40-pin header)
 * Wiring:
 *   Row anodes   -> GPIO 17, 18, 27, 22, 23, 24, 25, 4  (BCM)
 *   Column cathodes -> GPIO 5, 6, 12, 13, 19, 16, 26, 20 (BCM)
 *
 * Build: gcc -O2 -Wall -o led_matrix led_matrix.c -lpigpio -lrt
 * Run:   sudo ./led_matrix
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_ROWS    8
#define NUM_COLS    8
#define DELAY_US    800

/* BCM pin numbers */
static const int row_pins[NUM_ROWS] = {17, 18, 27, 22, 23, 24, 25, 4};
static const int col_pins[NUM_COLS] = {5, 6, 12, 13, 19, 16, 26, 20};

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Drive one row of the matrix.
 * Common anode: row HIGH (anode +) lights the row; column LOW (cathode -)
 * drives the LED.
 */
static int drive_row(int row, int col) {
    for (int r = 0; r < NUM_ROWS; r++) {
        if (gpioWrite(row_pins[r], (r == row) ? 1 : 0) < 0) {
            fprintf(stderr, "Error: gpioWrite failed on row pin %d\n", row_pins[r]);
            return -1;
        }
    }
    for (int c = 0; c < NUM_COLS; c++) {
        if (gpioWrite(col_pins[c], (c == col) ? 0 : 1) < 0) {
            fprintf(stderr, "Error: gpioWrite failed on col pin %d\n", col_pins[c]);
            return -1;
        }
    }
    return 0;
}

/*
 * Clear the matrix: all rows LOW, all columns HIGH (off).
 */
static int clear_matrix(void) {
    for (int r = 0; r < NUM_ROWS; r++) {
        if (gpioWrite(row_pins[r], 0) < 0) {
            fprintf(stderr, "Error: gpioWrite failed on row pin %d\n", row_pins[r]);
            return -1;
        }
    }
    for (int c = 0; c < NUM_COLS; c++) {
        if (gpioWrite(col_pins[c], 1) < 0) {
            fprintf(stderr, "Error: gpioWrite failed on col pin %d\n", col_pins[c]);
            return -1;
        }
    }
    return 0;
}

/*
 * Render a single frame of the wave animation.
 * left_to_right: 1 = wave moves left->right, 0 = right->left.
 */
static int render_frame(int frame, int left_to_right) {
    for (int r = 0; r < NUM_ROWS; r++) {
        for (int c = 0; c < NUM_COLS; c++) {
            int col = left_to_right ? c : (NUM_COLS - 1 - c);
            int val = (abs(col - frame) <= 1) ? 1 : 0;
            if (drive_row(r, val ? col : -1) < 0)
                return -1;
            gpioDelay(DELAY_US);
        }
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure row pins as outputs, column pins as outputs */
    for (int i = 0; i < NUM_ROWS; i++) {
        if (gpioSetMode(row_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed on row pin %d\n", row_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }
    for (int i = 0; i < NUM_COLS; i++) {
        if (gpioSetMode(col_pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode failed on col pin %d\n", col_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Start with matrix cleared */
    if (clear_matrix() < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        clear_matrix();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int frame = 0;
    while (running) {
        if (render_frame(frame, 1) < 0) {
            fprintf(stderr, "Error: render_frame (left) failed\n");
            break;
        }
        frame = (frame + 1) % NUM_COLS;

        if (!running) break;

        if (render_frame(frame, 0) < 0) {
            fprintf(stderr, "Error: render_frame (right) failed\n");
            break;
        }
        frame = (frame + 1) % NUM_COLS;
    }

    /* Cleanup: turn off all LEDs and release GPIO */
    clear_matrix();
    gpioTerminate();
    return EXIT_SUCCESS;
}

