/*
 * wave_led_matrix.c — 8x8 common-anode LED matrix wave animation
 *
 * Board: Raspberry Pi (40-pin header, BCM numbering)
 *
 * Wiring:
 *   Row anodes   -> GPIO 2, 3, 4, 17, 27, 22, 10, 9  (BCM)
 *   Column cathodes -> GPIO 14, 15, 18, 23, 24, 25, 8, 7 (BCM)
 *
 * Common-anode LED: anode -> row, cathode -> column (via resistor).
 * Cathode LOW lights the column; anode HIGH de-energizes the row.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o wave_led_matrix wave_led_matrix.c -lgpiod
 *
 * Run:
 *   sudo ./wave_led_matrix
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_ROWS    8
#define NUM_COLS    8
#define DELAY_MS    150

/* BCM pin numbers */
static const unsigned int row_pins[NUM_ROWS] = {2, 3, 4, 17, 27, 22, 10, 9};
static const unsigned int col_pins[NUM_COLS] = {14, 15, 18, 23, 24, 25, 8, 7};

static volatile sig_atomic_t g_running = 1;

static void sighandler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/*
 * Clear the matrix: all column cathodes HIGH (off) and all row anodes LOW
 * (all rows de-energized, no current flowing through any LED).
 */
static int matrix_clear(struct gpiod_line_bulk *rows, struct gpiod_line_bulk *cols)
{
    if (gpiod_line_set_value_bulk(cols, 1) < 0) {
        perror("gpiod_line_set_value_bulk(cols, HIGH)");
        return -1;
    }
    if (gpiod_line_set_value_bulk(rows, 0) < 0) {
        perror("gpiod_line_set_value_bulk(rows, LOW)");
        return -1;
    }
    return 0;
}

/*
 * Light the wave pattern for one column.
 * Column cathode LOW (cathode off) lights the column; all row anodes HIGH
 * (rows off) de-energizes the LED.
 */
static int matrix_wave_col(struct gpiod_line_bulk *rows,
                           struct gpiod_line_bulk *cols,
                           int col)
{
    if (gpiod_line_set_value_bulk(cols, 1) < 0) {
        perror("gpiod_line_set_value_bulk(cols, HIGH)");
        return -1;
    }
    if (gpiod_line_set_value_bulk(rows, 0) < 0) {
        perror("gpiod_line_set_value_bulk(rows, LOW)");
        return -1;
    }

    /* Light LEDs sequentially in the current column */
    for (int r = 0; r < NUM_ROWS; r++) {
        if (gpiod_line_set_value(rows, row_pins[r], 1) < 0) {
            fprintf(stderr, "Failed to set row %d HIGH\n", r);
            return -1;
        }
        usleep(10000); /* 10 ms per LED */
    }

    /* Turn off the current column cathode so no LED stays on */
    if (gpiod_line_set_value(cols, col_pins[col], 1) < 0) {
        perror("gpiod_line_set_value(cols, cathode HIGH)");
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk rows, cols;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip0\")");
        return EXIT_FAILURE;
    }

    gpiod_line_bulk_init(&rows);
    gpiod_line_bulk_init(&cols);

    for (int i = 0; i < NUM_ROWS; i++) {
        struct gpiod_line *l = gpiod_chip_get_line(chip, row_pins[i]);
        if (!l) {
            fprintf(stderr, "Failed to get row line %u\n", row_pins[i]);
            goto cleanup;
        }
        gpiod_line_bulk_add(&rows, l);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        struct gpiod_line *l = gpiod_chip_get_line(chip, col_pins[i]);
        if (!l) {
            fprintf(stderr, "Failed to get column line %u\n", col_pins[i]);
            goto cleanup;
        }
        gpiod_line_bulk_add(&cols, l);
    }

    /* Request row anodes as outputs, initial LOW */
    if (gpiod_line_request_bulk_output(&rows, "wave_led_matrix", 0) < 0) {
        perror("gpiod_line_request_bulk_output(rows)");
        goto cleanup;
    }
    /* Request column cathodes as outputs, initial HIGH (off) */
    if (gpiod_line_request_bulk_output(&cols, "wave_led_matrix", 1) < 0) {
        perror("gpiod_line_request_bulk_output(cols)");
        goto cleanup;
    }

    if (matrix_clear(&rows, &cols) != 0)
        goto cleanup;

    while (g_running) {
        for (int c = 0; c < NUM_COLS && g_running; c++) {
            if (matrix_wave_col(&rows, &cols, c) != 0)
                goto cleanup;
            usleep(DELAY_MS * 1000);
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure matrix is cleared before releasing */
    if (chip) {
        matrix_clear(&rows, &cols);
        gpiod_line_release_bulk(&rows);
        gpiod_line_release_bulk(&cols);
        gpiod_chip_close(chip);
    }
    return ret;
}

