/*
 * VL53L3CX Multi-Target Distance Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   VL53L3CX SDA -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   VL53L3CX SCL -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   VL53L3CX VDD -> 3.3 V (pin 1)
 *   VL53L3CX GND -> GND (pin 6)
 *   VL53L3CX XSHUT -> GPIO17 (pin 11, optional; tied high for single device)
 *
 * Build: gcc -O2 -Wall -o vl53l3cx_reader vl53l3cx_reader.c -lpigpio -lrt
 * Run:   sudo ./vl53l3cx_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L3CX I2C constants ---- */
#define I2C_BUS              1
#define VL53L3CX_ADDR        0x29
#define VL53L3CX_XSHUT_PIN   17

/* ---- VL53L3CX register map (subset) ---- */
#define REG_MODEL_ID         0x010F
#define REG_SYSTEM_START     0x0000
#define REG_RESULT_INT_STATUS 0x0044
#define REG_RESULT_RANGE_STATUS 0x0089
#define REG_RESULT_NUM_TARGETS 0x008A
#define REG_RESULT_SPHERE_TARGET 0x008B
#define REG_RESULT_TARGET_0_DIST 0x0096
#define REG_RESULT_TARGET_1_DIST 0x0098
#define REG_RESULT_TARGET_2_DIST 0x009A
#define REG_RESULT_TARGET_3_DIST 0x009C
#define REG_RESULT_TARGET_4_DIST 0x009E

#define EXPECTED_MODEL_ID     0xEA

/* ---- Globals for cleanup ---- */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint32_t len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int vl53l3cx_init(int handle)
{
    uint8_t model_id = 0;

    /* Verify model ID */
    if (i2c_read_reg16(handle, REG_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: failed to read model ID (sensor absent or bus error).\n");
        return -1;
    }
    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X).\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L3CX detected (model ID 0x%02X).\n", model_id);

    /*
     * NOTE: The VL53L3CX uses a proprietary firmware that must be loaded
     * via I2C.  The exact sequence is defined by STMicroelectronics and
     * varies per sensor revision.  This stub performs the high-level
     * handshake and mandatory register writes required to start ranging.
     *
     * In a production environment, replace the contents of this function
     * with the official ST firmware download and initialization sequence.
     */

    /* 1. Software reset */
    if (i2c_write_reg16(handle, 0x0000, 0x00) < 0) {
        fprintf(stderr, "Error: software reset write failed.\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    /* 2. Start ranging (mode 1 = continuous back-to-back) */
    if (i2c_write_reg16(handle, REG_SYSTEM_START, 0x01) < 0) {
        fprintf(stderr, "Error: failed to start ranging.\n");
        return -1;
    }

    printf("VL53L3CX initialized and ranging started.\n");
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read and print multi-target results                                 */
/* ------------------------------------------------------------------ */
static void read_and_print_targets(int handle)
{
    uint8_t status = 0;
    uint8_t num_targets = 0;
    uint16_t dist[5] = {0};
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    /* Poll interrupt status */
    if (i2c_read_reg16(handle, REG_RESULT_INT_STATUS, &status, 1) < 0) {
        fprintf(stderr, "Warning: failed to read interrupt status.\n");
        return;
    }

    if (!(status & 0x01)) {
        /* No new data yet */
        return;
    }

    /* Read number of targets */
    if (i2c_read_reg16(handle, REG_RESULT_NUM_TARGETS, &num_targets, 1) < 0) {
        fprintf(stderr, "Warning: failed to read number of targets.\n");
        return;
    }

    if (num_targets > 5) num_targets = 5;

    /* Read distances for each target */
    for (int i = 0; i < num_targets; i++) {
        uint16_t reg = REG_RESULT_TARGET_0_DIST + (uint16_t)(i * 2);
        if (i2c_read_reg16(handle, reg, (uint8_t *)&dist[i], 2) < 0) {
            fprintf(stderr, "Warning: failed to read distance for target %d.\n", i);
            dist[i] = 0;
        }
    }

    /* Timestamp */
    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    /* Print */
    printf("%s: Targets: %u", timestamp, num_targets);
    for (int i = 0; i < num_targets; i++) {
        printf("  Target %d: %u mm", i, dist[i]);
    }
    printf("\n");
    fflush(stdout);

    /* Clear interrupt by writing to status register */
    i2c_write_reg16(handle, REG_RESULT_INT_STATUS, 0x01);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        /* Stop ranging */
        i2c_write_reg16(i2c_handle, REG_SYSTEM_START, 0x00);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure XSHUT pin (optional) */
    gpioSetMode(VL53L3CX_XSHUT_PIN, PI_OUTPUT);
    gpioWrite(VL53L3CX_XSHUT_PIN, 1); /* Active high */
    gpioDelay(1000); /* 1 ms settle */

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, VL53L3CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X.\n",
                I2C_BUS, VL53L3CX_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l3cx_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L3CX initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Reading distances every 100 ms. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        read_and_print_targets(i2c_handle);
        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

