#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS "/dev/i2c-1"
#define MLX75031_ADDR 0x29
#define LOG_FILE "depth_log.csv"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_sensor(void) {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, MLX75031_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }
    return 0;
}

static void close_sensor(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
}

static int read_distance(uint16_t *distance) {
    uint16_t raw;
    if (i2c_read_reg16(i2c_fd, 0x00, &raw) < 0) {
        return -1;
    }
    *distance = raw;
    return 0;
}

static int log_data(uint16_t distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    if (fprintf(log_file, "%s,%u\n", timestamp, distance) < 0) {
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("Failed to set SIGINT handler");
        return 1;
    }

    if (init_sensor() < 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close_sensor();
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance\n");
        fflush(log_file);
    }

    while (running) {
        uint16_t distance;
        if (read_distance(&distance) < 0) {
            fprintf(stderr, "I2C read error, attempting to re-open bus...\n");
            close_sensor();
            usleep(1000000);
            if (init_sensor() < 0) {
                fprintf(stderr, "Re-initialization failed, exiting.\n");
                break;
            }
            if (log_data((uint16_t)-1) < 0) {
                fprintf(stderr, "Failed to log error data.\n");
            }
        } else {
            if (log_data(distance) < 0) {
                fprintf(stderr, "Failed to log data.\n");
            }
        }
        usleep(SAMPLE_INTERVAL_US);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }
    close_sensor();
    return 0;
}

