#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

/* Si1145 I2C address (ADDR pin tied to GND) */
#define SI1145_ADDR 0x60

/* Si1145 register addresses */
#define SI1145_REG_PART_ID       0x00
#define SI1145_REG_HW_KEY        0x07
#define SI1145_REG_MEAS_RATE0    0x08
#define SI1145_REG_MEAS_RATE1    0x09
#define SI1145_REG_PS_LED21      0x0F
#define SI1145_REG_PS1_DATA0     0x10
#define SI1145_REG_PS1_DATA1     0x11
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_ALS_VIS_DATA1 0x23
#define SI1145_REG_COMMAND       0x18

/* Si1145 command codes */
#define SI1145_CMD_RESET         0x01
#define SI1145_CMD_PS_FORCE      0x05
#define SI1145_CMD_ALS_FORCE     0x06
#define SI1145_CMD_PSALS_FORCE   0x07

/* Expected PART_ID for Si1145 */
#define SI1145_PART_ID_EXPECTED  0x45

/* Global resources for signal handler */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — clean shutdown on SIGINT / SIGTERM                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a Si1145 register                                 */
/* ------------------------------------------------------------------ */
static int si1145_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %s\n",
                reg, value, strerror(errno));
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a Si1145 register                                */
/* ------------------------------------------------------------------ */
static int si1145_read_reg(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %s\n",
                reg, strerror(errno));
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Send a command to the Si1145 COMMAND register                       */
/* ------------------------------------------------------------------ */
static int si1145_command(int handle, uint8_t cmd)
{
    return si1145_write_reg(handle, SI1145_REG_COMMAND, cmd);
}

/* ------------------------------------------------------------------ */
/* Initialize the Si1145 sensor                                        */
/* ------------------------------------------------------------------ */
static int si1145_init(int handle)
{
    int part_id;

    /* 1. Software reset */
    if (si1145_command(handle, SI1145_CMD_RESET) < 0) {
        fprintf(stderr, "[ERROR] Si1145 reset failed\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle after reset */

    /* 2. Verify PART_ID */
    part_id = si1145_read_reg(handle, SI1145_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "[ERROR] Cannot read PART_ID — sensor absent or bus error\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID_EXPECTED) {
        fprintf(stderr, "[ERROR] Unexpected PART_ID 0x%02X (expected 0x%02X)\n",
                part_id, SI1145_PART_ID_EXPECTED);
        return -1;
    }

    /* 3. Write HW_KEY (required by datasheet) */
    if (si1145_write_reg(handle, SI1145_REG_HW_KEY, 0x17) < 0) {
        fprintf(stderr, "[ERROR] Failed to write HW_KEY\n");
        return -1;
    }

    /* 4. Configure LED current for PS1 (LED1) — ~22.4 mA */
    if (si1145_write_reg(handle, SI1145_REG_PS_LED21, 0x0F) < 0) {
        fprintf(stderr, "[ERROR] Failed to configure PS_LED21\n");
        return -1;
    }

    /* 5. Set measurement rate to 0 (manual / forced mode) */
    if (si1145_write_reg(handle, SI1145_REG_MEAS_RATE0, 0x00) < 0) {
        fprintf(stderr, "[ERROR] Failed to set MEAS_RATE0\n");
        return -1;
    }
    if (si1145_write_reg(handle, SI1145_REG_MEAS_RATE1, 0x00) < 0) {
        fprintf(stderr, "[ERROR] Failed to set MEAS_RATE1\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read proximity and ambient light data                               */
/* ------------------------------------------------------------------ */
static int si1145_read_data(int handle, uint16_t *proximity, uint16_t *ambient)
{
    int ps0, ps1, als0, als1;

    /* Force a PS + ALS measurement */
    if (si1145_command(handle, SI1145_CMD_PSALS_FORCE) < 0) {
        return -1;
    }
    gpioDelay(10000); /* 10 ms conversion time */

    /* Read 16-bit proximity (PS1) */
    ps0 = si1145_read_reg(handle, SI1145_REG_PS1_DATA0);
    ps1 = si1145_read_reg(handle, SI1145_REG_PS1_DATA1);
    if (ps0 < 0 || ps1 < 0) {
        return -1;
    }
    *proximity = (uint16_t)((ps1 << 8) | ps0);

    /* Read 16-bit ambient light (ALS_VIS) */
    als0 = si1145_read_reg(handle, SI1145_REG_ALS_VIS_DATA0);
    als1 = si1145_read_reg(handle, SI1145_REG_ALS_VIS_DATA1);
    if (als0 < 0 || als1 < 0) {
        return -1;
    }
    *ambient = (uint16_t)((als1 << 8) | als0);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a reading to the log file                                    */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, uint16_t proximity, uint16_t ambient)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(fp, "%s, Proximity: %u, Ambient: %u\n",
            timestamp, proximity, ambient);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    uint16_t proximity, ambient;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1145 address */
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %s\n",
                SI1145_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (si1145_init(i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] Si1145 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open biometric_log.txt: %s\n",
                strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si1145 logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (program_running) {
        if (si1145_read_data(i2c_handle, &proximity, &ambient) == 0) {
            log_data(log_file, proximity, ambient);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed — continuing\n");
        }
        gpioDelay(500000); /* 500 ms */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

