#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* Si1145 I2C address (7-bit) */
#define SI1145_ADDR 0x60

/* Si1145 register addresses */
#define SI1145_REG_PART_ID    0x00
#define SI1145_REG_HW_KEY     0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_ALS_RATE   0x09
#define SI1145_REG_PS_RATE    0x0A
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_PS1_DATA0  0x26

/* Si1145 command register and values */
#define SI1145_REG_COMMAND    0x18
#define SI1145_CMD_RESET      0x01
#define SI1145_CMD_ALS_FORCE  0x06
#define SI1145_CMD_PS_FORCE   0x05
#define SI1145_CMD_PSALS_FORCE 0x07

/* Expected PART_ID for Si1145 */
#define SI1145_PART_ID_EXPECTED 0x45

/* Globals for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a byte to a Si1145 register; returns 0 on success, -1 on error */
static int si1145_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %d\n", value, reg, rc);
        return -1;
    }
    return 0;
}

/* Read a byte from a Si1145 register; returns value (0-255) or -1 on error */
static int si1145_read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    return rc;
}

/* Read a 16-bit little-endian value from two consecutive registers */
static int si1145_read_reg16(int handle, uint8_t reg) {
    int lo = si1145_read_reg(handle, reg);
    if (lo < 0) return -1;
    int hi = si1145_read_reg(handle, reg + 1);
    if (hi < 0) return -1;
    return (hi << 8) | lo;
}

/* Initialize the Si1145 sensor; returns 0 on success, -1 on error */
static int si1145_init(int handle) {
    /* Verify PART_ID */
    int part_id = si1145_read_reg(handle, SI1145_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART_ID\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X)\n",
                part_id, SI1145_PART_ID_EXPECTED);
        return -1;
    }
    printf("Si1145 detected (PART_ID = 0x%02X)\n", part_id);

    /* Reset the device */
    if (si1145_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms delay after reset */

    /* Write HW_KEY (required after reset) */
    if (si1145_write_reg(handle, SI1145_REG_HW_KEY, 0x17) < 0)
        return -1;

    /* Set measurement rates (0x00 = disabled, 0xFF = 255 ms) */
    if (si1145_write_reg(handle, SI1145_REG_MEAS_RATE0, 0x00) < 0)
        return -1;
    if (si1145_write_reg(handle, SI1145_REG_ALS_RATE, 0x00) < 0)
        return -1;
    if (si1145_write_reg(handle, SI1145_REG_PS_RATE, 0x00) < 0)
        return -1;

    return 0;
}

/* Read proximity and ambient light data; returns 0 on success, -1 on error */
static int read_si1145_data(int handle, int *proximity, int *ambient_light) {
    /* Force a PS + ALS measurement */
    if (si1145_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_PSALS_FORCE) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms for conversion */

    int als = si1145_read_reg16(handle, SI1145_REG_ALS_VIS_DATA0);
    if (als < 0) return -1;
    *ambient_light = als;

    int ps = si1145_read_reg16(handle, SI1145_REG_PS1_DATA0);
    if (ps < 0) return -1;
    *proximity = ps;

    return 0;
}

/* Log data to file in CSV format */
static void log_data(FILE *fp, int proximity, int ambient_light) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(fp, "%s,%d,%d\n", timestamp, proximity, ambient_light);
    fflush(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x60 */
    i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %d\n", SI1145_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the Si1145 sensor */
    if (si1145_init(i2c_handle) < 0) {
        fprintf(stderr, "Si1145 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open the log file in append mode */
    log_file = fopen("biometric_data.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }

    printf("Logging proximity and ambient light data to biometric_data.log (Ctrl+C to stop)\n");

    /* Main loop */
    while (!terminate) {
        int proximity, ambient_light;

        if (read_si1145_data(i2c_handle, &proximity, &ambient_light) == 0) {
            log_data(log_file, proximity, ambient_light);
            printf("Proximity: %d, Ambient Light: %d\n", proximity, ambient_light);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(1000000); /* 1 second delay (microseconds) */
    }

    /* Cleanup */
    printf("\nCleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

