#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    27

#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   30000   /* 30 ms */
#define POLL_DELAY_US     10000   /* 10 ms */
#define LOG_INTERVAL_S    60
#define MIN_DISTANCE_CM   2.0f
#define MAX_DISTANCE_CM   400.0f
#define WATER_THRESHOLD_CM 15.0f
#define SPEED_OF_SOUND_CM_PER_US 0.0343f

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in centimetres.
 * Returns 0 on success, -1 on timeout (no echo), -2 on out-of-range.
 */
static int measure_distance(float *distance_cm)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(trigger, 0) failed\n");
        return -1;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "gpioWrite(trigger, 1) failed\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "gpioWrite(trigger, 0) failed\n");
        return -1;
    }

    /* Wait for echo rising edge (timeout 30 ms) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Timeout waiting for echo rising edge\n");
            return -1;
        }
        gpioDelay(POLL_DELAY_US);
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout 30 ms) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Timeout waiting for echo falling edge\n");
            return -1;
        }
        gpioDelay(POLL_DELAY_US);
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float dist = (float)pulse_us * SPEED_OF_SOUND_CM_PER_US / 2.0f;

    if (dist < MIN_DISTANCE_CM || dist > MAX_DISTANCE_CM) {
        fprintf(stderr, "Distance out of range: %.2f cm\n", dist);
        return -2;
    }

    *distance_cm = dist;
    return 0;
}

static void log_data(float distance_cm, const char *status)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (g_log_file) {
        fprintf(g_log_file, "%s, Distance: %.2f cm, Status: %s\n",
