#define APDS9960_GFIFO_CONFIG73 0xFE
#define APDS9960_GFIFO_CONFIG74 0xFF

/* Proximity threshold */
#define PROXIMITY_THRESHOLD 200

/* Global variables */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static int init_apds9960(void);
static int read_proximity(void);
static int read_rgb(void);
static void log_data(int r, int g, int b, int proximity);
static void signal_handler(int sig);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* Initialize the APDS9960 sensor */
static int init_apds9960(void) {
    /* Disable all features first */
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x00) < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %s\n", strerror(errno));
        return -1;
    }

    /* Set ATIME (integration time) to 256 cycles (~2.4 ms) */
    if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xFF) < 0) {
        fprintf(stderr, "Error writing to ATIME register: %s\n", strerror(errno));
        return -1;
    }

    /* Set WTIME (wait time) to 256 cycles (~2.4 ms) */
    if (i2cWriteByteData(i2c_handle, APDS9960_WTIME, 0xFF) < 0) {
        fprintf(stderr, "Error writing to WTIME register: %s\n", strerror(errno));
        return -1;
    }

    /* Set PPULSE (proximity pulse length) to 16 us */
    if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x40) < 0) {
        fprintf(stderr, "Error writing to PPULSE register: %s\n", strerror(errno));
        return -1;
    }

    /* Set control register: enable proximity engine, ALS gain 4x */
    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x03) < 0) {
        fprintf(stderr, "Error writing to CONTROL register: %s\n", strerror(errno));
        return -1;
    }

    /* Set CONFIG1: proximity enable, LED drive 100mA */
    if (i2cWriteByteData(i2c_handle, APDS9960_CONFIG1, 0x60) < 0) {
        fprintf(stderr, "Error writing to CONFIG1 register: %s\n", strerror(errno));
        return -1;
    }

    /* Set CONFIG2: proximity LED current 100mA */
    if (i2cWriteByteData(i2c_handle, APDS9960_CONFIG2, 0x60) < 0) {
        fprintf(stderr, "Error writing to CONFIG2 register: %s\n", strerror(errno));
        return -1;
    }

    /* Enable proximity engine */
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x40) < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* Read proximity value from the APDS9960 */
static int read_proximity(void) {
    int proximity = i2cReadByteData(i2c_handle, APDS9960_PDATA);
    if (proximity < 0) {
        fprintf(stderr, "Error reading proximity data: %s\n", strerror(errno));
        return -1;
    }
    return proximity;
}

/* Read RGB color values from the APDS9960 */
static int read_rgb(void) {
    int r, g, b;

    r = i2cReadWordData(i2c_handle, APDS9960_RDATAL);
    if (r < 0) {
        fprintf(stderr, "Error reading red data: %s\n", strerror(errno));
        return -1;
    }

    g = i2cReadWordData(i2c_handle, APDS9960_GDATAL);
    if (g < 0) {
        fprintf(stderr, "Error reading green data: %s\n", strerror(errno));
        return -1;
    }

    b = i2cReadWordData(i2c_handle, APDS9960_BDATAL);
    if (b < 0) {
        fprintf(stderr, "Error reading blue data: %s\n", strerror(errno));
        return -1;
    }

    /* Swap bytes (pigpio returns little-endian, APDS9960 is big-endian) */
    r = ((r & 0xFF) << 8) | ((r >> 8) & 0xFF);
    g = ((g & 0xFF) << 8) | ((g >> 8) & 0xFF);
    b = ((b & 0xFF) << 8) | ((b >> 8) & 0xFF);

    printf("R: %d, G: %d, B: %d\n", r, g, b);
    return 0;
}

/* Log data to the CSV file */
static void log_data(int r, int g, int b, int proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%d\n", timestamp, r, g, b, proximity);
    fflush(log_file);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 */
    i2c_handle = i2cOpen(1, APDS9960_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    /* Initialize APDS9960 */
    if (init_apds9960() < 0) {
        fprintf(stderr, "APDS9960 initialisation failed\n");
        cleanup();
        return 1;
    }

    /* Open log file */
    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,R,G,B,Proximity\n");
        fflush(log_file);
    }

    /* Set up signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("APDS9960 proximity sensor logging started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        int proximity = read_proximity();
        if (proximity >= 0) {
            if (read_rgb() == 0) {
                if (proximity > PROXIMITY_THRESHOLD) {
                    log_data(0, 0, 0, proximity); /* Placeholder values */
                }
            }
        } else {
            fprintf(stderr, "Error reading proximity, attempting to re-initialize I2C...\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000); /* 100 ms delay before retry */
            i2c_handle = i2cOpen(1, APDS9960_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %s\n", strerror(errno));
                terminate = 1;
            } else {
                if (init_apds9960() < 0) {
                    fprintf(stderr, "Error re-initializing APDS9960\n");
                    terminate = 1;
                }
            }
        }

        gpioDelay(100000); /* 100 ms delay */
    }

    /* Cleanup */
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

