#define SI1182_ADDR    0x60
#define CSV_FILE       "heartrate.csv"
#define SAMPLE_MS      100

/* Si1182 register addresses (placeholder values — confirm against datasheet) */
#define REG_HW_KEY     0x00
#define REG_MEAS_RATE  0x01
#define REG_PS1_DATA   0x02
#define REG_PS2_DATA   0x03
#define REG_PS3_DATA   0x04
#define REG_PS4_DATA   0x05

static volatile sig_atomic_t running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    if (i2c_smbus_write_byte_data(fd, reg, val) < 0) {
        perror("i2c_smbus_write_byte_data failed");
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    int v = i2c_smbus_read_byte_data(fd, reg);
    if (v < 0) {
        perror("i2c_smbus_read_byte_data failed");
        return -1;
    }
    *val = (uint8_t)v;
    return 0;
}

static int init_si1182(int fd)
{
    /* Write HW_KEY to enable sensor; value 0x17 is a common init sequence */
    if (i2c_write_reg8(fd, REG_HW_KEY, 0x17) < 0)
        return -1;
    usleep(10000);

    /* Set measurement rate to 100 ms (placeholder — adjust per datasheet) */
    if (i2c_write_reg8(fd, REG_MEAS_RATE, 0x64) < 0)
        return -1;
    usleep(10000);

    return 0;
}

static int read_proximity(int fd, uint8_t *ps1, uint8_t *ps2,
                          uint8_t *ps3, uint8_t *ps4)
{
    if (i2c_read_reg8(fd, REG_PS1_DATA, ps1) < 0) return -1;
    if (i2c_read_reg8(fd, REG_PS2_DATA, ps2) < 0) return -1;
    if (i2c_read_reg8(fd, REG_PS3_DATA, ps3) < 0) return -1;
    if (i2c_read_reg8(fd, REG_PS4_DATA, ps4) < 0) return -1;
    return 0;
}

static int calculate_bpm(uint8_t ps1, uint8_t ps2, uint8_t ps3, uint8_t ps4)
{
    /* Placeholder conversion: average of four proximity readings */
    int sum = ps1 + ps2 + ps3 + ps4;
    return sum / 4;
}

static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    localtime_r(&now, &tmv);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tmv);
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    int rc = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("open(" I2C_BUS ")");
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        goto cleanup;
    }

    if (init_si1182(fd) < 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        goto cleanup;
    }

    fp = fopen(CSV_FILE, "a");
    if (!fp) {
        perror("fopen(" CSV_FILE ")");
        goto cleanup;
    }

    while (running) {
        uint8_t ps1, ps2, ps3, ps4;

        if (read_proximity(fd, &ps1, &ps2, &ps3, &ps4) < 0) {
            fprintf(stderr, "Warning: I2C read failed, skipping sample\n");
            usleep(SAMPLE_MS * 1000);
            continue;
        }

        int bpm = calculate_bpm(ps1, ps2, ps3, ps4);

        char ts[32];
        get_timestamp(ts, sizeof(ts));

        if (fprintf(fp, "%s,%d\n", ts, bpm) < 0) {
            perror("fprintf");
            goto cleanup;
        }
        if (fflush(fp) != 0) {
            perror("fflush");
            goto cleanup;
        }

        usleep(SAMPLE_MS * 1000);
    }

    rc = EXIT_SUCCESS;

cleanup:
    if (fp) fclose(fp);
    if (fd >= 0) close(fd);
    return rc;
}

