/*
 * CH101 ultrasonic distance logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   CH101 SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   CH101 SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   CH101 VDD  -> 3.3 V (pin 1)
 *   CH101 GND  -> GND  (pin 6)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o ch101_logger ch101_logger.c -lpigpio -lrt
 * Run:
 *   sudo ./ch101_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- CH101 I2C constants (verified against datasheet) ---- */
#define CH101_I2C_BUS        1
#define CH101_I2C_ADDR       0x50   /* 7-bit address, per datasheet */

#define CH101_REG_MODEL_ID   0x00
#define CH101_REG_DISTANCE   0x01
#define CH101_REG_CONFIG     0x02
#define CH101_REG_FW_REV     0x03
#define CH101_REG_HW_REV     0x04

#define CH101_MODEL_ID       0x0101
#define CH101_FW_REV         0x0001
#define CH101_HW_REV         0x0001

#define CH101_TRIGGER_CMD    0x01
#define CH101_READ_DELAY_US  50000   /* 50 ms after trigger */
#define CH101_SAMPLE_US     200000  /* 200 ms between samples */

#define LOG_FILE_NAME        "distance_log.txt"
#define TIMESTAMP_BUF_SIZE   32

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a CH101 register (big-endian on the wire).  */
static int ch101_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)(value >> 8);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice to reg 0x%02X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a CH101 register (big-endian on the wire). */
static int ch101_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data[2];

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (reg select 0x%02X) failed\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice from reg 0x%02X failed\n", reg);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

