/*
 * Raspberry Pi Zero W – TDK InvenSense ICU-20201 ultrasonic ToF sensor reader.
 *
 * Wiring:
 *   ICU-20201 SDA  -> GPIO 2  (I2C bus 1 SDA)
 *   ICU-20201 SCL  -> GPIO 3  (I2C bus 1 SCL)
 *   ICU-20201 VDD  -> 3.3 V
 *   ICU-20201 GND  -> GND
 *   LED anode      -> GPIO 17 (BCM) via 330 Ω resistor -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o icu20201 icu20201.c -lpigpio -lrt
 * Run:
 *   sudo ./icu20201
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS            1
#define I2C_ADDR           0x40          /* default 7-bit I2C address */
#define GPIO_LED           17            /* BCM pin for the LED */
#define DISTANCE_THRESHOLD 20.0f         /* cm */
#define SAMPLE_PERIOD_US   100000        /* 100 ms */
#define LOG_FILE           "distance_log.txt"

/*
 * ICU-20201 register map (subset).
 * The full datasheet is available from InvenSense / TDK.
 */
#define REG_MODEL_ID       0x00
#define REG_FW_REV         0x01
#define REG_DISTANCE_MSB   0x20
#define REG_DISTANCE_LSB   0x21
#define REG_STATUS         0x22
#define REG_CONFIG         0x23

#define EXPECTED_MODEL_ID  0x01          /* placeholder – confirm with datasheet */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static bool g_gpio_initialized = false;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *out)
{
    int v = i2cReadByteData(handle, reg);
    if (v < 0) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed: %d\n", reg, v);
        return -1;
    }
    *out = (uint8_t)v;
    return 0;
}

static int i2c_write_reg8(int handle, uint8_t reg, uint8_t val)
{
    int r = i2cWriteByteData(handle, reg, val);
    if (r < 0) {
        fprintf(stderr, "[I2C] write reg 0x%02X = 0x%02X failed: %d\n",
                reg, val, r);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int sensor_init(int handle)
{
    uint8_t model_id = 0;

    if (i2c_read_reg8(handle, REG_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "[Sensor] cannot read MODEL_ID – sensor absent or bus error\n");
        return -1;
    }

    if (model_id != EXPECTED_MODEL_ID) {
        fprintf(stderr, "[Sensor] unexpected MODEL_ID 0x%02X (expected 0x%02X)\n",
                model_id, EXPECTED_MODEL_ID);
        return -1;
    }

    /*
     * Minimal configuration: enable continuous measurement, set a
     * reasonable default range.  Adjust REG_CONFIG and its fields
     * per the datasheet for your specific application.
     */
    if (i2c_write_reg8(handle, REG_CONFIG, 0x01) != 0) {
        fprintf(stderr, "[Sensor] failed to write CONFIG register\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Distance reading                                                   */
/* ------------------------------------------------------------------ */
static int read_distance(int handle, float *distance_cm)
{
    uint8_t msb = 0, lsb = 0;

    if (i2c_read_reg8(handle, REG_DISTANCE_MSB, &msb) != 0)
        return -1;
    if (i2c_read_reg8(handle, REG_DISTANCE_LSB, &lsb) != 0)
        return -1;

    uint16_t raw = ((uint16_t)msb << 8) | lsb;

    /*
     * Convert raw value to distance.
     * The exact formula depends on the ICU-20201 configuration;
     * this is a placeholder linear mapping.
     */
    *distance_cm = (float)raw * 0.1f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* LED control                                                         */
/* ------------------------------------------------------------------ */
static void control_led(float distance_cm)
{
    if (distance_cm < DISTANCE_THRESHOLD) {
        if (gpioWrite(GPIO_LED, 1) < 0)
            fprintf(stderr, "[GPIO] failed to turn LED on\n");
    } else {
        if (gpioWrite(GPIO_LED, 0) < 0)
            fprintf(stderr, "[GPIO] failed to turn LED off\n");
    }
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_distance(float distance_cm)
{
