    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("[Log] localtime_r");
        fclose(fp);
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "[Log] strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "%s, %.2f cm\n", ts, distance_cm);
    fclose(fp);
