    fprintf(fp, "%s, %.2f cm\n", ts, distance_cm);
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_gpio_initialized) {
        gpioWrite(GPIO_LED, 0);
        g_gpio_initialized = false;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[pigpio] initialisation failed\n");
        return EXIT_FAILURE;
    }
    g_gpio_initialized = true;

    /* --- I2C open --------------------------------------------------- */
