        fprintf(stderr, "[Sensor] initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- GPIO LED setup --------------------------------------------- */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) < 0) {
        fprintf(stderr, "[GPIO] setMode failed for pin %d\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    /* --- Signals ---------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("[Signal] sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ICU-20201 distance monitor running.  Ctrl+C to exit.\n");

