code:
/*
 * Si1182-GMR Proximity & Ambient Light Logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   Si1182 SDA -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   Si1182 SCL -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   Si1182 VDD -> 3.3 V
 *   Si1182 GND -> GND
 *
 * Build: gcc -O2 -Wall -o biometric_logger biometric_logger.c -lpigpio -lrt
 * Run:   sudo ./biometric_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Si1182-GMR I2C address ---- */
#define SI1182_ADDR 0x60

/* ---- Si1182-GMR register addresses ---- */
#define REG_PART_ID       0x00
#define REG_REV_ID        0x01
#define REG_SEQ_ID        0x02
#define REG_INT_CFG       0x03
#define REG_IRQ_ENABLE    0x04
#define REG_IRQ_MODE1     0x05
#define REG_IRQ_MODE2     0x06
#define REG_HW_KEY        0x07
#define REG_MEAS_RATE0    0x08
#define REG_MEAS_RATE1    0x09
#define REG_PS_LED21      0x0F
#define REG_PS1_DATA0     0x10
#define REG_PS1_DATA1     0x11
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_ALS_IR_DATA0  0x24
#define REG_ALS_IR_DATA1  0x25
#define REG_COMMAND       0x30

/* ---- Si1182-GMR command codes ---- */
#define CMD_RESET         0x01
#define CMD_PS_FORCE      0x05
#define CMD_ALS_FORCE     0x06
#define CMD_PSALS_FORCE   0x07

/* ---- Expected part ID ---- */
#define SI1182_PART_ID    0x82

/* ---- Globals for cleanup ---- */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- Write a byte to a register, retrying on transient errors ---- */
static int write_reg(uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < 3; attempt++) {
        int rc = i2cWriteByteData(i2c_handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "Warning: i2cWriteByteData(reg=0x%02X, val=0x%02X) failed (rc=%d), attempt %d/3\n",
                reg, value, rc, attempt + 1);
        gpioDelay(10000); /* 10 ms backoff */
    }
    return -1;
}

/* ---- Read a byte from a register, retrying on transient errors ---- */
static int read_reg(uint8_t reg, uint8_t *value)
{
    for (int attempt = 0; attempt < 3; attempt++) {
        int rc = i2cReadByteData(i2c_handle, reg);
        if (rc >= 0) {
            *value = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "Warning: i2cReadByteData(reg=0x%02X) failed (rc=%d), attempt %d/3\n",
                reg, rc, attempt + 1);
        gpioDelay(10000);
    }
    return -1;
}

/* ---- Read a 16-bit little-endian register pair ---- */
static int read_reg16(uint8_t reg_lo, uint16_t *out)
{
    uint8_t lo, hi;
    if (read_reg(reg_lo, &lo) != 0)
        return -1;
    if (read_reg(reg_lo + 1, &hi) != 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ---- Initialize the Si1182-GMR sensor ---- */
static int init_si1182(void)
{
    uint8_t part_id;

    /* Verify device identity */
    if (read_reg(REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error: Cannot read PART_ID — sensor absent or bus error.\n");
        return -1;
    }
    if (part_id != SI1182_PART_ID) {
        fprintf(stderr, "Error: Unexpected PART_ID 0x%02X (expected 0x%02X).\n",
                part_id, SI1182_PART_ID);
        return -1;
    }
    printf("Si1182-GMR detected (PART_ID=0x%02X).\n", part_id);

    /* Software reset */
    if (write_reg(REG_COMMAND, CMD_RESET) != 0) {
        fprintf(stderr, "Error: Software reset failed.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms settle after reset */

    /* Write HW_KEY to enable measurement engine */
    if (write_reg(REG_HW_KEY, 0x17) != 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY.\n");
        return -1;
    }

    /* Configure measurement rate: 0x08 = 500 ms between forced measurements */
    if (write_reg(REG_MEAS_RATE0, 0x08) != 0) {
        fprintf(stderr, "Error: Failed to set MEAS_RATE0.\n");
        return -1;
    }

    /* Configure LED current for PS1 (LED1) — ~22.4 mA typical */
    if (write_reg(REG_PS_LED21, 0x0F) != 0) {
        fprintf(stderr, "Error: Failed to set PS_LED21.\n");
        return -1;
    }

    /* Clear any pending interrupts */
    if (write_reg(REG_IRQ_MODE1, 0x00) != 0) {
        fprintf(stderr, "Warning: Failed to clear IRQ_MODE1.\n");
    }

    printf("Si1182-GMR initialized successfully.\n");
    return 0;
}

/* ---- Trigger a forced PS+ALS measurement and read results ---- */
static int read_sensor_data(uint16_t *proximity, uint16_t *ambient_light)
{
    uint8_t cmd = CMD_PSALS_FORCE;

    /* Send forced measurement command */
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, cmd) != 0) {
        fprintf(stderr, "Error: Failed to send measurement command.\n");
        return -1;
    }

    /* Wait for measurement to complete (max ~10 ms at 500 ms rate) */
    gpioDelay(15000);

    /* Read proximity (PS1) */
    if (read_reg16(REG_PS1_DATA0, proximity) != 0) {
        fprintf(stderr, "Error: Failed to read proximity data.\n");
        return -1;
    }

    /* Read ambient light (VIS channel) */
    if (read_reg16(REG_ALS_VIS_DATA0, ambient_light) != 0) {
        fprintf(stderr, "Error: Failed to read ambient light data.\n");
        return -1;
    }

    return 0;
}

/* ---- Append a timestamped reading to the log file ---- */
static int log_data(uint16_t proximity, uint16_t ambient_light)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s, Proximity: %u, Ambient Light: %u\n",
                timestamp, proximity, ambient_light) < 0) {
        fprintf(stderr, "Error: Failed to write to log file.\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

/* ---- Cleanup all resources ---- */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si1182-GMR address */
    i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (init_si1182() != 0) {
        fprintf(stderr, "Error: Si1182-GMR initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Cannot open biometric_log.txt for writing.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler.\n");
    }

    printf("Logging proximity and ambient light data to biometric_log.txt (Ctrl+C to stop).\n");

    /* Main sampling loop */
    while (!terminate) {
        uint16_t proximity, ambient_light;

        if (read_sensor_data(&proximity, &ambient_light) == 0) {
            if (log_data(proximity, ambient_light) != 0) {
                fprintf(stderr, "Error: Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Error: Sensor read failed, continuing...\n");
        }

        /* 500 ms sampling interval */
        gpioDelay(500000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

