/*
 * Raspberry Pi 4 Model B – TDK InvenSense ICU-20201 ToF Distance Monitor
 *
 * Reads distance (mm) from the ICU-20201 on I2C bus 1 (address 0x52),
 * lights an LED on GPIO 17 when distance < threshold, logs readings
 * to tof_log.txt, and exits cleanly on SIGINT.
 *
 * Build:  gcc -O2 -Wall -o tof_monitor tof_monitor.c -lpigpio -lrt
 * Run:    sudo ./tof_monitor [threshold_mm]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS            1
#define I2C_ADDR           0x52
#define LED_GPIO           17
#define LOG_FILE           "tof_log.txt"
#define POLL_DELAY_US      50000          /* 50 ms */
#define WHO_AM_I_EXPECTED  0x00           /* placeholder – confirm with datasheet */

/* ---- ICU-20201 register map (placeholder values) ---- */
#define REG_WHO_AM_I       0x01
#define REG_DISTANCE_MM    0x10
#define REG_STATUS         0x11

/* ---- Globals for cleanup ---- */
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian register from the ICU-20201.
 * Returns 0 on success, -1 on I2C error. */
static int read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];
    int  rc;

    rc = i2cWriteByte(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[I2C] write reg 0x%02X failed: %d\n", reg, rc);
        return -1;
    }

    rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "[I2C] read reg 0x%02X failed: got %d bytes\n", reg, rc);
        return -1;
    }

    *out = (uint16_t)((uint8_t)buf[0] | ((uint8_t)buf[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_sensor(void)
{
    uint16_t who_am_i = 0;

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[I2C] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }

    /* Verify device identity */
    if (read_reg16(g_i2c_handle, REG_WHO_AM_I, &who_am_i) < 0) {
        fprintf(stderr, "[Sensor] Cannot read WHO_AM_I – sensor absent or bus error.\n");
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    if (who_am_i != WHO_AM_I_EXPECTED) {
        fprintf(stderr, "[Sensor] WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                who_am_i, WHO_AM_I_EXPECTED);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }

    printf("[Sensor] ICU-20201 detected (WHO_AM_I=0x%04X).\n", who_am_i);
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_distance(uint16_t *distance_mm)
{
    uint16_t raw = 0;

    if (read_reg16(g_i2c_handle, REG_DISTANCE_MM, &raw) < 0)
        return -1;

    /* Basic sanity check: 0xFFFF is a sentinel for "no valid reading" */
    if (raw == 0xFFFF) {
        fprintf(stderr, "[Sensor] Invalid reading (0xFFFF).\n");
        return -1;
    }

    *distance_mm = raw;
    return 0;
}

/* ------------------------------------------------------------------ */
static void control_led(int on)
{
    if (gpioWrite(LED_GPIO, on ? 1 : 0) < 0)
        fprintf(stderr, "[GPIO] gpioWrite(%d) failed.\n", LED_GPIO);
}

/* ------------------------------------------------------------------ */
static void log_reading(uint16_t distance_mm)
{
    time_t     t;
    struct tm  tm_info;
    char       ts[32];

    t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "[Log] time() failed.\n");
        return;
    }

    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "[Log] localtime_r() failed.\n");
        return;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[Log] strftime() failed.\n");
        return;
    }

    if (fprintf(g_log_file, "%s, Distance: %u mm\n", ts, distance_mm) < 0)
        fprintf(stderr, "[Log] fprintf() failed.\n");

    if (fflush(g_log_file) != 0)
        fprintf(stderr, "[Log] fflush() failed.\n");
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    control_led(0);
    gpioSetMode(LED_GPIO, PI_INPUT);

    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    uint16_t distance_mm = 0;
    int      threshold   = 100;          /* default 100 mm */

    if (argc > 1) {
        threshold = atoi(argv[1]);
        if (threshold <= 0) {
            fprintf(stderr, "Usage: %s [threshold_mm]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[pigpio] Initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- GPIO setup ---- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[GPIO] gpioSetMode(%d, OUTPUT) failed.\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    control_led(0);

    /* ---- Log file ---- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[Log] Cannot open %s: ", LOG_FILE);
        perror("");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Sensor init ---- */
    if (init_sensor() < 0) {
        fprintf(stderr, "[Main] Sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Signal handling ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("[Signal] sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("[Signal] sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("[Main] Monitoring distance (threshold %d mm). Press Ctrl+C to exit.\n",
           threshold);

    /* ---- Main loop ---- */
    while (g_running) {
        if (read_distance(&distance_mm) == 0) {
            control_led(distance_mm < (uint16_t)threshold);
            log_reading(distance_mm);
        } else {
            /* On read failure, turn LED off for safety and retry next cycle */
            control_led(0);
        }
        gpioDelay(POLL_DELAY_US);
    }

    printf("\n[Main] Shutting down cleanly.\n");
    cleanup();
    return EXIT_SUCCESS;
}

