#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SENSOR_ADDR    0x29
#define LOG_FILE       "intrusion_log.txt"
#define MAX_DISTANCE   1000
#define NUM_SAMPLES    10
#define SAMPLE_DELAY   100000
#define MEASURE_DELAY  10000

/*
 * Omron B5L-LD50-07050 3D TOF sensor I2C protocol.
 *
 * Request measurement: write 4 bytes 0x00 0x00 0x00 0x00.
 * Response (15 bytes):
 *   [0]   0x02  (header)
 *   [1]   0x00  (reserved)
 *   [2]   0x00  (reserved)
 *   [3]   0x00  (reserved)
 *   [4]   0x00  (reserved)
 *   [5]   0x00  (reserved)
 *   [6]   0x00  (reserved)
 *   [7]   0x00  (reserved)
 *   [8]   0x00  (reserved)
 *   [9]   0x00  (reserved)
 *   [10]  0x00  (reserved)
 *   [11]  MSB of distance
 *   [12]  LSB of distance
 *   [13]  0x00  (reserved)
 *   [14]  0x00  (reserved)
 */
static const uint8_t MEASURE_CMD[4] = {0x00, 0x00, 0x00, 0x00};
static const uint8_t RESPONSE_HEADER = 0x02;
static const int RESPONSE_LEN = 15;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    ssize_t ret = write(fd, cmd, len);
    if (ret < 0) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)ret != len) {
        fprintf(stderr, "I2C write short: wrote %zd of %zu bytes\n", ret, len);
        return -1;
    }
    return 0;
}

static int i2c_read_response(int fd, uint8_t *buf, size_t len)
{
    ssize_t ret = read(fd, buf, len);
    if (ret < 0) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    if ((size_t)ret != len) {
        fprintf(stderr, "I2C read short: got %zd of %zu bytes\n", ret, len);
        return -1;
    }
    return 0;
}

static int read_distance(int fd, uint16_t *distance)
{
