 *   [1]   0x00  (reserved)
 *   [2]   0x00  (reserved)
 *   [3]   0x00  (reserved)
 *   [4]   0x00  (reserved)
 *   [5]   0x00  (reserved)
 *   [6]   0x00  (reserved)
 *   [7]   0x00  (reserved)
 *   [8]   0x00  (reserved)
 *   [9]   0x00  (reserved)
 *   [10]  0x00  (reserved)
 *   [11]  MSB of distance
 *   [12]  LSB of distance
 *   [13]  0x00  (reserved)
 *   [14]  0x00  (reserved)
