#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* VL53L0X I2C address (ADDR pin tied to GND) */
#define VL53L0X_ADDR 0x29

/* VL53L0X register addresses */
#define VL53L0X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L0X_REG_SYSTEM_MODE_START 0x0000
#define VL53L0X_REG_RESULT_INTERRUPT_STATUS 0x0044
#define VL53L0X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096

/* Expected model ID for VL53L0X */
#define VL53L0X_EXPECTED_MODEL_ID 0xEA

/* Global I2C handle for signal handler cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a 16-bit register address and 8-bit value to the sensor */
static int vl53l0x_write8(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "Error writing to register 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read an 8-bit value from a 16-bit register address */
static int vl53l0x_read8(int handle, uint16_t reg, uint8_t *value) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "Error writing register address 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    char data_buf[1];
    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        fprintf(stderr, "Error reading from register 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

/* Read a 16-bit value from a 16-bit register address (little-endian) */
static int vl53l0x_read16(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) != 2) {
        fprintf(stderr, "Error writing register address 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    char data_buf[2];
    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        fprintf(stderr, "Error reading from register 0x%04X: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)((data_buf[1] << 8) | data_buf[0]);
    return 0;
}

/* Initialize the VL53L0X sensor */
static int vl53l0x_init(int handle) {
    uint8_t model_id = 0;
    if (vl53l0x_read8(handle, VL53L0X_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Failed to read model ID.\n");
        return -1;
    }
    if (model_id != VL53L0X_EXPECTED_MODEL_ID) {
        fprintf(stderr, "Incorrect model ID: 0x%02X (expected 0x%02X). Sensor not present?\n",
                model_id, VL53L0X_EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L0X detected (Model ID: 0x%02X).\n", model_id);

    /* Start continuous ranging mode */
    if (vl53l0x_write8(handle, VL53L0X_REG_SYSTEM_MODE_START, 0x00) != 0) {
        fprintf(stderr, "Failed to start ranging.\n");
        return -1;
    }
    return 0;
}

/* Read distance from the VL53L0X sensor */
static int vl53l0x_read_distance(int handle, uint16_t *distance) {
    uint8_t status = 0;
    int timeout = 100; /* 100 ms timeout */

    /* Poll for data ready */
    while (timeout-- > 0) {
        if (vl53l0x_read8(handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, &status) != 0) {
            return -1;
        }
        if (status & 0x01) {
            break;
        }
        gpioDelay(1000); /* 1 ms */
    }

    if (timeout <= 0) {
        fprintf(stderr, "Timeout waiting for data ready.\n");
        return -1;
    }

    /* Read distance */
    if (vl53l0x_read16(handle, VL53L0X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, distance) != 0) {
        return -1;
    }

    /* Clear interrupt by writing 0x01 to RESULT_INTERRUPT_STATUS */
    if (vl53l0x_write8(handle, VL53L0X_REG_RESULT_INTERRUPT_STATUS, 0x01) != 0) {
        fprintf(stderr, "Warning: failed to clear interrupt.\n");
    }

    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 */
    i2c_handle = i2cOpen(1, VL53L0X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %s\n", VL53L0X_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (vl53l0x_init(i2c_handle) != 0) {
        fprintf(stderr, "VL53L0X initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Starting distance measurements. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        uint16_t distance = 0;
        if (vl53l0x_read_distance(i2c_handle, &distance) == 0) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("%s Distance: %u mm\n", timestamp, distance);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read distance. Continuing...\n");
        }

        gpioDelay(500000); /* 500 ms */
    }

    /* Cleanup */
    printf("\nCleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

