/* Si1182 I2C address (7-bit) */
#define SI1182_ADDR 0x60

/* Si1182 register addresses */
#define SI1182_REG_PART_ID       0x00
#define SI1182_REG_HW_REV        0x01
#define SI1182_REG_SEQ_ID        0x02
#define SI1182_REG_INT_CFG       0x03
#define SI1182_REG_IRQ_ENABLE    0x04
#define SI1182_REG_IRQ_MODE1     0x05
#define SI1182_REG_IRQ_MODE2     0x06
#define SI1182_REG_HW_KEY        0x07
#define SI1182_REG_MEAS_RATE0    0x08
#define SI1182_REG_MEAS_RATE1    0x09
#define SI1182_REG_PS_LED21      0x0F
#define SI1182_REG_PS1_DATA0     0x10
#define SI1182_REG_PS1_DATA1     0x11
#define SI1182_REG_PS2_DATA0     0x12
#define SI1182_REG_PS2_DATA1     0x13
#define SI1182_REG_PS3_DATA0     0x14
#define SI1182_REG_PS3_DATA1     0x15
#define SI1182_REG_PS4_DATA0     0x16
#define SI1182_REG_PS4_DATA1     0x17
#define SI1182_REG_PS_LED3       0x18
#define SI1182_REG_PARAM_WR      0x17
#define SI1182_REG_COMMAND       0x18
#define SI1182_REG_RESPONSE      0x20

/* Si1182 command codes */
#define SI1182_CMD_RESET         0x01
#define SI1182_CMD_PS_FORCE      0x05
#define SI1182_CMD_PS_AUTO       0x06
#define SI1182_CMD_PARAM_QUERY   0x80
#define SI1182_CMD_PARAM_SET     0xA0

/* Si1182 parameter offsets */
#define SI1182_PARAM_CHLIST      0x01
#define SI1182_PARAM_PSLED12     0x02
#define SI1182_PARAM_PS1_ADCMUX  0x03
#define SI1182_PARAM_PS2_ADCMUX  0x04
#define SI1182_PARAM_PS3_ADCMUX  0x05
#define SI1182_PARAM_PS4_ADCMUX  0x06

/* Expected PART_ID for Si1182 */
#define SI1182_PART_ID_EXPECTED  0x82

/* Global I2C handle */
static int i2c_handle = -1;

/* Volatile flag for signal handling */
static volatile sig_atomic_t running = 1;

/* Signal handler for Ctrl+C */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a byte to a Si1182 register */
static int si1182_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

/* Read a byte from a Si1182 register */
static int si1182_read_reg(uint8_t reg) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

/* Read a 16-bit little-endian value from two consecutive registers */
static int si1182_read_16bit(uint8_t reg_low) {
    int lo = si1182_read_reg(reg_low);
    if (lo < 0) return -1;
    int hi = si1182_read_reg(reg_low + 1);
    if (hi < 0) return -1;
    return (hi << 8) | lo;
}

/* Write a parameter to the Si1182 parameter RAM */
static int si1182_param_set(uint8_t param, uint8_t value) {
    if (si1182_write_reg(SI1182_REG_PARAM_WR, value) < 0) return -1;
    if (si1182_write_reg(SI1182_REG_COMMAND, SI1182_CMD_PARAM_SET | (param & 0x1F)) < 0) return -1;
    return 0;
}

/* Initialize the Si1182 sensor */
static int si1182_init(void) {
    /* Reset the sensor */
    if (si1182_write_reg(SI1182_REG_COMMAND, SI1182_CMD_RESET) < 0) {
        fprintf(stderr, "Sensor reset failed (NACK or bus error).\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay after reset */

    /* Verify PART_ID */
    int part_id = si1182_read_reg(SI1182_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Failed to read PART_ID.\n");
        return -1;
    }
    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X).\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }
    printf("Si1182 detected (PART_ID=0x%02X).\n", part_id);

    /* Configure measurement rate: 0x00 = 0 ms between measurements */
    if (si1182_write_reg(SI1182_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (si1182_write_reg(SI1182_REG_MEAS_RATE1, 0x00) < 0) return -1;

    /* Configure LED current for PS1 (LED1) */
    if (si1182_write_reg(SI1182_REG_PS_LED21, 0x0F) < 0) return -1;

    /* Configure ADC mux for PS1, PS2, PS3, PS4 */
    if (si1182_param_set(SI1182_PARAM_PS1_ADCMUX, 0x03) < 0) return -1;
    if (si1182_param_set(SI1182_PARAM_PS2_ADCMUX, 0x03) < 0) return -1;
    if (si1182_param_set(SI1182_PARAM_PS3_ADCMUX, 0x03) < 0) return -1;
    if (si1182_param_set(SI1182_PARAM_PS4_ADCMUX, 0x03) < 0) return -1;

    /* Enable PS1, PS2, PS3, PS4 in CHLIST */
    if (si1182_param_set(SI1182_PARAM_CHLIST, 0x0F) < 0) return -1;

    /* Start autonomous measurements */
    if (si1182_write_reg(SI1182_REG_COMMAND, SI1182_CMD_PS_AUTO) < 0) {
        fprintf(stderr, "Failed to start PS auto.\n");
        return -1;
    }

    return 0;
}

/* Read proximity data from PS1 */
static int si1182_read_proximity(void) {
    return si1182_read_16bit(SI1182_REG_PS1_DATA0);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x60 */
    i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at 0x%02X: %d\n", SI1182_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (si1182_init() < 0) {
        fprintf(stderr, "Si1182 initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Reading proximity data every 500 ms. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        int proximity = si1182_read_proximity();
        if (proximity >= 0) {
            printf("Proximity: %d\n", proximity);
        } else {
            fprintf(stderr, "Error reading proximity data.\n");
        }
        gpioDelay(500000); /* 500 ms */
    }

    /* Clean up */
    printf("\nCleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

