/*
 * OPT3101 Time-of-Flight sensor reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   OPT3101 SDA -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   OPT3101 SCL -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   OPT3101 VDD -> 3.3 V
 *   OPT3101 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -o opt3101_reader opt3101_reader.c -lpigpio -lrt
 * Run:
 *   sudo ./opt3101_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- OPT3101 constants (from datasheet) ---- */
#define OPT3101_I2C_ADDR        0x54
#define OPT3101_REG_DEVICE_ID   0x00
#define OPT3101_REG_SYSTEM_CFG  0x01
#define OPT3101_REG_RESULT      0x02
#define OPT3101_REG_ERROR_FLAGS 0x03
#define OPT3101_REG_AMBIENT     0x04

#define OPT3101_EXPECTED_ID     0x3101
#define OPT3101_SYSTEM_CFG_VAL  0x0001  /* enable channel 0, default config */

#define I2C_BUS                 1
#define SAMPLE_PERIOD_US        500000  /* 500 ms */

/* ---- Globals for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a 16-bit register (pigpio uses uint8_t buf). */
static int reg_write16(int handle, uint8_t reg, uint16_t val)
{
    char buf[2];
    buf[0] = (char)(val >> 8);
    buf[1] = (char)(val & 0xFF);
    return i2cWriteI2CBlockData(handle, reg, buf, 2);
}

