/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi 3 Model B+
 * Trigger: GPIO 17 (BCM), Echo: GPIO 18 (BCM)
 *
 * NOTE: The HC-SR04 echo line is 5 V tolerant and the Pi GPIO is only
 * 3.3 V tolerant.  A 1 kΩ resistor (or voltage divider) must be used
 * between the HC-SR04 echo pin and the Pi GPIO 18 input.
 *
 * Build: gcc -O2 -Wall -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 µs trigger pulse            */
#define ECHO_TIMEOUT_US  200000      /* 200 ms max echo wait           */
#define SAMPLE_PERIOD_US 1000000     /* 1 s between readings           */
#define MAX_PULSE_US     38000       /* HC-SR04 max round-trip ~38 ms  */
#define MIN_PULSE_US     0           /* guard against spurious readings */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Send a 10 µs trigger pulse                                          */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Measure echo pulse width in microseconds.                           */
/* Returns 0 on success, -1 on timeout, -2 on invalid pulse duration.  */
/* ------------------------------------------------------------------ */
static int measure_echo_us(uint32_t *pulse_us)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Wait for echo rising edge (timeout 200 ms) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo rising-edge timeout (no object detected or sensor absent)\n");
            return -1;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout 200 ms) */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo falling-edge timeout (stuck high)\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    if (diff < MIN_PULSE_US || diff > MAX_PULSE_US) {
        fprintf(stderr, "Error: invalid pulse duration %u µs (out of 0–38000 µs range)\n", diff);
        return -2;
    }

    *pulse_us = diff;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert pulse width (µs) to distance (cm)                           */
/* Speed of sound ~343 m/s  =>  1 µs = 1/1000/343 cm                   */
/* ------------------------------------------------------------------ */
static float pulse_to_cm(uint32_t pulse_us)
{
    return (float)pulse_us / 1000.0f / 343.0f * 100.0f;
}

/* ------------------------------------------------------------------ */
/* Print timestamped distance reading                                  */
/* ------------------------------------------------------------------ */
static void log_reading(float distance_cm)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Distance: %.2f cm\n", ts, distance_cm);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (run as root?)\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: cannot set GPIO %d as input\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle time */

    printf("HC-SR04 ranging started.  Trigger=GPIO%d, Echo=GPIO%d\n",
           TRIGGER_PIN, ECHO_PIN);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        trigger_sensor();

        uint32_t pulse_us = 0;
        int rc = measure_echo_us(&pulse_us);

        if (rc == 0) {
            log_reading(pulse_to_cm(pulse_us));
        }
        /* rc == -1 (timeout) or -2 (invalid) already reported in measure_echo_us */

        /* Sleep 1 s between readings (interruptible by signals) */
        for (int i = 0; i < 10 && g_running; i++) {
            gpioDelay(100000);  /* 100 ms slices */
        }
    }

    /* --- Cleanup --- */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

