/*
 * Raspberry Pi 4 Model B – TDK Chirp ICU-20201 ultrasonic distance monitor
 *
 * Wiring:
 *   ICU-20201 SDA  -> GPIO 2  (I2C bus 1 SDA)
 *   ICU-20201 SCL  -> GPIO 3  (I2C bus 1 SCL)
 *   ICU-20201 VDD  -> 3.3 V
 *   ICU-20201 GND  -> GND
 *   Alert LED      -> GPIO 17 (BCM 17) via 330 Ω resistor to GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o distance_monitor distance_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./distance_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define I2C_ADDR            0x50          /* default 7-bit I2C address */
#define ALERT_GPIO          17            /* BCM 17 */
#define DISTANCE_THRESHOLD  10.0f         /* cm */
#define LOG_FILE            "distance_log.txt"
#define SAMPLE_PERIOD_US    100000        /* 100 ms */

/*
 * ICU-20201 register map (16-bit addresses, big-endian on the bus).
 * The sensor expects 16-bit register addresses sent MSB-first.
 */
#define REG_MODEL_ID        0x0000
#define REG_FW_VERSION      0x0001
#define REG_MEASURE_CMD     0x0002
#define REG_DISTANCE_MM     0x0003
#define REG_ALERT_STATUS    0x0004

#define MEASURE_CMD_START   0x0001
#define MEASURE_CMD_STOP    0x0000

#define MODEL_ID_EXPECTED   0x2020        /* ICU-20201 family */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* --------------------------- Signal handling ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- I2C helpers --------------------------------- */
static int i2c_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (value >> 8) & 0xFF;
    buf[3] = value & 0xFF;
    return i2cWriteDevice(handle, buf, 4);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char addr[2];
    char data[2];

    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) < 0)
        return -1;

    if (i2cReadDevice(handle, data, 2) != 2)
        return -1;

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* --------------------------- Sensor init --------------------------------- */
static int sensor_init(int handle)
{
    uint16_t model_id = 0;

    if (i2c_read_reg16(handle, REG_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error: cannot read MODEL_ID (sensor absent or bus error).\n");
        return -1;
    }

    if (model_id != MODEL_ID_EXPECTED) {
        fprintf(stderr, "Error: unexpected MODEL_ID 0x%04X (expected 0x%04X).\n",
                model_id, MODEL_ID_EXPECTED);
        return -1;
    }

    printf("ICU-20201 detected (MODEL_ID = 0x%04X).\n", model_id);

    /* Start continuous measurement mode */
    if (i2c_write_reg16(handle, REG_MEASURE_CMD, MEASURE_CMD_START) < 0) {
        fprintf(stderr, "Error: cannot start measurement.\n");
        return -1;
    }

    return 0;
}

/* --------------------------- Distance read -------------------------------- */
static int read_distance(int handle, float *distance_cm)
{
    uint16_t raw_mm = 0;

    if (i2c_read_reg16(handle, REG_DISTANCE_MM, &raw_mm) < 0) {
        fprintf(stderr, "Error: I2C read of distance register failed.\n");
        return -1;
    }

    *distance_cm = (float)raw_mm / 10.0f;
    return 0;
}

/* --------------------------- Logging ------------------------------------- */
static int log_distance(FILE *fp, float distance_cm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }

    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(fp, "%s, %.2f\n", ts, distance_cm) < 0) {
        fprintf(stderr, "Error: writing to log file failed.\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file.\n");
        return -1;
    }

    return 0;
}

/* --------------------------- Alert control -------------------------------- */
static void control_alert(float distance_cm)
{
    int level = (distance_cm < DISTANCE_THRESHOLD) ? 1 : 0;
    if (gpioWrite(ALERT_GPIO, level) < 0) {
        fprintf(stderr, "Warning: gpioWrite(%d) failed.\n", level);
    }
}

/* --------------------------- Cleanup -------------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /* Stop measurement before closing */
        (void)i2c_write_reg16(g_i2c_handle, REG_MEASURE_CMD, MEASURE_CMD_STOP);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    /* Ensure alert is off */
    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();
}

/* --------------------------- Main ---------------------------------------- */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure alert GPIO */
    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_OUTPUT) failed.\n", ALERT_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_GPIO, 0);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (sensor_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: sensor initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring distance (threshold %.1f cm). Press Ctrl+C to exit.\n",
           DISTANCE_THRESHOLD);

    /* Main loop */
    while (g_running) {
        float distance_cm = 0.0f;

        if (read_distance(g_i2c_handle, &distance_cm) == 0) {
            printf("Distance: %.2f cm\n", distance_cm);

            if (log_distance(g_log_file, distance_cm) < 0) {
                fprintf(stderr, "Warning: logging failed, continuing.\n");
            }

            control_alert(distance_cm);
        } else {
            fprintf(stderr, "Warning: read_distance failed, will retry.\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

