static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;
static VL53L1_Dev_t g_dev;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(void)
{
    /* Check whether the file already exists so we can write a header. */
    int exists = (access(LOG_FILE, F_OK) == 0);

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    if (!exists) {
        if (fprintf(g_log_file, "timestamp,distance_mm\n") < 0) {
            perror("fprintf(header)");
            fclose(g_log_file);
            g_log_file = NULL;
            return -1;
        }
        if (fflush(g_log_file) != 0) {
            perror("fflush(header)");
            fclose(g_log_file);
            g_log_file = NULL;
            return -1;
        }
    }
    return 0;
}

static void log_data(int distance_mm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time()");
        return;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (!t) {
        perror("localtime_r()");
        return;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }

    if (fprintf(g_log_file, "%s,%d\n", ts, distance_mm) < 0) {
        perror("fprintf(data)");
    } else {
        fflush(g_log_file);
    }
}

/* ------------------------------------------------------------------ */
/* Parking guidance                                                    */
/* ------------------------------------------------------------------ */
static void parking_guidance(int distance_mm)
{
    if (distance_mm < 300) {
        printf("STOP: Object too close (%d mm)\n", distance_mm);
    } else if (distance_mm < 600) {
        printf("APPROACH: Object at moderate distance (%d mm)\n", distance_mm);
    } else if (distance_mm < 1200) {
        printf("SLOW: Object at good distance (%d mm)\n", distance_mm);
    } else {
        printf("CLEAR: Object well beyond threshold (%d mm)\n", distance_mm);
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        /*
         * Best-effort de-initialisation.  If the sensor was not
         * initialised or the I2C handle was lost, VL53L1_Stop()
         * returns an error; that is acceptable here.
         */
        (void)VL53L1_Stop(&g_dev);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- VL53L1X init ---------------------------------------------- */
    g_dev.platform.user_data = (void *)g_i2c_handle;
    g_dev.platform.write     = (uint8_t (*)(uint16_t, uint8_t *, uint32_t))i2cWriteI2CBlockData;
    g_dev.platform.read      = (uint8_t (*)(uint16_t, uint8_t *, uint32_t))i2cReadI2CBlockData;
    g_dev.platform.wait_ms   = (void (*)(uint32_t))gpioDelay;
    g_dev.platform.sleep_ms  = (void (*)(uint32_t))gpioDelay;

    VL53L1_Error status = VL53L1_Init(&g_dev);
    if (status != VL53L1_ERROR_NONE) {
        fprintf(stderr, "VL53L1_Init failed: %s\n",
                status == VL53L1_ERROR_SENSOR_NOT_PRESENT
                    ? "sensor not present"
                    : "unknown error");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file --------------------------------------------------- */
    if (log_open() != 0) {
        VL53L1_Stop(&g_dev);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Signal handlers ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("Parking Assistance System started.  Press Ctrl+C to exit.\n");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        VL53L1_Error status = VL53L1_StartRanging(&g_dev);
        if (status != VL53L1_ERROR_NONE) {
            fprintf(stderr, "VL53L1_StartRanging failed: %s\n",
                    status == VL53L1_ERROR_SENSOR_NOT_PRESENT
                        ? "sensor not present"
                        : "unknown error");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /*
         * Wait for the measurement to complete.  The VL53L1X UAPI
         * provides a polling function; we poll every 1 ms for up to
         * 100 ms to avoid blocking the main thread for too long.
         */
        uint8_t ready = 0;
        for (int i = 0; i < 100 && g_running; i++) {
            status = VL53L1_CheckForDataReady(&g_dev, &ready);
            if (status != VL53L1_ERROR_NONE) {
                fprintf(stderr, "VL53L1_CheckForDataReady failed: %s\n",
                        status == VL53L1_ERROR_SENSOR_NOT_PRESENT
                            ? "sensor not present"
                            : "unknown error");
                ready = 0;
                break;
            }
            if (ready) break;
            gpioDelay(1000);
        }

        if (!ready) {
            fprintf(stderr, "Measurement timeout\n");
            VL53L1_StopRanging(&g_dev);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        uint16_t distance_mm = 0;
        status = VL53L1_GetDistance(&g_dev, &distance_mm);
        if (status != VL53L1_ERROR_NONE) {
            fprintf(stderr, "VL53L1_GetDistance failed: %s\n",
                    status == VL53L1_ERROR_SENSOR_NOT_PRESENT
                        ? "sensor not present"
                        : "unknown error");
            VL53L1_StopRanging(&g_dev);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        /* Sanity-check the reading. */
        if (distance_mm > MAX_DISTANCE_MM) {
            fprintf(stderr, "Out-of-range reading: %u mm\n", distance_mm);
            VL53L1_StopRanging(&g_dev);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        log_data((int)distance_mm);
        parking_guidance((int)distance_mm);

        status = VL53L1_StopRanging(&g_dev);
        if (status != VL53L1_ERROR_NONE) {
            fprintf(stderr, "VL53L1_StopRanging failed: %s\n",
                    status == VL53L1_ERROR_SENSOR_NOT_PRESENT
                        ? "sensor not present"
                        : "unknown error");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Graceful shutdown ----------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

