/*
 * CH201 ultrasonic ToF sensor reader with distance-based LED blink control.
 *
 * Board:  Raspberry Pi 4 Model B
 * I2C:    /dev/i2c-1  (GPIO2=SDA, GPIO3=SCL)
 * LED:    GPIO18 (BCM), 330 ohm series resistor to 3.3 V
 *
 * Build:  gcc -O2 -Wall -o ch201_led ch201_led.c -lpigpio -lrt
 * Run:    sudo ./ch201_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS          1
#define I2C_ADDR         0x50          /* CH201 default 7-bit address */
#define LED_GPIO         18
#define SAMPLE_PERIOD_US 100000        /* 100 ms */
#define MAX_RETRIES      3
#define RETRY_DELAY_US   10000         /* 10 ms */

/*
 * CH201 register map (16-bit registers, big-endian on the bus).
 * The sensor returns 16-bit distance in mm after a read of register 0x00.
 */
#define CH201_REG_DISTANCE 0x00

static volatile sig_atomic_t g_terminate = 0;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian register from the CH201.                   */
/* Returns 0 on success (distance stored in *out), -1 on failure.     */
/* ------------------------------------------------------------------ */
static int ch201_read_distance(int handle, uint16_t *out)
{
    char reg = (char)CH201_REG_DISTANCE;
    char buf[2];
    int  rc;

    for (int attempt = 0; attempt < MAX_RETRIES; ++attempt) {
        rc = i2cWriteDevice(handle, &reg, 1);
        if (rc < 0) {
            fprintf(stderr, "[attempt %d] i2cWriteDevice failed (rc=%d)\n",
                    attempt + 1, rc);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        rc = i2cReadDevice(handle, buf, 2);
        if (rc < 0) {
            fprintf(stderr, "[attempt %d] i2cReadDevice failed (rc=%d)\n",
                    attempt + 1, rc);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }
        if (rc != 2) {
            fprintf(stderr, "[attempt %d] short read: %d bytes\n",
                    attempt + 1, rc);
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
        return 0;
    }

    return -1;
}

/* ------------------------------------------------------------------ */
/* Map distance (mm) to LED blink frequency (Hz).                      */
/* Faster blink as distance decreases.  Returns 0 for 0 mm.            */
/* ------------------------------------------------------------------ */
static int distance_to_frequency(uint16_t distance_mm)
{
    if (distance_mm == 0)
        return 0;

    /*
     * 100 mm -> 1 Hz, 10 mm -> 10 Hz.
     * Clamp to a reasonable range so the LED is never too fast or too slow.
     */
    int freq = 1000000 / (int)distance_mm;
    if (freq < 1)   freq = 1;
    if (freq > 100) freq = 100;
    return freq;
}

/* ------------------------------------------------------------------ */
/* Perform one half-cycle of the LED at the given frequency.           */
/* Returns 0 on success, -1 on failure.                                */
/* ------------------------------------------------------------------ */
static int led_half_cycle(int gpio, int frequency_hz)
{
    if (frequency_hz <= 0) {
        if (gpioWrite(gpio, 0) < 0)
            return -1;
        return 0;
    }

    int half_period_us = 500000 / frequency_hz;
    if (half_period_us < 1000)
        half_period_us = 1000;          /* cap at 1 kHz */

    if (gpioWrite(gpio, 1) < 0)
        return -1;
    gpioDelay(half_period_us);
    if (gpioWrite(gpio, 0) < 0)
        return -1;
    gpioDelay(half_period_us);
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- LED GPIO setup --------------------------------------------- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- I2C open --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed on bus %d addr 0x%02X (rc=%d)\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handlers -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("CH201 distance reader started.  Ctrl+C to exit.\n");
    printf("I2C bus %d, address 0x%02X, LED on GPIO %d\n",
           I2C_BUS, I2C_ADDR, LED_GPIO);

    /* --- main loop -------------------------------------------------- */
    while (!g_terminate) {
        uint16_t distance = 0;

        if (ch201_read_distance(g_i2c_handle, &distance) < 0) {
            fprintf(stderr, "Sensor read failed after %d retries; "
                            "check wiring and sensor presence.\n",
                    MAX_RETRIES);
            /*
             * Keep the LED off for a while to avoid a flash of failure,
             * then retry.
             */
            gpioWrite(LED_GPIO, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        int freq = distance_to_frequency(distance);

        time_t now = time(NULL);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&now));

        printf("%s  Distance: %u mm  LED freq: %d Hz\n", ts, distance, freq);
        fflush(stdout);

        /*
         * Perform one half-cycle of the LED blink.
         * If the half-cycle write fails, report it and move on.
         */
        if (led_half_cycle(LED_GPIO, freq) < 0) {
            fprintf(stderr, "LED write failed; continuing.\n");
        }

        /*
         * Sleep for the remainder of the 100 ms sample period.
         * gpioDelay is a busy-wait but is acceptable here because the
         * LED half-cycle already consumed a small fraction of the period.
         */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- graceful shutdown ------------------------------------------ */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

