/*
 * MLX75030 Time-of-Flight Distance Logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   MLX75030 SDA -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   MLX75030 SCL -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   MLX75030 VDD -> 3.3V (pin 1)
 *   MLX75030 GND -> GND (pin 6)
 *
 * Build: gcc -O2 -Wall -o mlx75030_logger mlx75030_logger.c -lpigpio -lrt
 * Run:   sudo ./mlx75030_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29          /* MLX75030 default I2C address */
#define LOG_FILE       "distance_log.csv"
#define SAMPLE_US      100000        /* 100 ms between samples */
#define MEAS_DELAY_US  20000         /* 20 ms measurement settling time */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000         /* 10 ms between retries */

/* MLX75030 command to trigger a single distance measurement */
#define CMD_MEASURE    0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Write a command byte to the sensor                                  */
/* ------------------------------------------------------------------ */
static int sensor_write_cmd(uint8_t cmd)
{
    int rc = i2cWriteByte(g_i2c_handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x%02X) failed: %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 2-byte distance value (big-endian)                           */
/* ------------------------------------------------------------------ */
static int sensor_read_distance(uint16_t *distance_cm)
{
    char buf[2];
    int rc = i2cReadDevice(g_i2c_handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected 2)\n", rc);
        return -1;
    }
    *distance_cm = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the CSV log                         */
/* ------------------------------------------------------------------ */
static int log_data(uint16_t distance_cm)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed\n");
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s,%u\n", ts, distance_cm) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed\n");
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed\n");
        return -1;
    }

