static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(SENSOR_1_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_1_GPIO);
        gpioTerminate();
        return -1;
    }
    if (gpioSetMode(SENSOR_2_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as input\n", SENSOR_2_GPIO);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sensor(int gpio) {
    int retries = 0;
    int value;
    while (retries < MAX_RETRIES) {
        value = gpioRead(gpio);
        if (value == 0 || value == 1) {
            return value;
        }
        fprintf(stderr, "gpioRead(%d) failed (rc=%d), retry %d/%d\n",
                gpio, value, retries + 1, MAX_RETRIES);
        retries++;
        gpioDelay(1000);
    }
