            fprintf(stderr, "Sensor read error, continuing...\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        if (cur1 != prev1) {
            if (prev1 == 1 && cur1 == 0) {
                log_event(1, "DETECTED");
            } else if (prev1 == 0 && cur1 == 1) {
                log_event(1, "CLEARED");
            }
            prev1 = cur1;
