#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define CH101_ADDR     0x54
#define CSV_FILE       "distance_log.csv"
#define POLL_TIMEOUT_MS 50
#define SAMPLE_DELAY_MS 500

/* CH-101 register addresses (16-bit, big-endian on the bus) */
#define REG_MEAS_STATUS 0x0000
#define REG_DISTANCE    0x0004

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_csv   = NULL;

static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a 16-bit register address, then read `len` bytes back. */
static int i2c_read_reg(int fd, uint16_t reg, uint8_t *buf, size_t len)
{
    uint8_t addr[2] = { (uint8_t)(reg >> 8), (uint8_t)(reg & 0xFF) };

    if (write(fd, addr, 2) != 2) {
        fprintf(stderr, "I2C write (reg 0x%04X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C read (reg 0x%04X, %zu bytes) failed: %s\n",
                reg, len, strerror(errno));
        return -1;
    }
    return 0;
}

/* Poll MEAS_STATUS until bit 0 is set (data ready) or timeout. */
static int wait_for_data_ready(int fd, int timeout_ms)
{
    uint8_t status;
    int elapsed = 0;
    const int step_ms = 5;

    while (elapsed < timeout_ms) {
        if (i2c_read_reg(fd, REG_MEAS_STATUS, &status, 1) != 0)
            return -1;
        if (status & 0x01)
            return 0;
        usleep(step_ms * 1000);
        elapsed += step_ms;
    }
    fprintf(stderr, "Timeout waiting for CH-101 data ready (status=0x%02X)\n", status);
    return -1;
}

