static int read_distance(int fd, int *distance_mm)
{
    if (wait_for_data_ready(fd, POLL_TIMEOUT_MS) != 0)
        return -1;

    uint8_t buf[2];
    if (i2c_read_reg(fd, REG_DISTANCE, buf, 2) != 0)
        return -1;

    /* CH-101 distance is 16-bit big-endian, units are 1 mm per LSB. */
    *distance_mm = ((int)buf[0] << 8) | buf[1];
    return 0;
}

