        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty. */
    if (ftell(g_csv) == 0)
        fprintf(g_csv, "timestamp,distance_mm\n");

    printf("CH-101 distance logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int distance_mm;
        if (read_distance(g_i2c_fd, &distance_mm) == 0) {
            log_data(g_csv, distance_mm);
            printf("Distance: %d mm\n", distance_mm);
        } else {
            fprintf(stderr, "Sensor read failed; skipping sample.\n");
        }
