/*
 * MLX75030 Time-of-Flight distance reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   MLX75030 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   MLX75030 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   MLX75030 VDD -> 3.3 V
 *   MLX75030 GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -o mlx75030 mlx75030.c -lpigpio -lrt
 * Run:
 *   sudo ./mlx75030
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x29          /* MLX75030 default 7-bit I2C address */
#define SAMPLE_PERIOD  100000        /* 100 ms in microseconds */
#define MAX_RETRIES    3
#define RETRY_DELAY_US 10000         /* 10 ms between retries */

/*
 * MLX75030 register map (subset).
 * The full datasheet defines many more registers; this covers the
 * essential distance-measurement sequence.
 */
#define REG_MEASURE    0x00          /* Trigger / read measurement */
#define REG_DISTANCE   0x01          /* Distance result (16-bit, mm) */
#define REG_STATUS     0x02          /* Status / error flags */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers with retry logic                                        */
/* ------------------------------------------------------------------ */

/*
 * Write a single byte to a register.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_write_reg(uint8_t reg, uint8_t value)
{
    char buf[2] = { (char)reg, (char)value };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(g_i2c_handle, buf, 2);
        if (rc == 0)
            return 0;

        fprintf(stderr,
                "[WARN] i2cWriteDevice(reg=0x%02X, val=0x%02X) failed (rc=%d), attempt %d/%d\n",
                reg, value, rc, attempt + 1, MAX_RETRIES);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/*
 * Read N bytes starting from a register.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_read_reg(uint8_t reg, uint8_t *data, uint32_t len)
{
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteDevice(g_i2c_handle, (char *)&reg, 1);
        if (rc != 0) {
            fprintf(stderr,
                    "[WARN] i2cWriteDevice(reg=0x%02X) failed (rc=%d), attempt %d/%d\n",
                    reg, rc, attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1)
                gpioDelay(RETRY_DELAY_US);
            continue;
        }

        rc = i2cReadDevice(g_i2c_handle, (char *)data, len);
        if (rc == (int)len)
            return 0;

        fprintf(stderr,
                "[WARN] i2cReadDevice(reg=0x%02X, len=%u) failed (rc=%d), attempt %d/%d\n",
                reg, len, rc, attempt + 1, MAX_RETRIES);
        if (attempt < MAX_RETRIES - 1)
            gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int sensor_init(void)
{
    /*
     * Minimal initialization: verify the device is present by reading
     * the STATUS register.  A NACK here usually means the sensor is
     * absent or the address is wrong.
     */
    uint8_t status = 0;
    if (i2c_read_reg(REG_STATUS, &status, 1) != 0) {
        fprintf(stderr,
                "[ERROR] Cannot read STATUS register — sensor not responding at 0x%02X\n",
                I2C_ADDR);
        return -1;
    }
    printf("[INFO] MLX75030 detected (STATUS=0x%02X)\n", status);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Distance measurement                                                */
/* ------------------------------------------------------------------ */
static int read_distance(uint16_t *distance_mm)
{
    uint8_t data[2];

    /* Trigger a measurement by writing to the MEASURE register. */
    if (i2c_write_reg(REG_MEASURE, 0x01) != 0) {
        fprintf(stderr, "[ERROR] Failed to trigger measurement\n");
        return -1;
    }

    /*
     * Wait for the measurement to complete.
     * The MLX75030 typically requires ~10 ms; a short delay ensures
     * the data is ready.
     */
    gpioDelay(2000);  /* 2 ms */

    /* Read the 16-bit distance result. */
    if (i2c_read_reg(REG_DISTANCE, data, 2) != 0) {
        fprintf(stderr, "[ERROR] Failed to read distance register\n");
        return -1;
    }

    *distance_mm = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Timestamp helper                                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t cur = strlen(buf);
    snprintf(buf + cur, len - cur, ".%03ld", ts.tv_nsec / 1000000);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio library. */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open the I2C bus. */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr,
                "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed (rc=%d)\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor. */
    if (sensor_init() != 0) {
        fprintf(stderr, "[FATAL] Sensor initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Starting distance measurements (Ctrl-C to stop)\n");

    /* Main sampling loop. */
    while (g_running) {
        uint16_t distance = 0;

        if (read_distance(&distance) == 0) {
            char ts[32];
            get_timestamp(ts, sizeof(ts));
            printf("%s  Distance: %u mm\n", ts, distance);
        } else {
            fprintf(stderr, "[ERROR] Measurement failed — continuing\n");
        }

        gpioDelay(SAMPLE_PERIOD);
    }

    /* Graceful cleanup. */
    printf("\n[INFO] Shutting down...\n");
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

