#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* VL53L4CX I2C address (7-bit) */
#define VL53L4CX_ADDR 0x29

/* VL53L4CX register addresses */
#define VL53L4CX_REG_SOFT_RESET       0x000B
#define VL53L4CX_REG_SYSTEM_START     0x0001
#define VL53L4CX_REG_INT_STATUS       0x0044
#define VL53L4CX_REG_RESULT_DISTANCE  0x0096

/* Interrupt status bit: data ready */
#define VL53L4CX_INT_DATA_READY       0x01

/* Polling interval in microseconds */
#define POLL_INTERVAL_US 500000

/* Global I2C handle for signal handler cleanup */
static int i2c_handle = -1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    fprintf(stderr, "\nCaught signal, cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
    exit(0);
}

/* Write a 16-bit register address and 8-bit data value */
static int vl53l4cx_write_reg8(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

/* Read an 8-bit value from a 16-bit register address */
static int vl53l4cx_read_reg8(int handle, uint16_t reg, uint8_t *value) {
    char addr_buf[2];
    char data_buf[1];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr_buf, 2) < 0) {
        return -1;
    }
    if (i2cReadDevice(handle, data_buf, 1) != 1) {
        return -1;
    }
    *value = (uint8_t)data_buf[0];
    return 0;
}

/* Read a 16-bit big-endian value from a 16-bit register address */
static int vl53l4cx_read_reg16(int handle, uint16_t reg, uint16_t *value) {
    char addr_buf[2];
    char data_buf[2];
    addr_buf[0] = (reg >> 8) & 0xFF;
    addr_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, addr_buf, 2) < 0) {
        return -1;
    }
    if (i2cReadDevice(handle, data_buf, 2) != 2) {
        return -1;
    }
    *value = ((uint16_t)(uint8_t)data_buf[0] << 8) | (uint8_t)data_buf[1];
    return 0;
}

/* Initialize the VL53L4CX sensor */
static int vl53l4cx_init(int handle) {
    /* Soft reset */
    if (vl53l4cx_write_reg8(handle, VL53L4CX_REG_SOFT_RESET, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset register.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay after reset */

    /* Start ranging */
    if (vl53l4cx_write_reg8(handle, VL53L4CX_REG_SYSTEM_START, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to start ranging.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay for first measurement */

    return 0;
}

/* Read distance data from the VL53L4CX sensor */
static int vl53l4cx_read_distance(int handle, uint16_t *distance) {
    uint8_t int_status = 0;
    uint16_t dist = 0;

    /* Check interrupt status */
    if (vl53l4cx_read_reg8(handle, VL53L4CX_REG_INT_STATUS, &int_status) < 0) {
        fprintf(stderr, "Error: Failed to read interrupt status.\n");
        return -1;
    }

    if ((int_status & VL53L4CX_INT_DATA_READY) == 0) {
        return 1; /* No data ready yet */
    }

    /* Read distance */
    if (vl53l4cx_read_reg16(handle, VL53L4CX_REG_RESULT_DISTANCE, &dist) < 0) {
        fprintf(stderr, "Error: Failed to read distance register.\n");
        return -1;
    }

    *distance = dist;
    return 0;
}

