#include <time.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 22
#define DISTANCE_THRESHOLD 100
#define POLL_DELAY_US 500000

#define VL53L1X_REG_SOFT_RESET 0x0000
#define VL53L1X_REG_SYSTEM_MODE_START 0x0001
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int vl53l1x_write16(uint16_t reg, uint8_t value) {
    char buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int vl53l1x_read16(uint16_t reg, uint16_t *value) {
    char reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (i2cWriteDevice(i2c_handle, reg_buf, 2) < 0) return -1;
    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) return -1;
    *value = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int vl53l1x_init(void) {
    if (vl53l1x_write16(VL53L1X_REG_SOFT_RESET, 0x00) < 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write16(VL53L1X_REG_SOFT_RESET, 0x01) < 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write16(VL53L1X_REG_SYSTEM_MODE_START, 0x00) < 0) return -1;
    gpioDelay(10000);
    return 0;
}

static int vl53l1x_start_ranging(void) {
    return vl53l1x_write16(VL53L1X_REG_SYSTEM_MODE_START, 0x40);
}

static int vl53l1x_read_distance(uint16_t *distance) {
    uint16_t range_status;
    if (vl53l1x_read16(VL53L1X_REG_RESULT_RANGE_STATUS, &range_status) < 0) return -1;
    if ((range_status & 0x01) == 0) return 1;
    if (vl53l1x_read16(VL53L1X_REG_RESULT_DISTANCE, distance) < 0) return -1;
    return 0;
}

static void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(stderr, "[%s] ERROR: %s\n", timestamp, message);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_init() < 0) {
        log_error("Failed to initialize VL53L1X sensor");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (vl53l1x_start_ranging() < 0) {
        log_error("Failed to start ranging");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("VL53L1X distance sensor running. Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t distance;
        int ret = vl53l1x_read_distance(&distance);

        if (ret == 0) {
            printf("Distance: %u mm\n", distance);
            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_GPIO, 1);
            } else {
                gpioWrite(BUZZER_GPIO, 0);
            }
        } else if (ret < 0) {
            log_error("I2C read error");
        }

        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(BUZZER_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

