#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <sys/stat.h>
#include <mqueue.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define BUZZER_GPIO 23
#define DISTANCE_THRESHOLD 100
#define POLL_DELAY_US 50000
#define MAX_DISTANCE 4000
#define MQ_NAME "/distance_queue"
#define MQ_MAX_MSG_SIZE 64
#define MQ_MAX_MSGS 10

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START 0x0000
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x000B
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096
#define VL53L1X_REG_RANGING_MEASUREMENT_TIMING_BUDGET 0x0080
#define VL53L1X_REG_SOFT_RESET_GO2 0x0000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static mqd_t mq = (mqd_t)-1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int vl53l1x_write16(int handle, uint16_t reg, uint8_t value) {
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

static int vl53l1x_read16(int handle, uint16_t reg, uint16_t *value) {
    char reg_buf[2];
    char data[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    if (i2cReadDevice(handle, data, 2) != 2) return -1;
    *value = ((uint16_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

static int vl53l1x_init(int handle) {
    uint16_t model_id = 0;
    if (vl53l1x_read16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id) < 0) {
        fprintf(stderr, "Error reading model ID: %s\n", strerror(errno));
        return -1;
    }
    if (model_id != 0xEA) {
        fprintf(stderr, "Invalid model ID: 0x%04X (expected 0xEA)\n", model_id);
        return -1;
    }
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET_GO2, 0x00) < 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET_GO2, 0x01) < 0) return -1;
    gpioDelay(10000);
    if (vl53l1x_write16(handle, VL53L1X_REG_RANGING_MEASUREMENT_TIMING_BUDGET, 0x0031) < 0) return -1;
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_MODE_START, 0x00) < 0) return -1;
    return 0;
}

static int vl53l1x_read_distance(int handle, uint16_t *distance) {
    uint16_t range_status = 0;
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &range_status) < 0) return -1;
    if ((range_status & 0x01) == 0) {
        return 1;
    }
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, distance) < 0) return -1;
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) return -1;
    return 0;
}

static void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (mq != (mqd_t)-1) {
        mq_close(mq);
        mq = (mqd_t)-1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main() {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed\n");
        cleanup();
        return 1;
    }
    struct mq_attr attr;
    attr.mq_flags = 0;
    attr.mq_maxmsg = MQ_MAX_MSGS;
    attr.mq_msgsize = MQ_MAX_MSG_SIZE;
    attr.mq_curmsgs = 0;
    mq = mq_open(MQ_NAME, O_CREAT | O_RDWR, 0666, &attr);
    if (mq == (mqd_t)-1) {
        fprintf(stderr, "Error opening message queue: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);
    printf("Distance monitoring started. Press Ctrl+C to exit.\n");
    while (running) {
        uint16_t distance = 0;
        int ret = vl53l1x_read_distance(i2c_handle, &distance);
        if (ret == 0) {
            if (distance < DISTANCE_THRESHOLD) {
                gpioWrite(BUZZER_GPIO, 1);
            } else {
                gpioWrite(BUZZER_GPIO, 0);
            }
            char msg[MQ_MAX_MSG_SIZE];
            snprintf(msg, sizeof(msg), "%u", distance);
            if (mq_send(mq, msg, strlen(msg) + 1, 0) == -1) {
                fprintf(stderr, "Error sending message to queue: %s\n", strerror(errno));
            }
        } else if (ret < 0) {
            fprintf(stderr, "Error reading distance: %s\n", strerror(errno));
            gpioWrite(BUZZER_GPIO, 0);
        }
        gpioDelay(POLL_DELAY_US);
    }
    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

