/*
 * Parking sensor using HC-SR04 on Raspberry Pi 3 Model B+
 * Trigger: GPIO 17 (BCM), Echo: GPIO 27 (BCM), Buzzer: GPIO 22 (BCM)
 * Library: pigpio (interrupt-driven echo measurement)
 *
 * Build: gcc -Wall -O2 -o parking_sensor parking_sensor.c -lpigpio -lrt
 * Run:   sudo ./parking_sensor
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <stdint.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         27
#define BUZZER_PIN       22

#define SPEED_OF_SOUND   34300.0   /* cm/s at 20 °C */
#define THRESHOLD_CM     30.0
#define MIN_DISTANCE_CM  2.0
#define MAX_DISTANCE_CM  400.0
#define ECHO_TIMEOUT_US  30000     /* 30 ms (~5 m round trip) */
#define SAMPLE_PERIOD_US 100000   /* 100 ms */
#define TRIGGER_PULSE_US 10

static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile int      g_echo_done  = 0;
static volatile int      g_echo_state = 0;  /* 0=idle, 1=rising seen, 2=falling seen */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback for echo pin (interrupt-driven)               */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        /* Rising edge: start of echo pulse */
        g_start_tick = tick;
        g_echo_state = 1;
    } else if (level == 0 && g_echo_state == 1) {
        /* Falling edge: end of echo pulse */
        g_end_tick  = tick;
        g_echo_state = 2;
        g_echo_done  = 1;
    }
}

/* ------------------------------------------------------------------ */
/* Measure distance in cm; returns -1.0 on timeout / out-of-range      */
/* ------------------------------------------------------------------ */
static double measure_distance(void)
{
    g_echo_done  = 0;
    g_echo_state = 0;
    g_start_tick = 0;
    g_end_tick   = 0;

    /* Generate 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set trigger HIGH\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set trigger LOW\n");
        return -1.0;
    }

    /* Wait for echo with timeout (poll every 100 µs) */
    uint32_t waited = 0;
    while (!g_echo_done && waited < ECHO_TIMEOUT_US) {
        gpioDelay(100);
        waited += 100;
    }

    if (!g_echo_done) {
        return -1.0;  /* timeout: sensor absent or no object in range */
    }

    /* Handle 32-bit tick wraparound */
    uint32_t diff;
    if (g_end_tick >= g_start_tick) {
        diff = g_end_tick - g_start_tick;
    } else {
        diff = (0xFFFFFFFFu - g_start_tick) + g_end_tick + 1u;
    }

    double distance = (double)diff / 1000000.0 * SPEED_OF_SOUND / 2.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1.0;  /* out of valid range */
    }

    return distance;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* Register interrupt callback for echo pin */
    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Error: failed to register echo callback\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Parking sensor started. Press Ctrl+C to exit.\n");
    printf("Threshold: %.1f cm | Range: %.1f–%.1f cm\n",
           THRESHOLD_CM, MIN_DISTANCE_CM, MAX_DISTANCE_CM);

    while (g_running) {
        double distance = measure_distance();

        if (distance < 0.0) {
            printf("Distance: ERROR (timeout or out of range)\n");
        } else {
            printf("Distance: %.2f cm\n", distance);
        }

        /* Buzzer control */
        if (distance >= 0.0 && distance < THRESHOLD_CM) {
            if (gpioWrite(BUZZER_PIN, 1) < 0) {
                fprintf(stderr, "Warning: failed to activate buzzer\n");
            }
        } else {
