        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    gpioSetAlertFunc(ECHO_PIN, NULL);  /* unregister callback */
    gpioTerminate();

    return EXIT_SUCCESS;
