static volatile uint32_t g_end_tick   = 0;
static volatile int      g_echo_done  = 0;
static volatile int      g_echo_state = 0;  /* 0=idle, 1=rising seen, 2=falling seen */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
