/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        /* Rising edge: start of echo pulse */
        g_start_tick = tick;
        g_echo_state = 1;
    } else if (level == 0 && g_echo_state == 1) {
        /* Falling edge: end of echo pulse */
        g_end_tick  = tick;
        g_echo_state = 2;
        g_echo_done  = 1;
    }
