/*
 * Gate control system for Raspberry Pi Zero W
 * Sensor: VL53L1X (I2C bus 1, address 0x29)
 * Actuator: SG90 servo on GPIO18 (hardware PWM)
 * Logging: gate_log.txt
 *
 * Build: gcc -O2 -Wall -o gate_control gate_control.c -lpigpio -lrt
 * Run:   sudo ./gate_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29
#define SERVO_PIN            18      /* BCM 18 = hardware PWM0 */
#define DISTANCE_THRESHOLD   20      /* cm */
#define SERVO_OPEN_PULSE     1500    /* us  -> ~120 deg */
#define SERVO_CLOSE_PULSE    500     /* us  -> ~0 deg  */
#define LOG_FILE             "gate_log.txt"
#define POLL_DELAY_US        100000  /* 100 ms */
#define MAX_RETRIES          3

/* VL53L1X register addresses (16-bit, big-endian on bus) */
#define VL53L1X_REG_SOFT_RESET       0x000B
#define VL53L1X_REG_SYSTEM_MODE      0x0080
#define VL53L1X_REG_RANGE_START      0x0080
#define VL53L1X_REG_RESULT_RANGE     0x0096
#define VL53L1X_REG_RESULT_STATUS    0x0089

#define VL53L1X_SOFT_RESET_VALUE     0x00
#define VL53L1X_BOOTED_VALUE         0x01
#define VL53L1X_MODE_SINGLESHOT      0x01
#define VL53L1X_MODE_BACKTOBACK      0x02
#define VL53L1X_STATUS_DATA_READY    0x01

/* ----------------------------- Globals ----------------------------------- */
static int           i2c_handle = -1;
static FILE         *log_file   = NULL;
static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t gate_state = 0;   /* 0 = closed, 1 = open */

/* ----------------------------- Prototypes -------------------------------- */
static void signal_handler(int sig);
static void log_event(const char *msg);
static int  vl53l1x_write16(int h, uint16_t reg, uint8_t val);
static int  vl53l1x_read16(int h, uint16_t reg, uint8_t *buf, int len);
static int  vl53l1x_init(int h);
static int  vl53l1x_read_distance(int h, uint16_t *distance);
static void set_servo(int pulse_us);
static void open_gate(void);
static void close_gate(void);
static void force_open(void);
static void force_close(void);
static void status_request(void);

/* ----------------------------- Signal handler ----------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(const char *msg)
{
    if (!log_file) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(log_file, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(log_file);
}

/* ----------------------------- I2C helpers -------------------------------- */
static int vl53l1x_write16(int h, uint16_t reg, uint8_t val)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = val;
    return i2cWriteDevice(h, buf, 3);
}

static int vl53l1x_read16(int h, uint16_t reg, uint8_t *buf, int len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;
    if (i2cWriteDevice(h, addr, 2) < 0) return -1;
    return i2cReadDevice(h, (char *)buf, len);
}

/* ----------------------------- VL53L1X init ------------------------------- */
static int vl53l1x_init(int h)
{
    /* Software reset */
    if (vl53l1x_write16(h, VL53L1X_REG_SOFT_RESET, VL53L1X_SOFT_RESET_VALUE) < 0) {
        log_event("VL53L1X: soft reset write failed");
        return -1;
    }
    gpioDelay(10000);  /* 10 ms */

    /* Release reset */
    if (vl53l1x_write16(h, VL53L1X_REG_SOFT_RESET, 0x01) < 0) {
        log_event("VL53L1X: release reset failed");
        return -1;
    }
    gpioDelay(10000);  /* 10 ms */

    /* Wait for device to boot */
    uint8_t boot = 0;
    for (int i = 0; i < 100; i++) {
        if (vl53l1x_read16(h, VL53L1X_REG_SOFT_RESET, &boot, 1) < 0) {
            log_event("VL53L1X: boot-read failed");
            return -1;
        }
        if (boot == VL53L1X_BOOTED_VALUE) break;
        gpioDelay(1000);
        if (i == 99) {
            log_event("VL53L1X: boot timeout");
            return -1;
        }
    }

    /* Start back-to-back ranging */
    if (vl53l1x_write16(h, VL53L1X_REG_SYSTEM_MODE, VL53L1X_MODE_BACKTOBACK) < 0) {
        log_event("VL53L1X: start ranging failed");
        return -1;
    }
    gpioDelay(10000);  /* 10 ms */

    log_event("VL53L1X initialized");
    return 0;
}

/* ----------------------------- Distance read ------------------------------ */
static int vl53l1x_read_distance(int h, uint16_t *distance)
{
    uint8_t status = 0;
    uint8_t data[2];

    /* Check data-ready */
    if (vl53l1x_read16(h, VL53L1X_REG_RESULT_STATUS, &status, 1) < 0) {
        log_event("VL53L1X: status read failed");
        return -1;
    }
    if (!(status & VL53L1X_STATUS_DATA_READY)) {
        return 1;  /* not ready yet */
    }

    /* Read 16-bit distance */
    if (vl53l1x_read16(h, VL53L1X_REG_RESULT_RANGE, data, 2) < 0) {
        log_event("VL53L1X: distance read failed");
        return -1;
    }

    *distance = ((uint16_t)data[0] << 8) | data[1];

    /* Clear interrupt by writing to range-start */
    vl53l1x_write16(h, VL53L1X_REG_RANGE_START, VL53L1X_MODE_BACKTOBACK);

    return 0;
}

/* ----------------------------- Servo control ------------------------------ */
static void set_servo(int pulse_us)
{
    if (gpioServo(SERVO_PIN, pulse_us) < 0) {
        log_event("Servo: gpioServo failed");
    }
}

static void open_gate(void)
{
    if (gate_state == 1) return;
    set_servo(SERVO_OPEN_PULSE);
    gate_state = 1;
    log_event("Gate opened");
}

static void close_gate(void)
{
    if (gate_state == 0) return;
    set_servo(SERVO_CLOSE_PULSE);
    gate_state = 0;
    log_event("Gate closed");
}

/* ----------------------------- Driver callbacks --------------------------- */
static void force_open(void)
{
    log_event("Command: force_open");
    open_gate();
}

static void force_close(void)
{
    log_event("Command: force_close");
    close_gate();
}

static void status_request(void)
{
    char msg[64];
    snprintf(msg, sizeof(msg), "Status: gate=%s", gate_state ? "OPEN" : "CLOSED");
    log_event(msg);
}

/* ----------------------------- Main --------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open I2C */
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %d\n", i2c_handle);
        log_event("I2C open failed");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(i2c_handle) < 0) {
        log_event("VL53L1X init failed");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure servo pin */
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    set_servo(SERVO_CLOSE_PULSE);
    gate_state = 0;

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("System started");

    /* Main loop */
    while (running) {
        uint16_t distance = 0;
        int rc = vl53l1x_read_distance(i2c_handle, &distance);

        if (rc == 0) {
            if (distance < DISTANCE_THRESHOLD) {
                open_gate();
            } else {
                close_gate();
            }
        } else if (rc < 0) {
            /* I2C error: attempt re-init */
            log_event("I2C error, re-initializing sensor");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            int retries = 0;
            while (running && retries < MAX_RETRIES) {
                gpioDelay(500000);  /* 0.5 s */
                i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
                if (i2c_handle >= 0 && vl53l1x_init(i2c_handle) == 0) break;
                retries++;
            }
            if (i2c_handle < 0) {
                log_event("I2C re-init failed, exiting");
                break;
            }
        }
        /* rc == 1: data not ready, just wait */

        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    log_event("Shutting down");
    set_servo(SERVO_CLOSE_PULSE);
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file) fclose(log_file);
    gpioTerminate();
    return EXIT_SUCCESS;
}

