/*
 * HC-SR04 Ultrasonic Distance Measurement on Raspberry Pi 4 Model B
 *
 * Wiring:
 *   TRIG -> GPIO 23 (physical pin 16, BCM)
 *   ECHO -> GPIO 24 (physical pin 18, BCM)  [5 V tolerant; use level shifter]
 *   VCC  -> 5 V, GND -> GND
 *
 * The ECHO line is 5 V; a voltage divider or logic-level shifter is
 * required to bring it within the Pi's 3.3 V tolerance.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:
 *   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24

#define TRIGGER_PULSE_US 10          /* 10 µs trigger pulse            */
#define SAMPLE_PERIOD_US 200000      /* 5 Hz sampling                  */
#define ECHO_TIMEOUT_US  60000       /* 60 ms max echo wait            */
#define MIN_PULSE_US     100         /* reject noise / short pulses    */
#define MAX_PULSE_US     30000       /* reject long pulses / timeouts  */

/* ------------------------------------------------------------------ */
/* Shared state between callback and main thread                       */
/* ------------------------------------------------------------------ */
static volatile uint32_t g_rising_tick  = 0;
static volatile uint32_t g_falling_tick = 0;
static volatile bool     g_echo_seen     = false;
static volatile bool     g_running       = true;

static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = false;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback (runs in pigpio thread)                        */
/* ------------------------------------------------------------------ */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_rising_tick  = tick;
        g_echo_seen    = false;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        g_falling_tick = tick;
        g_echo_seen    = true;
    }
    /* level == 2 (timeout) is ignored here */
}

/* ------------------------------------------------------------------ */
/* Compute pulse width with 32-bit tick wraparound handling            */
/* ------------------------------------------------------------------ */
static uint32_t pulse_width_us(uint32_t rising, uint32_t falling)
{
    /* pigpio ticks are 32-bit microseconds; handle wraparound */
    return falling - rising;  /* unsigned subtraction wraps correctly */
}

/* ------------------------------------------------------------------ */
/* Distance from pulse width (cm)                                      */
/* ------------------------------------------------------------------ */
static float distance_cm(uint32_t pulse_us)
{
    /*
     * Speed of sound: 343 m/s = 0.0343 cm/µs
     * Round-trip distance = (pulse_us * 0.0343) / 2
     */
    return (float)pulse_us * 0.0343f / 2.0f;
}

/* ------------------------------------------------------------------ */
/* ISO 8601 timestamp string (thread-safe via localtime_r)             */
/* ------------------------------------------------------------------ */
static void iso_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tm_info;
    localtime_r(&now, &tm_info);
    strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
}

/* ------------------------------------------------------------------ */
/* Log a reading to stdout and the log file                            */
/* ------------------------------------------------------------------ */
static void log_reading(float distance_cm, uint32_t pulse_us)
{
    char ts[32];
    iso_timestamp(ts, sizeof(ts));

    printf("%s  Distance: %.2f cm  (pulse: %u us)\n", ts, distance_cm, pulse_us);
    fflush(stdout);

    if (g_log_fp) {
        fprintf(g_log_fp, "%s,%.2f,%u\n", ts, distance_cm, pulse_us);
        fflush(g_log_fp);
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: cannot set pull-down on ECHO_PIN %d.\n", ECHO_PIN);
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5000);  /* 5 ms settle */

    /* ---- Register alert callback ---- */
    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) != 0) {
        fprintf(stderr, "Error: cannot register alert on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen("distance_log.txt", "a");
    if (!g_log_fp) {
        perror("Error opening distance_log.txt");
        gpioSetAlertFunc(ECHO_PIN, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance measurement started.\n");
    printf("TRIG=GPIO%d, ECHO=GPIO%d. Press Ctrl+C to exit.\n",
           TRIGGER_PIN, ECHO_PIN);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        /* Reset echo state before triggering */
        g_echo_seen    = false;
        g_rising_tick  = 0;
        g_falling_tick = 0;

        /* Generate 10 µs trigger pulse */
        gpioWrite(TRIGGER_PIN, 1);
        gpioDelay(TRIGGER_PULSE_US);
        gpioWrite(TRIGGER_PIN, 0);

        /* Wait for echo with timeout (poll every 1 ms) */
        uint32_t wait_start = gpioTick();
        while (!g_echo_seen && (gpioTick() - wait_start) < ECHO_TIMEOUT_US) {
            gpioDelay(1000);
        }

        if (!g_echo_seen) {
            fprintf(stderr, "Warning: echo timeout (no object detected or sensor absent).\n");
            continue;
        }

        uint32_t pulse = pulse_width_us(g_rising_tick, g_falling_tick);

        if (pulse < MIN_PULSE_US || pulse > MAX_PULSE_US) {
            fprintf(stderr,
                    "Warning: out-of-range pulse %u us (rejected).\n",
                    pulse);
            continue;
        }

        float dist = distance_cm(pulse);
        log_reading(dist, pulse);

        /* Sleep until next sample period */
        uint32_t elapsed = gpioTick() - wait_start;
        if (elapsed < SAMPLE_PERIOD_US) {
            gpioDelay(SAMPLE_PERIOD_US - elapsed);
        }
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    gpioSetAlertFunc(ECHO_PIN, NULL);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    printf("Done.\n");
    return EXIT_SUCCESS;
}

