#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* VL53L1X I2C address (ADDR pin tied to GND) */
#define VL53L1X_ADDR 0x29

/* VL53L1X 16-bit register addresses */
#define VL53L1X_SOFT_RESET       0x000B
#define VL53L1X_SYSTEM_START     0x0000
#define VL53L1X_RANGE_STATUS     0x0089
#define VL53L1X_RESULT_DISTANCE  0x0096
#define VL53L1X_TIMING_BUDGET    0x0001

/* GPIO pins for gate control */
#define GATE_OPEN_PIN  18
#define GATE_CLOSE_PIN 19

/* Distance threshold in mm (20 cm) */
#define DISTANCE_THRESHOLD_MM 200

/* Polling interval in microseconds (500 ms) */
#define POLL_INTERVAL_US 500000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register (pigpio i2cWriteWordData uses little-endian  */
/* byte order on the wire, which matches VL53L1X 16-bit register      */
/* addressing).                                                        */
/* ------------------------------------------------------------------ */
static int vl53l1x_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    int rc = i2cWriteWordData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%04X, val=0x%04X): %d\n",
                reg, value, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register (returns 0 on success, -1 on error).         */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%04X): %d\n", reg, rc);
        return -1;
    }
    *out = (uint16_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the VL53L1X sensor.                                      */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (vl53l1x_write_reg16(handle, VL53L1X_SOFT_RESET, 0x0001) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms */

    /* Set timing budget to 50 ms (0x0032) */
    if (vl53l1x_write_reg16(handle, VL53L1X_TIMING_BUDGET, 0x0032) < 0)
        return -1;

    /* Start ranging (bit 0 of SYSTEM_START) */
    if (vl53l1x_write_reg16(handle, VL53L1X_SYSTEM_START, 0x0001) < 0)
        return -1;

    gpioDelay(10000); /* 10 ms for first measurement */
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read distance in mm. Returns -1 on I2C error.                      */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle)
{
    uint16_t status = 0;
    uint16_t distance = 0;

    /* Check range status (bit 0 = data ready) */
    if (vl53l1x_read_reg16(handle, VL53L1X_RANGE_STATUS, &status) < 0)
        return -1;

    if ((status & 0x0001) == 0) {
        /* Data not ready yet */
        return -2;
    }

    /* Read distance */
    if (vl53l1x_read_reg16(handle, VL53L1X_RESULT_DISTANCE, &distance) < 0)
        return -1;

    return (int)distance;
}

/* ------------------------------------------------------------------ */
/* Control the gate.                                                   */
/* ------------------------------------------------------------------ */
static void control_gate(int open)
{
    if (open) {
        gpioWrite(GATE_OPEN_PIN, 1);
        gpioWrite(GATE_CLOSE_PIN, 0);
    } else {
        gpioWrite(GATE_OPEN_PIN, 0);
        gpioWrite(GATE_CLOSE_PIN, 1);
    }
}

/* ------------------------------------------------------------------ */
/* Log an event with ISO 8601 UTC timestamp.                           */
/* ------------------------------------------------------------------ */
static void log_event(const char *event)
{
    if (g_log_file == NULL)
        return;

    time_t now = time(NULL);
    struct tm tm_utc;
    char ts[32];

    gmtime_r(&now, &tm_utc);
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(g_log_file, "%s: %s\n", ts, event);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure gate is closed */
    if (g_i2c_handle >= 0) {
        gpioWrite(GATE_OPEN_PIN, 0);
        gpioWrite(GATE_CLOSE_PIN, 1);
    }

    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    gpioTerminate();

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    gpioSetMode(GATE_OPEN_PIN, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_OUTPUT);
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 1);

    /* Open I2C bus 1 */
    g_i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %d\n",
                VL53L1X_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialization failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen("gate_events.log", "a");
    if (g_log_file == NULL) {
        perror("Failed to open gate_events.log");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Gate control system started. Press Ctrl+C to exit.\n");
    log_event("System started");

    int gate_open = 0;

    while (g_running) {
