            gate_open = 1;
            log_event("Gate opened");
            printf("Object detected at %d mm. Gate opened.\n", distance);
        } else if (!object_detected && gate_open) {
            control_gate(0);
            gate_open = 0;
            log_event("Gate closed");
            printf("No object detected. Gate closed.\n");
        }

