/*
 * Raspberry Pi 4 Model B – VL53L1X time-of-flight sensor + DC motor control
 *
 * Wiring:
 *   VL53L1X SDA  -> GPIO2  (I2C bus 1)
 *   VL53L1X SCL  -> GPIO3  (I2C bus 1)
 *   VL53L1X VDD  -> 3.3 V
 *   VL53L1X GND  -> GND
 *   DC motor FWD -> GPIO17 (via transistor/MOSFET)
 *   DC motor BWD -> GPIO18 (via transistor/MOSFET)
 *   Trigger      -> GPIO24 (BCM) – rising edge triggers a distance read
 *
 * Build:  gcc -O2 -Wall -o vl53l1x_motor vl53l1x_motor.c -lpigpio -lrt
 * Run:    sudo ./vl53l1x_motor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define I2C_ADDR             0x29          /* VL53L1X default 7-bit address */

#define MOTOR_FWD_PIN        17
#define MOTOR_BWD_PIN        18
#define TRIGGER_PIN          24

#define DISTANCE_THRESHOLD_LOW   100   /* mm – run forward */
#define DISTANCE_THRESHOLD_HIGH  300   /* mm – run backward */

#define POLL_TIMEOUT_MS       1000
#define MAX_RETRIES           3
#define RETRY_DELAY_US        10000       /* 10 ms */

/* VL53L1X register addresses */
#define VL53L1X_REG_SOFT_RESET        0x000B
#define VL53L1X_REG_SYSTEM_START      0x0000
#define VL53L1X_REG_RESULT_STATUS     0x0014
#define VL53L1X_REG_RESULT_DISTANCE   0x0096

#define VL53L1X_SOFT_RESET_VALUE      0x00
#define VL53L1X_SYSTEM_START_VALUE    0x01
#define VL53L1X_STATUS_DATA_READY     0x01

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* --------------------------- Function prototypes -------------------------- */
static void signal_handler(int sig);
static int  vl53l1x_write16(int handle, uint16_t reg, uint8_t value);
static int  vl53l1x_read16(int handle, uint16_t reg, uint16_t *out);
static int  vl53l1x_init(int handle);
static int  vl53l1x_read_distance(int handle, uint16_t *distance_mm);
static void motor_forward(void);
static void motor_backward(void);
static void motor_stop(void);
static void trigger_callback(int gpio, int level, uint32_t tick, void *userdata);

/* ------------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- VL53L1X helpers ------------------------------ */

/*
 * Write a single byte to a 16-bit register address.
 * pigpio's i2cWriteByteData uses the low byte of the key as the register,
 * so we must send the high byte separately when the register is 16-bit.
 */
static int vl53l1x_write16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (char)(reg >> 8);
    buf[1] = (char)(reg & 0xFF);
    buf[2] = (char)value;

    int rc = i2cWriteDevice(handle, buf, 3);
    if (rc < 0) {
        fprintf(stderr, "[VL53L1X] i2cWriteDevice(reg=0x%04X) failed: %d\n",
                reg, rc);
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit big-endian value from a 16-bit register address.
 * pigpio's i2cReadI2CBlockData returns the low byte of the key as the
 * register, so we must send the high byte separately.
 */
static int vl53l1x_read16(int handle, uint16_t reg, uint16_t *out)
{
    char reg_buf[2];
    reg_buf[0] = (char)(reg >> 8);
    reg_buf[1] = (char)(reg & 0xFF);

    if (i2cWriteDevice(handle, reg_buf, 2) < 0) {
        fprintf(stderr, "[VL53L1X] Failed to set register 0x%04X\n", reg);
        return -1;
    }

    char data[2];
    int rc = i2cReadDevice(handle, data, 2);
    if (rc != 2) {
        fprintf(stderr, "[VL53L1X] i2cReadDevice(reg=0x%04X) failed: %d\n",
                reg, rc);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/*
 * Initialise the VL53L1X: soft reset, then start continuous measurement.
 * Returns 0 on success, -1 on failure.
 */
static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (vl53l1x_write16(handle, VL53L1X_REG_SOFT_RESET,
                        VL53L1X_SOFT_RESET_VALUE) < 0) {
        return -1;
    }
    gpioDelay(1000);  /* 1 ms */

    /* Start continuous measurement */
    if (vl53l1x_write16(handle, VL53L1X_REG_SYSTEM_START,
                        VL53L1X_SYSTEM_START_VALUE) < 0) {
        return -1;
    }
    gpioDelay(1000);  /* 1 ms */

    return 0;
}

/*
 * Read a distance measurement.
 * Returns 0 on success and stores the distance in mm in *distance_mm.
 * Returns -1 on I2C error, -2 if the measurement is not ready within
 * POLL_TIMEOUT_MS, -3 if the sensor reports an error status.
 */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint16_t status = 0;
    int retries = 0;

    /* Poll the data-ready bit */
    while (retries < MAX_RETRIES) {
        if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_STATUS, &status) < 0) {
            retries++;
            gpioDelay(RETRY_DELAY_US * (1 << retries));
            continue;
        }
        if (status & VL53L1X_STATUS_DATA_READY) {
            break;
        }
        retries++;
        gpioDelay(RETRY_DELAY_US * (1 << retries));
    }

    if (retries >= MAX_RETRIES) {
        fprintf(stderr, "[VL53L1X] Timeout waiting for data-ready\n");
        return -2;
    }

    /* Read the 16-bit distance result */
    if (vl53l1x_read16(handle, VL53L1X_REG_RESULT_DISTANCE, distance_mm) < 0) {
        return -1;
    }

    /* Clear the data-ready bit so the next measurement can be flagged */
    if (vl53l1x_write16(handle, VL53L1X_REG_RESULT_STATUS, 0x00) < 0) {
        fprintf(stderr, "[VL53L1X] Warning: failed to clear status bit\n");
    }

    return 0;
}

/* ------------------------------- Motor control ---------------------------- */
static void motor_forward(void)
{
    gpioWrite(MOTOR_FWD_PIN, 1);
    gpioWrite(MOTOR_BWD_PIN, 0);
    printf("Motor: FORWARD\n");
}

static void motor_backward(void)
{
    gpioWrite(MOTOR_FWD_PIN, 0);
    gpioWrite(MOTOR_BWD_PIN, 1);
    printf("Motor: BACKWARD\n");
}

static void motor_stop(void)
{
    gpioWrite(MOTOR_FWD_PIN, 0);
    gpioWrite(MOTOR_BWD_PIN, 0);
    printf("Motor: STOP\n");
}

/* --------------------------- Trigger ISR callback ------------------------- */
static void trigger_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level != 1) {  /* rising edge only */
        return;
    }

    uint16_t distance = 0;
    int rc = vl53l1x_read_distance(g_i2c_handle, &distance);

    if (rc == 0) {
        printf("Distance: %u mm\n", distance);

        if (distance < DISTANCE_THRESHOLD_LOW) {
            motor_forward();
        } else if (distance > DISTANCE_THRESHOLD_HIGH) {
            motor_backward();
        } else {
            motor_stop();
        }
    } else {
        fprintf(stderr, "Error reading distance (rc=%d)\n", rc);
        motor_stop();
    }
}

/* --------------------------------- main ---------------------------------- */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure motor pins */
    if (gpioSetMode(MOTOR_FWD_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_BWD_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set motor GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    motor_stop();

    /* Configure trigger pin */
    if (gpioSetMode(TRIGGER_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set trigger GPIO mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioSetPullUpDown(TRIGGER_PIN, PI_PUD_DOWN);

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (vl53l1x_init(g_i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialisation failed – sensor may be absent\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register ISR on rising edge */
    if (gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0,
                         trigger_callback, NULL) < 0) {
        fprintf(stderr, "Failed to register ISR on GPIO%d\n", TRIGGER_PIN);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("VL53L1X ready. Trigger on GPIO%d (rising edge). Ctrl+C to exit.\n",
           TRIGGER_PIN);

    /* Main loop – sleep until signal received */
    while (g_running) {
        gpioDelay(100000);  /* 100 ms */
    }

    /* --------------------------- Clean shutdown --------------------------- */
    printf("\nShutting down...\n");
    gpioSetISRFuncEx(TRIGGER_PIN, RISING_EDGE, 0, NULL, NULL);  /* unregister */
    motor_stop();
    i2cClose(g_i2c_handle);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

