/*
 * Proximity-based interactive art installation for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - MPR121 capacitive touch sensor on /dev/i2c-1 (GPIO 2 = SDA, GPIO 3 = SCL)
 *   - 4-bit LED array: bit 0 -> GPIO 17, bit 1 -> GPIO 18, bit 2 -> GPIO 27, bit 3 -> GPIO 22
 *
 * Behavior:
 *   Polls the MPR121 every 50 ms, lights up the LED pattern corresponding to the
 *   first electrode that reports proximity, logs each event with a timestamp, and
 *   exits cleanly on SIGINT / SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ---- MPR121 I2C address ---- */
#define MPR121_ADDR 0x5A

/* ---- MPR121 register addresses ---- */
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECONFIG0    0x5E
#define MPR121_SOFTRESET     0x80

/* ---- GPIO pins for 4-bit LED array ---- */
#define LED_PIN_0 17
#define LED_PIN_1 18
#define LED_PIN_2 27
#define LED_PIN_3 22

/* ---- Polling interval (microseconds) ---- */
#define POLL_INTERVAL_US 50000

/* ---- Global state for signal handler ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* MPR121 initialization                                               */
/* ------------------------------------------------------------------ */
static int mpr121_init(int fd)
{
    uint8_t status = 0;

    /* Soft reset */
    if (i2c_write_reg8(fd, MPR121_SOFTRESET, 0x63) < 0)
        return -1;
    gpioDelay(10000); /* 10 ms settle */

    /* Verify sensor is present by reading the ELECONFIG0 register */
    if (i2c_read_reg8(fd, MPR121_ELECONFIG0, &status) < 0)
        return -1;

    /*
     * Basic configuration:
     *   - 12 electrodes enabled (ELECONFIG = 0x0C)
     *   - Baseline tracking enabled (ELECONFIG0 bit 0 = 1)
     */
    if (i2c_write_reg8(fd, MPR121_ELECONFIG0, 0x0C) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 12-bit touch status                                            */
/* ------------------------------------------------------------------ */
static int mpr121_read_touch(int fd, uint16_t *touch_status)
{
    uint8_t lo = 0, hi = 0;

    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_L, &lo) < 0)
        return -1;
    if (i2c_read_reg8(fd, MPR121_TOUCHSTATUS_H, &hi) < 0)
        return -1;

    *touch_status = ((uint16_t)hi << 8) | lo;
    return 0;
}

/* ------------------------------------------------------------------ */
/* LED control                                                         */
/* ------------------------------------------------------------------ */
static void set_leds(uint16_t touch_status)
{
    for (int i = 0; i < 12; i++) {
        if (touch_status & (1u << i)) {
            uint8_t pattern = (uint8_t)(1u << i);
            gpioWrite(LED_PIN_0, (pattern >> 0) & 1);
            gpioWrite(LED_PIN_1, (pattern >> 1) & 1);
            gpioWrite(LED_PIN_2, (pattern >> 2) & 1);
            gpioWrite(LED_PIN_3, (pattern >> 3) & 1);
            return;
        }
    }
    /* No touch: all LEDs off */
    gpioWrite(LED_PIN_0, 0);
    gpioWrite(LED_PIN_1, 0);
    gpioWrite(LED_PIN_2, 0);
    gpioWrite(LED_PIN_3, 0);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(uint16_t touch_status)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_fp, "%s - Touch status: 0x%04X\n", timestamp, touch_status);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        /* Put MPR121 into stop mode */
        (void)i2c_write_reg8(g_i2c_fd, MPR121_ELECONFIG0, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    /* Turn off LEDs */
    gpioWrite(LED_PIN_0, 0);
    gpioWrite(LED_PIN_1, 0);
    gpioWrite(LED_PIN_2, 0);
    gpioWrite(LED_PIN_3, 0);

    /* Release GPIO pins */
    gpioSetMode(LED_PIN_0, PI_INPUT);
    gpioSetMode(LED_PIN_1, PI_INPUT);
    gpioSetMode(LED_PIN_2, PI_INPUT);
    gpioSetMode(LED_PIN_3, PI_INPUT);

    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED pins as outputs */
    gpioSetMode(LED_PIN_0, PI_OUTPUT);
    gpioSetMode(LED_PIN_1, PI_OUTPUT);
    gpioSetMode(LED_PIN_2, PI_OUTPUT);
    gpioSetMode(LED_PIN_3, PI_OUTPUT);
    gpioWrite(LED_PIN_0, 0);
    gpioWrite(LED_PIN_1, 0);
    gpioWrite(LED_PIN_2, 0);
    gpioWrite(LED_PIN_3, 0);

    /* Open I2C bus */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MPR121_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init(g_i2c_fd) < 0) {
        fprintf(stderr, "MPR121 initialization failed (sensor absent or bus error)\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen("proximity_log.txt", "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Proximity art installation running. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        uint16_t touch_status = 0;

        if (mpr121_read_touch(g_i2c_fd, &touch_status) < 0) {
            fprintf(stderr, "I2C read error - continuing\n");
            gpioDelay(POLL_INTERVAL_US);
            continue;
        }

        set_leds(touch_status);

        if (touch_status != 0) {
            log_event(touch_status);
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

