#define MPR121_AUTO_CONFIG1 0x7C
#define MPR121_USL 0x7D
#define MPR121_LSL 0x7E
#define MPR121_TL 0x7F

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int mpr121_write_reg(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %d\n", value, reg, rc);
    }
    return rc;
}

static int mpr121_read_reg(uint8_t reg) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int mpr121_init() {
    if (mpr121_write_reg(MPR121_SOFTRESET, 0x63) < 0) return -1;
    gpioDelay(10000);

    if (mpr121_write_reg(MPR121_ECR, 0x00) < 0) return -1;

    if (mpr121_write_reg(MPR121_MHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDR, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLR, 0x0E) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLR, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_MHDF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDF, 0x05) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLF, 0x01) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLF, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NHDT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_NCLT, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_FDLT, 0x00) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (mpr121_write_reg(MPR121_TOUCHTH_0 + 2 * i, 0x0F) < 0) return -1;
        if (mpr121_write_reg(MPR121_RELEASETH_0 + 2 * i, 0x0A) < 0) return -1;
    }

    if (mpr121_write_reg(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write_reg(MPR121_CONFIG2, 0x20) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write_reg(MPR121_AUTO_CONFIG1, 0x00) < 0) return -1;
    if (mpr121_write_reg(MPR121_USL, 0xC8) < 0) return -1;
    if (mpr121_write_reg(MPR121_LSL, 0x82) < 0) return -1;
    if (mpr121_write_reg(MPR121_TL, 0xB4) < 0) return -1;

    if (mpr121_write_reg(MPR121_ECR, 0x8F) < 0) return -1;

    return 0;
}

static int mpr121_read_touch_status(uint16_t *touch_status) {
    int low = mpr121_read_reg(MPR121_TOUCHSTATUS_L);
    if (low < 0) return -1;
    int high = mpr121_read_reg(MPR121_TOUCHSTATUS_H);
    if (high < 0) return -1;
    *touch_status = (uint16_t)((high << 8) | low);
    return 0;
}

static void log_proximity_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Proximity event detected\n", timestamp);
    fflush(log_file);
}

static void cleanup() {
    if (i2c_handle >= 0) {
        mpr121_write_reg(MPR121_ECR, 0x00);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

