        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    int device_id = mpr121_read_reg(MPR121_SOFTRESET);
    if (device_id < 0) {
        fprintf(stderr, "MPR121 not detected on I2C bus %d at address 0x%02X\n", I2C_BUS, MPR121_ADDR);
        cleanup();
        return 1;
    }
    printf("MPR121 detected (Device ID: 0x%02X)\n", device_id);

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialisation failed\n");
        cleanup();
        return 1;
    }

    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Monitoring proximity... Press Ctrl+C to exit.\n");

    while (!terminate) {
        uint16_t touch_status = 0;
        if (mpr121_read_touch_status(&touch_status) < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        if (touch_status > 0) {
            printf("Proximity event detected (0x%04X)\n", touch_status);
            gpioWrite(LED_PIN, 1);
            log_proximity_event();
            gpioDelay(1000000);
            gpioWrite(LED_PIN, 0);
        }

        gpioDelay(50000);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return 0;
}

