#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define TRIGGER_PULSE_US  10
#define TRIGGER_SETTLE_US 5
#define ECHO_TIMEOUT_US   30000   /* 30 ms */
#define LOOP_DELAY_US     1000000 /* 1 s  */
#define MIN_DISTANCE_CM   2.0
#define MAX_DISTANCE_CM   400.0
#define SPEED_OF_SOUND_CM_PER_S 34300.0

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void get_timestamp_utc(char *buf, size_t len)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc);
}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set trigger pin %d as output\n", TRIGGER_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set echo pin %d as input\n", ECHO_PIN);
        gpioTerminate();
        return -1;
    }

    /* Ensure trigger starts LOW */
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise trigger pin LOW\n");
        gpioTerminate();
        return -1;
    }

    /* Allow sensor to settle */
    gpioDelay(50000); /* 50 ms */
    return 0;
}

static void cleanup_gpio(void)
{
    /* Best-effort: drive trigger low and terminate pigpio */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
}

static int trigger_sensor(void)
{
    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1;
    }
    gpioDelay(TRIGGER_SETTLE_US);

    if (gpioWrite(TRIGGER_PIN, 1) != 0) {
        fprintf(stderr, "Error: failed to set trigger high\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);

    if (gpioWrite(TRIGGER_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to set trigger low\n");
        return -1;
    }
    return 0;
}

/*
 * Returns distance in cm on success, or -1.0 on timeout / error.
 * Uses busy-wait via gpioTick() for microsecond precision.
 */
static float measure_distance(void)
{
    uint32_t start_tick = 0, end_tick = 0;
    uint32_t deadline;

    /* Wait for echo rising edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo pin never went high (sensor absent?)\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge */
    deadline = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - deadline) >= 0) {
            fprintf(stderr, "Error: echo pin stuck high (timeout)\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t pulse_us = end_tick - start_tick;
    float distance = (float)pulse_us * SPEED_OF_SOUND_CM_PER_S / 2000000.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Error: distance %.2f cm out of range [%.0f, %.0f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0;
    }
    return distance;
}

static void log_distance(float distance)
{
    char ts[32];
    get_timestamp_utc(ts, sizeof(ts));

    if (distance < 0.0) {
        fprintf(g_log, "%s,ERROR\n", ts);
    } else {
        fprintf(g_log, "%s,%.2f\n", ts, distance);
    }
    fflush(g_log);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    g_log = fopen("distance_log.txt", "a");
    if (g_log == NULL) {
        perror("fopen(distance_log.txt)");
        cleanup_gpio();
        return EXIT_FAILURE;
    }

    while (g_running) {
