/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi Zero W
 *
 * Wiring:
 *   TRIG -> GPIO17 (BCM)
 *   ECHO -> GPIO18 (BCM) via 1k/2k voltage divider (5V->3.3V)
 *
 * Build:
 *   gcc -O2 -Wall -o hcsr04 hcsr04.c -lpigpio -lrt
 * Run:
 *   sudo ./hcsr04
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define TRIGGER_PIN      17
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* 10 µs trigger pulse            */
#define SAMPLE_PERIOD_US 1000000     /* 1 s between measurements       */
#define ECHO_TIMEOUT_US  25000        /* 25 ms max echo wait            */
#define MIN_PULSE_US     58           /* ~1 cm                          */
#define MAX_PULSE_US     25000        /* ~4 m                           */

/* Shared state between ISR and main thread */
static volatile uint32_t g_start_tick = 0;
static volatile uint32_t g_end_tick   = 0;
static volatile bool     g_echo_seen  = false;
static volatile bool     g_running    = true;

static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* ISR: capture echo pulse width on either edge                       */
/* ------------------------------------------------------------------ */
static void echo_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        g_start_tick = tick;
        g_echo_seen  = false;
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        g_end_tick   = tick;
        g_echo_seen  = true;
    }
}

/* ------------------------------------------------------------------ */
/* Send a 10 µs trigger pulse                                         */
/* ------------------------------------------------------------------ */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/* ------------------------------------------------------------------ */
/* Compute pulse width with tick wrap-around handling                 */
/* ------------------------------------------------------------------ */
static uint32_t pulse_width_us(uint32_t start, uint32_t end)
{
    return (end >= start) ? (end - start) : (UINT32_MAX - start + end + 1);
}

/* ------------------------------------------------------------------ */
/* Convert pulse width (µs) to distance (m)                           */
/*   d = (pulse_us * 34300) / 2 / 1e6                                  */
/* ------------------------------------------------------------------ */
static float pulse_to_distance_m(uint32_t pulse_us)
{
    return (float)pulse_us * 0.01715f;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the log file                       */
/* ------------------------------------------------------------------ */
static void log_reading(float distance_m)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log, "%s, Distance: %.2f m\n", ts, distance_m);
    fflush(g_log);
}

/* ------------------------------------------------------------------ */
/* Signal handler: request graceful shutdown                          */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = false;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Disable ISR */
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);

    /* Close log file */
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }

    /* Release pigpio resources */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set TRIGGER_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set ECHO_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle */

    /* Open log file in append mode */
    g_log = fopen("distance_log.txt", "a");
    if (g_log == NULL) {
        perror("Error opening distance_log.txt");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register ISR on ECHO pin (both edges) */
    if (gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, echo_isr, NULL) != 0) {
        fprintf(stderr, "Failed to register ISR on ECHO_PIN\n");
        fclose(g_log);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HC-SR04 distance measurement started. Press Ctrl+C to stop.\n");

    while (g_running) {
        /* Reset state before triggering */
        g_start_tick = 0;
        g_end_tick   = 0;
        g_echo_seen  = false;

        trigger_sensor();

        /* Wait for echo with timeout */
        uint32_t wait_start = gpioTick();
        while (!g_echo_seen && g_running) {
            if ((gpioTick() - wait_start) > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Echo timeout (no object detected or sensor fault)\n");
                break;
            }
            gpioDelay(100);  /* 100 µs poll interval */
        }

        if (!g_running) {
            break;
        }

        if (!g_echo_seen) {
            continue;
        }

        uint32_t pw = pulse_width_us(g_start_tick, g_end_tick);

        if (pw < MIN_PULSE_US || pw > MAX_PULSE_US) {
            fprintf(stderr, "Pulse width out of range: %u µs\n", pw);
            continue;
        }

        float distance = pulse_to_distance_m(pw);
        log_reading(distance);

        /* Sleep for the remainder of the 1-second period */
        uint32_t elapsed = gpioTick() - wait_start;
        if (elapsed < SAMPLE_PERIOD_US) {
            gpioDelay(SAMPLE_PERIOD_US - elapsed);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

