#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GATE_GPIO 24
#define DISTANCE_THRESHOLD_CM 20
#define POLL_DELAY_US 100000
#define LOG_FILE "gate_log.txt"

#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_DISTANCE 0x0096

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void log_message(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static int i2c_write_reg16(uint16_t reg, uint8_t value) {
    char buf[3] = { (reg >> 8) & 0xFF, reg & 0xFF, value };
    return i2cWriteDevice(i2c_handle, buf, 3);
}

static int i2c_read_reg16(uint16_t reg, uint8_t *buf, uint32_t len) {
    char reg_buf[2] = { (reg >> 8) & 0xFF, reg & 0xFF };
    if (i2cWriteDevice(i2c_handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(i2c_handle, (char *)buf, len);
}

static int init_vl53l1x(void) {
    uint8_t model_id = 0;
    if (i2c_read_reg16(VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        log_message("Error: Failed to read model ID from VL53L1X.");
        return -1;
    }
    if (model_id != 0xEA) {
        char msg[64];
        snprintf(msg, sizeof(msg), "Error: Invalid model ID 0x%02X (expected 0xEA).", model_id);
        log_message(msg);
        return -1;
    }
    if (i2c_write_reg16(VL53L1X_REG_SYSTEM_MODE_START, 0x00) < 0) {
        log_message("Error: Failed to stop VL53L1X.");
        return -1;
    }
    gpioDelay(10000);
    if (i2c_write_reg16(VL53L1X_REG_SYSTEM_MODE_START, 0x01) < 0) {
        log_message("Error: Failed to start VL53L1X.");
        return -1;
    }
    gpioDelay(10000);
    return 0;
}

static int read_distance_cm(void) {
    uint8_t status = 0;
    if (i2c_read_reg16(VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0) {
        log_message("Error: Failed to read range status.");
        return -1;
    }
    if ((status & 0x01) == 0) {
        log_message("Warning: Range measurement not ready.");
        return -1;
    }
    uint8_t dist_buf[2] = {0};
    if (i2c_read_reg16(VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) < 0) {
        log_message("Error: Failed to read distance register.");
        return -1;
    }
    uint16_t distance_mm = (dist_buf[0] << 8) | dist_buf[1];
    return distance_mm / 10;
}

static void control_gate(int distance_cm) {
    static int gate_state = 0;
    int new_state = (distance_cm < DISTANCE_THRESHOLD_CM) ? 1 : 0;
    if (new_state != gate_state) {
        if (gpioWrite(GATE_GPIO, new_state) == 0) {
            gate_state = new_state;
            char msg[64];
            snprintf(msg, sizeof(msg), "Gate %s", gate_state ? "opened" : "closed");
            log_message(msg);
        } else {
            log_message("Error: Failed to write to gate GPIO.");
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_message("Error: Failed to open I2C bus.");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (init_vl53l1x() != 0) {
        log_message("Error: VL53L1X initialization failed.");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (gpioSetMode(GATE_GPIO, PI_OUTPUT) != 0) {
        log_message("Error: Failed to set gate GPIO mode.");
        i2cClose(i2c_handle);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    gpioWrite(GATE_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_message("System initialized. Starting distance monitoring.");

    while (!terminate) {
        int distance_cm = read_distance_cm();
        if (distance_cm >= 0) {
            char msg[64];
            snprintf(msg, sizeof(msg), "Distance: %d cm", distance_cm);
            log_message(msg);
            control_gate(distance_cm);
        } else {
            log_message("Error: Failed to read distance.");
        }
        gpioDelay(POLL_DELAY_US);
    }

    log_message("Shutting down gracefully.");
    gpioWrite(GATE_GPIO, 0);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();
    return 0;
}

