#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>
#include <unistd.h>

#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

#define SPEED_OF_SOUND 34300.0
#define MIN_DISTANCE 2.0
#define MAX_DISTANCE 400.0
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500
#define SERVO_CENTER_ANGLE 90
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180
#define TRIGGER_PULSE_US 10
#define ECHO_TIMEOUT_US 30000
#define MOVING_AVG_SIZE 5
#define LOOP_DELAY_US 100000
#define TRIGGER_INTERVAL_US 100000

static volatile uint32_t pulse_width = 0;
static volatile sig_atomic_t new_pulse = 0;
static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static double distance_buffer[MOVING_AVG_SIZE];
static int buffer_index = 0;
static int buffer_filled = 0;

static void echo_callback(int gpio, int level, uint32_t tick) {
    static uint32_t start_tick = 0;
    static int waiting_for_falling = 0;

    if (level == 1) {
        start_tick = tick;
        waiting_for_falling = 1;
    } else if (level == 0 && waiting_for_falling) {
        uint32_t end_tick = tick;
        uint32_t diff = end_tick - start_tick;
        pulse_width = diff;
        new_pulse = 1;
        waiting_for_falling = 0;
    }
}

static double calculate_distance(uint32_t pulse_us) {
    if (pulse_us == 0) return -1.0;
    double time_s = (double)pulse_us / 1000000.0;
    double distance = (time_s * SPEED_OF_SOUND) / 2.0;
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) return -1.0;
    return distance;
}

static int set_servo_angle(int angle) {
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
        fprintf(stderr, "Error: Angle %d out of range [%d, %d]\n", angle, SERVO_MIN_ANGLE, SERVO_MAX_ANGLE);
        return -1;
    }
    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((double)(angle - SERVO_MIN_ANGLE) / (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE)) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

static double moving_average(double new_value) {
    distance_buffer[buffer_index] = new_value;
    buffer_index = (buffer_index + 1) % MOVING_AVG_SIZE;
    if (buffer_index == 0) buffer_filled = 1;
    double sum = 0.0;
    int count = buffer_filled ? MOVING_AVG_SIZE : buffer_index;
    for (int i = 0; i < count; i++) sum += distance_buffer[i];
    return sum / count;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for TRIGGER_PIN %d\n", TRIGGER_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for ECHO_PIN %d\n", ECHO_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for SERVO_PIN %d\n", SERVO_PIN);
        gpioTerminate();
        return 1;
    }

    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) < 0) {
        fprintf(stderr, "Error: gpioSetAlertFunc failed for ECHO_PIN %d\n", ECHO_PIN);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("distance_log.csv", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }
    fprintf(log_file, "Timestamp,Distance_cm,Servo_Angle_deg\n");
    fflush(log_file);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: sigaction failed\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    if (set_servo_angle(SERVO_CENTER_ANGLE) < 0) {
        fprintf(stderr, "Error: Failed to set initial servo angle\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    uint32_t last_trigger_tick = 0;

    while (running) {
        uint32_t now = gpioTick();
        if (now - last_trigger_tick >= TRIGGER_INTERVAL_US) {
            if (gpioWrite(TRIGGER_PIN, 1) < 0) {
                fprintf(stderr, "Error: gpioWrite failed for TRIGGER_PIN high\n");
            }
            gpioDelay(TRIGGER_PULSE_US);
            if (gpioWrite(TRIGGER_PIN, 0) < 0) {
                fprintf(stderr, "Error: gpioWrite failed for TRIGGER_PIN low\n");
            }
            last_trigger_tick = now;
        }

        if (new_pulse) {
            uint32_t pw = pulse_width;
            new_pulse = 0;
            double distance = calculate_distance(pw);
            double avg_distance = moving_average(distance);
            int servo_angle = SERVO_CENTER_ANGLE;

            if (avg_distance > 0) {
                servo_angle = SERVO_CENTER_ANGLE + (int)((avg_distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * 90.0);
                if (servo_angle < SERVO_MIN_ANGLE) servo_angle = SERVO_MIN_ANGLE;
                if (servo_angle > SERVO_MAX_ANGLE) servo_angle = SERVO_MAX_ANGLE;
            } else {
                fprintf(stderr, "Warning: Invalid distance reading, setting servo to center\n");
            }

            if (set_servo_angle(servo_angle) < 0) {
                fprintf(stderr, "Error: Failed to set servo angle\n");
            }

            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s,%.2f,%d\n", timestamp, avg_distance, servo_angle);
            fflush(log_file);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    if (set_servo_angle(0) < 0) {
        fprintf(stderr, "Error: Failed to stop servo on exit\n");
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

