/*
 * VL53L1X time-of-flight distance monitor for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   VL53L1X SDA  -> GPIO2  (I2C bus 1 SDA)
 *   VL53L1X SCL  -> GPIO3  (I2C bus 1 SCL)
 *   VL53L1X VDD  -> 3.3 V
 *   VL53L1X GND  -> GND
 *   LED anode    -> GPIO17 (BCM) via 330 ohm resistor
 *   LED cathode  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -o vl53l1x_monitor vl53l1x_monitor.c -lpigpio -lrt
 * Run:
 *   sudo ./vl53l1x_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L1X constants (from STMicroelectronics datasheet) ---- */
#define VL53L1X_ADDR_DEFAULT 0x29
#define VL53L1X_REG_SOFT_RESET       0x000B
#define VL53L1X_REG_SYSTEM_MODE      0x0001
#define VL53L1X_REG_RANGE_START      0x0000
#define VL53L1X_REG_RESULT_RANGE     0x0096
#define VL53L1X_REG_RESULT_STATUS    0x0089
#define VL53L1X_REG_IDENTIFICATION   0x00C0
#define VL53L1X_REG_I2C_SLAVE_ADDR   0x0001
#define VL53L1X_REG_VHV_CONFIG       0x000B
#define VL53L1X_REG_PHASECAL_CONFIG  0x000C
#define VL53L1X_REG_RANGE_CONFIG     0x001C
#define VL53L1X_REG_INTERMEAS_MS     0x001E
#define VL53L1X_REG_SYSTEM_INTERRUPT 0x000A
#define VL53L1X_REG_GPIO_HV_MUX      0x0030
#define VL53L1X_REG_GPIO_TIO_HV      0x0031
#define VL53L1X_REG_INTERRUPT_CLEAR  0x0086
#define VL53L1X_REG_RANGE_STATUS     0x0089
#define VL53L1X_REG_RESULT_DISTANCE  0x0096

#define VL53L1X_EXPECTED_ID 0xEA
#define VL53L1X_SOFT_RESET_GO 0x00
#define VL53L1X_SOFT_RESET_RESET 0x01
#define VL53L1X_SYSTEM_MODE_SINGLE 0x01
#define VL53L1X_SYSTEM_MODE_CONT 0x02
#define VL53L1X_RANGE_STATUS_DATA_READY 0x01
#define VL53L1X_RANGE_STATUS_ERROR 0x00

#define I2C_BUS 1
#define GPIO_LED 17
#define DISTANCE_THRESHOLD_MM 200
#define BUFFER_SIZE 10
#define POLL_DELAY_US 50000  /* 50 ms */

/* ---- Circular buffer ---- */
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ---- Signal handler ---- */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value) {
    char buf[3] = { (char)(reg >> 8), (char)(reg & 0xFF), (char)value };
    return i2cWriteDevice(handle, buf, 3);
}

static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *data, uint8_t len) {
    char reg_buf[2] = { (char)(reg >> 8), (char)(reg & 0xFF) };
    if (i2cWriteDevice(handle, reg_buf, 2) < 0) return -1;
    return i2cReadDevice(handle, (char *)data, len);
}

/* ---- VL53L1X driver ---- */
static int vl53l1x_init(int handle) {
    uint8_t id = 0;
    uint8_t mode = 0;

    /* 1. Read and verify device ID */
    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION, &id, 1) < 0) {
        fprintf(stderr, "Error: failed to read device ID.\n");
        return -1;
    }
    if (id != VL53L1X_EXPECTED_ID) {
        fprintf(stderr, "Error: unexpected device ID 0x%02X (expected 0x%02X).\n",
                id, VL53L1X_EXPECTED_ID);
        return -1;
    }

    /* 2. Software reset */
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, VL53L1X_SOFT_RESET_GO) < 0) {
        fprintf(stderr, "Error: failed to trigger soft reset.\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */
    if (i2c_write_reg16(handle, VL53L1X_REG_SOFT_RESET, VL53L1X_SOFT_RESET_RESET) < 0) {
        fprintf(stderr, "Error: failed to release soft reset.\n");
        return -1;
    }
    gpioDelay(1000); /* 1 ms */

    /* 3. Verify device is back after reset */
    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION, &id, 1) < 0) {
        fprintf(stderr, "Error: failed to read device ID after reset.\n");
        return -1;
    }
    if (id != VL53L1X_EXPECTED_ID) {
        fprintf(stderr, "Error: device ID 0x%02X not valid after reset.\n", id);
        return -1;
    }

    /* 4. Set default I2C address (0x29) */
    if (i2c_write_reg16(handle, VL53L1X_REG_I2C_SLAVE_ADDR, VL53L1X_ADDR_DEFAULT) < 0) {
        fprintf(stderr, "Error: failed to set I2C address.\n");
        return -1;
    }

    /* 5. Configure VHV (vertical heating) */
    if (i2c_write_reg16(handle, VL53L1X_REG_VHV_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error: failed to configure VHV.\n");
        return -1;
    }

    /* 6. Configure phase calibration */
    if (i2c_write_reg16(handle, VL53L1X_REG_PHASECAL_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to configure phase calibration.\n");
        return -1;
    }

    /* 7. Configure range measurement (100 mm, 50 ms timing budget) */
    if (i2c_write_reg16(handle, VL53L1X_REG_RANGE_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: failed to configure range config.\n");
        return -1;
    }

    /* 8. Set inter-measurement period to 50 ms */
    if (i2c_write_reg16(handle, VL53L1X_REG_INTERMEAS_MS, 0x32) < 0) {
        fprintf(stderr, "Error: failed to set inter-measurement period.\n");
        return -1;
    }

    /* 9. Clear any pending interrupt */
    if (i2c_write_reg16(handle, VL53L1X_REG_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error: failed to clear interrupt.\n");
        return -1;
    }

    /* 10. Start continuous ranging */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE, VL53L1X_SYSTEM_MODE_CONT) < 0) {
        fprintf(stderr, "Error: failed to start continuous ranging.\n");
        return -1;
    }

    return 0;
}

static int vl53l1x_read_distance(int handle, int *distance_mm) {
    uint8_t status = 0;
    uint8_t data[2] = {0};
    int ret;

    /* Check if data is ready */
    ret = i2c_read_reg16(handle, VL53L1X_REG_RANGE_STATUS, &status, 1);
    if (ret < 0) {
        fprintf(stderr, "Error: failed to read range status.\n");
        return -1;
    }

    if ((status & VL53L1X_RANGE_STATUS_DATA_READY) == 0) {
        return 1; /* No data ready yet */
    }

    /* Read 16-bit distance (big-endian) */
    ret = i2c_read_reg16(handle, VL53L1X_REG_RESULT_DISTANCE, data, 2);
    if (ret < 0) {
        fprintf(stderr, "Error: failed to read distance register.\n");
        return -1;
    }

    *distance_mm = (data[0] << 8) | data[1];

    /* Clear interrupt to allow next measurement */
    if (i2c_write_reg16(handle, VL53L1X_REG_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Warning: failed to clear interrupt.\n");
    }

    return 0;
}

/* ---- Circular buffer operations ---- */
static void circular_buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void circular_buffer_add(CircularBuffer *cb, int value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

/* ---- Main ---- */
int main(void) {
    CircularBuffer distance_buffer;
    int distance;
    int consecutive_errors = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR_DEFAULT, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C bus %d at address 0x%02X.\n",
                I2C_BUS, VL53L1X_ADDR_DEFAULT);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure GPIO17 as output for LED */
    gpioSetMode(GPIO_LED, PI_OUTPUT);
    gpioWrite(GPIO_LED, 0);

    /* Initialize circular buffer */
    circular_buffer_init(&distance_buffer);

    /* Register signal handler */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("VL53L1X distance monitor started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (g_running) {
        int rc = vl53l1x_read_distance(g_i2c_handle, &distance);

        if (rc == 0) {
            consecutive_errors = 0;
            circular_buffer_add(&distance_buffer, distance);

            /* Control LED based on threshold */
            if (distance < DISTANCE_THRESHOLD_MM) {
                gpioWrite(GPIO_LED, 1);
            } else {
                gpioWrite(GPIO_LED, 0);
            }

            printf("Distance: %d mm\n", distance);
        } else if (rc < 0) {
            consecutive_errors++;
            fprintf(stderr, "Error reading distance (consecutive: %d).\n",
                    consecutive_errors);
            if (consecutive_errors > 10) {
                fprintf(stderr, "Too many consecutive errors, attempting re-init.\n");
                vl53l1x_init(g_i2c_handle);
                consecutive_errors = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");
    gpioWrite(GPIO_LED, 0);
    i2cClose(g_i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

