#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* Si1102 I2C address (7-bit) */
#define SI1102_ADDR_DEFAULT 0x60

/* Si1102 register addresses */
#define SI1102_REG_PART_ID      0x00
#define SI1102_REG_HW_KEY       0x07
#define SI1102_REG_MEAS_RATE0   0x08
#define SI1102_REG_MEAS_RATE1   0x09
#define SI1102_REG_PS_LED21     0x0F
#define SI1102_REG_PS1_DATA0    0x10
#define SI1102_REG_PS1_DATA1    0x11
#define SI1102_REG_INT_CFG      0x03
#define SI1102_REG_IRQ_ENABLE   0x06
#define SI1102_REG_IRQ_STATUS   0x21
#define SI1102_REG_COMMAND      0x18

/* Si1102 command codes */
#define SI1102_CMD_RESET        0x01
#define SI1102_CMD_PS_FORCE     0x05
#define SI1102_CMD_ALS_FORCE    0x06

/* Hardware key value required for proper operation */
#define SI1102_HW_KEY_VAL       0x17

/* GPIO pin for interrupt (BCM numbering) */
#define GPIO_INTERRUPT_PIN 27

/* Default proximity threshold */
#define DEFAULT_PROXIMITY_THRESHOLD 1000

/* Global variables */
static int i2c_fd = -1;
static FILE *log_file = NULL;
static int proximity_threshold = DEFAULT_PROXIMITY_THRESHOLD;
static int i2c_address = SI1102_ADDR_DEFAULT;
static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t interrupt_flag = 0;
static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

/* Function prototypes */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
static int i2c_read_byte(int fd, uint8_t reg, uint8_t *value);
static int si1102_init(int fd);
static int si1102_read_proximity(int fd, uint16_t *proximity);
static void log_proximity_data(uint16_t proximity, const char *status);
static void signal_handler(int signal);
static void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);

/* I2C write byte helper */
static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

/* I2C read byte helper */
static int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        perror("I2C write (reg select) failed");
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

/* Initialize the Si1102 sensor */
static int si1102_init(int fd) {
    uint8_t part_id;

    /* Read Part ID to verify sensor presence */
    if (i2c_read_byte(fd, SI1102_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error: Failed to read Part ID\n");
        return -1;
    }
    if (part_id != 0x02) {
        fprintf(stderr, "Error: Unexpected Part ID 0x%02X (expected 0x02)\n", part_id);
        return -1;
    }

    /* Reset the sensor */
    if (i2c_write_byte(fd, SI1102_REG_COMMAND, SI1102_CMD_RESET) != 0) {
        fprintf(stderr, "Error: Failed to reset Si1102\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay for reset */

    /* Write Hardware Key */
    if (i2c_write_byte(fd, SI1102_REG_HW_KEY, SI1102_HW_KEY_VAL) != 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY\n");
        return -1;
    }

    /* Configure LED current for PS1 (LED21) */
    if (i2c_write_byte(fd, SI1102_REG_PS_LED21, 0x0F) != 0) {
        fprintf(stderr, "Error: Failed to configure PS_LED21\n");
        return -1;
    }

    /* Set measurement rate to 0 (manual mode) */
    if (i2c_write_byte(fd, SI1102_REG_MEAS_RATE0, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set MEAS_RATE0\n");
        return -1;
    }
    if (i2c_write_byte(fd, SI1102_REG_MEAS_RATE1, 0x00) != 0) {
        fprintf(stderr, "Error: Failed to set MEAS_RATE1\n");
        return -1;
    }

    /* Enable PS1 interrupt */
    if (i2c_write_byte(fd, SI1102_REG_INT_CFG, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to set INT_CFG\n");
        return -1;
    }
    if (i2c_write_byte(fd, SI1102_REG_IRQ_ENABLE, 0x01) != 0) {
        fprintf(stderr, "Error: Failed to set IRQ_ENABLE\n");
        return -1;
    }

    /* Force a proximity measurement */
    if (i2c_write_byte(fd, SI1102_REG_COMMAND, SI1102_CMD_PS_FORCE) != 0) {
        fprintf(stderr, "Error: Failed to force PS measurement\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms delay for measurement */

    return 0;
}

/* Read proximity data from the Si1102 sensor */
static int si1102_read_proximity(int fd, uint16_t *proximity) {
    uint8_t low, high;

    if (i2c_read_byte(fd, SI1102_REG_PS1_DATA0, &low) != 0) {
        fprintf(stderr, "Error: Failed to read PS1_DATA0\n");
        return -1;
    }
