static void signal_handler(int signal) {
    (void)signal;
    running = 0;
}

/* Interrupt handler (runs in pigpio thread) */
static void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio;
    (void)level;
    (void)tick;
    (void)user_data;
    interrupt_flag = 1;
}

