    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error: Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    /* Set I2C slave address */
    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        perror("Error: Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    /* Initialize the Si1102 sensor */
    if (si1102_init(i2c_fd) != 0) {
        fprintf(stderr, "Error: Si1102 initialisation failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

