    log_file = fopen("proximity.log", "a");
    if (log_file == NULL) {
        perror("Error: Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    /* Configure GPIO pin for interrupt */
    if (gpioSetMode(GPIO_INTERRUPT_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO mode\n");
        fclose(log_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(GPIO_INTERRUPT_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: Failed to set GPIO pull-up\n");
        fclose(log_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    /* Set up interrupt handler */
    if (gpioSetISRFuncEx(GPIO_INTERRUPT_PIN, RISING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error: Failed to set ISR function\n");
        fclose(log_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error: Failed to set SIGINT handler");
        gpioSetISRFuncEx(GPIO_INTERRUPT_PIN, RISING_EDGE, 0, NULL, NULL);
        fclose(log_file);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        if (interrupt_flag) {
            interrupt_flag = 0;
            uint16_t proximity;
            if (si1102_read_proximity(i2c_fd, &proximity) == 0) {
                const char *status = (proximity <= proximity_threshold) ? "SAFE" : "ALERT";
