#define MAX_DISTANCE_CM  200.0f
#define MIN_FREQUENCY_HZ 200.0f
#define MAX_FREQUENCY_HZ 2000.0f

#define ECHO_TIMEOUT_US  200000   /* 200 ms */
#define SAMPLE_PERIOD_US 50000    /* 50 ms  */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* HC-SR04 measurement                                                 */
/* ------------------------------------------------------------------ */
/*
 * Returns distance in cm, or -1.0 on timeout / out-of-range / error.
 */
static float read_distance(void)
{
    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }
    gpioDelay(5);  /* settle */

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -1.0f;
    }
    gpioDelay(10);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -1.0f;
    }

    /* Wait for echo rising edge (timeout) */
    uint32_t start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo rising-edge timeout\n");
            return -1.0f;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (timeout) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((gpioTick() - echo_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo falling-edge timeout\n");
            return -1.0f;
        }
    }
    uint32_t echo_end = gpioTick();

    uint32_t diff = echo_end - echo_start;
    float distance = (float)diff / 58.0f;  /* cm per µs */

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f, %.0f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0f;
    }

    return distance;
}

/* ------------------------------------------------------------------ */
/* Frequency mapping                                                   */
/* ------------------------------------------------------------------ */
static float distance_to_frequency(float distance)
{
    if (distance < MIN_DISTANCE_CM) distance = MIN_DISTANCE_CM;
    if (distance > MAX_DISTANCE_CM) distance = MAX_DISTANCE_CM;

    float norm = (distance - MIN_DISTANCE_CM) /
                 (MAX_DISTANCE_CM - MIN_DISTANCE_CM);
    float log_freq = MIN_FREQUENCY_HZ *
                     powf(MAX_FREQUENCY_HZ / MIN_FREQUENCY_HZ, norm);
    return log_freq;
}

/* ------------------------------------------------------------------ */
/* PWM control                                                         */
/* ------------------------------------------------------------------ */
static int set_pwm_frequency(float frequency)
{
    if (frequency <= 0.0f) {
        fprintf(stderr, "Error: invalid frequency %.2f Hz\n", frequency);
        return -1;
    }

    /*
     * pigpio hardware PWM on GPIO18 supports a range of 0–255.
     * We use a 50 % duty cycle, so the range value is 128.
     */
    int range = 128;
    int actual = gpioHardwarePWM(PWM_PIN, (int)frequency, range);
    if (actual < 0) {
        fprintf(stderr, "Error: gpioHardwarePWM failed (rc=%d)\n", actual);
        return -1;
    }
    return 0;
}

static int stop_pwm(void)
{
    return gpioHardwarePWM(PWM_PIN, 0, 0);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO configuration ----------------------------------------- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(PWM) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);

    /* --- Signal handlers ------------------------------------------- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Theremin started. Press Ctrl+C to exit.\n");

    float prev_frequency = MIN_FREQUENCY_HZ;
    int consecutive_errors = 0;

    while (g_running) {
        float distance = read_distance();

        if (distance < 0.0f) {
            consecutive_errors++;
            fprintf(stderr, "Warning: sensor read failed (%d consecutive)\n",
                    consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Error: too many consecutive failures, aborting\n");
                break;
            }
            /* Preserve previous frequency on error */
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        consecutive_errors = 0;
        float frequency = distance_to_frequency(distance);

        if (set_pwm_frequency(frequency) < 0) {
            fprintf(stderr, "Warning: failed to set PWM frequency\n");
        } else {
            prev_frequency = frequency;
        }

        printf("Distance: %6.2f cm  ->  Frequency: %7.2f Hz\n",
               distance, frequency);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* --- Cleanup ---------------------------------------------------- */
    printf("\nShutting down...\n");
    stop_pwm();
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

