#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   50000   /* 50 ms */
#define LOOP_DELAY_US     500000  /* 500 ms */

#define MIN_DISTANCE_CM  2.0f
#define MAX_DISTANCE_CM  400.0f
#define TOO_CLOSE_CM     10.0f
#define SPEED_OF_SOUND   34300.0f /* cm/s at 20 °C */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure the echo pulse duration in microseconds.
 * Returns the duration in microseconds, or -1 on timeout / error.
 */
static long measure_echo_pulse(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Wait for echo to go high (start of pulse) */
    start_tick = gpioTick();
    timeout_tick = start_tick + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0)
            return -1;
    }

    /* Measure how long the echo stays high */
    start_tick = gpioTick();
    timeout_tick = start_tick + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0)
            return -1;
    }
    end_tick = gpioTick();

    return (long)(end_tick - start_tick);
}

/*
 * Trigger the HC-SR04: 10 µs high pulse on TRIGGER_PIN.
 */
static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/*
 * Convert echo pulse duration (µs) to distance (cm).
 * distance = (duration * speed_of_sound) / 2
 */
static float calculate_distance_cm(long pulse_us)
{
    if (pulse_us < 0)
        return -1.0f;
    return (float)pulse_us * SPEED_OF_SOUND / 2000000.0f;
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); /* 1 ms settle */

    printf("HC-SR04 distance measurement started.\n");
    printf("Trigger: GPIO%d | Echo: GPIO%d | Loop: %d ms\n",
           TRIGGER_PIN, ECHO_PIN, LOOP_DELAY_US / 1000);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        trigger_sensor();

        long pulse_us = measure_echo_pulse();
        float distance = calculate_distance_cm(pulse_us);

        if (distance < 0.0f) {
            printf("Invalid reading (timeout or error)\n");
        } else if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            printf("Invalid reading (%.2f cm out of range)\n", distance);
        } else {
            printf("Distance: %.2f cm", distance);
            if (distance < TOO_CLOSE_CM)
                printf("  Too close!");
            printf("\n");
        }

        /* Sleep 500 ms between measurements */
        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

