    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(1000); /* 1 ms settle */

    printf("HC-SR04 distance measurement started.\n");
    printf("Trigger: GPIO%d | Echo: GPIO%d | Loop: %d ms\n",
           TRIGGER_PIN, ECHO_PIN, LOOP_DELAY_US / 1000);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        trigger_sensor();

        long pulse_us = measure_echo_pulse();
        float distance = calculate_distance_cm(pulse_us);

        if (distance < 0.0f) {
            printf("Invalid reading (timeout or error)\n");
        } else if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            printf("Invalid reading (%.2f cm out of range)\n", distance);
        } else {
