#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL    0          /* CE0 / GPIO8 */
#define SPI_SPEED      1000000    /* 1 MHz */
#define SPI_FLAGS      0          /* mode 0, active-low CS, 8-bit words */
#define LOG_FILE       "distance_log.csv"
#define SAMPLE_PERIOD  100000     /* 100 ms in microseconds */

/* ----------------------------- Globals ----------------------------------- */
static int      spi_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  initialize_spi(void);
static int  read_distance(uint16_t *distance_mm);
static void log_data(uint16_t distance_mm);
static void signal_handler(int sig);
static void cleanup(void);

/*
 * Initialise the SPI bus.
 * Returns 0 on success, -1 on failure.
 */
static int initialize_spi(void)
{
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "[ERROR] spiOpen failed (pigpio error %d)\n", spi_handle);
        return -1;
    }
    return 0;
}

/*
 * Read distance from the ICU-20201 over SPI.
 * The sensor returns a 16-bit big-endian value in mm.
 * Returns 0 on success, -1 on SPI transfer failure.
 */
static int read_distance(uint16_t *distance_mm)
{
    char tx[2] = {0x00, 0x00};   /* dummy bytes to clock out data */
    char rx[2] = {0x00, 0x00};

    int ret = spiXfer(spi_handle, tx, rx, 2);
    if (ret != 2) {
        fprintf(stderr, "[ERROR] spiXfer returned %d (expected 2)\n", ret);
        return -1;
    }

    *distance_mm = ((uint16_t)(uint8_t)rx[0] << 8) | (uint8_t)rx[1];
    return 0;
}

/*
 * Append a timestamped distance reading to the CSV log.
 */
static void log_data(uint16_t distance_mm)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s,%u\n", timestamp, distance_mm);
    fflush(log_file);
}

/*
 * Signal handler – set flag so main loop can exit cleanly.
 */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/*
 * Release all resources.
 */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void)
{
    /* --- pigpio init ---------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- SPI init ------------------------------------------------------- */
    if (initialize_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file ------------------------------------------------------- */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
        fflush(log_file);
    }

    /* --- Signal handlers ----------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ICU-20201 logging started. Press Ctrl+C to stop.\n");

    /* --- Main loop ------------------------------------------------------ */
    while (!terminate) {
        uint16_t distance = 0;

        if (read_distance(&distance) == 0) {
            log_data(distance);
        } else {
            fprintf(stderr, "[WARN] SPI read failed – continuing\n");
        }

        gpioDelay(SAMPLE_PERIOD);
    }

    /* --- Cleanup -------------------------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

