#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Si1120 I2C address (7-bit) */
#define SI1120_ADDR 0x60

/* Si1120 register addresses */
#define SI1120_REG_PART_ID       0x00
#define SI1120_REG_HW_KEY        0x07
#define SI1120_REG_ALS_VIS_DATA0 0x22
#define SI1120_REG_ALS_VIS_DATA1 0x23
#define SI1120_REG_PS1_DATA0     0x26
#define SI1120_REG_PS1_DATA1     0x27
#define SI1120_REG_COMMAND       0x30

/* Si1120 command values */
#define SI1120_CMD_RESET         0x01
#define SI1120_CMD_ALS_FORCE     0x06
#define SI1120_CMD_PS_FORCE      0x05

/* Expected part ID for Si1120 */
#define SI1120_PART_ID           0x20

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 500000

/* Retry parameters */
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a byte to a Si1120 register with retry logic */
static int si1120_write_reg(int handle, uint8_t reg, uint8_t value) {
    int result;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0;
        }
        fprintf(stderr, "Warning: I2C write to reg 0x%02X failed (attempt %d/%d), error: %d\n",
                reg, attempt + 1, MAX_RETRIES, result);
        gpioDelay(RETRY_DELAY_US);
    }
    fprintf(stderr, "Error: I2C write to reg 0x%02X failed after %d attempts\n", reg, MAX_RETRIES);
    return -1;
}

/* Read a byte from a Si1120 register with retry logic */
static int si1120_read_reg(int handle, uint8_t reg) {
    int result;
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        result = i2cReadByteData(handle, reg);
        if (result >= 0) {
            return result;
        }
        fprintf(stderr, "Warning: I2C read from reg 0x%02X failed (attempt %d/%d), error: %d\n",
                reg, attempt + 1, MAX_RETRIES, result);
        gpioDelay(RETRY_DELAY_US);
    }
    fprintf(stderr, "Error: I2C read from reg 0x%02X failed after %d attempts\n", reg, MAX_RETRIES);
    return -1;
}

/* Initialize the Si1120 sensor */
static int si1120_init(int handle) {
    /* Reset the sensor */
    if (si1120_write_reg(handle, SI1120_REG_COMMAND, SI1120_CMD_RESET) != 0) {
        fprintf(stderr, "Error: Failed to reset Si1120\n");
        return -1;
    }
    gpioDelay(10000); /* Wait 10 ms for reset to complete */

    /* Write HW_KEY to enable the device */
    if (si1120_write_reg(handle, SI1120_REG_HW_KEY, 0x17) != 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY\n");
        return -1;
    }

    /* Verify part ID */
    int part_id = si1120_read_reg(handle, SI1120_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error: Failed to read part ID\n");
        return -1;
    }
    if (part_id != SI1120_PART_ID) {
        fprintf(stderr, "Error: Unexpected part ID 0x%02X (expected 0x%02X)\n", part_id, SI1120_PART_ID);
        return -1;
    }

    return 0;
}

/* Read ambient light and proximity data from the Si1120 */
static int si1120_read_data(int handle, uint16_t *ambient_light, uint16_t *proximity) {
    /* Trigger ALS measurement */
    if (si1120_write_reg(handle, SI1120_REG_COMMAND, SI1120_CMD_ALS_FORCE) != 0) {
        fprintf(stderr, "Error: Failed to trigger ALS measurement\n");
        return -1;
    }
    gpioDelay(10000); /* Wait 10 ms for measurement */

    /* Read ambient light data (little-endian) */
    int als_low = si1120_read_reg(handle, SI1120_REG_ALS_VIS_DATA0);
    int als_high = si1120_read_reg(handle, SI1120_REG_ALS_VIS_DATA1);
    if (als_low < 0 || als_high < 0) {
        fprintf(stderr, "Error: Failed to read ambient light data\n");
        return -1;
    }
    *ambient_light = (uint16_t)((als_high << 8) | als_low);

    /* Trigger proximity measurement */
    if (si1120_write_reg(handle, SI1120_REG_COMMAND, SI1120_CMD_PS_FORCE) != 0) {
        fprintf(stderr, "Error: Failed to trigger proximity measurement\n");
        return -1;
    }
    gpioDelay(10000); /* Wait 10 ms for measurement */

    /* Read proximity data (little-endian) */
    int ps_low = si1120_read_reg(handle, SI1120_REG_PS1_DATA0);
    int ps_high = si1120_read_reg(handle, SI1120_REG_PS1_DATA1);
    if (ps_low < 0 || ps_high < 0) {
        fprintf(stderr, "Error: Failed to read proximity data\n");
        return -1;
    }
    *proximity = (uint16_t)((ps_high << 8) | ps_low);

    return 0;
}

/* Log data to file with timestamp */
static int log_data(FILE *fp, uint16_t ambient_light, uint16_t proximity) {
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: Failed to get current time\n");
        return -1;
    }
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: Failed to convert time\n");
        return -1;
    }
    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error: Failed to format timestamp\n");
        return -1;
    }
    if (fprintf(fp, "%s, Ambient Light: %u, Proximity: %u\n", timestamp, ambient_light, proximity) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: Failed to flush log file\n");
        return -1;
    }
    return 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at address 0x%02X: %d\n", I2C_BUS, SI1120_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize Si1120 sensor */
    if (si1120_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: Si1120 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to set SIGINT handler\n");
    }

    printf("Si1120 sensor logging started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (!terminate) {
        uint16_t ambient_light = 0;
        uint16_t proximity = 0;

        if (si1120_read_data(i2c_handle, &ambient_light, &proximity) == 0) {
            if (log_data(log_file, ambient_light, proximity) != 0) {
                fprintf(stderr, "Error: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Cleanup */
    printf("\nCleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

