#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE "/dev/i2c-1"
#define SI1182_I2C_ADDR 0x60

#define SI1182_REG_PART_ID 0x00
#define SI1182_REG_HW_KEY 0x07
#define SI1182_REG_MEAS_RATE 0x08
#define SI1182_REG_ALS_VIS_DATA0 0x22
#define SI1182_REG_PS1_DATA0 0x24

#define SI1182_PART_ID 0x82
#define SI1182_HW_KEY_VAL 0x17
#define SI1182_MEAS_RATE_100MS 0x0A

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *value) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *value = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_si1182(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1182_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read Si1182 part ID (sensor absent or bus error)\n");
        return -1;
    }
    if (part_id != SI1182_PART_ID) {
        fprintf(stderr, "Unexpected part ID: 0x%02X (expected 0x%02X)\n", part_id, SI1182_PART_ID);
        return -1;
    }
    printf("Si1182 detected (part ID: 0x%02X)\n", part_id);

    if (i2c_write_reg8(fd, SI1182_REG_HW_KEY, SI1182_HW_KEY_VAL) != 0) return -1;
    if (i2c_write_reg8(fd, SI1182_REG_MEAS_RATE, SI1182_MEAS_RATE_100MS) != 0) return -1;

    printf("Si1182 initialized: measurement rate = 100 ms\n");
    return 0;
}

static void get_timestamp(char *buf, size_t len) {
    struct timespec ts;
    struct tm tm_info;
    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t pos = strlen(buf);
    snprintf(buf + pos, len - pos, ".%03ld", ts.tv_nsec / 1000000);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("open " I2C_DEVICE);
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_I2C_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return 1;
    }

    if (init_si1182(i2c_fd) != 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("biometric_log.txt", "a");
    if (!log_file) {
        perror("fopen biometric_log.txt");
        close(i2c_fd);
        return 1;
    }

    printf("Logging to biometric_log.txt (Ctrl+C to stop)\n");

    while (running) {
        uint16_t lux_raw, prox_raw;
        char timestamp[32];

        if (i2c_read_reg16(i2c_fd, SI1182_REG_ALS_VIS_DATA0, &lux_raw) != 0) {
            fprintf(stderr, "Failed to read lux data\n");
            usleep(100000);
            continue;
        }
        if (i2c_read_reg16(i2c_fd, SI1182_REG_PS1_DATA0, &prox_raw) != 0) {
            fprintf(stderr, "Failed to read proximity data\n");
            usleep(100000);
            continue;
        }

        get_timestamp(timestamp, sizeof(timestamp));
        fprintf(log_file, "%s,%u,%u\n", timestamp, lux_raw, prox_raw);
        fflush(log_file);
        printf("%s,%u,%u\n", timestamp, lux_raw, prox_raw);

        usleep(100000);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return 0;
}

