#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Si1145 I2C address (7-bit) */
#define SI1145_ADDR 0x60

/* Si1145 register addresses */
#define SI1145_REG_PART_ID       0x00
#define SI1145_REG_HW_KEY        0x07
#define SI1145_REG_MEAS_RATE0    0x08
#define SI1145_REG_MEAS_RATE1    0x09
#define SI1145_REG_PS_LED21      0x0F
#define SI1145_REG_PS1_DATA0     0x10
#define SI1145_REG_PS1_DATA1     0x11
#define SI1145_REG_COMMAND       0x18

/* Si1145 command codes */
#define SI1145_CMD_RESET         0x01
#define SI1145_CMD_PS_FORCE      0x05
#define SI1145_CMD_ALS_FORCE     0x06

/* Expected PART_ID for Si1145 */
#define SI1145_PART_ID_EXPECTED  0x45

/* Retry configuration */
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* Function prototypes */
static int si1145_write_reg(int handle, uint8_t reg, uint8_t value);
static int si1145_read_reg(int handle, uint8_t reg, uint8_t *value);
static int si1145_init(int handle);
static int si1145_read_proximity(int handle, uint16_t *proximity);
static void log_data(FILE *fp, uint16_t proximity);
static void log_error(FILE *fp, const char *message);
static void signal_handler(int sig);

/* Write a byte to a Si1145 register with retries */
static int si1145_write_reg(int handle, uint8_t reg, uint8_t value) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByteData(handle, reg, value);
        if (rc == 0) {
            return 0;
        }
        fprintf(stderr, "I2C write error (reg 0x%02X, val 0x%02X): %d (attempt %d/%d)\n",
                reg, value, rc, attempt + 1, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* Read a byte from a Si1145 register with retries */
static int si1145_read_reg(int handle, uint8_t reg, uint8_t *value) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadByteData(handle, reg);
        if (rc >= 0) {
            *value = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "I2C read error (reg 0x%02X): %d (attempt %d/%d)\n",
                reg, rc, attempt + 1, MAX_RETRIES);
        gpioDelay(RETRY_DELAY_US);
    }
    return -1;
}

/* Initialize the Si1145 sensor */
static int si1145_init(int handle) {
    uint8_t part_id = 0;

    /* Read and verify PART_ID */
    if (si1145_read_reg(handle, SI1145_REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Failed to read PART_ID after %d retries.\n", MAX_RETRIES);
        return -1;
    }
    if (part_id != SI1145_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X). Sensor not present?\n",
                part_id, SI1145_PART_ID_EXPECTED);
        return -1;
    }
    printf("Si1145 detected (PART_ID = 0x%02X).\n", part_id);

    /* Reset the device */
    if (si1145_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_RESET) != 0) {
        fprintf(stderr, "Failed to reset Si1145.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms reset delay */

    /* Write HW_KEY (required after reset) */
    if (si1145_write_reg(handle, SI1145_REG_HW_KEY, 0x17) != 0) {
        fprintf(stderr, "Failed to write HW_KEY.\n");
        return -1;
    }

    /* Configure measurement rate (0x00 = manual, 0xFF = 100 ms default) */
    if (si1145_write_reg(handle, SI1145_REG_MEAS_RATE0, 0x00) != 0) {
        fprintf(stderr, "Failed to set MEAS_RATE0.\n");
        return -1;
    }
    if (si1145_write_reg(handle, SI1145_REG_MEAS_RATE1, 0x00) != 0) {
        fprintf(stderr, "Failed to set MEAS_RATE1.\n");
        return -1;
    }

    /* Configure LED current for PS1 (LED1 ~ 22.4 mA) */
    if (si1145_write_reg(handle, SI1145_REG_PS_LED21, 0x0F) != 0) {
        fprintf(stderr, "Failed to set PS_LED21.\n");
        return -1;
    }

    /* Force a proximity measurement */
    if (si1145_write_reg(handle, SI1145_REG_COMMAND, SI1145_CMD_PS_FORCE) != 0) {
        fprintf(stderr, "Failed to force PS measurement.\n");
        return -1;
    }
    gpioDelay(10000); /* 10 ms conversion time */

    printf("Si1145 initialized successfully.\n");
    return 0;
}

/* Read 16-bit proximity data from PS1_DATA0 and PS1_DATA1 */
static int si1145_read_proximity(int handle, uint16_t *proximity) {
    uint8_t ps1_data0 = 0, ps1_data1 = 0;

    if (si1145_read_reg(handle, SI1145_REG_PS1_DATA0, &ps1_data0) != 0) {
        fprintf(stderr, "Failed to read PS1_DATA0.\n");
        return -1;
    }
    if (si1145_read_reg(handle, SI1145_REG_PS1_DATA1, &ps1_data1) != 0) {
        fprintf(stderr, "Failed to read PS1_DATA1.\n");
        return -1;
    }

    *proximity = ((uint16_t)ps1_data1 << 8) | ps1_data0;
    return 0;
}

/* Log proximity data with timestamp */
static void log_data(FILE *fp, uint16_t proximity) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed.\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, proximity);
    fflush(fp);
}

/* Log error message with timestamp */
static void log_error(FILE *fp, const char *message) {
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed.\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(fp);
}

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at Si1145 address */
    g_i2c_handle = i2cOpen(1, SI1145_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n",
                SI1145_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (si1145_init(g_i2c_handle) != 0) {
        fprintf(stderr, "Si1145 initialization failed.\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("proximity_log.txt", "a");
    if (g_log_file == NULL) {
