#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18
#define BUZZER_PIN  27

#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define DISTANCE_THRESHOLD_CM   20.0
#define TRIGGER_PULSE_US        10
#define ECHO_TIMEOUT_US         30000  /* 30 ms (~5 m round trip) */
#define LOOP_DELAY_US           1000000 /* 1 s */

static volatile uint32_t g_rise_tick = 0;
static volatile uint32_t g_fall_tick = 0;
static volatile int      g_echo_done = 0;

static void sigint_handler(int sig)
{
    (void)sig;
    fprintf(stderr, "\nSIGINT received, cleaning up...\n");
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    exit(0);
}

/*
 * pigpio alert callback for the echo pin.
 * level == 1 -> rising edge, level == 0 -> falling edge.
 */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        g_rise_tick = tick;
    } else if (level == 0) {
        g_fall_tick = tick;
        g_echo_done = 1;
    }
}

static void trigger_sensor(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

static double calculate_distance_cm(uint32_t pulse_us)
{
    /* distance = (pulse_us * speed_of_sound) / 2 / 1e6 */
    return (double)pulse_us * SPEED_OF_SOUND_CM_PER_S / 2000000.0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Register SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    /* Configure pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set BUZZER_PIN %d as output.\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    gpioWrite(BUZZER_PIN, 0);

    /* Register alert callback for echo pin */
    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) != 0) {
        fprintf(stderr, "Error: failed to set alert function for ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (1) {
        g_echo_done = 0;
        g_rise_tick = 0;
        g_fall_tick = 0;

        trigger_sensor();

        /* Wait for echo with timeout */
        uint32_t start = gpioTick();
        while (!g_echo_done) {
            if ((gpioTick() - start) > ECHO_TIMEOUT_US) {
                fprintf(stderr, "Warning: echo timeout (no object detected or sensor fault).\n");
                g_echo_done = 1;
                break;
            }
            gpioDelay(100); /* 100 µs poll interval */
        }

        if (g_echo_done) {
            uint32_t pulse_us = g_fall_tick - g_rise_tick;
            double distance = calculate_distance_cm(pulse_us);

            printf("Distance: %.2f cm\n", distance);

            if (distance < DISTANCE_THRESHOLD_CM) {
                gpioWrite(BUZZER_PIN, 1);
            } else {
                gpioWrite(BUZZER_PIN, 0);
            }
        } else {
            /* Timeout: ensure buzzer is off for safety */
            gpioWrite(BUZZER_PIN, 0);
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Unreachable in normal operation, but kept for completeness */
    gpioWrite(BUZZER_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

