/*
 * Parking-assist system for Raspberry Pi Zero W
 * HC-SR04 ultrasonic sensor: trigger=GPIO4 (BCM), echo=GPIO17 (BCM)
 * SG90 servo motor: signal=GPIO18 (BCM)
 *
 * Distance (cm) | Servo angle (deg)
 * --------------+-------------------
 *   200..200    |        0
 *   110..199    |       90
 *    20..109    |      180
 *
 * Build: gcc -O2 -Wall -o parking_assist parking_assist.c -lpigpio -lrt
 * Run:   sudo ./parking_assist
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 4
#define ECHO_PIN    17
#define SERVO_PIN   18

#define SPEED_OF_SOUND_CM_PER_US 0.0343
#define TIMEOUT_US               30000   /* 30 ms timeout for echo */
#define LOOP_DELAY_US            100000  /* 100 ms between readings */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in cm.
 * Returns distance on success, -1.0 on timeout / error.
 */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger is low for at least 2 us before pulsing */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(5);

    /* 10 us trigger pulse */
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10);
    gpioWrite(TRIGGER_PIN, 0);

    /* Wait for echo rising edge (timeout) */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0)
            return -1.0f;
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    timeout_tick = gpioTick() + TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0)
            return -1.0f;
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    return (float)diff * SPEED_OF_SOUND_CM_PER_US / 2.0f;
}

static void set_servo_angle(int angle)
{
    if (angle < 0)   angle = 0;
    if (angle > 180) angle = 180;

    /*
     * SG90 pulse width: 500 us = 0 deg, 1500 us = 90 deg, 2500 us = 180 deg
     * pigpio servoWrite takes pulse width in microseconds (0-2000000).
     */
    int pulse_width = 500 + (angle * 1000);
    gpioServo(SERVO_PIN, pulse_width);
}

int main(void)
{
    /* Install SIGINT handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set echo pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set servo pin mode.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50);

    printf("Parking assist system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Warning: sensor read error or timeout.\n");
        } else {
            int angle;
            if (distance >= 200.0f) {
                angle = 0;
            } else if (distance >= 110.0f) {
                angle = 90;
            } else {
                angle = 180;
