/*
 * VL53L1X time-of-flight gate controller for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   VL53L1X SDA -> GPIO2 (I2C bus 1 SDA)
 *   VL53L1X SCL -> GPIO3 (I2C bus 1 SCL)
 *   VL53L1X VDD -> 3.3 V
 *   VL53L1X GND -> GND
 *   Gate control signal -> GPIO18 (hardware PWM0)
 *
 * Build:
 *   gcc -O2 -Wall -o gate_ctrl gate_ctrl.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- VL53L1X constants (from ST application note AN4545) ---- */
#define VL53L1X_ADDR_DEFAULT 0x29
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x010F
#define VL53L1X_REG_SYSTEM_MODE_START_STOP 0x0000
#define VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR 0x0086
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0089
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0096
#define VL53L1X_REG_SYSTEM_INTERMEASUREMENT_PERIOD 0x000B
#define VL53L1X_REG_SYSTEM_RANGE_CONFIG 0x0082
#define VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO 0x0046
#define VL53L1X_REG_GPIO_HV_MUX_ACTIVE_HIGH 0x0030
#define VL53L1X_REG_PHASECAL_LIMIT 0x0040
#define VL53L1X_REG_SD_CONFIG_WOI_SD0 0x000A
#define VL53L1X_REG_SD_CONFIG_INIT_PHASE 0x0044
#define VL53L1X_REG_SD_CONFIG_QUALITY 0x0045

#define VL53L1X_EXPECTED_MODEL_ID 0xEA
#define VL53L1X_TIMING_BUDGET_MS 50

/* ---- Gate control constants ---- */
#define GATE_GPIO 18
#define DISTANCE_THRESHOLD_CLOSE_MM 200
#define DISTANCE_THRESHOLD_FAR_MM 250
#define PWM_FREQ_HZ 50
#define PWM_RANGE 2000000  /* 2 ms period -> 500 Hz */
#define PWM_PULSE_CLOSE_US 2000
#define PWM_PULSE_FAR_US 1000
#define PWM_PULSE_STEP 100
#define POLL_DELAY_US 100000  /* 100 ms */

/* ---- Globals for cleanup ---- */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
static int i2c_write_reg16(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = value;
    return i2cWriteDevice(handle, buf, 3);
}

/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int handle, uint16_t reg, uint8_t *buf, uint8_t len)
{
    char reg_buf[2];
    reg_buf[0] = (reg >> 8) & 0xFF;
    reg_buf[1] = reg & 0xFF;
    if (i2cWriteDevice(handle, reg_buf, 2) < 0)
        return -1;
    return i2cReadDevice(handle, (char *)buf, len);
}

/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    uint8_t model_id = 0;

    /* Verify model ID */
    if (i2c_read_reg16(handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID, &model_id, 1) < 0) {
        fprintf(stderr, "Error: failed to read model ID register.\n");
        return -1;
    }
    if (model_id != VL53L1X_EXPECTED_MODEL_ID) {
        fprintf(stderr, "Error: unexpected model ID 0x%02X (expected 0x%02X).\n",
                model_id, VL53L1X_EXPECTED_MODEL_ID);
        return -1;
    }
    printf("VL53L1X detected (model ID 0x%02X).\n", model_id);

    /* Stop any ongoing ranging */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START_STOP, 0x00) < 0) {
        fprintf(stderr, "Error: failed to stop ranging.\n");
        return -1;
    }

    /* Clear any pending interrupt */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0) {
        fprintf(stderr, "Error: failed to clear interrupt.\n");
        return -1;
    }

    /* Set timing budget (50 ms) */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_RANGE_CONFIG, 0x000A) < 0) {
        fprintf(stderr, "Error: failed to set timing budget.\n");
        return -1;
    }

    /* Configure interrupt GPIO (active low, new sample ready) */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO, 0x04) < 0) {
        fprintf(stderr, "Error: failed to configure interrupt.\n");
        return -1;
    }

    /* Set inter-measurement period to 100 ms (0x0064) */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERMEASUREMENT_PERIOD, 0x0064) < 0) {
        fprintf(stderr, "Error: failed to set inter-measurement period.\n");
        return -1;
    }

    /* Start ranging */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_MODE_START_STOP, 0x40) < 0) {
        fprintf(stderr, "Error: failed to start ranging.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle, uint16_t *distance_mm)
{
    uint8_t status = 0;
    uint8_t data[2];

    /* Check data ready (bit 0 of RESULT_RANGE_STATUS) */
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_RANGE_STATUS, &status, 1) < 0)
        return -1;

    if (!(status & 0x01))
        return 1;  /* not ready yet */

    /* Read 16-bit distance */
    if (i2c_read_reg16(handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0,
                       data, 2) < 0)
        return -1;

    *distance_mm = ((uint16_t)data[0] << 8) | data[1];

    /* Clear interrupt */
    if (i2c_write_reg16(handle, VL53L1X_REG_SYSTEM_INTERRUPT_CLEAR, 0x01) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static void gate_set_pulse(int pulse_us)
{
    /* pigpio hardware PWM: pulse width in microseconds, range in microseconds */
    gpioHardwarePWM(GATE_GPIO, PWM_FREQ_HZ, pulse_us);
}

/* ------------------------------------------------------------------ */
static void gate_log_event(const char *event)
{
    if (!log_file)
        return;

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL)
        return;

    fprintf(log_file, "%04d-%02d-%02d %02d:%02d:%02d: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2c_write_reg16(i2c_handle, VL53L1X_REG_SYSTEM_MODE_START_STOP, 0x00);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioHardwarePWM(GATE_GPIO, PWM_FREQ_HZ, 0);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    int current_pulse = PWM_PULSE_FAR_US;
    int target_pulse = PWM_PULSE_FAR_US;
    int gate_open = 0;
    uint16_t distance = 0;
    int consecutive_errors = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at default address */
    i2c_handle = i2cOpen(1, VL53L1X_ADDR_DEFAULT, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: VL53L1X initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure GPIO18 for hardware PWM */
    gpioSetMode(GATE_GPIO, PI_OUTPUT);
    gpioHardwarePWM(GATE_GPIO, PWM_FREQ_HZ, PWM_PULSE_FAR_US);

    /* Open log file */
    log_file = fopen("gate_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Error: failed to open gate_log.txt.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler.\n");
    }

    printf("Gate control started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        int rc = vl53l1x_read_distance(i2c_handle, &distance);

        if (rc == 0) {
            consecutive_errors = 0;

            /* Hysteresis: close when object is closer than 200 mm,
             * open when object is farther than 250 mm. */
            if (distance < DISTANCE_THRESHOLD_CLOSE_MM && !gate_open) {
                target_pulse = PWM_PULSE_CLOSE_US;
            } else if (distance > DISTANCE_THRESHOLD_FAR_MM && gate_open) {
                target_pulse = PWM_PULSE_FAR_US;
            }

            /* Smooth transition towards target pulse */
            if (current_pulse < target_pulse) {
                current_pulse += PWM_PULSE_STEP;
                if (current_pulse > target_pulse)
                    current_pulse = target_pulse;
            } else if (current_pulse > target_pulse) {
                current_pulse -= PWM_PULSE_STEP;
                if (current_pulse < target_pulse)
                    current_pulse = target_pulse;
            }

            gate_set_pulse(current_pulse);

            if (current_pulse == PWM_PULSE_CLOSE_US && !gate_open) {
                gate_log_event("Gate opened");
                gate_open = 1;
            } else if (current_pulse == PWM_PULSE_FAR_US && gate_open) {
                gate_log_event("Gate closed");
                gate_open = 0;
            }
        } else if (rc < 0) {
            consecutive_errors++;
            fprintf(stderr, "Error: I2C read failed (consecutive=%d).\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Fatal: too many consecutive I2C errors, aborting.\n");
                break;
            }
        }
        /* rc == 1: data not ready, just wait */

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

