#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 23
#define ECHO_PIN    24
#define SERVO_PIN   18

#define SPEED_OF_SOUND_CM_PER_S 34300.0
#define MIN_DISTANCE_CM         2.0
#define MAX_DISTANCE_CM         400.0
#define MIN_ANGLE_DEG           0
#define MAX_ANGLE_DEG           180
#define MIN_PULSE_WIDTH_US      500
#define MAX_PULSE_WIDTH_US      2500
#define TRIGGER_PULSE_US        10
#define ECHO_TIMEOUT_US         50000
#define LOOP_DELAY_US           100000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance (cm) using the HC-SR04.
 * Returns -1.0 on timeout or if the distance is outside the valid range.
 */
static float measure_distance(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to write trigger high\n");
        return -1.0;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to write trigger low\n");
        return -1.0;
    }

    /* Wait for echo rising edge (timeout 50 ms) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo rising-edge timeout\n");
            return -1.0;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout 50 ms) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: echo falling-edge timeout\n");
            return -1.0;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    float distance = (float)diff * SPEED_OF_SOUND_CM_PER_S / 2000000.0;

    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        fprintf(stderr, "Warning: distance %.2f cm out of range [%.0f, %.0f]\n",
                distance, MIN_DISTANCE_CM, MAX_DISTANCE_CM);
        return -1.0;
    }

    return distance;
}

/*
 * Map distance (cm) to servo angle (degrees).
 * Returns -1 on invalid input.
 */
static int map_distance_to_angle(float distance)
{
    if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
        return -1;
    }

    float angle = (distance - MIN_DISTANCE_CM) *
                  (float)(MAX_ANGLE_DEG - MIN_ANGLE_DEG) /
                  (MAX_DISTANCE_CM - MIN_DISTANCE_CM) + MIN_ANGLE_DEG;

    if (angle < MIN_ANGLE_DEG || angle > MAX_ANGLE_DEG) {
        return -1;
    }

    return (int)(angle + 0.5f);
}

/*
 * Set servo angle (0–180 degrees).
 * Returns 0 on success, -1 on error.
 */
static int set_servo_angle(int angle)
{
    if (angle < MIN_ANGLE_DEG || angle > MAX_ANGLE_DEG) {
        fprintf(stderr, "Error: angle %d out of range [%d, %d]\n",
                angle, MIN_ANGLE_DEG, MAX_ANGLE_DEG);
        return -1;
    }

    int pulse_width = MIN_PULSE_WIDTH_US +
                      (int)((float)angle / MAX_ANGLE_DEG *
                            (MAX_PULSE_WIDTH_US - MIN_PULSE_WIDTH_US));

    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pulse %d µs\n", pulse_width);
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set trigger pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set echo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set servo pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise trigger low\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Allow servo to settle */
    gpioDelay(500000);

    printf("HC-SR04 distance-to-servo control started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = measure_distance();

        if (distance < 0.0f) {
            fprintf(stderr, "Sensor read error or out-of-range; skipping cycle.\n");
        } else {
            int angle = map_distance_to_angle(distance);
            if (angle < 0) {
                fprintf(stderr, "Distance mapping error; skipping cycle.\n");
            } else {
                if (set_servo_angle(angle) < 0) {
                    fprintf(stderr, "Servo control error.\n");
                } else {
                    printf("Distance: %.2f cm  ->  Angle: %d °\n", distance, angle);
                }
            }
        }

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown: stop servo and release pigpio */
    printf("\nShutting down...\n");
    gpioServo(SERVO_PIN, 0);   /* Stop PWM signal to servo */
    gpioWrite(TRIGGER_PIN, 0); /* Ensure trigger is low */
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

