#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Si7005 I2C address (ADDR pin tied to GND) */
#define SI7005_ADDR 0x40

/* Si7005 register addresses */
#define SI7005_REG_TEMP_HOLD   0xE3
#define SI7005_REG_HUMID_HOLD  0xE5
#define SI7005_REG_CONFIG      0xE6

/* CONFIG register bits: heater disabled, 14-bit humidity, 12-bit temp */
#define SI7005_CONFIG_DEFAULT 0x00

/* Global I2C handle for signal handler cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a single byte to a register */
static int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2] = { (char)reg, (char)value };
    if (i2cWriteDevice(handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* Read a 16-bit big-endian value from a register */
static int read_register16(int handle, uint8_t reg, uint16_t *out) {
    char reg_buf[1] = { (char)reg };
    char data[2] = {0};

    if (i2cWriteDevice(handle, reg_buf, 1) != 0) {
        fprintf(stderr, "Error writing register address 0x%02X\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "Error reading 2 bytes from register 0x%02X\n", reg);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* Read temperature in Celsius */
static int read_temperature(int handle, float *temp) {
    uint16_t raw;
    if (read_register16(handle, SI7005_REG_TEMP_HOLD, &raw) != 0) {
        return -1;
    }
    *temp = (175.72f * (float)raw / 65536.0f) - 46.85f;
    return 0;
}

/* Read humidity in %RH */
static int read_humidity(int handle, float *hum) {
    uint16_t raw;
    if (read_register16(handle, SI7005_REG_HUMID_HOLD, &raw) != 0) {
        return -1;
    }
    *hum = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (*hum < 0.0f) *hum = 0.0f;
    if (*hum > 100.0f) *hum = 100.0f;
    return 0;
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si7005 address */
    i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n",
                SI7005_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure sensor: heater off, 14-bit humidity, 12-bit temperature */
    if (write_register(i2c_handle, SI7005_REG_CONFIG, SI7005_CONFIG_DEFAULT) != 0) {
        fprintf(stderr, "Error configuring Si7005\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    printf("Si7005 sensor reading started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature, humidity;

        if (read_temperature(i2c_handle, &temperature) == 0 &&
            read_humidity(i2c_handle, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "Error reading sensor data. Re-opening I2C handle.\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            i2c_handle = i2cOpen(1, SI7005_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error re-opening I2C bus: %d\n", i2c_handle);
                break;
            }
        }

        /* Wait 2 seconds between readings */
        gpioSleep(PI_TIME_RELATIVE, 2, 0);
    }

    /* Cleanup */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

