/*
 * Raspberry Pi 4 Model B - SHT40 Temperature & Humidity Sensor Reader
 *
 * Wiring:
 *   SHT40 VIN  -> Pi 3V3 (Pin 1)
 *   SHT40 GND  -> Pi GND  (Pin 9)
 *   SHT40 SDA  -> Pi GPIO2 / I2C1 SDA (Pin 3)
 *   SHT40 SCL  -> Pi GPIO3 / I2C1 SCL (Pin 5)
 *
 * I2C Bus: /dev/i2c-1, Address: 0x44
 * Measurement command: 0xFD (High Repeatability, clock stretching disabled)
 * Response: 6 bytes [T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC]
 * Conversion: T = T_MSB * 256 + T_LSB, RH = RH_MSB * 256 + RH_LSB
 * CRC-8: polynomial 0x31, initial value 0xFF
 *
 * Build: gcc -Wall -Wextra -O2 -o sht40_reader sht40_reader.c -lpigpio -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SHT40_ADDR     0x44
#define MEASURE_CMD    0xFD
#define READ_LEN       6
#define POLL_INTERVAL  5.0   /* seconds */
#define MEASURE_DELAY  0.02  /* 20 ms (datasheet: max 10 ms for high repeatability) */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static bool crc8_check(const uint8_t *data, size_t len, uint8_t expected)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc == expected;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open_bus(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    g_i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed on bus %d addr 0x%02X: %d\n",
                I2C_BUS, SHT40_ADDR, g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    return 0;
}

static int sht40_read(float *temperature, float *humidity)
{
    uint8_t cmd = MEASURE_CMD;
    uint8_t buf[READ_LEN];

    /* Send measurement command */
    if (i2cWriteDevice(g_i2c_handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (measurement command) failed\n");
        return -1;
    }

    /* Wait for conversion to complete */
    time_sleep(MEASURE_DELAY);

    /* Read 6 bytes: T_MSB, T_LSB, T_CRC, RH_MSB, RH_LSB, RH_CRC */
    if (i2cReadDevice(g_i2c_handle, (char *)buf, READ_LEN) != READ_LEN) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (expected %d bytes)\n", READ_LEN);
        return -1;
    }

    /* Validate CRCs */
    if (!crc8_check(&buf[0], 2, buf[2])) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (!crc8_check(&buf[3], 2, buf[5])) {
        fprintf(stderr, "[ERROR] Humidity CRC mismatch\n");
        return -1;
    }

    /* Convert raw values to physical units */
    uint16_t t_raw = (uint16_t)((buf[0] << 8) | buf[1]);
    uint16_t rh_raw = (uint16_t)((buf[3] << 8) | buf[4]);

    *temperature = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *humidity    = 100.0f * (float)rh_raw / 65535.0f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Register signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Open I2C bus */
    if (i2c_open_bus() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SHT40 reader started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature, humidity;

        if (sht40_read(&temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
        } else {
            fprintf(stderr, "[WARN] Read failed; re-opening I2C bus.\n");
            i2c_open_bus();
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++)
            time_sleep(POLL_INTERVAL / 50.0);
    }

    /* Cleanup */
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

