static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_word(int fd, uint8_t reg, float *out) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    uint8_t buf[3] = {0};
    if (read(fd, buf, 3) != 3) {
        return -1;
    }
    int16_t raw = (int16_t)((buf[1] << 8) | buf[0]);
    *out = raw * 0.02f - 273.15f;
    return 0;
}

static int log_temperature(float ambient, float object) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
