    if (fprintf(log_file, "%s,%.2f,%.2f\n", ts, ambient, object) < 0) {
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        return EXIT_FAILURE;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MLX90614_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen log file");
        close(i2c_fd);
        return EXIT_FAILURE;
    }

    while (running) {
        float ambient = 0.0f, object = 0.0f;
        int ok = 1;

        if (i2c_read_word(i2c_fd, TA, &ambient) != 0) {
            fprintf(stderr, "Error reading ambient temperature\n");
            ok = 0;
        }
        if (ok && i2c_read_word(i2c_fd, TOBJ1, &object) != 0) {
            fprintf(stderr, "Error reading object temperature\n");
            ok = 0;
        }

        if (ok) {
            if (log_temperature(ambient, object) != 0) {
                fprintf(stderr, "Error writing to log file\n");
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    if (log_file) fclose(log_file);
    if (i2c_fd >= 0) close(i2c_fd);
    return EXIT_SUCCESS;
}

