#define MEAS_DELAY_MS  2          /* SDP810 needs >= 1 ms after command */

/* SDP810 continuous measurement command (no arguments) */
static const uint8_t CMD_CONT_MEAS[2] = {0x36, 0x2F};

/* SDP810 read measurement command (no arguments) */
static const uint8_t CMD_READ_MEAS[2] = {0x36, 0x00};

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor initialization                                               */
/* ------------------------------------------------------------------ */
static int sdp810_init(int fd)
{
    /*
     * Start continuous measurement.  The SDP810 returns the first
     * measurement when the read command is issued, so we send the
     * continuous-measurement command and then a dummy read to prime
     * the sensor.
     */
    if (i2c_write_cmd(fd, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) != 0)
        return -1;

    /* Allow the first measurement to be ready */
    usleep(MEAS_DELAY_MS * 1000);

    /* Dummy read to confirm the sensor is responding */
    uint8_t dummy[9];
    if (i2c_read_data(fd, dummy, sizeof(dummy)) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read and convert one sample                                        */
/* ------------------------------------------------------------------ */
static int sdp810_read(int fd, float *pressure, float *temperature)
{
    uint8_t buf[9];

    /* Issue read-measurement command */
    if (i2c_write_cmd(fd, CMD_READ_MEAS, sizeof(CMD_READ_MEAS)) != 0)
        return -1;

    /* Wait for conversion (datasheet: typ 2 ms, max 15 ms) */
    usleep(MEAS_DELAY_MS * 1000);

    /* Read 9 bytes: pressure(2)+crc, temp(2)+crc, scale(2)+crc */
    if (i2c_read_data(fd, buf, sizeof(buf)) != 0)
        return -1;

    /* CRC validation */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "Scale-factor CRC mismatch\n");
        return -1;
    }

    int16_t raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    int16_t scale_factor    = (int16_t)((buf[6] << 8) | buf[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Invalid scale factor (0)\n");
        return -1;
    }

    *pressure    = (float)raw_pressure    / (float)scale_factor;
    *temperature = (float)raw_temperature / (float)scale_factor;

    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_data(const char *filename, float pressure, float temperature)
{
    /* Check if file exists to decide on header */
    bool need_header = (access(filename, F_OK) != 0);

    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    if (need_header)
        fprintf(fp, "timestamp,pressure_pa,temperature_c\n");

    time_t t = time(NULL);
    struct tm tm_utc;
    gmtime_r(&t, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", filename, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Set slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SDP810_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (sdp810_init(g_i2c_fd) != 0) {
        fprintf(stderr, "SDP810 initialization failed (sensor absent or bus error)\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("SDP810 logger started. Logging to %s every %d s. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_PERIOD);

    /* Main sampling loop */
    while (g_running) {
        float pressure, temperature;

        if (sdp810_read(g_i2c_fd, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
            if (log_data(LOG_FILE, pressure, temperature) != 0)
                fprintf(stderr, "Logging failed\n");
        } else {
            fprintf(stderr, "Sensor read failed; continuing\n");
        }

        /* Sleep but wake early on signal */
        for (int i = 0; i < SAMPLE_PERIOD && g_running; i++)
            sleep(1);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);

    return EXIT_SUCCESS;
}

