#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SDP31_ADDR 0x21
#define LOG_FILE "airflow.log"
#define SAMPLE_INTERVAL_US 100000
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 2000

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, SDP31_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, SDP31_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_log(void) {
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }
    return 0;
}

static int send_trigger(void) {
    uint8_t cmd[2] = {0x36, 0x15};
    int rc = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (rc < 0) {
        fprintf(stderr, "Error sending trigger command: %d\n", rc);
        return -1;
    }
    return 0;
}

static int read_measurement(uint8_t *buf, int len) {
    int rc = i2cReadDevice(i2c_handle, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "Error reading measurement: expected %d bytes, got %d\n",
                len, rc);
        return -1;
    }
    return 0;
}

static int convert(const uint8_t *buf, float *pressure, float *temperature) {
    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);

    *pressure = (float)raw_pressure / 60.0f;
    *temperature = (float)raw_temperature / 200.0f;
    return 0;
}

static int log_data(float pressure, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        perror("Error getting local time");
        return -1;
    }
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    if (fflush(log_file) != 0) {
        perror("Error flushing log file");
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Error registering SIGINT handler");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error registering SIGTERM handler");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_log() != 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t buf[6];
    float pressure, temperature;
    int retries;

    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES && !terminate) {
            if (send_trigger() == 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                gpioDelay(100000 * retries);
            }
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to send trigger after %d retries\n", MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        retries = 0;
        while (retries < MAX_RETRIES && !terminate) {
            if (read_measurement(buf, 6) == 0) {
                break;
            }
            retries++;
            if (retries < MAX_RETRIES) {
                gpioDelay(100000 * retries);
            }
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read measurement after %d retries\n", MAX_RETRIES);
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (convert(buf, &pressure, &temperature) != 0) {
            fprintf(stderr, "Error converting measurement data\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (log_data(pressure, temperature) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
}

