/*
 * Si7015 Temperature & Humidity Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Si7015 SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   Si7015 SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   Si7015 VDD  -> 3.3 V (pin 1)
 *   Si7015 GND  -> GND  (pin 6)
 *
 * I2C address: 0x40 (7-bit)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o si7015_reader si7015_reader.c -lpigpio -lrt
 * Run:
 *   sudo ./si7015_reader
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ---- Si7015 constants (from datasheet) ---- */
#define SI7015_ADDR        0x40
#define SI7015_CMD_TEMP    0xE3   /* Measure Temperature, No Hold Master  */
#define SI7015_CMD_HUM     0xE5   /* Measure Relative Humidity, No Hold   */
#define SI7015_CMD_RESET   0xFE   /* Soft reset command                   */
#define SI7015_RESET_DELAY_US 15000  /* 15 ms after reset                    */
#define SI7015_MEAS_DELAY_US  20000  /* 20 ms max for 12-bit temp/hum        */
#define SI7015_POLL_DELAY_US  1000   /* 1 ms between poll retries            */
#define SI7015_MAX_POLLS     20      /* 20 × 1 ms = 20 ms total poll window  */

#define LOG_FILE_NAME       "sensor_data.txt"
#define SAMPLE_INTERVAL_S   5

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single command byte to the Si7015.                          */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int si7015_write_cmd(int handle, uint8_t cmd)
{
    int rc = i2cWriteByte(handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x%02X) failed: %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 2-byte measurement result from the Si7015.                   */
/* Returns 0 on success and stores raw bytes in *msb / *lsb.           */
/* Returns -1 on error.                                                */
/* ------------------------------------------------------------------ */
static int si7015_read_measurement(int handle, uint8_t *msb, uint8_t *lsb)
{
    char buf[2];
    int rc = i2cReadDevice(handle, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (rc=%d): %s\n",
                rc, strerror(errno));
        return -1;
    }
    *msb = (uint8_t)buf[0];
    *lsb = (uint8_t)buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a measurement and wait for completion.                      */
/* Returns 0 on success and stores raw bytes in *msb / *lsb.           */
/* Returns -1 on error or timeout.                                     */
/* ------------------------------------------------------------------ */
static int si7015_measure(int handle, uint8_t cmd, uint8_t *msb, uint8_t *lsb)
{
    if (si7015_write_cmd(handle, cmd) != 0)
        return -1;

    /* Poll until the sensor is ready (no hold master mode) */
    for (int i = 0; i < SI7015_MAX_POLLS; i++) {
        if (si7015_read_measurement(handle, msb, lsb) == 0)
            return 0;
        gpioDelay(SI7015_POLL_DELAY_US);
    }

    fprintf(stderr, "[ERROR] Measurement 0x%02X timed out after %d polls\n",
            cmd, SI7015_MAX_POLLS);
    return -1;
}

/* ------------------------------------------------------------------ */
/* Convert raw bytes to physical units.                                */
/* ------------------------------------------------------------------ */
static float raw_to_temperature(uint8_t msb, uint8_t lsb)
{
    uint16_t raw = ((uint16_t)msb << 8) | lsb;
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

static float raw_to_humidity(uint8_t msb, uint8_t lsb)
{
    uint16_t raw = ((uint16_t)msb << 8) | lsb;
    return (125.0f * (float)raw / 65536.0f) - 6.0f;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped reading to the log file.                       */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int log_data(float temperature, float humidity)
{
    FILE *fp = fopen(LOG_FILE_NAME, "a");
    if (!fp) {
        fprintf(stderr, "[ERROR] Cannot open %s: %s\n",
                LOG_FILE_NAME, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, Temperature: %.2f C, Humidity: %.2f %%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, humidity);

    if (fclose(fp) != 0) {
        fprintf(stderr, "[WARN] fclose(%s) failed: %s\n",
                LOG_FILE_NAME, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                       */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Open I2C bus 1 at the Si7015 address ---- */
    g_i2c_handle = i2cOpen(1, SI7015_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %s\n",
                SI7015_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Soft reset the sensor ---- */
    if (si7015_write_cmd(g_i2c_handle, SI7015_CMD_RESET) != 0) {
        fprintf(stderr, "[FATAL] Sensor not responding at 0x%02X — check wiring\n",
                SI7015_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioDelay(SI7015_RESET_DELAY_US);

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("Si7015 sensor reader started. Logging to %s every %d s.\n",
           LOG_FILE_NAME, SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    /* ---- Main sampling loop ---- */
    while (g_running) {
        uint8_t t_msb = 0, t_lsb = 0, h_msb = 0, h_lsb = 0;
        int ok = 1;

        /* Temperature */
        if (si7015_measure(g_i2c_handle, SI7015_CMD_TEMP, &t_msb, &t_lsb) != 0) {
            fprintf(stderr, "[ERROR] Temperature measurement failed\n");
            ok = 0;
        }

        /* Humidity (only if temperature succeeded) */
        if (ok && si7015_measure(g_i2c_handle, SI7015_CMD_HUM, &h_msb, &h_lsb) != 0) {
            fprintf(stderr, "[ERROR] Humidity measurement failed\n");
            ok = 0;
        }

        if (ok) {
            float temperature = raw_to_temperature(t_msb, t_lsb);
            float humidity    = raw_to_humidity(h_msb, h_lsb);

            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);

            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "[WARN] Failed to log data\n");
            }
        }

        /* Sleep SAMPLE_INTERVAL_S, but wake early on signal */
        for (int s = 0; s < SAMPLE_INTERVAL_S && g_running; s++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

