#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SI7021_ADDR    0x40
#define FAN_GPIO       18
#define TEMP_THRESHOLD 28.0f
#define TEMP_HYSTERESIS 27.0f
#define BUFFER_SIZE    60
#define READ_INTERVAL  2
#define FAN_PULSE_US   10000
#define MAX_RETRIES    3

#define SI7021_CMD_MEASURE_TEMP_HOLD  0xE3
#define SI7021_CMD_RESET             0xFE

typedef struct {
    time_t timestamp;
    float  temperature;
} Reading;

static Reading  buffer[BUFFER_SIZE];
static int      buf_head = 0;
static int      buf_count = 0;
static int      i2c_handle = -1;
static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_cmd(int handle, uint8_t cmd) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cWriteByte(handle, cmd);
        if (rc == 0) return 0;
        fprintf(stderr, "I2C write 0x%02X failed (attempt %d/%d): %d\n",
                cmd, attempt + 1, MAX_RETRIES, rc);
        gpioDelay(10000);
    }
    return -1;
}

static int i2c_read_bytes(int handle, uint8_t *buf, int len) {
    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        int rc = i2cReadDevice(handle, (char *)buf, len);
        if (rc == len) return 0;
        fprintf(stderr, "I2C read failed (attempt %d/%d): got %d, expected %d\n",
                attempt + 1, MAX_RETRIES, rc, len);
        gpioDelay(10000);
    }
    return -1;
}

static int read_temperature(float *temp_out) {
    if (i2c_write_cmd(i2c_handle, SI7021_CMD_MEASURE_TEMP_HOLD) != 0) {
        fprintf(stderr, "Failed to trigger temperature measurement\n");
        return -1;
    }

    gpioDelay(10000);

    uint8_t data[2];
    if (i2c_read_bytes(i2c_handle, data, 2) != 0) {
        fprintf(stderr, "Failed to read temperature data\n");
        return -1;
    }

    uint16_t raw = ((uint16_t)data[0] << 8) | data[1];
    *temp_out = (175.72f * raw / 65536.0f) - 46.85f;
    return 0;
}

static void add_reading(float temperature) {
    time(&buffer[buf_head].timestamp);
    buffer[buf_head].temperature = temperature;
    buf_head = (buf_head + 1) % BUFFER_SIZE;
    if (buf_count < BUFFER_SIZE) buf_count++;
}

static void print_buffer(void) {
    printf("\n--- Temperature Buffer (%d entries) ---\n", buf_count);
    int start = (buf_count == BUFFER_SIZE) ? buf_head : 0;
    for (int i = 0; i < buf_count; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S",
                 localtime(&buffer[idx].timestamp));
        printf("[%s] Temperature: %.2f C\n", ts, buffer[idx].temperature);
    }
    printf("----------------------------------------\n");
}

static void control_fan(float temperature) {
    static int fan_on = 0;

    if (temperature > TEMP_THRESHOLD && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = 1;
            printf("Fan ON  (Temperature: %.2f C)\n", temperature);
        } else {
            fprintf(stderr, "Failed to turn fan ON\n");
        }
    } else if (temperature < TEMP_HYSTERESIS && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = 0;
            printf("Fan OFF (Temperature: %.2f C)\n", temperature);
        } else {
            fprintf(stderr, "Failed to turn fan OFF\n");
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X: %d\n",
                I2C_BUS, SI7021_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2c_write_cmd(i2c_handle, SI7021_CMD_RESET) != 0) {
        fprintf(stderr, "Warning: Si7021 reset failed; continuing anyway\n");
    }
    gpioDelay(15000);

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", FAN_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Si7021 temperature monitor started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            add_reading(temperature);
            char ts[32];
            strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", localtime(&buffer[buf_head].timestamp));
            printf("[%s] Temperature: %.2f C\n", ts, temperature);
            control_fan(temperature);
            gpioDelay(FAN_PULSE_US);
        } else {
            fprintf(stderr, "Sensor read failed; continuing\n");
        }
        sleep(READ_INTERVAL);
    }

    printf("\nShutting down...\n");
    gpioWrite(FAN_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    print_buffer();
    return EXIT_SUCCESS;
}

