/*
 * SCD40 CO2 / Temperature / Humidity logger for Raspberry Pi Zero W
 *
 * Wiring:
 *   SCD40 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SCD40 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SCD40 VDD  -> 3.3 V
 *   SCD40 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o air_quality air_quality.c -lpigpio -lrt
 * Run:
 *   sudo ./air_quality
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- SCD40 constants (from datasheet) ---- */
#define SCD40_I2C_BUS        1
#define SCD40_I2C_ADDR       0x62
#define SCD40_CLOCK_SPEED    100000          /* 100 kHz, clock-stretching-compatible */

#define CMD_START_PERIODIC   0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC    0x3F86
#define CMD_GET_DATA_READY   0xE4B8

#define MEASUREMENT_INTERVAL_S 5
#define FIRST_READ_DELAY_S     1
#define LOG_FILE_NAME          "air_quality.log"

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ---- Low-level I2C helpers ---- */
static int scd40_write_command(int handle, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%04X) failed\n", cmd);
        return -1;
    }
    return 0;
}

static int scd40_read_bytes(int handle, uint8_t *buf, size_t len)
{
    int n = i2cReadDevice(handle, (char *)buf, (int)len);
    if (n != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadDevice expected %zu bytes, got %d\n", len, n);
        return -1;
    }
    return 0;
}

/* ---- Sensor driver ---- */
static int scd40_init(int handle)
{
    if (scd40_write_command(handle, CMD_START_PERIODIC) != 0)
        return -1;
    return 0;
}

static int scd40_stop(int handle)
{
    if (scd40_write_command(handle, CMD_STOP_PERIODIC) != 0)
        return -1;
    return 0;
}

static int scd40_data_ready(int handle, bool *ready)
{
    if (scd40_write_command(handle, CMD_GET_DATA_READY) != 0)
        return -1;

    gpioDelay(2000);                       /* 2 ms processing time */

    uint8_t buf[3];
    if (scd40_read_bytes(handle, buf, sizeof(buf)) != 0)
        return -1;

    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[ERROR] CRC mismatch on data-ready word\n");
        return -1;
    }

    uint16_t word = ((uint16_t)buf[0] << 8) | buf[1];
    *ready = (word != 0);
    return 0;
}

static int scd40_read_measurement(int handle, uint16_t *co2,
                                  float *temp, float *rh)
{
    if (scd40_write_command(handle, CMD_READ_MEASUREMENT) != 0)
        return -1;

    gpioDelay(2000);                       /* 2 ms processing time */

    uint8_t buf[9];
    if (scd40_read_bytes(handle, buf, sizeof(buf)) != 0)
        return -1;

    /* Verify CRC for each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (sensirion_crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on measurement word %d\n", i);
            return -1;
        }
    }

    uint16_t co2_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t t_raw   = ((uint16_t)buf[3] << 8) | buf[4];
    uint16_t rh_raw  = ((uint16_t)buf[6] << 8) | buf[7];

    *co2 = co2_raw;
    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh  = 100.0f * (float)rh_raw / 65535.0f;
    return 0;
}

/* ---- Logging ---- */
static int log_data(FILE *fp, uint16_t co2, float temp, float rh)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%u,%.2f,%.2f\n", ts, co2, temp, rh) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log failed\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush failed\n");
        return -1;
    }
    return 0;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        scd40_stop(g_i2c_handle);
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(SCD40_I2C_BUS, SCD40_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                SCD40_I2C_BUS, SCD40_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (scd40_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] SCD40 init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open %s for append\n", LOG_FILE_NAME);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed\n");
    }

    printf("SCD40 air-quality logger started. Logging to %s every %d s.\n",
           LOG_FILE_NAME, MEASUREMENT_INTERVAL_S);
    printf("Press Ctrl+C to stop.\n");

    /* Wait for first measurement (datasheet: 1 s after start) */
    sleep(FIRST_READ_DELAY_S);

    while (g_running) {
        bool ready = false;
        if (scd40_data_ready(g_i2c_handle, &ready) != 0) {
            fprintf(stderr, "[WARN] data-ready check failed, retrying next cycle\n");
            sleep(MEASUREMENT_INTERVAL_S);
            continue;
        }

        if (!ready) {
            /* Data not ready yet — skip this cycle */
            sleep(MEASUREMENT_INTERVAL_S);
            continue;
        }

        uint16_t co2;
        float temp, rh;
        if (scd40_read_measurement(g_i2c_handle, &co2, &temp, &rh) != 0) {
            fprintf(stderr, "[WARN] measurement read failed, retrying next cycle\n");
            sleep(MEASUREMENT_INTERVAL_S);
            continue;
        }

        if (log_data(g_log_file, co2, temp, rh) != 0) {
            fprintf(stderr, "[WARN] logging failed\n");
        }

        printf("CO2: %u ppm | T: %.2f °C | RH: %.2f %%\n", co2, temp, rh);

        /* Sleep for the remainder of the interval */
        sleep(MEASUREMENT_INTERVAL_S);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

