/*
 * SCD40 CO2/Temperature/Humidity logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SCD40 SDA  -> GPIO2  (I2C bus 1 SDA)
 *   SCD40 SCL  -> GPIO3  (I2C bus 1 SCL)
 *   SCD40 VDD  -> 3.3 V
 *   SCD40 GND  -> GND
 *   LED anode  -> GPIO17 (with ~330 ohm series resistor)
 *   LED cathode -> GND
 *
 * Build:  gcc -O2 -Wall -o scd40_logger scd40_logger.c -lpigpio -lrt
 * Run:    sudo ./scd40_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS              1
#define SCD40_I2C_ADDR       0x62
#define GPIO_LED             17
#define CO2_THRESHOLD_PPM    1000
#define BUFFER_SIZE          20
#define SAMPLE_PERIOD_S      5

/* SCD40 commands (16-bit, big-endian on the wire) */
#define CMD_START_PERIODIC   0x21B1
#define CMD_READ_MEASUREMENT 0xEC05
#define CMD_STOP_PERIODIC    0x3F86
#define CMD_GET_DATA_READY   0xE4B8

/* Globals for cleanup */
static int      g_i2c_handle = -1;
static volatile sig_atomic_t g_terminate = 0;

/* ------------------------------------------------------------------ */
/* CRC-8 (polynomial 0x31, init 0xFF) — Sensirion convention           */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                              */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (i2cWriteDevice(g_i2c_handle, (char *)buf, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(0x%04X) failed\n", cmd);
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(uint8_t *buf, size_t len)
{
    int n = i2cReadDevice(g_i2c_handle, (char *)buf, (int)len);
    if (n != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadDevice expected %zu bytes, got %d\n",
                len, n);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* SCD40 sensor operations                                            */
/* ------------------------------------------------------------------ */
static int scd40_start_periodic(void)
{
    return i2c_write_cmd(CMD_START_PERIODIC);
}

static int scd40_stop_periodic(void)
{
    return i2c_write_cmd(CMD_STOP_PERIODIC);
}

static int scd40_data_ready(bool *ready)
{
    if (i2c_write_cmd(CMD_GET_DATA_READY) != 0)
        return -1;

    gpioDelay(2000); /* 2 ms processing time */

    uint8_t buf[3];
    if (i2c_read_bytes(buf, sizeof(buf)) != 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[WARN] data-ready CRC mismatch\n");
        return -1;
    }

    uint16_t word = ((uint16_t)buf[0] << 8) | buf[1];
    *ready = (word != 0);
    return 0;
}

static int scd40_read_measurement(uint16_t *co2, float *temp, float *rh)
{
    if (i2c_write_cmd(CMD_READ_MEASUREMENT) != 0)
        return -1;

    gpioDelay(2000); /* 2 ms processing time */

    uint8_t buf[9];
    if (i2c_read_bytes(buf, sizeof(buf)) != 0)
        return -1;

    /* Validate CRC on each 2-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[WARN] measurement CRC mismatch (word %d)\n", i);
            return -1;
        }
    }

    uint16_t co2_raw = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t t_raw   = ((uint16_t)buf[3] << 8) | buf[4];
    uint16_t rh_raw  = ((uint16_t)buf[6] << 8) | buf[7];

    *co2  = co2_raw;
    *temp = -45.0f + 175.0f * (float)t_raw / 65535.0f;
    *rh   = 100.0f * (float)rh_raw / 65535.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Circular buffer                                                    */
/* ------------------------------------------------------------------ */
typedef struct {
    uint16_t co2[BUFFER_SIZE];
    float    temp[BUFFER_SIZE];
    float    rh[BUFFER_SIZE];
    int      head;
    int      count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    memset(cb, 0, sizeof(*cb));
}

static void cb_push(CircularBuffer *cb, uint16_t co2, float temp, float rh)
{
    cb->co2[cb->head]  = co2;
    cb->temp[cb->head] = temp;
    cb->rh[cb->head]   = rh;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                    */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                            */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        scd40_stop_periodic();
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(GPIO_LED, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    CircularBuffer cb;
    cb_init(&cb);

    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, SCD40_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SCD40_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init ------------------------------------------------ */
    if (scd40_start_periodic() != 0) {
        fprintf(stderr, "[FATAL] SCD40 start periodic failed — "
                        "sensor may be absent or bus error\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- GPIO LED --------------------------------------------------- */
    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", GPIO_LED);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_LED, 0);

    /* --- Signals ---------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SCD40 logger started.  Periodic mode.  Ctrl-C to stop.\n");

    /* --- Main loop -------------------------------------------------- */
    while (!g_terminate) {
        bool ready = false;
        if (scd40_data_ready(&ready) != 0) {
            fprintf(stderr, "[WARN] data-ready query failed — "
                            "continuing\n");
            sleep(1);
            continue;
        }

        if (!ready) {
            sleep(1);
            continue;
        }

        uint16_t co2;
        float temp, rh;
        if (scd40_read_measurement(&co2, &temp, &rh) != 0) {
            fprintf(stderr, "[WARN] read measurement failed — "
                            "continuing\n");
            sleep(1);
            continue;
        }

        cb_push(&cb, co2, temp, rh);

        printf("CO2: %5u ppm  |  T: %5.2f C  |  RH: %5.2f %%\n",
               co2, temp, rh);

        gpioWrite(GPIO_LED, co2 > CO2_THRESHOLD_PPM ? 1 : 0);

        sleep(SAMPLE_PERIOD_S);
    }

    /* --- Graceful shutdown ----------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

