#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TMP05_GPIO 4
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 5000000  /* 5 seconds */
#define EDGE_TIMEOUT_US 500000       /* 500 ms */
#define MIN_TEMP -40.0
#define MAX_TEMP 150.0
#define MAX_CONSECUTIVE_ERRORS 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Busy-wait for a level change on the given GPIO pin.
 * Returns 0 on success, -1 on timeout or error.
 */
static int wait_for_level(int gpio, int target_level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    int level;

    while (1) {
        level = gpioRead(gpio);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed on GPIO %d: %s\n",
                    gpio, pigpio_error(level));
            return -1;
        }
        if (level == target_level)
            return 0;

        if ((gpioTick() - start) >= timeout_us)
            return -1;
    }
}

/*
 * Measure the high-pulse width (TH) and total cycle width (TL)
 * of the TMP05 PWM output.
 * Returns 0 on success, -1 on error.
 */
static int measure_pulse_widths(int gpio, uint32_t *th_us, uint32_t *tl_us) {
    uint32_t t0, t1, t2;

    /* Wait for the output to go HIGH (start of a valid cycle) */
    if (wait_for_level(gpio, 1, EDGE_TIMEOUT_US) != 0) {
        fprintf(stderr, "Timeout waiting for TMP05 output HIGH\n");
        return -1;
    }
    t0 = gpioTick();

    /* Wait for the output to go LOW (end of high pulse) */
    if (wait_for_level(gpio, 0, EDGE_TIMEOUT_US) != 0) {
        fprintf(stderr, "Timeout waiting for TMP05 output LOW\n");
        return -1;
    }
    t1 = gpioTick();

    *th_us = t1 - t0;

    /* Wait for the output to go HIGH again (end of full cycle) */
    if (wait_for_level(gpio, 1, EDGE_TIMEOUT_US) != 0) {
        fprintf(stderr, "Timeout waiting for TMP05 output HIGH (cycle end)\n");
        return -1;
    }
    t2 = gpioTick();

    *tl_us = t2 - t1;

    return 0;
}

/*
 * Convert TH (high-pulse width in microseconds) and TL (total cycle
 * width in microseconds) to temperature in degrees Celsius.
 * Formula from the TMP05 datasheet:
 *   T(°C) = 25 + (TH - 1000) * 100 / TL
 * Returns 0 on success, -1 if TL is zero (division by zero).
 */
static int calculate_temperature(uint32_t th_us, uint32_t tl_us, float *temp) {
    if (tl_us == 0) {
        fprintf(stderr, "Error: TL is zero, cannot calculate temperature\n");
        return -1;
    }

    *temp = 25.0f + ((float)(th_us - 1000) * 100.0f) / (float)tl_us;
    return 0;
}

static void log_temperature(float temperature) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s Temperature: %.2f C\n", timestamp, temperature);
    fflush(log_file);
}

static void log_error(const char *message) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    fprintf(log_file, "%s ERROR: %s\n", timestamp, message);
    fflush(log_file);
}

int main(void) {
    int consecutive_errors = 0;
    int rc;

    /* Initialize pigpio */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed: %s\n", pigpio_error(rc));
        return EXIT_FAILURE;
    }

    /* Configure GPIO4 as input */
    gpioSetMode(TMP05_GPIO, PI_INPUT);

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGTERM handler: %s\n",
                strerror(errno));
    }

    printf("TMP05 temperature logger started. Press Ctrl+C to exit.\n");

    while (running) {
        uint32_t th_us = 0, tl_us = 0;
        float temperature;

        if (measure_pulse_widths(TMP05_GPIO, &th_us, &tl_us) != 0) {
            consecutive_errors++;
            fprintf(stderr, "Pulse width measurement failed (attempt %d/%d)\n",
                    consecutive_errors, MAX_CONSECUTIVE_ERRORS);

            if (consecutive_errors >= MAX_CONSECUTIVE_ERRORS) {
                fprintf(stderr, "SENSOR MALFUNCTION: %d consecutive failures\n",
                        consecutive_errors);
                log_error("SENSOR MALFUNCTION");
                consecutive_errors = 0;
            }
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        consecutive_errors = 0;

        if (calculate_temperature(th_us, tl_us, &temperature) != 0) {
            fprintf(stderr, "Temperature calculation failed\n");
            log_error("Temperature calculation failed");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        if (temperature < MIN_TEMP || temperature > MAX_TEMP) {
            fprintf(stderr, "Temperature out of range: %.2f C\n", temperature);
            log_error("Temperature out of range");
        } else {
            log_temperature(temperature);
            printf("Temperature: %.2f C\n", temperature);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

