#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define SHT35_ADDR 0x44
#define MEASURE_CMD_MSB 0x2C
#define MEASURE_CMD_LSB 0x06
#define LOG_FILE "environmental_data.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_US 1000000
#define MEASUREMENT_DELAY_US 15000
#define SAMPLE_INTERVAL_US 5000000
#define ONE_HOUR_SEC 3600.0

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

typedef struct {
    float temperature;
    float humidity;
} SensorData;

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at bus %d, addr 0x%02X: %d\n", I2C_BUS, SHT35_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_sensor_data(SensorData *data) {
    uint8_t cmd[2] = {MEASURE_CMD_MSB, MEASURE_CMD_LSB};
    uint8_t buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, (char *)cmd, 2) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(i2c_handle, (char *)buf, 6) != 6) {
            fprintf(stderr, "I2C read failed (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "Temperature CRC mismatch (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        if (crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "Humidity CRC mismatch (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(RETRY_DELAY_US);
            continue;
        }

        uint16_t raw_temp = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t raw_hum = ((uint16_t)buf[3] << 8) | buf[4];

        data->temperature = -45.0f + (175.0f * (float)raw_temp / 65535.0f);
        data->humidity = 100.0f * (float)raw_hum / 65535.0f;

        return 0;
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
    return -1;
}

static void simulate_greenhouse(float *temperature, float *humidity, time_t start_time) {
    double elapsed = difftime(time(NULL), start_time);
    double phase = fmod(elapsed, ONE_HOUR_SEC) / ONE_HOUR_SEC;

    *temperature += 2.0f * sin(2.0 * M_PI * phase);
    *humidity += 5.0f * sin(2.0 * M_PI * phase);

    if (*temperature < -40.0f) *temperature = -40.0f;
    if (*temperature > 80.0f) *temperature = 80.0f;
    if (*humidity < 0.0f) *humidity = 0.0f;
    if (*humidity > 100.0f) *humidity = 100.0f;
}

