    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_i2c() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    time_t start_time = time(NULL);
    SensorData sensor_data;

    while (!terminate) {
        if (read_sensor_data(&sensor_data) == 0) {
            simulate_greenhouse(&sensor_data.temperature, &sensor_data.humidity, start_time);
            if (log_data(sensor_data.temperature, sensor_data.humidity) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            if (log_data(NAN, NAN) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

