/*
 * Raspberry Pi 3 Model B+ — Sensirion SDP810-125Pa differential pressure sensor
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP810 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * I2C address: 0x25 (7-bit)
 * Continuous measurement command: 0x362F
 * Conversion time: ~45 ms
 * Data block (9 bytes): pressure(2)+crc, temp(2)+crc, scale(2)+crc
 * CRC-8: polynomial 0x31, init 0xFF
 *
 * Build: gcc -O2 -Wall -o airflow airflow.c
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP810_ADDR    0x25
#define CMD_CONT_MEAS  0x362F
#define CONV_TIME_MS   45
#define CSV_FILE       "airflow.csv"
#define SAMPLE_PERIOD  1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Write a 16-bit command to the sensor ---- */
static int sdp_write_cmd(int fd, uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write failed (cmd 0x%04X): %s\n",
                cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- Read exactly n bytes from the sensor ---- */
static int sdp_read_bytes(int fd, uint8_t *buf, size_t n)
{
    size_t total = 0;
    while (total < n) {
        ssize_t r = read(fd, buf + total, n - total);
        if (r < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
            return -1;
        }
        if (r == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor absent?)\n");
            return -1;
        }
        total += (size_t)r;
    }
    return 0;
}

/* ---- Read one measurement block and convert to Pa / °C ---- */
static int sdp_read_measurement(int fd, float *pressure, float *temperature)
{
    uint8_t raw[9];

    if (sdp_read_bytes(fd, raw, sizeof(raw)) != 0)
        return -1;

    /* Validate CRCs for each 2-byte data word */
    if (crc8(&raw[0], 2) != raw[2]) {
        fprintf(stderr, "Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&raw[3], 2) != raw[5]) {
        fprintf(stderr, "Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&raw[6], 2) != raw[8]) {
        fprintf(stderr, "Scale-factor CRC mismatch\n");
        return -1;
    }

    int16_t dp_raw = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t t_raw  = (int16_t)((raw[3] << 8) | raw[4]);

    /* SDP8xx conversion formulas (datasheet) */
    *pressure    = (float)dp_raw / 240.0f;          /* Pa */
    *temperature = (float)t_raw / 200.0f;           /* °C */

    return 0;
}

/* ---- Append a CSV row ---- */
static int log_data(const char *filename, float pressure, float temperature)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    } else {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SDP810_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Start continuous measurement */
    if (sdp_write_cmd(g_i2c_fd, CMD_CONT_MEAS) != 0) {
        fprintf(stderr, "Failed to start continuous measurement\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Allow first conversion to complete */
    usleep(CONV_TIME_MS * 1000);

    printf("SDP810 logging to %s (Ctrl+C to stop)\n", CSV_FILE);

    while (g_running) {
        float pressure, temperature;

        if (sdp_read_measurement(g_i2c_fd, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
            if (log_data(CSV_FILE, pressure, temperature) != 0)
                fprintf(stderr, "Logging failed\n");
        } else {
            fprintf(stderr, "Sensor read error — continuing\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return EXIT_SUCCESS;
}

