    *temperature = (float)t_raw / 200.0f;           /* °C */

    return 0;
}

/* ---- Append a CSV row ---- */
static int log_data(const char *filename, float pressure, float temperature)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
        fprintf(fp, "%s,%.2f,%.2f\n", ts, pressure, temperature);
    } else {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP810_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SDP810_ADDR, strerror(errno));
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Start continuous measurement */
    if (sdp_write_cmd(g_i2c_fd, CMD_CONT_MEAS) != 0) {
        fprintf(stderr, "Failed to start continuous measurement\n");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    /* Allow first conversion to complete */
    usleep(CONV_TIME_MS * 1000);

    printf("SDP810 logging to %s (Ctrl+C to stop)\n", CSV_FILE);

    while (g_running) {
        float pressure, temperature;

        if (sdp_read_measurement(g_i2c_fd, &pressure, &temperature) == 0) {
            printf("Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   pressure, temperature);
            if (log_data(CSV_FILE, pressure, temperature) != 0)
                fprintf(stderr, "Logging failed\n");
        } else {
            fprintf(stderr, "Sensor read error — continuing\n");
        }

        sleep(SAMPLE_PERIOD);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    if (g_i2c_fd >= 0)
        close(g_i2c_fd);
    return EXIT_SUCCESS;
}

