    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device at bus %d addr 0x%02X\n", I2C_BUS, SHT35_ADDR);
        gpioTerminate();
        return 1;
    }

    float temperature, humidity;
    while (g_running) {
        if (read_sht35(g_i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(CSV_FILE, temperature, humidity) != 0) {
