/*
 * Si7021 greenhouse monitor — Raspberry Pi Zero W
 * I2C bus 1 (GPIO2 = SDA, GPIO3 = SCL), address 0x40
 * Logs temperature (°C) and humidity (%) to environment.log every 5 s.
 *
 * Build:  gcc -O2 -Wall -Wextra -o si7021_mon si7021_mon.c
 * Run:    ./si7021_mon
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SI7021_ADDR    0x40

/* Si7021 commands (8-bit, no register prefix) */
#define CMD_MEASURE_TEMP_HOLD   0xE3
#define CMD_MEASURE_HUMID_HOLD  0xE5
#define CMD_RESET               0xFE

/* CRC-8 parameters per Si7021 datasheet */
#define CRC8_POLY  0x31
#define CRC8_INIT  0x00

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Si7021 polynomial 0x31, init 0x00)                           */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X): %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

/*
 * Send a single command byte, then read `len` bytes back.
 * Returns 0 on success, -1 on error.
 */
static int i2c_read_bytes(int fd, uint8_t cmd, uint8_t *buf, size_t len)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write cmd 0x%02X: %s\n", cmd, strerror(errno));
        return -1;
    }
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read cmd 0x%02X: %s\n", cmd, strerror(errno));
        return -1;
    }
    if ((size_t)n != len) {
        fprintf(stderr, "I2C read cmd 0x%02X: short read (%zd/%zu)\n",
                cmd, n, len);
        return -1;
    }
    return 0;
}

/*
 * Send a reset command and wait for the sensor to re-enter IDLE mode.
 * Returns 0 on success, -1 on error.
 */
static int si7021_reset(int fd)
{
    uint8_t cmd = CMD_RESET;
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "Si7021 reset write failed: %s\n", strerror(errno));
        return -1;
    }
    /* Reset takes ~15 ms; give a safe margin */
    usleep(20000);

    /* After reset the sensor NACKs on any read — that's fine, we just
     * need to re-open the bus to talk to the freshly-powered chip. */
    return 0;
}

/*
 * Read a 16-bit measurement with CRC.
 * Returns 0 on success, -1 on I2C or CRC error.
 */
static int si7021_read_measurement(int fd, uint8_t cmd, uint16_t *raw)
{
    uint8_t buf[3];
    if (i2c_read_bytes(fd, cmd, buf, sizeof(buf)) != 0)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on cmd 0x%02X (calc=0x%02X got=0x%02X)\n",
                cmd, crc8(buf, 2), buf[2]);
        return -1;
    }

    *raw = (uint16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Conversions                                                         */
/* ------------------------------------------------------------------ */
static float raw_to_temperature(uint16_t raw)
{
    return (175.72f * (float)raw / 65536.0f) - 46.85f;
}

static float raw_to_humidity(uint16_t raw)
{
    float rh = (125.0f * (float)raw / 65536.0f) - 6.0f;
    if (rh < 0.0f)   rh = 0.0f;
    if (rh > 100.0f) rh = 100.0f;
    return rh;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_open(const char *path)
{
    FILE *fp = fopen(path, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", path, strerror(errno));
        return -1;
    }
    /* Write header only if file is empty */
    long pos = ftell(fp);
    if (pos == 0)
        fprintf(fp, "timestamp,temperature_C,humidity_percent\n");
    fclose(fp);
    return 0;
}

static int log_data(const char *path, float temp, float rh)
{
    FILE *fp = fopen(path, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", path, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        fclose(fp);
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s,%.2f,%.2f\n", ts, temp, rh);
    fclose(fp);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    if (log_open("environment.log") != 0)
        return EXIT_FAILURE;

    g_i2c_fd = i2c_open(I2C_BUS, SI7021_ADDR);
    if (g_i2c_fd < 0)
        return EXIT_FAILURE;

    printf("Si7021 greenhouse monitor started. Logging to environment.log\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        uint16_t raw_t = 0, raw_rh = 0;
        int ok = 1;

        /* --- Temperature (hold master mode) --- */
        if (si7021_read_measurement(g_i2c_fd, CMD_MEASURE_TEMP_HOLD, &raw_t) != 0) {
            fprintf(stderr, "Temperature read failed — resetting sensor.\n");
            if (si7021_reset(g_i2c_fd) != 0) {
                fprintf(stderr, "Reset failed; aborting.\n");
                ok = 0;
                break;
            }
            g_i2c_fd = i2c_open(I2C_BUS, SI7021_ADDR);
            if (g_i2c_fd < 0) {
                fprintf(stderr, "Re-open I2C failed; aborting.\n");
                ok = 0;
                break;
            }
            continue;
        }

        /* --- Humidity (hold master mode) --- */
        if (si7021_read_measurement(g_i2c_fd, CMD_MEASURE_HUMID_HOLD, &raw_rh) != 0) {
            fprintf(stderr, "Humidity read failed — resetting sensor.\n");
            if (si7021_reset(g_i2c_fd) != 0) {
                fprintf(stderr, "Reset failed; aborting.\n");
                ok = 0;
                break;
            }
            g_i2c_fd = i2c_open(I2C_BUS, SI7021_ADDR);
            if (g_i2c_fd < 0) {
                fprintf(stderr, "Re-open I2C failed; aborting.\n");
                ok = 0;
                break;
            }
            continue;
        }

        float temp = raw_to_temperature(raw_t);
        float rh   = raw_to_humidity(raw_rh);

        if (log_data("environment.log", temp, rh) != 0)
            fprintf(stderr, "Warning: log write failed.\n");

        printf("Temperature: %.2f °C  Humidity: %.2f %%\n", temp, rh);

        /* Sleep 5 s, but wake early on signal */
        for (int i = 0; i < 50 && g_running; i++)
            usleep(100000);
    }

    /* Clean shutdown */
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

