#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

/* SDP810-500Pa I2C address (7-bit) */
#define SDP810_ADDR 0x25

/* Continuous measurement command (no averaging, no clock stretching) */
#define SDP810_CMD_CONTINUOUS 0x361F

/* Conversion time for continuous mode (max 45 ms) */
#define SDP810_CONV_TIME_US 50000

/* CRC-8 polynomial for Sensirion sensors (0x31, init 0xFF) */
#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

/* Global variables for graceful shutdown */
static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* CRC-8 calculation for Sensirion sensors */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

/* Initialize pigpio and open I2C bus */
static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X (handle=%d)\n",
                SDP810_ADDR, i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* Send continuous measurement command to sensor */
static int send_command(void) {
    uint8_t cmd[2] = {
        (uint8_t)((SDP810_CMD_CONTINUOUS >> 8) & 0xFF),
        (uint8_t)(SDP810_CMD_CONTINUOUS & 0xFF)
    };

    int result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to write command to I2C device (result=%d)\n", result);
        return -1;
    }

    return 0;
}

/* Read 9 bytes of measurement data from sensor */
static int read_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (result != 9) {
        fprintf(stderr, "Error: Failed to read 9 bytes from I2C device (result=%d)\n", result);
        return -1;
    }

    return 0;
}

/* Convert raw data to pressure (Pa) and temperature (°C) */
static void convert_data(const uint8_t *data, float *pressure, float *temperature) {
    int16_t raw_pressure = (int16_t)((data[0] << 8) | data[1]);
    int16_t raw_temperature = (int16_t)((data[3] << 8) | data[4]);

    /* Scale factor for SDP810-500Pa is 240.0 */
    *pressure = (float)raw_pressure / 240.0f;
    *temperature = (float)raw_temperature / 240.0f;
}

/* Log data to binary file */
static int log_data(float pressure, float temperature) {
    if (fwrite(&pressure, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Error: Failed to write pressure to file\n");
        return -1;
    }
    if (fwrite(&temperature, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Error: Failed to write temperature to file\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    /* Initialize I2C */
    if (init_i2c() != 0) {
        return 1;
    }

    /* Open binary file for logging */
    fp = fopen("airflow.dat", "wb");
    if (fp == NULL) {
        perror("Error: Failed to open airflow.dat for writing");
        cleanup();
        return 1;
    }

    /* Send continuous measurement command */
    if (send_command() != 0) {
        cleanup();
        return 1;
    }

    /* Wait for conversion to complete */
    gpioDelay(SDP810_CONV_TIME_US);

    /* Main loop */
    while (!terminate) {
        uint8_t data[9];

        /* Read data from sensor */
        if (read_data(data) != 0) {
            fprintf(stderr, "Error: Failed to read data, retrying...\n");
            gpioDelay(100000); /* 100 ms delay before retry */
            continue;
        }

        /* Validate CRC for pressure (bytes 0-1, CRC at byte 2) */
        uint8_t crc_pressure = crc8(data, 2);
        if (crc_pressure != data[2]) {
            fprintf(stderr, "Error: Pressure CRC mismatch (calculated=0x%02X, received=0x%02X)\n",
                    crc_pressure, data[2]);
            continue;
        }

        /* Validate CRC for temperature (bytes 3-4, CRC at byte 5) */
        uint8_t crc_temperature = crc8(data + 3, 2);
        if (crc_temperature != data[5]) {
            fprintf(stderr, "Error: Temperature CRC mismatch (calculated=0x%02X, received=0x%02X)\n",
                    crc_temperature, data[5]);
            continue;
        }

        /* Convert data to pressure and temperature */
        float pressure, temperature;
        convert_data(data, &pressure, &temperature);

        /* Log data to file */
        if (log_data(pressure, temperature) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        /* Wait for 1 second before next reading */
        gpioDelay(1000000);
    }

    /* Cleanup and exit */
    cleanup();
    return 0;
}

