/*
 * Raspberry Pi 3 Model B+ — Sensirion SDP800-500Pa differential pressure logger
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * I2C address: 0x25 (7-bit)
 * Continuous measurement command: 0x362F
 * Conversion time: 45 ms
 * Response: 9 bytes = 3 data words + 3 CRC bytes
 *   data[0..1] = differential pressure (raw, signed)
 *   data[2..3] = temperature (raw)
 *   data[4..5] = scale factor (raw)
 * CRC-8 polynomial: 0x31, init: 0xFF
 *
 * Build: gcc -O2 -Wall -o sdp800_logger sdp800_logger.c -lpigpio -lrt
 * Run:   sudo ./sdp800_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP800_ADDR    0x25
#define CMD_CONT_MEAS  0x362F
#define CONV_TIME_US   45000   /* 45 ms */
#define SAMPLE_PERIOD  5       /* seconds */
#define LOG_FILE       "pressure_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ---- CRC-8 (Sensirion: poly 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Read one 9-byte measurement frame ---- */
static int read_sdp800(int handle, float *pressure)
{
    uint8_t cmd[2] = {
        (uint8_t)(CMD_CONT_MEAS >> 8),
        (uint8_t)(CMD_CONT_MEAS & 0xFF)
    };
    uint8_t buf[9];

    if (i2cWriteDevice(handle, (char *)cmd, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C write failed\n");
        return -1;
    }

    gpioDelay(CONV_TIME_US);

    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "[ERROR] I2C read failed\n");
        return -1;
    }

    /* Validate CRC for each 2-byte data word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    int16_t raw_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure = (float)raw_pressure;
    return 0;
}

/* ---- Log with timestamp ---- */
static void log_pressure(float pressure)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_file, "%s, %.2f Pa\n", ts, pressure);
    fflush(g_log_file);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open %s\n", LOG_FILE);
