/*
 * Raspberry Pi 3 Model B+ — Honeywell Zephyr HAFBLF0100A2AX5 differential pressure sensor
 * + PWM fan control on GPIO18 (hardware PWM, 25 kHz)
 *
 * Build:  gcc -O2 -Wall -o flow_monitor flow_monitor.c -lpigpio -lrt
 * Run:    sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS            1          /* /dev/i2c-1 on RPi 3B+ */
#define I2C_ADDR           0x28       /* Honeywell HAF default 7-bit address */
#define FAN_GPIO           18         /* BCM 18 — hardware PWM0 */
#define PWM_FREQ_HZ        25000      /* 25 kHz — typical for 4-wire PC fans */
#define PWM_RANGE          1000       /* duty-cycle steps 0..1000 */
#define SAMPLE_PERIOD_US   100000     /* 100 ms */
#define LOG_FILE           "flow_log.txt"

/* ----------------------------- Globals ----------------------------------- */
static int           i2c_handle = -1;
static FILE         *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  init_i2c(void);
static int  read_pressure(int16_t *pressure_out);
static float calculate_flow_rate(int16_t pressure);
static void set_fan_speed(float flow_rate);
static void log_data(float flow_rate);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- I2C init ---------------------------------- */
static int init_i2c(void)
{
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

/*
 * Read 2 bytes from the sensor.
 * The HAF returns the differential pressure in counts; a positive value
 * indicates a positive differential pressure.
 * Returns 0 on success, -1 on I2C error.
 */
static int read_pressure(int16_t *pressure_out)
{
    char buf[2];
    int  n;

    n = i2cReadDevice(i2c_handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected 2)\n", n);
        return -1;
    }

    /*
     * Honeywell HAF: 16-bit two's-complement, MSB first.
     * buf[0] = MSB, buf[1] = LSB.
     */
    *pressure_out = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) |
                              (uint16_t)(uint8_t)buf[1]);
    return 0;
}

/*
 * Placeholder flow-rate calculation.
 * Replace with the sensor's specific transfer-function from
 * differential-pressure (Pa) to flow-rate (m^3/s) for your
 * HAFBLF0100A2AX5 variant.
 */
static float calculate_flow_rate(int16_t pressure)
{
    /*
     * Example: linear approximation — adjust the slope and offset
     * per the datasheet curve for your specific airflow range.
     */
    const float slope     = 0.001f;   /* Pa -> m^3/s */
    const float intercept = 0.0f;     /* Pa offset   */
    return (float)pressure * slope + intercept;
}

/* ----------------------------- Fan control ------------------------------- */
static void set_fan_speed(float flow_rate)
{
    int duty;

    /*
     * Map flow-rate to PWM duty cycle.
     *   flow_rate < 0.0  -> fan off (duty = 0)
     *   flow_rate > 1.0  -> full speed (duty = PWM_RANGE)
     */
    if (flow_rate < 0.0f) {
        duty = 0;
    } else if (flow_rate > 1.0f) {
        duty = PWM_RANGE;
    } else {
        duty = (int)(flow_rate * (float)PWM_RANGE);
    }

    if (gpioPWM(FAN_GPIO, duty) < 0) {
        fprintf(stderr, "[WARN] gpioPWM failed on GPIO %d\n", FAN_GPIO);
    }
}

/* ----------------------------- Logging ----------------------------------- */
static void log_data(float flow_rate)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s,%.4f\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "[WARN] fprintf to log file failed\n");
    }
    fflush(log_file);
}

/* ----------------------------- Signal handling --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    /* Ensure fan is off before terminating pigpio */
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    int16_t  pressure;
    float    flow_rate;

    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C init --- */
    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Fan GPIO setup (hardware PWM) --- */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "[FATAL] gpioSetMode failed for GPIO %d\n", FAN_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "[WARN] gpioSetPWMfrequency failed for GPIO %d\n", FAN_GPIO);
    }
    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "[WARN] gpioSetPWMrange failed for GPIO %d\n", FAN_GPIO);
    }
    gpioPWM(FAN_GPIO, 0);  /* start with fan off */

    /* --- Log file --- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed — graceful shutdown may be limited\n");
    }

    printf("Flow monitoring started.  I2C bus %d, addr 0x%02X, fan PWM GPIO %d.\n",
           I2C_BUS, I2C_ADDR, FAN_GPIO);
    printf("Logging to '%s'.  Press Ctrl+C to exit.\n", LOG_FILE);

    /* --- Main loop --- */
    while (!terminate) {
        if (read_pressure(&pressure) == 0) {
            flow_rate = calculate_flow_rate(pressure);
            set_fan_speed(flow_rate);
            log_data(flow_rate);
        } else {
            /*
             * I2C read failed — keep fan at a safe state and retry.
             * Do not log errors to the file so transient bus glitches
             * do not fill the log with noise.
             */
            set_fan_speed(0.0f);
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

