#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* LPS33HW I2C address (SDO/SA0 tied to GND) */
#define LPS33HW_ADDR 0x5C

/* LPS33HW register addresses */
#define CTRL_REG1 0x10
#define CTRL_REG2 0x11
#define CTRL_REG3 0x20
#define CTRL_REG4 0x21
#define STATUS_REG 0x27
#define PRESS_OUT_XL 0x28
#define TEMP_OUT_L 0x2B

/* CTRL_REG1: ODR=1Hz (0x01), BDU=1 (0x02) -> 0x03 */
#define CTRL_REG1_VAL 0x03
/* CTRL_REG2: IF_ADD_INC=1 (0x01) -> 0x01 */
#define CTRL_REG2_VAL 0x01
/* CTRL_REG3: SIM=0 (0x00) -> 0x00 */
#define CTRL_REG3_VAL 0x00
/* CTRL_REG4: BLE=0, LIR=0, DIFF_EN=0 -> 0x00 */
#define CTRL_REG4_VAL 0x00

#define LOG_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL_US 1000000 /* 1 second */

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* Write one byte to a register; returns 0 on success, -1 on error. */
static int write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X: %s\n",
                value, reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read one byte from a register; returns byte value (0-255) or -1 on error. */
static int read_reg(uint8_t reg)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return rc;
}

/* Read a 16-bit little-endian word from two consecutive registers. */
static int read_word_le(uint8_t reg_low)
{
    int lo = read_reg(reg_low);
    if (lo < 0)
        return -1;
    int hi = read_reg(reg_low + 1);
    if (hi < 0)
        return -1;
    return (hi << 8) | lo;
}

/* Initialize the LPS33HW: power on, set ODR, BDU, enable IF_ADD_INC. */
static int init_lps33hw(void)
{
    if (write_reg(CTRL_REG1, CTRL_REG1_VAL) < 0)
        return -1;
    if (write_reg(CTRL_REG2, CTRL_REG2_VAL) < 0)
        return -1;
    if (write_reg(CTRL_REG3, CTRL_REG3_VAL) < 0)
        return -1;
    if (write_reg(CTRL_REG4, CTRL_REG4_VAL) < 0)
        return -1;
    return 0;
}

/* Read pressure in hPa (two's complement, 24-bit left-justified). */
static int read_pressure(float *pressure)
{
    int raw = read_word_le(PRESS_OUT_XL);
    if (raw < 0)
        return -1;
    /* 24-bit left-justified -> shift right 8 to get 24-bit value */
    int32_t val = (int32_t)raw >> 8;
    /* Sign-extend from 24 bits to 32 bits */
    if (val & 0x00800000)
        val |= 0xFF000000;
    *pressure = (float)val / 4096.0f;
    return 0;
}

