    if (raw < 0)
        return -1;
    int16_t val = (int16_t)raw;
    *temperature = (float)val / 480.0f + 42.5f;
    return 0;
}

/* Log a reading or error line to the file and stderr. */
static void log_line(const char *line)
{
    if (log_file) {
        fprintf(log_file, "%s\n", line);
        fflush(log_file);
    }
    fprintf(stderr, "%s\n", line);
}

int main(void)
{
