/* CTRL_REG3: SIM=0 (0x00) -> 0x00 */
#define CTRL_REG3_VAL 0x00
/* CTRL_REG4: BLE=0, LIR=0, DIFF_EN=0 -> 0x00 */
#define CTRL_REG4_VAL 0x00

