static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* Write one byte to a register; returns 0 on success, -1 on error. */
static int write_reg(uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to reg 0x%02X: %s\n",
                value, reg, strerror(errno));
        return -1;
    }
    return 0;
