#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define STLM75_ADDR    0x48
#define STLM75_TEMP_REG 0x00
#define LED_GPIO       17
#define BUFFER_SIZE    10
#define TEMP_THRESHOLD 28.0f
#define POLL_DELAY_US  1000000  /* 1 second */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read the STLM75 temperature register (0x00).
 * The sensor returns a signed 16-bit value in degrees Celsius,
 * where each LSB = 0.125 °C.  The pigpio i2cReadWordData returns
 * the raw 16-bit big-endian word, which on the STLM75 is the
 * two's-complement two-byte temperature already in the correct
 * order for conversion to float.
 */
static int read_temperature(int handle, float *temperature)
{
    int raw = i2cReadWordData(handle, STLM75_TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "I2C read error (pigpio code %d)\n", raw);
        return -1;
    }

    /* pigpio returns the word as a signed int; treat as big-endian */
    int16_t signed_raw = (int16_t)raw;
    *temperature = (float)signed_raw * 0.125f;
    return 0;
}

static void update_buffer(float new_temp, float *buffer, int *index, int size)
{
    buffer[*index] = new_temp;
    *index = (*index + 1) % size;
}

static float calculate_average(const float *buffer, int size)
{
    float sum = 0.0f;
    for (int i = 0; i < size; i++)
        sum += buffer[i];
    return sum / (float)size;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus to STLM75 --- */
    int i2c_handle = i2cOpen(I2C_BUS, STLM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X (pigpio code %d)\n",
                I2C_BUS, STLM75_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure LED GPIO --- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);  /* start with LED off */

    /* --- Allocate circular buffer --- */
    float temperature_buffer[BUFFER_SIZE];
    for (int i = 0; i < BUFFER_SIZE; i++)
        temperature_buffer[i] = 0.0f;
    int buffer_index = 0;

    /* --- Main loop --- */
    while (g_running) {
        float temperature;

        if (read_temperature(i2c_handle, &temperature) != 0) {
            /* Skip this iteration; will retry next cycle */
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        update_buffer(temperature, temperature_buffer, &buffer_index, BUFFER_SIZE);
        float average_temperature = calculate_average(temperature_buffer, BUFFER_SIZE);

        printf("Temperature: %.2f C, Average: %.2f C\n",
               temperature, average_temperature);

        if (average_temperature > TEMP_THRESHOLD) {
            gpioWrite(LED_GPIO, 1);
        } else {
            gpioWrite(LED_GPIO, 0);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    gpioWrite(LED_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

