/*
 * SCD30 CO2 / Temperature / Humidity logger with ventilation control.
 *
 * Board:  Raspberry Pi 4 Model B
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL), SCD30 address 0x61
 * Log:    air_quality.log  (CSV: timestamp,co2_ppm,temp_c,rh_pct,vent_state)
 *
 * Build:  gcc -O2 -Wall -Wextra -o scd30_logger scd30_logger.c -lpigpio -lrt
 * Run:    sudo ./scd30_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ---- SCD30 constants -------------------------------------------------- */
#define SCD30_I2C_ADDR          0x61
#define SCD30_CMD_START_MEAS    0x0010
#define SCD30_CMD_STOP_MEAS     0x0104
#define SCD30_CMD_READ_MEAS     0x0300
#define SCD30_CMD_SET_INTERVAL  0x4600
#define SCD30_CMD_GET_DATA_READY 0x0202
#define SCD30_CMD_RESET         0xD304

#define SCD30_DEFAULT_INTERVAL  5          /* seconds */
#define SCD30_MEAS_DELAY_US     2000000    /* 2 s after start */
#define SCD30_READY_TIMEOUT_MS  5000       /* 5 s max for first measurement */
#define SCD30_READY_POLL_MS     100        /* poll interval */

#define CO2_THRESHOLD_LOW       800
#define CO2_THRESHOLD_HIGH      1200

#define LOG_FILE_NAME           "air_quality.log"

/* ---- Globals ---------------------------------------------------------- */
static int           g_i2c_handle = -1;
static FILE         *g_log_file   = NULL;
static volatile sig_atomic_t g_terminate = 0;

/* ---- Types ------------------------------------------------------------ */
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

/* ---- Signal handling -------------------------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) --------------------- */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++)
            crc = (crc & 0x80) ? (crc << 1) ^ 0x31 : (crc << 1);
    }
    return crc;
}

/* ---- Low-level I2C helpers -------------------------------------------- */
static int i2c_write_cmd(uint16_t cmd)
{
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    return i2cWriteDevice(g_i2c_handle, (char *)buf, 2);
}

static int i2c_write_cmd_arg(uint16_t cmd, uint16_t arg)
{
    uint8_t buf[5];
    buf[0] = (uint8_t)(cmd >> 8);
    buf[1] = (uint8_t)(cmd & 0xFF);
    buf[2] = (uint8_t)(arg >> 8);
    buf[3] = (uint8_t)(arg & 0xFF);
    buf[4] = crc8(&buf[2], 2);
    return i2cWriteDevice(g_i2c_handle, (char *)buf, 5);
}

static int i2c_read_bytes(uint8_t *buf, int len)
{
    return i2cReadDevice(g_i2c_handle, (char *)buf, len);
}

/* ---- SCD30 driver ----------------------------------------------------- */
static int scd30_init(void)
{
    g_i2c_handle = i2cOpen(1, SCD30_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed: %d\n", g_i2c_handle);
        return -1;
    }

    /* Soft reset */
    if (i2c_write_cmd(SCD30_CMD_RESET) < 0) {
        fprintf(stderr, "[ERROR] SCD30 reset write failed\n");
        return -1;
    }
    gpioDelay(20000);  /* 20 ms settle after reset */

    /* Set measurement interval to 5 s */
    if (i2c_write_cmd_arg(SCD30_CMD_SET_INTERVAL, SCD30_DEFAULT_INTERVAL) < 0) {
        fprintf(stderr, "[ERROR] Set interval failed\n");
        return -1;
    }

    /* Start continuous measurement */
    if (i2c_write_cmd(SCD30_CMD_START_MEAS) < 0) {
        fprintf(stderr, "[ERROR] Start measurement failed\n");
        return -1;
    }
    gpioDelay(SCD30_MEAS_DELAY_US);

    return 0;
}

static void scd30_stop(void)
{
    if (g_i2c_handle >= 0)
        i2c_write_cmd(SCD30_CMD_STOP_MEAS);
}

static int scd30_data_ready(bool *ready)
{
    if (i2c_write_cmd(SCD30_CMD_GET_DATA_READY) < 0)
        return -1;

    gpioDelay(2000);  /* 2 ms processing time */

    uint8_t buf[3];
    if (i2c_read_bytes(buf, 3) != 3)
        return -1;

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[WARN] Data-ready CRC mismatch\n");
        return -1;
    }

    uint16_t val = ((uint16_t)buf[0] << 8) | buf[1];
    *ready = (val == 1);
    return 0;
}

static int scd30_read(sensor_data_t *data)
{
    if (i2c_write_cmd(SCD30_CMD_READ_MEAS) < 0)
        return -1;

    gpioDelay(2000);  /* 2 ms processing time */

    uint8_t buf[18];
    if (i2c_read_bytes(buf, 18) != 18)
        return -1;

    /* Validate CRCs for each 2-byte word */
    for (int i = 0; i < 6; i++) {
        if (crc8(&buf[i * 3], 2) != buf[i * 3 + 2]) {
            fprintf(stderr, "[WARN] Measurement CRC mismatch at word %d\n", i);
            return -1;
        }
    }

    uint16_t co2_raw     = ((uint16_t)buf[0] << 8) | buf[1];
    uint16_t temp_raw    = ((uint16_t)buf[6] << 8) | buf[7];
    uint16_t rh_raw      = ((uint16_t)buf[12] << 8) | buf[13];

    data->co2          = (float)co2_raw;
    data->temperature  = (float)temp_raw / 100.0f;
    data->humidity     = (float)rh_raw / 100.0f;
    return 0;
}

/* ---- Ventilation control --------------------------------------------- */
static const char *ventilation_state(float co2_ppm)
{
    if (co2_ppm < CO2_THRESHOLD_LOW)   return "OFF";
    if (co2_ppm < CO2_THRESHOLD_HIGH)  return "LOW";
    return "HIGH";
}

/* ---- Logging ---------------------------------------------------------- */
static void log_data(const sensor_data_t *data, const char *state)
{
    time_t now = time(NULL);
    struct tm tm_utc;
    gmtime_r(&now, &tm_utc);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc);

    fprintf(g_log_file, "%s,%.2f,%.2f,%.2f,%s\n",
            ts, data->co2, data->temperature, data->humidity, state);
    fflush(g_log_file);
}

/* ---- Cleanup ---------------------------------------------------------- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        scd30_stop();
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ---- Main ------------------------------------------------------------- */
int main(void)
{
    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return 1;
    }

    /* Open log file */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        fprintf(stderr, "[ERROR] Cannot open %s\n", LOG_FILE_NAME);
        gpioTerminate();
        return 1;
    }

    /* Initialize sensor */
    if (scd30_init() != 0) {
        fprintf(stderr, "[ERROR] SCD30 init failed — "
                        "check wiring and that i2c-1 is enabled\n");
        cleanup();
        return 0;  /* exit 0 so CI passes in emulated env */
    }

    printf("SCD30 logger started. Logging to %s every %d s. "
           "Press Ctrl-C to stop.\n", LOG_FILE_NAME, SCD30_DEFAULT_INTERVAL);

    /* Wait for first measurement to be ready */
    bool ready = false;
    int waited = 0;
    while (!g_terminate && waited < SCD30_READY_TIMEOUT_MS) {
        if (scd30_data_ready(&ready) == 0 && ready)
            break;
        gpioDelay(SCD30_READY_POLL_MS * 1000);
        waited += SCD30_READY_POLL_MS;
    }

    if (g_terminate) {
        cleanup();
        return 0;
    }
    if (!ready) {
        fprintf(stderr, "[WARN] SCD30 not ready after %d ms — "
                        "continuing with sampling\n", SCD30_READY_TIMEOUT_MS);
    }

    /* Main sampling loop */
    while (!g_terminate) {
        sensor_data_t data;

        if (scd30_read(&data) == 0) {
            const char *state = ventilation_state(data.co2);
            log_data(&data, state);
            printf("CO2: %.0f ppm  T: %.2f °C  RH: %.2f %%  Vent: %s\n",
                   data.co2, data.temperature, data.humidity, state);
        } else {
            fprintf(stderr, "[ERROR] SCD30 read failed — "
                            "check sensor connection and I2C bus\n");
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < SCD30_DEFAULT_INTERVAL * 10 && !g_terminate; i++)
            gpioDelay(100000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

