/*
 * SDP32 differential-pressure reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   SDP32 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP32 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP32 VDD  -> 3.3 V
 *   SDP32 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o sdp32_reader sdp32_reader.c
 *
 * Run:
 *   ./sdp32_reader [sampling_interval_ms]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP32_ADDR     0x21
#define SDP32_CMD_MSB  0x36
#define SDP32_CMD_LSB  0x2F
#define READ_LEN       9
#define DEFAULT_INTERVAL_MS 1000

static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* CRC-8 polynomial 0x31, init 0xFF, as used by Sensirion SDP3x family */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char buf[32];
    if (localtime_r(&now, &tm_info) != NULL &&
        strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
        printf("[%s] ", buf);
    }
}

static void sleep_ms(unsigned ms)
{
    struct timespec ts = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    nanosleep(&ts, NULL);
}

int main(int argc, char *argv[])
{
    int interval_ms = DEFAULT_INTERVAL_MS;

    if (argc > 1) {
        long val = strtol(argv[1], NULL, 10);
        if (val > 0 && val <= 100000) {
            interval_ms = (int)val;
        } else {
            fprintf(stderr, "Invalid sampling interval '%s'. Using default %d ms.\n",
                    argv[1], DEFAULT_INTERVAL_MS);
        }
    }

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: pigpio error %d.\n",
                I2C_BUS, SDP32_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * Probe: send a measurement command and read back the first 9 bytes.
     * If the sensor is absent or the bus is mis-wired, i2cReadDevice()
     * will return a negative value.
     */
    uint8_t cmd[2] = { SDP32_CMD_MSB, SDP32_CMD_LSB };
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error writing measurement command to SDP32 (sensor absent or bus error).\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t probe[READ_LEN];
    int n = i2cReadDevice(handle, (char *)probe, READ_LEN);
    if (n != READ_LEN) {
        fprintf(stderr, "Probe read failed: expected %d bytes, got %d (sensor absent or bus error).\n",
                READ_LEN, n);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify CRCs for pressure, temperature, and scale factor */
    if (crc8(&probe[0], 2) != probe[2]) {
        fprintf(stderr, "Pressure CRC mismatch (calc=0x%02X, got=0x%02X).\n",
                crc8(&probe[0], 2), probe[2]);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (crc8(&probe[3], 2) != probe[5]) {
        fprintf(stderr, "Temperature CRC mismatch (calc=0x%02X, got=0x%02X).\n",
                crc8(&probe[3], 2), probe[5]);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (crc8(&probe[6], 2) != probe[8]) {
        fprintf(stderr, "Scale-factor CRC mismatch (calc=0x%02X, got=0x%02X).\n",
                crc8(&probe[6], 2), probe[8]);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SDP32 reader started. Sampling every %d ms. Press Ctrl+C to stop.\n",
           interval_ms);

    while (!g_terminate) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            print_timestamp();
            fprintf(stderr, "Error writing measurement command.\n");
            break;
        }

        uint8_t data[READ_LEN];
        int bytes = i2cReadDevice(handle, (char *)data, READ_LEN);
        if (bytes != READ_LEN) {
            print_timestamp();
            fprintf(stderr, "Error reading %d bytes (got %d).\n", READ_LEN, bytes);
            break;
        }

        /* Verify CRCs */
        if (crc8(&data[0], 2) != data[2] ||
            crc8(&data[3], 2) != data[5] ||
            crc8(&data[6], 2) != data[8]) {
            print_timestamp();
            fprintf(stderr, "CRC mismatch on sensor data.\n");
            break;
        }

        int16_t pressure_raw    = (int16_t)((data[0] << 8) | data[1]);
        int16_t temperature_raw = (int16_t)((data[3] << 8) | data[4]);
        int16_t scale_factor    = (int16_t)((data[6] << 8) | data[7]);

        print_timestamp();
        printf("Pressure: %d Pa, Temperature: %d °C, Scale Factor: %d\n",
               pressure_raw, temperature_raw, scale_factor);

        sleep_ms((unsigned)interval_ms);
    }

    print_timestamp();
    printf("Shutting down.\n");

    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

