    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    int handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: pigpio error %d.\n",
                I2C_BUS, SDP32_ADDR, handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /*
     * Probe: send a measurement command and read back the first 9 bytes.
     * If the sensor is absent or the bus is mis-wired, i2cReadDevice()
     * will return a negative value.
     */
    uint8_t cmd[2] = { SDP32_CMD_MSB, SDP32_CMD_LSB };
    if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
        fprintf(stderr, "Error writing measurement command to SDP32 (sensor absent or bus error).\n");
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    uint8_t probe[READ_LEN];
    int n = i2cReadDevice(handle, (char *)probe, READ_LEN);
    if (n != READ_LEN) {
        fprintf(stderr, "Probe read failed: expected %d bytes, got %d (sensor absent or bus error).\n",
                READ_LEN, n);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify CRCs for pressure, temperature, and scale factor */
    if (crc8(&probe[0], 2) != probe[2]) {
        fprintf(stderr, "Pressure CRC mismatch (calc=0x%02X, got=0x%02X).\n",
                crc8(&probe[0], 2), probe[2]);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (crc8(&probe[3], 2) != probe[5]) {
        fprintf(stderr, "Temperature CRC mismatch (calc=0x%02X, got=0x%02X).\n",
                crc8(&probe[3], 2), probe[5]);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (crc8(&probe[6], 2) != probe[8]) {
        fprintf(stderr, "Scale-factor CRC mismatch (calc=0x%02X, got=0x%02X).\n",
                crc8(&probe[6], 2), probe[8]);
        i2cClose(handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("SDP32 reader started. Sampling every %d ms. Press Ctrl+C to stop.\n",
           interval_ms);

    while (!g_terminate) {
        if (i2cWriteDevice(handle, (char *)cmd, 2) != 0) {
            print_timestamp();
            fprintf(stderr, "Error writing measurement command.\n");
            break;
        }

        uint8_t data[READ_LEN];
        int bytes = i2cReadDevice(handle, (char *)data, READ_LEN);
        if (bytes != READ_LEN) {
            print_timestamp();
            fprintf(stderr, "Error reading %d bytes (got %d).\n", READ_LEN, bytes);
            break;
        }

        /* Verify CRCs */
        if (crc8(&data[0], 2) != data[2] ||
            crc8(&data[3], 2) != data[5] ||
            crc8(&data[6], 2) != data[8]) {
            print_timestamp();
            fprintf(stderr, "CRC mismatch on sensor data.\n");
            break;
        }

        int16_t pressure_raw    = (int16_t)((data[0] << 8) | data[1]);
        int16_t temperature_raw = (int16_t)((data[3] << 8) | data[4]);
        int16_t scale_factor    = (int16_t)((data[6] << 8) | data[7]);

        print_timestamp();
        printf("Pressure: %d Pa, Temperature: %d °C, Scale Factor: %d\n",
               pressure_raw, temperature_raw, scale_factor);

        sleep_ms((unsigned)interval_ms);
    }

    print_timestamp();
    printf("Shutting down.\n");

    i2cClose(handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

