/*
 * SDP810-125Pa differential pressure sensor reader for Raspberry Pi 4.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (BCM 2, physical pin 3)
 *   SDP810 SCL  -> GPIO3 (BCM 3, physical pin 5)
 *   SDP810 VDD  -> 3.3 V
 *   SDP810 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o sdp810 sdp810.c
 *
 * Requires pigpio (http://abyz.me.uk/rpi/pigpio/).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS          1
#define SDP810_ADDR      0x25
#define SAMPLE_PERIOD_S  1
#define CONV_DELAY_US    45000   /* 45 ms conversion time */
#define MAX_RETRIES      3

/* SDP810-125Pa continuous measurement command (no averaging) */
static const uint8_t CMD_CONT_MEAS[2] = {0x36, 0x2F};

/* CRC-8 parameters per Sensirion SDP8xx datasheet */
#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion style)                                             */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Low-level I2C helpers                                               */
/* ------------------------------------------------------------------ */
static int i2c_write_cmd(int handle, const uint8_t *cmd, size_t len)
{
    int rc = i2cWriteDevice(handle, (char *)cmd, (int)len);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed (rc=%d): %s\n",
                rc, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int handle, uint8_t *buf, size_t len)
{
    int rc = i2cReadDevice(handle, (char *)buf, (int)len);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (rc=%d): %s\n",
                rc, pigpio_error(rc));
        return -1;
    }
    if ((size_t)rc != len) {
        fprintf(stderr, "[ERROR] Short read: got %d of %zu bytes\n", rc, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Sensor data structure                                               */
/* ------------------------------------------------------------------ */
typedef struct {
    float differential_pressure;   /* Pa */
    float temperature;             /* °C */
} sensor_data_t;

/* ------------------------------------------------------------------ */
/* Read one sample from the SDP810                                      */
/* ------------------------------------------------------------------ */
static int read_sdp810(int handle, sensor_data_t *out)
{
    uint8_t raw[9];

    /* Trigger continuous measurement */
    if (i2c_write_cmd(handle, CMD_CONT_MEAS, sizeof(CMD_CONT_MEAS)) != 0)
        return -1;

    /* Wait for conversion to complete */
    gpioDelay(CONV_DELAY_US);

    /* Read 9 bytes: pressure(2)+crc, temp(2)+crc, scale(2)+crc */
    if (i2c_read_bytes(handle, raw, sizeof(raw)) != 0)
        return -1;

    /* CRC validation on each 3-byte word */
    for (int i = 0; i < 3; i++) {
        if (crc8(&raw[i * 3], 2) != raw[i * 3 + 2]) {
            fprintf(stderr, "[ERROR] CRC mismatch on word %d\n", i);
            return -1;
        }
    }

    /* Assemble raw values (big-endian, signed) */
    int16_t raw_pressure = (int16_t)((raw[0] << 8) | raw[1]);
    int16_t raw_temp     = (int16_t)((raw[3] << 8) | raw[4]);

    /* Scale factors from the datasheet */
    float pressure_scale = 240.0f;   /* Pa / count */
    float temp_scale     = 200.0f;   /* °C / count */

    out->differential_pressure = (float)raw_pressure / pressure_scale;
    out->temperature            = (float)raw_temp     / temp_scale;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (rc=%d): %s\n",
                g_i2c_handle, pigpio_error(g_i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP810-125Pa reader started. Press Ctrl+C to stop.\n");

    while (g_running) {
        sensor_data_t data;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_sdp810(g_i2c_handle, &data) == 0) {
                ok = 1;
                break;
            }
            /* Brief back-off before retry */
            gpioDelay(10000);
        }

        if (ok) {
            printf("Differential Pressure: %.2f Pa, Temperature: %.2f °C\n",
                   data.differential_pressure, data.temperature);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed after %d attempts; "
                            "check wiring and sensor presence.\n", MAX_RETRIES);
        }

        /* Sleep SAMPLE_PERIOD_S, but wake early on signal */
        for (int s = 0; s < SAMPLE_PERIOD_S && g_running; s++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

