static int hdc1000_write_reg16(int fd, uint8_t reg, uint16_t value)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(value >> 8);
    buf[2] = (uint8_t)(value & 0xFF);

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "Error writing register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from a 16-bit register address.
 * Returns 0 on success and stores the value in *out; -1 on error.
 */
static int hdc1000_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/*
 * Trigger a temperature + humidity measurement and read the results.
 * Returns 0 on success and fills *temp_c and *rh; -1 on error.
 */
static int hdc1000_read(int fd, float *temp_c, float *rh)
{
    uint16_t raw_temp, raw_hum;

    /*
     * Bit 12 (0x1000) of the config register enables the 14-bit
     * temperature and humidity measurement mode.  The device then
     * triggers a single conversion on the next read of the temp
     * register, so we write the config first, wait, then read.
     */
    if (hdc1000_write_reg16(fd, HDC1000_CONFIG_REG, 0x1000) != 0)
        return -1;

    sleep_ms(CONVERSION_DELAY_MS);

    if (hdc1000_read_reg16(fd, HDC1000_TEMP_REG, &raw_temp) != 0)
        return -1;

    if (hdc1000_read_reg16(fd, HDC1000_HUM_REG, &raw_hum) != 0)
        return -1;

    *temp_c = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *rh     = ((float)raw_hum  / 65536.0f) * 100.0f;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    g_fd = open(I2C_BUS, O_RDWR);
    if (g_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", I2C_BUS, strerror(errno));
        fprintf(stderr, "Check that the I2C kernel module is loaded and "
                        "the user has permission to access the bus.\n");
        return EXIT_FAILURE;
    }

    if (ioctl(g_fd, I2C_SLAVE, HDC1000_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                HDC1000_ADDR, strerror(errno));
        close(g_fd);
        g_fd = -1;
        return EXIT_FAILURE;
    }

    /*
     * Probe: a simple read of the temperature register indicates the
     * sensor is present and responding.  If not, the device file was
     * opened but no ACK was received at the sensor address.
     */
    uint16_t probe;
    if (hdc1000_read_reg16(g_fd, HDC1000_TEMP_REG, &probe) != 0) {
        fprintf(stderr, "HDC1000 not detected at address 0x%02X on %s.\n",
                HDC1000_ADDR, I2C_BUS);
        close(g_fd);
        g_fd = -1;
        return EXIT_FAILURE;
    }

    printf("HDC1000 detected. Starting periodic readings every %d s.\n",
           SAMPLE_INTERVAL_S);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        float temp_c, rh;

        if (hdc1000_read(g_fd, &temp_c, &rh) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temp_c, rh);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        /*
         * Sleep in 100 ms increments so signals are caught promptly.
         */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
            sleep_ms(100);
    }

    printf("\nExiting...\n");
    if (g_fd >= 0) {
        close(g_fd);
        g_fd = -1;
    }
    return EXIT_SUCCESS;
}

