#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>

#define I2C_BUS 1
#define SI7051_ADDR 0x40
#define MEASURE_TEMP_CMD 0xF3
#define READ_TEMP_CMD 0xE0
#define READ_PREV_TEMP_CMD 0xE1
#define READ_RH_CMD 0xE5
#define READ_PREV_RH_CMD 0xE0
#define RESET_CMD 0xFE
#define SOFT_RESET_CMD 0x09
#define SAMPLE_INTERVAL_SEC 5
#define MAX_RETRIES 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(float *temperature) {
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cWriteByte(i2c_handle, MEASURE_TEMP_CMD);
        if (result < 0) {
            fprintf(stderr, "Error writing to I2C: %s (attempt %d)\n", strerror(errno), retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }

        gpioDelay(10000);

        result = i2cReadWordData(i2c_handle, READ_TEMP_CMD);
        if (result < 0) {
            fprintf(stderr, "Error reading temperature from I2C: %s (attempt %d)\n", strerror(errno), retries + 1);
            retries++;
            gpioDelay(100000);
            continue;
        }

        uint16_t raw_temp = (uint16_t)result;
        *temperature = (175.72 * raw_temp / 65536.0) - 46.85;
        return 0;
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", MAX_RETRIES);
    return -1;
}

static void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] Temperature: %.2f °C\n", timestamp, temperature);
    fflush(stdout);
}

