/*
 * MLX90833 Pressure Sensor Reader for Raspberry Pi 4 Model B
 *
 * Reads absolute pressure from a Melexis MLX90833 sensor over I2C every
 * 500 ms and logs the value with a timestamp to the console.
 *
 * Wiring:
 *   MLX90833 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   MLX90833 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   MLX90833 VDD -> 3.3 V (pin 1)
 *   MLX90833 GND -> GND  (pin 6)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mlx90833 mlx90833.c -lpigpio -lrt
 * Run:
 *   sudo ./mlx90833
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS        1          /* /dev/i2c-1 on Raspberry Pi 4 */
#define MLX90833_ADDR  0x20       /* Default 7-bit I2C address */

/*
 * MLX90833 register map (subset).
 * The MLX90833 uses a 16-bit register address space; the pigpio i2cReadI2CBlockData
 * and i2cWriteI2CBlockData functions operate on byte buffers, so we must
 * send the 16-bit register address as two separate bytes (big-endian).
 */
#define REG_STATUS     0x00
#define REG_PRESSURE   0x04

#define STATUS_READY   0x01       /* Bit 0: data ready */

#define SAMPLE_PERIOD_US 500000   /* 500 ms */

/* ---- Globals for cleanup ---- */
static int  g_i2c_handle = -1;
static volatile sig_atomic_t g_terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ---- Helpers ---- */

/*
 * Write a 16-bit register address followed by a data byte.
 * Returns 0 on success, -1 on error.
 */
static int mlx_write_reg8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (char)(reg >> 8);
    buf[1] = (char)(reg & 0xFF);
    buf[2] = (char)value;

    if (i2cWriteI2CBlockData(handle, buf[0], &buf[1], 2) < 0) {
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit register address, then read `len` bytes into `data`.
 * Returns 0 on success, -1 on error.
 */
static int mlx_read_reg(int handle, uint16_t reg, uint8_t *data, uint8_t len)
{
    char addr_buf[2];
    addr_buf[0] = (char)(reg >> 8);
    addr_buf[1] = (char)(reg & 0xFF);

    /* Write the 16-bit register address */
    if (i2cWriteI2CBlockData(handle, addr_buf[0], &addr_buf[1], 1) < 0) {
        return -1;
    }

    /* Read the data bytes */
    if (i2cReadI2CBlockData(handle, addr_buf[0], (char *)data, len) != len) {
        return -1;
    }
    return 0;
}

/*
 * Read the 24-bit absolute pressure value from register 0x04.
 * The MLX90833 returns 3 bytes: [status, pressure_hi, pressure_lo].
 * We mask off the status byte and assemble the 24-bit value.
 * Returns 0 on success, -1 on error.
 */
static int read_pressure(int handle, int32_t *pressure_out)
{
    uint8_t data[3];

    if (mlx_read_reg(handle, REG_PRESSURE, data, sizeof(data)) < 0) {
        return -1;
    }

    /* Clear the status bits (upper nibble of the first byte) */
    uint32_t raw = ((uint32_t)(data[0] & 0x0F) << 16) |
                   ((uint32_t)data[1] << 8) |
                   ((uint32_t)data[2]);

    /* Sign-extend from 24 bits to 32 bits */
    if (raw & 0x00800000) {
        raw |= 0xFF000000;
    }

    *pressure_out = (int32_t)raw;
    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, MLX90833_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d). "
                        "Check wiring and that the sensor is present.\n",
                        g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90833 Pressure Sensor Reader\n");
    printf("I2C bus %d, address 0x%02X. Press Ctrl+C to exit.\n",
           I2C_BUS, MLX90833_ADDR);

    /* Main sampling loop */
    while (!g_terminate) {
        int32_t pressure = 0;

        if (read_pressure(g_i2c_handle, &pressure) < 0) {
            fprintf(stderr, "Warning: I2C read error (sensor absent or bus error).\n");
        } else {
            time_t now = time(NULL);
            struct tm tm_info;
            char ts[32];

            if (localtime_r(&now, &tm_info) != NULL &&
                strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info) > 0) {
                printf("[%s] Pressure: %d Pa\n", ts, pressure);
            } else {
                printf("[unknown] Pressure: %d Pa\n", pressure);
            }
            fflush(stdout);
        }

        /* Sleep 500 ms, checking for termination every 100 ms */
        for (int i = 0; i < 5 && !g_terminate; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    printf("\nExiting...\n");
    cleanup();
    return EXIT_SUCCESS;
}

