    return 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register; returns 0 on success, -1 on error    */
/* ------------------------------------------------------------------ */
static int write_register(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Trigger a measurement and wait for conversion                      */
/* ------------------------------------------------------------------ */
static int trigger_measurement(int handle)
{
    if (write_register(handle, ICP10101_REG_MEAS_CMD, ICP10101_MEAS_CMD) < 0) {
        fprintf(stderr, "Error: failed to write measurement command\n");
        return -1;
    }
    gpioDelay(ICP10101_CONV_TIME_US);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read temperature in degrees Celsius (datasheet: 1 LSB = 0.01 °C)   */
/* ------------------------------------------------------------------ */
static int read_temperature(int handle, float *temperature)
{
    uint8_t msb, lsb;

    if (read_register(handle, ICP10101_REG_TEMP_MSB, &msb) < 0) {
        fprintf(stderr, "Error: failed to read temperature MSB\n");
        return -1;
    }
    if (read_register(handle, ICP10101_REG_TEMP_MSB + 1, &lsb) < 0) {
        fprintf(stderr, "Error: failed to read temperature LSB\n");
        return -1;
    }

    int16_t raw = (int16_t)(((uint16_t)msb << 8) | lsb);
    *temperature = (float)raw / 100.0f;
    return 0;
}

/* ------------------------------------------------------------------ */
