    if (read_register(handle, ICP10101_REG_PRESS_MSB, &msb) < 0) {
        fprintf(stderr, "Error: failed to read pressure MSB\n");
        return -1;
    }
    if (read_register(handle, ICP10101_REG_PRESS_MSB + 1, &lsb) < 0) {
        fprintf(stderr, "Error: failed to read pressure LSB\n");
        return -1;
    }

