/* ------------------------------------------------------------------ */
static void print_reading(float temperature, float pressure)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) != NULL) {
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm_info);
    } else {
        snprintf(ts, sizeof(ts), "unknown-time");
    }

    printf("%s - Temperature: %.2f C, Pressure: %.2f Pa\n",
           ts, temperature, pressure);
    fflush(stdout);
}

/* ------------------------------------------------------------------ */
