/*
 * HVAC Airflow Monitor using Sensirion SDP800-500Pa
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (SDA=GPIO2, SCL=GPIO3)
 * Sensor: Sensirion SDP800-500Pa (I2C address 0x25)
 *
 * Build:  gcc -O2 -Wall -o airflow_monitor airflow_monitor.c -lpigpio -lrt
 * Run:    sudo ./airflow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS          1
#define SDP800_ADDR      0x25
#define MEASURE_CMD      0x362F   /* continuous measurement, no averaging */
#define MEASURE_DELAY_US 45000    /* 45 ms measurement time */
#define READ_LEN         9        /* 3 words + 3 CRC bytes */
#define LOG_FILE         "pressure_log.txt"
#define SAMPLE_PERIOD_S  5

/* CRC-8 parameters per Sensirion SDP800 datasheet */
#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
