    rc = i2cWriteWordData(handle, 0x00, MEASURE_CMD);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteWordData failed (rc=%d): %s\n",
                rc, pigpio_error(rc));
