/*
 * Raspberry Pi 4 Model B - Sensirion SDP800-500Pa Differential Pressure Logger
 *
 * Wiring:
 *   SDP800 SDA -> GPIO2 (I2C1 SDA, pin 3)
 *   SDP800 SCL -> GPIO3 (I2C1 SCL, pin 5)
 *   SDP800 VDD -> 3.3 V (pin 1)
 *   SDP800 GND -> GND (pin 6)
 *
 * Build: gcc -O2 -Wall -o airflow_logger airflow_logger.c
 * Run:   ./airflow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define SDP800_ADDR    0x25
#define LOG_FILE       "airflow_log.csv"
#define MEAS_DELAY_MS  8
#define POLL_DELAY_MS  100

/* SDP800-500Pa trigger command (no arguments) */
static const uint8_t CMD_TRIGGER[0] = {0x36, 0x2F};

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ---- CRC-8 (Sensirion polynomial 0x31, init 0xFF) ---- */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_cmd(int fd, const uint8_t *cmd, size_t len)
{
    if (write(fd, cmd, len) != (ssize_t)len) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read failed: expected %zu bytes, got %zd (%s)\n",
                len, n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    return 0;
}

/* ---- Sensor read ---- */
static int read_sdp800(int fd, float *pressure)
{
    uint8_t buf[3];

    /* Trigger measurement */
    if (i2c_write_cmd(fd, CMD_TRIGGER, sizeof(CMD_TRIGGER)) != 0)
        return -1;

    /* Wait for conversion (datasheet: typ 5 ms, max 8 ms) */
    usleep(MEAS_DELAY_MS * 1000);

    /* Read 3 bytes: MSB, LSB, CRC */
    if (i2c_read_bytes(fd, buf, sizeof(buf)) != 0)
        return -1;

    /* CRC check */
    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch: calc=0x%02X recv=0x%02X\n",
                crc8(buf, 2), buf[2]);
        return -1;
    }

    /* Convert: 16-bit signed, LSB = 1 Pa */
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *pressure = (float)raw;
    return 0;
}

/* ---- Logging ---- */
static int log_data(FILE *fp, float pressure)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f\n", ts, pressure) < 0) {
        fprintf(stderr, "fprintf failed: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp);
    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

int main(void)
{
    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, SDP800_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                SDP800_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (append) */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (fseek(g_log_fp, 0, SEEK_END) == 0) {
        long sz = ftell(g_log_fp);
        if (sz == 0) {
            fprintf(g_log_fp, "timestamp,pressure_pa\n");
            fflush(g_log_fp);
        }
    }

    printf("SDP800 logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        float pressure;
        if (read_sdp800(g_i2c_fd, &pressure) == 0) {
            if (log_data(g_log_fp, pressure) != 0)
                fprintf(stderr, "Logging failed; continuing.\n");
        } else {
            fprintf(stderr, "Sensor read failed; will retry.\n");
        }
        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

