#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/*
 * MLX90821 pressure sensor reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   MLX90821 SDA  -> GPIO 2 (I2C bus 1 SDA)
 *   MLX90821 SCL  -> GPIO 3 (I2C bus 1 SCL)
 *   MLX90821 VDD  -> 3.3 V
 *   MLX90821 GND  -> GND
 *
 * The MLX90821 is a digital pressure sensor; this program assumes
 * a driver library (mlx90821.h) is available and provides the
 * following functions:
 *
 *   int  mlx90821_init(void)
 *   int  mlx90821_read_pressure(float *pressure_kPa)
 *   void mlx90821_close(void)
 *
 * The sensor returns pressure in kPa.
 */

#include "mlx90821.h"

#define I2C_BUS        1
#define I2C_ADDR       0x2A          /* MLX90821 default I2C address */
#define LOG_FILE       "pressure_log.csv"
#define SAMPLE_PERIOD  1.0           /* seconds between samples */
#define MIN_PRESSURE   200.0f        /* kPa, safe tire minimum */
#define MAX_PRESSURE   250.0f        /* kPa, safe tire maximum */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    mlx90821_close();
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Open the log file; write a header only if the file is new/empty.    */
/* ------------------------------------------------------------------ */
static int open_log_file(void)
{
    long pos;

    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    /* Determine whether the file is newly created (size == 0). */
    pos = ftell(g_log_file);
    if (pos < 0) {
        perror("ftell");
        fclose(g_log_file);
        g_log_file = NULL;
        return -1;
    }

    if (pos == 0) {
        if (fprintf(g_log_file, "timestamp,pressure_kPa\n") < 0) {
            perror("fprintf(header)");
            fclose(g_log_file);
            g_log_file = NULL;
            return -1;
        }
        if (fflush(g_log_file) != 0) {
            perror("fflush(header)");
            fclose(g_log_file);
            g_log_file = NULL;
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append one data row to the CSV log.                                 */
/* ------------------------------------------------------------------ */
static int log_pressure(float pressure_kPa)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%.2f\n", timestamp, pressure_kPa) < 0) {
        perror("fprintf(data)");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        perror("fflush(data)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Reopen the I2C bus after a failure.                                 */
/* ------------------------------------------------------------------ */
static int reopen_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float pressure_kPa;

    /* --- Initialize pigpio ---------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* --- Initialize MLX90821 driver -------------------------------- */
    if (mlx90821_init() != 0) {
        fprintf(stderr, "mlx90821_init failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus ---------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        mlx90821_close();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --------------------------------------------- */
    if (open_log_file() != 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        mlx90821_close();
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers ----------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("MLX90821 pressure logger started.  Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop ---------------------------------------- */
    while (g_running) {
        if (mlx90821_read_pressure(&pressure_kPa) != 0) {
            fprintf(stderr, "mlx90821_read_pressure failed; "
                            "reopening I2C and retrying once.\n");
            if (reopen_i2c() != 0) {
                fprintf(stderr, "I2C reopen failed; continuing to retry.\n");
            } else {
                if (mlx90821_read_pressure(&pressure_kPa) != 0) {
                    fprintf(stderr, "Second read attempt failed; "
                                    "will retry next cycle.\n");
                }
            }
        } else {
            if (log_pressure(pressure_kPa) != 0) {
                fprintf(stderr, "log_pressure failed.\n");
            }

            if (pressure_kPa < MIN_PRESSURE || pressure_kPa > MAX_PRESSURE) {
                fprintf(stderr,
                        "WARNING: Pressure %.2f kPa outside safe tire range "
                        "[%.0f, %.0f] kPa\n",
                        pressure_kPa, MIN_PRESSURE, MAX_PRESSURE);
            }
        }

        time_sleep(SAMPLE_PERIOD);
    }

    /* --- Graceful shutdown ----------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

