#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define HIH6130_ADDR   0x27
#define LOG_FILE       "environmental_data.log"
#define LOG_SIZE_LIMIT 1048576  /* 1 MB */
#define MEASURE_DELAY  5        /* seconds between readings */
#define CONVERSION_MS  40       /* HIH6130 conversion time */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Open the I2C bus and set the slave address.
 * Returns 0 on success, -1 on failure.
 */
static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus %s: %s\n", bus, strerror(errno));
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "Error setting I2C slave address 0x%02X: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Read 4 bytes from the HIH6130.
 * Returns 0 on success, -1 on failure.
 */
static int hih6130_read(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C read error: %s\n", strerror(errno));
        return -1;
    }
    if (n != (ssize_t)len) {
        fprintf(stderr, "I2C read short: got %zd of %zu bytes\n", n, len);
        return -1;
    }
    return 0;
}

/*
 * Trigger a measurement and read the result.
 * Returns 0 on success, -1 on failure.
 */
static int hih6130_measure(int fd, float *temperature, float *humidity)
{
    uint8_t buf[4];

    /* Trigger a measurement by writing a zero-length message. */
    if (write(fd, buf, 0) < 0) {
        fprintf(stderr, "Error triggering measurement: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for the conversion to complete. */
    usleep(CONVERSION_MS * 1000);

    /* Read the 4-byte result. */
    if (hih6130_read(fd, buf, sizeof(buf)) < 0) {
        return -1;
    }

    /* Check status bits (upper nibble of the first byte). */
    uint8_t status = (buf[0] >> 6) & 0x03;
    if (status != 0x00) {
        fprintf(stderr, "HIH6130 status error: 0x%02X\n", status);
        return -1;
    }

    /* Humidity: 14-bit value, 0.01 %RH resolution. */
    uint16_t raw_humidity = ((uint16_t)(buf[0] & 0x3F) << 8) | buf[1];
    *humidity = (float)raw_humidity / 16383.0f * 100.0f;

    /* Temperature: 14-bit value, 0.01 °C resolution. */
    uint16_t raw_temp = ((uint16_t)buf[2] << 6) | (buf[3] >> 2);
    *temperature = (float)raw_temp / 16383.0f * 165.0f - 40.0f;

    return 0;
}

/*
 * Write a reading to the log file with an ISO-8601 timestamp.
 * Returns 0 on success, -1 on failure.
 */
static int log_data(const char *filename, float temperature, float humidity)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file %s: %s\n", filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/*
 * Check the log file size and roll it if it exceeds the limit.
 * Returns 0 on success, -1 on failure.
 */
static int log_roll(const char *filename, long limit)
{
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        /* File does not exist yet; nothing to roll. */
        return 0;
    }

    if (fseek(fp, 0, SEEK_END) != 0) {
        fprintf(stderr, "Error seeking in log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    long size = ftell(fp);
    if (size < 0) {
        fprintf(stderr, "Error getting log file size: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    if (size > limit) {
        fp = fopen(filename, "w");
        if (!fp) {
            fprintf(stderr, "Error opening log file for truncation: %s\n", strerror(errno));
            return -1;
        }
        if (fclose(fp) != 0) {
            fprintf(stderr, "Error closing log file after truncation: %s\n", strerror(errno));
            return -1;
        }
        printf("Log file rolled (size exceeded %ld bytes).\n", limit);
    }

    return 0;
}

int main(void)
{
    /* Register signal handler for graceful shutdown. */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    /* Open the I2C bus and set the slave address. */
    g_i2c_fd = i2c_open(I2C_BUS, HIH6130_ADDR);
    if (g_i2c_fd < 0) {
        return 1;
    }

    printf("HIH6130 environmental monitor started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float temperature, humidity;

        if (hih6130_measure(g_i2c_fd, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n", temperature, humidity);

            if (log_data(LOG_FILE, temperature, humidity) < 0) {
                fprintf(stderr, "Failed to log data.\n");
            }

            if (log_roll(LOG_FILE, LOG_SIZE_LIMIT) < 0) {
                fprintf(stderr, "Failed to roll log file.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        /* Sleep for the measurement interval, but wake early on signal. */
        for (int i = 0; i < MEASURE_DELAY && g_running; i++) {
            sleep(1);
        }
    }

    /* Clean up resources. */
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    printf("\nExiting gracefully.\n");
    return 0;
}

