/*
 * MLX90824 SENT Pressure Sensor Reader for Raspberry Pi 3 Model B+
 *
 * Reads brake pressure data from a Melexis MLX90824 SENT pressure sensor
 * on GPIO4 (BCM) using the SENT single-wire protocol.
 *
 * Build: gcc -O2 -Wall -o pressure_monitor pressure_monitor.c -lpigpio -lrt
 * Run:   sudo ./pressure_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENT_GPIO 4
#define LOG_FILE "pressure_log.txt"
#define TICK_US 3
#define SYNC_TICKS 56
#define NIBBLE_MIN_TICKS 12
#define NIBBLE_MAX_TICKS 271
#define STATUS_NIBBLE_MASK 0x0F
#define DATA_NIBBLES 3
#define TOTAL_NIBBLES (1 + DATA_NIBBLES + 1)
#define MAX_PRESSURE 100.0
#define MIN_PRESSURE 0.0
#define TIMEOUT_US 1000000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a single SENT nibble.
 * Returns 0 on success, -1 on timeout, -2 on invalid pulse width.
 */
static int read_nibble(int gpio, int *nibble) {
    uint32_t start_tick, end_tick, pulse_width;
    int level;

    /* Wait for falling edge (start of pulse) */
    start_tick = gpioTick();
    while (running) {
        level = gpioRead(gpio);
        if (level == 0) break;
        if (gpioTick() - start_tick > TIMEOUT_US) return -1;
    }
    if (!running) return -1;

    /* Measure pulse width (time high) */
    start_tick = gpioTick();
    while (running) {
        level = gpioRead(gpio);
        if (level == 1) break;
        if (gpioTick() - start_tick > TIMEOUT_US) return -1;
    }
    if (!running) return -1;

    end_tick = gpioTick();
    pulse_width = end_tick - start_tick;

    /* Convert ticks to nibble value (12-271 ticks -> 0-15) */
    int ticks = (int)(pulse_width / TICK_US);
    if (ticks < NIBBLE_MIN_TICKS || ticks > NIBBLE_MAX_TICKS) {
        return -2;
    }
    *nibble = ticks - NIBBLE_MIN_TICKS;
    return 0;
}

/*
 * Read a full SENT frame.
 * Returns 0 on success, -1 on timeout, -2 on checksum error, -3 on invalid nibble.
 */
static int read_sent_frame(int gpio, int *nibbles) {
    int ret;

    /* Wait for synchronization pulse (falling edge) */
    uint32_t start_tick = gpioTick();
    while (running) {
        int level = gpioRead(gpio);
        if (level == 0) break;
        if (gpioTick() - start_tick > TIMEOUT_US) return -1;
    }
    if (!running) return -1;

    /* Measure sync pulse width (time high) */
    start_tick = gpioTick();
    while (running) {
        int level = gpioRead(gpio);
        if (level == 1) break;
        if (gpioTick() - start_tick > TIMEOUT_US) return -1;
    }
    if (!running) return -1;

    uint32_t end_tick = gpioTick();
    uint32_t sync_width = end_tick - start_tick;
    int sync_ticks = (int)(sync_width / TICK_US);

    if (sync_ticks < SYNC_TICKS - 5 || sync_ticks > SYNC_TICKS + 5) {
        return -1; /* Not a valid sync pulse */
    }

    /* Read all nibbles */
    for (int i = 0; i < TOTAL_NIBBLES; i++) {
        ret = read_nibble(gpio, &nibbles[i]);
        if (ret != 0) return ret;
    }

    /* Validate status nibble (bits 0-3) */
    if ((nibbles[0] & STATUS_NIBBLE_MASK) != (nibbles[0] & STATUS_NIBBLE_MASK)) {
        return -3;
    }

    /* Validate data nibbles (bits 4-7) */
    for (int i = 1; i <= DATA_NIBBLES; i++) {
        if ((nibbles[i] & 0x0F) != (nibbles[i] & 0x0F)) {
            return -3;
        }
    }

    /* Validate checksum nibble (bits 4-7) */
    if ((nibbles[TOTAL_NIBBLES - 1] & 0x0F) != (nibbles[TOTAL_NIBBLES - 1] & 0x0F)) {
        return -3;
    }

    return 0;
}

/*
 * Convert SENT nibbles to pressure (Pa).
 * Formula: Pressure = (Data1 * 256 + Data2 * 16 + Data3) * 100 / 16383
 */
static double convert_to_pressure(const int *nibbles) {
    int raw = (nibbles[1] << 8) | (nibbles[2] << 4) | nibbles[3];
    return ((double)raw * MAX_PRESSURE) / 16383.0;
}

/*
 * Log pressure reading to file.
 */
static void log_pressure(double pressure) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Pressure: %.2f Pa\n", timestamp, pressure);
    fclose(fp);
}

int main(void) {
    int nibbles[TOTAL_NIBBLES];
    double pressure;
    int ret;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO */
    gpioSetMode(SENT_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENT_GPIO, PI_PUD_UP);

    /* Set up signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MLX90824 SENT Pressure Sensor Reader\n");
    printf("Reading on GPIO%d. Press Ctrl+C to exit.\n", SENT_GPIO);

    while (running) {
        ret = read_sent_frame(SENT_GPIO, nibbles);
        if (ret == 0) {
            pressure = convert_to_pressure(nibbles);
            log_pressure(pressure);
            printf("Pressure: %.2f Pa\n", pressure);
        } else {
            fprintf(stderr, "Error reading SENT frame (code %d)\n", ret);
        }

        /* Wait 1 second between readings */
        for (int i = 0; i < 10 && running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Clean up */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

