/* TMP117 I2C address (ADDR pin tied to GND) */
#define TMP117_ADDR 0x48

/* TMP117 register addresses */
#define TMP117_REG_TEMP_RESULT 0x00
#define TMP117_REG_DEVICE_ID   0x0F

/* Expected device ID for TMP117 (0x117) */
#define TMP117_DEVICE_ID 0x0117

/* Conversion time for 12-bit resolution (50 ms) */
#define TMP117_CONV_TIME_MS 50

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Function to read a 16-bit register from the TMP117 */
static int read_register16(int handle, uint8_t reg, int16_t *value) {
    char buf[2];
    int result;

    result = i2cWriteByte(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error writing register address 0x%02X: %d\n", reg, result);
        return -1;
    }

    gpioDelay(1000); /* 1 ms delay for register selection */

    result = i2cReadDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }

    /* TMP117 sends data in little-endian format */
    *value = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

/* Function to read the temperature from the TMP117 */
static int read_temperature(int handle, float *temperature) {
    int16_t raw_temp;
    int result;

    result = read_register16(handle, TMP117_REG_TEMP_RESULT, &raw_temp);
    if (result < 0) {
        return -1;
    }

    /* Convert raw temperature to degrees Celsius */
    *temperature = (float)raw_temp / 256.0f;
    return 0;
}

/* Function to log the temperature to a binary file */
static int log_temperature(FILE *file, float temperature) {
    size_t bytes_written;

    bytes_written = fwrite(&temperature, sizeof(float), 1, file);
    if (bytes_written != 1) {
        fprintf(stderr, "Error writing temperature to file: %zu bytes written\n", bytes_written);
        return -1;
    }

    fflush(file);
    return 0;
}

/* Function to verify the TMP117 device ID */
static int verify_device_id(int handle) {
    int16_t device_id;
    int result;

    result = read_register16(handle, TMP117_REG_DEVICE_ID, &device_id);
    if (result < 0) {
        return -1;
    }

    /* The device ID register returns a 16-bit value; the lower 12 bits contain the ID */
    uint16_t id = (uint16_t)(device_id & 0x0FFF);
    if (id != TMP117_DEVICE_ID) {
        fprintf(stderr, "Device ID mismatch: expected 0x%03X, got 0x%03X\n", TMP117_DEVICE_ID, id);
        return -1;
    }

    return 0;
}

