#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define LOG_FILE "environmental_data.txt"
#define SAMPLE_INTERVAL_SEC 5
#define CONVERSION_DELAY_US 10000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (crc << 1) ^ 0x31;
            else
                crc <<= 1;
        }
    }
    return crc;
}

static int read_sht40(int handle, float *temperature, float *humidity) {
    uint8_t cmd = MEASURE_CMD;
    uint8_t data[6];

    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: I2C write failed\n");
        return -1;
    }

    gpioDelay(CONVERSION_DELAY_US);

    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed\n");
        return -1;
    }

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }

    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch\n");
        return -1;
    }

    uint16_t temp_raw = (data[0] << 8) | data[1];
    uint16_t hum_raw = (data[3] << 8) | data[4];

    *temperature = -45.0f + 175.0f * (float)temp_raw / 65535.0f;
    *humidity = 100.0f * (float)hum_raw / 65535.0f;

    return 0;
}

static int log_data(FILE *fp, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s, Temperature: %.2f C, Humidity: %.2f %%\n",
                timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Error: Failed to write to log file\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error: Failed to flush log file\n");
        return -1;
    }

    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device at address 0x%02X\n", SHT40_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file '%s'\n", LOG_FILE);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: Failed to install SIGINT handler\n");
    }

    float temperature, humidity;

    while (running) {
        if (read_sht40(i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(log_file, temperature, humidity) != 0) {
                fprintf(stderr, "Error: Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Error: Sensor read failed, continuing...\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && running; i++) {
            sleep(1);
        }
    }

    fprintf(stderr, "\nShutting down cleanly...\n");

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

