#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TMP117_TEMP_REG 0x00
#define TMP117_CONFIG_REG 0x01
#define BUFFER_SIZE 10
#define SAMPLE_INTERVAL_SEC 5
#define LOG_FILE "temperature_log.dat"

typedef struct {
    time_t timestamp;
    float temperature;
} TemperatureReading;

typedef struct {
    TemperatureReading buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static int i2c_handle = -1;
static CircularBuffer temp_buffer;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at addr 0x%02X: %d\n", I2C_BUS, TMP117_ADDR, i2c_handle);
        return -1;
    }
    return 0;
}

static int init_tmp117(void) {
    int status = i2cWriteByteData(i2c_handle, TMP117_CONFIG_REG, 0x60);
    if (status < 0) {
        fprintf(stderr, "Error writing TMP117 config register: %d\n", status);
        return -1;
    }
    return 0;
}

static int read_temperature(float *temperature) {
    int raw = i2cReadWordData(i2c_handle, TMP117_TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "Error reading temperature register: %d\n", raw);
        return -1;
    }
    int16_t temp_raw = (int16_t)((raw & 0xFF) << 8 | (raw >> 8));
    *temperature = (float)temp_raw / 128.0f;
    return 0;
}

static void buffer_init(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

static void buffer_add(CircularBuffer *cb, time_t timestamp, float temperature) {
    cb->buffer[cb->head].timestamp = timestamp;
    cb->buffer[cb->head].temperature = temperature;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

static int write_buffer_to_file(const CircularBuffer *cb, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        perror("Error opening file for writing");
        return -1;
    }
    size_t written = fwrite(cb->buffer, sizeof(TemperatureReading), cb->count, fp);
    if (written != (size_t)cb->count) {
        fprintf(stderr, "Error writing buffer to file: wrote %zu of %d entries\n", written, cb->count);
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        perror("Error closing file");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_tmp117() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    buffer_init(&temp_buffer);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Error setting up signal handlers");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        float temperature;
        if (read_temperature(&temperature) == 0) {
            time_t now = time(NULL);
            buffer_add(&temp_buffer, now, temperature);
            printf("Temperature: %.2f C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping sample.\n");
        }

        if (write_buffer_to_file(&temp_buffer, LOG_FILE) != 0) {
            fprintf(stderr, "Failed to write buffer to file.\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_SEC && !terminate; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    if (write_buffer_to_file(&temp_buffer, LOG_FILE) != 0) {
        fprintf(stderr, "Failed to write final buffer to file.\n");
    }
    cleanup();
    printf("Temperature monitoring stopped.\n");
    return EXIT_SUCCESS;
}

