#define MEASURE_CMD_HIGH_REP 0x78
#define MEASURE_CMD_LOW_POWER 0x60
#define MEASURE_CMD_ULTRA_LOW_POWER 0x40
#define MEASUREMENT_DELAY_US 12500
#define LOG_FILE "shtc3_environment.log"
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_shtc3(int handle, float *temperature, float *humidity) {
    uint8_t cmd = MEASURE_CMD_HIGH_REP;
    uint8_t data[6];

    if (i2cWriteDevice(handle, (char *)&cmd, 1) != 0) {
        fprintf(stderr, "Error: I2C write failed.\n");
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_US);

    if (i2cReadDevice(handle, (char *)data, 6) != 6) {
        fprintf(stderr, "Error: I2C read failed.\n");
        return -1;
    }

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Error: Temperature CRC mismatch.\n");
        return -1;
    }
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Error: Humidity CRC mismatch.\n");
        return -1;
    }

    uint16_t temp_ticks = (data[0] << 8) | data[1];
    uint16_t hum_ticks = (data[3] << 8) | data[4];

    *temperature = -40.0f + 175.0f * (float)temp_ticks / 65535.0f;
    *humidity = 100.0f * (float)hum_ticks / 65535.0f;

    if (*temperature < -40.0f || *temperature > 125.0f) {
        fprintf(stderr, "Error: Temperature out of range: %.2f\n", *temperature);
        return -1;
    }
    if (*humidity < 0.0f || *humidity > 100.0f) {
        fprintf(stderr, "Error: Humidity out of range: %.2f\n", *humidity);
        return -1;
    }

    return 0;
}

static int log_data(float temperature, float humidity) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file %s.\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            temperature, humidity);
    fclose(fp);
    return 0;
