/*
 * Si7202 I2C Hall-effect sensor reader for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Si7202 SDA -> GPIO2 (pin 3, I2C bus 1)
 *   Si7202 SCL -> GPIO3 (pin 5, I2C bus 1)
 *   Si7202 VDD -> 3.3 V
 *   Si7202 GND -> GND
 *
 * Build: gcc -O2 -Wall -o mag_temp mag_temp.c -lpigpio -lrt -lm
 * Run:   sudo ./mag_temp
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ---- Si7202 constants (from datasheet) ---- */
#define SI7202_I2C_ADDR        0x30
#define SI7202_REG_DEVICE_ID   0x00
#define SI7202_REG_SPEED       0x02
#define SI7202_REG_TEMP        0x04
#define SI7202_REG_CTRL        0x08
#define SI7202_REG_STATUS      0x0A

#define SI7202_CTRL_MEAS_EN    0x01
#define SI7202_CTRL_RESET      0x80
#define SI7202_STATUS_RDY      0x01

#define SI7202_DEVICE_ID       0x0D

#define LOG_FILE_NAME          "mag_temp_log.csv"
#define SAMPLE_PERIOD_US       1000000  /* 1 second */

/* ---- Globals for cleanup ---- */
static int      g_i2c_handle = -1;
static FILE    *g_log_file   = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to a register; returns 0 on success, -1 on error.   */
static int reg_write(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from a register; returns value (0-255) or -1 on err. */
static int reg_read(int handle, uint8_t reg)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit little-endian value from two consecutive registers.  */
static int reg_read16(int handle, uint8_t reg, uint16_t *out)
{
    int lo = reg_read(handle, reg);
    if (lo < 0)
        return -1;
    int hi = reg_read(handle, reg + 1);
    if (hi < 0)
        return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the Si7202: verify device ID, reset, enable measurement. */
static int si7202_init(int handle)
{
    int id = reg_read(handle, SI7202_REG_DEVICE_ID);
    if (id < 0) {
        fprintf(stderr, "[ERROR] Cannot read device ID (sensor absent or bus error).\n");
        return -1;
    }
    if (id != SI7202_DEVICE_ID) {
        fprintf(stderr, "[ERROR] Unexpected device ID 0x%02X (expected 0x%02X).\n",
                id, SI7202_DEVICE_ID);
        return -1;
    }
    printf("[INFO] Si7202 detected (device ID 0x%02X).\n", id);

    /* Software reset */
    if (reg_write(handle, SI7202_REG_CTRL, SI7202_CTRL_RESET) < 0)
        return -1;
    gpioDelay(20000);  /* 20 ms settle after reset */

    /* Enable continuous measurement mode */
    if (reg_write(handle, SI7202_REG_CTRL, SI7202_CTRL_MEAS_EN) < 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read speed (RPM) and temperature (°C). Returns 0 on success.       */
static int si7202_read(int handle, float *speed, float *temp)
{
    /* Poll STATUS bit 0 (RDY) — max ~10 ms for a conversion */
    for (int i = 0; i < 10; i++) {
        int st = reg_read(handle, SI7202_REG_STATUS);
        if (st < 0)
            return -1;
        if (st & SI7202_STATUS_RDY)
            break;
        gpioDelay(1000);  /* 1 ms */
    }

    uint16_t raw_speed, raw_temp;
    if (reg_read16(handle, SI7202_REG_SPEED, &raw_speed) < 0)
        return -1;
    if (reg_read16(handle, SI7202_REG_TEMP, &raw_temp) < 0)
        return -1;

    /* Convert raw values to physical units (per datasheet) */
    *speed = (float)raw_speed / 10.0f;          /* counts -> RPM */
    *temp  = (float)raw_temp / 100.0f;          /* 0.01 °C per LSB */

    return 0;
}

/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float speed, float temp, bool ok)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    if (ok)
        fprintf(fp, "%s,%.2f,%.2f\n", ts, speed, temp);
    else
        fprintf(fp, "%s,NaN,NaN\n", ts);

    fflush(fp);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si7202 address */
    g_i2c_handle = i2cOpen(1, SI7202_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                SI7202_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si7202_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] Si7202 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (append); create header if new */
    bool file_exists = (access(LOG_FILE_NAME, F_OK) == 0);
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open %s for append.\n", LOG_FILE_NAME);
        cleanup();
        return EXIT_FAILURE;
    }
    if (!file_exists)
        fprintf(g_log_file, "timestamp,speed_rpm,temperature_c\n");

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE_NAME);

    /* Main sampling loop */
    while (g_running) {
        float speed = 0.0f, temp = 0.0f;
        bool ok = (si7202_read(g_i2c_handle, &speed, &temp) == 0);

        if (ok)
            printf("[INFO] Speed: %.2f RPM, Temp: %.2f °C\n", speed, temp);
        else
            fprintf(stderr, "[WARN] Sensor read failed; logging NaN.\n");

        log_data(g_log_file, speed, temp, ok);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

