    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the Si7202 address */
    g_i2c_handle = i2cOpen(1, SI7202_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                SI7202_I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (si7202_init(g_i2c_handle) < 0) {
        fprintf(stderr, "[FATAL] Si7202 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file (append); create header if new */
    bool file_exists = (access(LOG_FILE_NAME, F_OK) == 0);
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (!g_log_file) {
        fprintf(stderr, "[FATAL] Cannot open %s for append.\n", LOG_FILE_NAME);
        cleanup();
        return EXIT_FAILURE;
    }
    if (!file_exists)
        fprintf(g_log_file, "timestamp,speed_rpm,temperature_c\n");

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Logging to %s. Press Ctrl+C to stop.\n", LOG_FILE_NAME);

    /* Main sampling loop */
    while (g_running) {
        float speed = 0.0f, temp = 0.0f;
        bool ok = (si7202_read(g_i2c_handle, &speed, &temp) == 0);

        if (ok)
            printf("[INFO] Speed: %.2f RPM, Temp: %.2f °C\n", speed, temp);
        else
            fprintf(stderr, "[WARN] Sensor read failed; logging NaN.\n");

        log_data(g_log_file, speed, temp, ok);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\n[INFO] Shutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

