#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define TMP117_ADDR 0x48
#define TMP117_TEMP_REG 0x00
#define TMP117_CONFIG_REG 0x01
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_US 1000000
#define MAX_REINIT_ATTEMPTS 3

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at 0x%02X: %s\n",
                TMP117_ADDR, strerror(errno));
        gpioTerminate();
        return -1;
    }

    /* Configure TMP117: continuous conversion, 1 Hz update rate */
    if (i2cWriteWordData(i2c_handle, TMP117_CONFIG_REG, 0x0000) < 0) {
        fprintf(stderr, "Failed to write TMP117 config register: %s\n",
                strerror(errno));
        i2cClose(i2c_handle);
        i2c_handle = -1;
        gpioTerminate();
        return -1;
    }

    return 0;
}

static int read_temperature(float *temperature) {
    int raw = i2cReadWordData(i2c_handle, TMP117_TEMP_REG);
    if (raw < 0) {
        fprintf(stderr, "Failed to read temperature register: %s\n",
                strerror(errno));
        return -1;
    }

    /* TMP117 returns 16-bit two's complement; pigpio returns raw byte data */
    int16_t signed_raw = (int16_t)((raw & 0xFF) << 8 | ((raw >> 8) & 0xFF));
    *temperature = (float)signed_raw / 128.0f;
    return 0;
}

static int log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Failed to get local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Failed to format timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s, Temperature: %.2f C\n", timestamp, temperature) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Failed to close log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n",
                strerror(errno));
        return 1;
    }

    if (init_i2c() != 0) {
        return 1;
    }

    int reinit_attempts = 0;

    while (running) {
        float temperature;

        if (read_temperature(&temperature) == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
            reinit_attempts = 0;
        } else {
            fprintf(stderr, "Temperature read failed. Attempting re-initialization...\n");

            if (reinit_attempts < MAX_REINIT_ATTEMPTS) {
                reinit_attempts++;
                fprintf(stderr, "Re-initialization attempt %d/%d\n",
                        reinit_attempts, MAX_REINIT_ATTEMPTS);

                if (i2c_handle >= 0) {
                    i2cClose(i2c_handle);
                    i2c_handle = -1;
                }
                gpioTerminate();

                if (init_i2c() != 0) {
                    fprintf(stderr, "Re-initialization failed.\n");
                    if (reinit_attempts >= MAX_REINIT_ATTEMPTS) {
                        fprintf(stderr, "Max re-initialization attempts reached. Exiting.\n");
                        break;
                    }
                } else {
                    fprintf(stderr, "Re-initialization successful.\n");
                    reinit_attempts = 0;
                }
            } else {
                fprintf(stderr, "Max re-initialization attempts reached. Exiting.\n");
                break;
            }
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return 0;
}

