code:
/*
 * Raspberry Pi Zero W - Honeywell HAF Series HAFUHH0025PA3 Airflow Sensor
 *
 * Reads 4 bytes from the sensor every second, extracts a 14-bit flow
 * value and a 12-bit temperature value, and logs them to flow_log.txt.
 *
 * Wiring:
 *   VCC -> 3.3V (Pin 1)
 *   GND -> GND  (Pin 9)
 *   SDA -> GPIO2 / I2C1 SDA (Pin 3)
 *   SCL -> GPIO3 / I2C1 SCL (Pin 5)
 *
 * Build: gcc -o flow_logger flow_logger.c -lpigpio -lrt
 * Run:   sudo ./flow_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x28
#define LOG_FILE       "flow_log.txt"
#define SAMPLE_PERIOD  1.0   /* seconds */
#define MAX_RETRIES    3

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Initialise I2C                                                      */
/* ------------------------------------------------------------------ */
static int init_i2c(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }

    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen failed (bus=%d, addr=0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 4 bytes from the sensor                                        */
/* ------------------------------------------------------------------ */
static int read_sensor_data(uint8_t *data)
{
    int bytes_read = i2cReadDevice(g_i2c_handle, (char *)data, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "[ERROR] i2cReadDevice returned %d (expected 4)\n",
                bytes_read);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Parse 4 bytes into flow (SLPM) and temperature (deg C)              */
/* ------------------------------------------------------------------ */
static void parse_data(const uint8_t *data, float *flow, float *temp)
{
    /*
     * HAFUHH0025PA3 4-byte data layout (big-endian):
     *   Byte 0: Flow MSB (bits 7:4 = 0, bits 3:0 = flow[13:10])
     *   Byte 1: Flow[9:2]
     *   Byte 2: Temp MSB (bits 7:4 = temp[11:8], bits 3:0 = 0)
     *   Byte 3: Temp[7:0]
     *
     * Flow  = (byte0 & 0x0F) << 10 | (byte1 << 2) | (byte2 >> 4)
     * Temp  = ((byte2 & 0x0F) << 8) | byte3
     *
     * Scale: flow = raw / 16383.0  -> SLPM
     *        temp = raw / 4095.0   -> deg C
     */
    uint16_t flow_raw = ((uint16_t)(data[0] & 0x0F) << 10) |
                        ((uint16_t)data[1] << 2) |
                        ((uint16_t)data[2] >> 4);
    uint16_t temp_raw = ((uint16_t)(data[2] & 0x0F) << 8) |
                        (uint16_t)data[3];

    *flow = (float)flow_raw / 16383.0f;
    *temp = (float)temp_raw / 4095.0f;
}

/* ------------------------------------------------------------------ */
/* Log a measurement to the file                                       */
/* ------------------------------------------------------------------ */
static void log_data(float flow, float temp)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(g_log_file, "%s, Flow: %.2f SLPM, Temp: %.2f C\n",
            timestamp, flow, temp);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open log file ---------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[FATAL] fopen(" LOG_FILE ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- install signal handlers ----------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- initial I2C open ------------------------------------------- */
    if (init_i2c() != 0) {
        fprintf(stderr, "[FATAL] Cannot initialise I2C. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /*
     * HAFUHH0025PA3 power-up / first reads may return stale data.
     * Drain two samples to let the sensor settle.
     */
    uint8_t dummy[4];
    if (read_sensor_data(dummy) != 0) {
        fprintf(stderr, "[WARN] Initial read failed; continuing.\n");
    }
    time_sleep(SAMPLE_PERIOD);
    if (read_sensor_data(dummy) != 0) {
        fprintf(stderr, "[WARN] Second initial read failed; continuing.\n");
    }

    printf("HAFUHH0025PA3 flow logger started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* --- main sampling loop ----------------------------------------- */
    while (g_running) {
        uint8_t data[4];
        float flow, temp;

        if (read_sensor_data(data) == 0) {
            parse_data(data, &flow, &temp);
            log_data(flow, temp);
            printf("Flow: %.2f SLPM, Temp: %.2f C\n", flow, temp);
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed; attempting re-init.\n");
            if (init_i2c() != 0) {
                fprintf(stderr, "[FATAL] Re-init failed. Exiting.\n");
                break;
            }
        }

        time_sleep(SAMPLE_PERIOD);
    }

    /* --- graceful shutdown ------------------------------------------ */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

