    /* --- install signal handlers ----------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* --- initial I2C open ------------------------------------------- */
    if (init_i2c() != 0) {
        fprintf(stderr, "[FATAL] Cannot initialise I2C. Exiting.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /*
     * HAFUHH0025PA3 power-up / first reads may return stale data.
     * Drain two samples to let the sensor settle.
     */
    uint8_t dummy[4];
    if (read_sensor_data(dummy) != 0) {
        fprintf(stderr, "[WARN] Initial read failed; continuing.\n");
    }
    time_sleep(SAMPLE_PERIOD);
    if (read_sensor_data(dummy) != 0) {
        fprintf(stderr, "[WARN] Second initial read failed; continuing.\n");
    }

    printf("HAFUHH0025PA3 flow logger started. Logging to %s\n", LOG_FILE);
    printf("Press Ctrl+C to stop.\n");

    /* --- main sampling loop ----------------------------------------- */
    while (g_running) {
        uint8_t data[4];
        float flow, temp;

        if (read_sensor_data(data) == 0) {
            parse_data(data, &flow, &temp);
            log_data(flow, temp);
            printf("Flow: %.2f SLPM, Temp: %.2f C\n", flow, temp);
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed; attempting re-init.\n");
            if (init_i2c() != 0) {
                fprintf(stderr, "[FATAL] Re-init failed. Exiting.\n");
                break;
            }
        }

        time_sleep(SAMPLE_PERIOD);
    }

    /* --- graceful shutdown ------------------------------------------ */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

