#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define DHT11_GPIO 4
#define DHT11_FILE "dht11_readings.txt"
#define DHT11_ERROR_FILE "dht11_errors.txt"
#define DHT11_TIMEOUT_US 1000000
#define DHT11_START_LOW_US 20000
#define DHT11_START_HIGH_US 40
#define DHT11_RESP_LOW_US 80
#define DHT11_RESP_HIGH_US 80
#define DHT11_BIT_LOW_US 50
#define DHT11_BIT_THRESHOLD_US 50
#define DHT11_SAMPLE_INTERVAL_S 2

#define DHT11_OK 0
#define DHT11_ERR_TIMEOUT 1
#define DHT11_ERR_CHECKSUM 2
#define DHT11_ERR_SENSOR_ABSENT 3
#define DHT11_ERR_GPIO 4

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_error(int code, const char *msg) {
    FILE *fp = fopen(DHT11_ERROR_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d, Code: %d, %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, code, msg);
    fclose(fp);
}

static int wait_for_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

static int read_dht11(int gpio, float *temp, float *hum) {
    uint8_t data[5] = {0};
    int i;

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 1);
    gpioDelay(500000);

    gpioWrite(gpio, 0);
    gpioDelay(DHT11_START_LOW_US);
    gpioWrite(gpio, 1);
    gpioDelay(30);

    gpioSetMode(gpio, PI_INPUT);
    gpioSetPullUpDown(gpio, PI_PUD_UP);

    if (wait_for_level(gpio, 0, DHT11_TIMEOUT_US) < 0) {
        log_error(DHT11_ERR_TIMEOUT, "Timeout waiting for response low");
        return DHT11_ERR_TIMEOUT;
    }
    if (wait_for_level(gpio, 1, DHT11_TIMEOUT_US) < 0) {
        log_error(DHT11_ERR_TIMEOUT, "Timeout waiting for response high");
        return DHT11_ERR_TIMEOUT;
    }
    if (wait_for_level(gpio, 0, DHT11_TIMEOUT_US) < 0) {
        log_error(DHT11_ERR_TIMEOUT, "Timeout waiting for data start");
        return DHT11_ERR_TIMEOUT;
    }

    for (i = 0; i < 40; i++) {
        if (wait_for_level(gpio, 1, DHT11_TIMEOUT_US) < 0) {
            log_error(DHT11_ERR_TIMEOUT, "Timeout waiting for bit high");
            return DHT11_ERR_TIMEOUT;
        }
        uint32_t start = gpioTick();
        if (wait_for_level(gpio, 0, DHT11_TIMEOUT_US) < 0) {
            log_error(DHT11_ERR_TIMEOUT, "Timeout waiting for bit low");
            return DHT11_ERR_TIMEOUT;
        }
        uint32_t duration = gpioTick() - start;
        data[i / 8] <<= 1;
        if (duration > DHT11_BIT_THRESHOLD_US) {
            data[i / 8] |= 1;
        }
    }

    uint8_t checksum = (uint8_t)(data[0] + data[1] + data[2] + data[3]);
    if (checksum != data[4]) {
        log_error(DHT11_ERR_CHECKSUM, "Checksum mismatch");
        return DHT11_ERR_CHECKSUM;
    }

    *hum = (float)data[0];
    *temp = (float)data[2];
    return DHT11_OK;
}

static void log_reading(float temp, float hum) {
    FILE *fp = fopen(DHT11_FILE, "a");
    if (!fp) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(fp, "%04d-%02d-%02dT%02d:%02d:%02d, Temp: %.1fC, Hum: %.1f%%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, temp, hum);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        log_error(DHT11_ERR_GPIO, "pigpio initialisation failed");
        return 1;
    }

    while (g_running) {
        float temp, hum;
        int rc = read_dht11(DHT11_GPIO, &temp, &hum);
        if (rc == DHT11_OK) {
            log_reading(temp, hum);
        }
        sleep(DHT11_SAMPLE_INTERVAL_S);
    }

    gpioTerminate();
    return 0;
}

