#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SHT31D_ADDR        0x44
#define MEASURE_CMD_HIGH   0x2C
#define MEASURE_CMD_LOW    0x06
#define MEASUREMENT_DELAY_US 20000   /* 20 ms (datasheet: typ 15 ms) */
#define LOG_INTERVAL_S     5
#define MAX_RETRIES        3
#define LOG_FILE_NAME      "sht31d_data.log"

static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* CRC-8 polynomial 0x31, initial value 0xFF (Sensirion SHT3x datasheet) */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

static int init_i2c(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, SHT31D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return -1;
    }
    return 0;
}

static int read_sht31d(float *temperature, float *humidity) {
    uint8_t cmd[2] = {MEASURE_CMD_HIGH, MEASURE_CMD_LOW};
    uint8_t buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int rc = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
        if (rc != 0) {
            fprintf(stderr, "Warning: i2cWriteDevice failed (rc=%d), retry %d/%d\n",
                    rc, retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        rc = i2cReadDevice(i2c_handle, (char *)buf, 6);
        if (rc != 6) {
            fprintf(stderr, "Warning: i2cReadDevice returned %d bytes, retry %d/%d\n",
                    rc, retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        /* Validate CRCs */
        if (crc8(buf, 2) != buf[2]) {
            fprintf(stderr, "Warning: temperature CRC mismatch, retry %d/%d\n",
                    retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }
        if (crc8(buf + 3, 2) != buf[5]) {
            fprintf(stderr, "Warning: humidity CRC mismatch, retry %d/%d\n",
                    retries + 1, MAX_RETRIES);
            retries++;
            gpioDelay(10000);
            continue;
        }

        uint16_t temp_raw = ((uint16_t)buf[0] << 8) | buf[1];
        uint16_t hum_raw  = ((uint16_t)buf[3] << 8) | buf[4];

        *temperature = -45.0f + (175.0f * (float)temp_raw / 65535.0f);
        *humidity    = 100.0f * (float)hum_raw / 65535.0f;

        return 0;
    }

    fprintf(stderr, "Error: SHT31-D read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

static int log_data(float temperature, float humidity) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, humidity) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }
    fflush(log_file);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (init_i2c() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    float temperature, humidity;

    while (!terminate) {
        if (read_sht31d(&temperature, &humidity) == 0) {
            if (log_data(temperature, humidity) != 0) {
                fprintf(stderr, "Error: failed to log data\n");
            }
        } else {
            time_t rawtime;
            struct tm timeinfo;
            char timestamp[32];
            time(&rawtime);
            localtime_r(&rawtime, &timeinfo);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);
            fprintf(stderr, "%s,ERROR: sensor read failed\n", timestamp);
        }

        /* Sleep in 1-second increments so signals are caught promptly */
        for (int i = 0; i < LOG_INTERVAL_S && !terminate; i++) {
            sleep(1);
        }
    }

    cleanup();
    return 0;
}

