/*
 * Raspberry Pi Zero W - Dual ADPD105 Photometric Front-End Reader
 * Computes average correlated color temperature (CCT) and logs to cct_log.csv.
 *
 * Hardware:
 *   - ADPD105 sensor 1: I2C bus 1, address 0x50
 *   - ADPD105 sensor 2: I2C bus 1, address 0x51
 *
 * Build: gcc -o cct_logger cct_logger.c -lm
 * Run:   sudo ./cct_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define I2C_BUS 1
#define ADPD105_ADDR_1 0x50
#define ADPD105_ADDR_2 0x51

#define ADPD105_REG_DATA_0 0x00
#define ADPD105_REG_DATA_1 0x01
#define ADPD105_REG_DATA_2 0x02
#define ADPD105_REG_DATA_3 0x03
#define ADPD105_REG_DATA_4 0x04
#define ADPD105_REG_DATA_5 0x05
#define ADPD105_REG_DATA_6 0x06
#define ADPD105_REG_DATA_7 0x07
#define ADPD105_REG_DATA_8 0x08
#define ADPD105_REG_DATA_9 0x09
#define ADPD105_REG_DATA_10 0x0A
#define ADPD105_REG_DATA_11 0x0B
#define ADPD105_REG_DATA_12 0x0C
#define ADPD105_REG_DATA_13 0x0D
#define ADPD105_REG_DATA_14 0x0E
#define ADPD105_REG_DATA_15 0x0F

#define ADPD105_REG_CONFIG 0x0F
#define ADPD105_REG_MODE 0x10

#define LOG_FILE "cct_log.csv"
#define SAMPLE_INTERVAL_SEC 1

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * Read a 16-bit word from the ADPD105.
 * pigpio's i2cReadWordData returns the data in the lower 16 bits of the int.
 * The ADPD105 is big-endian on the bus, so we swap bytes.
 */
static int read_adpd105_word(int handle, uint8_t reg, uint16_t *value) {
    int raw = i2cReadWordData(handle, reg);
    if (raw < 0) {
        return -1;
    }
    *value = ((raw & 0xFF00) >> 8) | ((raw & 0x00FF) << 8);
    return 0;
}

/*
 * Read a 32-bit double-word from the ADPD105.
 * We read 8 bytes starting at reg and assemble them into a uint32_t.
 */
static int read_adpd105_dword(int handle, uint8_t reg, uint32_t *value) {
    char buf[8];
    int bytes = i2cReadI2CBlockData(handle, reg, buf, 8);
    if (bytes != 8) {
        return -1;
    }
    *value = ((uint32_t)(uint8_t)buf[0] << 24) |
             ((uint32_t)(uint8_t)buf[1] << 16) |
             ((uint32_t)(uint8_t)buf[2] << 8)  |
             ((uint32_t)(uint8_t)buf[3]);
    return 0;
}

/*
 * Compute a mock correlated color temperature (CCT) from the 16-bit data words.
 * In a real application, this would involve the ADPD105's specific
 * photometric calculation algorithms.
 */
static double calculate_cct(uint16_t d0, uint16_t d1, uint16_t d2, uint16_t d3) {
    double sum = (double)d0 + (double)d1 + (double)d2 + (double)d3;
    if (sum == 0.0) {
        return 0.0;
    }
    return 1000.0 + (sum / 4.0) * 10.0;
}

static int log_cct(double cct) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return -1;
    }

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Average_CCT\n");
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f\n", timestamp, cct);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int handle1 = i2cOpen(I2C_BUS, ADPD105_ADDR_1, 0);
    if (handle1 < 0) {
        fprintf(stderr, "Error opening I2C device 1 (addr 0x%02X): %d\n", ADPD105_ADDR_1, handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int handle2 = i2cOpen(I2C_BUS, ADPD105_ADDR_2, 0);
    if (handle2 < 0) {
        fprintf(stderr, "Error opening I2C device 2 (addr 0x%02X): %d\n", ADPD105_ADDR_2, handle2);
        i2cClose(handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Minimal configuration: enable sensor, set mode */
    if (i2cWriteByteData(handle1, ADPD105_REG_MODE, 0x01) < 0) {
        fprintf(stderr, "Error writing to I2C device 1 (addr 0x%02X)\n", ADPD105_ADDR_1);
    }
    if (i2cWriteByteData(handle2, ADPD105_REG_MODE, 0x01) < 0) {
        fprintf(stderr, "Error writing to I2C device 2 (addr 0x%02X)\n", ADPD105_ADDR_2);
    }

    while (running) {
        uint16_t d0, d1, d2, d3;
        uint32_t dword1, dword2;

        if (read_adpd105_word(handle1, ADPD105_REG_DATA_0, &d0) < 0 ||
            read_adpd105_word(handle1, ADPD105_REG_DATA_1, &d1) < 0 ||
            read_adpd105_word(handle1, ADPD105_REG_DATA_2, &d2) < 0 ||
            read_adpd105_word(handle1, ADPD105_REG_DATA_3, &d3) < 0) {
            fprintf(stderr, "Error reading data from sensor 1\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        if (read_adpd105_dword(handle1, ADPD105_REG_DATA_4, &dword1) < 0 ||
            read_adpd105_dword(handle2, ADPD105_REG_DATA_4, &dword2) < 0) {
            fprintf(stderr, "Error reading extended data from sensors\n");
            sleep(SAMPLE_INTERVAL_SEC);
            continue;
        }

        double cct1 = calculate_cct(d0, d1, d2, d3);
        double cct2 = calculate_cct((uint16_t)dword1, (uint16_t)(dword1 >> 16),
                                    (uint16_t)dword2, (uint16_t)(dword2 >> 16));

        double average_cct = (cct1 + cct2) / 2.0;

        if (log_cct(average_cct) < 0) {
            fprintf(stderr, "Error logging CCT value\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    i2cClose(handle1);
    i2cClose(handle2);
    gpioTerminate();

    return EXIT_SUCCESS;
}

