static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Write a 16-bit value to a 16-bit-addressed register.
 * Returns 0 on success, -1 on failure.
 */
static int mlx_write_reg16(int handle, uint16_t reg, uint16_t value)
{
    char buf[4];
    buf[0] = (char)((reg >> 8) & 0xFF);
    buf[1] = (char)(reg & 0xFF);
    buf[2] = (char)((value >> 8) & 0xFF);
    buf[3] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 4) != 4) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(reg=0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit value from a 16-bit-addressed register.
 * Returns 0 on success and stores the value in *out; -1 on failure.
 */
static int mlx_read_reg16(int handle, uint16_t reg, uint16_t *out)
{
    char addr[2];
    char data[2];

    addr[0] = (char)((reg >> 8) & 0xFF);
    addr[1] = (char)(reg & 0xFF);

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice(addr=0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice(reg=0x%04X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/*
 * Read pressure and temperature.
 * Returns 0 on success and fills *pressure (Pa) and *temperature (°C);
 * -1 on failure.
 */
static int mlx90824_read(int handle, float *pressure, float *temperature)
{
    uint16_t raw_pressure, raw_temperature;

    if (mlx_read_reg16(handle, REG_PRESSURE_MSB, &raw_pressure) != 0)
        return -1;

    if (mlx_read_reg16(handle, REG_TEMP_MSB, &raw_temperature) != 0)
        return -1;

    /*
     * Convert raw 16-bit values to physical units.
     * (The exact formulas depend on the sensor's calibration data;
     *  the constants below are placeholders for the MLX90824.)
     */
    *pressure    = (float)raw_pressure    * 0.1f;   /* Pa  */
    *temperature = (float)raw_temperature * 0.01f;  /* °C  */

    return 0;
}

/*
 * Append a timestamped line to the log file.
 * Returns 0 on success, -1 on failure.
 */
static int log_line(const char *line)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "[ERROR] time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "[ERROR] localtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "[ERROR] strftime() failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s %s\n", ts, line) < 0) {
        fprintf(stderr, "[ERROR] fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "[ERROR] fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- open I2C --------------------------------------------------- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %s\n",
                I2C_BUS, I2C_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- open log file ---------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] fopen(%s) failed: %s\n",
                LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signals ---------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed: %s\n", strerror(errno));
    }

    printf("MLX90824 logging started. Press Ctrl+C to stop.\n");

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        float pressure, temperature;

        if (mlx90824_read(g_i2c_handle, &pressure, &temperature) == 0) {
            char line[128];
            snprintf(line, sizeof(line),
                     "Pressure: %.2f Pa, Temperature: %.2f C",
                     pressure, temperature);
            if (log_line(line) != 0) {
                fprintf(stderr, "[ERROR] Failed to log data\n");
            }
        } else {
            fprintf(stderr, "[ERROR] Sensor read failed; logging error\n");
            if (log_line("ERROR: sensor read failed") != 0) {
                fprintf(stderr, "[ERROR] Failed to log error line\n");
            }
        }

        /* Sleep in 100 ms increments so signals are caught promptly. */
        for (int i = 0; i < (int)(READ_INTERVAL * 10.0) && g_running; i++) {
            time_sleep(0.1);
        }
    }

    /* --- graceful shutdown ----------------------------------------- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

