#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LM75B_ADDR        0x48
#define LM75B_TEMP_REG    0x00
#define FAN_GPIO          18
#define BUFFER_SIZE       60
#define TEMP_THRESHOLD_ON  28.0f
#define TEMP_THRESHOLD_OFF 26.0f
#define SAMPLE_INTERVAL_S  1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_temperature(int i2c_handle, float *temperature) {
    char buf[2];
    int rc = i2cReadI2CBlockData(i2c_handle, LM75B_TEMP_REG, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "Error reading temperature register (rc=%d)\n", rc);
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    raw >>= 5;
    *temperature = (float)raw * 0.125f;
    return 0;
}

static void control_fan(float avg_temp) {
    static bool fan_on = false;
    if (avg_temp > TEMP_THRESHOLD_ON && !fan_on) {
        if (gpioWrite(FAN_GPIO, 1) == 0) {
            fan_on = true;
            printf("Fan ON (avg=%.2f C)\n", avg_temp);
        } else {
            fprintf(stderr, "Error turning fan ON\n");
        }
    } else if (avg_temp < TEMP_THRESHOLD_OFF && fan_on) {
        if (gpioWrite(FAN_GPIO, 0) == 0) {
            fan_on = false;
            printf("Fan OFF (avg=%.2f C)\n", avg_temp);
        } else {
            fprintf(stderr, "Error turning fan OFF\n");
        }
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(FAN_GPIO, 0);

    int i2c_handle = i2cOpen(1, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at addr 0x%02X (rc=%d)\n", LM75B_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    float temp_buffer[BUFFER_SIZE];
    int buffer_index = 0;
    int buffer_count = 0;

    while (g_running) {
        float temperature;
        if (read_temperature(i2c_handle, &temperature) == 0) {
            temp_buffer[buffer_index] = temperature;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;
            if (buffer_count < BUFFER_SIZE) buffer_count++;

            float sum = 0.0f;
            for (int i = 0; i < buffer_count; i++) sum += temp_buffer[i];
            float avg = sum / (float)buffer_count;

            printf("Temperature: %.2f C, Average: %.2f C\n", temperature, avg);
            control_fan(avg);
        } else {
            fprintf(stderr, "Failed to read temperature, retrying next cycle\n");
        }
        sleep(SAMPLE_INTERVAL_S);
    }

    gpioWrite(FAN_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

