#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define STTS2004_ADDR  0x4A
#define STTS2004_TEMP  0x02
#define STTS2004_CTRL  0x04
#define STTS2004_CTRL_PD 0x01

#define GPIO_LED       17
#define TEMP_HIGH      28.0f
#define TEMP_LOW       27.0f
#define POLL_DELAY_US  1000000

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int read_temperature(int fd, float *temp_c) {
    uint8_t msb, lsb;
    if (i2c_read_reg8(fd, STTS2004_TEMP, &msb) != 0) return -1;
    if (i2c_read_reg8(fd, STTS2004_TEMP + 1, &lsb) != 0) return -1;

    int16_t raw = (int16_t)((msb << 8) | lsb);
    raw >>= 4;
    *temp_c = (float)raw * 0.0625f;
    return 0;
}

static int control_led(int gpio, bool on) {
    if (gpioWrite(gpio, on ? 1 : 0) != 0) {
        fprintf(stderr, "Failed to write GPIO %d: %s\n", gpio, strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(fd, I2C_SLAVE, STTS2004_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", STTS2004_ADDR, strerror(errno));
        close(fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (i2c_write_reg8(fd, STTS2004_CTRL, STTS2004_CTRL_PD) != 0) {
        fprintf(stderr, "Failed to power on STTS2004\n");
        close(fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_LED, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GPIO_LED);
        close(fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (control_led(GPIO_LED, false) != 0) {
        close(fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    bool led_on = false;
    int consecutive_errors = 0;

    while (g_running) {
        float temp;
        if (read_temperature(fd, &temp) == 0) {
            consecutive_errors = 0;
            printf("Temperature: %.2f C\n", temp);
            fflush(stdout);

            if (temp > TEMP_HIGH && !led_on) {
                if (control_led(GPIO_LED, true) == 0) led_on = true;
            } else if (temp < TEMP_LOW && led_on) {
                if (control_led(GPIO_LED, false) == 0) led_on = false;
            }
        } else {
            consecutive_errors++;
            fprintf(stderr, "Temperature read failed (consecutive: %d)\n", consecutive_errors);
            if (consecutive_errors >= 5) {
                fprintf(stderr, "Too many consecutive I2C errors, exiting.\n");
                break;
            }
        }
        usleep(POLL_DELAY_US);
    }

    control_led(GPIO_LED, false);
    close(fd);
    gpioTerminate();
    return EXIT_SUCCESS;
}

