#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x40
#define LOG_FILE       "environment.log"
#define MAX_RETRIES    3
#define SAMPLE_PERIOD  60          /* seconds between readings */
#define CONV_DELAY_US  25000       /* 25 ms conversion wait */

/* Si7021 command bytes (no register prefix) */
#define CMD_MEASURE_RH_NOHOLD   0xF5
#define CMD_MEASURE_TEMP_NOHOLD 0xF3
#define CMD_READ_TEMP_PREV_RH   0xE0
#define CMD_READ_ID_1           0xFA  /* electronic ID byte 0 */
#define CMD_READ_ID_2           0x0F  /* electronic ID byte 1 */
#define CMD_READ_FW_REV         0x84  /* firmware revision */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a single command byte to the Si7021 (no data payload).        */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int si7021_write_cmd(uint8_t cmd)
{
    int rc = i2cWriteByte(g_i2c_handle, cmd);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByte(0x%02X) failed: %d\n", cmd, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read `len` bytes from the Si7021 (no register address).             */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int si7021_read_bytes(uint8_t *buf, uint32_t len)
{
    int rc = i2cReadDevice(g_i2c_handle, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "[ERROR] i2cReadDevice expected %u, got %d\n", len, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 8-bit electronic ID (first two bytes of ID).               */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int si7021_read_id(uint8_t *id)
{
    if (si7021_write_cmd(CMD_READ_ID_1) != 0)
        return -1;
    if (si7021_write_cmd(CMD_READ_ID_2) != 0)
        return -1;
    uint8_t buf[2];
    if (si7021_read_bytes(buf, 2) != 0)
        return -1;
    id[0] = buf[0];
    id[1] = buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 8-bit firmware revision.                                  */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int si7021_read_fw_rev(uint8_t *rev)
{
    if (si7021_write_cmd(CMD_READ_FW_REV) != 0)
        return -1;
