#include <string.h>
#include <unistd.h>

#define HDC1080_ADDR 0x40
#define HDC1080_TEMP_REG 0x00
#define HDC1080_HUMID_REG 0x01
#define HDC1080_CONFIG_REG 0x02
#define HDC1080_RESET_CMD 0x80
#define HDC1080_CONFIG_MEASURE 0x10
#define HDC1080_CONFIG_MODE 0x01
#define HDC1080_CONFIG_TRES_14 0x00
#define HDC1080_CONFIG_HRES_14 0x00
#define HDC1080_CONV_TIME_US 25000
#define LOG_FILE "enviro_log.txt"
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int hdc1080_init(int handle) {
    if (i2cWriteByteData(handle, HDC1080_CONFIG_REG, HDC1080_RESET_CMD) < 0) {
        fprintf(stderr, "Error: Failed to reset HDC1080\n");
        return -1;
    }
    gpioDelay(15000);

    uint8_t config = HDC1080_CONFIG_TRES_14 | HDC1080_CONFIG_HRES_14 | HDC1080_CONFIG_MODE;
    if (i2cWriteByteData(handle, HDC1080_CONFIG_REG, config) < 0) {
        fprintf(stderr, "Error: Failed to configure HDC1080\n");
        return -1;
    }
    return 0;
}

static int hdc1080_read(int handle, float *temperature, float *humidity) {
    if (i2cWriteByteData(handle, HDC1080_CONFIG_REG, HDC1080_CONFIG_MEASURE) < 0) {
        fprintf(stderr, "Error: Failed to trigger measurement\n");
        return -1;
    }

    gpioDelay(HDC1080_CONV_TIME_US);

    char buf[4];
    if (i2cReadI2CBlockData(handle, HDC1080_TEMP_REG, buf, 4) != 4) {
        fprintf(stderr, "Error: Failed to read temperature/humidity data\n");
        return -1;
    }

    uint16_t raw_temp = ((uint16_t)(buf[0] & 0xFF) << 8) | (uint16_t)(buf[1] & 0xFF);
    uint16_t raw_hum = ((uint16_t)(buf[2] & 0xFF) << 8) | (uint16_t)(buf[3] & 0xFF);

    *temperature = ((float)raw_temp / 65536.0f) * 165.0f - 40.0f;
    *humidity = ((float)raw_hum / 65536.0f) * 100.0f;

    return 0;
}

static int log_data(const char *filename, float temperature, float humidity) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", filename);
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, temperature, humidity);
    fclose(fp);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(1, HDC1080_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (hdc1080_init(i2c_handle) < 0) {
        fprintf(stderr, "Error: HDC1080 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float temperature, humidity;

    while (running) {
        if (hdc1080_read(i2c_handle, &temperature, &humidity) == 0) {
            if (log_data(LOG_FILE, temperature, humidity) != 0) {
                fprintf(stderr, "Warning: Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed, skipping log entry\n");
        }

        for (int i = 0; i < SAMPLE_INTERVAL_S && running; i++) {
            gpioSleep(PI_TIME_RELATIVE, 1, 0);
        }
    }

    i2cClose(i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

