#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_DEVICE      "/dev/i2c-1"
#define STS40_ADDR      0x44
#define LOG_FILE        "temperature_log.txt"
#define SAMPLE_INTERVAL 5
#define CONVERSION_DELAY_MS 10

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* Sensirion CRC8: polynomial 0x31, init 0xFF, no final XOR */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_cmd(int fd, uint8_t cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        perror("I2C write command failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len)
{
    size_t total = 0;
    while (total < len) {
        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            perror("I2C read failed");
            return -1;
        }
        if (n == 0) {
            fprintf(stderr, "I2C read: unexpected EOF (sensor disconnected?)\n");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

static int read_temperature(int fd, float *temperature)
{
    uint8_t cmd = 0xF4;  /* high-resolution measurement, clock stretching disabled */
    uint8_t data[3];

    if (i2c_write_cmd(fd, cmd) < 0)
        return -1;

    usleep(CONVERSION_DELAY_MS * 1000);

    if (i2c_read_bytes(fd, data, sizeof(data)) < 0)
        return -1;

    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "CRC mismatch on temperature data\n");
        return -1;
    }

    int16_t raw = (int16_t)((data[0] << 8) | data[1]);
    *temperature = -45.0f + (175.0f * (float)raw) / 65535.0f;
    return 0;
}

static void log_temperature(FILE *fp, float temperature)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (fprintf(fp, "%s, %.2f\n", ts, temperature) < 0)
        perror("fprintf to log failed");
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open(" I2C_DEVICE ")");
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, STS40_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    while (g_running) {
        float temperature;
        if (read_temperature(g_i2c_fd, &temperature) == 0) {
            log_temperature(g_log_fp, temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Retrying in %d seconds.\n",
                    SAMPLE_INTERVAL);
        }
        sleep(SAMPLE_INTERVAL);
    }

    fprintf(stderr, "\nShutting down cleanly...\n");
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

