#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* SDP810-500Pa I2C address (ADDR pin tied to GND) */
#define SDP810_ADDR 0x25

/* SDP810 commands */
#define SDP810_CMD_TRIGGER_MEAS 0x362F
#define SDP810_CMD_READ_ID      0x3636
#define SDP810_CMD_SOFT_RESET   0x0006

/* CRC-8 parameters for Sensirion SDP810 (polynomial 0x31, init 0xFF) */
#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Function prototypes */
static uint8_t crc8(const uint8_t *data, int len);
static int sdp810_init(int handle);
static int sdp810_trigger_measurement(int handle);
static int sdp810_read_measurement(int handle, float *pressure, float *temperature);
static void log_data(FILE *fp, float pressure, float temperature);
static void log_error(FILE *fp, const char *message);
static void signal_handler(int signal);
static void cleanup(void);

/* CRC-8 calculation for Sensirion sensors */
static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLY;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

/* Initialize the SDP810 sensor */
static int sdp810_init(int handle) {
    /* Soft reset */
    if (i2cWriteWordData(handle, 0x00, SDP810_CMD_SOFT_RESET) < 0) {
        fprintf(stderr, "Error: Soft reset write failed\n");
        return -1;
    }
    gpioDelay(20000); /* 20 ms delay after reset */

    /* Read ID to verify sensor presence */
    int id = i2cReadWordData(handle, 0x00);
    if (id < 0) {
        fprintf(stderr, "Error: Failed to read sensor ID\n");
        return -1;
    }
    /* Swap bytes (pigpio returns little-endian, sensor expects big-endian) */
    uint8_t id_buf[2] = { (uint8_t)(id >> 8), (uint8_t)(id & 0xFF) };
    if (crc8(id_buf, 2) != 0) {
        fprintf(stderr, "Error: Sensor ID CRC mismatch\n");
        return -1;
    }
    printf("SDP810 initialized successfully (ID: 0x%02X%02X)\n", id_buf[0], id_buf[1]);
    return 0;
}

/* Trigger a measurement */
static int sdp810_trigger_measurement(int handle) {
    if (i2cWriteWordData(handle, 0x00, SDP810_CMD_TRIGGER_MEAS) < 0) {
        fprintf(stderr, "Error: Failed to trigger measurement\n");
        return -1;
    }
    gpioDelay(50000); /* 50 ms delay for measurement */
    return 0;
}

/* Read measurement data (9 bytes: pressure, temp, scale factor) */
static int sdp810_read_measurement(int handle, float *pressure, float *temperature) {
    char buffer[9];
    int bytes_read = i2cReadDevice(handle, buffer, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Error: Failed to read measurement data (read %d bytes)\n", bytes_read);
        return -1;
    }

    /* Validate CRC for pressure (bytes 0-1, CRC at byte 2) */
    if (crc8((uint8_t *)buffer, 2) != (uint8_t)buffer[2]) {
        fprintf(stderr, "Error: Pressure CRC mismatch\n");
        return -1;
    }

    /* Validate CRC for temperature (bytes 3-4, CRC at byte 5) */
    if (crc8((uint8_t *)(buffer + 3), 2) != (uint8_t)buffer[5]) {
        fprintf(stderr, "Error: Temperature CRC mismatch\n");
        return -1;
    }

    /* Validate CRC for scale factor (bytes 6-8, CRC at byte 8) */
    if (crc8((uint8_t *)(buffer + 6), 2) != (uint8_t)buffer[8]) {
        fprintf(stderr, "Error: Scale factor CRC mismatch\n");
        return -1;
    }

    /* Convert raw data to pressure and temperature */
    int16_t raw_pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_temperature = (int16_t)((buffer[3] << 8) | buffer[4]);

    /* Scale factor is used to convert raw values to physical units */
    int16_t scale_factor = (int16_t)((buffer[6] << 8) | buffer[7]);

    if (scale_factor == 0) {
        fprintf(stderr, "Error: Invalid scale factor (0)\n");
        return -1;
    }

    *pressure = (float)raw_pressure / scale_factor;
    *temperature = (float)raw_temperature / scale_factor;

    return 0;
}

/* Log data to file */
static void log_data(FILE *fp, float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, pressure, temperature);
    fflush(fp);
}

/* Log error to file */
static void log_error(FILE *fp, const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,ERROR,%s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(fp);
}

/* Signal handler for Ctrl+C */
static void signal_handler(int signal) {
    (void)signal;
    terminate = 1;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(1, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize SDP810 sensor */
    if (sdp810_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: SDP810 initialisation failed\n");
        cleanup();
        return 1;
    }

    /* Open log file */
    log_file = fopen("hvac_pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        cleanup();
        return 1;
    }

    /* Register signal handler */
    signal(SIGINT, signal_handler);

    float pressure, temperature;

    /* Main loop */
    while (!terminate) {
        /* Trigger measurement */
        if (sdp810_trigger_measurement(i2c_handle) != 0) {
            log_error(log_file, "Measurement trigger failed");
            gpioDelay(1000000); /* Wait 1 second before retrying */
            continue;
        }

        /* Read measurement data */
        if (sdp810_read_measurement(i2c_handle, &pressure, &temperature) == 0) {
            log_data(log_file, pressure, temperature);
        } else {
            log_error(log_file, "Measurement read failed");
        }

        gpioDelay(1000000); /* Wait 1 second */
    }

    /* Cleanup */
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

