    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C connection */
    i2c_handle = i2cOpen(1, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (%d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize SDP810 sensor */
    if (sdp810_init(i2c_handle) != 0) {
        fprintf(stderr, "Error: SDP810 initialisation failed\n");
        cleanup();
        return 1;
    }

    /* Open log file */
    log_file = fopen("hvac_pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        cleanup();
        return 1;
    }

    /* Register signal handler */
    signal(SIGINT, signal_handler);

    float pressure, temperature;

    /* Main loop */
    while (!terminate) {
        /* Trigger measurement */
        if (sdp810_trigger_measurement(i2c_handle) != 0) {
            log_error(log_file, "Measurement trigger failed");
            gpioDelay(1000000); /* Wait 1 second before retrying */
            continue;
        }

        /* Read measurement data */
        if (sdp810_read_measurement(i2c_handle, &pressure, &temperature) == 0) {
            log_data(log_file, pressure, temperature);
        } else {
            log_error(log_file, "Measurement read failed");
        }

        gpioDelay(1000000); /* Wait 1 second */
    }

    /* Cleanup */
    cleanup();
    printf("Program terminated gracefully.\n");
    return 0;
}

