#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <linux/i2c-dev.h>
#include <sys/ioctl.h>

#define SCD40_I2C_ADDR 0x62
#define I2C_BUS "/dev/i2c-1"
#define LOG_DIR "/var/log/scd40_data/"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"
#define BUFFER_SIZE 100
#define READ_INTERVAL_SEC 5
#define LOG_INTERVAL_SEC 60
#define MEASUREMENT_START_DELAY_SEC 1

#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86
#define CMD_READ_MEASUREMENT 0xEC05

#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

typedef struct {
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

typedef struct {
    sensor_data_t data[BUFFER_SIZE];
    int head;
    int tail;
    int count;
    pthread_mutex_t mutex;
} circular_buffer_t;

static int i2c_fd = -1;
static circular_buffer_t buffer;
static volatile sig_atomic_t running = 1;
static pthread_t logging_thread;

static void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (!fp) {
        perror("fopen error log");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INIT;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int i2c_write_cmd(uint16_t cmd) {
    uint8_t buf[2] = { (uint8_t)(cmd >> 8), (uint8_t)(cmd & 0xFF) };
    if (write(i2c_fd, buf, 2) != 2) {
        log_error("I2C write command failed");
        return -1;
    }
    return 0;
}

static int i2c_read_data(uint8_t *data, int len) {
    if (read(i2c_fd, data, len) != len) {
        log_error("I2C read data failed");
        return -1;
    }
    return 0;
}

static int scd40_start_periodic_measurement(void) {
    return i2c_write_cmd(CMD_START_PERIODIC_MEASUREMENT);
}

static int scd40_stop_periodic_measurement(void) {
    return i2c_write_cmd(CMD_STOP_PERIODIC_MEASUREMENT);
}

static int scd40_read_measurement(uint16_t *co2, float *temperature, float *humidity) {
    if (i2c_write_cmd(CMD_READ_MEASUREMENT) != 0) {
        return -1;
    }
    usleep(10000);

    uint8_t data[9];
    if (i2c_read_data(data, 9) != 0) {
        return -1;
    }

    if (crc8(&data[0], 2) != data[2]) {
        log_error("CRC check failed for CO2");
        return -1;
    }
    if (crc8(&data[3], 2) != data[5]) {
        log_error("CRC check failed for temperature");
        return -1;
    }
    if (crc8(&data[6], 2) != data[8]) {
        log_error("CRC check failed for humidity");
        return -1;
    }

    *co2 = (uint16_t)((data[0] << 8) | data[1]);
    uint16_t raw_temp = (uint16_t)((data[3] << 8) | data[4]);
    uint16_t raw_hum = (uint16_t)((data[6] << 8) | data[7]);

    *temperature = -45.0f + 175.0f * (float)raw_temp / 65535.0f;
    *humidity = 100.0f * (float)raw_hum / 65535.0f;

    return 0;
}

static void buffer_init(circular_buffer_t *buf) {
    buf->head = 0;
    buf->tail = 0;
    buf->count = 0;
    pthread_mutex_init(&buf->mutex, NULL);
}

static void buffer_add(circular_buffer_t *buf, sensor_data_t data) {
    pthread_mutex_lock(&buf->mutex);
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count == BUFFER_SIZE) {
        buf->tail = (buf->tail + 1) % BUFFER_SIZE;
    } else {
        buf->count++;
    }
    pthread_mutex_unlock(&buf->mutex);
}

static int buffer_get(circular_buffer_t *buf, int index, sensor_data_t *data) {
    pthread_mutex_lock(&buf->mutex);
    if (index < 0 || index >= buf->count) {
        pthread_mutex_unlock(&buf->mutex);
        return -1;
    }
    int actual_index = (buf->tail + index) % BUFFER_SIZE;
    *data = buf->data[actual_index];
    pthread_mutex_unlock(&buf->mutex);
    return 0;
}

static int buffer_size(circular_buffer_t *buf) {
    pthread_mutex_lock(&buf->mutex);
    int size = buf->count;
    pthread_mutex_unlock(&buf->mutex);
    return size;
}

static void buffer_flush(circular_buffer_t *buf, const char *filename) {
    int size = buffer_size(buf);
    if (size == 0) {
        return;
    }

    FILE *fp = fopen(filename, "a");
    if (!fp) {
        log_error("Failed to open CSV file for flushing");
        return;
    }

    for (int i = 0; i < size; i++) {
        sensor_data_t data;
        if (buffer_get(buf, i, &data) == 0) {
            fprintf(fp, "%u,%.2f,%.2f\n", data.co2, data.temperature, data.humidity);
        }
    }

    fclose(fp);

    pthread_mutex_lock(&buf->mutex);
    buf->head = 0;
    buf->tail = 0;
    buf->count = 0;
    pthread_mutex_unlock(&buf->mutex);
}

static void *logging_thread_func(void *arg) {
    (void)arg;
    while (running) {
        sleep(LOG_INTERVAL_SEC);
        if (!running) {
            break;
        }

        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char filename[256];
        snprintf(filename, sizeof(filename), "%sdata_%d-%02d-%02d_%02d-%02d-%02d.csv",
                 LOG_DIR, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                 tm.tm_hour, tm.tm_min, tm.tm_sec);

        struct stat st;
        if (stat(LOG_DIR, &st) == -1) {
            if (mkdir(LOG_DIR, 0755) == -1) {
                log_error("Failed to create log directory");
            }
        }

        buffer_flush(&buffer, filename);
    }
    return NULL;
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    buffer_init(&buffer);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SCD40_I2C_ADDR) < 0) {
        log_error("Failed to acquire I2C bus access");
        close(i2c_fd);
        return 1;
    }

    if (scd40_start_periodic_measurement() != 0) {
        log_error("Failed to start periodic measurement");
        close(i2c_fd);
        return 1;
    }

    sleep(MEASUREMENT_START_DELAY_SEC);

    if (pthread_create(&logging_thread, NULL, logging_thread_func, NULL) != 0) {
        log_error("Failed to create logging thread");
        scd40_stop_periodic_measurement();
        close(i2c_fd);
        return 1;
    }

    while (running) {
        uint16_t co2;
        float temperature, humidity;

        if (scd40_read_measurement(&co2, &temperature, &humidity) == 0) {
            sensor_data_t data = { co2, temperature, humidity };
            buffer_add(&buffer, data);
        } else {
            log_error("Failed to read sensor data");
        }

        sleep(READ_INTERVAL_SEC);
    }

    scd40_stop_periodic_measurement();
    pthread_join(logging_thread, NULL);

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char final_filename[256];
    snprintf(final_filename, sizeof(final_filename), "%sdata_%d-%02d-%02d_%02d-%02d-%02d.csv",
             LOG_DIR, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
             tm.tm_hour, tm.tm_min, tm.tm_sec);
    buffer_flush(&buffer, final_filename);

    close(i2c_fd);
    pthread_mutex_destroy(&buffer.mutex);

    return 0;
}

