/*
 * SDP810-500Pa differential pressure logger for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   SDP810 SDA  -> GPIO2 (I2C bus 1 SDA, pin 3)
 *   SDP810 SCL  -> GPIO3 (I2C bus 1 SCL, pin 5)
 *   SDP810 VDD  -> 3.3 V (pin 1)
 *   SDP810 GND  -> GND  (pin 6)
 *
 * Build:  gcc -O2 -Wall -o sdp810_logger sdp810_logger.c -lpigpio -lrt
 * Run:    sudo ./sdp810_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP810_ADDR    0x25
#define LOG_FILE       "sdp810_log.txt"
#define SAMPLE_PERIOD  1.0   /* seconds */
#define MEAS_DELAY     0.045 /* seconds (45 ms) */

/* SDP810-500Pa trigger command (mass flow / differential pressure mode) */
static const uint8_t TRIGGER_CMD[2] = {0x36, 0x2F};

/* CRC-8 parameters per Sensirion SDP8xx datasheet */
#define CRC8_POLY 0x31
#define CRC8_INIT 0xFF

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion style: poly 0x31, init 0xFF, no final XOR)         */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLY);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte sample from the SDP810                              */
/* ------------------------------------------------------------------ */
static int read_sdp810(int handle, float *pressure, float *temperature)
{
    uint8_t buf[9];
    int16_t raw_pressure, raw_temperature;
    int16_t scale_factor;

    /* Trigger a single-shot measurement */
    if (i2cWriteDevice(handle, (char *)TRIGGER_CMD, 2) != 0) {
        fprintf(stderr, "[ERROR] I2C write (trigger) failed\n");
        return -1;
    }

    /* Wait for conversion to complete (>= 45 ms) */
    time_sleep(MEAS_DELAY);

    /* Read 9 bytes: pressure(2)+crc, temperature(2)+crc, scale(2)+crc */
    if (i2cReadDevice(handle, (char *)buf, 9) != 9) {
        fprintf(stderr, "[ERROR] I2C read failed\n");
        return -1;
    }

    /* CRC validation */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] Scale-factor CRC mismatch\n");
        return -1;
    }

    raw_pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    raw_temperature = (int16_t)((buf[3] << 8) | buf[4]);
    scale_factor    = (int16_t)((buf[6] << 8) | buf[7]);

    /*
     * SDP8xx conversion formulas (from datasheet):
