     * SDP8xx conversion formulas (from datasheet):
     *   pressure [Pa] = raw_pressure / scale_factor
     *   temperature [°C] = raw_temperature / scale_factor
     * The scale factor is typically 240 for the SDP810-500Pa.
     */
    if (scale_factor == 0) {
        fprintf(stderr, "[ERROR] Scale factor is zero, cannot convert\n");
        return -1;
    }

    *pressure    = (float)raw_pressure    / (float)scale_factor;
    *temperature = (float)raw_temperature / (float)scale_factor;

    return 0;
}

