#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ICP-10110 I2C address (7-bit) */
#define ICP10110_ADDR 0x28

/* ICP-10110 register addresses */
#define ICP10110_REG_PRESSURE_MSB 0x00
#define ICP10110_REG_TEMPERATURE_MSB 0x02
#define ICP10110_REG_MEAS_CONFIG 0x04
#define ICP10110_REG_PRODUCT_ID 0x0F

/* Measurement configuration: continuous mode, 100 Hz ODR */
#define ICP10110_MEAS_CONFIG_VALUE 0x00

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int init_icp10110(void);
static int read_icp10110(float *pressure, float *temperature);
static void log_data(float pressure, float temperature);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

/* Initialize the ICP-10110 sensor */
static int init_icp10110(void) {
    /* Verify product ID to ensure sensor is present */
    int product_id = i2cReadByteData(i2c_handle, ICP10110_REG_PRODUCT_ID);
    if (product_id < 0) {
        fprintf(stderr, "Error reading product ID: %d\n", product_id);
        return -1;
    }
    if (product_id != 0x10) {
        fprintf(stderr, "Unexpected product ID: 0x%02X (expected 0x10)\n", product_id);
        return -1;
    }

    /* Configure measurement: continuous mode, 100 Hz */
    if (i2cWriteByteData(i2c_handle, ICP10110_REG_MEAS_CONFIG, ICP10110_MEAS_CONFIG_VALUE) < 0) {
        fprintf(stderr, "Error writing measurement configuration\n");
        return -1;
    }

    /* Wait for first measurement to be ready (10 ms for 100 Hz) */
    gpioDelay(10000); /* 10 ms in microseconds */

    return 0;
}

/* Read pressure and temperature from the ICP-10110 sensor */
static int read_icp10110(float *pressure, float *temperature) {
    char buffer[4];
    int result;

    /* Read 4 bytes starting from PRESSURE_MSB (0x00) */
    result = i2cReadI2CBlockData(i2c_handle, ICP10110_REG_PRESSURE_MSB, buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    /* Parse raw values (big-endian) */
    uint32_t raw_pressure = ((uint32_t)(uint8_t)buffer[0] << 16) |
                            ((uint32_t)(uint8_t)buffer[1] << 8)  |
                            ((uint32_t)(uint8_t)buffer[2]);
    uint32_t raw_temperature = ((uint32_t)(uint8_t)buffer[3] << 16) |
                               ((uint32_t)(uint8_t)buffer[4] << 8)  |
                               ((uint32_t)(uint8_t)buffer[5]);

    /* Convert to physical units */
    *pressure = (float)raw_pressure / 100.0f; /* hPa */
    *temperature = (float)raw_temperature / 100.0f; /* °C */

    return 0;
}

/* Log data to file and stdout */
static void log_data(float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(fp);

    printf("%s,%.2f,%.2f\n", timestamp, pressure, temperature);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 (default for Raspberry Pi 4) */
    i2c_handle = i2cOpen(1, ICP10110_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize the sensor */
    if (init_icp10110() < 0) {
        fprintf(stderr, "ICP-10110 initialization failed\n");
        cleanup();
        return 1;
    }

    /* Open the log file in append mode */
    fp = fopen("environmental_data.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float pressure, temperature;

    /* Main loop */
    while (program_running) {
        /* Read sensor data */
        if (read_icp10110(&pressure, &temperature) == 0) {
            /* Log the data */
            log_data(pressure, temperature);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping sample\n");
        }

        /* Wait 5 seconds (100 ms intervals for responsive shutdown) */
        for (int i = 0; i < 50 && program_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }
    }

    /* Cleanup */
    cleanup();

    return 0;
}

