#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define FAN_GPIO 18
#define TEMP_THRESHOLD_ON 30.0
#define TEMP_THRESHOLD_OFF 28.0
#define LOG_FILE "temperature_log.txt"
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_US 10000
#define POLL_DELAY_US 2000000

#define MLX90614_RAWIR1 0x04
#define MLX90614_RAWIR2 0x05
#define MLX90614_TA 0x06
#define MLX90614_TOBJ1 0x07
#define MLX90614_TOBJ2 0x08

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_mlx90614_temp(int handle, float *ambient, float *object) {
    int retries = I2C_RETRIES;
    int raw_ir1, raw_ir2, raw_ta, raw_tobj1, raw_tobj2;

    while (retries > 0) {
        raw_ir1 = i2cReadWordData(handle, MLX90614_RAWIR1);
        raw_ir2 = i2cReadWordData(handle, MLX90614_RAWIR2);
        raw_ta = i2cReadWordData(handle, MLX90614_TA);
        raw_tobj1 = i2cReadWordData(handle, MLX90614_TOBJ1);
        raw_tobj2 = i2cReadWordData(handle, MLX90614_TOBJ2);

        if (raw_ir1 >= 0 && raw_ir2 >= 0 && raw_ta >= 0 && raw_tobj1 >= 0 && raw_tobj2 >= 0) {
            *ambient = (float)raw_ta * 0.02 - 273.15;
            *object = (float)raw_tobj1 * 0.02 - 273.15;
            return 0;
        }

        fprintf(stderr, "I2C read error (ambient/object). Retrying...\n");
        gpioDelay(I2C_RETRY_DELAY_US);
        retries--;
    }

    fprintf(stderr, "I2C read failed after %d retries.\n", I2C_RETRIES);
    return -1;
}

static void log_temperature(float ambient, float object) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Ambient: %.2f C, Object: %.2f C\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, ambient, object);
    fclose(fp);
}

static void control_fan(float object_temp) {
    static int fan_on = 0;

    if (object_temp > TEMP_THRESHOLD_ON && !fan_on) {
        gpioWrite(FAN_GPIO, 1);
        fan_on = 1;
        printf("Fan ON (Object: %.2f C)\n", object_temp);
    } else if (object_temp < TEMP_THRESHOLD_OFF && fan_on) {
        gpioWrite(FAN_GPIO, 0);
        fan_on = 0;
        printf("Fan OFF (Object: %.2f C)\n", object_temp);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    float ambient_temp, object_temp;

    while (running) {
        if (read_mlx90614_temp(i2c_handle, &ambient_temp, &object_temp) == 0) {
            log_temperature(ambient_temp, object_temp);
            control_fan(object_temp);
        } else {
            fprintf(stderr, "Skipping logging due to read failure.\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    gpioWrite(FAN_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

