#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define PORT 8080
#define MAX_RETRIES 3
#define MEASUREMENT_DELAY_US 10000
#define POLL_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static int server_fd = -1;

typedef struct {
    float temperature;
    float humidity;
    int valid;
} sensor_data_t;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_i2c(void) {
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at addr 0x%02X: %s\n", SHT40_ADDR, pigpio_error(i2c_handle));
        return -1;
    }
    return 0;
}

static sensor_data_t read_sht40(void) {
    sensor_data_t data = {0.0f, 0.0f, 0};
    char cmd = MEASURE_CMD;
    char buf[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, &cmd, 1) != 0) {
            fprintf(stderr, "I2C write error (attempt %d/%d): %s\n", retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            gpioDelay(100000);
            continue;
        }

        gpioDelay(MEASUREMENT_DELAY_US);

        if (i2cReadDevice(i2c_handle, buf, 6) != 6) {
            fprintf(stderr, "I2C read error (attempt %d/%d): %s\n", retries + 1, MAX_RETRIES, strerror(errno));
            retries++;
            gpioDelay(100000);
            continue;
        }

        unsigned short temp_ticks = (buf[0] << 8) | buf[1];
        unsigned short hum_ticks = (buf[3] << 8) | buf[4];

        data.temperature = -45.0f + 175.0f * (float)temp_ticks / 65535.0f;
        data.humidity = 100.0f * (float)hum_ticks / 65535.0f;

        if (data.humidity < 0.0f) data.humidity = 0.0f;
        if (data.humidity > 100.0f) data.humidity = 100.0f;

        data.valid = 1;
        return data;
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries.\n", MAX_RETRIES);
    return data;
}

static void send_http_response(int client_fd, const char *html) {
    char header[256];
    int len = snprintf(header, sizeof(header),
        "HTTP/1.1 200 OK\r\n"
        "Content-Type: text/html\r\n"
        "Content-Length: %zu\r\n"
        "Connection: close\r\n"
        "\r\n", strlen(html));
    if (len > 0) {
        send(client_fd, header, (size_t)len, 0);
    }
    send(client_fd, html, strlen(html), 0);
}

static void handle_client(int client_fd) {
    char buffer[1024];
    ssize_t bytes = recv(client_fd, buffer, sizeof(buffer) - 1, 0);
    if (bytes > 0) {
        buffer[bytes] = '\0';
        sensor_data_t sd = read_sht40();
        char html[512];
        if (sd.valid) {
            snprintf(html, sizeof(html),
                "<!DOCTYPE html><html><head><title>SHT40</title><meta http-equiv=\"refresh\" content=\"5\"></head>"
                "<body><h1>SHT40 Sensor Data</h1><p>Temperature: %.2f &deg;C</p><p>Humidity: %.2f %%</p></body></html>",
                sd.temperature, sd.humidity);
        } else {
            snprintf(html, sizeof(html),
                "<!DOCTYPE html><html><head><title>SHT40</title><meta http-equiv=\"refresh\" content=\"5\"></head>"
                "<body><h1>SHT40 Sensor Data</h1><p>Error reading sensor data.</p></body></html>");
        }
        send_http_response(client_fd, html);
    }
    close(client_fd);
}

static int setup_server(void) {
    struct sockaddr_in address;
    int opt = 1;

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        perror("socket failed");
        return -1;
    }

    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        perror("setsockopt failed");
        close(server_fd);
        server_fd = -1;
        return -1;
    }

    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        close(server_fd);
        server_fd = -1;
        return -1;
    }

    if (listen(server_fd, 3) < 0) {
        perror("listen failed");
        close(server_fd);
        server_fd = -1;
        return -1;
    }

    printf("Server listening on port %d\n", PORT);
    return 0;
}

static void cleanup(void) {
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    if (setup_server() != 0) {
        cleanup();
        return 1;
    }

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t addrlen = sizeof(client_addr);
        int client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &addrlen);
        if (client_fd < 0) {
            if (errno == EINTR) continue;
            perror("accept failed");
            continue;
        }
        handle_client(client_fd);
    }

    cleanup();
    return 0;
}

