#define HDC2010_ADDR        0x40    /* 7-bit I2C address */
#define HDC2010_BUS         1       /* I2C bus 1 on Pi Zero W */

#define REG_TEMP_LOW        0x00
#define REG_TEMP_HIGH       0x01
#define REG_HUM_LOW         0x02
#define REG_HUM_HIGH        0x03
#define REG_MEAS_CONFIG     0x0E
#define REG_INT_CONFIG      0x0F
#define REG_MANUFACTURER_ID 0xFE
#define REG_DEVICE_ID       0xFF

#define HDC2010_MANUFACTURER_ID 0x5449  /* 'TI' */
#define HDC2010_DEVICE_ID       0x2010  /* HDC2010 */

/* MEASUREMENT_CONFIG (0x0E) bit layout */
#define MEAS_CONFIG_START     0x01    /* bit 0: START bit */
#define MEAS_CONFIG_MODE_TEMP 0x00    /* bits 1:0 = 00 -> temp + humidity */
#define MEAS_CONFIG_MODE_HUM  0x01    /* bits 1:0 = 01 -> humidity only */
#define MEAS_CONFIG_MODE_BOTH 0x02    /* bits 1:0 = 10 -> temp + humidity */
#define MEAS_CONFIG_TRIGGER   0x04    /* bit 2: trigger measurement */
#define MEAS_CONFIG_RESET     0x80    /* bit 7: software reset */

/* ---- Globals ---- */
static int g_i2c_handle = -1;
static volatile sig_atomic_t g_terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/* ---- Low-level I2C helpers ---- */
static int i2c_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 2);
    if (rc != 2) {
        fprintf(stderr, "I2C read failed for reg 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    *out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static int i2c_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[2];
    buf[0] = (char)((value >> 8) & 0xFF);
    buf[1] = (char)(value & 0xFF);
    int rc = i2cWriteI2CBlockData(handle, reg, buf, 2);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed for reg 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int handle, uint8_t reg, uint8_t *out)
{
    char buf[1];
    int rc = i2cReadI2CBlockData(handle, reg, buf, 1);
    if (rc != 1) {
        fprintf(stderr, "I2C read8 failed for reg 0x%02X (rc=%d)\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)buf[0];
    return 0;
}

/* ---- Sensor identification ---- */
static int verify_sensor(int handle)
{
    uint16_t manuf_id = 0, device_id = 0;

    if (i2c_read_reg16(handle, REG_MANUFACTURER_ID, &manuf_id) != 0)
        return -1;
    if (i2c_read_reg16(handle, REG_DEVICE_ID, &device_id) != 0)
        return -1;

    if (manuf_id != HDC2010_MANUFACTURER_ID) {
        fprintf(stderr, "Manufacturer ID mismatch: 0x%04X (expected 0x%04X)\n",
                manuf_id, HDC2010_MANUFACTURER_ID);
        return -1;
    }
    if (device_id != HDC2010_DEVICE_ID) {
        fprintf(stderr, "Device ID mismatch: 0x%04X (expected 0x%04X)\n",
                device_id, HDC2010_DEVICE_ID);
        return -1;
    }

    printf("HDC2010 detected: Manufacturer=0x%04X, Device=0x%04X\n",
           manuf_id, device_id);
    return 0;
}

/* ---- Trigger a measurement and wait for completion ---- */
static int trigger_measurement(int handle)
{
    uint16_t meas_cfg = 0;

    /* Read current config so we can set START bit and trigger */
    if (i2c_read_reg16(handle, REG_MEAS_CONFIG, &meas_cfg) != 0)
        return -1;

    meas_cfg |= MEAS_CONFIG_START | MEAS_CONFIG_TRIGGER;
    if (i2c_write_reg16(handle, REG_MEAS_CONFIG, meas_cfg) != 0)
        return -1;

    /* Poll MEASUREMENT_CONFIG bit 0 until it clears (measurement done) */
    for (int i = 0; i < 500; i++) {
        if (i2c_read_reg16(handle, REG_MEAS_CONFIG, &meas_cfg) != 0)
            return -1;
        if ((meas_cfg & MEAS_CONFIG_START) == 0)
            return 0;
        gpioDelay(1000); /* 1 ms */
    }

    fprintf(stderr, "Measurement timeout (config register stuck set)\n");
    return -1;
}

/* ---- Read temperature and humidity ---- */
static int read_hdc2010(int handle, float *temperature, float *humidity)
{
    uint16_t temp_raw = 0, hum_raw = 0;

    if (trigger_measurement(handle) != 0)
        return -1;

    if (i2c_read_reg16(handle, REG_TEMP_LOW, &temp_raw) != 0)
        return -1;
    if (i2c_read_reg16(handle, REG_HUM_LOW, &hum_raw) != 0)
        return -1;

    *temperature = ((float)temp_raw / 65536.0f) * 165.0f - 40.0f;
    *humidity    = ((float)hum_raw  / 65536.0f) * 100.0f;

    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    float temperature = 0.0f, humidity = 0.0f;
    int consecutive_errors = 0;
    const int max_consecutive_errors = 10;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(HDC2010_BUS, HDC2010_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at addr 0x%02X (rc=%d)\n",
                HDC2010_BUS, HDC2010_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify sensor identity */
    if (verify_sensor(g_i2c_handle) != 0) {
        fprintf(stderr, "HDC2010 not detected on bus %d at addr 0x%02X\n",
                HDC2010_BUS, HDC2010_ADDR);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("HDC2010 reader started. Press Ctrl+C to exit.\n");

    while (!g_terminate) {
        if (read_hdc2010(g_i2c_handle, &temperature, &humidity) == 0) {
            printf("Temperature: %.2f C, Humidity: %.2f %%\n",
                   temperature, humidity);
            consecutive_errors = 0;
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read failed (consecutive=%d/%d)\n",
                    consecutive_errors, max_consecutive_errors);
            if (consecutive_errors >= max_consecutive_errors) {
                fprintf(stderr, "Max consecutive errors reached, aborting.\n");
                break;
            }
        }

        /* Sleep 5 seconds, but wake early if a signal arrives */
        for (int i = 0; i < 50 && !g_terminate; i++)
            gpioDelay(100000); /* 100 ms */
    }

    cleanup();
    printf("Program terminated gracefully.\n");
    return EXIT_SUCCESS;
}

