/*
 * Raspberry Pi 3 Model B+ - Sensirion SDP800-500Pa differential pressure reader
 *
 * Wiring:
 *   SDP800 SDA  -> GPIO2 (pin 3, I2C bus 1)
 *   SDP800 SCL  -> GPIO3 (pin 5, I2C bus 1)
 *   SDP800 VDD  -> 3.3 V
 *   SDP800 GND  -> GND
 *
 * I2C address: 0x25 (7-bit)
 *
 * Build:  gcc -O2 -Wall -o sdp800 sdp800.c -lpigpio -lrt
 * Run:    sudo ./sdp800
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <signal.h>
#include <pigpio.h>

#define I2C_BUS        1
#define SDP800_ADDR    0x25
#define READ_INTERVAL  500000          /* microseconds (500 ms) */
#define MEAS_DELAY     45000           /* microseconds (45 ms)  */

/* SDP800-500Pa: continuous measurement, no averaging */
static const uint8_t CMD_CONT_MEAS[2] = {0x36, 0x2F};

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* CRC-8 (Sensirion polynomial 0x31, init 0xFF)                        */
/* ------------------------------------------------------------------ */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read one 9-byte measurement frame and validate CRCs                 */
/* ------------------------------------------------------------------ */
static int read_sdp800(int handle, int16_t *pressure, int16_t *temperature)
{
    uint8_t buf[9];
    int n;

    /* Send continuous-measurement command */
    n = i2cWriteDevice(handle, (char *)CMD_CONT_MEAS, 2);
    if (n != 2) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed (returned %d)\n", n);
        return -1;
    }

    /* Wait for the conversion to complete (datasheet: ~45 ms) */
    gpioDelay(MEAS_DELAY);

    /* Read 9 bytes: pressure(2)+crc, temperature(2)+crc, scale(2)+crc */
    n = i2cReadDevice(handle, (char *)buf, 9);
    if (n != 9) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed (returned %d)\n", n);
        return -1;
    }

    /* Validate CRCs */
    if (crc8(&buf[0], 2) != buf[2]) {
        fprintf(stderr, "[ERROR] Pressure CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[3], 2) != buf[5]) {
        fprintf(stderr, "[ERROR] Temperature CRC mismatch\n");
        return -1;
    }
    if (crc8(&buf[6], 2) != buf[8]) {
        fprintf(stderr, "[ERROR] Scale-factor CRC mismatch\n");
        return -1;
    }

    *pressure    = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int16_t pressure = 0, temperature = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x25 */
    g_i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle %d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("SDP800-500Pa reader started. Press Ctrl+C to stop.\n");

    while (g_running) {
        if (read_sdp800(g_i2c_handle, &pressure, &temperature) == 0) {
            printf("Pressure: %d raw, Temperature: %d raw\n",
                   pressure, temperature);
        } else {
            fprintf(stderr, "[WARN] Read failed; will retry next cycle.\n");
        }
        gpioDelay(READ_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

