#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 1000000
#define RELAY_GPIO 17
#define LOG_FILE "reflow_log.csv"
#define PROFILE_FILE "profile.txt"
#define MAX_PROFILE_ENTRIES 100
#define SAMPLE_INTERVAL_US 1000000
#define CONTROL_PERIOD_US 1000000

#define KP 1.0
#define KI 0.1
#define KD 0.01

typedef struct {
    int time_seconds;
    float target_temperature;
} TemperatureProfile;

static volatile sig_atomic_t terminate = 0;
static int spi_handle = -1;
static FILE *log_file = NULL;
static TemperatureProfile temperature_profile[MAX_PROFILE_ENTRIES];
static int profile_size = 0;
static float integral = 0.0;
static float previous_error = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int read_thermocouple_temperature(float *temperature) {
    char buffer[4];
    int bytes_read = spiRead(spi_handle, buffer, 4);
    if (bytes_read != 4) {
        fprintf(stderr, "SPI read error: expected 4 bytes, got %d\n", bytes_read);
        return -1;
    }
    if (buffer[3] & 0x01) {
        fprintf(stderr, "Thermocouple not connected or fault detected\n");
        return -1;
    }
    int raw_temp = ((buffer[0] & 0x0F) << 8) | buffer[1];
    *temperature = (float)raw_temp * 0.25;
    return 0;
}

static float calculate_pid(float setpoint, float actual) {
    float error = setpoint - actual;
    integral += error;
    float derivative = error - previous_error;
    float output = KP * error + KI * integral + KD * derivative;
    previous_error = error;
    if (output < 0.0) output = 0.0;
    if (output > 1.0) output = 1.0;
    return output;
}

static void set_relay_duty_cycle(float duty_cycle) {
    int pulse_width = (int)(duty_cycle * CONTROL_PERIOD_US);
    if (pulse_width > 0) {
        gpioPulse_t pulses[2] = {
            {1, pulse_width},
            {0, CONTROL_PERIOD_US - pulse_width}
        };
        gpioWaveClear();
        gpioWaveAddGeneric(2, pulses);
        int wave_id = gpioWaveCreate();
        if (wave_id >= 0) {
            gpioWaveTxSend(wave_id, PI_WAVE_MODE_ONE_SHOT);
            while (gpioWaveTxBusy()) {
                gpioDelay(100);
            }
            gpioWaveDelete(wave_id);
        } else {
            fprintf(stderr, "Failed to create wave: %s\n", strerror(errno));
        }
    }
}

static int log_temperature(float temperature, float setpoint, float pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    if (fprintf(log_file, "%s,%.2f,%.2f,%.4f\n", timestamp, temperature, setpoint, pid_output) < 0) {
        fprintf(stderr, "Failed to write to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_file);
    return 0;
}

static int load_temperature_profile(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Failed to open profile file: %s\n", strerror(errno));
        return -1;
    }
    profile_size = 0;
    char line[256];
    while (fgets(line, sizeof(line), fp) && profile_size < MAX_PROFILE_ENTRIES) {
        if (sscanf(line, "%d,%f", &temperature_profile[profile_size].time_seconds, &temperature_profile[profile_size].target_temperature) == 2) {
            profile_size++;
        } else {
            fprintf(stderr, "Invalid profile entry: %s", line);
        }
    }
    fclose(fp);
    if (profile_size == 0) {
        fprintf(stderr, "No valid entries in profile file\n");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0);
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }
    if (load_temperature_profile(PROFILE_FILE) != 0) {
        cleanup();
        return 1;
    }
    int profile_index = 0;
    float current_setpoint = temperature_profile[profile_index].target_temperature;
    printf("Starting reflow oven control. Target: %.2f C\n", current_setpoint);
    while (!terminate) {
        float temperature;
        if (read_thermocouple_temperature(&temperature) != 0) {
            fprintf(stderr, "Sensor read error, skipping cycle\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }
        float pid_output = calculate_pid(current_setpoint, temperature);
        set_relay_duty_cycle(pid_output);
        if (log_temperature(temperature, current_setpoint, pid_output) != 0) {
            fprintf(stderr, "Logging error\n");
        }
        if (profile_index < profile_size - 1 && gpioTick() >= (unsigned)temperature_profile[profile_index + 1].time_seconds * 1000000) {
            profile_index++;
            current_setpoint = temperature_profile[profile_index].target_temperature;
            printf("Target temperature updated to %.2f C\n", current_setpoint);
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }
    gpioWrite(RELAY_GPIO, 0);
    cleanup();
    printf("Reflow oven control terminated.\n");
    return 0;
}

