#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <dirent.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define W1_DEVICES_DIR "/sys/bus/w1/devices/"
#define W1_SLAVE_FILE "w1_slave"
#define RELAY_GPIO 17
#define PWM_GPIO 18
#define PWM_FREQ 1000
#define PWM_RANGE 1000
#define LOG_FILE "greenhouse.log"
#define SAMPLE_INTERVAL 5
#define MAX_TEMP_READINGS 10

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

typedef struct {
    double Kp, Ki, Kd;
    double setpoint;
    double integral, previous_error;
} PIDController;

static PIDController pid;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(const char *sensor_id, double *temperature) {
    char path[256];
    snprintf(path, sizeof(path), "%s%s/%s", W1_DEVICES_DIR, sensor_id, W1_SLAVE_FILE);

    int fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("Error opening w1_slave file");
        return -1;
    }

    char buffer[256];
    ssize_t bytes_read = read(fd, buffer, sizeof(buffer) - 1);
    if (bytes_read < 0) {
        perror("Error reading w1_slave file");
        close(fd);
        return -1;
    }
    buffer[bytes_read] = '\0';
    close(fd);

    char *temp_str = strstr(buffer, "t=");
    if (temp_str == NULL) {
        fprintf(stderr, "Error: Temperature data not found in w1_slave output.\n");
        return -1;
    }

    long temp_raw = strtol(temp_str + 2, NULL, 10);
    if (temp_raw == 0 && temp_str[2] != '0') {
        fprintf(stderr, "Error: Invalid temperature data in w1_slave output.\n");
        return -1;
    }

    *temperature = (double)temp_raw / 1000.0;
    return 0;
}

static double calculate_pid(double current_temp) {
    double error = pid.setpoint - current_temp;
    pid.integral += error;
    double derivative = error - pid.previous_error;
    double output = pid.Kp * error + pid.Ki * pid.integral + pid.Kd * derivative;
    pid.previous_error = error;
    return output;
}

static void set_pwm(double pid_output) {
    int duty_cycle = (int)(pid_output * 10);
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;
    gpioPWM(PWM_GPIO, duty_cycle);
}

static void set_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

static void log_data(double avg_temp, double setpoint, double pid_output, int pwm_duty) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%d\n", timestamp, avg_temp, setpoint, pid_output, pwm_duty);
    fflush(log_file);
}

static void cleanup(void) {
    set_relay(0);
    gpioPWM(PWM_GPIO, 0);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 5) {
        fprintf(stderr, "Usage: %s <setpoint> <Kp> <Ki> <Kd>\n", argv[0]);
        return 1;
    }

    pid.setpoint = atof(argv[1]);
    pid.Kp = atof(argv[2]);
    pid.Ki = atof(argv[3]);
    pid.Kd = atof(argv[4]);
    pid.integral = 0.0;
    pid.previous_error = 0.0;

    if (pid.Kp < 0 || pid.Ki < 0 || pid.Kd < 0) {
        fprintf(stderr, "Error: PID gains must be non-negative.\n");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQ);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    DIR *dir = opendir(W1_DEVICES_DIR);
    if (dir == NULL) {
        perror("Error opening w1 devices directory");
        cleanup();
        return 1;
    }

    struct dirent *ent;
    int sensor_count = 0;
    char sensor_ids[10][32];

    while ((ent = readdir(dir)) != NULL) {
        if (strstr(ent->d_name, "28-") != NULL) {
            if (sensor_count < 10) {
                strncpy(sensor_ids[sensor_count], ent->d_name, sizeof(sensor_ids[sensor_count]) - 1);
                sensor_ids[sensor_count][sizeof(sensor_ids[sensor_count]) - 1] = '\0';
                sensor_count++;
            } else {
                fprintf(stderr, "Warning: More than 10 DS18B20 sensors found. Only using the first 10.\n");
                break;
            }
        }
    }
    closedir(dir);

    if (sensor_count == 0) {
        fprintf(stderr, "Error: No DS18B20 sensors found. Ensure the w1-gpio module is loaded and the sensor is connected.\n");
        cleanup();
        return 1;
    }

    printf("Found %d DS18B20 sensor(s).\n", sensor_count);
    for (int i = 0; i < sensor_count; i++) {
        printf("Sensor %d: %s\n", i + 1, sensor_ids[i]);
    }

    double temperatures[MAX_TEMP_READINGS];
    int temp_index = 0;
    double sum_temperatures = 0.0;

    while (running) {
        double avg_temp = 0.0;
        int valid_readings = 0;

        for (int i = 0; i < sensor_count; i++) {
            double temp;
            if (read_temperature(sensor_ids[i], &temp) == 0) {
                temperatures[temp_index] = temp;
                temp_index = (temp_index + 1) % MAX_TEMP_READINGS;
                if (temp_index == 0) {
                    sum_temperatures -= temperatures[0];
                }
                sum_temperatures += temp;
                valid_readings++;
            } else {
                fprintf(stderr, "Error reading temperature from sensor %s. Skipping.\n", sensor_ids[i]);
            }
        }

        if (valid_readings > 0) {
            avg_temp = sum_temperatures / valid_readings;
            double pid_output = calculate_pid(avg_temp);
            set_pwm(pid_output);
            set_relay(1);

            int pwm_duty = (int)(pid_output * 10);
            if (pwm_duty < 0) pwm_duty = 0;
            if (pwm_duty > PWM_RANGE) pwm_duty = PWM_RANGE;

            log_data(avg_temp, pid.setpoint, pid_output, pwm_duty);
            printf("Avg Temp: %.2f, Setpoint: %.2f, PID Output: %.2f, PWM Duty: %d\n", avg_temp, pid.setpoint, pid_output, pwm_duty);
        } else {
            fprintf(stderr, "Error: No valid temperature readings. Skipping PID calculation and PWM control.\n");
            set_relay(0);
        }

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");
    cleanup();
    return 0;
}

