#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define AHT20_ADDR          0x38
#define AHT20_CMD_INIT      0xBE
#define AHT20_CMD_MEASURE   0xAC
#define AHT20_CMD_SOFTRESET 0xBA
#define AHT20_MEASURE_DELAY_US 80000
#define AHT20_RETRY_COUNT   3
#define AHT20_RETRY_DELAY_US 10000
#define HUMIDITY_HIGH       60.0f
#define HUMIDITY_LOW        55.0f
#define DEHUMIDIFIER_GPIO   17
#define POLL_INTERVAL_S     5

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int aht20_soft_reset(int fd) {
    uint8_t cmd = AHT20_CMD_SOFTRESET;
    if (write(fd, &cmd, 1) != 1) {
        return -1;
    }
    usleep(20000);
    return 0;
}

static int aht20_init(int fd) {
    uint8_t cmd = AHT20_CMD_INIT;
    if (write(fd, &cmd, 1) != 1) {
        return -1;
    }
    usleep(10000);
    return 0;
}

static int aht20_read_humidity(int fd, float *humidity) {
    uint8_t cmd = AHT20_CMD_MEASURE;
    uint8_t buf[6];
    int retries = AHT20_RETRY_COUNT;

    while (retries > 0) {
        if (write(fd, &cmd, 1) != 1) {
            retries--;
            if (retries > 0) usleep(AHT20_RETRY_DELAY_US);
            continue;
        }

        usleep(AHT20_MEASURE_DELAY_US);

        ssize_t n = read(fd, buf, 6);
        if (n != 6) {
            retries--;
            if (retries > 0) usleep(AHT20_RETRY_DELAY_US);
            continue;
        }

        if ((buf[0] & 0x80) != 0) {
            retries--;
            if (retries > 0) usleep(AHT20_RETRY_DELAY_US);
            continue;
        }

        uint32_t raw_humidity = ((uint32_t)buf[1] << 12) |
                                ((uint32_t)buf[2] << 4)  |
                                ((uint32_t)buf[3] >> 4);
        *humidity = ((float)raw_humidity / 1048576.0f) * 100.0f;
        return 0;
    }

    return -1;
}

static void control_dehumidifier(float humidity) {
    if (humidity > HUMIDITY_HIGH) {
