#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <syslog.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <stdint.h>

#define I2C_BUS "/dev/i2c-1"
#define HTU21D_ADDR 0x40
#define API_ENDPOINT "http://api.example.com/humidity"
#define POLL_INTERVAL 60
#define MEASURE_HUMIDITY_HOLD 0xE5
#define SOFT_RESET 0xFE

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0x00;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 8; bit > 0; --bit) {
            if (crc & 0x80) crc = (crc << 1) ^ 0x31;
            else crc = (crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, unsigned char cmd) {
    if (write(fd, &cmd, 1) != 1) {
        syslog(LOG_ERR, "I2C write failed for cmd 0x%02X: %s", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_data(int fd, unsigned char *buf, int len) {
    if (read(fd, buf, len) != len) {
        syslog(LOG_ERR, "I2C read failed: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_humidity(int fd, float *humidity) {
    unsigned char buf[3];
    unsigned int raw_humidity;

    if (i2c_write_cmd(fd, MEASURE_HUMIDITY_HOLD) < 0) return -1;
    usleep(50000);

    if (i2c_read_data(fd, buf, 3) < 0) return -1;

    if (crc8(buf, 2) != buf[2]) {
        syslog(LOG_ERR, "CRC mismatch on humidity data");
        return -1;
    }

    raw_humidity = ((unsigned int)buf[0] << 8) | buf[1];
    raw_humidity &= 0xFFFC;
    *humidity = -6.0f + 125.0f * ((float)raw_humidity / 65536.0f);

    if (*humidity < 0.0f || *humidity > 100.0f) {
        syslog(LOG_ERR, "Humidity out of range: %.2f", *humidity);
        return -1;
    }

    return 0;
}

static int post_data(const char *json_data) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) {
        syslog(LOG_ERR, "Socket creation failed: %s", strerror(errno));
        return -1;
    }

    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(80);

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        syslog(LOG_ERR, "Connection to API failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    char request[512];
    int req_len = snprintf(request, sizeof(request),
        "POST /humidity HTTP/1.1\r\n"
        "Host: api.example.com\r\n"
        "Content-Type: application/json\r\n"
        "Content-Length: %zu\r\n"
        "Connection: close\r\n"
        "\r\n"
        "%s", strlen(json_data), json_data);

    if (req_len < 0 || (size_t)req_len >= sizeof(request)) {
        syslog(LOG_ERR, "Request buffer overflow");
        close(sockfd);
        return -1;
    }

    if (write(sockfd, request, req_len) < 0) {
        syslog(LOG_ERR, "HTTP request write failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }

    char response[1024];
    ssize_t bytes = read(sockfd, response, sizeof(response) - 1);
    if (bytes < 0) {
        syslog(LOG_ERR, "HTTP response read failed: %s", strerror(errno));
        close(sockfd);
        return -1;
    }
    response[bytes] = '\0';

    int status_code = 0;
    if (sscanf(response, "HTTP/%*d.%*d %d", &status_code) != 1) {
        syslog(LOG_ERR, "Failed to parse HTTP status code");
        close(sockfd);
        return -1;
    }

    if (status_code < 200 || status_code >= 300) {
        syslog(LOG_ERR, "HTTP request failed with status code: %d", status_code);
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main() {
    openlog("humidity_monitor", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        closelog();
        return 1;
    }

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        syslog(LOG_ERR, "Failed to open I2C bus %s: %s", I2C_BUS, strerror(errno));
        closelog();
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, HTU21D_ADDR) < 0) {
        syslog(LOG_ERR, "Failed to acquire I2C bus access: %s", strerror(errno));
        close(i2c_fd);
        closelog();
        return 1;
    }

    if (i2c_write_cmd(i2c_fd, SOFT_RESET) < 0) {
        syslog(LOG_ERR, "Failed to reset HTU21D sensor");
        close(i2c_fd);
        closelog();
        return 1;
    }
    usleep(15000);

    while (running) {
        float humidity;
        if (read_humidity(i2c_fd, &humidity) == 0) {
            char json_data[64];
            snprintf(json_data, sizeof(json_data), "{\"humidity\": %.2f}", humidity);

            if (post_data(json_data) == 0) {
                syslog(LOG_INFO, "Humidity: %.2f%%, posted to API", humidity);
            } else {
                syslog(LOG_ERR, "Failed to post data to API");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity from sensor");
        }

        for (int i = 0; i < POLL_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    if (i2c_fd >= 0) close(i2c_fd);
    closelog();
    return 0;
}

