/*
 * Raspberry Pi 4B – TMP117 + AHT20 + PIR logger
 *
 * Build:  gcc -o logger logger.c -lgpiod -lrt
 *
 * Wiring:
 *   TMP117  SDA->GPIO2  SCL->GPIO3  VDD->3V3  GND->GND  (I2C addr 0x48)
 *   AHT20   SDA->GPIO2  SCL->GPIO3  VDD->3V3  GND->GND  (I2C addr 0x38)
 *   PIR     OUT->GPIO17 GND->GND
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define TMP117_ADDR        0x48
#define AHT20_ADDR         0x38
#define PIR_GPIO_LINE      17          /* gpiochip4 line 17 */
#define I2C_BUS            "/dev/i2c-1"
#define LOG_DIR            "./logs"
#define SAMPLE_INTERVAL_S  1
#define MAX_RETRIES        3
#define RETRY_DELAY_MS     10

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---------- I2C helpers ---------- */

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s): %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE 0x%02X): %s\n", addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int i2c_write(int fd, const uint8_t *buf, size_t len)
{
    ssize_t n = write(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c write: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read(int fd, uint8_t *buf, size_t len)
{
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        fprintf(stderr, "i2c read: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ---------- TMP117 ---------- */

static int tmp117_read(int fd, float *temp_c)
{
    uint8_t reg = 0x00;
    uint8_t buf[2];

    if (i2c_write(fd, &reg, 1) < 0)
        return -1;

    if (i2c_read(fd, buf, 2) < 0)
        return -1;

    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *temp_c = (float)raw / 128.0f;
    return 0;
}

/* ---------- AHT20 ---------- */

static int aht20_read(int fd, float *humidity)
{
    uint8_t cmd[1] = {0xBE};
    uint8_t buf[7];

    if (i2c_write(fd, cmd, 1) < 0)
        return -1;

    usleep(10000);  /* 10 ms measurement delay */

    if (i2c_read(fd, buf, 7) < 0)
        return -1;

    if ((buf[0] & 0x80) != 0) {
        fprintf(stderr, "AHT20 busy\n");
        return -1;
    }

    uint32_t h = ((uint32_t)buf[1] << 12) | ((uint32_t)buf[2] << 4) | (buf[3] >> 4);
    *humidity = (float)h / 1048576.0f * 100.0f;
    return 0;
}

/* ---------- Logging ---------- */

static void get_timestamp(char *ts, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    localtime_r(&t, &tmv);
    strftime(ts, len, "%Y-%m-%d %H:%M:%S", &tmv);
}

static void get_date(char *date, size_t len)
{
    time_t t = time(NULL);
    struct tm tmv;
    localtime_r(&t, &tmv);
    strftime(date, len, "%Y-%m-%d", &tmv);
}

static int ensure_log_dir(void)
{
    if (access(LOG_DIR, F_OK) == 0)
        return 0;
    if (mkdir(LOG_DIR, 0755) < 0 && errno != EEXIST) {
        fprintf(stderr, "mkdir(%s): %s\n", LOG_DIR, strerror(errno));
        return -1;
    }
    return 0;
}

static int log_data(const char *date, float temp, float hum, int motion)
{
    char path[256];
    snprintf(path, sizeof(path), "%s/%s.csv", LOG_DIR, date);

    int need_header = (access(path, F_OK) != 0);

    FILE *fp = fopen(path, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", path, strerror(errno));
        return -1;
    }

    if (need_header)
        fprintf(fp, "Timestamp,Temperature(C),Humidity(%%),MotionDetected\n");

    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(fp, "%s,%.2f,%.2f,%d\n", ts, temp, hum, motion);
    fclose(fp);
    return 0;
}

/* ---------- Main ---------- */

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (ensure_log_dir() < 0)
        return EXIT_FAILURE;

    int i2c_fd = i2c_open(I2C_BUS, TMP117_ADDR);
    if (i2c_fd < 0) {
        fprintf(stderr, "TMP117 not detected at 0x%02X\n", TMP117_ADDR);
    }

    int aht_fd = i2c_open(I2C_BUS, AHT20_ADDR);
    if (aht_fd < 0) {
        fprintf(stderr, "AHT20 not detected at 0x%02X\n", AHT20_ADDR);
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open: %s\n", strerror(errno));
        goto cleanup_i2c;
    }

    struct gpiod_line *pir = gpiod_chip_get_line(chip, PIR_GPIO_LINE);
    if (!pir) {
        fprintf(stderr, "gpiod_chip_get_line(%d): %s\n", PIR_GPIO_LINE, strerror(errno));
        goto cleanup_chip;
    }

    if (gpiod_line_request_input(pir, "pir-logger") < 0) {
        fprintf(stderr, "gpiod_line_request_input: %s\n", strerror(errno));
        goto cleanup_chip;
    }

    printf("Logging started. Press Ctrl+C to stop.\n");

    char prev_date[16] = "";

