#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN   22
#define MOTOR_IN1_PIN   23
#define MOTOR_IN2_PIN   24
#define POLL_INTERVAL_SEC 2
#define MOTOR_RUN_SEC    5

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void log_message(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static int set_motor(struct gpiod_line *ena, struct gpiod_line *in1,
                     struct gpiod_line *in2, int forward) {
    int v1 = forward ? 1 : 0;
    int v2 = forward ? 0 : 1;
    if (gpiod_line_set_value(in1, v1) < 0) {
        log_message("ERROR: failed to set IN1");
        return -1;
    }
    if (gpiod_line_set_value(in2, v2) < 0) {
        log_message("ERROR: failed to set IN2");
        return -1;
    }
    if (gpiod_line_set_value(ena, 1) < 0) {
        log_message("ERROR: failed to enable motor");
        return -1;
    }
    return 0;
}

static int stop_motor(struct gpiod_line *ena, struct gpiod_line *in1,
                      struct gpiod_line *in2) {
    if (gpiod_line_set_value(ena, 0) < 0) {
        log_message("ERROR: failed to disable motor");
        return -1;
    }
    if (gpiod_line_set_value(in1, 0) < 0) {
        log_message("ERROR: failed to reset IN1");
        return -1;
    }
    if (gpiod_line_set_value(in2, 0) < 0) {
        log_message("ERROR: failed to reset IN2");
        return -1;
    }
    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *rain_line = NULL;
    struct gpiod_line *ena_line = NULL;
    struct gpiod_line *in1_line = NULL;
    struct gpiod_line *in2_line = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        perror("gpiod_chip_open");
        return EXIT_FAILURE;
    }

    rain_line = gpiod_chip_get_line(chip, RAIN_SENSOR_PIN);
    ena_line  = gpiod_chip_get_line(chip, MOTOR_ENA_PIN);
    in1_line  = gpiod_chip_get_line(chip, MOTOR_IN1_PIN);
    in2_line  = gpiod_chip_get_line(chip, MOTOR_IN2_PIN);

    if (!rain_line || !ena_line || !in1_line || !in2_line) {
        log_message("ERROR: failed to acquire GPIO lines");
        goto cleanup;
    }

    if (gpiod_line_request_input(rain_line, "rain_sensor") < 0) {
        log_message("ERROR: failed to request rain sensor line as input");
        goto cleanup;
    }
    if (gpiod_line_request_output(ena_line, "motor_ena", 0) < 0) {
        log_message("ERROR: failed to request ENA line as output");
        goto cleanup;
    }
    if (gpiod_line_request_output(in1_line, "motor_in1", 0) < 0) {
        log_message("ERROR: failed to request IN1 line as output");
        goto cleanup;
    }
    if (gpiod_line_request_output(in2_line, "motor_in2", 0) < 0) {
        log_message("ERROR: failed to request IN2 line as output");
        goto cleanup;
    }

    log_message("Rain sensor monitoring started. Press Ctrl+C to exit.");

    while (program_running) {
        int val = gpiod_line_get_value(rain_line);
        if (val < 0) {
            log_message("ERROR: failed to read rain sensor");
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        if (val == 0) {
            log_message("Rain detected! Closing window...");
            if (set_motor(ena_line, in1_line, in2_line, 1) < 0) {
                log_message("ERROR: failed to start motor");
            } else {
                sleep(MOTOR_RUN_SEC);
                if (stop_motor(ena_line, in1_line, in2_line) < 0) {
                    log_message("ERROR: failed to stop motor");
                } else {
                    log_message("Window closed.");
                }
            }
        } else {
            log_message("No rain.");
        }

        sleep(POLL_INTERVAL_SEC);
    }

    log_message("Shutting down...");
    ret = EXIT_SUCCESS;

cleanup:
    if (ena_line)  gpiod_line_release(ena_line);
    if (in1_line)  gpiod_line_release(in1_line);
    if (in2_line)  gpiod_line_release(in2_line);
    if (rain_line) gpiod_line_release(rain_line);
    if (chip)      gpiod_chip_close(chip);
    return ret;
}

