#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

#define PWM_RANGE 255
#define SAMPLE_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read /proc/stat and return user + system CPU time in seconds. */
static int read_cpu_time(double *total)
{
    FILE *fp = fopen("/proc/stat", "r");
    if (!fp) {
        fprintf(stderr, "Error opening /proc/stat: %s\n", strerror(errno));
        return -1;
    }

    char line[256];
    if (!fgets(line, sizeof(line), fp)) {
        fprintf(stderr, "Error reading /proc/stat: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    if (strncmp(line, "cpu ", 4) != 0) {
        fprintf(stderr, "Unexpected /proc/stat format\n");
        return -1;
    }

    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal;
    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal) != 8) {
        fprintf(stderr, "Error parsing /proc/stat\n");
        return -1;
    }

    *total = (double)(user + nice + system + irq + softirq + steal)
           / (double)(user + nice + system + idle + iowait + irq + softirq + steal);
    return 0;
}

/* Map CPU load (0.0–1.0) to a color gradient: green -> yellow -> red. */
static void load_to_color(double load, int *r, int *g, int *b)
{
    if (load < 0.0) load = 0.0;
    if (load > 1.0) load = 1.0;

    if (load < 0.5) {
        *r = 0;
        *g = (int)(255.0 * load * 2.0);
        *b = 0;
    } else {
        *r = (int)(255.0 * (load - 0.5) * 2.0);
