#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define BMP280_I2C_ADDR 0x76
#define UDP_SERVER_IP "192.168.1.100"
#define UDP_SERVER_PORT 5000
#define SAMPLE_INTERVAL_SEC 5

/* BMP280 Registers */
#define BMP280_REG_TEMP_MSB 0xFA
#define BMP280_REG_PRESS_MSB 0xF7
#define BMP280_REG_CONFIG 0xF5
#define BMP280_REG_CTRL_MEAS 0xF4
#define BMP280_REG_ID 0xD0
#define BMP280_REG_RESET 0xE0

/* Calibration coefficients */
typedef struct {
    uint16_t dig_T1;
    int16_t dig_T2;
    int16_t dig_T3;
    uint16_t dig_P1;
    int16_t dig_P2;
    int16_t dig_P3;
    int16_t dig_P4;
    int16_t dig_P5;
    int16_t dig_P6;
    int16_t dig_P7;
    int16_t dig_P8;
    int16_t dig_P9;
} bmp280_calib_t;

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static int g_udp_socket = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_calibration(int handle, bmp280_calib_t *cal) {
    uint8_t buf[24];
    if (i2cReadI2CBlockData(handle, 0x88, (char *)buf, 24) != 24) {
        fprintf(stderr, "Failed to read calibration data: %s\n", strerror(errno));
        return -1;
    }
    cal->dig_T1 = (uint16_t)(buf[0] | (buf[1] << 8));
    cal->dig_T2 = (int16_t)(buf[2] | (buf[3] << 8));
    cal->dig_T3 = (int16_t)(buf[4] | (buf[5] << 8));
    cal->dig_P1 = (uint16_t)(buf[6] | (buf[7] << 8));
    cal->dig_P2 = (int16_t)(buf[8] | (buf[9] << 8));
    cal->dig_P3 = (int16_t)(buf[10] | (buf[11] << 8));
    cal->dig_P4 = (int16_t)(buf[12] | (buf[13] << 8));
    cal->dig_P5 = (int16_t)(buf[14] | (buf[15] << 8));
    cal->dig_P6 = (int16_t)(buf[16] | (buf[17] << 8));
    cal->dig_P7 = (int16_t)(buf[18] | (buf[19] << 8));
    cal->dig_P8 = (int16_t)(buf[20] | (buf[21] << 8));
    cal->dig_P9 = (int16_t)(buf[22] | (buf[23] << 8));
    return 0;
}

static int32_t compensate_temperature(int32_t adc_T, const bmp280_calib_t *cal, int32_t *t_fine) {
    int32_t var1, var2;
    var1 = ((((adc_T >> 3) - ((int32_t)cal->dig_T1 << 1))) * ((int32_t)cal->dig_T2)) >> 11;
    var2 = (((((adc_T >> 4) - ((int32_t)cal->dig_T1)) * ((adc_T >> 4) - ((int32_t)cal->dig_T1))) >> 12) * ((int32_t)cal->dig_T3)) >> 14;
    *t_fine = var1 + var2;
    return (*t_fine * 5 + 128) >> 8;
}

static uint32_t compensate_pressure(int32_t adc_P, const bmp280_calib_t *cal, int32_t t_fine) {
    int64_t var1, var2, p;
    var1 = ((int64_t)t_fine) - 128000;
    var2 = var1 * var1 * (int64_t)cal->dig_P6;
    var2 = var2 + ((var1 * (int64_t)cal->dig_P5) << 17);
    var2 = var2 + (((int64_t)cal->dig_P4) << 35);
    var1 = ((var1 * var1 * (int64_t)cal->dig_P3) >> 8) + ((var1 * (int64_t)cal->dig_P2) << 12);
    var1 = (((((int64_t)1) << 47) + var1)) * ((int64_t)cal->dig_P1) >> 33;
    if (var1 == 0) return 0;
    p = 1048576 - adc_P;
    p = (((p << 31) - var2) * 3125) / var1;
    var1 = (((int64_t)cal->dig_P9) * (p >> 13) * (p >> 13)) >> 25;
    var2 = (((int64_t)cal->dig_P8) * p) >> 19;
    p = ((p + var1 + var2) >> 8) + (((int64_t)cal->dig_P7) << 4);
    return (uint32_t)p;
}

static int read_bmp280(int handle, const bmp280_calib_t *cal, float *temperature, float *pressure) {
    /* Wait for measurement to complete (osrs_t=x1, osrs_p=x1, mode=normal) */
    if (i2cWriteByteData(handle, BMP280_REG_CTRL_MEAS, 0x27) < 0) {
        fprintf(stderr, "Failed to write CTRL_MEAS: %s\n", strerror(errno));
        return -1;
    }
    gpioDelay(10000); /* 10 ms */

    uint8_t data[6];
    if (i2cReadI2CBlockData(handle, BMP280_REG_PRESS_MSB, (char *)data, 6) != 6) {
        fprintf(stderr, "Failed to read pressure/temp data: %s\n", strerror(errno));
        return -1;
    }

    int32_t adc_P = (data[0] << 12) | (data[1] << 4) | (data[2] >> 4);
    int32_t adc_T = (data[3] << 12) | (data[4] << 4) | (data[5] >> 4);

    int32_t t_fine;
    int32_t temp = compensate_temperature(adc_T, cal, &t_fine);
    uint32_t pres = compensate_pressure(adc_P, cal, t_fine);

    *temperature = temp / 100.0f;
    *pressure = pres / 256.0f;
    return 0;
}

static int send_udp_data(const char *json_string) {
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_SERVER_PORT);
    if (inet_pton(AF_INET, UDP_SERVER_IP, &server_addr.sin_addr) <= 0) {
        fprintf(stderr, "Invalid address: %s\n", UDP_SERVER_IP);
        return -1;
    }

    if (sendto(g_udp_socket, json_string, strlen(json_string), 0,
               (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "UDP send failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    g_i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X: %s\n", BMP280_I2C_ADDR, strerror(errno));
        gpioTerminate();
        return 1;
    }

    /* Verify sensor presence by reading chip ID */
    int chip_id = i2cReadByteData(g_i2c_handle, BMP280_REG_ID);
    if (chip_id < 0) {
        fprintf(stderr, "Failed to read chip ID: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (chip_id != 0x58) {
        fprintf(stderr, "Unexpected chip ID: 0x%02X (expected 0x58 for BMP280)\n", chip_id);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    bmp280_calib_t cal;
    if (read_calibration(g_i2c_handle, &cal) < 0) {
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    g_udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (g_udp_socket < 0) {
        fprintf(stderr, "Socket creation failed: %s\n", strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (g_running) {
        float temperature, pressure;
        if (read_bmp280(g_i2c_handle, &cal, &temperature, &pressure) == 0) {
            char json_string[128];
            snprintf(json_string, sizeof(json_string),
                     "{\"temperature\": %.2f, \"pressure\": %.2f}",
                     temperature, pressure);
            if (send_udp_data(json_string) != 0) {
                fprintf(stderr, "Failed to send UDP data\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }
        sleep(SAMPLE_INTERVAL_SEC);
    }

    if (g_i2c_handle >= 0) i2cClose(g_i2c_handle);
    if (g_udp_socket >= 0) close(g_udp_socket);
    gpioTerminate();
    return 0;
}

