#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED   500000
#define SPI_MODE    0
#define FAN_GPIO    18
#define PWM_FREQ    1000
#define PWM_RANGE   255
#define BUFFER_SIZE 20
#define SAMPLE_US   1000000

typedef struct {
    time_t timestamp;
    float  temperature;
    int    duty_cycle;
} DataPoint;

typedef struct {
    DataPoint buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

static volatile sig_atomic_t running = 1;
static int spi_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void cb_init(CircularBuffer *cb) {
    cb->head  = 0;
    cb->count = 0;
}

static void cb_add(CircularBuffer *cb, time_t ts, float temp, int duty) {
    cb->buffer[cb->head].timestamp  = ts;
    cb->buffer[cb->head].temperature = temp;
    cb->buffer[cb->head].duty_cycle  = duty;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) cb->count++;
}

static void cb_print(const CircularBuffer *cb) {
    printf("\n--- Circular Buffer Contents ---\n");
    for (int i = 0; i < cb->count; i++) {
        int idx = (cb->head - cb->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        char tbuf[32];
        struct tm *tm = localtime(&cb->buffer[idx].timestamp);
        if (tm) strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", tm);
        else    snprintf(tbuf, sizeof(tbuf), "<invalid>");
        printf("[%s] Temp: %.2f C, Duty: %d\n",
               tbuf, cb->buffer[idx].temperature, cb->buffer[idx].duty_cycle);
    }
    printf("--- End of Buffer ---\n");
}

static int read_max31855(int handle, float *temperature) {
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    if (spiXfer(handle, tx, rx, 4) != 4) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    if (raw & 0x00010000) {
        fprintf(stderr, "Error: MAX31855 fault detected (raw=0x%08X)\n", raw);
        return -1;
    }

    int16_t thermocouple_raw = (int16_t)(raw >> 18);
    *temperature = thermocouple_raw * 0.25f;
    return 0;
}

static int calculate_duty_cycle(float temperature) {
    if (temperature < 25.0f) return 0;
    if (temperature < 40.0f) return (int)((temperature - 25.0f) / 15.0f * 127.5f);
    if (temperature < 60.0f) return (int)((temperature - 40.0f) / 20.0f * 127.5f + 127.5f);
    return 255;
}

static void set_fan_speed(int duty_cycle) {
    if (gpioPWM(FAN_GPIO, duty_cycle) < 0) {
        fprintf(stderr, "Error: gpioPWM failed for duty %d\n", duty_cycle);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel=%d, speed=%d, mode=%d)\n",
                SPI_CHANNEL, SPI_SPEED, SPI_MODE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed for GPIO %d\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed for GPIO %d\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioPWM(FAN_GPIO, 0) < 0) {
        fprintf(stderr, "Error: gpioPWM initial off failed for GPIO %d\n", FAN_GPIO);
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: sigaction(SIGINT) failed\n");
    }

    CircularBuffer cb;
    cb_init(&cb);

    printf("Fan control started. Press Ctrl+C to exit.\n");

    while (running) {
        float temperature;
        if (read_max31855(spi_handle, &temperature) != 0) {
            fprintf(stderr, "Warning: MAX31855 read failed, skipping cycle\n");
            gpioDelay(SAMPLE_US);
            continue;
        }

        int duty_cycle = calculate_duty_cycle(temperature);
        set_fan_speed(duty_cycle);

        time_t now = time(NULL);
        cb_add(&cb, now, temperature, duty_cycle);

        printf("Temp: %.2f C, Duty: %d\n", temperature, duty_cycle);

        gpioDelay(SAMPLE_US);
    }

    printf("\nShutting down...\n");
    set_fan_speed(0);
    cb_print(&cb);

    if (spi_handle >= 0) spiClose(spi_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

