/*
 * MAX31865 RTD-to-Digital Temperature Logger for Raspberry Pi 5
 *
 * Wiring:
 *   MAX31865 VIN  -> 3.3V (Pin 1)
 *   MAX31865 GND  -> GND  (Pin 9)
 *   MAX31865 CLK  -> GPIO11 (SPI0 SCLK)
 *   MAX31865 CS   -> GPIO8  (SPI0 CE0)
 *   MAX31865 DO   -> GPIO9  (SPI0 MISO)
 *
 * Build: gcc -O2 -Wall -o rtd_logger rtd_logger.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_0
#define LOG_FILE        "rtd_log.csv"
#define SAMPLE_INTERVAL 5
#define RREF            4300.0
#define RTD_NOMINAL     100.0
#define ALPHA           0.0039083

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    int fd = open(SPI_DEVICE, O_RDWR);
    if (fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(fd);
        return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(fd);
        return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Read 4 bytes from the MAX31865.
 * Returns 0 on success, -1 on SPI transfer failure.
 */
static int read_max31865(uint8_t *data) {
    struct spi_ioc_transfer tr = {
        .tx_buf = 0,
        .rx_buf = (unsigned long)data,
        .len = 4,
        .speed_hz = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }
    return 0;
}

/*
 * Parse the 32-bit raw value and compute temperature.
 * Returns 0 on success, -1 on fault.
 */
static int parse_rtd(uint32_t raw, float *temperature) {
    /* Check fault bit (bit 16) */
    if (raw & 0x00010000) {
        if (raw & 0x00000001)
            fprintf(stderr, "RTDIN- fault\n");
        if (raw & 0x00000002)
            fprintf(stderr, "RTDIN+ fault\n");
        if (raw & 0x00000004)
            fprintf(stderr, "REFIN- fault\n");
        if (raw & 0x00000008)
            fprintf(stderr, "REFIN+ fault\n");
        if (raw & 0x00000010)
            fprintf(stderr, "RTDN fault\n");
        if (raw & 0x00000020)
            fprintf(stderr, "Overrange fault\n");
        if (raw & 0x00000040)
            fprintf(stderr, "Underrange fault\n");
        if (raw & 0x00000080)
            fprintf(stderr, "CRC fault\n");
        return -1;
    }

    /* Extract 15-bit RTD code (bits 15:1) */
    uint16_t rtd_code = (raw >> 1) & 0x7FFF;

    /* Callendar-Van Dusen equation */
    float rtd_resistance = (float)rtd_code * RREF / 32768.0;
    float a = ALPHA;
    float r0 = RTD_NOMINAL;
    float rtd_diff = rtd_resistance - r0;

    if (rtd_diff < 0.0) {
        *temperature = -273.15f;
        return -1;
    }

    float temp = -242.02f;
    temp += 2.2228f * rtd_diff;
    temp += (2.5859e-4f * rtd_diff) * rtd_diff;

    /* Higher order terms for improved accuracy */
    if (rtd_diff > 0.0) {
        temp -= (1.1851e-6f * rtd_diff) * rtd_diff * rtd_diff;
        temp -= (2.7183e-8f * rtd_diff) * rtd_diff * rtd_diff * rtd_diff;
        temp += 1.5243e-3f * rtd_diff;
    }

    *temperature = temp;
    return 0;
}

static void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s,%.2f\n", timestamp, temperature) < 0) {
        perror("fprintf");
    } else {
        fflush(g_log_fp);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_spi_fd = spi_init();
    if (g_spi_fd < 0) {
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        close(g_spi_fd);
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_fp) == 0) {
        fprintf(g_log_fp, "Timestamp,Temperature (C)\n");
        fflush(g_log_fp);
    }

    printf("RTD Logger started. Logging to %s every %d seconds.\n", LOG_FILE, SAMPLE_INTERVAL);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        uint8_t data[4];
        float temperature;

        if (read_max31865(data) < 0) {
            fprintf(stderr, "SPI read failed. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        uint32_t raw = ((uint32_t)data[0] << 24) |
                       ((uint32_t)data[1] << 16) |
                       ((uint32_t)data[2] << 8)  |
                       ((uint32_t)data[3]);

        if (parse_rtd(raw, &temperature) < 0) {
            fprintf(stderr, "RTD fault detected. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        log_temperature(temperature);
        printf("Temperature: %.2f C\n", temperature);

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    printf("RTD Logger stopped.\n");
    return EXIT_SUCCESS;
}

