            fprintf(stderr, "RTD fault detected. Retrying in %d seconds.\n", SAMPLE_INTERVAL);
            sleep(SAMPLE_INTERVAL);
            continue;
        }

        log_temperature(temperature);
        printf("Temperature: %.2f C\n", temperature);

        sleep(SAMPLE_INTERVAL);
    }

    printf("\nShutting down...\n");

    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }

    printf("RTD Logger stopped.\n");
    return EXIT_SUCCESS;
}

