#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS              1
#define BMP180_ADDR          0x77
#define ALERT_GPIO           24
#define PRESSURE_THRESHOLD   5.0f   /* hPa */
#define BUFFER_SIZE          120    /* 60 s at 2 Hz */
#define SAMPLE_PERIOD_US     50000  /* 50 ms */
#define ALERT_HOLD_US        1000000 /* 1 s */

/* BMP180 registers */
#define BMP180_REG_CONTROL   0xF4
#define BMP180_REG_MSB       0xF6
#define BMP180_REG_LSB       0xF7
#define BMP180_REG_XLSB      0xF8
#define BMP180_REG_CAL_AC1   0xAA
#define BMP180_REG_CAL_AC2   0xAC
#define BMP180_REG_CAL_AC3   0xAE
#define BMP180_REG_CAL_AC4   0xB0
#define BMP180_REG_CAL_AC5   0xB2
#define BMP180_REG_CAL_AC6   0xB4
#define BMP180_REG_CAL_B1    0xB6
#define BMP180_REG_CAL_B2    0xB8
#define BMP180_REG_CAL_MB    0xBA
#define BMP180_REG_CAL_MC    0xBC
#define BMP180_REG_CAL_MD    0xBE

#define BMP180_CMD_TEMP      0x2E
#define BMP180_CMD_PRESSURE  0x34

/* ----------------------------- Data types ------------------------------- */
typedef struct {
    time_t timestamp;
    float  pressure;
} PressureReading;

typedef struct {
    PressureReading data[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

/* ----------------------------- Globals ---------------------------------- */
static int           i2c_handle = -1;
static CircularBuffer pressure_buffer;
static volatile sig_atomic_t terminate = 0;

/* Calibration coefficients (read once from the sensor) */
static int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

/* ----------------------------- Prototypes -------------------------------- */
static int  bmp180_read_calibration(void);
static int  bmp180_read_raw_temperature(int32_t *raw_temp);
static int  bmp180_read_raw_pressure(int32_t *raw_pressure);
static float bmp180_convert_pressure(int32_t raw_pressure);
static void buffer_add(PressureReading reading);
static float buffer_average(void);
static void alert_trigger(float current, float average);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- Implementation ---------------------------- */

/* Read a signed 16-bit big-endian calibration word */
static int read_s16(int handle, uint8_t reg, int16_t *out)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2)
        return -1;
    *out = (int16_t)(((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    return 0;
}

/* Read an unsigned 16-bit big-endian calibration word */
static int read_u16(int handle, uint8_t reg, uint16_t *out)
{
    char buf[2];
    if (i2cReadI2CBlockData(handle, reg, buf, 2) != 2)
        return -1;
    *out = (uint16_t)(((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    return 0;
}

static int bmp180_read_calibration(void)
{
    if (read_s16(i2c_handle, BMP180_REG_CAL_AC1, &ac1) < 0) return -1;
    if (read_s16(i2c_handle, BMP180_REG_CAL_AC2, &ac2) < 0) return -1;
    if (read_s16(i2c_handle, BMP180_REG_CAL_AC3, &ac3) < 0) return -1;
    if (read_u16(i2c_handle, BMP180_REG_CAL_AC4, &ac4) < 0) return -1;
    if (read_u16(i2c_handle, BMP180_REG_CAL_AC5, &ac5) < 0) return -1;
    if (read_u16(i2c_handle, BMP180_REG_CAL_AC6, &ac6) < 0) return -1;
    if (read_s16(i2c_handle, BMP180_REG_CAL_B1,  &b1)  < 0) return -1;
    if (read_s16(i2c_handle, BMP180_REG_CAL_B2,  &b2)  < 0) return -1;
    if (read_s16(i2c_handle, BMP180_REG_CAL_MB,  &mb)  < 0) return -1;
    if (read_s16(i2c_handle, BMP180_REG_CAL_MC,  &mc)  < 0) return -1;
    if (read_s16(i2c_handle, BMP180_REG_CAL_MD,  &md)  < 0) return -1;
    return 0;
}

static int bmp180_read_raw_temperature(int32_t *raw_temp)
{
    char cmd = BMP180_CMD_TEMP;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, &cmd, 1) < 0)
        return -1;
    gpioDelay(5000); /* 4.5 ms max conversion time */

    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 2) != 2)
        return -1;
    *raw_temp = (int32_t)(((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1]);
    return 0;
}

static int bmp180_read_raw_pressure(int32_t *raw_pressure)
{
    char cmd = BMP180_CMD_PRESSURE;
    if (i2cWriteI2CBlockData(i2c_handle, BMP180_REG_CONTROL, &cmd, 1) < 0)
        return -1;
    gpioDelay(5000); /* 4.5 ms max conversion time */

    char buf[3];
    if (i2cReadI2CBlockData(i2c_handle, BMP180_REG_MSB, buf, 3) != 3)
        return -1;
    *raw_pressure = ((int32_t)(uint8_t)buf[0] << 16) |
                    ((int32_t)(uint8_t)buf[1] << 8)  |
                    ((int32_t)(uint8_t)buf[2]);
    *raw_pressure >>= (8 - 0); /* OSS = 0 */
    return 0;
}

/* Returns pressure in hPa */
static float bmp180_convert_pressure(int32_t raw_pressure)
{
    int32_t  x1, x2, x3, b3, b5, b6, p;
    uint32_t b4, b7;

    x1 = ((raw_pressure - (int32_t)ac6) * (int32_t)ac5) >> 15;
    x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    b5 = x1 + x2;

    b6 = b5 - 4000;
    x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)ac2 * b6) >> 11;
    x3 = x1 + x2;
    b3 = (((((int32_t)ac1 * 4 + x3) << 0) + 2) >> 2);

    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    b7 = ((uint32_t)raw_pressure - (uint32_t)b3) * (50000 >> 0);

    if (b7 < 0x80000000UL)
        p = (b7 * 2) / b4;
    else
        p = (b7 / b4) * 2;

    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p += (x1 + x2 + 3791) >> 4;

    return (float)p / 100.0f;
}

static void buffer_add(PressureReading reading)
{
    pressure_buffer.data[pressure_buffer.head] = reading;
    pressure_buffer.head = (pressure_buffer.head + 1) % BUFFER_SIZE;
    if (pressure_buffer.count < BUFFER_SIZE)
        pressure_buffer.count++;
}

static float buffer_average(void)
{
    if (pressure_buffer.count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < pressure_buffer.count; i++)
        sum += pressure_buffer.data[i].pressure;
    return sum / (float)pressure_buffer.count;
}

static void alert_trigger(float current, float average)
{
    if (fabsf(current - average) > PRESSURE_THRESHOLD) {
        gpioWrite(ALERT_GPIO, 1);
        fprintf(stderr, "ALERT: pressure %.2f hPa deviates from average %.2f hPa\n",
                current, average);
        gpioDelay(ALERT_HOLD_US);
        gpioWrite(ALERT_GPIO, 0);
    }
}

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(ALERT_GPIO, 0);
    gpioTerminate();
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (code %d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (bmp180_read_calibration() < 0) {
        fprintf(stderr, "Error: failed to read BMP180 calibration data\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ALERT_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO%d\n", ALERT_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(ALERT_GPIO, 0);

    memset(&pressure_buffer, 0, sizeof(pressure_buffer));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BMP180 monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int32_t raw_temp, raw_pressure;

        if (bmp180_read_raw_temperature(&raw_temp) < 0) {
            fprintf(stderr, "Warning: temperature read failed\n");
        } else if (bmp180_read_raw_pressure(&raw_pressure) < 0) {
            fprintf(stderr, "Warning: pressure read failed\n");
        } else {
            float pressure = bmp180_convert_pressure(raw_pressure);

            PressureReading reading;
            reading.timestamp = time(NULL);
            reading.pressure  = pressure;
            buffer_add(reading);

            float avg = buffer_average();
            alert_trigger(pressure, avg);

            printf("Pressure: %.2f hPa, Average: %.2f hPa\n", pressure, avg);
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

