#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_OSS 0

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

typedef struct {
    int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

static bmp180_cal_t cal;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_calibration(void) {
    int16_t *s = &cal.ac1;
    uint16_t *u = &cal.ac4;
    const int regs[11] = {
        BMP180_REG_CAL_AC1, BMP180_REG_CAL_AC2, BMP180_REG_CAL_AC3,
        BMP180_REG_CAL_AC4, BMP180_REG_CAL_AC5, BMP180_REG_CAL_AC6,
        BMP180_REG_CAL_B1, BMP180_REG_CAL_B2, BMP180_REG_CAL_MB,
        BMP180_REG_CAL_MC, BMP180_REG_CAL_MD
    };
    for (int i = 0; i < 11; i++) {
        int v = i2cReadWordData(i2c_handle, regs[i]);
        if (v < 0) return -1;
        if (i < 6) *(s++) = (int16_t)v;
        else *(u++) = (uint16_t)v;
    }
    return 0;
}

static int read_raw_temp(int32_t *ut) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (msb < 0 || lsb < 0) return -1;
    *ut = (msb << 8) | lsb;
    return 0;
}

static int read_raw_pressure(int32_t *up) {
    if (i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (BMP180_OSS << 6)) < 0) return -1;
    gpioDelay(2000 + (3000 << BMP180_OSS));
    int msb = i2cReadByteData(i2c_handle, BMP180_REG_MSB);
    int lsb = i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    int xlsb = i2cReadByteData(i2c_handle, BMP180_REG_XLSB);
    if (msb < 0 || lsb < 0 || xlsb < 0) return -1;
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - BMP180_OSS);
    return 0;
}

static double calc_temp(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)cal.ac6) * (int32_t)cal.ac5) >> 15;
    int32_t x2 = ((int32_t)cal.mc << 11) / (x1 + (int32_t)cal.md);
    int32_t b5 = x1 + x2;
    return ((b5 + 8) >> 4) / 10.0;
}

static double calc_pressure(int32_t up, int32_t ut) {
    int32_t x1 = ((ut - (int32_t)cal.ac6) * (int32_t)cal.ac5) >> 15;
    int32_t x2 = ((int32_t)cal.mc << 11) / (x1 + (int32_t)cal.md);
    int32_t b5 = x1 + x2;
    int32_t b6 = b5 - 4000;
    x1 = ((int32_t)cal.b2 * ((b6 * b6) >> 12)) >> 11;
    x2 = ((int32_t)cal.ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)cal.ac1 * 4 + x3) << BMP180_OSS) + 2) >> 2);
    x1 = ((int32_t)cal.ac3 * b6) >> 13;
    x2 = ((int32_t)cal.b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)cal.ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) p = (b7 * 2) / b4;
    else p = (b7 / b4) * 2;
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    return p + ((x1 + x2 + 3791) >> 4);
}

static void timer_callback(void *user) {
    (void)user;
    int32_t ut, up;
    if (read_raw_temp(&ut) < 0) {
        fprintf(stderr, "Error reading temperature\n");
        return;
    }
    if (read_raw_pressure(&up) < 0) {
        fprintf(stderr, "Error reading pressure\n");
        return;
    }
    double temp = calc_temp(ut);
    double pres = calc_pressure(up, ut);
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "%s,%.2f,%.2f\n", ts, temp, pres);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (read_calibration() < 0) {
        fprintf(stderr, "Calibration read failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("bmp180_log.txt", "a");
    if (!log_file) {
        fprintf(stderr, "Log file open failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (gpioSetTimerFuncEx(0, 500, timer_callback, NULL) < 0) {
        fprintf(stderr, "Timer setup failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    while (running) gpioDelay(100000);

    gpioSetTimerFuncEx(0, 500, NULL, NULL);
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

