#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define FAN_GPIO 18
#define PWM_RANGE 255
#define PWM_FREQ 25000
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define MIN_TEMP 40.0
#define MAX_TEMP 70.0
#define I2C_BUS "/dev/i2c-1"
#define PWM_CHIP 0
#define PWM_CHANNEL 0

static volatile sig_atomic_t running = 1;
static int pwm_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_temperature(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", TEMP_FILE, strerror(errno));
        return -1;
    }
    int temp_milli;
    if (fscanf(fp, "%d", &temp_milli) != 1) {
        fprintf(stderr, "Error reading temperature from %s\n", TEMP_FILE);
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp_milli / 1000;
}

static int map_temperature_to_duty(int temp) {
    if (temp <= MIN_TEMP) return 0;
    if (temp >= MAX_TEMP) return PWM_RANGE;
    return (int)(((float)(temp - MIN_TEMP) / (MAX_TEMP - MIN_TEMP)) * PWM_RANGE);
}

static int pwm_init(void) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/export", PWM_CHIP);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        if (errno != EBUSY) {
            fprintf(stderr, "Error exporting PWM channel: %s\n", strerror(errno));
            return -1;
        }
    } else {
        if (write(fd, "0", 1) < 0 && errno != EBUSY) {
            fprintf(stderr, "Error exporting PWM channel: %s\n", strerror(errno));
            close(fd);
            return -1;
        }
        close(fd);
    }

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/period", PWM_CHIP, PWM_CHANNEL);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening period file: %s\n", strerror(errno));
        return -1;
    }
    char period_str[16];
    int period_ns = 1000000000 / PWM_FREQ;
    snprintf(period_str, sizeof(period_str), "%d", period_ns);
    if (write(fd, period_str, strlen(period_str)) < 0) {
        fprintf(stderr, "Error writing period: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening duty_cycle file: %s\n", strerror(errno));
        return -1;
    }
    char duty_str[16];
    snprintf(duty_str, sizeof(duty_str), "0");
    if (write(fd, duty_str, strlen(duty_str)) < 0) {
        fprintf(stderr, "Error writing initial duty cycle: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);

    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening enable file: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, "1", 1) < 0) {
        fprintf(stderr, "Error enabling PWM: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);

    return 0;
}

static int pwm_set_duty(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;

    char path[64];
    snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/duty_cycle", PWM_CHIP, PWM_CHANNEL);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening duty_cycle file: %s\n", strerror(errno));
        return -1;
    }
    char duty_str[16];
    int duty_ns = (duty * (1000000000 / PWM_FREQ)) / PWM_RANGE;
    snprintf(duty_str, sizeof(duty_str), "%d", duty_ns);
    if (write(fd, duty_str, strlen(duty_str)) < 0) {
        fprintf(stderr, "Error writing duty cycle: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int pwm_cleanup(void) {
    if (pwm_fd >= 0) {
        char path[64];
        snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/pwm%d/enable", PWM_CHIP, PWM_CHANNEL);
        int fd = open(path, O_WRONLY);
        if (fd >= 0) {
            write(fd, "0", 1);
            close(fd);
        }
        snprintf(path, sizeof(path), "/sys/class/pwm/pwmchip%d/unexport", PWM_CHIP);
        fd = open(path, O_WRONLY);
        if (fd >= 0) {
            write(fd, "0", 1);
            close(fd);
        }
        pwm_fd = -1;
    }
    return 0;
}

static int log_data(int temp, int duty) {
    if (!log_fp) {
        log_fp = fopen(LOG_FILE, "a");
        if (!log_fp) {
            fprintf(stderr, "Error opening log file %s: %s\n", LOG_FILE, strerror(errno));
            return -1;
        }
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    if (fprintf(log_fp, "%s, Temp: %d C, Duty: %d\n", timestamp, temp, duty) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(log_fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error setting signal handlers: %s\n", strerror(errno));
        return 1;
    }

    if (pwm_init() < 0) {
        fprintf(stderr, "PWM initialization failed\n");
        return 1;
    }

    while (running) {
        int temp = read_temperature();
        if (temp < 0) {
            fprintf(stderr, "Failed to read temperature, retrying...\n");
            sleep(5);
            continue;
        }

        int duty = map_temperature_to_duty(temp);
        if (pwm_set_duty(duty) < 0) {
            fprintf(stderr, "Failed to set PWM duty cycle\n");
        }

        if (log_data(temp, duty) < 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        sleep(5);
    }

    pwm_set_duty(0);
    pwm_cleanup();
    if (log_fp) fclose(log_fp);
    printf("Program terminated gracefully.\n");
    return 0;
}

