#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <pthread.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define LM75_ADDR      0x48
#define LM75_TEMP_REG  0x00
#define GPIO_CHIP      "gpiochip4"
#define GPIO_OFFSET    18
#define BUFFER_SIZE    60
#define TEMP_THRESHOLD 28.0f
#define POLL_INTERVAL  1

static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static struct gpiod_line *g_led_line = NULL;
static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    float buffer[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static CircularBuffer g_temp_buffer;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[0] << 8) | buf[1]);
    return 0;
}

static int init_i2c(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, LM75_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", LM75_ADDR, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int init_gpio(void) {
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }
    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_OFFSET);
    if (!line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }
    if (gpiod_line_request_output(line, "lm75_alert", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_led_line) {
        gpiod_line_set_value(g_led_line, 0);
        gpiod_line_release(g_led_line);
        g_led_line = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    pthread_mutex_destroy(&g_mutex);
}

static void *alert_thread(void *arg) {
    (void)arg;
    while (g_running) {
        float avg = 0.0f;
        int   cnt = 0;
        pthread_mutex_lock(&g_mutex);
        if (g_temp_buffer.count > 0) {
            float sum = 0.0f;
            for (int i = 0; i < g_temp_buffer.count; i++) {
                sum += g_temp_buffer.buffer[i];
            }
            avg = sum / (float)g_temp_buffer.count;
            cnt = g_temp_buffer.count;
        }
        pthread_mutex_unlock(&g_mutex);

        int val = (cnt > 0 && avg > TEMP_THRESHOLD) ? 1 : 0;
        if (gpiod_line_set_value(g_led_line, val) < 0) {
            fprintf(stderr, "Failed to set LED value: %s\n", strerror(errno));
        }
        sleep(1);
    }
    return NULL;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = init_i2c();
    if (g_i2c_fd < 0) {
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", GPIO_CHIP, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }
    g_led_line = gpiod_chip_get_line(chip, GPIO_OFFSET);
    if (!g_led_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", GPIO_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        close(g_i2c_fd);
        return 1;
    }
    if (gpiod_line_request_output(g_led_line, "lm75_alert", 0) < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as output: %s\n", GPIO_OFFSET, strerror(errno));
        gpiod_chip_close(chip);
        close(g_i2c_fd);
        return 1;
    }
    gpiod_chip_close(chip);

    memset(&g_temp_buffer, 0, sizeof(g_temp_buffer));

    pthread_t tid;
    if (pthread_create(&tid, NULL, alert_thread, NULL) != 0) {
        fprintf(stderr, "Failed to create alert thread: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    while (g_running) {
        int16_t raw;
        if (i2c_read_reg16(g_i2c_fd, LM75_TEMP_REG, &raw) < 0) {
            fprintf(stderr, "Sensor read error; re-initializing I2C...\n");
            close(g_i2c_fd);
            g_i2c_fd = -1;
            sleep(1);
            g_i2c_fd = init_i2c();
            if (g_i2c_fd < 0) {
                fprintf(stderr, "I2C re-init failed; exiting.\n");
                break;
            }
            continue;
        }

        float temp_c = (float)raw / 256.0f;

        pthread_mutex_lock(&g_mutex);
        g_temp_buffer.buffer[g_temp_buffer.head] = temp_c;
        g_temp_buffer.head = (g_temp_buffer.head + 1) % BUFFER_SIZE;
        if (g_temp_buffer.count < BUFFER_SIZE) {
            g_temp_buffer.count++;
        }
        pthread_mutex_unlock(&g_mutex);

        printf("Temperature: %.2f C\n", temp_c);
        sleep(POLL_INTERVAL);
    }

    g_running = 0;
    pthread_join(tid, NULL);
    cleanup();
    return 0;
}

