#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>
#include <jansson.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 500000
#define SPI_MODE 1
#define PWM_GPIO 18
#define PWM_FREQUENCY 1000
#define PWM_RANGE 1000
#define RTD_REF_RESISTANCE 430.0
#define PT100_NOMINAL_RESISTANCE 100.0
#define TARGET_TEMP_DEFAULT 25.0
#define KP_DEFAULT 1.0
#define KI_DEFAULT 0.1
#define KD_DEFAULT 0.01
#define MAX_TEMP 80.0
#define LOOP_DELAY_US 100000
#define MAX31865_FAULT_BIT 0x0001

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;

typedef struct {
    double target_temperature;
    double kp;
    double ki;
    double kd;
} PIDConfig;

static PIDConfig pid_config = {
    .target_temperature = TARGET_TEMP_DEFAULT,
    .kp = KP_DEFAULT,
    .ki = KI_DEFAULT,
    .kd = KD_DEFAULT
};

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        spi_fd = -1;
        return -1;
    }

    return 0;
}

static int read_max31865(uint16_t *raw_data) {
    uint8_t tx_buf[4] = {0, 0, 0, 0};
    uint8_t rx_buf[4] = {0, 0, 0, 0};

    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 4,
        .speed_hz = SPI_SPEED,
        .delay_usecs = 0,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }

    *raw_data = ((uint16_t)rx_buf[0] << 8) | rx_buf[1];
    return 0;
}

static double rtd_to_temperature(uint16_t raw_data) {
    if (raw_data & MAX31865_FAULT_BIT) {
        fprintf(stderr, "MAX31865 fault detected (raw=0x%04X)\n", raw_data);
        return -1000.0;
    }

    uint16_t rtd_code = raw_data >> 1;
    double resistance = (double)rtd_code * RTD_REF_RESISTANCE / 32768.0;
    double temp = (resistance / PT100_NOMINAL_RESISTANCE) - 1.0;
    temp /= 0.00385;
    return temp;
}

static void set_pwm_duty(int duty) {
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    gpioPWM(PWM_GPIO, duty);
}

static void pid_control(double current_temp, double target_temp, double *integral, double *prev_error, double kp, double ki, double kd) {
    double error = target_temp - current_temp;
    *integral += error;
    double derivative = error - *prev_error;
    double output = kp * error + ki * (*integral) + kd * derivative;
    *prev_error = error;

    int duty = (int)output;
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    set_pwm_duty(duty);
}

static int load_configuration(const char *filename, PIDConfig *config) {
    json_error_t error;
    json_t *root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error loading config: %s\n", error.text);
        return -1;
    }

    json_t *target = json_object_get(root, "target_temperature");
    if (target && json_is_number(target)) {
        config->target_temperature = json_number_value(target);
    }

    json_t *kp = json_object_get(root, "kp");
    if (kp && json_is_number(kp)) {
        config->kp = json_number_value(kp);
    }

    json_t *ki = json_object_get(root, "ki");
    if (ki && json_is_number(ki)) {
        config->ki = json_number_value(ki);
    }

    json_t *kd = json_object_get(root, "kd");
    if (kd && json_is_number(kd)) {
        config->kd = json_number_value(kd);
    }

    json_decref(root);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (spi_init() < 0) {
        gpioTerminate();
        return 1;
    }

    gpioSetMode(PWM_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(PWM_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(PWM_GPIO, PWM_RANGE);
    set_pwm_duty(0);

    if (load_configuration("config.json", &pid_config) < 0) {
        fprintf(stderr, "Using default PID parameters\n");
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    double integral = 0.0;
    double prev_error = 0.0;

    while (running) {
        uint16_t raw_data = 0;
        if (read_max31865(&raw_data) < 0) {
            fprintf(stderr, "SPI read failed, exiting\n");
            break;
        }

        double current_temp = rtd_to_temperature(raw_data);
        if (current_temp < -999.0) {
            fprintf(stderr, "RTD fault detected, exiting\n");
            break;
        }

        if (current_temp > MAX_TEMP) {
            fprintf(stderr, "Temperature exceeds maximum (%.2f > %.2f), exiting\n", current_temp, MAX_TEMP);
            break;
        }

        pid_control(current_temp, pid_config.target_temperature, &integral, &prev_error, pid_config.kp, pid_config.ki, pid_config.kd);
        printf("Current: %.2f, Target: %.2f, Duty: %d\n", current_temp, pid_config.target_temperature, gpioGetPWMdutycycle(PWM_GPIO));

        usleep(LOOP_DELAY_US);
    }

    set_pwm_duty(0);
    if (spi_fd >= 0) {
        close(spi_fd);
        spi_fd = -1;
    }
    gpioTerminate();
    return 0;
}

