#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR             0x77
#define BMP180_REG_CONTROL      0xF4
#define BMP180_REG_MSB          0xF6
#define BMP180_REG_CAL_START    0xAA
#define BMP180_CAL_BYTES        22
#define BMP180_CMD_TEMP         0x2E
#define BMP180_CMD_PRESSURE     0x34
#define OSS                     0
#define FAN_GPIO                18
#define BUFFER_SIZE             60
#define SAMPLE_PERIOD_US        500000
#define TEMP_THRESHOLD          30.0f

typedef struct {
    int16_t  ac1, ac2, ac3, b1, b2, mb, mc, md;
    uint16_t ac4, ac5, ac6;
} bmp180_cal_t;

typedef struct {
    time_t timestamp;
    float  temperature;
    float  pressure;
} sensor_data_t;

static sensor_data_t  buffer[BUFFER_SIZE];
static int            buf_idx = 0;
static int            buf_count = 0;
static int            i2c_handle = -1;
static volatile sig_atomic_t running = 1;
static bmp180_cal_t   cal;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    if (i2cWriteByte(handle, reg) < 0) return -1;
    if (i2cReadDevice(handle, (char *)buf, len) != (int)len) return -1;
    return 0;
}

static int read_calibration(int handle, bmp180_cal_t *c) {
    uint8_t d[BMP180_CAL_BYTES];
    if (i2c_read_block(handle, BMP180_REG_CAL_START, d, BMP180_CAL_BYTES) < 0) return -1;
    c->ac1 = (int16_t)((d[0]  << 8) | d[1]);
    c->ac2 = (int16_t)((d[2]  << 8) | d[3]);
    c->ac3 = (int16_t)((d[4]  << 8) | d[5]);
    c->ac4 = (uint16_t)((d[6]  << 8) | d[7]);
    c->ac5 = (uint16_t)((d[8]  << 8) | d[9]);
    c->ac6 = (uint16_t)((d[10] << 8) | d[11]);
    c->b1  = (int16_t)((d[12] << 8) | d[13]);
    c->b2  = (int16_t)((d[14] << 8) | d[15]);
    c->mb  = (int16_t)((d[16] << 8) | d[17]);
    c->mc  = (int16_t)((d[18] << 8) | d[19]);
    c->md  = (int16_t)((d[20] << 8) | d[21]);
    if (c->ac1 == 0 && c->ac6 == 0) return -1;
    return 0;
}

static int read_raw_temp(int handle, int32_t *ut) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_TEMP) < 0) return -1;
    gpioDelay(5000);
    uint8_t d[2];
    if (i2c_read_block(handle, BMP180_REG_MSB, d, 2) < 0) return -1;
    *ut = (int32_t)((d[0] << 8) | d[1]);
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_CMD_PRESSURE + (OSS << 6)) < 0) return -1;
    gpioDelay(2000 + (3000 << OSS));
    uint8_t d[3];
    if (i2c_read_block(handle, BMP180_REG_MSB, d, 3) < 0) return -1;
    *up = ((int32_t)d[0] << 16 | (int32_t)d[1] << 8 | d[2]) >> (8 - OSS);
    return 0;
}

static float calc_temp(int32_t ut, const bmp180_cal_t *c) {
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    int32_t b5 = x1 + x2;
    return ((b5 + 8) >> 4) / 10.0f;
}

static float calc_pressure(int32_t up, int32_t ut, const bmp180_cal_t *c) {
    int32_t x1 = ((ut - (int32_t)c->ac6) * (int32_t)c->ac5) >> 15;
    int32_t x2 = ((int32_t)c->mc << 11) / (x1 + (int32_t)c->md);
    int32_t b5 = x1 + x2;
