    buffer[buf_idx].pressure    = p;
    buf_idx = (buf_idx + 1) % BUFFER_SIZE;
    if (buf_count < BUFFER_SIZE) buf_count++;
    printf("Timestamp: %ld, Temperature: %.2f C, Pressure: %.2f Pa\n",
           (long)now, t, p);
    if (t > TEMP_THRESHOLD) gpioWrite(FAN_GPIO, 1);
    else                    gpioWrite(FAN_GPIO, 0);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus 1 at 0x%02X\n", BMP180_ADDR);
        gpioTerminate();
        return 1;
    }
    if (read_calibration(i2c_handle, &cal) < 0) {
        fprintf(stderr, "Failed to read BMP180 calibration data\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    gpioSetMode(FAN_GPIO, PI_OUTPUT);
    gpioWrite(FAN_GPIO, 0);
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    if (gpioSetTimerFuncEx(0, SAMPLE_PERIOD_US, timer_callback, NULL) < 0) {
        fprintf(stderr, "Failed to set timer\n");
