#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define BMP180_ADDR 0x77
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE
#define BMP180_OSS 3
#define BMP180_TEMP_CMD 0x2E
#define BMP180_PRESS_CMD 0x34
#define GPIO_INTERRUPT 27
#define DEBOUNCE_US 200000
#define LOG_INTERVAL_S 2

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t logging_enabled = 0;
static volatile uint32_t last_interrupt_tick = 0;

static int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
static uint16_t ac4, ac5, ac6;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_i2c_word(int handle, uint8_t reg, int16_t *out) {
    int hi = i2cReadByteData(handle, reg);
    if (hi < 0) return -1;
    int lo = i2cReadByteData(handle, reg + 1);
    if (lo < 0) return -1;
    *out = (int16_t)((hi << 8) | lo);
    return 0;
}

static int read_i2c_word_u(int handle, uint8_t reg, uint16_t *out) {
    int hi = i2cReadByteData(handle, reg);
    if (hi < 0) return -1;
    int lo = i2cReadByteData(handle, reg + 1);
    if (lo < 0) return -1;
    *out = (uint16_t)((hi << 8) | lo);
    return 0;
}

static int read_calibration_data(int handle) {
    if (read_i2c_word(handle, BMP180_REG_CAL_AC1, &ac1) < 0) return -1;
    if (read_i2c_word(handle, BMP180_REG_CAL_AC2, &ac2) < 0) return -1;
    if (read_i2c_word(handle, BMP180_REG_CAL_AC3, &ac3) < 0) return -1;
    if (read_i2c_word_u(handle, BMP180_REG_CAL_AC4, &ac4) < 0) return -1;
    if (read_i2c_word_u(handle, BMP180_REG_CAL_AC5, &ac5) < 0) return -1;
    if (read_i2c_word_u(handle, BMP180_REG_CAL_AC6, &ac6) < 0) return -1;
    if (read_i2c_word(handle, BMP180_REG_CAL_B1, &b1) < 0) return -1;
    if (read_i2c_word(handle, BMP180_REG_CAL_B2, &b2) < 0) return -1;
    if (read_i2c_word(handle, BMP180_REG_CAL_MB, &mb) < 0) return -1;
    if (read_i2c_word(handle, BMP180_REG_CAL_MC, &mc) < 0) return -1;
    if (read_i2c_word(handle, BMP180_REG_CAL_MD, &md) < 0) return -1;
    return 0;
}

static int read_raw_temperature(int handle, int32_t *ut) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_TEMP_CMD) < 0) return -1;
    gpioDelay(5000);
    int msb = i2cReadByteData(handle, BMP180_REG_MSB);
    if (msb < 0) return -1;
    int lsb = i2cReadByteData(handle, BMP180_REG_LSB);
    if (lsb < 0) return -1;
    *ut = (int32_t)((msb << 8) | lsb);
    return 0;
}

static int read_raw_pressure(int handle, int32_t *up) {
    if (i2cWriteByteData(handle, BMP180_REG_CONTROL, BMP180_PRESS_CMD + (BMP180_OSS << 6)) < 0) return -1;
    gpioDelay(2000 + (3000 << BMP180_OSS));
    int msb = i2cReadByteData(handle, BMP180_REG_MSB);
    if (msb < 0) return -1;
    int lsb = i2cReadByteData(handle, BMP180_REG_LSB);
    if (lsb < 0) return -1;
    int xlsb = i2cReadByteData(handle, BMP180_REG_XLSB);
    if (xlsb < 0) return -1;
    *up = ((msb << 16) | (lsb << 8) | xlsb) >> (8 - BMP180_OSS);
    return 0;
}

static int32_t compute_b5(int32_t ut) {
    int32_t x1 = ((ut - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t x2 = ((int32_t)mc << 11) / (x1 + (int32_t)md);
    return x1 + x2;
}

static int32_t compute_pressure(int32_t up, int32_t b5) {
    int32_t b6 = b5 - 4000;
    int32_t x1 = ((int32_t)b2 * ((b6 * b6) >> 12)) >> 11;
    int32_t x2 = ((int32_t)ac2 * b6) >> 11;
    int32_t x3 = x1 + x2;
    int32_t b3 = (((((int32_t)ac1) * 4 + x3) << BMP180_OSS) + 2) >> 2;
    x1 = ((int32_t)ac3 * b6) >> 13;
    x2 = ((int32_t)b1 * ((b6 * b6) >> 12)) >> 16;
    x3 = ((x1 + x2) + 2) >> 2;
    uint32_t b4 = ((uint32_t)ac4 * (uint32_t)(x3 + 32768)) >> 15;
    uint32_t b7 = ((uint32_t)up - b3) * (50000 >> BMP180_OSS);
    int32_t p;
    if (b7 < 0x80000000) {
        p = (b7 * 2) / b4;
    } else {
        p = (b7 / b4) * 2;
    }
    x1 = (p >> 8) * (p >> 8);
    x1 = (x1 * 3038) >> 16;
    x2 = (-7357 * p) >> 16;
    p = p + ((x1 + x2 + 3791) >> 4);
    return p;
}

static void log_data(int32_t pressure) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, %d Pa\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    fclose(fp);
}

static void interrupt_handler(int gpio, int level, uint32_t tick, void *user) {
    (void)gpio; (void)level; (void)user;
    if (tick - last_interrupt_tick > DEBOUNCE_US) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
        last_interrupt_tick = tick;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return 1;
    }

    int handle = i2cOpen(1, BMP180_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    if (read_calibration_data(handle) < 0) {
        fprintf(stderr, "Failed to read calibration data\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_INTERRUPT, PI_INPUT);
    gpioSetPullUpDown(GPIO_INTERRUPT, PI_PUD_UP);
    if (gpioSetISRFuncEx(GPIO_INTERRUPT, FALLING_EDGE, 0, interrupt_handler, NULL) < 0) {
        fprintf(stderr, "Failed to set ISR\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("BMP180 logging started. Press button on GPIO27 to toggle logging.\n");

    while (running) {
        if (logging_enabled) {
            int32_t ut, up, b5, pressure;
            if (read_raw_temperature(handle, &ut) < 0) {
                fprintf(stderr, "Temperature read error: %s\n", strerror(errno));
                gpioDelay(1000000);
                continue;
            }
            if (read_raw_pressure(handle, &up) < 0) {
                fprintf(stderr, "Pressure read error: %s\n", strerror(errno));
                gpioDelay(1000000);
                continue;
            }
            b5 = compute_b5(ut);
            pressure = compute_pressure(up, b5);
            log_data(pressure);
        }
        gpioDelay(LOG_INTERVAL_S * 1000000);
    }

    printf("\nCleaning up...\n");
    gpioSetISRFuncEx(GPIO_INTERRUPT, FALLING_EDGE, 0, NULL, NULL);
    i2cClose(handle);
    gpioTerminate();
    return 0;
}

