/*
 * MAX31855 thermocouple PI controller with PWM heater control.
 *
 * Hardware (Raspberry Pi 3 Model B+):
 *   - MAX31855 SPI0 CE0  -> GPIO8  (physical pin 24)
 *   - MAX31855 SCLK     -> GPIO11 (physical pin 23)
 *   - MAX31855 CS       -> GPIO8  (physical pin 24, SPI0 CE0)
 *   - MAX31855 DO       -> GPIO9  (physical pin 21)
 *   - Heater relay      -> GPIO17 (physical pin 11) via NPN transistor/MOSFET
 *
 * Build:
 *   gcc -O2 -Wall -o heater_control heater_control.c -lpigpio -lrt
 *   (run as root, or ensure pigpio group access)
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL        0          /* SPI0 CE0  */
#define SPI_SPEED          2000000    /* 2 MHz     */
#define SPI_FLAGS          0          /* Mode 0, active-low CS handled by pigpio */

#define HEATER_GPIO        17         /* PWM-capable pin for relay */
#define PWM_FREQUENCY      1000       /* Hz */
#define PWM_RANGE          1000       /* duty 0..1000 -> 0..100 % */

#define TARGET_TEMP        25.0       /* °C */
#define MAX_DUTY_CYCLE     800        /* 80 % of PWM_RANGE */
#define LOG_FILE           "heater_log.csv"
#define SAMPLE_PERIOD_US   100000     /* 100 ms */

/* MAX31855 fault bits (D16..D18 of 32-bit SPI payload) */
#define FAULT_OPEN_CIRCUIT  0x01
#define FAULT_SHORT_GND     0x02
#define FAULT_SHORT_VCC     0x04

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Function prototypes -------------------------- */
static int  initialize(void);
static void cleanup(void);
static void signal_handler(int sig);
static int  read_max31855(uint32_t *raw);
static float convert_to_celsius(uint32_t raw);
static int  calculate_duty_cycle(float current_temp);
static int  set_heater_duty(int duty);
static int  log_data(float temp, int duty);
static void handle_fault(uint32_t raw);

/* ------------------------------- Signal ---------------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ----------------------------- Initialization ----------------------------- */
static int initialize(void)
{
    /* pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    /* Heater GPIO */
    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: cannot set GPIO%d as output.\n", HEATER_GPIO);
        gpioTerminate();
        return -1;
    }
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);
    if (set_heater_duty(0) < 0) {
        fprintf(stderr, "Error: cannot initialise PWM on GPIO%d.\n", HEATER_GPIO);
        gpioTerminate();
        return -1;
    }

    /* SPI */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: spiOpen failed (channel %d, %d Hz).\n",
                SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return -1;
    }

    /* Log file */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
        gpioTerminate();
        return -1;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,temperature_c,duty_cycle_pct\n");
        fflush(g_log_file);
    }

    return 0;
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    /* Ensure heater is off */
    if (g_spi_handle >= 0 || g_log_file != NULL) {
        set_heater_duty(0);
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- MAX31855 read ----------------------------- */
/*
 * Read 4 bytes from the MAX31855.
 * Returns 0 on success, -1 on SPI transfer failure.
 */
static int read_max31855(uint32_t *raw)
{
    char tx[4] = {0, 0, 0, 0};
    char rx[4] = {0, 0, 0, 0};

    int ret = spiXfer(g_spi_handle, tx, rx, 4);
    if (ret != 4) {
        fprintf(stderr, "Error: SPI transfer failed (returned %d).\n", ret);
        return -1;
    }

    *raw = ((uint32_t)(uint8_t)rx[0] << 24) |
           ((uint32_t)(uint8_t)rx[1] << 16) |
           ((uint32_t)(uint8_t)rx[2] <<  8) |
           ((uint32_t)(uint8_t)rx[3]);
    return 0;
}

/* --------------------------- Convert to °C ------------------------------- */
static float convert_to_celsius(uint32_t raw)
{
    /* D31..D18 = thermocouple temperature, 14-bit signed, 0.25 °C / LSB */
    int16_t temp_raw = (int16_t)((raw >> 18) & 0x3FFF);
    /* Sign-extend 14-bit value */
    if (temp_raw & 0x2000) {
        temp_raw |= 0xC000;
    }
    return (float)temp_raw * 0.25f;
}

/* ------------------------- PI controller (discrete) ----------------------- */
static int calculate_duty_cycle(float current_temp)
{
    static float integral = 0.0f;
    static float prev_error = 0.0f;
    const float Kp = 1.0f;
    const float Ki = 0.1f;
    const float dt = 0.1f;  /* seconds */

    float error = TARGET_TEMP - current_temp;

    /* Proportional */
    float P = Kp * error;

    /* Integral with anti-windup clamping */
    integral += Ki * error * dt;
    if (integral > 100.0f) integral = 100.0f;
    if (integral < 0.0f)   integral = 0.0f;

    /* PI output */
    float output = P + integral;

    /* Clamp to valid range */
    if (output > 100.0f) output = 100.0f;
    if (output < 0.0f)   output = 0.0f;

    /* Convert to duty cycle (0..PWM_RANGE) */
    int duty = (int)(output * (PWM_RANGE / 100.0f));
    if (duty > MAX_DUTY_CYCLE) duty = MAX_DUTY_CYCLE;

    return duty;
}

/* ----------------------------- Set heater PWM ---------------------------- */
static int set_heater_duty(int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(HEATER_GPIO, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM failed for GPIO%d.\n", HEATER_GPIO);
        return -1;
    }
    return 0;
}

/* ------------------------------- Log data -------------------------------- */
static int log_data(float temp, int duty)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error: time() failed.\n");
        return -1;
    }

    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    if (t == NULL) {
        fprintf(stderr, "Error: localtime_r() failed.\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t) == 0) {
        fprintf(stderr, "Error: strftime() failed.\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s,%.2f,%d\n", ts, temp, duty) < 0) {
        fprintf(stderr, "Error: writing to log file failed.\n");
        return -1;
    }
    fflush(g_log_file);
    return 0;
}

/* --------------------------- Handle MAX31855 fault ----------------------- */
static void handle_fault(uint32_t raw)
{
    uint8_t fault = (uint8_t)((raw >> 16) & 0x07);
    if (fault == 0) return;

    fprintf(stderr, "MAX31855 fault detected (0x%02X):", fault);
    if (fault & FAULT_OPEN_CIRCUIT)  fprintf(stderr, " open circuit");
    if (fault & FAULT_SHORT_GND)     fprintf(stderr, " short to GND");
    if (fault & FAULT_SHORT_VCC)     fprintf(stderr, " short to VCC");
    fprintf(stderr, ".\n");

    /* Safety: turn off heater immediately */
    set_heater_duty(0);
    log_data(-999.0f, 0);  /* -999 sentinel for error */
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    printf("Heater control started. Target: %.1f °C, Max duty: %d%%\n",
           TARGET_TEMP, MAX_DUTY_CYCLE / 10);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        uint32_t raw = 0;

        if (read_max31855(&raw) != 0) {
            /* SPI error: turn off heater and log, then retry */
            set_heater_duty(0);
            log_data(-999.0f, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Check fault bit (D16) */
        if (raw & 0x00010000) {
            handle_fault(raw);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float temp = convert_to_celsius(raw);
        int duty   = calculate_duty_cycle(temp);

        if (set_heater_duty(duty) != 0) {
            fprintf(stderr, "Warning: failed to set heater duty.\n");
        }

        if (log_data(temp, duty) != 0) {
            fprintf(stderr, "Warning: failed to log data.\n");
        }

        printf("T=%.2f °C  duty=%d%%\n", temp, duty / 10);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

