        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    printf("Heater control started. Target: %.1f °C, Max duty: %d%%\n",
           TARGET_TEMP, MAX_DUTY_CYCLE / 10);
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        uint32_t raw = 0;

        if (read_max31855(&raw) != 0) {
            /* SPI error: turn off heater and log, then retry */
            set_heater_duty(0);
            log_data(-999.0f, 0);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Check fault bit (D16) */
        if (raw & 0x00010000) {
            handle_fault(raw);
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        float temp = convert_to_celsius(raw);
        int duty   = calculate_duty_cycle(temp);

        if (set_heater_duty(duty) != 0) {
            fprintf(stderr, "Warning: failed to set heater duty.\n");
        }

        if (log_data(temp, duty) != 0) {
            fprintf(stderr, "Warning: failed to log data.\n");
        }

        printf("T=%.2f °C  duty=%d%%\n", temp, duty / 10);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

