#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_led_color(int r, int g, int b) {
    if (gpioPWM(RED_PIN,   PWM_RANGE - r) < 0) return -1;
    if (gpioPWM(GREEN_PIN, PWM_RANGE - g) < 0) return -1;
    if (gpioPWM(BLUE_PIN,  PWM_RANGE - b) < 0) return -1;
    return 0;
}

static int read_temperature(void) {
    FILE *fp = fopen(TEMP_FILE, "r");
    if (!fp) {
        perror("Error opening temperature file");
        return -1;
    }
    int temp;
    if (fscanf(fp, "%d", &temp) != 1) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }
    if (ferror(fp)) {
        fprintf(stderr, "Error reading temperature from file\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    return temp;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RED_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(GREEN_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(BLUE_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Failed to set PWM range\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("Failed to set signal handler");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int temp = read_temperature();
        if (temp < 0) {
            fprintf(stderr, "Error reading temperature, skipping update\n");
            usleep(500000);
            continue;
        }

        int r, g, b;
        if (temp < 40000) {
            r = 0; g = 0; b = 255; /* Blue */
        } else if (temp < 60000) {
            r = 0; g = 255; b = 0;   /* Green */
        } else {
            r = 255; g = 0; b = 0;   /* Red */
        }

        if (set_led_color(r, g, b) < 0) {
            fprintf(stderr, "Failed to set LED color\n");
            gpioTerminate();
            return EXIT_FAILURE;
        }

        printf("Temperature: %d mC, R: %d, G: %d, B: %d\n", temp, r, g, b);
        fflush(stdout);
        usleep(500000);
    }

    /* Graceful shutdown: turn off LED and release pigpio */
    set_led_color(0, 0, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

