#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define SERVER_URL "yourserver.com"
#define SERVER_PORT 80
#define API_ENDPOINT "/api/humidity"
#define TIMEOUT_US 200

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int wait_for_level(int gpio, int level, uint32_t timeout_us) {
    uint32_t start = gpioTick();
    while (gpioRead(gpio) != level) {
        if ((gpioTick() - start) > timeout_us) return -1;
    }
    return 0;
}

static int read_dht22(float *temperature, float *humidity) {
    uint8_t data[5] = {0};
    int i;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, 0);
    gpioDelay(2000);
    gpioWrite(DHT22_GPIO, 1);
    gpioDelay(30);
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    if (wait_for_level(DHT22_GPIO, 0, TIMEOUT_US) < 0) return -1;
    if (wait_for_level(DHT22_GPIO, 1, TIMEOUT_US) < 0) return -1;
    if (wait_for_level(DHT22_GPIO, 0, TIMEOUT_US) < 0) return -1;

    for (i = 0; i < 40; i++) {
        if (wait_for_level(DHT22_GPIO, 1, TIMEOUT_US) < 0) return -1;
        uint32_t start = gpioTick();
        if (wait_for_level(DHT22_GPIO, 0, TIMEOUT_US) < 0) return -1;
        uint32_t duration = gpioTick() - start;
        data[i / 8] <<= 1;
        if (duration > 50) data[i / 8] |= 1;
    }

    if (data[4] != ((data[0] + data[1] + data[2] + data[3]) & 0xFF)) return -2;

    *humidity = (float)((data[0] << 8) | data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0;
    if (data[2] & 0x80) *temperature *= -1;

    return 0;
}

static int post_data(float temperature, float humidity) {
    int sockfd = socket(AF_INET, SOCK_STREAM, 0);
    if (sockfd < 0) { perror("socket"); return -1; }

    struct sockaddr_in serv_addr;
    memset(&serv_addr, 0, sizeof(serv_addr));
    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_URL, &serv_addr.sin_addr) <= 0) {
        perror("inet_pton"); close(sockfd); return -1;
    }

    if (connect(sockfd, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("connect"); close(sockfd); return -1;
    }

    char payload[256];
    snprintf(payload, sizeof(payload),
             "POST %s HTTP/1.1\r\nHost: %s\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n{\"temperature\":%.1f,\"humidity\":%.1f}",
             API_ENDPOINT, SERVER_URL, strlen(payload) - 2, temperature, humidity);

    if (send(sockfd, payload, strlen(payload), 0) < 0) {
        perror("send"); close(sockfd); return -1;
    }

    char buffer[1024];
    ssize_t bytes = recv(sockfd, buffer, sizeof(buffer) - 1, 0);
    if (bytes < 0) { perror("recv"); close(sockfd); return -1; }
    buffer[bytes] = '\0';

    close(sockfd);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    float temperature, humidity;
    int retries;

    while (running) {
        retries = 0;
        int result = -1;

        while (retries < MAX_RETRIES && running) {
            result = read_dht22(&temperature, &humidity);
            if (result == 0) break;
            retries++;
            if (retries < MAX_RETRIES) gpioDelay(2000000);
        }

        if (result == 0) {
            if (post_data(temperature, humidity) == 0) {
                printf("Temperature: %.1f C, Humidity: %.1f %%\n", temperature, humidity);
            } else {
                fprintf(stderr, "Failed to post data\n");
            }
        } else {
            fprintf(stderr, "Failed to read DHT22 after %d retries (code %d)\n", MAX_RETRIES, result);
        }

        if (running) gpioDelay(60000000);
    }

    gpioTerminate();
    return 0;
}

