#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <getopt.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY 2
#define READ_INTERVAL 10
#define DHT_TIMEOUT 1000000
#define DHT_MAX_EDGES 85

static volatile sig_atomic_t running = 1;
static char *api_url = "http://your-the-library's-API-call.com/api/humidity";

typedef struct {
    float temperature;
    float humidity;
} DHT22Data;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }
    gpioSetMode(DHT22_GPIO, PI_INPUT);
    return 0;
}

static int read_dht22(DHT22Data *data) {
    int edges[DHT_MAX_EDGES];
    int edge_count = 0;
    int last_state = PI_HIGH;
    uint32_t start_tick, current_tick;

    gpioSetMode(DHT22_GPIO, PI_OUTPUT);
    gpioWrite(DHT22_GPIO, PI_LOW);
    gpioDelay(1000);
    gpioWrite(DHT22_GPIO, PI_HIGH);
    gpioDelay(30);
    gpioSetMode(DHT22_GPIO, PI_INPUT);

    start_tick = gpioTick();
    while (gpioRead(DHT22_GPIO) == PI_HIGH) {
        if (gpioTick() - start_tick > DHT_TIMEOUT) {
            syslog(LOG_ERR, "DHT22: timeout waiting for response low");
            return -1;
        }
    }
    while (gpioRead(DHT22_GPIO) == PI_LOW) {
        if (gpioTick() - start_tick > DHT_TIMEOUT) {
            syslog(LOG_ERR, "DHT22: timeout waiting for response high");
            return -1;
        }
    }

    while (edge_count < DHT_MAX_EDGES && running) {
        last_state = gpioRead(DHT22_GPIO);
        current_tick = gpioTick();
        if (current_tick - start_tick > DHT_TIMEOUT) {
            syslog(LOG_ERR, "DHT22: timeout during edge capture");
            return -1;
        }
        if (gpioRead(DHT22_GPIO) != last_state) {
            edges[edge_count++] = current_tick - start_tick;
            start_tick = current_tick;
        }
    }

    if (edge_count < 40) {
        syslog(LOG_ERR, "DHT22: insufficient edges captured (%d)", edge_count);
        return -1;
    }

    unsigned char bytes[5] = {0};
    for (int i = 0; i < 40; i++) {
        int high_us = edges[2 * i + 1];
        if (high_us > 50) {
            bytes[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    if (bytes[4] != ((bytes[0] + bytes[1] + bytes[2] + bytes[3]) & 0xFF)) {
        syslog(LOG_ERR, "DHT22: checksum mismatch");
        return -1;
    }

    data->humidity = (float)((bytes[0] << 8) | bytes[1]) / 10.0;
    data->temperature = (float)(((bytes[2] & 0x7F) << 8) | bytes[3]) / 10.0;
    if (bytes[2] & 0x80) {
        data->temperature = -data->temperature;
    }
    return 0;
}

static int format_json(const DHT22Data *data, char *buffer, size_t buffer_size) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    if (t == NULL) {
        syslog(LOG_ERR, "localtime failed: %s", strerror(errno));
        return -1;
    }
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", t);
    int n = snprintf(buffer, buffer_size,
                     "{\"timestamp\":\"%s\",\"temperature\":%.1f,\"humidity\":%.1f}",
                     timestamp, data->temperature, data->humidity);
    if (n < 0 || (size_t)n >= buffer_size) {
        syslog(LOG_ERR, "JSON formatting failed");
        return -1;
    }
    return 0;
}

static int post_data(const char *json_data) {
    FILE *fp = popen("curl -s -X POST -H 'Content-Type: application/json' -d", "w");
    if (fp == NULL) {
        syslog(LOG_ERR, "popen failed: %s", strerror(errno));
        return -1;
    }
    fprintf(fp, "%s", json_data);
    pclose(fp);
    return 0;
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "s:")) != -1) {
        switch (opt) {
            case 's':
                api_url = optarg;
                break;
            default:
                fprintf(stderr, "Usage: %s [-s api_url]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    openlog("dht22_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting DHT22 monitor (GPIO%d, URL: %s)", DHT22_GPIO, api_url);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    while (running) {
        DHT22Data data;
        int success = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (read_dht22(&data) == 0) {
                success = 1;
                break;
            }
            syslog(LOG_WARNING, "DHT22 read failed (attempt %d/%d)", attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1) {
                sleep(RETRY_DELAY);
            }
        }

        if (!success) {
            syslog(LOG_ERR, "DHT22 read failed after %d attempts, skipping", MAX_RETRIES);
            for (int i = 0; i < READ_INTERVAL && running; i++) {
                sleep(1);
            }
            continue;
        }

        char json_data[256];
        if (format_json(&data, json_data, sizeof(json_data)) != 0) {
            syslog(LOG_ERR, "JSON formatting failed, skipping");
            for (int i = 0; i < READ_INTERVAL && running; i++) {
                sleep(1);
            }
            continue;
        }

        int post_success = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && running; attempt++) {
            if (post_data(json_data) == 0) {
                post_success = 1;
                break;
            }
            syslog(LOG_WARNING, "POST failed (attempt %d/%d)", attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1) {
                sleep(RETRY_DELAY);
            }
        }

        if (!post_success) {
            syslog(LOG_ERR, "POST failed after %d attempts", MAX_RETRIES);
        }

        for (int i = 0; i < READ_INTERVAL && running; i++) {
            sleep(1);
        }
    }

    gpioTerminate();
    curl_global_cleanup();
    syslog(LOG_INFO, "DHT22 monitor stopped");
    closelog();
    return EXIT_SUCCESS;
}

