#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#define CPU_TEMP_PATH "/sys/class/thermal/thermal_zone0/temp"
#define FAN_STATE_PATH "/sys/class/thermal/cooling_device0/cur_state"
#define FAN_LOG_PATH "/var/log/fan_control.log"
#define POLL_INTERVAL_SEC 5
#define TEMP_THRESHOLD_1 45000
#define TEMP_THRESHOLD_2 55000
#define TEMP_THRESHOLD_3 65000

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int read_cpu_temp(int *out_temp) {
    FILE *fp = fopen(CPU_TEMP_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", CPU_TEMP_PATH, strerror(errno));
        return -1;
    }

    char buffer[16];
    if (!fgets(buffer, sizeof(buffer), fp)) {
        fprintf(stderr, "Error reading %s: %s\n", CPU_TEMP_PATH, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *endptr = NULL;
    long val = strtol(buffer, &endptr, 10);
    if (endptr == buffer) {
        fprintf(stderr, "Error parsing temperature value from %s\n", CPU_TEMP_PATH);
        return -1;
    }

    *out_temp = (int)val;
    return 0;
}

static int read_fan_state(int *out_state) {
    FILE *fp = fopen(FAN_STATE_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", FAN_STATE_PATH, strerror(errno));
        return -1;
    }

    char buffer[16];
    if (!fgets(buffer, sizeof(buffer), fp)) {
        fprintf(stderr, "Error reading %s: %s\n", FAN_STATE_PATH, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *endptr = NULL;
    long val = strtol(buffer, &endptr, 10);
    if (endptr == buffer) {
        fprintf(stderr, "Error parsing fan state from %s\n", FAN_STATE_PATH);
        return -1;
    }

    *out_state = (int)val;
    return 0;
}

static int write_fan_state(int state) {
    FILE *fp = fopen(FAN_STATE_PATH, "w");
    if (!fp) {
        fprintf(stderr, "Error opening %s for writing: %s\n", FAN_STATE_PATH, strerror(errno));
        return -1;
    }

    if (fprintf(fp, "%d", state) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", FAN_STATE_PATH, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", FAN_STATE_PATH, strerror(errno));
        return -1;
    }

    return 0;
}

static int get_max_fan_state(int *out_max_state) {
    FILE *fp = fopen(FAN_STATE_PATH, "r");
    if (!fp) {
        fprintf(stderr, "Error opening %s for max_state read: %s\n", FAN_STATE_PATH, strerror(errno));
        return -1;
    }

    char buffer[16];
    if (!fgets(buffer, sizeof(buffer), fp)) {
        fprintf(stderr, "Error reading %s for max_state: %s\n", FAN_STATE_PATH, strerror(errno));
        fclose(fp);
        return -1;
    }
    fclose(fp);

    char *endptr = NULL;
    long val = strtol(buffer, &endptr, 10);
    if (endptr == buffer) {
        fprintf(stderr, "Error parsing max_state from %s\n", FAN_STATE_PATH);
        return -1;
    }

    *out_max_state = (int)val;
    return 0;
}

static int determine_fan_speed(int cpu_temp, int max_state) {
    if (cpu_temp < TEMP_THRESHOLD_1) {
        return 0;
    } else if (cpu_temp < TEMP_THRESHOLD_2) {
        return 1;
    } else if (cpu_temp < TEMP_THRESHOLD_3) {
        return 2;
    } else {
        return max_state;
    }
}

static int log_fan_speed_change(int new_state) {
    FILE *fp = fopen(FAN_LOG_PATH, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s for logging: %s\n", FAN_LOG_PATH, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d - Fan speed set to: %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, new_state);

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", FAN_LOG_PATH, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Error registering SIGTERM handler: %s\n", strerror(errno));
        return 1;
    }

    int max_state = 0;
    if (get_max_fan_state(&max_state) != 0) {
        fprintf(stderr, "Failed to determine max fan state. Exiting.\n");
        return 1;
    }

    int current_fan_state = -1;
    if (read_fan_state(&current_fan_state) != 0) {
        fprintf(stderr, "Failed to read initial fan state. Exiting.\n");
        return 1;
    }

    printf("Fan control started. Initial fan state: %d (max: %d)\n", current_fan_state, max_state);

    while (g_running) {
        int cpu_temp = 0;
        if (read_cpu_temp(&cpu_temp) != 0) {
            fprintf(stderr, "Failed to read CPU temperature. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        int new_fan_speed = determine_fan_speed(cpu_temp, max_state);

        if (new_fan_speed != current_fan_state) {
            if (write_fan_state(new_fan_speed) == 0) {
                current_fan_state = new_fan_speed;
                if (log_fan_speed_change(new_fan_speed) != 0) {
                    fprintf(stderr, "Warning: Failed to log fan speed change.\n");
                }
            } else {
                fprintf(stderr, "Failed to write new fan state. Retrying in %d seconds.\n", POLL_INTERVAL_SEC);
            }
        }

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nShutting down...\n");
    if (write_fan_state(0) == 0) {
        printf("Fan set to OFF (state 0).\n");
        if (log_fan_speed_change(0) != 0) {
            fprintf(stderr, "Warning: Failed to log shutdown event.\n");
        }
    } else {
        fprintf(stderr, "Failed to set fan to OFF during shutdown.\n");
    }

    return 0;
}

