/*
 * PID Heater Controller for Raspberry Pi Zero W
 *
 * Hardware:
 *   - MAX31855 thermocouple amplifier on SPI0 (CLK=GPIO11, CS=GPIO8/CE0, DO=GPIO9)
 *   - Resistive heater on GPIO18 (hardware PWM, 1 kHz, 0-100% duty)
 *
 * Build:
 *   gcc -O2 -Wall -o heater_controller heater_controller.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for hardware PWM).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define HEATER_GPIO          18
#define PWM_FREQUENCY        1000          /* Hz  */
#define PWM_RANGE            100           /* %   */
#define SPI_CHANNEL          0             /* CE0 on GPIO8 */
#define SPI_SPEED            500000        /* 500 kHz */
#define SPI_FLAGS            0             /* Mode 0, active-low CS */
#define TARGET_TEMPERATURE   50.0          /* °C  */
#define LOG_FILE             "heater_log.txt"
#define SAMPLE_PERIOD_US     1000000       /* 1 s */

/* PID gains */
#define KP                   1.0
#define KI                   0.1
#define KD                   0.01

/* Failsafe / safety thresholds */
#define MAX_TEMPERATURE      100.0         /* °C  */
#define MIN_TEMPERATURE      0.0           /* °C  */

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_spi_handle = -1;
static FILE *g_log_file  = NULL;

/* PID state */
static double g_integral   = 0.0;
static double g_previous_error = 0.0;

/* --------------------------- Function prototypes -------------------------- */
static void signal_handler(int sig);
static int  initialize(void);
static void cleanup(void);
static int  read_temperature(double *temperature);
static void set_heater_pwm(int duty_percent);
static double calculate_pid(double current_temp);
static void log_data(double temp, int duty, double pid_out);
static void handle_fault(uint8_t fault_bits);

/* ------------------------------- Signal handler --------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Initialization --------------------------- */
static int initialize(void)
{
    /* --- pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    /* --- Heater GPIO (hardware PWM) --- */
    if (gpioSetMode(HEATER_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n", HEATER_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO%d.\n", HEATER_GPIO);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(HEATER_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO%d.\n", HEATER_GPIO);
        gpioTerminate();
        return -1;
    }

    /* --- SPI --- */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (channel %d, %d Hz).\n",
                SPI_CHANNEL, SPI_SPEED);
        gpioTerminate();
        return -1;
    }

    /* --- Log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
        gpioTerminate();
        return -1;
    }

    /* Write CSV header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,Temperature_C,Duty_Percent,PID_Output\n");
        fflush(g_log_file);
    }

    return 0;
}

/* -------------------------------- Cleanup -------------------------------- */
static void cleanup(void)
{
    /* Disable heater */
    if (g_spi_handle >= 0 || g_log_file != NULL) {
        gpioPWM(HEATER_GPIO, 0);
    }

    if (g_spi_handle >= 0) {
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* --------------------------- Read temperature ----------------------------- */
/*
 * MAX31855 32-bit SPI payload (MSB first):
 *   D[31:18]  Thermocouple temperature, signed, 0.25 °C / count
 *   D[17:4]   Internal cold-junction temperature, signed, 0.0625 °C / count
 *   D[3]      Reserved
 *   D[2]      SCV fault (short to VCC)
 *   D[1]      SCG fault (short to GND)
 *   D[0]      OC  fault (open circuit)
 */
static int read_temperature(double *temperature)
{
    char rx[4] = {0, 0, 0, 0};

    int bytes = spiRead(g_spi_handle, rx, 4);
    if (bytes != 4) {
        fprintf(stderr, "Error: SPI read returned %d bytes (expected 4).\n", bytes);
        return -1;
    }

    uint32_t raw = ((uint32_t)(uint8_t)rx[0] << 24) |
                   ((uint32_t)(uint8_t)rx[1] << 16) |
                   ((uint32_t)(uint8_t)rx[2] << 8)  |
                   ((uint32_t)(uint8_t)rx[3]);

    /* Fault bits are the two LSBs of byte 3 */
    uint8_t fault_bits = raw & 0x03;
    if (fault_bits != 0) {
        handle_fault(fault_bits);
        return -1;
    }

    /*
     * Thermocouple temperature: bits 31:18, signed 14-bit, 0.25 °C / count.
     * Shift right 18 to get the 14-bit signed value, then scale.
     */
    int16_t temp_raw = (int16_t)((raw >> 18) & 0x3FFF);
    if (temp_raw & 0x2000) {
        temp_raw |= 0xC000;          /* sign-extend 14-bit to 16-bit */
    }
    *temperature = (double)temp_raw * 0.25;

    return 0;
}

/* --------------------------- Handle MAX31855 faults ---------------------- */
static void handle_fault(uint8_t fault_bits)
{
    const char *msg = NULL;

    switch (fault_bits) {
        case 0x01: msg = "MAX31855 fault: short to VCC (SCV)"; break;
        case 0x02: msg = "MAX31855 fault: short to GND (SCG)"; break;
        case 0x03: msg = "MAX31855 fault: open circuit (OC)"; break;
        default:   msg = "MAX31855 unknown fault"; break;
    }

    fprintf(stderr, "%s\n", msg);

    if (g_log_file != NULL) {
        time_t now = time(NULL);
        struct tm tm_buf;
        struct tm *t = localtime_r(&now, &tm_buf);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
        fprintf(g_log_file, "%s,FAULT,%s\n", ts, msg);
        fflush(g_log_file);
    }

    /* Safety: disable heater and reset PID state */
    gpioPWM(HEATER_GPIO, 0);
    g_integral        = 0.0;
    g_previous_error  = 0.0;
}

/* --------------------------- Set heater PWM ------------------------------- */
static void set_heater_pwm(int duty_percent)
{
    if (duty_percent < 0)   duty_percent = 0;
    if (duty_percent > 100) duty_percent = 100;

    if (gpioPWM(HEATER_GPIO, duty_percent) < 0) {
        fprintf(stderr, "Warning: gpioPWM failed for duty %d%%.\n", duty_percent);
    }
}

/* ----------------------------- PID calculation ---------------------------- */
static double calculate_pid(double current_temp)
{
    double error = TARGET_TEMPERATURE - current_temp;

    /* Proportional */
    double P = KP * error;

    /* Integral (anti-windup: clamp integral to prevent excessive accumulation) */
    g_integral += error;
    if (g_integral > 100.0)  g_integral = 100.0;
    if (g_integral < -100.0) g_integral = -100.0;
    double I = KI * g_integral;

    /* Derivative */
    double D = KD * (error - g_previous_error);
    g_previous_error = error;

    double output = P + I + D;

    /* Clamp output to valid PWM range */
    if (output < 0.0)   output = 0.0;
    if (output > 100.0) output = 100.0;

    return output;
}

/* ------------------------------- Log data --------------------------------- */
static void log_data(double temp, int duty, double pid_out)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s,%.2f,%d,%.2f\n", ts, temp, duty, pid_out);
    fflush(g_log_file);
}

/* --------------------------------- Main ----------------------------------- */
int main(void)
{
    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize() != 0) {
        return EXIT_FAILURE;
    }

    printf("Heater PID controller started. Target: %.1f °C. Press Ctrl+C to exit.\n",
           TARGET_TEMPERATURE);

    while (g_running) {
        double temperature = 0.0;

        if (read_temperature(&temperature) != 0) {
            /* Sensor fault already handled; wait and retry */
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        /* Failsafe: disable heater if temperature out of range */
        if (temperature > MAX_TEMPERATURE || temperature < MIN_TEMPERATURE) {
            fprintf(stderr, "Failsafe: temperature %.2f °C out of range [%.1f, %.1f]. "
                            "Disabling heater.\n",
                    temperature, MIN_TEMPERATURE, MAX_TEMPERATURE);
            gpioPWM(HEATER_GPIO, 0);
            g_integral        = 0.0;
            g_previous_error  = 0.0;
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double pid_output = calculate_pid(temperature);
        set_heater_pwm((int)pid_output);

        log_data(temperature, (int)pid_output, pid_output);

        printf("T=%.2f °C  Duty=%3d%%  PID=%.2f\n",
               temperature, (int)pid_output, pid_output);

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

