/*
 * Noctua NF-A4x10 5V PWM Fan Controller for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   Fan PWM signal  -> GPIO18 (physical pin 12)
 *   Fan GND         -> GND
 *   Fan 5V          -> 5V (external 5V supply recommended; do NOT power the fan
 *                        directly from the Pi 5V pin)
 *
 * Behavior:
 *   Polls CPU temperature every 5 seconds.
 *   Maps 40 C -> 0 % duty, 70 C -> 100 % duty, linearly in between.
 *   Logs timestamp, temperature, and duty cycle to cooling_log.csv.
 *   Handles SIGINT/SIGTERM for graceful shutdown.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define FAN_GPIO          18
#define PWM_FREQUENCY     25000   /* 25 kHz — Noctua NF-A4x10 PWM input */
#define PWM_RANGE         1000    /* 0..1000 -> 0.0..100.0 % duty */
#define TEMP_MIN          40.0f   /* °C — fan off below this */
#define TEMP_MAX          70.0f   /* °C — full speed above this */
#define POLL_INTERVAL_S   5       /* seconds between readings */
#define LOG_FILE          "cooling_log.csv"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Temperature reading                                                 */
/* ------------------------------------------------------------------ */
static float read_cpu_temperature(void)
{
    FILE *fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (!fp) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        return -1.0f;
    }

    int temp_milli_c;
    if (fscanf(fp, "%d", &temp_milli_c) != 1) {
        fprintf(stderr, "Error reading temperature value\n");
        fclose(fp);
        return -1.0f;
    }

    fclose(fp);
    return (float)temp_milli_c / 1000.0f;
}

/* ------------------------------------------------------------------ */
/* PWM control                                                         */
/* ------------------------------------------------------------------ */
static int set_fan_speed(float temperature)
{
    float duty_percent;

    if (temperature <= TEMP_MIN) {
        duty_percent = 0.0f;
    } else if (temperature >= TEMP_MAX) {
        duty_percent = 100.0f;
    } else {
        duty_percent = (temperature - TEMP_MIN) /
                       (TEMP_MAX - TEMP_MIN) * 100.0f;
    }

    int duty = (int)(duty_percent * (float)PWM_RANGE / 100.0f);
    if (duty < 0)          duty = 0;
    if (duty > PWM_RANGE)  duty = PWM_RANGE;

    if (gpioPWM(FAN_GPIO, duty) != 0) {
        fprintf(stderr, "Error setting PWM duty cycle to %d\n", duty);
        return -1;
    }

    return duty;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static int log_data(float temperature, int duty_cycle)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error getting local time\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f,%d\n", timestamp, temperature, duty_cycle) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure fan is off before releasing resources */
    gpioPWM(FAN_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO18 for hardware PWM --- */
    if (gpioSetMode(FAN_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", FAN_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(FAN_GPIO, PWM_FREQUENCY) != PWM_FREQUENCY) {
        fprintf(stderr, "Warning: could not set PWM frequency to %d Hz\n",
                PWM_FREQUENCY);
    }

    if (gpioSetPWMrange(FAN_GPIO, PWM_RANGE) != PWM_RANGE) {
        fprintf(stderr, "Warning: could not set PWM range to %d\n", PWM_RANGE);
    }

    /* --- Write CSV header if file is new/empty --- */
    {
        FILE *fp = fopen(LOG_FILE, "r");
        if (!fp) {
            /* File does not exist yet — create and write header */
            fp = fopen(LOG_FILE, "w");
            if (fp) {
                fprintf(fp, "timestamp,temperature_c,duty_cycle_pct\n");
                fclose(fp);
            } else {
                fprintf(stderr, "Warning: could not create log file '%s': %s\n",
                        LOG_FILE, strerror(errno));
            }
        } else {
            fclose(fp);
        }
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler: %s\n",
                strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler: %s\n",
                strerror(errno));
    }

    printf("Fan controller started. GPIO%d @ %d Hz, range %d.\n",
           FAN_GPIO, PWM_FREQUENCY, PWM_RANGE);
    printf("Logging to '%s'. Press Ctrl+C to exit.\n", LOG_FILE);

    /* --- Main control loop --- */
    while (g_running) {
        float temperature = read_cpu_temperature();
        if (temperature < 0.0f) {
            fprintf(stderr, "Failed to read temperature. Retrying in %d s.\n",
                    POLL_INTERVAL_S);
            sleep(POLL_INTERVAL_S);
            continue;
        }

        int duty_cycle = set_fan_speed(temperature);
        if (duty_cycle < 0) {
            fprintf(stderr, "Failed to set fan speed. Retrying in %d s.\n",
                    POLL_INTERVAL_S);
            sleep(POLL_INTERVAL_S);
            continue;
        }

        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Failed to log data.\n");
        }

        printf("Temp: %.2f C  Duty: %d/%d (%.1f%%)\n",
               temperature, duty_cycle, PWM_RANGE,
               (float)duty_cycle / (float)PWM_RANGE * 100.0f);

        sleep(POLL_INTERVAL_S);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Fan controller stopped.\n");
    return EXIT_SUCCESS;
}

