#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define SLF3S_ADDR_1 0x39
#define SLF3S_ADDR_2 0x3A
#define LOG_FILE "flow_log.txt"
#define MAX_RETRIES 3
#define POLL_INTERVAL_US 1000000

static volatile sig_atomic_t running = 1;
static int i2c_handle_1 = -1;
static int i2c_handle_2 = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int bit = 0; bit < 8; bit++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

static int read_flow_rate(int handle, float *flow_rate) {
    uint8_t buf[3];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        int bytes_read = i2cReadDevice(handle, (char *)buf, 3);
        if (bytes_read == 3) {
            if (crc8(buf, 2) == buf[2]) {
                int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
                *flow_rate = (float)raw / 100.0f;
                return 0;
            } else {
                fprintf(stderr, "CRC mismatch on handle %d (attempt %d)\n", handle, retries + 1);
            }
        } else {
            fprintf(stderr, "I2C read error on handle %d: %d (attempt %d)\n", handle, bytes_read, retries + 1);
        }
        retries++;
        gpioDelay(10000);
    }
    return -1;
}

static int log_flow_rates(float flow1, float flow2) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle_1 = i2cOpen(I2C_BUS, SLF3S_ADDR_1, 0);
    if (i2c_handle_1 < 0) {
        fprintf(stderr, "Failed to open I2C device 1 (addr 0x%02X): %d\n", SLF3S_ADDR_1, i2c_handle_1);
        gpioTerminate();
        return 1;
    }

    i2c_handle_2 = i2cOpen(I2C_BUS, SLF3S_ADDR_2, 0);
    if (i2c_handle_2 < 0) {
        fprintf(stderr, "Failed to open I2C device 2 (addr 0x%02X): %d\n", SLF3S_ADDR_2, i2c_handle_2);
        i2cClose(i2c_handle_1);
        gpioTerminate();
        return 1;
    }

    while (running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int ok1 = read_flow_rate(i2c_handle_1, &flow1);
        int ok2 = read_flow_rate(i2c_handle_2, &flow2);

        if (ok1 == 0 && ok2 == 0) {
            if (log_flow_rates(flow1, flow2) != 0) {
                fprintf(stderr, "Failed to log flow rates\n");
            }
        } else {
            fprintf(stderr, "Skipping log entry due to sensor read failure\n");
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    if (i2c_handle_1 >= 0) i2cClose(i2c_handle_1);
    if (i2c_handle_2 >= 0) i2cClose(i2c_handle_2);
    gpioTerminate();
    return 0;
}

