#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

#define ENCODER_A_PIN 17
#define ENCODER_B_PIN 18
#define LOG_FILE "encoder_log.txt"
#define PULSES_PER_REVOLUTION 360.0f
#define DEBOUNCE_DELAY_US 1000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_encoder(int a_pin, int b_pin) {
    int a = gpioRead(a_pin);
    int b = gpioRead(b_pin);
    if (a < 0 || b < 0) {
        fprintf(stderr, "Error reading GPIO pins: %d, %d\n", a, b);
        return -1;
    }
    return (a << 1) | b;
}

static float calculate_angle(int pulses) {
    float angle = ((float)pulses / PULSES_PER_REVOLUTION) * 360.0f;
    if (angle < 0.0f) angle += 360.0f;
    if (angle >= 360.0f) angle -= 360.0f;
    return angle;
}

static void log_position(float angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        if (fprintf(log_file, "%s, Angle: %.2f\n", timestamp, angle) < 0) {
            fprintf(stderr, "Error writing to log file\n");
        }
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

int main(void) {
    int prev_state = 0;
    int pulses = 0;
    int current_state;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(ENCODER_A_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(ENCODER_A_PIN, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(ENCODER_B_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error setting pull-up resistors\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error setting up signal handlers\n");
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        current_state = read_encoder(ENCODER_A_PIN, ENCODER_B_PIN);
        if (current_state < 0) {
            gpioDelay(100000);
            continue;
        }

        if (current_state != prev_state) {
            int direction;
            switch (prev_state) {
                case 0:
                    if (current_state == 1) direction = 1;
                    else if (current_state == 2) direction = -1;
                    else direction = 0;
                    break;
                case 1:
                    if (current_state == 0) direction = -1;
                    else if (current_state == 3) direction = 1;
                    else direction = 0;
                    break;
                case 2:
                    if (current_state == 0) direction = 1;
                    else if (current_state == 3) direction = -1;
                    else direction = 0;
                    break;
                case 3:
                    if (current_state == 1) direction = -1;
                    else if (current_state == 2) direction = 1;
                    else direction = 0;
                    break;
                default:
                    direction = 0;
                    break;
            }

            if (direction != 0) {
                pulses += direction;
                float angle = calculate_angle(pulses);
                log_position(angle);
            }
            prev_state = current_state;
        }

        gpioDelay(DEBOUNCE_DELAY_US);
    }

    printf("\nCleaning up and exiting...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

