#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>

#define SENSOR_GPIO 18
#define LOG_FILE "rpm_log.txt"
#define SAMPLE_INTERVAL_US 1000000  /* 1 second in microseconds */

static volatile int pulse_count = 0;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/*
 * ISR callback — pigpio dispatches this on a dedicated thread, so we
 * protect the shared counter with a mutex.
 */
static void pulse_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

/*
 * Signal handler — set the terminate flag so the main loop exits cleanly.
 */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/*
 * Read and reset the pulse count atomically.
 */
static int read_and_reset_pulse_count(void)
{
    int count;
    pthread_mutex_lock(&pulse_mutex);
    count = pulse_count;
    pulse_count = 0;
    pthread_mutex_unlock(&pulse_mutex);
    return count;
}

/*
 * Log one RPM value with a timestamp.
 */
static void log_rpm(float rpm)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    fprintf(log_file, "%s, RPM: %.2f\n", timestamp, rpm);
    fflush(log_file);
}

int main(void)
{
    int rc;

    /* --- Initialize pigpio --- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n", rc);
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO18 as input with pull-down --- */
    gpioSetMode(SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_GPIO, PI_PUD_DOWN);

    /* --- Register ISR on rising edge --- */
    rc = gpioSetISRFuncEx(SENSOR_GPIO, RISING_EDGE, 0, pulse_isr, NULL);
    if (rc != 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO%d (code %d).\n",
                SENSOR_GPIO, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file in append mode --- */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error: failed to open log file");
        gpioSetISRFuncEx(SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers --- */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("RPM monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR_GPIO);

    /* --- Main sampling loop --- */
    while (!terminate) {
        gpioDelay(SAMPLE_INTERVAL_US);

        int pulses = read_and_reset_pulse_count();
        float rpm = (float)pulses;  /* one pulse = one revolution */

        log_rpm(rpm);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");

    /* Deregister ISR before terminating */
    gpioSetISRFuncEx(SENSOR_GPIO, RISING_EDGE, 0, NULL, NULL);

    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }

    gpioTerminate();
    pthread_mutex_destroy(&pulse_mutex);

    printf("RPM monitoring stopped.\n");
    return EXIT_SUCCESS;
}

