/*
 * ADPD144RI Red/Infrared Photometric Sensor Logger
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    /dev/i2c-1  (GPIO2=SDA, GPIO3=SCL)
 * Sensor: Analog Devices ADPD144RI (I2C address 0x3A)
 * LED:    GPIO17 (active-high)
 *
 * Build:  gcc -O2 -Wall -o adpd144ri_logger adpd144ri_logger.c -lgpiod
 *
 * The ADPD144RI is a 16-bit red/infrared photometric sensor.  This program
 * reads the 16-bit infrared channel (register 0x04) every 100 ms and logs
 * timestamped readings to adpd144ri_log.txt.  An LED on GPIO17 lights when
 * the infrared value exceeds IR_THRESHOLD.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

#define I2C_BUS        "/dev/i2c-1"
#define ADPD144RI_ADDR 0x3A
#define IR_DATA_REG    0x04
#define LED_GPIO       17
#define IR_THRESHOLD   2000
#define LOG_FILE       "adpd144ri_log.txt"
#define SAMPLE_MS      100

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a 16-bit little-endian register from the ADPD144RI.
 * Returns 0 on success, -1 on error.
 */
static int adpd144ri_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static void log_data(FILE *fp, uint16_t ir)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%u\n", ts, ir);
    fflush(fp);
}

int main(void)
{
    int fd = -1;
    FILE *fp = NULL;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led = NULL;
    int ret = EXIT_FAILURE;

    /* --- Signal handling for clean shutdown --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        goto cleanup;
    }

    /* --- Open I2C bus --- */
    fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        goto cleanup;
    }

    if (ioctl(fd, I2C_SLAVE, ADPD144RI_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADPD144RI_ADDR, strerror(errno));
        goto cleanup;
    }

    /* --- Open GPIO chip and request LED line --- */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Cannot open gpiochip0: %s\n", strerror(errno));
        goto cleanup;
    }

    led = gpiod_chip_get_line(chip, LED_GPIO);
    if (!led) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                LED_GPIO, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(led, "adpd144ri_led", 0) < 0) {
        fprintf(stderr, "Cannot request GPIO %d as output: %s\n",
                LED_GPIO, strerror(errno));
        goto cleanup;
    }

    /* --- Open log file --- */
    fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        goto cleanup;
    }

    /* Write CSV header if file is empty */
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,infrared\n");
        fflush(fp);
    }

    printf("ADPD144RI logger started.  Logging to %s.  Press Ctrl+C to stop.\n",
           LOG_FILE);

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t ir = 0;

        if (adpd144ri_read_reg16(fd, IR_DATA_REG, &ir) == 0) {
            log_data(fp, ir);

            if (ir > IR_THRESHOLD) {
                if (gpiod_line_set_value(led, 1) < 0) {
                    fprintf(stderr, "Failed to set LED high: %s\n",
                            strerror(errno));
                }
            } else {
                if (gpiod_line_set_value(led, 0) < 0) {
                    fprintf(stderr, "Failed to set LED low: %s\n",
                            strerror(errno));
                }
            }
        } else {
            /* Sensor read failed: turn LED off for safety and retry next cycle */
            gpiod_line_set_value(led, 0);
        }

        usleep(SAMPLE_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (led) {
        gpiod_line_set_value(led, 0);
        gpiod_line_release(led);
    }
    if (chip)
        gpiod_chip_close(chip);
    if (fp)
        fclose(fp);
    if (fd >= 0)
        close(fd);

    return ret;
}

