#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define AUDIO_PIN 17
#define GAIN_PIN 18
#define LOG_FILE "audio_log.txt"
#define POLL_DELAY_US 10000  /* 10 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(int level) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s %d\n", timestamp, level) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void) {
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error installing SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(AUDIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as input\n", AUDIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GAIN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting GPIO%d as output\n", GAIN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set GAIN_PIN LOW to select 60 dB gain */
    if (gpioWrite(GAIN_PIN, 0) != 0) {
        fprintf(stderr, "Error writing to GPIO%d\n", GAIN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Audio event detection started. Press Ctrl+C to exit.\n");

    int last_state = gpioRead(AUDIO_PIN);
    if (last_state < 0) {
        fprintf(stderr, "Error reading initial state of GPIO%d\n", AUDIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        int current_state = gpioRead(AUDIO_PIN);
        if (current_state < 0) {
            fprintf(stderr, "Error reading GPIO%d\n", AUDIO_PIN);
            break;
        }

        /* Detect rising edge */
        if (last_state == 0 && current_state == 1) {
            if (log_event(1) != 0) {
                fprintf(stderr, "Error logging event\n");
            }
        }

        last_state = current_state;
        gpioDelay(POLL_DELAY_US);
    }

    /* Clean up pigpio resources */
    gpioTerminate();
    printf("Audio event detection stopped.\n");

    return EXIT_SUCCESS;
}

