#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

/* SLF3S-4000B I2C address (7-bit) */
#define SLF3S_ADDR 0x39

/* I2C bus on Raspberry Pi Zero W */
#define I2C_BUS 1

/* Measurement interval in microseconds (1000 ms) */
#define MEASUREMENT_INTERVAL_US 1000000

/* Globals for cleanup in signal handler */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Sensirion CRC-8 parameters */
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INIT 0xFF

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits and cleanup runs      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Sensirion CRC-8 — matches datasheet polynomial 0x31, init 0xFF     */
/* ------------------------------------------------------------------ */
static uint8_t sensirion_crc8(const uint8_t *data, size_t len)
{
    uint8_t crc = CRC8_INIT;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ CRC8_POLYNOMIAL);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* ------------------------------------------------------------------ */
/* Read flow rate from SLF3S-4000B                                    */
/* Returns 0 on success (flow_rate populated), -1 on I/O error,        */
/* -2 on CRC mismatch.                                                */
/* ------------------------------------------------------------------ */
static int read_flow_rate(int handle, float *flow_rate)
{
    uint8_t buffer[3];
    int result;

    /*
     * SLF3S-4000B: trigger a measurement by writing the command byte
     * 0x36 0x08 (start continuous measurement, no clock stretching).
     * The sensor returns a 2-byte MSB-first raw value followed by a CRC.
     */
    uint8_t cmd[2] = {0x36, 0x08};
    result = i2cWriteDevice(handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing measurement command to I2C: %d\n", result);
        return -1;
    }

    /*
     * Wait for the measurement to be ready.  The SLF3S-4000B needs
     * ~1 ms after the command is issued before the first read is valid.
     */
    gpioDelay(2000); /* 2 ms */

    /* Read 3 bytes: MSB, LSB, CRC */
    result = i2cReadDevice(handle, (char *)buffer, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C: expected 3 bytes, got %d\n", result);
        return -1;
    }

    /* Validate CRC over the two data bytes */
    if (sensirion_crc8(buffer, 2) != buffer[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -2;
    }

    /* Assemble 16-bit signed raw value (MSB first) */
    int16_t raw = (int16_t)((buffer[0] << 8) | buffer[1]);

    /*
     * Convert raw to flow rate.
     * SLF3S-4000B: flow_rate = raw * 0.01 uL/min (per datasheet).
     */
    *flow_rate = (float)raw * 0.01f;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log a flow rate reading with a timestamp to the CSV file            */
/* ------------------------------------------------------------------ */
static int log_flow_rate(FILE *fp, float flow_rate)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error getting time\n");
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error converting time\n");
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "Error formatting timestamp\n");
        return -1;
    }

    if (fprintf(fp, "%s,%.2f\n", timestamp, flow_rate) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "Error flushing log file\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup — close I2C, flush/close log file, terminate pigpio        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the SLF3S address */
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, SLF3S_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file once in append mode */
    log_file = fopen("flow_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: flow_log.csv\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(log_file) == 0) {
        fprintf(log_file, "timestamp,flow_rate_uL_min\n");
        fflush(log_file);
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGTERM handler\n");
    }

    printf("Monitoring flow rate. Press Ctrl+C to stop.\n");

    /* Main measurement loop */
    while (!terminate) {
        float flow_rate;
        int rc = read_flow_rate(i2c_handle, &flow_rate);

        if (rc == 0) {
            if (log_flow_rate(log_file, flow_rate) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else if (rc == -2) {
            /* CRC error — skip this reading, keep running */
            fprintf(stderr, "CRC error on flow reading; skipping.\n");
        } else {
            /* I/O error — attempt to re-open I2C bus */
            fprintf(stderr, "I/O error on flow reading; re-opening I2C.\n");
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(100000); /* 100 ms backoff */
            i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Re-open failed: %d\n", i2c_handle);
            }
        }

        /* Wait 1000 ms before next measurement */
        gpioDelay(MEASUREMENT_INTERVAL_US);
    }

    /* Graceful cleanup */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

