/*
 * Raspberry Pi Zero W - Honeywell MICS-VZ-89TE VOC Sensor Reader
 *
 * Wiring:
 *   MICS-VZ-89TE VCC -> Pi 3.3V (Pin 1)
 *   MICS-VZ-89TE GND -> Pi GND  (Pin 6)
 *   MICS-VZ-89TE SDA -> Pi GPIO2 / I2C bus 1 SDA (Pin 3)
 *   MICS-VZ-89TE SCL -> Pi GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * Build: gcc -Wall -o air_quality air_quality.c -lpigpio -lrt
 * Run:   sudo ./air_quality
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define I2C_ADDR       0x18
#define LOG_FILE       "air_quality_log.csv"
#define SAMPLE_PERIOD  5.0   /* seconds */

/*
 * MICS-VZ-89TE register map (per datasheet).
 * The sensor presents a 16-bit register address followed by a 16-bit data
 * payload in a single I2C transaction.  We use a 16-bit register address
 * and read 4 bytes back: 2 bytes TVOC, 2 bytes eCO2.
 */
#define REG_TVOC       0x00
#define REG_ECO2       0x01

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read sensor data                                                    */
/* ------------------------------------------------------------------ */
/*
 * Returns 0 on success, -1 on I2C error.
 * Fills *tvoc_ppb and *eco2_ppm with the raw sensor values.
 */
static int read_sensor_data(uint16_t *tvoc_ppb, uint16_t *eco2_ppm)
{
    char buf[4];
    int  rc;

    /*
     * Write the 16-bit register address (big-endian).
     * i2cWriteI2CBlockData sends the address byte followed by the data;
     * we use a zero-length payload to just set the register pointer.
     */
    rc = i2cWriteI2CBlockData(g_i2c_handle, REG_TVOC, NULL, 0);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteI2CBlockData (set reg) failed: %d\n", rc);
        return -1;
    }

    /*
     * Small delay so the sensor has time to latch the register pointer
     * and prepare the response.
     */
    time_sleep(0.01);

    /*
     * Read 4 bytes: 2 bytes TVOC, 2 bytes eCO2 (both big-endian).
     */
    rc = i2cReadI2CBlockData(g_i2c_handle, REG_TVOC, buf, 4);
    if (rc != 4) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData failed: %d\n", rc);
        return -1;
    }

    *tvoc_ppb = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *eco2_ppm = ((uint16_t)(uint8_t)buf[2] << 8) | (uint8_t)buf[3];

    return 0;
}

/* ------------------------------------------------------------------ */
/* Compute IAQ index                                                   */
/* ------------------------------------------------------------------ */
static int calculate_iaq_index(uint16_t tvoc_ppb, uint16_t eco2_ppm)
{
    /*
     * Placeholder IAQ calculation.
     * Replace with the actual Honeywell formula from the datasheet
     * once calibration and specific thresholds are determined.
     */
    int iaq = (int)tvoc_ppb + (int)eco2_ppm;
    if (iaq < 0) iaq = 0;
    if (iaq > 500) iaq = 500;
    return iaq;
}

/* ------------------------------------------------------------------ */
/* Log data                                                            */
/* ------------------------------------------------------------------ */
static void log_data(int iaq_index, uint16_t tvoc_ppb, uint16_t eco2_ppm)
{
    time_t     rawtime;
    struct tm *timeinfo;
    char       timestamp[32];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "[ERROR] localtime() failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(g_log_file, "%s,%d,%u,%u\n", timestamp, iaq_index, tvoc_ppb, eco2_ppm);
    fflush(g_log_file);

    printf("%s, IAQ: %d, TVOC: %u ppb, eCO2: %u ppm\n",
           timestamp, iaq_index, tvoc_ppb, eco2_ppm);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Open I2C bus --- */
    g_i2c_handle = i2cOpen(I2C_BUS, I2C_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (bus %d, addr 0x%02X): %d\n",
                I2C_BUS, I2C_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open log file '%s'\n", LOG_FILE);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "Timestamp,IAQ,TVOC_ppb,eCO2_ppm\n");
        fflush(g_log_file);
    }

    /* --- Install signal handlers --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGINT) failed\n");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction(SIGTERM) failed\n");
    }

    printf("MICS-VZ-89TE air quality logger started.  Logging to '%s' every %.1f s.\n",
           LOG_FILE, SAMPLE_PERIOD);
    printf("Press Ctrl+C to stop.\n");

    /* --- Main sampling loop --- */
    while (g_running) {
        uint16_t tvoc_ppb = 0;
        uint16_t eco2_ppm = 0;

        if (read_sensor_data(&tvoc_ppb, &eco2_ppm) == 0) {
            int iaq = calculate_iaq_index(tvoc_ppb, eco2_ppm);
            log_data(iaq, tvoc_ppb, eco2_ppm);
        } else {
            fprintf(stderr, "[WARN] Sensor read failed; will retry next cycle.\n");
        }

        /* Sleep in small increments so signals are caught promptly */
        for (int i = 0; i < 50 && g_running; i++) {
            time_sleep(0.1);
        }
    }

    /* --- Graceful cleanup --- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

