/*
 * INMP441 I2S MEMS Microphone Capture for Raspberry Pi 4 Model B
 *
 * Captures 16-bit PCM audio from the INMP441 via the Linux ALSA I2S
 * subsystem (/dev/snd/pcmC0D0c) and writes the raw PCM data to
 * audio_capture.pcm.  The L/R channel-select line on GPIO 17 (BCM)
 * is driven to select the left channel.
 *
 * Build:  gcc -O2 -Wall -o inmp441_capture inmp441_capture.c -lpigpio -lrt
 * Run:    sudo ./inmp441_capture
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/soundcard.h>

#include <pigpio.h>

#define PCM_DEVICE      "/dev/snd/pcmC0D0c"
#define OUTPUT_FILE     "audio_capture.pcm"
#define CHANNEL_SELECT  17          /* BCM GPIO 17 */
#define SAMPLE_RATE     48000
#define FRAME_BITS      16
#define CHANNELS        2
#define PERIOD_FRAMES   1024
#define CAPTURE_SECONDS 60

static volatile sig_atomic_t g_terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

/*
 * Open the PCM device for capture.
 * Returns a file descriptor >= 0 on success, or -1 on failure.
 */
static int open_pcm_device(void)
{
    int fd = open(PCM_DEVICE, O_RDONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening PCM device '%s': %s\n",
                PCM_DEVICE, strerror(errno));
        return -1;
    }

    int format = AFMT_S16_LE;
    if (ioctl(fd, SNDCTL_DSP_SETFMT, &format) < 0) {
        fprintf(stderr, "Error setting PCM format: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    int channels = CHANNELS;
    if (ioctl(fd, SNDCTL_DSP_CHANNELS, &channels) < 0) {
        fprintf(stderr, "Error setting PCM channels: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    int rate = SAMPLE_RATE;
    if (ioctl(fd, SNDCTL_DSP_SPEED, &rate) < 0) {
        fprintf(stderr, "Error setting PCM sample rate: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

/*
 * Read audio frames from the PCM device.
 * Returns the number of bytes read on success, or -1 on error.
 */
static int read_audio_data(int fd, char *buffer, size_t buffer_size)
{
    ssize_t bytes_read = read(fd, buffer, buffer_size);
    if (bytes_read < 0) {
        fprintf(stderr, "Error reading from PCM device: %s\n", strerror(errno));
        return -1;
    }
    return (int)bytes_read;
}

/*
 * Write audio data to the output file.
 * Returns 0 on success, or -1 on error.
 */
static int write_audio_data(FILE *fp, const char *buffer, size_t buffer_size)
{
    size_t bytes_written = fwrite(buffer, 1, buffer_size, fp);
    if (bytes_written != buffer_size) {
        fprintf(stderr, "Error writing to output file: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    int pcm_fd = -1;
    FILE *output_fp = NULL;
    int ret_code = EXIT_FAILURE;

    /* Register signal handler for graceful termination */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error registering SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio for GPIO control */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO 17 as output and drive it LOW to select the left channel */
    if (gpioSetMode(CHANNEL_SELECT, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d as output\n", CHANNEL_SELECT);
        goto cleanup_gpio;
    }
    if (gpioWrite(CHANNEL_SELECT, 0) < 0) {
        fprintf(stderr, "Error writing to GPIO %d\n", CHANNEL_SELECT);
        goto cleanup_gpio;
    }

    /* Open the PCM device */
    pcm_fd = open_pcm_device();
    if (pcm_fd < 0) {
        goto cleanup_gpio;
    }

    /* Open the output file */
    output_fp = fopen(OUTPUT_FILE, "wb");
    if (output_fp == NULL) {
        fprintf(stderr, "Error opening output file '%s': %s\n",
                OUTPUT_FILE, strerror(errno));
        goto cleanup_pcm;
    }

    size_t buffer_size = PERIOD_FRAMES * CHANNELS * (FRAME_BITS / 8);
    char *audio_buffer = (char *)malloc(buffer_size);
    if (audio_buffer == NULL) {
        fprintf(stderr, "Error allocating audio buffer: %s\n", strerror(errno));
        goto cleanup_file;
    }

    printf("Capturing audio for %d seconds...\n", CAPTURE_SECONDS);
    printf("Press Ctrl+C to stop early.\n");

    time_t start_time = time(NULL);
    int error_count = 0;

    while (!g_terminate) {
        int bytes_read = read_audio_data(pcm_fd, audio_buffer, buffer_size);
        if (bytes_read < 0) {
            error_count++;
            if (error_count > 10) {
                fprintf(stderr, "Too many read errors, aborting.\n");
                break;
            }
            continue;
        }
        error_count = 0;

        if (write_audio_data(output_fp, audio_buffer, (size_t)bytes_read) < 0) {
            break;
        }

        if (time(NULL) - start_time >= CAPTURE_SECONDS) {
            break;
        }
    }

    printf("Audio capture complete.\n");
    ret_code = EXIT_SUCCESS;

    free(audio_buffer);

cleanup_file:
    if (output_fp != NULL) {
        fclose(output_fp);
    }

cleanup_pcm:
    if (pcm_fd >= 0) {
        close(pcm_fd);
    }

cleanup_gpio:
    gpioWrite(CHANNEL_SELECT, 0);
    gpioTerminate();

    return ret_code;
}

