#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18
#define PWM_FREQUENCY 100
#define DEBOUNCE_DELAY_US 50000
#define POLL_DELAY_US 50000
#define SENSOR_TIMEOUT_MS 5000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    localtime_r(&now, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file);
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        return -1;
    }
    if (gpioSetMode(FAN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set fan pin mode\n");
        return -1;
    }
    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "Failed to set pull-up on flame sensor pin\n");
        return -1;
    }
    if (gpioPWM(FAN_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise PWM on fan pin\n");
        return -1;
    }
    return 0;
}

static void cleanup_gpio(void) {
    gpioPWM(FAN_PIN, 0);
    gpioWrite(FAN_PIN, 0);
    gpioTerminate();
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    log_file = fopen("flame_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        fclose(log_file);
        return EXIT_FAILURE;
    }

    log_event("System started");

    int flame_active = 0;
    int last_stable_state = 0;
    uint32_t last_change_tick = 0;
    uint32_t last_read_tick = gpioTick();
    int sensor_stable = 0;

    while (running) {
        int raw = gpioRead(FLAME_SENSOR_PIN);
        uint32_t now = gpioTick();

        if (raw < 0) {
            fprintf(stderr, "GPIO read error on flame sensor pin\n");
            if (!sensor_stable) {
                sensor_stable = 1;
                log_event("Sensor read error - possible sensor absent or bus fault");
            }
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        sensor_stable = 0;
        last_read_tick = now;

        if (raw != last_stable_state) {
            if (last_change_tick == 0 || (now - last_change_tick) >= DEBOUNCE_DELAY_US) {
                last_stable_state = raw;
                last_change_tick = now;
                if (raw == 0) {
                    if (!flame_active) {
                        flame_active = 1;
                        log_event("Flame detected");
                        if (gpioPWM(FAN_PIN, 128) != 0) {
                            fprintf(stderr, "Failed to start PWM on fan pin\n");
                        }
                    }
                } else {
                    if (flame_active) {
                        flame_active = 0;
                        log_event("Flame ended");
                        if (gpioPWM(FAN_PIN, 0) != 0) {
                            fprintf(stderr, "Failed to stop PWM on fan pin\n");
                        }
                    }
                }
            }
        }

        gpioDelay(POLL_DELAY_US);

        if (sensor_stable && (now - last_read_tick) > (SENSOR_TIMEOUT_MS * 1000)) {
            log_event("Sensor timeout - no valid readings");
            break;
        }
    }

    log_event("Shutting down");
    cleanup_gpio();
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    return EXIT_SUCCESS;
}

