#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8

#define FRAME_TRIGGER_PIN 23
#define DATA_READY_PIN    24

#define FRAME_PERIOD_US  100000
#define HEATMAP_BYTES    32768
#define HEATMAP_WORDS    (HEATMAP_BYTES / 2)

#define MAGIC_NUMBER     4144

typedef struct {
    uint16_t startFreq;
    uint16_t endFreq;
    uint16_t numChirps;
    uint16_t numSamples;
} __attribute__((packed)) RadarConfig;

typedef struct {
    uint32_t magic;
    uint64_t timestamp;
    RadarConfig config;
} __attribute__((packed)) FileHeader;

typedef struct {
    uint64_t timestamp;
    uint32_t frameNumber;
} __attribute__((packed)) FrameHeader;

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int spi_init(void) {
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        perror("open(" SPI_DEVICE ")");
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("ioctl(SPI_IOC_WR_MODE)");
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("ioctl(SPI_IOC_WR_BITS_PER_WORD)");
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("ioctl(SPI_IOC_WR_MAX_SPEED_HZ)");
        close(g_spi_fd); g_spi_fd = -1; return -1;
    }

    return 0;
}

static int spi_transfer(const uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf = (unsigned long)tx;
    tr.rx_buf = (unsigned long)rx;
    tr.len = len;
    tr.speed_hz = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs = 0;
    tr.cs_change = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("ioctl(SPI_IOC_MESSAGE)");
        return -1;
    }
    return 0;
}

static int read_heatmap(uint16_t *data) {
    uint8_t tx[HEATMAP_BYTES];
    uint8_t rx[HEATMAP_BYTES];
    memset(tx, 0, sizeof(tx));
    memset(rx, 0, sizeof(rx));

    if (spi_transfer(tx, rx, sizeof(tx)) < 0) return -1;

    for (size_t i = 0; i < HEATMAP_WORDS; i++) {
        data[i] = (uint16_t)((rx[i * 2 + 1] << 8) | rx[i * 2]);
    }
    return 0;
}

static int log_frame(const uint16_t *data, uint64_t ts, uint32_t frame) {
    FrameHeader hdr;
    hdr.timestamp = ts;
    hdr.frameNumber = frame;

    if (fwrite(&hdr, sizeof(hdr), 1, g_log_file) != 1) {
        perror("fwrite(FrameHeader)");
        return -1;
    }
    if (fwrite(data, sizeof(uint16_t), HEATMAP_WORDS, g_log_file) != HEATMAP_WORDS) {
        perror("fwrite(heatmap)");
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (gpioSetMode(FRAME_TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(FRAME_TRIGGER_PIN) failed\n");
        gpioTerminate(); return 1;
    }
    if (gpioSetMode(DATA_READY_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "gpioSetMode(DATA_READY_PIN) failed\n");
        gpioTerminate(); return 1;
    }
    if (gpioSetPullUpDown(DATA_READY_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "gpioSetPullUpDown(DATA_READY_PIN) failed\n");
        gpioTerminate(); return 1;
    }

    if (spi_init() < 0) {
        gpioTerminate(); return 1;
    }

    g_log_file = fopen("radar_data.bin", "wb");
    if (!g_log_file) {
        perror("fopen(radar_data.bin)");
        close(g_spi_fd); g_spi_fd = -1;
        gpioTerminate(); return 1;
    }

    RadarConfig cfg = { .startFreq = 7700, .endFreq = 7900, .numChirps = 64, .numSamples = 256 };
    FileHeader hdr = { .magic = MAGIC_NUMBER, .timestamp = 0, .config = cfg };
    if (fwrite(&hdr, sizeof(hdr), 1, g_log_file) != 1) {
        perror("fwrite(FileHeader)");
        fclose(g_log_file); g_log_file = NULL;
        close(g_spi_fd); g_spi_fd = -1;
        gpioTerminate(); return 1;
    }
    fflush(g_log_file);

    uint16_t *heatmap = malloc(HEATMAP_BYTES);
    if (!heatmap) {
        perror("malloc(heatmap)");
        fclose(g_log_file); g_log_file = NULL;
        close(g_spi_fd); g_spi_fd = -1;
        gpioTerminate(); return 1;
    }

    uint32_t frame = 0;
    while (g_running) {
        if (gpioWrite(FRAME_TRIGGER_PIN, 1) < 0) {
            fprintf(stderr, "gpioWrite(trigger high) failed\n");
            break;
        }
        gpioDelay(10);

        uint32_t timeout = 0;
        while (gpioRead(DATA_READY_PIN) == 1) {
            if (timeout++ > 1000) {
                fprintf(stderr, "Timeout waiting for data-ready\n");
                gpioWrite(FRAME_TRIGGER_PIN, 0);
                break;
            }
            gpioDelay(100);
        }
        if (timeout >= 1000) continue;

        if (gpioWrite(FRAME_TRIGGER_PIN, 0) < 0) {
            fprintf(stderr, "gpioWrite(trigger low) failed\n");
            break;
        }

        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
            perror("clock_gettime");
            break;
        }
        uint64_t t = (uint64_t)ts.tv_sec * 1000000ULL + (uint64_t)ts.tv_nsec / 1000ULL;

        if (read_heatmap(heatmap) < 0) {
            fprintf(stderr, "SPI transfer failed\n");
            break;
        }

        if (log_frame(heatmap, t, frame++) < 0) {
            fprintf(stderr, "Frame logging failed\n");
            break;
        }
        fflush(g_log_file);

        uint32_t elapsed = (uint32_t)(ts.tv_sec * 1000000 + ts.tv_nsec / 1000);
        uint32_t next = (frame * FRAME_PERIOD_US) % 1000000;
        if (next > elapsed) {
            gpioDelay((next - elapsed) * 1000);
        }
    }

    free(heatmap);
    if (g_log_file) { fclose(g_log_file); g_log_file = NULL; }
    if (g_spi_fd >= 0) { close(g_spi_fd); g_spi_fd = -1; }
    gpioTerminate();
    return 0;
}

