/*
 * flame_detect.c — SainSmart IR Flame Detection Sensor Module reader
 *
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: SainSmart IR Flame Detection Sensor Module
 * Wiring: VCC -> 3V3 (pin 1), GND -> GND (pin 6), DOUT -> GPIO17 (pin 11)
 * Library: libgpiod (v2 API)
 *
 * Build:  gcc -Wall -Wextra -O2 -o flame_detect flame_detect.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define GPIO_LINE_OFFSET 17          /* BCM 17 */
#define POLL_INTERVAL_SEC 1

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

static int install_signal_handler(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */
static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }

    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }
    printf("%s", buf);
}

/*
 * Read the flame sensor DOUT line.
 * Returns 0 (flame detected, active-low) or 1 (no flame), or -1 on error.
 */
static int read_flame_sensor(struct gpiod_line *line)
{
    int val = gpiod_line_get_value(line);
    if (val < 0) {
        fprintf(stderr, "gpiod_line_get_value() failed: %s\n",
                strerror(errno));
        return -1;
    }
    return val;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    struct gpiod_line_request_config *req_cfg = NULL;
    struct gpiod_line_settings *settings = NULL;
    int ret = EXIT_FAILURE;

    /* --- Open GPIO chip --------------------------------------------- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    /* --- Get line ---------------------------------------------------- */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    /* --- Configure line as input with pull-up ------------------------ */
    settings = gpiod_line_settings_new();
    if (settings == NULL) {
        fprintf(stderr, "gpiod_line_settings_new() failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_settings_set_direction(settings,
                                          GPIOD_LINE_DIRECTION_INPUT) < 0) {
        fprintf(stderr, "set_direction(INPUT) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_settings_set_bias(settings,
                                     GPIOD_LINE_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "set_bias(PULL_UP) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    req_cfg = gpiod_line_request_config_new();
    if (req_cfg == NULL) {
        fprintf(stderr, "gpiod_line_request_config_new() failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    gpiod_line_request_config_set_consumer(req_cfg, "flame-detect");

    /* --- Request line ------------------------------------------------ */
    if (gpiod_line_request(line, req_cfg, settings) < 0) {
        fprintf(stderr, "gpiod_line_request() failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* --- Install signal handler ------------------------------------- */
    if (install_signal_handler() < 0) {
        goto cleanup;
    }

    printf("Flame detection started on GPIO%d. Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    /* --- Main loop --------------------------------------------------- */
    while (g_running) {
        int val = read_flame_sensor(line);
        if (val < 0) {
            /* Transient read error — keep running */
            sleep(POLL_INTERVAL_SEC);
            continue;
        }

        print_timestamp();
        printf(" Flame Detected: %s\n",
               (val == 0) ? "YES" : "NO");
        fflush(stdout);

        sleep(POLL_INTERVAL_SEC);
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    if (req_cfg != NULL)
        gpiod_line_request_config_free(req_cfg);
    if (settings != NULL)
        gpiod_line_settings_free(settings);
    if (line != NULL)
        gpiod_line_release(line);
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

