/*
 * TTP226 8-channel touch sensor reader for Raspberry Pi Zero W.
 *
 * Wiring:
 *   TTP226 OUT1 -> BCM GPIO 2
 *   TTP226 OUT2 -> BCM GPIO 3
 *   TTP226 OUT3 -> BCM GPIO 4
 *   TTP226 OUT4 -> BCM GPIO 5
 *   TTP226 OUT5 -> BCM GPIO 6
 *   TTP226 OUT6 -> BCM GPIO 7
 *   TTP226 OUT7 -> BCM GPIO 8
 *   TTP226 OUT8 -> BCM GPIO 9
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o ttp226_reader ttp226_reader.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 100

static const unsigned int channel_pins[NUM_CHANNELS] = {
    2, 3, 4, 5, 6, 7, 8, 9
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%d %H:%M:%S", &timeinfo);
        printf("[%s] ", buffer);
    } else {
        printf("[unknown-time] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int values[NUM_CHANNELS];
    int ret;
    int i;

    for (i = 0; i < NUM_CHANNELS; i++)
        lines[i] = NULL;

    /* Install signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on Raspberry Pi) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: failed to open gpiochip0: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get and request each of the eight GPIO lines as inputs */
    for (i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, channel_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Error: failed to get GPIO line %u: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }

        ret = gpiod_line_request_input(lines[i], "ttp226-reader");
        if (ret < 0) {
            fprintf(stderr, "Error: failed to request GPIO line %u as input: %s\n",
                    channel_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    printf("TTP226 8-channel touch sensor reader started.\n");
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main polling loop */
    while (program_running) {
        for (i = 0; i < NUM_CHANNELS; i++) {
            values[i] = gpiod_line_get_value(lines[i]);
            if (values[i] < 0) {
                fprintf(stderr, "Error: failed to read GPIO line %u: %s\n",
                        channel_pins[i], strerror(errno));
                goto cleanup;
            }
        }

        print_timestamp();
        for (i = 0; i < NUM_CHANNELS; i++) {
            printf("%d", values[i]);
            if (i < NUM_CHANNELS - 1)
                printf(", ");
        }
        printf("\n");
        fflush(stdout);

        /* Sleep for POLL_INTERVAL_MS milliseconds */
        struct timespec ts = {
            .tv_sec = POLL_INTERVAL_MS / 1000,
            .tv_nsec = (POLL_INTERVAL_MS % 1000) * 1000000L
        };
        nanosleep(&ts, NULL);
    }

    printf("\nExiting gracefully...\n");

cleanup:
    /* Release each line handle */
    for (i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL)
            gpiod_line_release(lines[i]);
    }

    if (chip != NULL)
        gpiod_chip_close(chip);

    return (program_running == 0) ? EXIT_SUCCESS : EXIT_FAILURE;
}

