#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define SAMPLE_INTERVAL_US 100000  /* 100 ms */

/* TTP226 OUT1..OUT8 wired to BCM GPIO 2..9 */
static const int sensor_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    /* --- Install signal handlers for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed (code %d).\n",
                gpioInitialise());
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs with pull-down --- */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode failed for pin %d.\n",
                    sensor_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Error: gpioSetPullUpDown failed for pin %d.\n",
                    sensor_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    printf("TTP226 8-channel touch sensor reader started.\n");
    printf("Pins: BCM %d %d %d %d %d %d %d %d  |  Sample interval: %d us\n",
           sensor_pins[0], sensor_pins[1], sensor_pins[2], sensor_pins[3],
           sensor_pins[4], sensor_pins[5], sensor_pins[6], sensor_pins[7],
           SAMPLE_INTERVAL_US);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main sampling loop --- */
    while (running) {
        int values[NUM_CHANNELS];
        int rc = gpioReadAll(values);
        if (rc < 0) {
            fprintf(stderr, "Error: gpioReadAll failed (code %d).\n", rc);
            break;
        }

        printf("[+%ld ms] CH1=%d CH2=%d CH3=%d CH4=%d "
               "CH5=%d CH6=%d CH7=%d CH8=%d\n",
               (long)(SAMPLE_INTERVAL_US / 1000),
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);
        fflush(stdout);

        /* Sleep for the sampling interval (microseconds) */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* --- Clean shutdown --- */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

