/*
 * TMAG5110 Hall-Effect Latch Sensor Reader
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (C API)
 *
 * Wiring:
 *   Sensor 1 OUT -> BCM GPIO4 (physical pin 7)
 *   Sensor 2 OUT -> BCM GPIO5 (physical pin 29)
 *   VCC          -> 3.3 V (physical pin 1)
 *   GND          -> GND  (physical pin 9)
 *
 * The TMAG5110 OUT pin is an open-drain output with an external
 * pull-up resistor.  An unasserted (no magnet) output reads HIGH
 * and reads LOW when a magnetic field is detected.
 *
 * Build:
 *   gcc -Wall -o hall_effect hall_effect.c -lpigpio -lrt
 * Run:
 *   sudo ./hall_effect
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 5
#define POLL_DELAY_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C)                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin and print its logical state                       */
/* ------------------------------------------------------------------ */
static void read_sensor(int pin, int sensor_id)
{
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d (sensor %d)\n",
                pin, sensor_id);
        return;
    }

    /*
     * TMAG5110 OUT is open-drain with an external pull-up.
     *   level == 1 (PI_HIGH)  -> no magnet detected (output reads HIGH)
     *   level == 0 (PI_LOW)   -> magnet detected     (output reads LOW)
     */
    const char *state_str = (level == 1) ? "HIGH" : "LOW";
    printf("Sensor %d (BCM %d): %s\n", sensor_id, pin, state_str);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio library --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        fprintf(stderr, "       Is the pigpio daemon running? (sudo pigpiod)\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs --- */
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

