/*
 * TMAG5110 Hall-Effect Latch Sensor Reader
 * Board:  Raspberry Pi 3 Model B+
 * Library: pigpio (C API)
 *
 * Wiring:
 *   Sensor 1 OUT -> BCM GPIO4 (physical pin 7)
 *   Sensor 2 OUT -> BCM GPIO5 (physical pin 29)
 *   VCC          -> 3.3 V (physical pin 1)
 *   GND          -> GND  (physical pin 9)
 *
 * The TMAG5110 OUT pin is an open-drain output with an external
 * pull-up resistor.  An unasserted (no magnet) output reads HIGH
 * and reads LOW when a magnetic field is detected.
 *
 * Build:
 *   gcc -Wall -o hall_effect hall_effect.c -lpigpio -lrt
 * Run:
 *   sudo ./hall_effect
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 4
#define SENSOR2_PIN 5
#define POLL_DELAY_US 500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler for graceful shutdown (Ctrl+C)                       */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a sensor pin and print its logical state                       */
/* ------------------------------------------------------------------ */
static void read_sensor(int pin, int sensor_id)
{
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d (sensor %d)\n",
                pin, sensor_id);
        return;
    }

    /*
     * TMAG5110 OUT is open-drain with an external pull-up.
     *   level == 1 (PI_HIGH)  -> no magnet detected (output reads HIGH)
     *   level == 0 (PI_LOW)   -> magnet detected     (output reads LOW)
     */
    const char *state_str = (level == 1) ? "HIGH" : "LOW";
    printf("Sensor %d (BCM %d): %s\n", sensor_id, pin, state_str);
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio library --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        fprintf(stderr, "       Is the pigpio daemon running? (sudo pigpiod)\n");
        return EXIT_FAILURE;
    }

    /* --- Configure sensor pins as inputs --- */
    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", SENSOR1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed for pin %d\n", SENSOR2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handler for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("TMAG5110 Hall-Effect Sensor Reader\n");
    printf("Sensor 1: BCM GPIO%d | Sensor 2: BCM GPIO%d\n",
           SENSOR1_PIN, SENSOR2_PIN);
    printf("Press Ctrl+C to exit.\n\n");

    /* --- Main polling loop --- */
    while (g_running) {
        read_sensor(SENSOR1_PIN, 1);
        read_sensor(SENSOR2_PIN, 2);
        printf("---\n");
        fflush(stdout);

        /*
         * gpioDelay returns the actual delay (microseconds).
         * If the delay was interrupted by a signal, it returns early.
         * We check g_running to avoid unnecessary iterations.
         */
        if (g_running) {
            gpioDelay(POLL_DELAY_US);
        }
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");
    gpioTerminate();
    return EXIT_SUCCESS;
}

