#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TILT_SENSOR_PIN 4
#define POLL_DELAY_US   100000  /* 100 ms */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

int main(void)
{
    int last_state = -1;
    int rc;

    /* --- Install SIGINT handler for clean shutdown --- */
    struct sigaction sa;
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed (code %d).\n", rc);
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO4 as input with internal pull-up --- */
    rc = gpioSetMode(TILT_SENSOR_PIN, PI_INPUT);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioSetMode(%d, PI_INPUT) failed (code %d).\n",
                TILT_SENSOR_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    rc = gpioSetPullUpDown(TILT_SENSOR_PIN, PI_PUD_UP);
    if (rc != 0) {
        fprintf(stderr, "Error: gpioSetPullUpDown(%d, PI_PUD_UP) failed (code %d).\n",
                TILT_SENSOR_PIN, rc);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Tilt sensor monitoring started on GPIO%d.\n", TILT_SENSOR_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* --- Main polling loop --- */
    while (g_running) {
        int level = gpioRead(TILT_SENSOR_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead(%d) failed (code %d).\n",
                    TILT_SENSOR_PIN, level);
            break;
        }

        if (level != last_state) {
            printf("%s\n", level == 0 ? "Tilted" : "Not Tilted");
            fflush(stdout);
            last_state = level;
        }

        usleep(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

