#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define SI1145_ADDR 0x60

#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_UV_INDEX0 0x2C

#define SI1145_PART_ID 0x45
#define SI1145_HW_KEY_VAL 0x17

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int init_si1145(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1145_REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Error: Failed to read PART_ID register.\n");
        return -1;
    }
    if (part_id != SI1145_PART_ID) {
        fprintf(stderr, "Error: Unexpected PART_ID 0x%02X (expected 0x%02X). Sensor not present.\n", part_id, SI1145_PART_ID);
        return -1;
    }

    if (i2c_write_reg8(fd, SI1145_REG_HW_KEY, SI1145_HW_KEY_VAL) < 0) {
        fprintf(stderr, "Error: Failed to write HW_KEY register.\n");
        return -1;
    }

    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE0, 0x08) < 0) {
        fprintf(stderr, "Error: Failed to write MEAS_RATE0 register.\n");
        return -1;
    }

    return 0;
}

static int read_uv_index(int fd, uint8_t *uv_index) {
    return i2c_read_reg8(fd, SI1145_REG_UV_INDEX0, uv_index);
}

static int read_als_visible(int fd, uint16_t *als_visible) {
    return i2c_read_reg16(fd, SI1145_REG_ALS_VIS_DATA0, als_visible);
}

static void log_data(FILE *fp, uint8_t uv_index, uint16_t als_visible) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%u,%u\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            uv_index, als_visible);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening /dev/i2c-1");
        return 1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return 1;
    }

    if (init_si1145(i2c_fd) < 0) {
        fprintf(stderr, "Error initializing Si1145 sensor.\n");
        close(i2c_fd);
        return 1;
    }

    log_file = fopen("uv_als_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,uv_index,als_visible\n");
        fflush(log_file);
    }

    printf("Si1145 sensor initialized. Logging to uv_als_log.csv\n");

    while (running) {
        uint8_t uv_index;
        uint16_t als_visible;

        if (read_uv_index(i2c_fd, &uv_index) < 0) {
            fprintf(stderr, "Error reading UV index.\n");
        } else if (read_als_visible(i2c_fd, &als_visible) < 0) {
            fprintf(stderr, "Error reading ALS visible.\n");
        } else {
            printf("UV Index: %u, ALS Visible: %u\n", uv_index, als_visible);
            log_data(log_file, uv_index, als_visible);
        }

        sleep(1);
    }

    printf("\nExiting gracefully...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    return 0;
}

