#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS "/dev/i2c-1"
#define SENSOR1_ADDR 0x39
#define SENSOR2_ADDR 0x3A
#define ALARM_GPIO 17
#define FLOW_THRESHOLD 0.5f
#define LOG_FILE "flow_log.txt"
#define MEASUREMENT_DELAY_MS 100
#define START_CMD_MSB 0x36
#define START_CMD_LSB 0x08
#define READ_LEN 3

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_fp = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static uint8_t sensirion_crc8(const uint8_t *data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

static int i2c_write_cmd(int fd, uint8_t msb, uint8_t lsb) {
    uint8_t buf[2] = {msb, lsb};
    if (write(fd, buf, 2) != 2) {
        perror("I2C write failed");
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t *buf, size_t len) {
    ssize_t n = read(fd, buf, len);
    if (n < 0 || (size_t)n != len) {
        perror("I2C read failed");
        return -1;
    }
    return 0;
}

static int read_flow_rate(int fd, float *flow_rate) {
    uint8_t buf[READ_LEN];
    if (i2c_read_bytes(fd, buf, READ_LEN) != 0)
        return -1;
    if (sensirion_crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "CRC mismatch on flow data\n");
        return -1;
    }
    int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
    *flow_rate = (float)raw / 100.0f;
    return 0;
}

static void log_flow_rate(float rate1, float rate2, float avg) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[64];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_fp, "%s, Sensor1: %.2f, Sensor2: %.2f, Average: %.2f\n",
            ts, rate1, rate2, avg);
    fflush(log_fp);
}

static void set_alarm(int state) {
    gpioWrite(ALARM_GPIO, state);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio init failed\n");
        return 1;
    }
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    set_alarm(0);

    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("open I2C bus");
        gpioTerminate();
        return 1;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        perror("open log file");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    int addrs[2] = {SENSOR1_ADDR, SENSOR2_ADDR};
    float rates[2] = {0.0f, 0.0f};
    int valid[2] = {0, 0};

    for (int i = 0; i < 2; i++) {
        if (ioctl(i2c_fd, I2C_SLAVE, addrs[i]) < 0) {
            perror("ioctl I2C_SLAVE");
            goto cleanup;
        }
        if (i2c_write_cmd(i2c_fd, START_CMD_MSB, START_CMD_LSB) != 0) {
            fprintf(stderr, "Failed to start sensor 0x%02X\n", addrs[i]);
            goto cleanup;
        }
        gpioDelay(MEASUREMENT_DELAY_MS * 1000);
    }

    while (running) {
        for (int i = 0; i < 2; i++) {
            if (ioctl(i2c_fd, I2C_SLAVE, addrs[i]) < 0) {
                perror("ioctl I2C_SLAVE");
                valid[i] = 0;
                continue;
            }
            if (read_flow_rate(i2c_fd, &rates[i]) == 0) {
                valid[i] = 1;
            } else {
                fprintf(stderr, "Sensor 0x%02X read error\n", addrs[i]);
                valid[i] = 0;
            }
        }

        float sum = 0.0f;
        int count = 0;
        for (int i = 0; i < 2; i++) {
            if (valid[i]) {
                sum += rates[i];
                count++;
            }
        }
        float avg = (count > 0) ? (sum / count) : 0.0f;

        log_flow_rate(rates[0], rates[1], avg);
        set_alarm(avg < FLOW_THRESHOLD ? 1 : 0);

        gpioDelay(1000000);
    }

cleanup:
    set_alarm(0);
    if (log_fp) fclose(log_fp);
    if (i2c_fd >= 0) close(i2c_fd);
    gpioTerminate();
    return 0;
}

