#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x28
#define D7S_MODE_REG   0x00
#define D7S_X_L_REG    0x02
#define D7S_X_H_REG    0x03
#define D7S_Y_L_REG    0x04
#define D7S_Y_H_REG    0x05
#define D7S_Z_L_REG    0x06
#define D7S_Z_H_REG    0x07
#define D7S_MODE_ACTIVE 0x01
#define CSV_FILE       "fan_health.csv"
#define POLL_INTERVAL_MS 500
#define ACTIVATION_TIMEOUT_S 1

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
