/*
 * TMAG5170-Q1 3D Hall-Effect Sensor Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   VCC  -> 3.3 V (Pin 1)
 *   GND  -> GND  (Pin 9)
 *   SDA  -> GPIO2 / I2C bus 1 SDA (Pin 3)
 *   SCL  -> GPIO3 / I2C bus 1 SCL (Pin 5)
 *
 * Build:
 *   gcc -O2 -Wall -o mag_logger mag_logger.c -lpigpio -lrt
 *   Run with sudo (pigpio requires root for I2C access).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- TMAG5170-Q1 I2C address ---- */
#define TMAG5170_ADDR 0x30

/* ---- TMAG5170-Q1 register addresses ---- */
#define REG_DEVICE_CONFIG_1 0x00
#define REG_DEVICE_CONFIG_2 0x01
#define REG_X_MSB           0x02
#define REG_X_LSB           0x03
#define REG_Y_MSB           0x04
#define REG_Y_LSB           0x05
#define REG_Z_MSB           0x06
#define REG_Z_LSB           0x07
#define REG_TEMP_MSB        0x08
#define REG_TEMP_LSB        0x09
#define REG_DEVICE_ID       0x0F

/* ---- Expected device ID ---- */
#define TMAG5170_DEVICE_ID 0x5170

/* ---- Global resources for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a TMAG5170 register (big-endian)            */
/* ------------------------------------------------------------------ */
static int tmag_write_reg16(int handle, uint8_t reg, uint16_t value)
{
    char buf[3];
    buf[0] = (char)reg;
    buf[1] = (char)((value >> 8) & 0xFF);
    buf[2] = (char)(value & 0xFF);

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed for reg 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a TMAG5170 register (big-endian)           */
/* ------------------------------------------------------------------ */
static int tmag_read_reg16(int handle, uint8_t reg, uint16_t *out)
{
    char reg_buf[1] = { (char)reg };
    char data[2];

    if (i2cWriteDevice(handle, reg_buf, 1) != 1) {
        fprintf(stderr, "[ERROR] i2cWriteDevice (reg select) failed for 0x%02X\n", reg);
        return -1;
    }

    if (i2cReadDevice(handle, data, 2) != 2) {
        fprintf(stderr, "[ERROR] i2cReadDevice failed for reg 0x%02X\n", reg);
        return -1;
    }

    *out = ((uint16_t)(uint8_t)data[0] << 8) | (uint8_t)data[1];
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure TMAG5170 for continuous conversion, 50 mT range           */
/* ------------------------------------------------------------------ */
static int configure_tmag5170(int handle)
{
    uint16_t dev_id = 0;

    /* Verify device identity */
    if (tmag_read_reg16(handle, REG_DEVICE_ID, &dev_id) != 0) {
        fprintf(stderr, "[ERROR] Cannot read DEVICE_ID — sensor absent or bus error.\n");
        return -1;
    }
    if (dev_id != TMAG5170_DEVICE_ID) {
        fprintf(stderr, "[ERROR] Unexpected DEVICE_ID 0x%04X (expected 0x%04X).\n",
                dev_id, TMAG5170_DEVICE_ID);
        return -1;
    }

    /*
     * DEVICE_CONFIG_1 (0x00):
     *   [15:13] MAG_CH_EN  = 0b111  (X, Y, Z axes enabled)
     *   [12:11] CONV_MODE  = 0b00   (continuous conversion)
     *   [10:9]  MAG_GAIN   = 0b00   (50 mT range)
     *   [8:7]   TEMP_EN    = 0b00   (temperature disabled)
     *   [6:5]   MAG_CH_EN2 = 0b00
     *   [4:3]   CONV_MODE2 = 0b00
     *   [2:0]   MAG_GAIN2  = 0b000
     * Result: 0x0070
     */
    if (tmag_write_reg16(handle, REG_DEVICE_CONFIG_1, 0x0070) != 0) {
        fprintf(stderr, "[ERROR] Failed to write DEVICE_CONFIG_1.\n");
        return -1;
    }

    /*
     * DEVICE_CONFIG_2 (0x01):
     *   [15:14] MAG_CH_EN3 = 0b00
     *   [13:12] CONV_MODE3 = 0b00
     *   [11:10] MAG_GAIN3  = 0b00
     *   [9:8]   TEMP_EN2   = 0b00
     *   [7:6]   MAG_CH_EN4 = 0b00
     *   [5:4]   CONV_MODE4 = 0b00
     *   [3:2]   MAG_GAIN4  = 0b00
     *   [1:0]   RESERVED   = 0b00
     * Result: 0x0000
     */
    if (tmag_write_reg16(handle, REG_DEVICE_CONFIG_2, 0x0000) != 0) {
        fprintf(stderr, "[ERROR] Failed to write DEVICE_CONFIG_2.\n");
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read X, Y, Z magnetic field values (14-bit, left-justified)         */
/* ------------------------------------------------------------------ */
static int read_magnetic_data(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    uint16_t x_raw = 0, y_raw = 0, z_raw = 0;

    if (tmag_read_reg16(handle, REG_X_MSB, &x_raw) != 0) return -1;
    if (tmag_read_reg16(handle, REG_Y_MSB, &y_raw) != 0) return -1;
    if (tmag_read_reg16(handle, REG_Z_MSB, &z_raw) != 0) return -1;

    /* TMAG5170 outputs 14-bit data left-justified in 16-bit registers */
    *x = (int16_t)(x_raw >> 2);
    *y = (int16_t)(y_raw >> 2);
    *z = (int16_t)(z_raw >> 2);

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one data row to the CSV file                                    */
/* ------------------------------------------------------------------ */
static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "[ERROR] fprintf to log file failed.\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "[ERROR] fflush on log file failed.\n");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                          */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at TMAG5170 address */
    g_i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d).\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure sensor */
    if (configure_tmag5170(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] TMAG5170 configuration failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("magnetic_log.csv", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open magnetic_log.csv for writing.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,x,y,z\n");
        fflush(g_log_file);
    }

    /* Register signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("TMAG5170 logging started. Press Ctrl-C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        int16_t x = 0, y = 0, z = 0;

        if (read_magnetic_data(g_i2c_handle, &x, &y, &z) == 0) {
            if (log_data(g_log_file, x, y, z) != 0) {
                fprintf(stderr, "[WARN] Logging failed for this sample.\n");
            }
        } else {
            fprintf(stderr, "[WARN] I2C read error — skipping sample.\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

