    /* Main sampling loop */
    while (g_running) {
        int16_t x = 0, y = 0, z = 0;

        if (read_magnetic_data(g_i2c_handle, &x, &y, &z) == 0) {
            if (log_data(g_log_file, x, y, z) != 0) {
                fprintf(stderr, "[WARN] Logging failed for this sample.\n");
            }
        } else {
            fprintf(stderr, "[WARN] I2C read error — skipping sample.\n");
        }

        gpioDelay(100000); /* 100 ms */
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

