#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pthread.h>
#include <stdatomic.h>
#include <pigpio.h>

#define SENSOR_PIN 4          /* BCM GPIO4, physical pin 7 */
#define LOG_FILE   "rpm_log.txt"
#define SAMPLE_US  1000000     /* 1 second in microseconds */

static atomic_int g_pulse_count = 0;
static FILE      *g_log_fp      = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — counts rising edges on SENSOR_PIN          */
/* ------------------------------------------------------------------ */
static void pulse_callback(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)tick;
    (void)userdata;

    if (level == 1) {                 /* rising edge */
        atomic_fetch_add(&g_pulse_count, 1);
    }
}

/* ------------------------------------------------------------------ */
/* Compute RPM from pulses counted in the last second window          */
/* ------------------------------------------------------------------ */
static double calculate_rpm(int pulses)
{
    return (double)pulses * 60.0 / (SAMPLE_US / 1000000.0);
}

/* ------------------------------------------------------------------ */
/* Log one sample line: "YYYY-MM-DD HH:MM:SS <rpm>"                   */
/* ------------------------------------------------------------------ */
static int log_rpm(double rpm)
{
    time_t     rawtime;
    struct tm  timeinfo;
    char       timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_fp, "%s %.2f\n", timestamp, rpm) < 0) {
        fprintf(stderr, "fprintf to log file failed\n");
        return -1;
    }

    if (fflush(g_log_fp) != 0) {
        fprintf(stderr, "fflush failed\n");
        return -1;
    }

    printf("%s %.2f\n", timestamp, rpm);
    fflush(stdout);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — called on every exit path                         */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Disable alert callback first so no more pulses arrive */
    if (g_pulse_count >= 0) {
        gpioSetAlertFuncEx(SENSOR_PIN, NULL, NULL);
    }

    /* Disable timer */
    if (g_pulse_count >= 0) {
        gpioSetTimerFuncEx(0, 0, NULL, NULL);
    }

    /* Close log file */
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }

    /* Release pigpio resources */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    int rc;

    /* ---- Initialize pigpio ---- */
    rc = gpioInitialise();
    if (rc < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n", rc);
        return EXIT_FAILURE;
    }

    /* ---- Configure sensor pin as input with pull-up ---- */
    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for pin %d\n", SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP) != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for pin %d\n", SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        perror("fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* ---- Register alert callback ---- */
    if (gpioSetAlertFuncEx(SENSOR_PIN, pulse_callback, NULL) != 0) {
        fprintf(stderr, "gpioSetAlertFuncEx failed for pin %d\n", SENSOR_PIN);
        cleanup();
        return EXIT_FAILURE;
    }

    printf("RPM monitoring started on BCM GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR_PIN);
    fflush(stdout);

    /* ---- Main sampling loop ---- */
    while (g_running) {
        int pulses = atomic_exchange(&g_pulse_count, 0);
        double rpm = calculate_rpm(pulses);

        if (log_rpm(rpm) != 0) {
            fprintf(stderr, "Logging failed; continuing.\n");
        }

        /* Sleep 1 second (microseconds) — pigpio timer 0 */
        if (gpioSetTimerFuncEx(0, SAMPLE_US, NULL, NULL) != 0) {
            fprintf(stderr, "gpioSetTimerFuncEx failed\n");
            break;
        }

        /* Wait for the 1-second window to elapse */
        while (g_running && gpioGetTimerTick() < SAMPLE_US) {
            gpioDelay(10000);  /* 10 ms */
        }
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

