/*
 * Quadrature Hall-effect rotation detector using two MLX90217 sensors.
 *
 * Wiring (Raspberry Pi Zero W):
 *   Sensor A signal -> GPIO17 (BCM)
 *   Sensor B signal -> GPIO27 (BCM)
 *   Both sensors VCC -> 3.3 V
 *   Both sensors GND -> GND
 *   (Internal pull-ups enabled on both GPIO pins.)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o rotation_detect rotation_detect.c -lpigpio -lrt
 * Run:
 *   sudo ./rotation_detect
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27
#define LOG_FILE_NAME "rotation_log.txt"

/* Quadrature state machine: two-bit gray code phase tracking. */
typedef enum {
    QUAD_A = 0,
    QUAD_B = 1,
    QUAD_C = 2,
    QUAD_D = 3
} quadrature_state_t;

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;
static pthread_mutex_t g_log_mutex = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t g_rotation_cond = PTHREAD_COND_INITIALIZER;

/* ------------------------------------------------------------------ */
/* Signal handler — graceful shutdown                                  */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
    pthread_cond_signal(&g_rotation_cond);
}

/* ------------------------------------------------------------------ */
/* Timestamp helper: "YYYY-MM-DD HH:MM:SS.mmm"                         */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        snprintf(buf, len, "TIMESTAMP_ERROR");
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t used = strlen(buf);
    snprintf(buf + used, len - used, ".%03ld", ts.tv_nsec / 1000000L);
}

/* ------------------------------------------------------------------ */
/* Log a rotation event to the file                                    */
/* ------------------------------------------------------------------ */
static void log_rotation(const char *direction)
{
    char ts[40];
    get_timestamp(ts, sizeof(ts));

    pthread_mutex_lock(&g_log_mutex);
    if (g_log_file != NULL) {
        fprintf(g_log_file, "%s: %s\n", ts, direction);
        fflush(g_log_file);
    }
    pthread_mutex_unlock(&g_log_mutex);
}

/* ------------------------------------------------------------------ */
/* pigpio alert callback — runs in pigpio thread context               */
/* ------------------------------------------------------------------ */
static void rotation_alert_cb(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)tick;
    (void)userdata;

    if (level != 0 && level != 1) {
        return; /* ignore timeout / no-change alerts */
    }

    static quadrature_state_t prev_state = QUAD_A;
    static int first_event = 1;

    quadrature_state_t current_state;

    if (gpio == SENSOR_A_GPIO) {
        if (level == 1) {
            current_state = (prev_state == QUAD_A) ? QUAD_B :
                            (prev_state == QUAD_B) ? QUAD_C :
                            (prev_state == QUAD_C) ? QUAD_D : QUAD_A;
        } else {
            current_state = (prev_state == QUAD_A) ? QUAD_D :
                            (prev_state == QUAD_D) ? QUAD_C :
                            (prev_state == QUAD_C) ? QUAD_B : QUAD_A;
        }
    } else if (gpio == SENSOR_B_GPIO) {
        if (level == 1) {
            current_state = (prev_state == QUAD_A) ? QUAD_C :
                            (prev_state == QUAD_C) ? QUAD_B :
                            (prev_state == QUAD_B) ? QUAD_D : QUAD_A;
        } else {
            current_state = (prev_state == QUAD_A) ? QUAD_B :
                            (prev_state == QUAD_B) ? QUAD_D :
                            (prev_state == QUAD_D) ? QUAD_C : QUAD_A;
        }
    } else {
        return;
    }

    if (!first_event && current_state != prev_state) {
        if (current_state == QUAD_B) {
            log_rotation("Clockwise");
        } else if (current_state == QUAD_C) {
            log_rotation("Counter-Clockwise");
        }
    }

    prev_state = current_state;
    first_event = 0;

    pthread_cond_signal(&g_rotation_cond);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins as inputs with pull-ups ---- */
    if (gpioSetMode(SENSOR_A_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_A_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_B_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n", SENSOR_B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", SENSOR_A_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on GPIO%d.\n", SENSOR_B_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("Error opening log file");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Register alert callbacks ---- */
    if (gpioSetAlertFuncEx(SENSOR_A_GPIO, rotation_alert_cb, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert on GPIO%d.\n", SENSOR_A_GPIO);
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetAlertFuncEx(SENSOR_B_GPIO, rotation_alert_cb, NULL) != 0) {
        fprintf(stderr, "Error: failed to register alert on GPIO%d.\n", SENSOR_B_GPIO);
        gpioSetAlertFuncEx(SENSOR_A_GPIO, NULL, NULL);
        fclose(g_log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Rotation detection started.\n");
    printf("  Sensor A: GPIO%d\n", SENSOR_A_GPIO);
    printf("  Sensor B: GPIO%d\n", SENSOR_B_GPIO);
    printf("  Log file: %s\n", LOG_FILE_NAME);
    printf("Press Ctrl+C to exit.\n");

    /* ---- Main loop — wait for condition or signal ---- */
    while (g_running) {
        pthread_cond_wait(&g_rotation_cond, &g_log_mutex);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");

    gpioSetAlertFuncEx(SENSOR_A_GPIO, NULL, NULL);
    gpioSetAlertFuncEx(SENSOR_B_GPIO, NULL, NULL);

    pthread_mutex_lock(&g_log_mutex);
    if (g_log_file != NULL) {
        fflush(g_log_file);
        fclose(g_log_file);
        g_log_file = NULL;
    }
    pthread_mutex_unlock(&g_log_mutex);

    gpioTerminate();

    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

