#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME  "gpiochip0"
#define TOUCH_SENSOR_PIN 23   /* BCM 23, physical pin 16 */
#define LED_PIN         18   /* BCM 18, physical pin 12 */
#define POLL_INTERVAL_US 50000  /* 50 ms */

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signum)
{
    (void)signum;
    program_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *touch_line = NULL;
    struct gpiod_line *led_line = NULL;
    int ret;

    openlog("touch_led_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting touch sensor (BCM %d) -> LED (BCM %d) monitor",
           TOUCH_SENSOR_PIN, LED_PIN);

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to install SIGINT handler: %s", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "Failed to install SIGTERM handler: %s", strerror(errno));
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        syslog(LOG_ERR, "Failed to open %s: %s", GPIO_CHIP_NAME, strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    /* Get the touch sensor line (input) */
    touch_line = gpiod_chip_get_line(chip, TOUCH_SENSOR_PIN);
    if (touch_line == NULL) {
        syslog(LOG_ERR, "Failed to get touch sensor line (BCM %d): %s",
               TOUCH_SENSOR_PIN, strerror(errno));
        goto cleanup_chip;
    }

    ret = gpiod_line_request_input(touch_line, "touch_sensor");
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request touch sensor line as input: %s",
               strerror(errno));
        goto cleanup_chip;
    }

    /* Get the LED line (output, initial value 0) */
    led_line = gpiod_chip_get_line(chip, LED_PIN);
    if (led_line == NULL) {
        syslog(LOG_ERR, "Failed to get LED line (BCM %d): %s",
               LED_PIN, strerror(errno));
        goto cleanup_touch;
    }

    ret = gpiod_line_request_output(led_line, "led_control", 0);
    if (ret < 0) {
        syslog(LOG_ERR, "Failed to request LED line as output: %s",
               strerror(errno));
        goto cleanup_touch;
    }

    syslog(LOG_INFO, "Monitoring started: touch=BCM%d, LED=BCM%d",
           TOUCH_SENSOR_PIN, LED_PIN);

    /* Main polling loop */
    while (program_running) {
        int val = gpiod_line_get_value(touch_line);
        if (val < 0) {
            syslog(LOG_ERR, "Failed to read touch sensor: %s", strerror(errno));
            usleep(POLL_INTERVAL_US);
            continue;
        }

        if (val == 1) {
            syslog(LOG_INFO, "Touch detected");
            ret = gpiod_line_set_value(led_line, 1);
            if (ret < 0) {
                syslog(LOG_ERR, "Failed to turn LED on: %s", strerror(errno));
            }
        } else {
            ret = gpiod_line_set_value(led_line, 0);
            if (ret < 0) {
                syslog(LOG_ERR, "Failed to turn LED off: %s", strerror(errno));
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down gracefully");

    /* Ensure LED is off before releasing resources */
    if (led_line != NULL) {
        gpiod_line_set_value(led_line, 0);
    }

cleanup_touch:
    if (touch_line != NULL) {
        gpiod_line_release(touch_line);
    }
cleanup_chip:
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    closelog();
    return EXIT_SUCCESS;
}

