#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define LED_1_PIN 27
#define LED_2_PIN 22

#define BUFFER_SIZE 100
#define POLL_DELAY_US 50000

typedef struct {
    int sensor_pin;
    time_t timestamp;
    int state;
} Event;

static Event event_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_overflow_count = 0;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

static void add_event(int sensor_pin, int state) {
    event_buffer[buffer_index].sensor_pin = sensor_pin;
    event_buffer[buffer_index].timestamp = time(NULL);
    event_buffer[buffer_index].state = state;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_index == 0) {
        buffer_overflow_count++;
    }
}

static void print_event_buffer(void) {
    printf("\n--- Event Log ---\n");
    int start = (buffer_overflow_count > 0) ? buffer_index : 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("Sensor: %d, Timestamp: %ld, State: %d\n",
               event_buffer[idx].sensor_pin,
               (long)event_buffer[idx].timestamp,
               event_buffer[idx].state);
    }
    printf("Overflow count: %d\n", buffer_overflow_count);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: could not register SIGINT handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: could not register SIGTERM handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SENSOR_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", SENSOR_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", LED_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", LED_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED1 state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialise LED2 state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int prev_s1 = gpioRead(SENSOR_1_PIN);
    int prev_s2 = gpioRead(SENSOR_2_PIN);
    if (prev_s1 < 0 || prev_s2 < 0) {
        fprintf(stderr, "Error: failed to read initial sensor states\n");
        gpioWrite(LED_1_PIN, 0);
        gpioWrite(LED_2_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    add_event(SENSOR_1_PIN, prev_s1);
    add_event(SENSOR_2_PIN, prev_s2);

    while (program_running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0) {
            fprintf(stderr, "Error: failed to read sensor 1 (GPIO%d)\n", SENSOR_1_PIN);
        } else if (s1 != prev_s1) {
            if (gpioWrite(LED_1_PIN, s1) != 0) {
                fprintf(stderr, "Error: failed to write LED 1 (GPIO%d)\n", LED_1_PIN);
            }
            add_event(SENSOR_1_PIN, s1);
            prev_s1 = s1;
        }

        if (s2 < 0) {
            fprintf(stderr, "Error: failed to read sensor 2 (GPIO%d)\n", SENSOR_2_PIN);
        } else if (s2 != prev_s2) {
            if (gpioWrite(LED_2_PIN, s2) != 0) {
                fprintf(stderr, "Error: failed to write LED 2 (GPIO%d)\n", LED_2_PIN);
            }
            add_event(SENSOR_2_PIN, s2);
            prev_s2 = s2;
        }

        gpioDelay(POLL_DELAY_US);
    }

    if (gpioWrite(LED_1_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to turn off LED 1 during shutdown\n");
    }
    if (gpioWrite(LED_2_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to turn off LED 2 during shutdown\n");
    }

    print_event_buffer();

    gpioTerminate();
    return EXIT_SUCCESS;
}

