#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Si1182 I2C address (7-bit) */
#define SI1182_ADDR 0x60

/* Si1182 register addresses */
#define SI1182_REG_PART_ID       0x00
#define SI1182_REG_HW_REV        0x01
#define SI1182_REG_SEQ_ID        0x02
#define SI1182_REG_INT_CFG       0x03
#define SI1182_REG_IRQ_ENABLE    0x04
#define SI1182_REG_IRQ_STATUS    0x05
#define SI1182_REG_HW_KEY        0x07
#define SI1182_REG_MEAS_RATE0    0x08
#define SI1182_REG_MEAS_RATE1    0x09
#define SI1182_REG_ALS_RATE0     0x0A
#define SI1182_REG_ALS_RATE1     0x0B
#define SI1182_REG_PS_RATE0      0x0C
#define SI1182_REG_PS_RATE1      0x0D
#define SI1182_REG_PS_LED21      0x0E
#define SI1182_REG_PS_LED3       0x0F
#define SI1182_REG_PARAM_WR      0x17
#define SI1182_REG_COMMAND       0x18
#define SI1182_REG_RESPONSE      0x20
#define SI1182_REG_ALS_VIS_DATA0 0x22
#define SI1182_REG_ALS_VIS_DATA1 0x23
#define SI1182_REG_ALS_IR_DATA0  0x24
#define SI1182_REG_ALS_IR_DATA1  0x25
#define SI1182_REG_PS1_DATA0     0x26
#define SI1182_REG_PS1_DATA1     0x27
#define SI1182_REG_PS2_DATA0     0x28
#define SI1182_REG_PS2_DATA1     0x29
#define SI1182_REG_PS3_DATA0     0x2A
#define SI1182_REG_PS3_DATA1     0x2B

/* Si1182 command codes */
#define SI1182_CMD_RESET         0x01
#define SI1182_CMD_PS_FORCE      0x05
#define SI1182_CMD_ALS_FORCE     0x06
#define SI1182_CMD_PSALS_FORCE   0x07

/* Si1182 parameter offsets */
#define SI1182_PARAM_CHLIST      0x01
#define SI1182_PARAM_PSLED12     0x02
#define SI1182_PARAM_PS1_ADCMUX  0x03
#define SI1182_PARAM_PS2_ADCMUX  0x04
#define SI1182_PARAM_PS3_ADCMUX  0x05

/* Expected PART_ID for Si1182 */
#define SI1182_PART_ID_EXPECTED  0x82

/* Global resources for signal handler cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Write a single byte to a Si1182 register */
static int si1182_write_reg(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing reg 0x%02X = 0x%02X: %d\n", reg, value, rc);
    }
    return rc;
}

/* Read a single byte from a Si1182 register */
static int si1182_read_reg(int handle, uint8_t reg) {
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading reg 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

/* Write a parameter to the Si1182 parameter RAM */
static int si1182_write_param(int handle, uint8_t param, uint8_t value) {
    if (si1182_write_reg(handle, SI1182_REG_PARAM_WR, value) < 0) return -1;
    if (si1182_write_reg(handle, SI1182_REG_COMMAND, param) < 0) return -1;
    return 0;
}

/* Initialize the Si1182 sensor */
static int si1182_init(int handle) {
    int part_id;

    /* Reset the sensor */
    if (si1182_write_reg(handle, SI1182_REG_COMMAND, SI1182_CMD_RESET) < 0) return -1;
    gpioDelay(10000); /* 10 ms delay after reset */

    /* Verify Part ID */
    part_id = si1182_read_reg(handle, SI1182_REG_PART_ID);
    if (part_id < 0) return -1;
    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected Part ID: 0x%02X (expected 0x%02X)\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }

    /* Configure measurement rates */
    if (si1182_write_reg(handle, SI1182_REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (si1182_write_reg(handle, SI1182_REG_MEAS_RATE1, 0x00) < 0) return -1;
    if (si1182_write_reg(handle, SI1182_REG_ALS_RATE0, 0x00) < 0) return -1;
    if (si1182_write_reg(handle, SI1182_REG_ALS_RATE1, 0x00) < 0) return -1;
    if (si1182_write_reg(handle, SI1182_REG_PS_RATE0, 0x00) < 0) return -1;
    if (si1182_write_reg(handle, SI1182_REG_PS_RATE1, 0x00) < 0) return -1;

    /* Configure LED current for PS1 */
    if (si1182_write_reg(handle, SI1182_REG_PS_LED21, 0x0F) < 0) return -1;

    /* Configure channel list: enable PS1, ALS_VIS, ALS_IR */
    if (si1182_write_param(handle, SI1182_PARAM_CHLIST, 0x07) < 0) return -1;

    /* Configure PS1 ADC mux to large photodiode */
    if (si1182_write_param(handle, SI1182_PARAM_PS1_ADCMUX, 0x03) < 0) return -1;

    /* Set HW_KEY to 0x00 to enable normal operation */
    if (si1182_write_reg(handle, SI1182_REG_HW_KEY, 0x00) < 0) return -1;

    return 0;
}

/* Read heart rate and SpO2 data from the Si1182 */
static int si1182_read_data(int handle, int *heart_rate, int *spo2) {
    int ps1_data, als_vis_data, als_ir_data;

    /* Trigger a forced PS + ALS measurement */
    if (si1182_write_reg(handle, SI1182_REG_COMMAND, SI1182_CMD_PSALS_FORCE) < 0) return -1;
    gpioDelay(10000); /* 10 ms delay for measurement */

    /* Read PS1 data (large photodiode) */
    ps1_data = si1182_read_reg(handle, SI1182_REG_PS1_DATA0);
    if (ps1_data < 0) return -1;
    als_vis_data = si1182_read_reg(handle, SI1182_REG_ALS_VIS_DATA0);
    if (als_vis_data < 0) return -1;
    als_ir_data = si1182_read_reg(handle, SI1182_REG_ALS_IR_DATA0);
    if (als_ir_data < 0) return -1;

    /* Basic data validation */
    if (ps1_data == 0 || als_vis_data == 0 || als_ir_data == 0) {
        fprintf(stderr, "Warning: Sensor data is zero (PS1=%d, ALS_VIS=%d, ALS_IR=%d)\n",
                ps1_data, als_vis_data, als_ir_data);
    }

    /*
     * Placeholder conversion formulas.
     * A real implementation would use the Si1182's built-in
     * heart-rate and SpO2 algorithms, or a custom algorithm
     * based on the raw ADC values.
     */
    *heart_rate = (int)(ps1_data * 0.5);
    *spo2 = (int)(100.0 - (als_ir_data * 0.1));

    /* Clamp SpO2 to valid range */
    if (*spo2 < 70) *spo2 = 70;
    if (*spo2 > 100) *spo2 = 100;

    return 0;
}

/* Log data to file */
static void log_data(FILE *fp, int heart_rate, int spo2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, Heart Rate: %d BPM, SpO2: %d%%\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            heart_rate, spo2);
    fflush(fp);
}

int main(void) {
    int heart_rate, spo2;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at Si1182 address */
    i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n",
                SI1182_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize the Si1182 sensor */
    if (si1182_init(i2c_handle) < 0) {
        fprintf(stderr, "Si1182 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Open the log file in append mode */
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Install signal handler for Ctrl+C */
    signal(SIGINT, signal_handler);

    /* Main loop */
    while (program_running) {
        if (si1182_read_data(i2c_handle, &heart_rate, &spo2) == 0) {
            log_data(log_file, heart_rate, spo2);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }
        gpioDelay(1000000); /* 1 second delay */
    }

    /* Cleanup */
    if (i2c_handle >= 0) i2cClose(i2c_handle);
    if (log_file != NULL) fclose(log_file);
    gpioTerminate();

    return 0;
}

