#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SENSOR_1_PIN 17
#define SENSOR_2_PIN 18
#define ALARM_PIN 27

#define TILT_THRESHOLD_MS 2000
#define POLL_INTERVAL_US 100000
#define LOG_FILE_NAME "bridge_integrity.log"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event_type) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm tm_info;
    char timestamp[32];
    if (localtime_r(&now, &tm_info) == NULL) return;
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) return;
    fprintf(log_file, "%s - %s\n", timestamp, event_type);
    fflush(log_file);
}

static void cleanup(void) {
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    if (gpioInitialise() >= 0) {
        gpioWrite(ALARM_PIN, 0);
        gpioTerminate();
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_1_PIN, PI_INPUT) != 0 ||
        gpioSetMode(SENSOR_2_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ALARM_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO modes.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN) != 0 ||
        gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down resistors.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALARM_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize alarm pin LOW.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (!log_file) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE_NAME, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: failed to install signal handlers: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    log_event("Monitoring started");

    uint32_t tilt_start_tick = 0;
    int alarm_active = 0;
    int tilt_in_progress = 0;

    while (running) {
        int s1 = gpioRead(SENSOR_1_PIN);
        int s2 = gpioRead(SENSOR_2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Error: gpioRead failed (s1=%d, s2=%d).\n", s1, s2);
            break;
        }

        if (s1 == 1 || s2 == 1) {
            if (!tilt_in_progress) {
                tilt_in_progress = 1;
                tilt_start_tick = gpioTick();
                log_event("Tilt started");
            }

            uint32_t elapsed = gpioTick() - tilt_start_tick;
            if (elapsed >= TILT_THRESHOLD_MS * 1000) {
                if (!alarm_active) {
                    if (gpioWrite(ALARM_PIN, 1) == 0) {
                        alarm_active = 1;
                        log_event("Threshold exceeded - alarm activated");
                    } else {
                        fprintf(stderr, "Error: failed to activate alarm.\n");
                    }
                }
            }
        } else {
            if (tilt_in_progress) {
                tilt_in_progress = 0;
                log_event("Tilt ended");
            }
            if (alarm_active) {
                if (gpioWrite(ALARM_PIN, 0) == 0) {
                    alarm_active = 0;
                    log_event("Alarm deactivated");
                } else {
                    fprintf(stderr, "Error: failed to deactivate alarm.\n");
                }
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    log_event("Monitoring stopped");
    cleanup();
    return EXIT_SUCCESS;
}

