/*
 * seismic.c — Raspberry Pi 3 Model B+
 *
 * Reads an Omron D7S-A0011 seismic sensor over I2C (bus 1, SDA=GPIO2, SCL=GPIO3)
 * and lights an LED on GPIO17 when the Euclidean vibration magnitude exceeds 500.
 *
 * Build:  gcc -O2 -Wall -o seismic seismic.c -lthe -lm -lrt
 * Run:    ./seismic
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#include <linux/i2c-dev.h>
#include <sys/ioctl.h>
#include <fcntl.h>

#include <the/driver.h>

#define I2C_BUS          "/dev/i2c-1"
#define D7S_I2C_ADDR     0x1D
#define LED_GPIO         17
#define THRESHOLD        500
#define POLL_DELAY_MS    100
#define MAX_RETRIES      3
#define LOG_FILE         "seismic_events.log"

/* D7S-A0011 register map (16-bit registers, big-endian on the bus) */
#define REG_CTRL1        0x01
#define REG_CTRL2        0x02
#define REG_STATUS       0x03
#define REG_OUT_TEMP_L   0x04
#define REG_OUT_TEMP_H   0x05
#define REG_OUT_X_L      0x06
#define REG_OUT_X_H      0x07
#define REG_OUT_Y_L      0x08
#define REG_OUT_Y_H      0x09
#define REG_OUT_Z_L      0x0A
#define REG_OUT_Z_H      0x0B

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to a D7S register (address + 2 data bytes).    */
static int d7s_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val & 0xFF);          /* low byte first  */
    buf[2] = (uint8_t)((val >> 8) & 0xFF);   /* high byte second */

    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit value from a D7S register (2 data bytes + address).   */
static int d7s_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t addr = reg;
    uint8_t data[2];

    if (write(fd, &addr, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
static int d7s_init(int fd)
{
    uint16_t ctrl1 = 0;

    /* Verify sensor presence by reading CTRL1 */
    if (d7s_read_reg16(fd, REG_CTRL1, &ctrl1) < 0) {
        fprintf(stderr, "D7S not responding on 0x%02X\n", D7S_I2C_ADDR);
        return -1;
    }

    /* Clear power-down bit (CTRL1 bit 0 = ODR) to enable sensor */
    if (d7s_write_reg16(fd, REG_CTRL1, ctrl1 & ~0x0001) < 0)
        return -1;

    /* Allow sensor to settle after power-up */
    usleep(50 * 1000);

    printf("D7S initialised (CTRL1=0x%04X).\n", ctrl1);
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_sensor(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint16_t rx, ry, rz;

    if (d7s_read_reg16(fd, REG_OUT_X_L, &rx) < 0) return -1;
    if (d7s_read_reg16(fd, REG_OUT_Y_L, &ry) < 0) return -1;
    if (d7s_read_reg16(fd, REG_OUT_Z_L, &rz) < 0) return -1;

    *x = (int16_t)rx;
    *y = (int16_t)ry;
    *z = (int16_t)rz;
    return 0;
}

/* ------------------------------------------------------------------ */
static int calculate_magnitude(int16_t x, int16_t y, int16_t z)
{
    return (int)sqrt((double)x * x + (double)y * y + (double)z * z);
}

/* ------------------------------------------------------------------ */
static void log_event(FILE *fp, int magnitude)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    fprintf(fp, "%s - Magnitude: %d\n", ts, magnitude);
    fflush(fp);
    printf("%s - Magnitude: %d\n", ts, magnitude);
}

/* ------------------------------------------------------------------ */
static void trigger_alert(int gpio)
{
    if (gpioWrite(gpio, 1) < 0)
        fprintf(stderr, "Failed to set LED GPIO %d high\n", gpio);
    usleep(1000 * 1000);
    if (gpioWrite(gpio, 0) < 0)
        fprintf(stderr, "Failed to set LED GPIO %d low\n", gpio);
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log) {
        fclose(g_log);
        g_log = NULL;
    }
    /* Ensure LED is off before exiting */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- LED GPIO setup --------------------------------------------- */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* --- I2C open --------------------------------------------------- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_I2C_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave 0x%02X: %s\n",
                D7S_I2C_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Sensor init ------------------------------------------------ */
    if (d7s_init(g_i2c_fd) < 0) {
        fprintf(stderr, "D7S initialisation failed — sensor absent or bus error.\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Log file --------------------------------------------------- */
    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        int16_t x = 0, y = 0, z = 0;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; ++attempt) {
            if (read_sensor(g_i2c_fd, &x, &y, &z) == 0) {
                ok = 1;
                break;
            }
            usleep(10 * 1000);
        }

        if (!ok) {
            fprintf(stderr, "Sensor read failed after %d retries.\n", MAX_RETRIES);
            continue;
        }

        int mag = calculate_magnitude(x, y, z);

        if (mag > THRESHOLD) {
            log_event(g_log, mag);
            trigger_alert(LED_GPIO);
        }

        usleep(POLL_DELAY_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

