/*
 * flame_monitor.c — Raspberry Pi 3 Model B+
 *
 * Monitors five Keyes KY-026 flame sensors on BCM GPIO 2, 3, 4, 17, 27.
 * Logs confirmed flame transitions to /var/log/flame_events.log and
 * reports events via syslog.  Uses libgpiod (gpiod_line_request_input).
 *
 * Build:  gcc -O2 -Wall -Wextra -o flame_monitor flame_monitor.c -lgpiod
 * Run:    sudo ./flame_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <gpiod.h>

#define NUM_SENSORS      5
#define LOG_FILE         "/var/log/flame_events.log"
#define DEBOUNCE_MS      50
#define POLL_INTERVAL_S  1
#define TS_LEN           32
#define MSG_LEN          256

static const unsigned int sensor_pins[NUM_SENSORS] = {2, 3, 4, 17, 27};
static const char *sensor_ids[NUM_SENSORS] = {"S1", "S2", "S3", "S4", "S5"};

static volatile sig_atomic_t program_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Format current UTC time as ISO-8601:  YYYY-MM-DDTHH:MM:SSZ
 * Returns 0 on success, -1 on failure.
 */
static int get_iso8601_timestamp(char *buf, size_t len)
{
    time_t rawtime;
    struct tm tm_utc;

    if (time(&rawtime) == (time_t)-1)
        return -1;
    if (gmtime_r(&rawtime, &tm_utc) == NULL)
        return -1;
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0)
        return -1;
    return 0;
}

/*
 * Append a flame event line to the log file.
 * Returns 0 on success, -1 on failure (message logged to syslog).
 */
static int log_flame_event(const char *sensor_id, unsigned int pin)
{
    char ts[TS_LEN];
    char msg[MSG_LEN];

    if (get_iso8601_timestamp(ts, sizeof(ts)) != 0) {
        syslog(LOG_ERR, "Failed to generate timestamp: %s", strerror(errno));
        return -1;
    }

    if (snprintf(msg, sizeof(msg), "%s - Sensor ID: %s (GPIO %u) - Flame Detected",
                 ts, sensor_id, pin) >= (int)sizeof(msg)) {
        syslog(LOG_ERR, "Log message truncated for sensor %s", sensor_id);
        return -1;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        syslog(LOG_ERR, "Failed to open log file %s: %s", LOG_FILE, strerror(errno));
        return -1;
    }

    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_WARNING, "flock(LOCK_EX) failed on log file: %s", strerror(errno));
        /* non-fatal — continue anyway */
    }

    if (fprintf(fp, "%s\n", msg) < 0) {
        syslog(LOG_ERR, "fprintf to log file failed: %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (fflush(fp) == EOF) {
        syslog(LOG_ERR, "fflush on log file failed: %s", strerror(errno));
        flock(fileno(fp), LOCK_UN);
        fclose(fp);
        return -1;
    }

    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_WARNING, "flock(LOCK_UN) failed: %s", strerror(errno));
    }

    if (fclose(fp) == EOF) {
        syslog(LOG_ERR, "fclose on log file failed: %s", strerror(errno));
        return -1;
    }

    syslog(LOG_INFO, "%s", msg);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_SENSORS];
    int prev_state[NUM_SENSORS];
    int ret = EXIT_FAILURE;

    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = NULL;
        prev_state[i] = 1;  /* assume no flame at startup */
    }

    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Flame monitor starting (libgpiod)");

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed: %s", strerror(errno));
        goto cleanup;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed: %s", strerror(errno));
        goto cleanup;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        syslog(LOG_ERR, "Failed to open gpiochip0: %s", strerror(errno));
        goto cleanup;
    }

    /* Get and request each line as input */
    for (int i = 0; i < NUM_SENSORS; i++) {
        lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!lines[i]) {
            syslog(LOG_ERR, "Failed to get GPIO line %u: %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_input(lines[i], "flame_monitor") < 0) {
            syslog(LOG_ERR, "Failed to request GPIO %u as input: %s",
                   sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        syslog(LOG_INFO, "Sensor %s (GPIO %u) initialized",
               sensor_ids[i], sensor_pins[i]);
    }

    syslog(LOG_INFO, "Monitoring started. Press Ctrl+C to exit.");

    /* Main polling loop */
    while (program_running) {
        for (int i = 0; i < NUM_SENSORS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                syslog(LOG_ERR, "Read error on sensor %s (GPIO %u): %s",
                       sensor_ids[i], sensor_pins[i], strerror(errno));
                continue;
            }

            /* Detect HIGH -> LOW transition */
            if (prev_state[i] == 1 && val == 0) {
                /* Debounce: re-read after 50 ms */
                usleep(DEBOUNCE_MS * 1000);
                int debounced = gpiod_line_get_value(lines[i]);
                if (debounced < 0) {
                    syslog(LOG_ERR, "Debounce read error on sensor %s (GPIO %u): %s",
                           sensor_ids[i], sensor_pins[i], strerror(errno));
                    continue;
                }
                if (debounced == 0) {
                    if (log_flame_event(sensor_ids[i], sensor_pins[i]) != 0) {
                        syslog(LOG_ERR, "Failed to log flame event for sensor %s",
                               sensor_ids[i]);
                    }
                }
            }
            prev_state[i] = val;
        }
        sleep(POLL_INTERVAL_S);
    }

    syslog(LOG_INFO, "Shutting down gracefully.");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release all requested lines */
    for (int i = 0; i < NUM_SENSORS; i++) {
        if (lines[i])
            gpiod_line_release(lines[i]);
    }
    if (chip)
        gpiod_chip_close(chip);
    closelog();
    return ret;
}

