 *   OUT0 -> GPIO5   OUT1 -> GPIO6   OUT2 -> GPIO13  OUT3 -> GPIO19
 *   OUT4 -> GPIO26  OUT5 -> GPIO12  OUT6 -> GPIO16  OUT7 -> GPIO20
 *
 * Build:  gcc -Wall -Wextra -o ttp226 ttp226.c -lgpiod
 * Run:    ./ttp226
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>
#include <errno.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <gpiod.h>

#define NUM_SENSORS 8
#define POLL_INTERVAL_MS 50

static const unsigned int sensor_pins[NUM_SENSORS] = {
    5,  6,  13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void print_timestamp(void)
{
    time_t rawtime;
    struct tm timeinfo;
    char buffer[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) != NULL) {
        strftime(buffer, sizeof(buffer), "%Y-%m-%dT%H:%M:%S", &timeinfo);
        printf("[%s] ", buffer);
    } else {
        printf("[unknown-time] ");
    }
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line_bulk lines;
    struct gpiod_line_request_config config;
    int prev_states[NUM_SENSORS];
    int ret;
    int i;

    /* Initialize previous states to -1 so the first poll prints all states */
    for (i = 0; i < NUM_SENSORS; i++)
        prev_states[i] = -1;

    /* Register signal handler for graceful shutdown */
    if (signal(SIGINT, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: Failed to register SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Error: Failed to open gpiochip0: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize line bulk for bulk operations */
    gpiod_line_bulk_init(&lines);

    /* Add all sensor lines to the bulk */
    for (i = 0; i < NUM_SENSORS; i++) {
        struct gpiod_line *line = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (line == NULL) {
            fprintf(stderr, "Error: Failed to get GPIO line %u: %s\n",
                    sensor_pins[i], strerror(errno));
            gpiod_chip_close(chip);
            return EXIT_FAILURE;
        }
        gpiod_line_bulk_add(&lines, line);
    }

    /* Configure all lines as inputs */
    memset(&config, 0, sizeof(config));
    config.consumer = "ttp226-touch";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;
    config.flags = 0;

    ret = gpiod_line_request_bulk(&lines, &config, 0);
    if (ret < 0) {
        fprintf(stderr, "Error: Failed to request GPIO lines as input: %s\n",
                strerror(errno));
        gpiod_chip_close(chip);
        return EXIT_FAILURE;
    }

    printf("TTP226 touch sensor monitoring started.\n");
    printf("Pins: BCM %u, %u, %u, %u, %u, %u, %u, %u\n",
           sensor_pins[0], sensor_pins[1], sensor_pins[2], sensor_pins[3],
           sensor_pins[4], sensor_pins[5], sensor_pins[6], sensor_pins[7]);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* Main polling loop */
    while (program_running) {
        ret = gpiod_line_get_value_bulk(&lines, prev_states);
        if (ret < 0) {
            fprintf(stderr, "Error: Failed to read GPIO values: %s\n",
                    strerror(errno));
            break;
        }

        for (i = 0; i < NUM_SENSORS; i++) {
            if (prev_states[i] != -1 && prev_states[i] != ret) {
                print_timestamp();
                printf("Sensor %d (BCM GPIO %u): %s\n",
                       i, sensor_pins[i],
                       (ret == 1) ? "TOUCHED" : "RELEASED");
                fflush(stdout);
            }
        }

        /* Update previous states */
        for (i = 0; i < NUM_SENSORS; i++)
            prev_states[i] = ret;

        /* Sleep for the poll interval, checking for signals */
        struct timespec ts = {
            .tv_sec = POLL_INTERVAL_MS / 1000,
            .tv_nsec = (POLL_INTERVAL_MS % 1000) * 1000000L
        };
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR && program_running) {
            /* Retry with remaining time if interrupted by signal */
        }
    }

    /* Clean up resources */
    gpiod_line_release_bulk(&lines);
    gpiod_chip_close(chip);

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

