/*
 * Adaptive Grow Light System — Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - VEML7700 lux sensor on I2C bus 1 (address 0x10)
 *   - Grow light LED on GPIO18 (BCM) with hardware PWM, 1000 Hz
 *
 * Behavior:
 *   Samples ambient light every 1 s, maps lux to a brightness level
 *   (100 % at <100, 75 % at <500, 50 % at <1000, 25 % at >=1000),
 *   applies the level as a PWM duty cycle, and logs each sample to
 *   grow_log.txt.  Handles I2C / sensor errors and SIGINT/SIGTERM.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ----------------------------- Constants ----------------------------- */
#define I2C_BUS            1
#define VEML7700_ADDR      0x10
#define LED_GPIO           18
#define PWM_FREQ_HZ        1000
#define PWM_RANGE          100
#define SAMPLE_INTERVAL_S  1
#define LOG_FILE           "grow_log.txt"

/* VEML7700 register addresses (16-bit, big-endian on the bus) */
#define VEML7700_REG_ALS_CONF  0x00
#define VEML7700_REG_ALS_DATA  0x04

/* ALS_CONF: ALS_EN=1, ALS_IT=100 ms (0x0000), ALS_PERS=1 (0x0000) */
#define VEML7700_CONF_VALUE   0x0000

/* --------------------------- Global state ---------------------------- */
static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd   = -1;
static FILE *g_log_fp  = NULL;

/* ------------------------- Function prototypes ------------------------ */
static void signal_handler(int sig);
static int  veml7700_init(int fd);
static int  veml7700_read_lux(int fd, uint16_t *lux_out);
static int  set_led_brightness(int gpio, int brightness);
static int  log_data(FILE *fp, uint16_t lux, int brightness, int err);
static void cleanup(void);

/* ------------------------------ Signal handler ------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* --------------------------- VEML7700 helpers ------------------------- */
static int veml7700_init(int fd)
{
    uint8_t buf[3];

    /* Write 16-bit configuration value, big-endian */
    buf[0] = VEML7700_REG_ALS_CONF;
    buf[1] = (uint8_t)(VEML7700_CONF_VALUE >> 8);
    buf[2] = (uint8_t)(VEML7700_CONF_VALUE & 0xFF);

    if (write(fd, buf, 3) != 3) {
        fprintf(stderr, "VEML7700 config write failed: %s\n", strerror(errno));
        return -1;
    }

    /* Allow first integration to complete (100 ms) */
    gpioDelay(100000);
    return 0;
}

static int veml7700_read_lux(int fd, uint16_t *lux_out)
{
    uint8_t reg = VEML7700_REG_ALS_DATA;
    uint8_t data[2];

    /* Set register pointer */
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "VEML7700 set register pointer failed: %s\n",
                strerror(errno));
        return -1;
    }

    /* Read 2 bytes (big-endian) */
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "VEML7700 data read failed: %s\n", strerror(errno));
        return -1;
    }

    *lux_out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

/* ----------------------------- LED control ---------------------------- */
static int set_led_brightness(int gpio, int brightness)
{
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;

    if (gpioPWM(gpio, brightness) != 0) {
        fprintf(stderr, "gpioPWM failed on GPIO %d\n", gpio);
        return -1;
    }
    return 0;
}

/* ------------------------------- Logging ------------------------------ */
static int log_data(FILE *fp, uint16_t lux, int brightness, int err)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (fprintf(fp, "%s,%u,%d,%d\n", ts, lux, brightness, err) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------- Cleanup ------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Ensure LED is off before terminating pigpio */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* --------------------------------- Main -------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    char i2c_dev[32];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    g_i2c_fd = open(i2c_dev, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", i2c_dev, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Acquire I2C device */
    if (ioctl(g_i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus for 0x%02X: %s\n",
                VEML7700_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize VEML7700 */
    if (veml7700_init(g_i2c_fd) != 0) {
        fprintf(stderr, "VEML7700 initialization failed — sensor may be absent\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO for hardware PWM */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", LED_GPIO);
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed for GPIO %d\n", LED_GPIO);
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "gpioSetPWMrange failed for GPIO %d\n", LED_GPIO);
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(LED_GPIO, 0) != 0) {
        fprintf(stderr, "gpioPWM initial off failed for GPIO %d\n", LED_GPIO);
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Adaptive Grow Light started.  Sampling every %d s.  Ctrl+C to exit.\n",
           SAMPLE_INTERVAL_S);

    /* Main control loop */
    while (g_running) {
        uint16_t lux = 0;
        int err = 0;

        if (veml7700_read_lux(g_i2c_fd, &lux) != 0) {
            err = -1;
            fprintf(stderr, "Sensor read error — turning off LED\n");
            set_led_brightness(LED_GPIO, 0);
        } else {
            /* Map lux to brightness level (0-100) */
            int brightness;
            if (lux < 100) {
                brightness = 100;
            } else if (lux < 500) {
                brightness = 75;
            } else if (lux < 1000) {
                brightness = 50;
            } else {
                brightness = 25;
            }

            if (set_led_brightness(LED_GPIO, brightness) != 0) {
                err = -2;
            } else {
                if (log_data(g_log_fp, lux, brightness, 0) != 0) {
                    fprintf(stderr, "Logging failed\n");
                }
            }
        }

        if (err != 0) {
            log_data(g_log_fp, 0, 0, err);
        }

        /* Sleep SAMPLE_INTERVAL_S, but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

