    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);

    if (fprintf(fp, "%s,%u,%d,%d\n", ts, lux, brightness, err) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush log failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------- Cleanup ------------------------------ */
static void cleanup(void)
{
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    /* Ensure LED is off before terminating pigpio */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* --------------------------------- Main -------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    char i2c_dev[32];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);
    g_i2c_fd = open(i2c_dev, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", i2c_dev, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Acquire I2C device */
    if (ioctl(g_i2c_fd, I2C_SLAVE, VEML7700_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus for 0x%02X: %s\n",
                VEML7700_ADDR, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize VEML7700 */
    if (veml7700_init(g_i2c_fd) != 0) {
        fprintf(stderr, "VEML7700 initialization failed — sensor may be absent\n");
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO for hardware PWM */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", LED_GPIO);
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQ_HZ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed for GPIO %d\n", LED_GPIO);
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) != 0) {
        fprintf(stderr, "gpioSetPWMrange failed for GPIO %d\n", LED_GPIO);
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioPWM(LED_GPIO, 0) != 0) {
        fprintf(stderr, "gpioPWM initial off failed for GPIO %d\n", LED_GPIO);
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Adaptive Grow Light started.  Sampling every %d s.  Ctrl+C to exit.\n",
           SAMPLE_INTERVAL_S);

    /* Main control loop */
    while (g_running) {
        uint16_t lux = 0;
        int err = 0;

        if (veml7700_read_lux(g_i2c_fd, &lux) != 0) {
            err = -1;
            fprintf(stderr, "Sensor read error — turning off LED\n");
            set_led_brightness(LED_GPIO, 0);
        } else {
            /* Map lux to brightness level (0-100) */
            int brightness;
            if (lux < 100) {
                brightness = 100;
            } else if (lux < 500) {
                brightness = 75;
            } else if (lux < 1000) {
                brightness = 50;
            } else {
                brightness = 25;
            }

            if (set_led_brightness(LED_GPIO, brightness) != 0) {
                err = -2;
            } else {
                if (log_data(g_log_fp, lux, brightness, 0) != 0) {
                    fprintf(stderr, "Logging failed\n");
                }
            }
        }

        if (err != 0) {
            log_data(g_log_fp, 0, 0, err);
        }

        /* Sleep SAMPLE_INTERVAL_S, but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL_S && g_running; i++) {
            sleep(1);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

