#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define NUM_CHANNELS 8
#define LED_PIN 17
#define POLL_DELAY_US 50000  /* 50 ms */
#define LOG_FILE "touch_log.txt"

static const int sensor_pins[NUM_CHANNELS] = {2, 3, 4, 5, 6, 7, 8, 9};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int log_touch_event(int channel)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (!localtime_r(&t, &tm_info)) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s – Channel %d Touched\n", timestamp, channel) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs with pull-down resistors */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(sensor_pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO%d as input\n", sensor_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        if (gpioSetPullUpDown(sensor_pins[i], PI_PUD_DOWN) != 0) {
            fprintf(stderr, "Failed to set pull-down on GPIO%d\n", sensor_pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
    }

    /* Configure LED pin as output and ensure it is off */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise LED state on GPIO%d\n", LED_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    int prev_state[NUM_CHANNELS];
    int curr_state[NUM_CHANNELS];
    for (int i = 0; i < NUM_CHANNELS; i++) {
        prev_state[i] = gpioRead(sensor_pins[i]);
        curr_state[i] = prev_state[i];
    }

    while (running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            curr_state[i] = gpioRead(sensor_pins[i]);
            if (curr_state[i] < 0) {
                fprintf(stderr, "Error reading GPIO%d\n", sensor_pins[i]);
                continue;
            }

            /* Detect rising edge (untouched -> touched) */
            if (curr_state[i] == 1 && prev_state[i] == 0) {
                if (log_touch_event(i + 1) != 0) {
                    fprintf(stderr, "Failed to log touch event for channel %d\n", i + 1);
                }
            }
        }

        /* LED on when any channel is touched, off when all released */
        int led_on = 0;
        for (int i = 0; i < NUM_CHANNELS; i++) {
            if (curr_state[i] == 1) {
                led_on = 1;
                break;
            }
        }

        if (gpioWrite(LED_PIN, led_on) != 0) {
            fprintf(stderr, "Failed to write LED state on GPIO%d\n", LED_PIN);
        }

        prev_state[0] = curr_state[0];
        prev_state[1] = curr_state[1];
        prev_state[2] = curr_state[2];
        prev_state[3] = curr_state[3];
        prev_state[4] = curr_state[4];
        prev_state[5] = curr_state[5];
        prev_state[6] = curr_state[6];
        prev_state[7] = curr_state[7];

        gpioDelay(POLL_DELAY_US);
    }

    /* Clean shutdown */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

