static int i2c_write_reg16(int fd, uint8_t reg, uint16_t val)
{
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (uint8_t)(val >> 8);   /* OPT3001 expects big-endian */
    buf[2] = (uint8_t)(val & 0xFF);
    if (write(fd, buf, sizeof(buf)) != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "i2c_write_reg16(0x%02X): write failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    uint8_t reg_buf = reg;
    uint8_t data[2];

    if (write(fd, &reg_buf, 1) != 1) {
        fprintf(stderr, "i2c_read_reg16(0x%02X): write reg failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, data, 2) != 2) {
        fprintf(stderr, "i2c_read_reg16(0x%02X): read failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = ((uint16_t)data[0] << 8) | data[1];
    return 0;
}

static int opt3001_init(int fd)
{
    if (i2c_write_reg16(fd, REG_CONFIG, CONFIG_VALUE) != 0) {
        fprintf(stderr, "opt3001_init: failed to write config register\n");
        return -1;
    }
    return 0;
}

static int opt3001_read_lux(int fd, float *lux_out)
{
    uint16_t raw;
    if (i2c_read_reg16(fd, REG_RESULT, &raw) != 0) {
        fprintf(stderr, "opt3001_read_lux: failed to read result register\n");
        return -1;
    }

    /* OPT3001 result: exponent in bits 12-15, mantissa in bits 11-0 */
    uint16_t exponent = (raw >> 12) & 0x0F;
    uint16_t mantissa = raw & 0x0FFF;
    *lux_out = (float)mantissa * (0.01f * (float)(1UL << exponent));
    return 0;
}

static int log_data(FILE *fp, float lux)
{
    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "log_data: time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        fprintf(stderr, "log_data: localtime_r failed\n");
        return -1;
    }
    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &tm_info) == 0) {
        fprintf(stderr, "log_data: strftime failed\n");
        return -1;
    }
    if (fprintf(fp, "%s, %.2f\n", timestamp, lux) < 0) {
        fprintf(stderr, "log_data: fprintf failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "log_data: fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, OPT3001_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                OPT3001_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (opt3001_init(g_i2c_fd) != 0) {
        fprintf(stderr, "OPT3001 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    g_log_fp = fopen("light_data.txt", "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(light_data.txt) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Greenhouse monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float lux;
        if (opt3001_read_lux(g_i2c_fd, &lux) != 0) {
            fprintf(stderr, "Skipping sample due to read error\n");
        } else {
            if (log_data(g_log_fp, lux) != 0) {
                fprintf(stderr, "Skipping sample due to log error\n");
            } else {
                printf("Light: %.2f lux\n", lux);
            }
        }
        sleep(SAMPLE_PERIOD_S);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

