    while (program_running) {
        int sensor_value = gpioRead(FLAME_SENSOR_PIN);

        if (sensor_value < 0) {
            fprintf(stderr, "Error: Failed to read flame sensor (GPIO%d).\n", FLAME_SENSOR_PIN);
