            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (sensor_value == 0) {
            if (gpioWrite(ALERT_PIN, 1) != 0) {
                fprintf(stderr, "Error: Failed to set alert pin HIGH.\n");
                log_event("Error: Failed to trigger alert.");
            } else {
                log_event("Flame detected!");
                gpioDelay(ALERT_DURATION_US);
                if (gpioWrite(ALERT_PIN, 0) != 0) {
                    fprintf(stderr, "Error: Failed to reset alert pin LOW.\n");
                    log_event("Error: Failed to reset alert pin.");
                }
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Warning: Failed to close log file: %s\n", strerror(errno));
        }
        log_file = NULL;
    }

    cleanup_gpio();

    printf("Exiting.\n");
    return 0;
}

