    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO4 as input with pull-down --- */
    ret = gpioSetMode(TOUCH_SENSOR_GPIO, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO%d: %s\n",
                TOUCH_SENSOR_GPIO, pigpio_error(ret));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(TOUCH_SENSOR_GPIO, PI_PUD_DOWN);
    if (ret != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO%d: %s\n",
                TOUCH_SENSOR_GPIO, pigpio_error(ret));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file in append mode --- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Read initial state --- */
    last_state = gpioRead(TOUCH_SENSOR_GPIO);
    if (last_state < 0) {
        fprintf(stderr, "gpioRead failed for GPIO%d: %s\n",
                TOUCH_SENSOR_GPIO, pigpio_error(last_state));
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started on GPIO%d. Press Ctrl+C to exit.\n",
           TOUCH_SENSOR_GPIO);

    /* --- Main polling loop --- */
    while (g_running) {
        current_state = gpioRead(TOUCH_SENSOR_GPIO);
        if (current_state < 0) {
            fprintf(stderr, "gpioRead failed for GPIO%d: %s\n",
                    TOUCH_SENSOR_GPIO, pigpio_error(current_state));
            break;
        }

        if (current_state != last_state) {
            if (log_touch_event(g_log_file, current_state) != 0) {
                fprintf(stderr, "Logging failed; continuing to monitor.\n");
            }
            last_state = current_state;
            gpioDelay(DEBOUNCE_DELAY_US);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Clean shutdown --- */
    printf("\nShutting down...\n");

    if (g_log_file != NULL) {
        if (fclose(g_log_file) != 0) {
            fprintf(stderr, "fclose failed: %s\n", strerror(errno));
        }
        g_log_file = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

