        } else {
            fprintf(stderr, "CRC error; logging and continuing.\n");
            log_data(0.0f, 0, "ERROR");
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    cleanup();
    return EXIT_SUCCESS;
