#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <stdbool.h>
#include <gpiod.h>

#define LEFT_SENSOR_PIN  17
#define MIDDLE_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN  22
#define LOG_FILE_NAME    "path_log.csv"
#define POLL_INTERVAL_MS 50

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static int write_header_if_new(FILE *fp)
{
    long pos = ftell(fp);
    if (pos < 0) {
        perror("ftell");
        return -1;
    }
    if (pos == 0) {
        if (fprintf(fp, "timestamp,left,middle,right\n") < 0) {
            perror("fprintf header");
            return -1;
        }
        if (fflush(fp) != 0) {
            perror("fflush header");
            return -1;
        }
    }
    return 0;
}

static int log_data(FILE *fp, int left, int middle, int right)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        perror("localtime_r");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right) < 0) {
        perror("fprintf data");
        return -1;
    }

    if (fflush(fp) != 0) {
        perror("fflush data");
        return -1;
    }

    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *left_line = NULL;
    struct gpiod_line *middle_line = NULL;
    struct gpiod_line *right_line = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    left_line = gpiod_chip_get_line(chip, LEFT_SENSOR_PIN);
    middle_line = gpiod_chip_get_line(chip, MIDDLE_SENSOR_PIN);
    right_line = gpiod_chip_get_line(chip, RIGHT_SENSOR_PIN);
    if (left_line == NULL || middle_line == NULL || right_line == NULL) {
        perror("gpiod_chip_get_line");
        goto cleanup;
    }

    if (gpiod_line_request_input(left_line, "ky033-left") < 0) {
        perror("gpiod_line_request_input left");
        goto cleanup;
    }
    if (gpiod_line_request_input(middle_line, "ky033-middle") < 0) {
        perror("gpiod_line_request_input middle");
        goto cleanup;
    }
    if (gpiod_line_request_input(right_line, "ky033-right") < 0) {
        perror("gpiod_line_request_input right");
        goto cleanup;
    }

    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        perror("fopen");
        goto cleanup;
    }

    if (write_header_if_new(log_file) != 0) {
        goto cleanup;
    }

    printf("Logging KY-033 sensor data to %s. Press Ctrl+C to stop.\n",
           LOG_FILE_NAME);

    while (program_running) {
        int left_val = gpiod_line_get_value(left_line);
        int middle_val = gpiod_line_get_value(middle_line);
        int right_val = gpiod_line_get_value(right_line);

        if (left_val < 0 || middle_val < 0 || right_val < 0) {
            perror("gpiod_line_get_value");
            break;
        }

        if (log_data(log_file, left_val, middle_val, right_val) != 0) {
            break;
        }

        struct timespec ts;
        ts.tv_sec = POLL_INTERVAL_MS / 1000;
        ts.tv_nsec = (POLL_INTERVAL_MS % 1000) * 1000000L;
        nanosleep(&ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            perror("fclose");
        }
    }
    if (left_line != NULL) {
        gpiod_line_release(left_line);
    }
    if (middle_line != NULL) {
        gpiod_line_release(middle_line);
    }
    if (right_line != NULL) {
        gpiod_line_release(right_line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nExiting cleanly.\n");
    }
    return ret;
}

