/*
 * flame_alert.c — Flame detection safety system for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   Keyes KY-026 flame sensor  (digital output, active-low)
 *     DO  -> GPIO17 (BCM 17, physical pin 11)
 *     VCC -> 3.3 V
 *     GND -> GND
 *   Active buzzer
 *     +   -> GPIO18 (BCM 18, physical pin 12)
 *     -   -> GND
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o flame_alert flame_alert.c -lgpiod
 *
 * Run:
 *   sudo ./flame_alert
 */

#include <errno.h>
#include <signal.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define FLAME_SENSOR_PIN  17   /* BCM 17, physical pin 11 */
#define BUZZER_PIN        18   /* BCM 18, physical pin 12 */
#define LOG_FILE          "alert_log.txt"
#define POLL_INTERVAL_MS  500
#define BUZZER_DURATION_S 2
#define CHIP_NAME         "gpiochip0"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(FILE *log, const char *message)
{
    if (!log) {
        fprintf(stderr, "log_event: log file is NULL\n");
        return;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "log_event: time() failed: %s\n", strerror(errno));
        return;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "log_event: localtime_r() failed\n");
        return;
    }

    fprintf(log, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log);
}

/* ------------------------------------------------------------------ */
/* Buzzer control                                                      */
/* ------------------------------------------------------------------ */
static int buzzer_on(struct gpiod_line *line)
{
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "buzzer_on: gpiod_line_set_value(1) failed: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

static int buzzer_off(struct gpiod_line *line)
{
    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "buzzer_off: gpiod_line_set_value(0) failed: %s\n",
                strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(struct gpiod_chip *chip,
                    struct gpiod_line *flame_line,
                    struct gpiod_line *buzzer_line,
                    FILE *log)
{
    if (buzzer_line) {
        (void)buzzer_off(buzzer_line);
        gpiod_line_release(buzzer_line);
    }
    if (flame_line)
        gpiod_line_release(flame_line);
    if (chip)
        gpiod_chip_close(chip);
    if (log)
        fclose(log);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *flame_line = NULL;
    struct gpiod_line *buzzer_line = NULL;
    FILE *log = NULL;
    int ret = EXIT_FAILURE;

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    log = fopen(LOG_FILE, "a");
    if (!log) {
        fprintf(stderr, "Failed to open log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip ---- */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                CHIP_NAME, strerror(errno));
        goto cleanup;
    }

    /* ---- Get flame sensor line ---- */
    flame_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                FLAME_SENSOR_PIN, strerror(errno));
        goto cleanup;
    }

    /* ---- Get buzzer line ---- */
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                BUZZER_PIN, strerror(errno));
        goto cleanup;
    }

    /* ---- Request flame sensor line as input ---- */
    if (gpiod_line_request_input(flame_line, "flame_sensor") < 0) {
        fprintf(stderr, "gpiod_line_request_input(flame) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- Request buzzer line as output, initial value LOW ---- */
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "gpiod_line_request_output(buzzer) failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* ---- Log system start ---- */
    log_event(log, "System started");

    /* ---- Main polling loop ---- */
    int last_flame_state = 1;   /* assume no flame at startup */

    while (g_running) {
        int val = gpiod_line_get_value(flame_line);
        if (val < 0) {
            fprintf(stderr, "gpiod_line_get_value(flame) failed: %s\n",
                    strerror(errno));
            log_event(log, "Error reading flame sensor");
            break;
        }

        /* HIGH (1) = no flame, LOW (0) = flame detected */
        if (val == 0 && last_flame_state == 1) {
            log_event(log, "FLAME DETECTED");

            if (buzzer_on(buzzer_line) < 0) {
                log_event(log, "Error activating buzzer");
                break;
            }

            /*
             * Buzzer activation broken into 100 ms slices so the
             * 2-second duration is interruptible by signals.
             */
            for (int i = 0; i < (BUZZER_DURATION_S * 10) && g_running; i++)
                usleep(100000);

            if (buzzer_off(buzzer_line) < 0) {
                log_event(log, "Error deactivating buzzer");
                break;
            }
        }

        last_flame_state = val;

        /*
         * Poll interval broken into 100 ms slices for responsive
         * shutdown.
         */
        for (int i = 0; i < (POLL_INTERVAL_MS / 100) && g_running; i++)
            usleep(100000);
    }

    /* ---- Log system stop ---- */
    log_event(log, "System stopped");
    ret = EXIT_SUCCESS;

cleanup:
    cleanup(chip, flame_line, buzzer_line, log);
    return ret;
}

