#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define LED_PIN          17
#define LOG_FILE         "touch_log.txt"
#define POLL_DELAY_US    10000   /* 10 ms  */
#define DEBOUNCE_US      200000  /* 200 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can clean up and exit.      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Append a UTC ISO-8601 timestamp line to the log file.               */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int log_touch_event(void)
{
    time_t rawtime;
    struct tm tm_info;
    char timestamp[32];

    time(&rawtime);
    if (gmtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "gmtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%dT%H:%M:%SZ", &tm_info) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log, "%s\n", timestamp) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int last_state = 0;          /* 0 = not touched, 1 = touched */
    uint32_t last_event_tick = 0;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Configure GPIO pins ---- */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(TOUCH) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(LED) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* TTP223B output is active-HIGH: 1 = touched, 0 = released */
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(TOUCH) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with LED off */
    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(LED, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Open log file ---- */
    g_log = fopen(LOG_FILE, "a");
    if (g_log == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioWrite(LED_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started.\n"
           "  Sensor : GPIO%d (BCM)\n"
           "  LED    : GPIO%d (BCM)\n"
           "  Log    : %s\n"
           "Press Ctrl+C to exit.\n",
           TOUCH_SENSOR_PIN, LED_PIN, LOG_FILE);

    /* ---- Main polling loop ---- */
    while (g_running) {
        int current_state = gpioRead(TOUCH_SENSOR_PIN);
        if (current_state < 0) {
            fprintf(stderr, "gpioRead(TOUCH) failed\n");
            break;
        }

        /* Rising edge: LOW -> HIGH */
        if (current_state == 1 && last_state == 0) {
            uint32_t now = gpioTick();
            if (now - last_event_tick >= DEBOUNCE_US) {
                last_event_tick = now;

                /* Toggle LED */
                int led_val = gpioRead(LED_PIN);
                if (led_val < 0) {
                    fprintf(stderr, "gpioRead(LED) failed\n");
                    break;
                }
                if (gpioWrite(LED_PIN, !led_val) != 0) {
                    fprintf(stderr, "gpioWrite(LED) failed\n");
                    break;
                }

                /* Log event */
                if (log_touch_event() != 0) {
                    fprintf(stderr, "Warning: failed to log touch event\n");
                }
            }
        }

        last_state = current_state;
        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Cleanup ---- */
    printf("\nShutting down...\n");

    gpioWrite(LED_PIN, 0);   /* ensure LED is off */

    if (g_log != NULL) {
        if (fclose(g_log) != 0) {
            fprintf(stderr, "fclose(log) failed: %s\n", strerror(errno));
        }
        g_log = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

