            return EXIT_FAILURE;
        }
    }

    /* ---- Open log file ---- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        perror("fopen(" LOG_FILE_NAME ")");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring TMAG5110A1 sensors on GPIO4, 17, 27. Press Ctrl+C to exit.\n");

    /* ---- Initialise previous states ---- */
    int prev[3] = {0, 0, 0};
    int first_read[3] = {1, 1, 1};

    /* ---- Main polling loop ---- */
    while (g_running) {
        for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
            int v = read_sensor(pins[i]);
            if (v < 0) {
                continue;  /* error already reported; skip this sample */
            }

            if (first_read[i]) {
                /* Record baseline without logging a false transition */
                prev[i] = v;
                first_read[i] = 0;
            } else if (v != prev[i]) {
                log_event((int)(i + 1), v);
                prev[i] = v;
            }
        }
        gpioDelay(POLL_DELAY_US);
    }

    /* ---- Clean shutdown ---- */
    printf("\nShutting down...\n");
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

