/* Expected PART_ID and HW_REV for Si1182-A-GM */
#define SI1182_PART_ID_EXPECTED 0x82
#define SI1182_HW_REV_EXPECTED  0x01

/* Moving average filter window size */
#define WINDOW_SIZE 5

/* Global variables for cleanup */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Structure to hold heart rate data and moving average state */
typedef struct {
    int data[WINDOW_SIZE];
    int index;
    int count;
    int sum;
} HeartRateFilter;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a single byte to a register */
static int write_register(int handle, uint8_t reg, uint8_t value) {
    int result = i2cWriteByteData(handle, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

/* Read a single byte from a register */
static int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cReadByteData(handle, reg);
    if (result < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, result);
        return -1;
    }
    *value = (uint8_t)result;
    return 0;
}

/* Initialize the Si1182 sensor */
static int initialize_sensor(int handle) {
    uint8_t part_id, hw_rev;

    /* Verify sensor presence by reading PART_ID */
    if (read_register(handle, REG_PART_ID, &part_id) < 0) {
        fprintf(stderr, "Sensor not responding on I2C bus (no ACK at PART_ID).\n");
        return -1;
    }

    if (part_id != SI1182_PART_ID_EXPECTED) {
        fprintf(stderr, "Unexpected PART_ID: 0x%02X (expected 0x%02X). Sensor absent or wrong part.\n",
                part_id, SI1182_PART_ID_EXPECTED);
        return -1;
    }

    /* Verify HW_REV */
    if (read_register(handle, REG_HW_REV, &hw_rev) < 0) {
        fprintf(stderr, "Failed to read HW_REV.\n");
        return -1;
    }

    if (hw_rev != SI1182_HW_REV_EXPECTED) {
        fprintf(stderr, "Unexpected HW_REV: 0x%02X (expected 0x%02X).\n",
                hw_rev, SI1182_HW_REV_EXPECTED);
        return -1;
    }

    printf("Si1182-A-GM detected (PART_ID=0x%02X, HW_REV=0x%02X).\n", part_id, hw_rev);

    /* Configure measurement rate (e.g., 100ms interval) */
    if (write_register(handle, REG_MEAS_RATE0, 0x00) < 0) return -1;
    if (write_register(handle, REG_MEAS_RATE1, 0x64) < 0) return -1; /* 100ms */

    /* Configure LED current for PS1 */
    if (write_register(handle, REG_PS_LED21, 0x0F) < 0) return -1;

    /* Configure ADC gain and misc for PS1 */
    if (write_register(handle, REG_PS_ADC_GAIN, 0x00) < 0) return -1;
    if (write_register(handle, REG_PS_ADC_MISC, 0x00) < 0) return -1;

    /* Enable PS1 ADC */
    if (write_register(handle, REG_PS1_ADCMUX, 0x01) < 0) return -1;

    /* Enable HR data interrupt */
    if (write_register(handle, REG_INT_CFG, 0x01) < 0) return -1;
    if (write_register(handle, REG_IRQ_ENABLE, 0x01) < 0) return -1;

    return 0;
}

/* Read heart rate data from the sensor */
static int read_heart_rate(int handle, int *heart_rate) {
    uint8_t data[2];

    /* Read 2 bytes from HR_DATA0 (0x26) */
    int result = i2cReadI2CBlockData(handle, REG_HR_DATA0, (char *)data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading heart rate data: %d\n", result);
        return -1;
    }

    /* Combine the two bytes into a 16-bit value (little-endian) */
    *heart_rate = (data[1] << 8) | data[0];
    return 0;
}

/* Apply a moving average filter to the heart rate data */
static int apply_moving_average(HeartRateFilter *filter, int new_value) {
    filter->sum -= filter->data[filter->index];
    filter->data[filter->index] = new_value;
    filter->sum += new_value;
    filter->index = (filter->index + 1) % WINDOW_SIZE;
    if (filter->count < WINDOW_SIZE) {
        filter->count++;
    }
    return filter->sum / filter->count;
}

/* Log heart rate data to a file */
static int log_heart_rate(FILE *fp, int heart_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error getting local time.\n");
        return -1;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(fp, "%s,%d\n", timestamp, heart_rate) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }
    fflush(fp);
    return 0;
}

int main(void) {
    HeartRateFilter heart_rate_filter = {{0}, 0, 0, 0};
    int heart_rate;
    int filtered_heart_rate;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 */
    i2c_handle = i2cOpen(1, SI1182_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the sensor */
    if (initialize_sensor(i2c_handle) < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open the log file */
    log_file = fopen("heart_rate.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Warning: could not register SIGINT handler.\n");
    }

    printf("Heart rate monitoring started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        /* Read heart rate data */
        if (read_heart_rate(i2c_handle, &heart_rate) == 0) {
            /* Validate heart rate range (30-220 BPM) */
            if (heart_rate >= 30 && heart_rate <= 220) {
                /* Apply moving average filter */
                filtered_heart_rate = apply_moving_average(&heart_rate_filter, heart_rate);

                /* Log heart rate data */
                if (log_heart_rate(log_file, filtered_heart_rate) == 0) {
                    printf("Heart Rate: %d BPM\n", filtered_heart_rate);
                } else {
                    fprintf(stderr, "Error logging heart rate data.\n");
                }
            } else {
                fprintf(stderr, "Invalid heart rate reading: %d BPM (out of range 30-220)\n", heart_rate);
            }
        } else {
            fprintf(stderr, "Error reading heart rate data. Retrying in 1 second.\n");
        }

        /* Wait for 1 second */
        gpioSleep(PI_TIME_RELATIVE, 1, 0);
    }

    /* Cleanup */
    printf("\nCleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return EXIT_SUCCESS;
}

