 *
 * Board:  Raspberry Pi Zero W
 * Library: libgpiod (modern Linux GPIO character-device API)
 *
 * Wiring
 *   TTP226 OUT1..OUT8 → BCM 5, 6, 7, 8, 9, 10, 11, 12
 *   Counter bit 0     → BCM 17
 *   Counter bit 7     → BCM 24
 *
 * Build:  gcc -O2 -Wall -Wextra -o touch_counter touch_counter.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define NUM_CHANNELS 8
#define LOG_FILE     "touch_log.txt"
#define POLL_MS      10
#define STABILIZE_MS 200

static const unsigned int sensor_pins[NUM_CHANNELS] = {5, 6, 7, 8, 9, 10, 11, 12};
static const unsigned int counter_pins[NUM_CHANNELS] = {17, 18, 19, 20, 21, 22, 23, 24};

static volatile sig_atomic_t g_running = 1;

static void sighandler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void install_signals(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1)
        perror("sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) == -1)
        perror("sigaction(SIGTERM)");
}

static void timestamp_utc(char *buf, size_t len)
{
    time_t t = time(NULL);
    struct tm tmu;
    if (gmtime_r(&t, &tmu) == NULL) {
        snprintf(buf, len, "1970-01-01T00:00:00Z");
        return;
    }
    strftime(buf, len, "%Y-%m-%dT%H:%M:%SZ", &tmu);
}

static int log_touch_event(int channel, int counter)
{
    char ts[32];
    timestamp_utc(ts, sizeof(ts));

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "fopen(%s): %s\n", LOG_FILE, strerror(errno));
        return -1;
    }
    if (fprintf(fp, "%s, Channel: %d, Counter: %d\n", ts, channel, counter) < 0) {
        fprintf(stderr, "fprintf(log): %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }
    if (fclose(fp) != 0) {
        fprintf(stderr, "fclose(log): %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

int main(void)
{
    install_signals();

    struct gpiod_chip *chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    struct gpiod_line *sensor_lines[NUM_CHANNELS];
    struct gpiod_line *counter_lines[NUM_CHANNELS];
    int acquired = 0;

    for (int i = 0; i < NUM_CHANNELS; i++) {
        sensor_lines[i] = gpiod_chip_get_line(chip, sensor_pins[i]);
        if (!sensor_lines[i]) {
            fprintf(stderr, "get sensor line %u: %s\n", sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        counter_lines[i] = gpiod_chip_get_line(chip, counter_pins[i]);
        if (!counter_lines[i]) {
            fprintf(stderr, "get counter line %u: %s\n", counter_pins[i], strerror(errno));
            goto cleanup;
        }
        acquired++;
    }

    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpiod_line_request_input(sensor_lines[i], "ttp226_sensor") < 0) {
            fprintf(stderr, "request_input sensor %u: %s\n", sensor_pins[i], strerror(errno));
            goto cleanup;
        }
        if (gpiod_line_request_output(counter_lines[i], "ttp226_counter", 0) < 0) {
            fprintf(stderr, "request_output counter %u: %s\n", counter_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    usleep(STABILIZE_MS * 1000);

    int counter = 0;
    int prev[NUM_CHANNELS] = {0};

    while (g_running) {
        for (int i = 0; i < NUM_CHANNELS; i++) {
            int v = gpiod_line_get_value(sensor_lines[i]);
            if (v < 0) {
                fprintf(stderr, "read sensor %u: %s\n", sensor_pins[i], strerror(errno));
                continue;
            }
            if (v == 1 && prev[i] == 0) {
                counter = (counter + 1) & 0xFF;
                int vals[NUM_CHANNELS];
                for (int b = 0; b < NUM_CHANNELS; b++)
                    vals[b] = (counter >> b) & 1;
                for (int b = 0; b < NUM_CHANNELS; b++) {
                    if (gpiod_line_set_value(counter_lines[b], vals[b]) < 0)
                        fprintf(stderr, "write counter %u: %s\n", counter_pins[b], strerror(errno));
                }
                if (log_touch_event(i + 1, counter) < 0)
                    fprintf(stderr, "log_touch_event failed for channel %d\n", i + 1);
                printf("Touch on channel %d | Counter: %d\n", i + 1, counter);
            }
            prev[i] = v;
        }
        usleep(POLL_MS * 1000);
    }

    for (int i = 0; i < NUM_CHANNELS; i++)
        gpiod_line_set_value(counter_lines[i], 0);

cleanup:
    for (int i = 0; i < acquired; i++) {
        if (sensor_lines[i])  gpiod_line_release(sensor_lines[i]);
        if (counter_lines[i]) gpiod_line_release(counter_lines[i]);
    }
    gpiod_chip_close(chip);
    return EXIT_SUCCESS;
}

