#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 18
#define SENSOR3_PIN 27
#define SENSOR4_PIN 22
#define LOG_FILE "tracking_log.csv"
#define POLL_DELAY_US 100000  /* 100 ms */

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    int pins[] = {SENSOR1_PIN, SENSOR2_PIN, SENSOR3_PIN, SENSOR4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); ++i) {
        if (gpioSetMode(pins[i], PI_INPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as input.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        /* Enable internal pull-up so the sensor line reads HIGH when idle */
        if (gpioSetPullUpDown(pins[i], PI_PUD_UP) != 0) {
            fprintf(stderr, "Warning: failed to set pull-up on GPIO %d.\n", pins[i]);
        }
    }
    return 0;
}

static int read_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "Error: failed to read GPIO %d (pigpio error %d).\n", pin, value);
        return -1;
    }
    return value;
}

static int log_data(FILE *fp, int s1, int s2, int s3, int s4) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed.\n");
        return -1;
    }
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed.\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, s1, s2, s3, s4) < 0) {
        fprintf(stderr, "Error: failed to write to log file.\n");
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header if file is empty */
    if (fseek(fp, 0, SEEK_END) == 0) {
        long file_size = ftell(fp);
        if (file_size == 0) {
            fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
            fflush(fp);
        }
    } else {
        fprintf(stderr, "Warning: fseek failed on %s: %s\n", LOG_FILE, strerror(errno));
    }

    printf("Logging KY-033 sensor data to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);
        int s3 = read_sensor(SENSOR3_PIN);
        int s4 = read_sensor(SENSOR4_PIN);

        if (s1 >= 0 && s2 >= 0 && s3 >= 0 && s4 >= 0) {
            if (log_data(fp, s1, s2, s3, s4) != 0) {
                fprintf(stderr, "Error: logging failed, continuing.\n");
            }
        } else {
            fprintf(stderr, "Error: sensor read failure, skipping log entry.\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down gracefully...\n");
    if (fclose(fp) != 0) {
        fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

