}

static int init_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(SENSOR1_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR1_PIN);
        return -1;
    }
    if (gpioSetMode(SENSOR2_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SENSOR2_PIN);
        return -1;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        return -1;
    }

    /* Ensure LED is off at startup */
    if (gpioWrite(LED_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialise LED state on GPIO%d\n", LED_PIN);
        return -1;
    }

    return 0;
}

static int read_sensor(int pin)
{
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "gpioRead failed on GPIO%d\n", pin);
        return -1;
    }
    return v;
}

static int control_led(int state)
{
    if (gpioWrite(LED_PIN, state) < 0) {
        fprintf(stderr, "gpioWrite failed on GPIO%d\n", LED_PIN);
        return -1;
    }
    return 0;
}

static int log_data(int s1, int s2, int led)
{
    time_t rawtime;
    struct tm timeinfo;
    char ts[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(log_fp, "%s,%d,%d,%d\n", ts, s1, s2, led) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Best-effort LED off */
    (void)gpioWrite(LED_PIN, 0);
    gpioTerminate();
    if (log_fp != NULL) {
        fclose(log_fp);
        log_fp = NULL;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (log_fp == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    if (ftell(log_fp) == 0) {
        fprintf(log_fp, "timestamp,sensor1,sensor2,led_state\n");
        fflush(log_fp);
    }

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    while (running) {
        int s1 = read_sensor(SENSOR1_PIN);
        int s2 = read_sensor(SENSOR2_PIN);

        if (s1 < 0 || s2 < 0) {
            fprintf(stderr, "Sensor read error; continuing.\n");
            gpioDelay(POLL_US);
            continue;
        }

        /* TCRT5000 is active-low: 0 => obstacle detected */
        int led_state = (s1 == 0 && s2 == 0) ? 1 : 0;

        if (control_led(led_state) != 0) {
            fprintf(stderr, "LED control error; continuing.\n");
        }

        if (log_data(s1, s2, led_state) != 0) {
            fprintf(stderr, "Logging error; continuing.\n");
        }

        gpioDelay(POLL_US);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

