#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define MICROPHONE_PIN 4
#define LED_PIN 17
#define SAMPLE_PERIOD_US 125
#define LED_ON_DURATION_US 100000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static void print_timestamp_ms(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return;
    }
    long ms = (ts.tv_sec * 1000L) + (ts.tv_nsec / 1000000L);
    printf("%ld\n", ms);
    fflush(stdout);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MICROPHONE_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set microphone pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(LED_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise LED state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sampling started. Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (program_running) {
        int level = gpioRead(MICROPHONE_PIN);
        if (level < 0) {
            fprintf(stderr, "gpioRead failed on microphone pin\n");
            break;
        }

        if (level == 1) {
            print_timestamp_ms();

            if (gpioWrite(LED_PIN, 1) != 0) {
                fprintf(stderr, "Failed to turn LED on\n");
                break;
            }

            gpioDelay(LED_ON_DURATION_US);

            if (gpioWrite(LED_PIN, 0) != 0) {
                fprintf(stderr, "Failed to turn LED off\n");
                break;
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    gpioWrite(LED_PIN, 0);
    gpioTerminate();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

