#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN  17
#define CENTER_SENSOR_PIN 27
#define RIGHT_SENSOR_PIN  22

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    int left_state, center_state, right_state;
    int ret;

    /* Register signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to register SIGTERM handler");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure sensor pins as inputs with pull-up resistors */
    ret = gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input (ret=%d).\n", LEFT_SENSOR_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    ret = gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to set pull-up on GPIO%d (ret=%d).\n", LEFT_SENSOR_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "Error: Failed to set GPIO%d as input (ret=%d).\n", CENTER_SENSOR_PIN, ret);
        gpioTerminate();
        return EXIT_FAILURE;
