/*
 * Si1175 ALS (Ambient Light Sensor) Reader for Raspberry Pi 4 Model B
 *
 * Reads the 16-bit raw ALS data from the Si1175 sensor on I2C bus 1
 * at 100 ms intervals and logs the value to the console.
 *
 * Wiring:
 *   Si1175 SDA -> GPIO 2 (I2C1 SDA)
 *   Si1175 SCL -> GPIO 3 (I2C1 SCL)
 *   Si1175 VDD -> 3.3 V
 *   Si1175 GND -> GND
 *
 * Build: gcc -Wall -Wextra -O2 -o si1175_als si1175_als.c -lpigpio -lrt
 * Run:   sudo ./si1175_als
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* Si1175 I2C address (7-bit) */
#define SI1175_ADDR 0x60

/* Si1175 register addresses */
#define SI1175_REG_ALS_LSB 0x22
#define SI1175_REG_ALS_MSB 0x23

/* I2C bus on Raspberry Pi 4 Model B */
#define I2C_BUS 1

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* Global flag for graceful shutdown */
static volatile sig_atomic_t g_running = 1;

/* Signal handler for Ctrl+C */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read a single byte from a Si1175 register.
 * Returns the byte value (0-255) on success, or -1 on error.
 */
static int read_register(int handle, uint8_t reg)
{
    int value = i2cReadByteData(handle, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, value);
        return -1;
    }
    return value;
}

/*
 * Read the 16-bit ALS data from the Si1175.
 * Returns the raw 16-bit value on success, or -1 on error.
 */
static int read_als_data(int handle)
{
    int lsb = read_register(handle, SI1175_REG_ALS_LSB);
    if (lsb < 0) {
        return -1;
    }

    int msb = read_register(handle, SI1175_REG_ALS_MSB);
    if (msb < 0) {
        return -1;
    }

    return (msb << 8) | lsb;
}

int main(void)
{
    int handle = -1;
    int exit_code = EXIT_FAILURE;

    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C connection to Si1175 */
    handle = i2cOpen(I2C_BUS, SI1175_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at bus %d, address 0x%02X: %d\n",
                I2C_BUS, SI1175_ADDR, handle);
        goto cleanup_gpio;
    }

    /* Main loop to read and log ALS data */
    while (g_running) {
        int als_data = read_als_data(handle);

        if (als_data < 0) {
            fprintf(stderr, "Error reading ALS data. Retrying...\n");
        } else {
            printf("ALS Raw Data: %d\n", als_data);
            fflush(stdout);
        }

        /* Delay for 100 ms */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    exit_code = EXIT_SUCCESS;

    /* Clean up resources on normal exit */
    i2cClose(handle);

cleanup_gpio:
    gpioTerminate();
    return exit_code;
}

