#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/gpio.h>

#define LEFT_SENSOR   2   /* BCM GPIO2 */
#define MIDDLE_SENSOR 3   /* BCM GPIO3 */
#define RIGHT_SENSOR  4   /* BCM GPIO4 */
#define POLL_INTERVAL_US 100000  /* 100 ms */
#define GPIO_CHIP_NAME   "gpiochip0"

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

/*
 * Read the digital value of a single GPIO line.
 * Returns 0 or 1 on success, -1 on error.
 */
static int read_gpio_line(int fd, unsigned int offset)
{
    struct gpiohandle_request req;
    struct gpiohandle_data data;
    int ret;

    memset(&req, 0, sizeof(req));
    memset(&data, 0, sizeof(data));

    req.lineoffsets[0] = offset;
    req.flags = GPIOHANDLE_REQUEST_INPUT;
    req.lines = 1;

    ret = ioctl(fd, GPIO_GET_LINEHANDLE_IOCTL, &req);
    if (ret < 0) {
        fprintf(stderr, "Error getting line handle for GPIO %u: %s\n",
                offset, strerror(errno));
        return -1;
    }

    data.values[0] = 0;
    ret = ioctl(req.fd, GPIOHANDLE_GET_LINE_VALUES_IOCTL, &data);
    if (ret < 0) {
        fprintf(stderr, "Error reading GPIO %u: %s\n",
                offset, strerror(errno));
        close(req.fd);
        return -1;
    }

    close(req.fd);
    return (int)data.values[0];
}

int main(void)
{
    int left_value, middle_value, right_value;
    int ret;
    int gpio_fd = -1;

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Error installing SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip device */
    gpio_fd = open(GPIO_CHIP_NAME, O_RDWR);
    if (gpio_fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Main polling loop */
    while (program_running) {
        left_value = read_gpio_line(gpio_fd, LEFT_SENSOR);
        middle_value = read_gpio_line(gpio_fd, MIDDLE_SENSOR);
        right_value = read_gpio_line(gpio_fd, RIGHT_SENSOR);

        if (left_value < 0 || middle_value < 0 || right_value < 0) {
            fprintf(stderr, "Error reading sensor values. Exiting.\n");
            break;
        }

        printf("L:%d M:%d R:%d\n", left_value, middle_value, right_value);
        fflush(stdout);

        usleep(POLL_INTERVAL_US);
    }

    /* Clean up */
    if (gpio_fd >= 0) {
        close(gpio_fd);
    }

    return EXIT_SUCCESS;
}

