 *   TP8 -> GPIO20 (BCM)
 *   VCC -> 3.3 V
 *   GND -> GND
 *
 * Compile:
 *   gcc -o touch_poll touch_poll.c -lrt
 *
 * Run:
 *   ./touch_poll
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>

#include <gpiod.h>

#define NUM_CHANNELS 8
#define POLL_INTERVAL_MS 200

static const unsigned int gpio_pins[NUM_CHANNELS] = {
    5,  6,  13, 19, 26, 12, 16, 20
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_CHANNELS];
    int values[NUM_CHANNELS];
    int ret;
    int exit_code = EXIT_SUCCESS;

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire each GPIO line as input */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        lines[i] = gpiod_chip_get_line(chip, gpio_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    gpio_pins[i], strerror(errno));
            exit_code = EXIT_FAILURE;
            goto cleanup;
        }

        ret = gpiod_line_request_input(lines[i], "ttp226-touch");
        if (ret < 0) {
            fprintf(stderr, "Failed to request GPIO line %u as input: %s\n",
                    gpio_pins[i], strerror(errno));
            exit_code = EXIT_FAILURE;
            goto cleanup;
        }
    }

    /* Main polling loop */
    while (program_running) {
        struct timespec ts;
        if (clock_gettime(CLOCK_MONOTONIC, &ts) == -1) {
            fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
            exit_code = EXIT_FAILURE;
            break;
        }

        printf("[%.3f] ", (double)ts.tv_sec + (double)ts.tv_nsec / 1e9);

        for (int i = 0; i < NUM_CHANNELS; i++) {
            int val = gpiod_line_get_value(lines[i]);
            if (val < 0) {
                fprintf(stderr, "Failed to read GPIO line %u: %s\n",
                        gpio_pins[i], strerror(errno));
                exit_code = EXIT_FAILURE;
                goto cleanup;
            }
            values[i] = val;
        }

        printf("CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
               values[0], values[1], values[2], values[3],
               values[4], values[5], values[6], values[7]);
        fflush(stdout);

        usleep(POLL_INTERVAL_MS * 1000);
    }

cleanup:
    /* Release each line and close the chip */
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (lines[i] != NULL) {
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }

    return exit_code;
}

