#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <fcntl.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define PWM_FREQ  1000
#define PWM_RANGE 255
#define FADE_STEPS 50
#define FADE_DELAY_US 100000  /* 5 s / 50 steps */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Read 5 bytes from /dev/urandom and use them to seed rand(). */
static void seed_rand_from_urandom(void)
{
    int fd = open("/dev/urandom", O_RDONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "open(/dev/urandom): %s", strerror(errno));
        return;
    }

    unsigned char seed[5];
    ssize_t n = read(fd, seed, sizeof(seed));
    if (n != (ssize_t)sizeof(seed)) {
        syslog(LOG_ERR, "read(/dev/urandom): %s",
               n < 0 ? strerror(errno) : "short read");
    } else {
        srand((unsigned int)seed[0] |
              ((unsigned int)seed[1] << 8) |
              ((unsigned int)seed[2] << 16) |
              ((unsigned int)seed[3] << 24));
    }

    if (close(fd) < 0) {
        syslog(LOG_WARNING, "close(/dev/urandom): %s", strerror(errno));
    }
}

/* Map a 0..1 float to a 0..255 int, clamping. */
static int float_to_int_clamped(float v)
{
    if (v < 0.0f)   return 0;
    if (v > 1.0f)   return 255;
    return (int)(v * 255.0f + 0.5f);
}

/* Convert HSV (h in [0,360), s/v in [0,1]) to RGB (each 0..255). */
static void hsv_to_rgb(float h, float s, float v,
                       int *r, int *g, int *b)
{
    if (s <= 0.0f) {
        int gray = float_to_int_clamped(v);
        *r = *g = *b = gray;
        return;
    }

    h = fmodf(h, 360.0f);
    if (h < 0.0f) h += 360.0f;

    float hh = h / 60.0f;
    int   i  = (int)hh;
    float ff = hh - (float)i;
    float p  = v * (1.0f - s);
    float q  = v * (1.0f - s * ff);
    float t  = v * (1.0f - s * (1.0f - ff));

    float rf, gf, bf;
    switch (i) {
        case 0: rf = v; gf = t; bf = p; break;
        case 1: rf = q; gf = v; bf = p; break;
        case 2: rf = p; gf = v; bf = t; break;
        case 3: rf = p; gf = q; bf = v; break;
        case 4: rf = t; gf = p; bf = v; break;
        default: rf = v; gf = p; bf = q; break;
    }

    *r = float_to_int_clamped(rf);
    *g = float_to_int_clamped(gf);
    *b = float_to_int_clamped(bf);
}

static int set_led_color(int r, int g, int b)
{
    /* Common-anode: invert the duty cycle so 0 = full brightness,
       255 = off. */
    int rc = gpioPWM(RED_PIN,   PWM_RANGE - r);
    int gc = gpioPWM(GREEN_PIN, PWM_RANGE - g);
    int bc = gpioPWM(BLUE_PIN,  PWM_RANGE - b);

    if (rc < 0) syslog(LOG_ERR, "gpioPWM(red): %s", pigpio_error(rc));
    if (gc < 0) syslog(LOG_ERR, "gpioPWM(green): %s", pigpio_error(gc));
    if (bc < 0) syslog(LOG_ERR, "gpioPWM(blue): %s", pigpio_error(bc));

    return (rc < 0 || gc < 0 || bc < 0) ? -1 : 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "gpioInitialise() failed");
        return -1;
    }

    int rc = gpioSetMode(RED_PIN,   PI_OUTPUT);
    int gc = gpioSetMode(GREEN_PIN, PI_OUTPUT);
    int bc = gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    if (rc < 0) syslog(LOG_ERR, "gpioSetMode(red): %s", pigpio_error(rc));
    if (gc < 0) syslog(LOG_ERR, "gpioSetMode(green): %s", pigpio_error(gc));
    if (bc < 0) syslog(LOG_ERR, "gpioSetMode(blue): %s", pigpio_error(bc));

    rc = gpioSetPWMfrequency(RED_PIN,   PWM_FREQ);
    gc = gpioSetPWMfrequency(GREEN_PIN, PWM_FREQ);
    bc = gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQ);

    if (rc < 0) syslog(LOG_ERR, "gpioSetPWMfrequency(red): %s", pigpio_error(rc));
    if (gc < 0) syslog(LOG_ERR, "gpioSetPWMfrequency(green): %s", pigpio_error(gc));
    if (bc < 0) syslog(LOG_ERR, "gpioSetPWMfrequency(blue): %s", pigpio_error(bc));

    rc = gpioSetPWMrange(RED_PIN,   PWM_RANGE);
    gc = gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    bc = gpioSetPWMrange(BLUE_PIN,  PWM_RANGE);

    if (rc < 0) syslog(LOG_ERR, "gpioSetPWMrange(red): %s", pigpio_error(rc));
    if (gc < 0) syslog(LOG_ERR, "gpioSetPWMrange(green): %s", pigpio_error(gc));
    if (bc < 0) syslog(LOG_ERR, "gpioSetPWMrange(blue): %s", pigpio_error(bc));

    /* Start with the LED off. */
    if (set_led_color(0, 0, 0) < 0) {
        syslog(LOG_ERR, "Failed to initialize LED to off state");
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void)
{
    /* Turn off the LED first for safety. */
    (void)gpioPWM(RED_PIN,   PWM_RANGE);
    (void)gpioPWM(GREEN_PIN, PWM_RANGE);
    (void)gpioPWM(BLUE_PIN,  PWM_RANGE);

    gpioTerminate();
}

int main(void)
{
    openlog("rgb_fade", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGINT): %s", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM): %s", strerror(errno));
    }

    if (initialize_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed; aborting");
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "RGB fade started (PWM %d Hz, range %d)", PWM_FREQ, PWM_RANGE);

    seed_rand_from_urandom();

    float h1 = (float)(rand() % 360);
    float s1 = (float)(rand() % 100) / 100.0f;
    float v1 = (float)(rand() % 100) / 100.0f;

    while (g_running) {
        float h2 = (float)(rand() % 360);
        float s2 = (float)(rand() % 100) / 100.0f;
        float v2 = (float)(rand() % 100) / 100.0f;

        syslog(LOG_INFO, "Fading from HSV(%.1f,%.2f,%.2f) to HSV(%.1f,%.2f,%.2f)",
               h1, s1, v1, h2, s2, v2);

        for (int step = 0; step <= FADE_STEPS && g_running; step++) {
            float t = (float)step / (float)FADE_STEPS;

            float h = h1 + t * (h2 - h1);
            float s = s1 + t * (s2 - s1);
            float v = v1 + t * (v2 - v1);

            int r, g, b;
            hsv_to_rgb(h, s, v, &r, &g, &b);

            if (set_led_color(r, g, b) < 0) {
                syslog(LOG_ERR, "PWM write failed during fade");
            }

            usleep(FADE_DELAY_US);
        }

        if (!g_running) break;

        h1 = h2;
        s1 = s2;
        v1 = v2;
    }

    syslog(LOG_INFO, "Shutting down");
    cleanup_gpio();
    closelog();
    return EXIT_SUCCESS;
}

