#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define TCS34725_ADDR  0x29
#define LED_PIN        17

#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_ID      0x12
#define TCS34725_CDATA   0x14
#define TCS34725_RDATA   0x16
#define TCS34725_GDATA   0x18
#define TCS34725_BDATA   0x1A

#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02

#define RED_THRESHOLD   200
#define POLL_DELAY_US   200000
#define ATIME_VALUE     0xFF

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = { reg, value };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, uint8_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int tcs34725_init(int fd) {
    uint8_t id = 0;
    if (i2c_read_block(fd, TCS34725_ID, &id, 1) != 0) {
        return -1;
    }
    if (id != 0x44) {
        fprintf(stderr, "TCS34725 not detected (ID=0x%02X, expected 0x44)\n", id);
        return -1;
    }

    if (i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON) != 0) return -1;
    gpioDelay(3000);

    if (i2c_write_byte(fd, TCS34725_ATIME, ATIME_VALUE) != 0) return -1;
    if (i2c_write_byte(fd, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) != 0) return -1;

    return 0;
}

static int tcs34725_read_calibrated(int fd, uint16_t *r, uint16_t *g, uint16_t *b, uint16_t *c) {
    uint8_t buf[8];
    if (i2c_read_block(fd, TCS34725_CDATA, buf, 8) != 0) return -1;

    *c = (uint16_t)((buf[1] << 8) | buf[0]);
    *r = (uint16_t)((buf[3] << 8) | buf[2]);
