/*
 * Raspberry Pi 4 Model B – BH1750 ambient light sensor → WS2812B LED strip
 *
 * Hardware:
 *   - BH1750FVI on I2C bus 1, address 0x23 (ADDR pin low)
 *   - WS2812B data line on GPIO18 (PCM_CLK), BCM pin 18
 *
 * Build:
 *   gcc -O2 -Wall -o light_led light_led.c -lpigpio -lrt
 *   (pigpio must be running; start with: sudo pigpiod)
 *
 * The program reads lux from the BH1750, maps it to a logarithmic
 * brightness level, and drives the WS2812B using the pigpio wave
 * API to produce the precise 400–800 kHz WS2812B protocol.
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define BH1750_ADDR        0x23
#define BH1750_PWR_ON      0x01
#define BH1750_RESET       0x07
#define BH1750_CONT_HRES   0x10  /* 1 lux resolution, ~120 ms typ */

#define WS2812_GPIO        18
#define NUM_LEDS           10
#define PWM_FREQ           800000  /* 800 kHz – WS2812B threshold */
#define PWM_DUTY_0         0
#define PWM_DUTY_1         1

#define I2C_BUS            1
#define SAMPLE_PERIOD_US   200000  /* 200 ms between readings */
#define BH1750_WAIT_US     180000  /* 180 ms conversion wait */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* BH1750 helpers                                                      */
/* ------------------------------------------------------------------ */
static int bh1750_write_cmd(uint8_t cmd)
{
    if (i2cWriteByte(g_i2c_handle, cmd) < 0) {
        fprintf(stderr, "[BH1750] write(0x%02X) failed\n", cmd);
        return -1;
    }
    return 0;
}

static int bh1750_init(void)
{
    g_i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[BH1750] i2cOpen failed (handle=%d)\n", g_i2c_handle);
        return -1;
    }

    if (bh1750_write_cmd(BH1750_RESET) < 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    gpioDelay(15000);  /* 15 ms reset settling */

    if (bh1750_write_cmd(BH1750_PWR_ON) < 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    gpioDelay(10000);  /* 10 ms power-on settling */

    if (bh1750_write_cmd(BH1750_CONT_HRES) < 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
        return -1;
    }
    gpioDelay(BH1750_WAIT_US);  /* first conversion */

    return 0;
}

static int bh1750_read_lux(float *lux_out)
{
    char buf[2];
    int n = i2cReadDevice(g_i2c_handle, buf, 2);
    if (n != 2) {
        fprintf(stderr, "[BH1750] read failed (got %d bytes)\n", n);
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* WS2812B helpers                                                     */
/* ------------------------------------------------------------------ */
/*
 * pigpio wave API: each wave_pulse_t is a tuple (gpio, duration, level).
 * WS2812B bit timing: T0H ≈500 ns, T0L ≈600 ns, T1H ≈600 ns, T1L ≈500 ns.
 * At 800 kHz the period is 1.25 µs; we round to 1 µs for safety.
 */
static void ws2812_build_wave(uint8_t *leds, int num_leds, int *wave_id_out)
{
    int total_pulses = num_leds * 24 * 2;  /* 2 pulses per bit */
    gpioPulse_t *pulses = malloc((size_t)total_pulses * sizeof(gpioPulse_t));
    if (!pulses) {
        fprintf(stderr, "[WS2812] malloc failed\n");
        *wave_id_out = -1;
        return;
    }

    int idx = 0;
    for (int i = 0; i < num_leds; i++) {
        uint32_t grb = ((uint32_t)leds[i * 3] << 16) |
                       ((uint32_t)leds[i * 3 + 1] << 8) |
                       (uint32_t)leds[i * 3 + 2];

        for (int bit = 23; bit >= 0; bit--) {
            int one = (grb >> bit) & 1;
            pulses[idx].gpioOn  = (1u << WS2812_GPIO);
            pulses[idx].gpioOff = 0;
            pulses[idx].usDelay = one ? 1 : 1;  /* ~600 ns */
            idx++;

            pulses[idx].gpioOn  = 0;
            pulses[idx].gpioOff = (1u << WS2812_GPIO);
            pulses[idx].usDelay = one ? 1 : 1;  /* ~500 ns */
            idx++;
        }
    }

    /* Latch / reset: hold line low for >50 µs */
    pulses[idx].gpioOn  = 0;
    pulses[idx].gpioOff = (1u << WS2812_GPIO);
    pulses[idx].usDelay = 60;
    idx++;

    int w_id = gpioWaveAddNew();
    if (w_id < 0) {
        fprintf(stderr, "[WS2812] gpioWaveAddNew failed (%d)\n", w_id);
        free(pulses);
        *wave_id_out = -1;
        return;
    }

    if (gpioWaveAddGeneric(idx, pulses) < 0) {
        fprintf(stderr, "[WS2812] gpioWaveAddGeneric failed\n");
        free(pulses);
        *wave_id_out = -1;
        return;
    }
    free(pulses);

    if (gpioWaveCreate() < 0) {
        fprintf(stderr, "[WS2812] gpioWaveCreate failed\n");
        *wave_id_out = -1;
        return;
    }
    *wave_id_out = w_id;
}

static void ws2812_transmit(uint8_t *leds, int num_leds)
{
    int w_id = -1;
    ws2812_build_wave(leds, num_leds, &w_id);
    if (w_id < 0)
        return;

    gpioWaveTxSend(w_id, PI_WAVE_MODE_ONE_SHOT);

    /* Wait for the wave to complete before deleting */
    while (gpioWaveTxBusy())
        gpioDelay(100);

    gpioWaveDelete(w_id);
}

static void ws2812_set_brightness(uint8_t *leds, int num_leds, float brightness)
{
    if (brightness < 0.0f) brightness = 0.0f;
    if (brightness > 1.0f) brightness = 1.0f;

    for (int i = 0; i < num_leds; i++) {
        for (int c = 0; c < 3; c++) {
            uint8_t v = leds[i * 3 + c];
            leds[i * 3 + c] = (uint8_t)(v * brightness);
        }
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (bh1750_init() < 0) {
        fprintf(stderr, "BH1750 initialisation failed – sensor absent or bus error\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure GPIO18 for hardware PWM output */
    gpioSetMode(WS2812_GPIO, PI_OUTPUT);
    gpioSetPWMfrequency(WS2812_GPIO, PWM_FREQ);
    gpioPWM(WS2812_GPIO, 0);  /* start with LED off */

    uint8_t leds[NUM_LEDS * 3];
    for (int i = 0; i < NUM_LEDS * 3; i++)
        leds[i] = 0;

    while (g_running) {
        float lux = 0.0f;
        if (bh1750_read_lux(&lux) < 0) {
            fprintf(stderr, "BH1750 read error – retrying in 1 s\n");
            gpioDelay(1000000);
            continue;
        }

        /* Logarithmic mapping: 0 lux → 0%, 1000 lux → 100% */
        float log_lux = log10f(lux + 1.0f);
        float norm    = log_lux / log10f(1000.0f + 1.0f);
        if (norm < 0.0f) norm = 0.0f;
        if (norm > 1.0f) norm = 1.0f;

        ws2812_set_brightness(leds, NUM_LEDS, norm);
        ws2812_transmit(leds, NUM_LEDS);

        printf("Lux: %.1f  Brightness: %.2f\n", lux, norm);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    gpioWaveTxStop();
    gpioPWM(WS2812_GPIO, 0);
    gpioSetMode(WS2812_GPIO, PI_INPUT);
    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

