/*
 * Raspberry Pi Zero W – BH1750 ambient light sensor → APA102 LED strip
 *
 * Hardware:
 *   BH1750  SDA → GPIO2 (pin 3), SCL → GPIO3 (pin 5), VCC → 3V3, GND → GND
 *   APA102  DIN → GPIO10 (pin 19, SPI0 MOSI), SCLK → GPIO11 (pin 23, SPI0 SCLK),
 *           CS  → GPIO8  (pin 24, SPI0 CE0),  VCC → 5V, GND → GND
 *
 * Build:  gcc -O2 -Wall -o light_led light_led.c -lpigpio -lrt
 * Run:    sudo ./light_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

#define I2C_BUS        "/dev/i2c-1"
#define SPI_DEVICE     "/dev/spidev0.0"
#define BH1750_ADDR    0x23
#define NUM_LEDS       10
#define SPI_SPEED_HZ   1000000U   /* 1 MHz – well within APA102 40 MHz limit */
#define SPI_BITS       8
#define SPI_DELAY_US   0
#define CONV_TIME_US   120000U    /* 120 ms conversion wait */
#define LOOP_DELAY_US  500000U    /* 500 ms between readings */
#define MAX_RETRIES    3

/* BH1750 commands (no register prefix required) */
#define BH1750_PWR_ON   0x01
#define BH1750_RESET    0x07
#define BH1750_CONT_HI  0x10  /* continuous high-resolution mode (~1 lux, ~120 ms) */

/* APA102 frame fields (big-endian on the wire) */
#define APA102_START    0x00000000U
#define APA102_END      0x00000000U
#define APA102_BRIGHT   0xE0U   /* global brightness, 4 bits (0xE = 14/15) */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static int g_spi_fd = -1;

/* ------------------------------------------------------------------ */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void sleep_us(uint32_t us)
{
    struct timespec ts = {
        .tv_sec  = (time_t)(us / 1000000U),
        .tv_nsec = (long)((us % 1000000U) * 1000L)
    };
    nanosleep(&ts, NULL);
}

/* ------------------------------------------------------------------ */
/* Write a single command byte to the BH1750 (no register prefix).     */
/* ------------------------------------------------------------------ */
static int bh1750_write_cmd(uint8_t cmd)
{
    if (write(g_i2c_fd, &cmd, 1) != 1) {
        fprintf(stderr, "BH1750 write(0x%02X) failed: %s\n", cmd, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the 2-byte light level from the BH1750.                        */
/* ------------------------------------------------------------------ */
static int bh1750_read_lux(float *lux_out)
{
    uint8_t buf[2];
    ssize_t n = read(g_i2c_fd, buf, sizeof(buf));
    if (n != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "BH1750 read failed (got %zd bytes): %s\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    /* BH1750 continuous high-res: lux = raw / 1.2 */
    *lux_out = (float)raw / 1.2f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Build and transmit an APA102 frame.                                 */
/* ------------------------------------------------------------------ */
static int apa102_send_frame(uint8_t brightness, uint8_t r, uint8_t g, uint8_t b)
{
    uint32_t led_frame = ((uint32_t)APA102_BRIGHT |
                         ((uint32_t)b << 16) |
                         ((uint32_t)g << 8)  |
                         ((uint32_t)r));

    size_t frame_len = 4 + (size_t)NUM_LEDS * 4 + 4;
    uint8_t *frame = malloc(frame_len);
    if (!frame) {
        fprintf(stderr, "APA102 malloc failed: %s\n", strerror(errno));
        return -1;
    }

    uint8_t *p = frame;
    uint32_t start_le = __builtin_bswap32(APA102_START);
    memcpy(p, &start_le, 4); p += 4;

    for (int i = 0; i < NUM_LEDS; i++) {
        uint32_t led_le = __builtin_bswap32(led_frame);
        memcpy(p, &led_le, 4); p += 4;
    }

    uint32_t end_le = __builtin_bswap32(APA102_END);
    memcpy(p, &end_le, 4);

    struct spi_ioc_transfer tr = {
        .tx_buf        = (unsigned long)frame,
        .rx_buf        = 0,
        .len           = frame_len,
        .speed_hz      = SPI_SPEED_HZ,
        .bits_per_word = SPI_BITS,
        .delay_usecs   = SPI_DELAY_US,
        .cs_change     = 0,
    };

    int ret = ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr);
    free(frame);

    if (ret < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void apa102_off(void)
{
    /* Send a frame of all-zero LEDs (brightness = 0) */
    uint8_t brightness = 0x00;
    (void)apa102_send_frame(brightness, 0, 0, 0);
}

/* ------------------------------------------------------------------ */
static int init_i2c(void)
{
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                BH1750_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    /* Power on and reset */
    if (bh1750_write_cmd(BH1750_PWR_ON) < 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    if (bh1750_write_cmd(BH1750_RESET) < 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }
    /* Start continuous high-resolution mode */
    if (bh1750_write_cmd(BH1750_CONT_HI) < 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
static int init_spi(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE_0;
    uint8_t bits = SPI_BITS;
    uint32_t speed = SPI_SPEED_HZ;

    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MODE failed: %s\n", strerror(errno));
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "SPI_IOC_WR_BITS_PER_WORD failed: %s\n", strerror(errno));
        goto fail;
    }
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "SPI_IOC_WR_MAX_SPEED_HZ failed: %s\n", strerror(errno));
        goto fail;
    }

    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        apa102_off();
        close(g_spi_fd);
        g_spi_fd = -1;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_i2c() < 0) {
        fprintf(stderr, "BH1750 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_spi() < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("BH1750 + APA102 ready. Press Ctrl+C to exit.\n");

    while (g_running) {
        float lux = 0.0f;
        int ok = 0;

        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (bh1750_read_lux(&lux) == 0) {
                ok = 1;
                break;
            }
            sleep_us(100000U);  /* 100 ms back-off before retry */
        }

        if (!ok) {
            fprintf(stderr, "BH1750 read failed after %d attempts; turning off LEDs.\n",
                    MAX_RETRIES);
            apa102_off();
            sleep_us(LOOP_DELAY_US);
            continue;
        }

        /* Scale lux (0–65535) to brightness (0–255) */
        uint8_t brightness = (uint8_t)(lux / 655.35f);
        if (brightness > 255) brightness = 255;

        /* Map brightness to RGB (linear interpolation) */
        uint8_t r, g, b;
        if (brightness < 85) {
            r = (uint8_t)(brightness * 3);
            g = (uint8_t)(brightness * 3);
            b = (uint8_t)(brightness * 3);
        } else if (brightness < 170) {
            r = (uint8_t)((brightness - 85) * 3);
            g = (uint8_t)(brightness * 2);
            b = (uint8_t)(brightness * 2);
        } else {
            r = (uint8_t)(brightness * 2);
            g = (uint8_t)(brightness * 2);
            b = (uint8_t)((brightness - 85) * 3);
        }

        if (apa102_send_frame(brightness, r, g, b) < 0) {
            fprintf(stderr, "APA102 frame transmission failed\n");
        }

        printf("Lux: %6.1f  Brightness: %3u  RGB: (%3u, %3u, %3u)\n",
               lux, brightness, r, g, b);

        sleep_us(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

