            b = (uint8_t)(brightness * 3);
        } else if (brightness < 170) {
            r = (uint8_t)((brightness - 85) * 3);
            g = (uint8_t)(brightness * 2);
            b = (uint8_t)(brightness * 2);
        } else {
            r = (uint8_t)(brightness * 2);
            g = (uint8_t)(brightness * 2);
            b = (uint8_t)((brightness - 85) * 3);
        }

        if (apa102_send_frame(brightness, r, g, b) < 0) {
            fprintf(stderr, "APA102 frame transmission failed\n");
        }

        printf("Lux: %6.1f  Brightness: %3u  RGB: (%3u, %3u, %3u)\n",
               lux, brightness, r, g, b);

        sleep_us(LOOP_DELAY_US);
    }

    printf("\nShutting down...\n");
