/*
 * Raspberry Pi 3 Model B+ — BH1750 ambient-light sensor array + APA102 LED strip
 *
 * Hardware:
 *   - BH1750  I2C  address 0x23 (ADDR pin low)  on I2C bus 1
 *   - BH1750  I2C  address 0x5C (ADDR pin high) on I2C bus 1
 *   - BH1750  I2C  address 0x62 (ADDR pin high) on I2C bus 1
 *   - APA102  data (MOSI) on GPIO10 (BCM)
 *   - APA102  clock (SCLK) on GPIO11 (BCM)
 *
 * Build:
 *   gcc -O2 -Wall -o light_led light_led.c -lpigpio -lrt
 * Run:
 *   sudo ./light_led
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- BH1750 constants ---- */
#define BH1750_ADDR_1 0x23
#define BH1750_ADDR_2 0x5C
#define BH1750_ADDR_3 0x62
#define BH1750_PWR_ON 0x01
#define BH1750_RESET  0x07
#define BH1750_CONT_HIGH_RES 0x10  /* ~120 ms, ~1 lx resolution */
#define BH1750_CONV_TIME_US 180000 /* 180 ms conversion wait */

/* ---- APA102 constants ---- */
#define APA102_NUM_LEDS 30
#define APA102_START_FRAME 0x00
#define APA102_END_FRAME 0xFF
#define APA102_BRIGHTNESS 0xE0  /* global brightness 31/32 */
#define SPI_SPEED 1000000       /* 1 MHz */

/* ---- Globals ---- */
static int i2c_handles[3] = {-1, -1, -1};
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ---- Prototypes ---- */
static int  init_bh1750(int addr);
static int  read_bh1750(int handle);
static int  init_apa102(void);
static void set_apa102_brightness(uint8_t brightness);
static void cleanup(void);
static void signal_handler(int sig);

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- Initialize a BH1750 sensor ---- */
static int init_bh1750(int addr)
{
    int handle = i2cOpen(1, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "BH1750 @ 0x%02X: i2cOpen failed (%d)\n", addr, handle);
        return -1;
    }

    /* Power on */
    if (i2cWriteByte(handle, BH1750_PWR_ON) < 0) {
        fprintf(stderr, "BH1750 @ 0x%02X: power-on write failed\n", addr);
        i2cClose(handle);
        return -1;
    }

    /* Reset */
    if (i2cWriteByte(handle, BH1750_RESET) < 0) {
        fprintf(stderr, "BH1750 @ 0x%02X: reset write failed\n", addr);
        i2cClose(handle);
        return -1;
    }

    /* Set continuous high-resolution mode */
    if (i2cWriteByte(handle, BH1750_CONT_HIGH_RES) < 0) {
        fprintf(stderr, "BH1750 @ 0x%02X: mode write failed\n", addr);
        i2cClose(handle);
        return -1;
    }

    return handle;
}

/* ---- Read light level from a BH1750 ---- */
static int read_bh1750(int handle)
{
    char buf[2];
    int bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        fprintf(stderr, "BH1750 read failed (got %d bytes)\n", bytes);
        return -1;
    }
    return ((uint8_t)buf[0] << 8) | (uint8_t)buf[1];
}

/* ---- Initialize APA102 SPI ---- */
static int init_apa102(void)
{
    /* pigpio spiOpen flags: 0 = mode 0, active-low CE, 8-bit words */
    spi_handle = spiOpen(0, SPI_SPEED, 0);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed (%d)\n", spi_handle);
        return -1;
    }
    return 0;
}

/* ---- Send a frame to the APA102 strip ---- */
static void set_apa102_brightness(uint8_t brightness)
{
    if (spi_handle < 0)
        return;

    /* 4-byte frame per LED: 0xE0 | B, G, R, B */
    uint8_t frame[APA102_NUM_LEDS * 4 + 4];
    size_t idx = 0;

    frame[idx++] = APA102_START_FRAME;
    frame[idx++] = APA102_START_FRAME;
    frame[idx++] = APA102_START_FRAME;
    frame[idx++] = APA102_START_FRAME;

    for (int i = 0; i < APA102_NUM_LEDS; i++) {
        frame[idx++] = 0xE0 | brightness; /* global brightness */
        frame[idx++] = 0x00;             /* blue   */
        frame[idx++] = 0x00;             /* green  */
        frame[idx++] = 0x00;             /* red    */
    }

    frame[idx++] = APA102_END_FRAME;
    frame[idx++] = APA102_END_FRAME;

    if (spiWrite(spi_handle, (char *)frame, idx) < 0) {
        fprintf(stderr, "spiWrite failed\n");
    }
}

/* ---- Cleanup all resources ---- */
static void cleanup(void)
{
    /* Turn off LED strip */
    set_apa102_brightness(0x00);

    /* Close I2C handles */
    for (int i = 0; i < 3; i++) {
        if (i2c_handles[i] >= 0) {
            i2cClose(i2c_handles[i]);
            i2c_handles[i] = -1;
        }
    }

    /* Close SPI */
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    /* Terminate pigpio */
    gpioTerminate();
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Initialize I2C sensors */
    int addrs[3] = {BH1750_ADDR_1, BH1750_ADDR_2, BH1750_ADDR_3};
    for (int i = 0; i < 3; i++) {
        i2c_handles[i] = init_bh1750(addrs[i]);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Warning: BH1750 @ 0x%02X not found, skipping\n", addrs[i]);
        }
    }

    /* Initialize APA102 */
    if (init_apa102() < 0) {
        cleanup();
        return EXIT_FAILURE;
    }

    /* Install signal handler */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* Main loop */
    while (!terminate) {
        int sum = 0;
        int count = 0;

        /* Read each sensor that is present */
        for (int i = 0; i < 3; i++) {
            if (i2c_handles[i] >= 0) {
                int light = read_bh1750(i2c_handles[i]);
                if (light >= 0) {
                    sum += light;
                    count++;
                }
            }
        }

        int avg = (count > 0) ? (sum / count) : 0;

        /* Map 0–65535 to 0–255 brightness (linear) */
        uint8_t brightness = (uint8_t)(avg >> 8);

        /* Fade to target brightness over 500 ms */
        uint8_t current = 0;
        int steps = 50;
        int step_delay = 10000; /* 10 ms per step */
        for (int s = 0; s < steps && !terminate; s++) {
            current += (brightness - current) / steps;
            set_apa102_brightness(current);
            gpioDelay(step_delay);
        }

        gpioDelay(100000); /* 100 ms between cycles */
    }

    cleanup();
    return EXIT_SUCCESS;
}

