/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *out)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    uint8_t buf[2];
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

/* ------------------------------------------------------------------ */
/* VEML7700                                                           */
/* ------------------------------------------------------------------ */
static int veml7700_init(int fd)
{
    /*
     * Configuration:
     *   IT = 100ms (bits[11:9] = 000)
     *   HD = 100ms (bits[8:6]  = 000)
     *   AF = 1     (bit[5]    = 1)
     *   SD = 0     (bit[4]    = 0)
     *   bits[3:0] = 0000
     * => 0x0000
     */
    if (i2c_write_reg8(fd, VEML7700_CONF, 0x00) != 0)
        return -1;
    usleep(50000); /* power-up delay */
    return 0;
}

static int veml7700_read_lux(int fd, uint16_t *lux_out)
{
    uint16_t als;
    if (i2c_read_reg16(fd, VEML7700_ALS, &als) != 0)
        return -1;
    *lux_out = als;
    return 0;
}

/* ------------------------------------------------------------------ */
/* WS2812B bit-bang (pigpio)                                           */
/* ------------------------------------------------------------------ */
static void ws2812b_set_brightness(uint8_t brightness)
{
    /*
     * 24 bits per LED, MSB-first, 0 = ~700 ns low, 1 = ~600 ns high.
     * pigpio's gpioWrite is ~100 ns per call, so a simple threshold
     * approach (50% duty cycle) is sufficient for a 800 kHz carrier.
     */
    uint32_t color = ((uint32_t)brightness << 16) |
                     ((uint32_t)brightness << 8)  |
                     (uint32_t)brightness;

    uint8_t bits[24];
    for (int i = 0; i < 24; i++) {
        bits[i] = (color >> (23 - i)) & 1;
    }

    gpioSetMode(WS2812B_PIN, PI_OUTPUT);
    gpioWrite(WS2812B_PIN, 0);
    usleep(50); /* reset / latch */

    for (int i = 0; i < 24; i++) {
        if (bits[i]) {
            /* ~700 ns low + ~600 ns high = ~1300 ns total per bit */
            gpioWrite(WS2812B_PIN, 1);
            usleep(1);
