#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define FLAME_SENSOR_PIN 4
#define BUZZER_PIN       17
#define LED_PIN          18

#define SELF_TEST_SAMPLES 5
#define SELF_TEST_DELAY_US 100000
#define POLL_DELAY_US      50000
#define LED_BLINK_US       500000
#define LED_ERROR_US       100000
#define BUZZER_PATTERN_MS  {200, 200, 600, 200}
#define BUZZER_REPEATS     3

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg) {
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", ts, msg);
    fflush(stdout);
}

static int safe_set_mode(unsigned pin, unsigned mode) {
    if (gpioSetMode(pin, mode) < 0) {
        fprintf(stderr, "Error: gpioSetMode(%u, %u) failed\n", pin, mode);
        return -1;
    }
    return 0;
}

static int safe_write(unsigned pin, unsigned level) {
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %u) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_read(unsigned pin) {
    int v = gpioRead(pin);
    if (v < 0) {
        fprintf(stderr, "Error: gpioRead(%u) failed\n", pin);
        return -1;
    }
    return v;
}

static int self_test(void) {
    log_event("Starting self-test...");

    for (int i = 0; i < 2; i++) {
        if (safe_write(LED_PIN, 1) < 0) return -1;
        gpioDelay(LED_BLINK_US);
        if (safe_write(LED_PIN, 0) < 0) return -1;
        gpioDelay(LED_BLINK_US);
    }

    int flame_detected = 0;
    for (int i = 0; i < SELF_TEST_SAMPLES; i++) {
        int v = safe_read(FLAME_SENSOR_PIN);
        if (v < 0) return -1;
        if (v == 0) flame_detected = 1;
        gpioDelay(SELF_TEST_DELAY_US);
    }

    if (flame_detected) {
        log_event("Flame detected during self-test!");
        for (int rep = 0; rep < BUZZER_REPEATS; rep++) {
            const int pat[] = BUZZER_PATTERN_MS;
            for (size_t j = 0; j < sizeof(pat) / sizeof(pat[0]); j++) {
                if (safe_write(BUZZER_PIN, 1) < 0) return -1;
                gpioDelay(pat[j] * 1000);
                if (safe_write(BUZZER_PIN, 0) < 0) return -1;
                gpioDelay(pat[j] * 1000);
            }
        }
        for (int i = 0; i < 5; i++) {
            if (safe_write(LED_PIN, 1) < 0) return -1;
            gpioDelay(LED_ERROR_US);
            if (safe_write(LED_PIN, 0) < 0) return -1;
            gpioDelay(LED_ERROR_US);
        }
        return 1;
    }

    log_event("Self-test passed.");
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        gpioTerminate();
        return 1;
    }

    if (safe_set_mode(FLAME_SENSOR_PIN, PI_INPUT) < 0 ||
        safe_set_mode(BUZZER_PIN, PI_OUTPUT) < 0 ||
        safe_set_mode(LED_PIN, PI_OUTPUT) < 0) {
        gpioTerminate();
        return 1;
    }

    int st = self_test();
    if (st < 0) {
        log_event("Self-test failed due to GPIO error.");
        gpioTerminate();
        return 1;
    }
    if (st == 1) {
        gpioTerminate();
        return 1;
    }

    log_event("Entering main loop...");
    int alarm_active = 0;

    while (g_running) {
        int v = safe_read(FLAME_SENSOR_PIN);
        if (v < 0) {
            log_event("Error reading flame sensor.");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        if (v == 0 && !alarm_active) {
            log_event("Flame detected!");
            if (safe_write(BUZZER_PIN, 1) < 0 || safe_write(LED_PIN, 1) < 0) {
                log_event("Error activating alarm outputs.");
            } else {
                alarm_active = 1;
            }
        } else if (v == 1 && alarm_active) {
            log_event("Flame cleared.");
            if (safe_write(BUZZER_PIN, 0) < 0 || safe_write(LED_PIN, 0) < 0) {
                log_event("Error deactivating alarm outputs.");
            } else {
                alarm_active = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    log_event("Shutting down...");
    safe_write(BUZZER_PIN, 0);
    safe_write(LED_PIN, 0);
    gpioTerminate();
    return 0;
}

