#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define I2C_BUS        "/dev/i2c-1"
#define BH1750_ADDR    0x23
#define BH1750_CONT_H  0x10  /* continuous high-resolution mode */
#define GPIO_LED       17
#define BUFFER_SIZE    60
#define SAMPLE_PERIOD  1     /* seconds */

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */

static int i2c_write_byte(int fd, uint8_t byte)
{
    if (write(fd, &byte, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, uint16_t *out)
{
    uint8_t buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read failed (got %zd bytes): %s\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }
    /* BH1750 sends MSB first */
    *out = ((uint16_t)buf[0] << 8) | buf[1];
    return 0;
}

/* ---- BH1750 ---- */

static int bh1750_init(int fd)
{
    return i2c_write_byte(fd, BH1750_CONT_H);
}

static int bh1750_read_lux(int fd, float *lux)
{
    uint16_t raw;
    if (i2c_read_word(fd, &raw) < 0)
        return -1;
    /* Conversion: lux = raw / 1.2 */
    *lux = (float)raw / 1.2f;
    return 0;
}

/* ---- GPIO (sysfs) ---- */

static int gpio_export(int pin)
{
    int fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "export open failed: %s\n", strerror(errno));
        return -1;
    }
    char buf[16];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, (size_t)len) != len) {
        fprintf(stderr, "export write failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_unexport(int pin)
{
    int fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "unexport open failed: %s\n", strerror(errno));
        return -1;
    }
    char buf[16];
    int len = snprintf(buf, sizeof(buf), "%d", pin);
    if (write(fd, buf, (size_t)len) != len) {
        fprintf(stderr, "unexport write failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_set_direction(int pin, const char *dir)
{
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "direction open failed: %s\n", strerror(errno));
        return -1;
    }
    if (write(fd, dir, strlen(dir)) != (ssize_t)strlen(dir)) {
        fprintf(stderr, "direction write failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

static int gpio_write(int pin, int value)
{
    char path[64];
    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    int fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "value open failed: %s\n", strerror(errno));
        return -1;
    }
    char buf[2] = { value ? '1' : '0', '\n' };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "value write failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

/* ---- Circular buffer ---- */

typedef struct {
    float data[BUFFER_SIZE];
    int   head;
    int   count;
} CircularBuffer;

static void cb_init(CircularBuffer *cb)
{
    memset(cb->data, 0, sizeof(cb->data));
    cb->head  = 0;
    cb->count = 0;
}

static void cb_push(CircularBuffer *cb, float v)
{
    cb->data[cb->head] = v;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static float cb_average(const CircularBuffer *cb)
{
    if (cb->count == 0)
        return 0.0f;
    float sum = 0.0f;
    for (int i = 0; i < cb->count; i++)
        sum += cb->data[i];
    return sum / (float)cb->count;
}

/* ---- Main ---- */

int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return 1;
    }

    /* I2C */
    int i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "open %s failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }
    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                BH1750_ADDR, strerror(errno));
        close(i2c_fd);
        return 1;
    }
    if (bh1750_init(i2c_fd) < 0) {
        fprintf(stderr, "BH1750 init failed\n");
        close(i2c_fd);
        return 1;
    }

    /* GPIO */
    if (gpio_export(GPIO_LED) < 0) {
        close(i2c_fd);
        return 1;
    }
    if (gpio_set_direction(GPIO_LED, "out") < 0) {
        gpio_unexport(GPIO_LED);
        close(i2c_fd);
        return 1;
    }

    CircularBuffer lux_buf;
    cb_init(&lux_buf);

    printf("BH1750 lux reader started. Press Ctrl-C to exit.\n");

    while (g_running) {
        float lux;
        if (bh1750_read_lux(i2c_fd, &lux) < 0) {
            fprintf(stderr, "Sensor read error; skipping sample.\n");
        } else {
            cb_push(&lux_buf, lux);
            float avg = cb_average(&lux_buf);
            printf("Lux: %.2f  |  Avg(%d): %.2f\n", lux, lux_buf.count, avg);

            /* Blink frequency: 0.5 Hz at 0 lux, 5 Hz at 1000+ lux */
            float freq = 0.5f + (avg / 1000.0f) * 4.5f;
            if (freq < 0.5f) freq = 0.5f;
            if (freq > 5.0f) freq = 5.0f;

            int half_period_us = (int)(500000.0f / freq);
            if (half_period_us < 1000) half_period_us = 1000;  /* safety cap */

            for (int i = 0; i < 10 && g_running; i++) {
                if (gpio_write(GPIO_LED, 1) < 0) break;
                usleep(half_period_us);
                if (gpio_write(GPIO_LED, 0) < 0) break;
                usleep(half_period_us);
            }
        }

        /* Sleep but wake early on signal */
        for (int s = 0; s < SAMPLE_PERIOD && g_running; s++)
            sleep(1);
    }

    /* Cleanup */
    gpio_write(GPIO_LED, 0);
    gpio_unexport(GPIO_LED);
    close(i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

