#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <unistd.h>

#define DATA_PIN  17
#define CLOCK_PIN 18
#define LATCH_PIN 27

/* 74HC595 outputs Q0..Q7 mapped to segments a..g (dp unused) */
static const unsigned char digit_5[8] = {
    0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x01, 0x00
};

static void shift_out(int data, int clock, int latch)
{
    for (int i = 7; i >= 0; i--) {
        if (gpioWrite(clock, 0) < 0) {
            fprintf(stderr, "gpioWrite(clock, 0) failed\n");
            return;
        }
        if (gpioWrite(data, (data >> i) & 1) < 0) {
            fprintf(stderr, "gpioWrite(data, %d) failed\n", (data >> i) & 1);
            return;
        }
        if (gpioWrite(clock, 1) < 0) {
            fprintf(stderr, "gpioWrite(clock, 1) failed\n");
            return;
        }
    }
    if (gpioWrite(latch, 1) < 0) {
        fprintf(stderr, "gpioWrite(latch, 1) failed\n");
        return;
    }
    if (gpioWrite(latch, 0) < 0) {
        fprintf(stderr, "gpioWrite(latch, 0) failed\n");
        return;
    }
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(DATA_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(DATA_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(CLOCK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(CLOCK_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LATCH_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode(LATCH_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure lines start in a known low state */
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);

    while (1) {
        shift_out(digit_5[0], DATA_PIN, CLOCK_PIN);
        shift_out(digit_5[1], DATA_PIN, CLOCK_PIN);
        shift_out(digit_5[2], DATA_PIN, CLOCK_PIN);
        shift_out(digit_5[3], DATA_PIN, CLOCK_PIN);
        shift_out(digit_5[4], DATA_PIN, CLOCK_PIN);
        shift_out(digit_5[5], DATA_PIN, CLOCK_PIN);
        shift_out(digit_5[6], DATA_PIN, CLOCK_PIN);
        shift_out(digit_5[7], DATA_PIN, CLOCK_PIN);

        gpioDelay(500000); /* 500 ms on */

        /* Clear display (all segments off) */
        for (int i = 0; i < 8; i++) {
            shift_out(0x00, DATA_PIN, CLOCK_PIN);
        }

        gpioDelay(500000); /* 500 ms off */
    }

    /* Unreachable in normal operation, but clean shutdown */
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

