/*
 * blink_button.c — Blink an LED on GPIO17 (BCM) with a 2-second period,
 * and stop immediately when a falling-edge event is detected on GPIO18.
 *
 * Build:  gcc -o blink_button blink_button.c -lgpiod
 * Run:    ./blink_button
 */
#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <gpiod.h>

#define LED_PIN    17
#define BUTTON_PIN 18
