#include <gpiod.h>

#define LED_PIN    24   /* BCM 24, physical pin 18 */
#define BUTTON_PIN 22   /* BCM 22, physical pin 15 */
#define CHIP_NAME  "gpiochip0"

static volatile sig_atomic_t running = 1;

static void sighandler(int sig)
{
    (void)sig;
    running = 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *led = NULL;
    struct gpiod_line *button = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = sighandler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Open the GPIO chip */
    chip = gpiod_chip_open_by_name(CHIP_NAME);
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    /* Get the LED line */
    led = gpiod_chip_get_line(chip, LED_PIN);
    if (!led) {
        perror("gpiod_chip_get_line(LED)");
        goto cleanup;
    }

    /* Get the button line */
    button = gpiod_chip_get_line(chip, BUTTON_PIN);
    if (!button) {
        perror("gpiod_chip_get_line(BUTTON)");
        goto cleanup;
    }

    /* Request LED as output, initial value low */
    if (gpiod_line_request_output(led, "led-blink", 0) < 0) {
        perror("gpiod_line_request_output(LED)");
        goto cleanup;
    }

    /* Request button as input with pull-down */
    if (gpiod_line_request_input_flags(button, "button-led",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_DOWN) < 0) {
        perror("gpiod_line_request_input_flags(BUTTON)");
        goto cleanup;
    }

    printf("LED and button ready. Hold the button to blink the LED. Ctrl-C to exit.\n");

    while (running) {
        int val = gpiod_line_get_value(button);
        if (val < 0) {
            perror("gpiod_line_get_value(BUTTON)");
            break;
        }

        if (val == 1) {
            /* Button pressed: blink LED 500 ms on / 500 ms off */
            if (gpiod_line_set_value(led, 1) < 0) {
                perror("gpiod_line_set_value(LED, 1)");
                break;
            }
            usleep(500000);
            if (!running) break;
            if (gpiod_line_set_value(led, 0) < 0) {
                perror("gpiod_line_set_value(LED, 0)");
                break;
            }
            usleep(500000);
        } else {
            /* Button released: ensure LED is off */
            if (gpiod_line_set_value(led, 0) < 0) {
                perror("gpiod_line_set_value(LED, 0)");
                break;
            }
            usleep(10000); /* 10 ms poll delay to avoid busy-loop */
        }
    }

    /* Turn LED off before exit */
    if (led) {
        gpiod_line_set_value(led, 0);
    }
    ret = EXIT_SUCCESS;

cleanup:
    if (led) gpiod_line_release(led);
    if (button) gpiod_line_release(button);
    if (chip) gpiod_chip_close(chip);
    return ret;
}

