#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

#define PWM_PERIOD_NS 10000000L   /* 10 ms -> 100 Hz */
#define STEP_NS       100000L     /* 100 us step for busy-wait */
#define COLOR_CHANGE_MS 100

static volatile sig_atomic_t running = 1;

static void sigint_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* Busy-wait sleep: sub-millisecond precision using clock_nanosleep */
static void busy_wait_ns(long ns)
{
    struct timespec req = {
        .tv_sec  = ns / 1000000000L,
        .tv_nsec = ns % 1000000000L
    };
    while (req.tv_sec > 0 || req.tv_nsec > 0) {
        struct timespec rem;
        if (clock_nanosleep(CLOCK_MONOTONIC, 0, &req, &rem) == 0) {
            req = rem;
        } else if (errno == EINTR) {
            req = rem;
        } else {
            break;
        }
    }
}

/* Drive a single PWM channel: duty 0..100, period 10 ms */
static void set_pwm(struct gpiod_line *line, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > 100) duty = 100;

    long on_ns  = (PWM_PERIOD_NS * duty) / 100;
    long off_ns = PWM_PERIOD_NS - on_ns;

    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "set_pwm: failed to set line high: %s\n", strerror(errno));
        return;
    }
    busy_wait_ns(on_ns);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "set_pwm: failed to set line low: %s\n", strerror(errno));
        return;
    }
    busy_wait_ns(off_ns);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *red_line = NULL, *green_line = NULL, *blue_line = NULL;
    int ret = EXIT_FAILURE;

    /* Install signal handler for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip4 on Raspberry Pi 5) */
    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        chip = gpiod_chip_open_by_name("gpiochip0");
    }
    if (!chip) {
        fprintf(stderr, "Failed to open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Get the three GPIO lines */
    red_line   = gpiod_chip_get_line(chip, RED_PIN);
    green_line = gpiod_chip_get_line(chip, GREEN_PIN);
    blue_line  = gpiod_chip_get_line(chip, BLUE_PIN);
    if (!red_line || !green_line || !blue_line) {
        fprintf(stderr, "Failed to get GPIO lines: %s\n", strerror(errno));
        goto cleanup;
    }

    /* Request each line as output, initial value LOW */
    if (gpiod_line_request_output(red_line, "rgb_led", 0) < 0) {
        fprintf(stderr, "Failed to request red line: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(green_line, "rgb_led", 0) < 0) {
        fprintf(stderr, "Failed to request green line: %s\n", strerror(errno));
        goto cleanup;
    }
    if (gpiod_line_request_output(blue_line, "rgb_led", 0) < 0) {
        fprintf(stderr, "Failed to request blue line: %s\n", strerror(errno));
        goto cleanup;
    }

    srand((unsigned int)time(NULL));

    while (running) {
        int red   = rand() % 101;
        int green = rand() % 101;
        int blue  = rand() % 101;

        set_pwm(red_line,   red);
        set_pwm(green_line, green);
        set_pwm(blue_line,  blue);

        /* Sleep 100 ms between color changes */
        struct timespec ts = {
            .tv_sec  = COLOR_CHANGE_MS / 1000,
            .tv_nsec = (COLOR_CHANGE_MS % 1000) * 1000000L
        };
