/*
 * LSM303DLHC Impact Detector for Raspberry Pi Zero W
 *
 * Polls the accelerometer at 10 Hz, computes the total G-force magnitude,
 * and pulses GPIO17 HIGH when the magnitude exceeds a configurable threshold.
 *
 * Build:  gcc -O2 -Wall -o impact_detect impact_detect.c -lpigpio -lrt -lm
 * Run:    sudo ./impact_detect [-t threshold_g]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <getopt.h>
#include <pigpio.h>

/* ---- LSM303DLHC I2C constants ---- */
#define LSM303_ACCEL_ADDR   0x19
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A   0x28

/* ---- GPIO / timing constants ---- */
#define GPIO_PIN            17
#define PULSE_DURATION_US   50000   /* 50 ms */
#define SAMPLE_PERIOD_US    100000  /* 10 Hz */

/* ---- Globals for cleanup ---- */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- Read 6 bytes of accelerometer data ---- */
static int read_accel_data(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];

    if (i2cReadI2CBlockData(handle, LSM303_ACCEL_OUT_X_L_A, buf, 6) != 6) {
        fprintf(stderr, "Error: failed to read 6-byte accelerometer block\n");
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | (uint8_t)buf[0]);
    *y = (int16_t)((buf[3] << 8) | (uint8_t)buf[2]);
    *z = (int16_t)((buf[5] << 8) | (uint8_t)buf[4]);
    return 0;
}

/* ---- Compute total G-force magnitude ---- */
static double calculate_magnitude(int16_t x, int16_t y, int16_t z)
{
    /* Sensitivity for default range +/- 2 g: 1 mg/LSB = 0.001 g/LSB */
    const double scale = 0.001;
    return sqrt((double)x * x + (double)y * y + (double)z * z) * scale;
}

/* ---- Log impact event with timestamp ---- */
static void log_impact(int16_t x, int16_t y, int16_t z, double magnitude)
{
    FILE *fp = fopen("impact_log.txt", "a");
    if (!fp) {
        perror("Error opening impact_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X=%d, Y=%d, Z=%d, Mag=%.3f G\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z, magnitude);
    }
    fclose(fp);
}

/* ---- Trigger impact interrupt ---- */
static void trigger_impact(void)
{
    if (gpioWrite(GPIO_PIN, 1) < 0) {
        fprintf(stderr, "Warning: failed to set GPIO%d HIGH\n", GPIO_PIN);
        return;
    }
    gpioDelay(PULSE_DURATION_US);
    if (gpioWrite(GPIO_PIN, 0) < 0) {
        fprintf(stderr, "Warning: failed to set GPIO%d LOW\n", GPIO_PIN);
    }
}

/* ---- Initialize LSM303DLHC accelerometer ---- */
static int init_accelerometer(int handle)
{
    /*
     * CTRL_REG1_A (0x20):
     *   0x57 = 0b01010111
     *       0x07  -> ODR = 100 Hz (bits[6:4] = 100)
     *       0x00  -> LPen = normal mode (bit[3] = 0)
     *       0x00  -> Zen = X/Y/Z enabled (bits[2:1] = 00)
     *       0x00  -> Yen = X/Y/Z enabled
     *       0x00  -> Xen = X/Y/Z enabled
     */
    if (i2cWriteByteData(handle, LSM303_ACCEL_CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error: failed to write CTRL_REG1_A\n");
        return -1;
    }
    return 0;
}

/* ---- Cleanup resources ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

int main(int argc, char *argv[])
{
    double threshold = 2.0;
    int opt;

    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                threshold = atof(optarg);
                if (threshold <= 0.0) {
                    fprintf(stderr, "Threshold must be positive\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold_g]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the LSM303DLHC address */
    i2c_handle = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: failed to open I2C device at 0x%02X (err=%d)\n",
                LSM303_ACCEL_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize accelerometer */
    if (init_accelerometer(i2c_handle) < 0) {
        fprintf(stderr, "Error: LSM303DLHC not detected or init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure GPIO17 as output and ensure it starts LOW */
    if (gpioSetMode(GPIO_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", GPIO_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(GPIO_PIN, 0);

    /* Register signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Impact detection started. Threshold: %.2f G. Press Ctrl+C to exit.\n",
           threshold);

    /* Main sampling loop */
    while (!terminate) {
        int16_t x, y, z;

        if (read_accel_data(i2c_handle, &x, &y, &z) < 0) {
            /*
             * I2C error: wait briefly and retry.
             * A disconnected sensor or bus glitch is not fatal.
             */
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        double magnitude = calculate_magnitude(x, y, z);

        if (magnitude > threshold) {
            printf("Impact detected! Magnitude: %.3f G\n", magnitude);
            log_impact(x, y, z, magnitude);
            trigger_impact();
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

