/*
 * Raspberry Pi Zero W - ADPD188BI Ambient Light & Color Logger
 *
 * Reads ALS, Red, Green, and Blue data from the ADPD188BI via I2C bus 1.
 * Logs timestamped readings to color_log.csv.
 * Controls an LED on GPIO18 (BCM) with hardware PWM proportional to ALS.
 *
 * Hardware:
 *   - ADPD188BI SDA -> GPIO2 (I2C1 SDA)
 *   - ADPD188BI SCL -> GPIO3 (I2C1 SCL)
 *   - ADPD188BI VDD -> 3.3V
 *   - ADPD188BI GND -> GND
 *   - LED anode -> GPIO18 (BCM) via 330 ohm resistor
 *   - LED cathode -> GND
 *
 * Build: gcc -o color_logger color_logger.c -lpigpio -lrt
 * Run:   sudo ./color_logger
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADPD188BI I2C address (7-bit) */
#define ADPD188BI_ADDR 0x50

/* ADPD188BI register addresses */
#define REG_ALS_LSB   0x04
#define REG_ALS_MSB   0x05
#define REG_RED_LSB   0x06
#define REG_RED_MSB   0x07
#define REG_GREEN_LSB 0x08
#define REG_GREEN_MSB 0x09
#define REG_BLUE_LSB  0x0A
#define REG_BLUE_MSB  0x0B

/* LED GPIO pin (BCM) */
#define LED_PIN 18

/* PWM range and frequency */
#define PWM_RANGE 255
#define PWM_FREQ  1000

/* Sampling interval in microseconds (500 ms) */
#define SAMPLE_INTERVAL_US 500000

/* Error delay in microseconds (100 ms) */
#define ERROR_DELAY_US 100000

/* Global state for signal handler */
static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Read a 16-bit little-endian register from the ADPD188BI */
static int read_register16(int handle, uint8_t reg_lsb, uint8_t reg_msb, uint16_t *value) {
    int lsb = i2cReadByteData(handle, reg_lsb);
    if (lsb < 0) {
        return -1;
    }
    int msb = i2cReadByteData(handle, reg_msb);
    if (msb < 0) {
        return -1;
    }
    *value = (uint16_t)((msb << 8) | lsb);
    return 0;
}

/* Read all four channels from the ADPD188BI */
static int read_sensor_data(int handle, uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (read_register16(handle, REG_ALS_LSB, REG_ALS_MSB, als) < 0) return -1;
    if (read_register16(handle, REG_RED_LSB, REG_RED_MSB, red) < 0) return -1;
    if (read_register16(handle, REG_GREEN_LSB, REG_GREEN_MSB, green) < 0) return -1;
    if (read_register16(handle, REG_BLUE_LSB, REG_BLUE_MSB, blue) < 0) return -1;
    return 0;
}

/* Log a data row to the CSV file */
static void log_data(FILE *fp, uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(fp);
}

/* Set LED brightness proportional to ALS (0-255) */
static void set_led_brightness(uint16_t als) {
    /* Map ALS (0-65535) to PWM range (0-255) */
    int brightness = (int)(als * PWM_RANGE / 65535);
    if (brightness < 0) brightness = 0;
    if (brightness > PWM_RANGE) brightness = PWM_RANGE;
    gpioPWM(LED_PIN, brightness);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at the ADPD188BI address */
    i2c_handle = i2cOpen(1, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X (code %d).\n", ADPD188BI_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open CSV file for logging */
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open color_log.csv for writing.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
        fflush(log_file);
    }

    /* Configure LED pin for hardware PWM */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioSetPWMrange(LED_PIN, PWM_RANGE);
    gpioSetPWMfrequency(LED_PIN, PWM_FREQ);
    gpioPWM(LED_PIN, 0); /* Start with LED off */

    /* Set up signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADPD188BI color logger started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (running) {
        uint16_t als, red, green, blue;

        if (read_sensor_data(i2c_handle, &als, &red, &green, &blue) == 0) {
            log_data(log_file, als, red, green, blue);
            set_led_brightness(als);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Retrying in %d ms.\n", ERROR_DELAY_US / 1000);
            gpioDelay(ERROR_DELAY_US);
            continue;
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful shutdown */
    printf("\nShutting down...\n");
    gpioPWM(LED_PIN, 0); /* Turn off LED */
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    printf("Cleanup complete.\n");

    return EXIT_SUCCESS;
}

