#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define FXOS8700_ADDR        0x1F
#define WHO_AM_I             0x0D
#define WHO_AM_I_VAL         0xC7
#define CTRL_REG1            0x2A
#define CTRL_REG2            0x2B
#define XYZ_DATA_CFG         0x0E
#define OUT_X_MSB            0x01
#define STATUS_REG           0x00
#define STATUS_DATA_READY    0x08
#define IMPACT_THRESHOLD     2.0f
#define SAMPLE_PERIOD_US     50000  /* 50 ms */
#define LOG_FILE             "impact_log.txt"

/* ---- Globals for cleanup ---- */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg(uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(i2c_handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %s\n",
                reg, val, pigpio_error(rc));
    }
    return rc;
}

static int i2c_read_reg(uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %s\n",
                reg, pigpio_error(rc));
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int i2c_read_block(uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "I2C block read failed (reg=0x%02X, len=%u): %s\n",
                reg, len, pigpio_error(rc));
        return -1;
    }
    if ((uint32_t)rc != len) {
        fprintf(stderr, "I2C block read short: got %d, expected %u\n", rc, len);
        return -1;
    }
    return 0;
}

/* ---- Sensor init ---- */
static int init_fxos8700(void)
{
    uint8_t who;

    if (i2c_read_reg(WHO_AM_I, &who) < 0)
        return -1;

    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who, WHO_AM_I_VAL);
        return -1;
    }

    /* Standby first so configuration changes take effect */
    if (i2c_write_reg(CTRL_REG1, 0x00) < 0)
        return -1;

    /* ±2 g range */
    if (i2c_write_reg(XYZ_DATA_CFG, 0x00) < 0)
        return -1;

    /* 200 Hz ODR, no sleep, active mode */
    if (i2c_write_reg(CTRL_REG1, 0x0D) < 0)
        return -1;

    /* Enable hybrid auto-increment (MSB/LSB pairs) */
    if (i2c_write_reg(CTRL_REG2, 0x02) < 0)
        return -1;

    return 0;
}

/* ---- Read one sample ---- */
static int read_accel(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t status;
    uint8_t raw[6];

    if (i2c_read_reg(STATUS_REG, &status) < 0)
        return -1;

    if (!(status & STATUS_DATA_READY)) {
        /* Data not ready yet — skip this cycle */
        return 1;
    }

    /* Read 6 bytes starting at OUT_X_MSB (0x01) */
    if (i2c_read_block(OUT_X_MSB, raw, 6) < 0)
        return -1;

    *x = (int16_t)((raw[0] << 8) | raw[1]) >> 2;
    *y = (int16_t)((raw[2] << 8) | raw[3]) >> 2;
    *z = (int16_t)((raw[4] << 8) | raw[5]) >> 2;

    return 0;
}

/* ---- Log impact ---- */
static void log_impact(int16_t x, int16_t y, int16_t z, float mag)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%d,%d,%d,%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec,
                x, y, z, mag);
    } else {
        fprintf(fp, "1970-01-01 00:00:00,%d,%d,%d,%.3f\n", x, y, z, mag);
    }

    fclose(fp);
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, FXOS8700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed: %s\n", pigpio_error(i2c_handle));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_fxos8700() < 0) {
        fprintf(stderr, "FXOS8700 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("FXOS8700 initialised. Logging impacts > %.2f g to %s\n",
           IMPACT_THRESHOLD, LOG_FILE);

    while (!terminate) {
        int16_t x, y, z;
        int rc = read_accel(&x, &y, &z);

        if (rc == 0) {
            float gx = (float)x / 4096.0f;
            float gy = (float)y / 4096.0f;
            float gz = (float)z / 4096.0f;
            float mag = sqrtf(gx * gx + gy * gy + gz * gz);

            if (mag > IMPACT_THRESHOLD) {
                log_impact(x, y, z, mag);
                printf("Impact: X=%d Y=%d Z=%d |g|=%.3f\n", x, y, z, mag);
            }
        } else if (rc < 0) {
            /* I2C error — keep running, but do not crash */
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* ---- Cleanup ---- */
    i2c_write_reg(CTRL_REG1, 0x00);  /* Standby */
    i2cClose(i2c_handle);
    gpioTerminate();

    printf("\nProgram terminated gracefully.\n");
    return EXIT_SUCCESS;
}

