#define OUT_Y_H        0x2B
#define OUT_Z_L        0x2C
#define OUT_Z_H        0x2D
#define SENSITIVITY    0.00875f
#define ALERT_THRESH   50.0f
#define CALIB_SAMPLES  100
#define SAMPLE_PERIOD  50000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int init_gyro(int fd)
{
    uint8_t who;
    if (i2c_read_reg8(fd, WHO_AM_I, &who) < 0)
        return -1;
    if (who != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who, WHO_AM_I_VAL);
        return -1;
    }
    if (i2c_write_reg8(fd, CTRL_REG1, 0x0F) < 0) return -1;
    if (i2c_write_reg8(fd, CTRL_REG4, 0x00) < 0) return -1;
    return 0;
}

static int calibrate_gyro(int fd, float *x_off, float *y_off, float *z_off)
{
    int32_t sx = 0, sy = 0, sz = 0;
    int16_t x, y, z;
    printf("Calibrating gyroscope (%d samples)...\n", CALIB_SAMPLES);
    for (int i = 0; i < CALIB_SAMPLES; i++) {
        if (i2c_read_reg16(fd, OUT_X_L, &x) < 0) return -1;
        if (i2c_read_reg16(fd, OUT_Y_L, &y) < 0) return -1;
        if (i2c_read_reg16(fd, OUT_Z_L, &z) < 0) return -1;
        sx += x; sy += y; sz += z;
        usleep(10000);
    }
    *x_off = (float)sx / CALIB_SAMPLES * SENSITIVITY;
    *y_off = (float)sy / CALIB_SAMPLES * SENSITIVITY;
    *z_off = (float)sz / CALIB_SAMPLES * SENSITIVITY;
    printf("Calibration complete: X=%.4f Y=%.4f Z=%.4f dps\n", *x_off, *y_off, *z_off);
    return 0;
}

static int read_gyro(int fd, float *x, float *y, float *z)
{
    int16_t rx, ry, rz;
    if (i2c_read_reg16(fd, OUT_X_L, &rx) < 0) return -1;
    if (i2c_read_reg16(fd, OUT_Y_L, &ry) < 0) return -1;
    if (i2c_read_reg16(fd, OUT_Z_L, &rz) < 0) return -1;
    *x = (float)rx * SENSITIVITY;
    *y = (float)ry * SENSITIVITY;
    *z = (float)rz * SENSITIVITY;
    return 0;
}

static void log_data(FILE *f, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
    fprintf(f, "%s,%.4f,%.4f,%.4f\n", ts, x, y, z);
    fflush(f);
}

static void check_alert(float x, float y, float z)
{
    if (fabsf(x) > ALERT_THRESH || fabsf(y) > ALERT_THRESH || fabsf(z) > ALERT_THRESH) {
        fprintf(stderr, "ALERT: angular velocity exceeds %.1f dps (X=%.2f Y=%.2f Z=%.2f)\n",
                ALERT_THRESH, x, y, z);
        time_t t = time(NULL);
        struct tm tm;
        localtime_r(&t, &tm);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", &tm);
        fprintf(g_log, "%s,ALERT,%.2f,%.2f,%.2f\n", ts, x, y, z);
        fflush(g_log);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return 1;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, GYRO_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return 1;
    }
    if (init_gyro(g_i2c_fd) < 0) {
        fprintf(stderr, "Gyroscope initialization failed.\n");
        close(g_i2c_fd);
        return 1;
    }

    float x_off = 0, y_off = 0, z_off = 0;
    if (calibrate_gyro(g_i2c_fd, &x_off, &y_off, &z_off) < 0) {
        fprintf(stderr, "Calibration failed.\n");
        close(g_i2c_fd);
        return 1;
    }

    g_log = fopen("gyro_log.txt", "a");
    if (!g_log) {
        perror("fopen gyro_log.txt");
        close(g_i2c_fd);
        return 1;
    }

    printf("Logging gyroscope data to gyro_log.txt at 20 Hz...\n");
    while (g_running) {
        float x, y, z;
        if (read_gyro(g_i2c_fd, &x, &y, &z) < 0) {
            fprintf(stderr, "Gyro read error; continuing.\n");
            usleep(SAMPLE_PERIOD);
            continue;
        }
        x -= x_off;
        y -= y_off;
        z -= z_off;
        log_data(g_log, x, y, z);
        check_alert(x, y, z);
        usleep(SAMPLE_PERIOD);
    }

    printf("\nShutting down cleanly.\n");
    if (g_log)   fclose(g_log);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

