#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

/* ADXL345 I2C address (ALT ADDRESS pin tied to GND) */
#define ADXL345_ADDR 0x53

/* ADXL345 register addresses */
#define ADXL345_REG_DEVID       0x00
#define ADXL345_REG_POWER_CTL   0x2D
#define ADXL345_REG_DATA_FORMAT 0x31
#define ADXL345_REG_DATAX0      0x32

/* Expected device ID for ADXL345 */
#define ADXL345_DEVID_EXPECTED  0xE5

/* Full-resolution, ±2 g range, 4-wire SPI interface (default) */
#define ADXL345_DATA_FORMAT_VAL 0x0B

/* Power control: measure mode */
#define ADXL345_POWER_CTL_MEASURE 0x08

/* LED GPIO pin (BCM numbering) */
#define LED_PIN 17

/* Sampling interval in microseconds (100 ms → 10 Hz) */
#define SAMPLE_INTERVAL_US 100000

/* Threshold in g */
#define ACCEL_THRESHOLD_G 2.0f

/* Full-resolution ±2 g range: 3.9 mg/LSB → 256 LSB/g */
#define SCALE_FACTOR 256.0f

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop exits cleanly               */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write one byte to an ADXL345 register; returns 0 on success, -1    */
/* on failure.                                                         */
/* ------------------------------------------------------------------ */
static int adxl345_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an ADXL345 register; returns 0 on success, -1   */
/* on failure.                                                         */
/* ------------------------------------------------------------------ */
static int adxl345_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read 6 bytes of acceleration data (little-endian).                 */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int adxl345_read_accel(int handle, int16_t *x, int16_t *y, int16_t *z)
{
    char buf[6];
    int  rc = i2cReadI2CBlockData(handle, ADXL345_REG_DATAX0, buf, 6);
    if (rc != 6) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData failed: %d\n", rc);
        return -1;
    }
    *x = (int16_t)(((uint8_t)buf[1] << 8) | (uint8_t)buf[0]);
    *y = (int16_t)(((uint8_t)buf[3] << 8) | (uint8_t)buf[2]);
    *z = (int16_t)(((uint8_t)buf[5] << 8) | (uint8_t)buf[4]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Verify device identity and configure ADXL345.                      */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;

    if (adxl345_read_reg(handle, ADXL345_REG_DEVID, &devid) != 0)
        return -1;

    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "[ERROR] Device ID mismatch: got 0x%02X, expected 0x%02X\n",
                devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }

    /* Standby first (clear measure bit) so configuration changes take effect */
    if (adxl345_write_reg(handle, ADXL345_REG_POWER_CTL, 0x00) != 0)
        return -1;

    /* Data format: full-resolution, ±2 g, right-justified, 4-wire SPI */
    if (adxl345_write_reg(handle, ADXL345_REG_DATA_FORMAT, ADXL345_DATA_FORMAT_VAL) != 0)
        return -1;

    /* Enter measurement mode */
    if (adxl345_write_reg(handle, ADXL345_REG_POWER_CTL, ADXL345_POWER_CTL_MEASURE) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample to the file.                                        */
/* ------------------------------------------------------------------ */
static void log_sample(FILE *fp, float x, float y, float z)
{
    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "[ERROR] localtime_r failed\n");
        return;
    }
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times.                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure LED is off before terminating pigpio */
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                               */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- I2C open --------------------------------------------------- */
    g_i2c_handle = i2cOpen(1, ADXL345_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                ADXL345_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- ADXL345 init ------------------------------------------------ */
    if (adxl345_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- LED GPIO --------------------------------------------------- */
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n", LED_PIN);
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    /* --- Log file --------------------------------------------------- */
    g_log_file = fopen("accel_log.txt", "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "[FATAL] Cannot open accel_log.txt for appending\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Signals ---------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "[WARN] sigaction failed — signals will not clean up\n");
    }

    printf("ADXL345 logging started. Press Ctrl+C to stop.\n");

    /* --- Main loop -------------------------------------------------- */
    while (g_running) {
        int16_t raw_x, raw_y, raw_z;

        if (adxl345_read_accel(g_i2c_handle, &raw_x, &raw_y, &raw_z) == 0) {
            float x = (float)raw_x / SCALE_FACTOR;
            float y = (float)raw_y / SCALE_FACTOR;
            float z = (float)raw_z / SCALE_FACTOR;

            log_sample(g_log_file, x, y, z);

            bool exceeded = (fabsf(x) > ACCEL_THRESHOLD_G ||
                             fabsf(y) > ACCEL_THRESHOLD_G ||
                             fabsf(z) > ACCEL_THRESHOLD_G);
            gpioWrite(LED_PIN, exceeded ? 1 : 0);
        } else {
