#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM303DLHC I2C addresses */
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR   0x1E

/* LSM303DLHC register addresses */
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A   0x28
#define CTRL_REG1_M 0x20
#define CTRL_REG2_M 0x21
#define CTRL_REG3_M 0x22
#define CTRL_REG4_M 0x23
#define OUT_X_H_M   0x03

/* Sensitivities */
#define ACCEL_SENSITIVITY 0.000244f  /* g/LSB for +/- 2g range */
#define MAG_SENSITIVITY   0.00014f   /* gauss/LSB for +/- 1.3 gauss range */

static int i2c_handle_accel = -1;
static int i2c_handle_mag   = -1;
static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

static int init_accelerometer(void) {
    /* Enable accelerometer: 50 Hz ODR, all axes enabled */
    if (i2cWriteByteData(i2c_handle_accel, CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Error writing to accelerometer CTRL_REG1_A\n");
        return -1;
    }
    /* Set full-scale range to +/- 2g */
    if (i2cWriteByteData(i2c_handle_accel, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Error writing to accelerometer CTRL_REG4_A\n");
        return -1;
    }
    return 0;
}

static int init_magnetometer(void) {
    /* Temp sensor enabled, medium performance */
    if (i2cWriteByteData(i2c_handle_mag, CTRL_REG1_M, 0x14) < 0) {
        fprintf(stderr, "Error writing to magnetometer CTRL_REG1_M\n");
        return -1;
    }
    /* Set full-scale to +/- 1.3 gauss */
    if (i2cWriteByteData(i2c_handle_mag, CTRL_REG2_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to magnetometer CTRL_REG2_M\n");
        return -1;
    }
    /* Continuous conversion mode */
    if (i2cWriteByteData(i2c_handle_mag, CTRL_REG1_M, 0x16) < 0) {
        fprintf(stderr, "Error writing to magnetometer CTRL_REG1_M (mode)\n");
        return -1;
    }
    /* Z-axis high performance */
    if (i2cWriteByteData(i2c_handle_mag, CTRL_REG4_M, 0x0C) < 0) {
        fprintf(stderr, "Error writing to magnetometer CTRL_REG4_M\n");
        return -1;
    }
    return 0;
}

static int read_accelerometer(float *ax, float *ay, float *az) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle_accel, OUT_X_L_A | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);
    *ax = raw_x * ACCEL_SENSITIVITY;
    *ay = raw_y * ACCEL_SENSITIVITY;
    *az = raw_z * ACCEL_SENSITIVITY;
    return 0;
}

static int read_magnetometer(float *mx, float *my, float *mz) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle_mag, OUT_X_H_M, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    int16_t raw_x = (int16_t)((buffer[0] << 8) | buffer[1]);
    int16_t raw_z = (int16_t)((buffer[2] << 8) | buffer[3]);
    int16_t raw_y = (int16_t)((buffer[4] << 8) | buffer[5]);
    *mx = raw_x * MAG_SENSITIVITY;
    *my = raw_y * MAG_SENSITIVITY;
    *mz = raw_z * MAG_SENSITIVITY;
    return 0;
}

static float calculate_heading(float ax, float ay, float az, float mx, float my, float mz) {
    float roll  = atan2f(ay, az);
    float pitch = atan2f(-ax, sqrtf(ay * ay + az * az));
    float cos_roll = cosf(roll);
    float sin_roll = sinf(roll);
    float cos_pitch = cosf(pitch);
    float sin_pitch = sinf(pitch);
    float xh = mx * cos_pitch + mz * sin_pitch;
    float yh = mx * sin_roll * sin_pitch + my * cos_roll - mz * sin_roll * cos_pitch;
    float heading = atan2f(yh, xh) * 180.0f / M_PI;
    if (heading < 0) heading += 360.0f;
    return heading;
}

static void log_data(float heading, float ax, float ay, float az, float mx, float my, float mz) {
    FILE *fp = fopen("compass_log.txt", "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec,
            heading, ax, ay, az, mx, my, mz);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle_accel = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Error opening I2C for accelerometer: %d\n", i2c_handle_accel);
        gpioTerminate();
        return 1;
    }

    i2c_handle_mag = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Error opening I2C for magnetometer: %d\n", i2c_handle_mag);
        i2cClose(i2c_handle_accel);
        gpioTerminate();
        return 1;
    }

    if (init_accelerometer() < 0 || init_magnetometer() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    FILE *fp = fopen("compass_log.txt", "r");
    if (!fp) {
        fp = fopen("compass_log.txt", "w");
        if (fp) {
            fprintf(fp, "Timestamp,Heading_deg,Accel_X_g,Accel_Y_g,Accel_Z_g,Mag_X_g,Mag_Y_g,Mag_Z_g\n");
            fclose(fp);
        }
    } else {
        fclose(fp);
    }

    while (!terminate) {
        float ax, ay, az, mx, my, mz;
        if (read_accelerometer(&ax, &ay, &az) == 0 && read_magnetometer(&mx, &my, &mz) == 0) {
            float heading = calculate_heading(ax, ay, az, mx, my, mz);
            log_data(heading, ax, ay, az, mx, my, mz);
        } else {
            fprintf(stderr, "Sensor read error, skipping sample\n");
        }
        gpioDelay(100000); /* 100 ms */
    }

    i2cClose(i2c_handle_accel);
    i2cClose(i2c_handle_mag);
    gpioTerminate();
    return 0;
}

