#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16488A register addresses (7-bit, MSB = 0 for read) */
#define ADIS16488A_REG_XGYRO_OUT  0x04
#define ADIS16488A_REG_YGYRO_OUT  0x06
#define ADIS16488A_REG_ZGYRO_OUT  0x08
#define ADIS16488A_REG_XACCEL_OUT 0x0A
#define ADIS16488A_REG_YACCEL_OUT 0x0C
#define ADIS16488A_REG_ZACCEL_OUT 0x0E

/* Sensitivities (from datasheet) */
#define GYRO_SENSITIVITY  0.005f   /* deg/sec/LSB */
#define ACCEL_SENSITIVITY 0.00025f /* g/LSB */

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000 /* 1 MHz */
#define SPI_MODE    3       /* CPOL=1, CPHA=1 */
#define STALL_US    40      /* Stall time between request and data */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register via SPI                                      */
/* Returns 0 on success (data in *out), -1 on error                    */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *out)
{
    char tx_cmd[2];
    char rx_cmd[2];
    char tx_data[2];
    char rx_data[2];
    int  ret;

    /* Build 16-bit command word: MSB=0 (read), bits[6:0]=reg */
    tx_cmd[0] = 0x00;
    tx_cmd[1] = (char)reg;

    /* Send read request */
    ret = spiXfer(spi_handle, tx_cmd, rx_cmd, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI read request failed for reg 0x%02X (ret=%d)\n",
                reg, ret);
        return -1;
    }

    /* Stall per datasheet */
    gpioDelay(STALL_US);

    /* Send dummy data to clock out the register contents */
    tx_data[0] = 0x00;
    tx_data[1] = 0x00;
    ret = spiXfer(spi_handle, tx_data, rx_data, 2);
    if (ret != 2) {
        fprintf(stderr, "SPI data transfer failed for reg 0x%02X (ret=%d)\n",
                reg, ret);
        return -1;
    }

    /* Data is big-endian */
    *out = (int16_t)(((uint8_t)rx_data[0] << 8) | (uint8_t)rx_data[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read all six axes                                                   */
/* ------------------------------------------------------------------ */
static int read_imu_data(int16_t *gx, int16_t *gy, int16_t *gz,
                         int16_t *ax, int16_t *ay, int16_t *az)
{
    if (read_register(ADIS16488A_REG_XGYRO_OUT, gx) != 0) return -1;
    if (read_register(ADIS16488A_REG_YGYRO_OUT, gy) != 0) return -1;
    if (read_register(ADIS16488A_REG_ZGYRO_OUT, gz) != 0) return -1;
    if (read_register(ADIS16488A_REG_XACCEL_OUT, ax) != 0) return -1;
    if (read_register(ADIS16488A_REG_YACCEL_OUT, ay) != 0) return -1;
    if (read_register(ADIS16488A_REG_ZACCEL_OUT, az) != 0) return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Convert raw to physical units                                       */
/* ------------------------------------------------------------------ */
static void convert_data(int16_t gx, int16_t gy, int16_t gz,
                         int16_t ax, int16_t ay, int16_t az,
                         float *gx_dps, float *gy_dps, float *gz_dps,
                         float *ax_g,  float *ay_g,  float *az_g)
{
    *gx_dps = (float)gx * GYRO_SENSITIVITY;
    *gy_dps = (float)gy * GYRO_SENSITIVITY;
    *gz_dps = (float)gz * GYRO_SENSITIVITY;
    *ax_g   = (float)ax * ACCEL_SENSITIVITY;
    *ay_g   = (float)ay * ACCEL_SENSITIVITY;
    *az_g   = (float)az * ACCEL_SENSITIVITY;
}

/* ------------------------------------------------------------------ */
/* Log one sample                                                      */
/* ------------------------------------------------------------------ */
static void log_data(float gx, float gy, float gz,
                     float ax, float ay, float az)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long ms = ts.tv_sec * 1000L + ts.tv_nsec / 1000000L;

    fprintf(fp, "%ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            ms, gx, gy, gz, ax, ay, az);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Non-blocking delay that checks the running flag                     */
/* ------------------------------------------------------------------ */
static void delay_ms(unsigned int ms)
{
    uint32_t start = gpioTick();
    while (running && (gpioTick() - start) < (uint32_t)(ms * 1000)) {
        gpioDelay(1000); /* 1 ms slices */
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI: channel 0, 1 MHz, mode 3 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open CSV file */
    fp = fopen("imu_data.csv", "w");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open imu_data.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write header */
    fprintf(fp, "timestamp,gyro_x,gyro_y,gyro_z,accel_x,accel_y,accel_z\n");
    fflush(fp);

    /* Register cleanup */
    atexit(cleanup);

    /* Signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADIS16488A logging started. Press Ctrl+C to stop.\n");

    /* Main loop */
    while (running) {
        int16_t gx, gy, gz, ax, ay, az;
        float gx_dps, gy_dps, gz_dps, ax_g, ay_g, az_g;

        if (read_imu_data(&gx, &gy, &gz, &ax, &ay, &az) == 0) {
            convert_data(gx, gy, gz, ax, ay, az,
                         &gx_dps, &gy_dps, &gz_dps,
                         &ax_g, &ay_g, &az_g);
            log_data(gx_dps, gy_dps, gz_dps, ax_g, ay_g, az_g);
        } else {
            fprintf(stderr, "Error reading IMU data, skipping sample\n");
        }

        delay_ms(100); /* 100 ms */
    }

    printf("\nShutting down...\n");
    return EXIT_SUCCESS;
}

