#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 3
#define SPI_BITS 8

#define ADIS16448_REG_GX_LSB 0x04
#define ADIS16448_REG_GY_LSB 0x06
#define ADIS16448_REG_GZ_LSB 0x08
#define ADIS16448_REG_AX_LSB 0x0A
#define ADIS16448_REG_AY_LSB 0x0C
#define ADIS16448_REG_AZ_LSB 0x0E

#define GYRO_SCALE 0.02f
#define ACCEL_SCALE 0.00025f

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int read_register(uint8_t reg, uint16_t *value) {
    uint8_t tx[2] = { (uint8_t)(reg | 0x80), 0x00 };
    uint8_t rx[2] = { 0 };

    if (spi_transfer(tx, rx, 2) < 0) {
        return -1;
    }

    *value = (uint16_t)((rx[0] << 8) | rx[1]);
    return 0;
}

static int read_imu_data(float *gx, float *gy, float *gz, float *ax, float *ay, float *az) {
    uint16_t raw_gx, raw_gy, raw_gz, raw_ax, raw_ay, raw_az;

    if (read_register(ADIS16448_REG_GX_LSB, &raw_gx) < 0) return -1;
    if (read_register(ADIS16448_REG_GY_LSB, &raw_gy) < 0) return -1;
    if (read_register(ADIS16448_REG_GZ_LSB, &raw_gz) < 0) return -1;
    if (read_register(ADIS16448_REG_AX_LSB, &raw_ax) < 0) return -1;
    if (read_register(ADIS16448_REG_AY_LSB, &raw_ay) < 0) return -1;
