    *gz = (float)((int16_t)raw_gz) * GYRO_SCALE;
    *ax = (float)((int16_t)raw_ax) * ACCEL_SCALE;
    *ay = (float)((int16_t)raw_ay) * ACCEL_SCALE;
    *az = (float)((int16_t)raw_az) * ACCEL_SCALE;

    return 0;
}

