    while (running) {
        float gx, gy, gz, ax, ay, az;

        if (read_imu_data(&gx, &gy, &gz, &ax, &ay, &az) < 0) {
            fprintf(stderr, "Error reading IMU data. Retrying...\n");
            usleep(100000);
            continue;
