        printf("Gyroscope: X=%.2f dps, Y=%.2f dps, Z=%.2f dps\n", gx, gy, gz);
        printf("Accelerometer: X=%.4f g, Y=%.4f g, Z=%.4f g\n", ax, ay, az);
        printf("----------------------------------------\n");

        usleep(100000);
    }

    printf("\nExiting gracefully...\n");
