/*
 * ADIS16448 IMU reader for Raspberry Pi 4 Model B
 * SPI channel 0 (CE0 / GPIO8), 1 MHz, SPI Mode 0
 * Reads gyro (X/Y/Z) and accel (X/Y/Z) every 100 ms.
 *
 * Build:  gcc -O2 -Wall -o adis16448 adis16448.c -lpigpio -lrt
 * Run:    sudo ./adis16448
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADIS16448 register map (subset) ---- */
#define ADIS16448_REG_XGYRO_OUT  0x04
#define ADIS16448_REG_YGYRO_OUT  0x06
#define ADIS16448_REG_ZGYRO_OUT  0x08
#define ADIS16448_REG_XACCEL_OUT 0x0A
#define ADIS16448_REG_YACCEL_OUT 0x0C
#define ADIS16448_REG_ZACCEL_OUT 0x0E

/* ---- Scaling factors (from datasheet) ---- */
#define GYRO_SCALE   0.05f    /* deg/sec per LSB */
#define ACCEL_SCALE  0.00025f /* g per LSB */

/* ---- SPI parameters ---- */
#define SPI_CHANNEL  0
#define SPI_SPEED    1000000  /* 1 MHz */
#define SPI_FLAGS    0        /* Mode 0, active-low CE */

/* ---- Timing ---- */
#define SAMPLE_PERIOD_US 100000  /* 100 ms */
#define STALL_DELAY_US   50      /* >= 40 us stall between reads */

/* ---- Globals for cleanup ---- */
static int spi_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read one 16-bit register using the two-cycle protocol.
 *   Cycle 1: send (reg | 0x8000) as 2 bytes.
 *   Cycle 2: send dummy 0x0000, clock out the 16-bit data.
 * Returns 0 on success, -1 on SPI transfer failure.
 */
static int read_register(uint16_t reg, int16_t *out)
{
    char tx1[2], rx1[2];
    char tx2[2], rx2[2];

    /* Cycle 1: send read command */
    tx1[0] = (reg >> 8) & 0xFF;
    tx1[1] = reg & 0xFF;
    if (spiXfer(spi_handle, tx1, rx1, 2) != 2) {
        fprintf(stderr, "SPI transfer failed during command phase (reg 0x%04X)\n", reg);
        return -1;
    }

    /* Stall >= 40 us */
    gpioDelay(STALL_DELAY_US);

    /* Cycle 2: clock out data */
    tx2[0] = 0x00;
    tx2[1] = 0x00;
    if (spiXfer(spi_handle, tx2, rx2, 2) != 2) {
        fprintf(stderr, "SPI transfer failed during data phase (reg 0x%04X)\n", reg);
        return -1;
    }

    *out = (int16_t)(((uint16_t)rx2[0] << 8) | (uint8_t)rx2[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
static int read_imu_data(float *gx, float *gy, float *gz,
                         float *ax, float *ay, float *az)
{
    int16_t raw;

    if (read_register(ADIS16448_REG_XGYRO_OUT,  &raw) != 0) return -1;
    *gx = (float)raw * GYRO_SCALE;

    if (read_register(ADIS16448_REG_YGYRO_OUT,  &raw) != 0) return -1;
    *gy = (float)raw * GYRO_SCALE;

    if (read_register(ADIS16448_REG_ZGYRO_OUT,  &raw) != 0) return -1;
    *gz = (float)raw * GYRO_SCALE;

    if (read_register(ADIS16448_REG_XACCEL_OUT, &raw) != 0) return -1;
    *ax = (float)raw * ACCEL_SCALE;

    if (read_register(ADIS16448_REG_YACCEL_OUT, &raw) != 0) return -1;
    *ay = (float)raw * ACCEL_SCALE;

    if (read_register(ADIS16448_REG_ZACCEL_OUT, &raw) != 0) return -1;
    *az = (float)raw * ACCEL_SCALE;

    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    float gx, gy, gz, ax, ay, az;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0, 1 MHz, Mode 0 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("ADIS16448 IMU reader started. Press Ctrl-C to stop.\n");
    printf("Gyro (deg/s): X=%8.3f Y=%8.3f Z=%8.3f  |  Accel (g): X=%8.4f Y=%8.4f Z=%8.4f\n",
           gx, gy, gz, ax, ay, az);

    /* Main sampling loop */
    while (!terminate) {
        if (read_imu_data(&gx, &gy, &gz, &ax, &ay, &az) == 0) {
            printf("Gyro (deg/s): X=%8.3f Y=%8.3f Z=%8.3f  |  Accel (g): X=%8.4f Y=%8.4f Z=%8.4f\n",
                   gx, gy, gz, ax, ay, az);
        } else {
            fprintf(stderr, "Error reading IMU data\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

