/* MPU-6886 I2C address (AD0 tied to GND) */
#define MPU6886_ADDR 0x68

/* MPU-6886 register addresses */
#define MPU6886_REG_SMPLRT_DIV   0x19
#define MPU6886_REG_CONFIG       0x1A
#define MPU6886_REG_GYRO_CONFIG  0x1B
#define MPU6886_REG_ACCEL_CONFIG 0x1C
#define MPU6886_REG_ACCEL_XOUT_H 0x3B
#define MPU6886_REG_GYRO_XOUT_H  0x43
#define MPU6886_REG_PWR_MGMT_1   0x6B
#define MPU6886_REG_WHO_AM_I     0x75

/* Expected WHO_AM_I value for MPU-6886 */
#define MPU6886_WHO_AM_I_VAL     0x68

/* I2C bus device path on Raspberry Pi 4 */
#define I2C_BUS_DEV "/dev/i2c-1"

/* Global file descriptor for I2C communication */
static int g_i2c_fd = -1;

/* Volatile flag for signal handling */
static volatile sig_atomic_t g_running = 1;

/* Signal handler for Ctrl+C */
static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an 8-bit register */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read a single byte from an 8-bit register */
static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, value, 1) != 1) {
        fprintf(stderr, "Error reading reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Read multiple bytes starting from a register */
static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error selecting reg 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "Error reading %zu bytes from reg 0x%02X: %s\n", len, reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* Initialize the MPU-6886 */
static int mpu6886_init(int fd) {
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (i2c_read_reg8(fd, MPU6886_REG_WHO_AM_I, &who_am_i) != 0) {
        return -1;
    }
    if (who_am_i != MPU6886_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, MPU6886_WHO_AM_I_VAL);
        return -1;
    }

    /* Wake up the MPU-6886 (clear SLEEP bit) */
    if (i2c_write_reg8(fd, MPU6886_REG_PWR_MGMT_1, 0x00) != 0) {
        return -1;
    }
    usleep(100000); /* 100 ms stabilization */

    /* Set sample rate divider to 7 (1 kHz / (1 + 7) = 125 Hz) */
    if (i2c_write_reg8(fd, MPU6886_REG_SMPLRT_DIV, 0x07) != 0) {
        return -1;
    }

    /* Set gyro full-scale range to +/- 250 degrees/sec (FS_SEL = 0) */
    if (i2c_write_reg8(fd, MPU6886_REG_GYRO_CONFIG, 0x00) != 0) {
        return -1;
    }

    /* Set accelerometer full-scale range to +/- 2g (AFS_SEL = 0) */
    if (i2c_write_reg8(fd, MPU6886_REG_ACCEL_CONFIG, 0x00) != 0) {
        return -1;
    }

    /* Configure DLPF (Digital Low Pass Filter) to 44 Hz bandwidth */
    if (i2c_write_reg8(fd, MPU6886_REG_CONFIG, 0x03) != 0) {
        return -1;
    }

    return 0;
}

/* Read raw 16-bit signed accelerometer data */
static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, MPU6886_REG_ACCEL_XOUT_H, buf, 6) != 0) {
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

/* Read raw 16-bit signed gyroscope data */
static int read_gyro(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];
    if (i2c_read_burst(fd, MPU6886_REG_GYRO_XOUT_H, buf, 6) != 0) {
        return -1;
    }
    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);
    return 0;
}

int main(void) {
    /* Register signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS_DEV, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus %s: %s\n", I2C_BUS_DEV, strerror(errno));
        return EXIT_FAILURE;
    }

    /* Acquire I2C slave address */
    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6886_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire I2C bus access to 0x%02X: %s\n", MPU6886_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6886 */
    if (mpu6886_init(g_i2c_fd) != 0) {
        fprintf(stderr, "MPU-6886 initialization failed.\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("MPU-6886 initialized. Reading data every 50 ms...\n");

    /* Main loop */
    while (g_running) {
        int16_t ax, ay, az, gx, gy, gz;
        bool read_ok = false;

        /* Retry transient I2C errors up to 3 times */
        for (int attempt = 0; attempt < 3 && g_running; attempt++) {
            if (read_accel(g_i2c_fd, &ax, &ay, &az) == 0 &&
                read_gyro(g_i2c_fd, &gx, &gy, &gz) == 0) {
                read_ok = true;
                break;
            }
            usleep(10000); /* 10 ms backoff before retry */
        }

        if (read_ok) {
            printf("Accel: X=%6d Y=%6d Z=%6d  Gyro: X=%6d Y=%6d Z=%6d\n",
                   ax, ay, az, gx, gy, gz);
        } else {
            fprintf(stderr, "Failed to read sensor data after 3 attempts.\n");
        }

        usleep(50000); /* 50 ms delay */
    }

    /* Clean shutdown */
    printf("\nExiting gracefully...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    return EXIT_SUCCESS;
}

