/*
 * ADXL345 Impact Detector for Raspberry Pi Zero W
 *
 * Wiring:
 *   ADXL345 SDA -> GPIO2 (I2C bus 1 SDA)
 *   ADXL345 SCL -> GPIO3 (I2C bus 1 SCL)
 *   ADXL345 VDD -> 3.3 V
 *   ADXL345 GND -> GND
 *   Red LED anode -> GPIO17 (BCM) via 330 ohm resistor
 *   Red LED cathode -> GND
 *
 * Build: gcc -O2 -Wall -o impact impact.c -lpigpio -lrt -lm
 * Run:   sudo ./impact
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADXL345 constants ---- */
#define ADXL345_ADDR          0x53
#define ADXL345_REG_DEVID     0x00
#define ADXL345_REG_POWER_CTL 0x2D
#define ADXL345_REG_DATA_FMT  0x31
#define ADXL345_REG_DATAX0    0x32
#define ADXL345_REG_BW_RATE   0x2C
#define ADXL345_DEVID_EXPECTED 0xE5

#define ADXL345_SCALE_2G      256.0f   /* LSB per g in full-resolution ±2 g mode */

/* ---- Application constants ---- */
#define I2C_BUS              1
#define LED_GPIO             17
#define THRESHOLD_G          2.5f
#define POLL_DELAY_US        10000     /* 10 ms */
#define LED_ON_TIME_US       500000    /* 500 ms */
#define LOG_FILE             "impact_log.txt"

/* ---- Globals for cleanup ---- */
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure LED is off before terminating pigpio */
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Write one byte to an ADXL345 register; returns 0 on success, -1 on error. */
static int adxl_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read one byte from an ADXL345 register; returns 0 on success, -1 on error. */
static int adxl_read_reg(int handle, uint8_t reg, uint8_t *out)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "[ERROR] i2cReadByteData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    *out = (uint8_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a block of bytes starting at reg; returns 0 on success, -1 on error. */
static int adxl_read_block(int handle, uint8_t reg, uint8_t *buf, uint8_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != len) {
        fprintf(stderr, "[ERROR] i2cReadI2CBlockData(reg=0x%02X, len=%u) returned %d\n",
                reg, len, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;

    /* Verify device identity */
    if (adxl_read_reg(handle, ADXL345_REG_DEVID, &devid) != 0)
        return -1;

    if (devid != ADXL345_DEVID_EXPECTED) {
        fprintf(stderr, "[ERROR] ADXL345 not detected (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID_EXPECTED);
        return -1;
    }

    /* Standby -> configure -> Measure */
    if (adxl_write_reg(handle, ADXL345_REG_POWER_CTL, 0x00) != 0)
        return -1;

    /* Full resolution, ±2 g range */
    if (adxl_write_reg(handle, ADXL345_REG_DATA_FMT, 0x0B) != 0)
        return -1;

    /* 100 Hz output data rate */
    if (adxl_write_reg(handle, ADXL345_REG_BW_RATE, 0x0A) != 0)
        return -1;

    /* Enter measurement mode */
    if (adxl_write_reg(handle, ADXL345_REG_POWER_CTL, 0x08) != 0)
        return -1;

    return 0;
}

/* ------------------------------------------------------------------ */
static int read_acceleration(int handle, float *x, float *y, float *z)
{
    uint8_t raw[6];

    if (adxl_read_block(handle, ADXL345_REG_DATAX0, raw, sizeof(raw)) != 0)
        return -1;

    int16_t x_raw = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t y_raw = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t z_raw = (int16_t)((raw[5] << 8) | raw[4]);

    *x = (float)x_raw / ADXL345_SCALE_2G;
    *y = (float)y_raw / ADXL345_SCALE_2G;
    *z = (float)z_raw / ADXL345_SCALE_2G;
    return 0;
}

/* ------------------------------------------------------------------ */
static float calculate_magnitude(float x, float y, float z)
{
    return sqrtf(x * x + y * y + z * z);
}

/* ------------------------------------------------------------------ */
static void log_impact(float x, float y, float z, float magnitude)
{
    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t == NULL) {
        strncpy(ts, "UNKNOWN", sizeof(ts));
        ts[sizeof(ts) - 1] = '\0';
    } else {
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    }

    fprintf(g_log_file, "%s - Impact: Mag=%.2f g, X=%.2f, Y=%.2f, Z=%.2f\n",
            ts, magnitude, x, y, z);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[ERROR] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure LED GPIO */
    if (gpioSetMode(LED_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[ERROR] gpioSetMode(%d, PI_OUTPUT) failed\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_GPIO, 0);

    /* Open I2C bus 1 at ADXL345 address */
    g_i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "[ERROR] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ADXL345_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (adxl345_init(g_i2c_handle) != 0) {
        fprintf(stderr, "[ERROR] ADXL345 initialisation failed (sensor absent or bus error)\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (g_log_file == NULL) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXL345 impact detector running. Threshold: %.1f g. Press Ctrl+C to exit.\n",
           THRESHOLD_G);

    /* Main polling loop */
    while (g_running) {
        float x, y, z;

        if (read_acceleration(g_i2c_handle, &x, &y, &z) != 0) {
            fprintf(stderr, "[WARN] I2C read error — continuing\n");
            gpioDelay(POLL_DELAY_US);
            continue;
        }

