/* Initialize I2C communication */
static int init_i2c(void) {
    i2c_handle = i2cOpen(I2C_BUS, MMA8451Q_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", I2C_BUS, MMA8451Q_ADDR, i2c_handle);
