    if (i2cWriteByteData(i2c_handle, CTRL_REG2, 0x00) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG2\n");
        return -1;
    }

    /* Enable auto-increment for multi-byte reads */
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x01) < 0) {
