    int bytes_read = i2cReadI2CBlockData(i2c_handle, OUT_X_MSB, buffer, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading acceleration data: %d\n", bytes_read);
        return -1;
    }

    /* Combine MSB and LSB, sign-extend 12-bit to 16-bit */
    int16_t raw_x = (int16_t)(((uint16_t)buffer[0] << 8) | (uint8_t)buffer[1]) >> 4;
    int16_t raw_y = (int16_t)(((uint16_t)buffer[2] << 8) | (uint8_t)buffer[3]) >> 4;
    int16_t raw_z = (int16_t)(((uint16_t)buffer[4] << 8) | (uint8_t)buffer[5]) >> 4;

