    if (init_mma8451q() != 0) {
        cleanup();
        return 1;
    }

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    /* Set up signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float x, y, z;

    /* Main loop */
    while (!terminate) {
        if (read_acceleration(&x, &y, &z) == 0) {
            if (is_impact(x, y, z)) {
                gpioWrite(LED_GPIO, 1);
                log_impact(x, y, z);
                gpioDelay(LED_ON_TIME_US);
                gpioWrite(LED_GPIO, 0);
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data. Retrying...\n");
        }
        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    cleanup();
    return 0;
}

