        fprintf(stderr, "fprintf to CSV failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int ensure_csv_header(FILE *fp) {
    long pos = ftell(fp);
    if (pos < 0) {
        fprintf(stderr, "ftell failed: %s\n", strerror(errno));
        return -1;
    }
    if (pos == 0) {
        if (fprintf(fp, "Timestamp,X,Y,Z\n") < 0) {
            fprintf(stderr, "Failed to write CSV header: %s\n", strerror(errno));
            return -1;
        }
        if (fflush(fp) != 0) {
            fprintf(stderr, "fflush header failed: %s\n", strerror(errno));
            return -1;
        }
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, TMAG5273_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n", TMAG5273_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    /* Basic device configuration: enable X, Y, Z channels, set default range */
    if (i2c_write_reg8(g_i2c_fd, REG_DEVICE_CONFIG, 0x03) < 0) {
        fprintf(stderr, "Failed to configure TMAG5273\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    g_csv = fopen(CSV_FILE, "a");
    if (g_csv == NULL) {
        fprintf(stderr, "Failed to open %s: %s\n", CSV_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    if (ensure_csv_header(g_csv) < 0) {
        fclose(g_csv);
        g_csv = NULL;
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return 1;
    }

    printf("TMAG5273 logging started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int16_t x, y, z;

        if (read_magnetic_data(g_i2c_fd, &x, &y, &z) == 0) {
            if (log_data(g_csv, x, y, z) < 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }
        } else {
            fprintf(stderr, "Sensor read failed; continuing.\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    printf("\nShutting down cleanly...\n");

    if (g_csv != NULL) {
        fclose(g_csv);
        g_csv = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }

    return 0;
}

