/*
 * ADXL345 Free-Fall Logger for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADXL345 SDA  -> GPIO2  (physical pin 3, I2C bus 1)
 *   ADXL345 SCL  -> GPIO3  (physical pin 5, I2C bus 1)
 *   ADXL345 VCC  -> 3.3 V
 *   ADXL345 GND  -> GND
 *   ADXL345 INT1 -> GPIO17 (physical pin 11, BCM 17)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o freefall_log freefall_log.c -lgpiod
 *
 * Requires libgpiod v1.x (libgpiod-dev package on Raspberry Pi OS).
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>
#include <gpiod.h>

/* ---- ADXL345 register definitions ---- */
#define ADXL345_ADDRESS          0x53
#define ADXL345_REG_DEVID        0x00
#define ADXL345_REG_THRESH_FF    0x28
#define ADXL345_REG_TIME_FF      0x29
#define ADXL345_REG_DATA_FORMAT  0x31
#define ADXL345_REG_POWER_CTL    0x2D
#define ADXL345_REG_INT_ENABLE   0x2E
#define ADXL345_REG_INT_MAP      0x2F
#define ADXL345_REG_INT_SOURCE   0x30
#define ADXL345_REG_DATAX0       0x32
#define ADXL345_REG_FIFO_CTL     0x38

#define ADXL345_DEVID            0xE5
#define ADXL345_POWER_CTL_MEASURE 0x08
#define ADXL345_INT_ENABLE_FF    0x04
#define ADXL345_INT_MAP_FF       0x04

#define I2C_BUS                 "/dev/i2c-1"
#define GPIO_CHIP               "gpiochip4"   /* BCM GPIO controller on Pi 4 */
#define GPIO_LINE               17            /* BCM 17 = physical pin 11 */
#define LOG_FILE                "freefall_log.csv"
#define SAMPLE_PERIOD_MS        100

static volatile sig_atomic_t g_running = 1;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_burst(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C burst write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C burst read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

/* ---- ADXL345 driver ---- */
struct adxl345 {
    int fd;
    struct gpiod_line *int_line;
};

static int adxl345_init(struct adxl345 *dev)
{
    dev->fd = open(I2C_BUS, O_RDWR);
    if (dev->fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(dev->fd, I2C_SLAVE, ADXL345_ADDRESS) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                ADXL345_ADDRESS, strerror(errno));
        close(dev->fd);
        dev->fd = -1;
        return -1;
    }

    /* Verify device identity */
    uint8_t devid = 0;
    if (i2c_read_reg8(dev->fd, ADXL345_REG_DEVID, &devid) < 0) {
        close(dev->fd);
        dev->fd = -1;
        return -1;
    }
    if (devid != ADXL345_DEVID) {
        fprintf(stderr, "ADXL345 not found (DEVID=0x%02X, expected 0x%02X)\n",
                devid, ADXL345_DEVID);
        close(dev->fd);
        dev->fd = -1;
        return -1;
    }

    /* Enter standby so configuration writes take effect */
    if (i2c_write_reg8(dev->fd, ADXL345_REG_POWER_CTL, 0x00) < 0) {
        close(dev->fd);
        dev->fd = -1;
        return -1;
    }

    /* Configure data format: full resolution, +/-200 g range */
    if (i2c_write_reg8(dev->fd, ADXL345_REG_DATA_FORMAT, 0x0B) < 0) {
        close(dev->fd);
        dev->fd = -1;
        return -1;
    }

    /* Free-fall threshold: 10 g (0x0A) */
    if (i2c_write_reg8(dev->fd, ADXL345_REG_THRESH_FF, 0x0A) < 0) {
        close(dev->fd);
        dev->fd = -1;
        return -1;
    }

    /* Free-fall time: 100 ms (0x64) */
    if (i2c_write_reg8(dev->fd, ADXL345_REG_TIME_FF, 0x64) < 0) {
        close(dev->fd);
        dev->fd = -1;
        return -1;
    }

    /* Map free-fall interrupt to INT1 */
    if (i2c_write_reg8(dev->fd, ADXL345_REG_INT_MAP, ADXL345_INT_MAP_FF) < 0) {
        close(dev->fd);
        dev->fd = -1;
        return -1;
    }

    /* Enable free-fall interrupt */
    if (i2c_write_reg8(dev->fd, ADXL345_REG_INT_ENABLE, ADXL345_INT_ENABLE_FF) < 0) {
        close(dev->fd);
        dev->fd = -1;
        return -1;
    }

    /* Enter measurement mode */
    if (i2c_write_reg8(dev->fd, ADXL345_REG_POWER_CTL, ADXL345_POWER_CTL_MEASURE) < 0) {
        close(dev->fd);
        dev->fd = -1;
        return -1;
    }

    return 0;
}

static void adxl345_disable(struct adxl345 *dev)
{
    if (dev->fd >= 0) {
        (void)i2c_write_reg8(dev->fd, ADXL345_REG_POWER_CTL, 0x00);
        (void)i2c_write_reg8(dev->fd, ADXL345_REG_INT_ENABLE, 0x00);
        close(dev->fd);
        dev->fd = -1;
    }
}

/* ---- GPIO interrupt setup via libgpiod ---- */
static int gpio_init(struct adxl345 *dev)
{
    struct gpiod_chip *chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        return -1;
    }

    struct gpiod_line *line = gpiod_chip_get_line(chip, GPIO_LINE);
    if (!line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n", GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    /* Request rising-edge events on INT1 */
    if (gpiod_line_request_rising_edge_events(line, "adxl345-freefall") < 0) {
        fprintf(stderr, "Cannot request rising-edge events on GPIO %d: %s\n",
                GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    dev->int_line = line;
    return 0;
}

static void gpio_release(struct adxl345 *dev)
{
    if (dev->int_line) {
        gpiod_line_release(dev->int_line);
        dev->int_line = NULL;
    }
}

/* ---- Logging ---- */
static int log_open(FILE **fp)
{
    *fp = fopen(LOG_FILE, "a");
    if (!*fp) {
        fprintf(stderr, "Cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    /* Write header only if file is empty */
    long pos = ftell(*fp);
    if (pos == 0) {
        fprintf(*fp, "Timestamp,X,Y,Z\n");
        fflush(*fp);
    }
    return 0;
}

static void log_sample(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(fp, "%s.%03ld,%d,%d,%d\n", tbuf, ts.tv_nsec / 1000000, x, y, z);
    fflush(fp);
}

/* ---- Main ---- */
int main(void)
{
    struct adxl345 dev = { .fd = -1, .int_line = NULL };
    FILE *log_fp = NULL;
    int ret = EXIT_FAILURE;

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (adxl345_init(&dev) < 0) {
        fprintf(stderr, "ADXL345 initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Initialize GPIO */
    if (gpio_init(&dev) < 0) {
        fprintf(stderr, "GPIO initialization failed.\n");
        adxl345_disable(&dev);
        return EXIT_FAILURE;
    }

    /* Open log file */
    if (log_open(&log_fp) < 0) {
        fprintf(stderr, "Log file initialization failed.\n");
        gpio_release(&dev);
        adxl345_disable(&dev);
        return EXIT_FAILURE;
    }

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    /* Main event loop */
    while (g_running) {
        /* Block up to 1 s waiting for a rising edge on INT1 */
        int rv = gpiod_line_event_wait(dev.int_line, &(struct timespec){1, 0});
        if (rv < 0) {
            if (errno == EINTR) continue;
            fprintf(stderr, "GPIO event wait error: %s\n", strerror(errno));
            break;
        }
        if (rv == 0) continue; /* timeout, no event */

        /* Drain any pending events */
        while (gpiod_line_event_read(dev.int_line, NULL) == 0) {
            /* discard */
        }

        /* Read interrupt source to confirm free-fall */
        uint8_t int_src = 0;
        if (i2c_read_reg8(dev.fd, ADXL345_REG_INT_SOURCE, &int_src) < 0) {
            continue;
        }
        if ((int_src & ADXL345_INT_SOURCE_FF) == 0) {
            continue;
        }

        /* Read acceleration data (6 bytes starting at DATAX0) */
        uint8_t data[6];
        if (i2c_read_burst(dev.fd, ADXL345_REG_DATAX0, data, 6) < 0) {
            continue;
        }

        int16_t x = (int16_t)((data[1] << 8) | data[0]);
        int16_t y = (int16_t)((data[3] << 8) | data[2]);
        int16_t z = (int16_t)((data[5] << 8) | data[4]);

        log_sample(log_fp, x, y, z);
        printf("Free-fall detected: X=%d Y=%d Z=%d\n", x, y, z);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpio_release(&dev);
    adxl345_disable(&dev);
    if (log_fp) fclose(log_fp);

    return EXIT_SUCCESS;
}

