#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C address (SA0 tied to GND) */
#define LSM6DSR_ADDR 0x6B

/* LSM6DSR register addresses */
#define WHO_AM_I       0x0F
#define CTRL1_XL       0x10
#define CTRL2_G        0x11
#define OUTX_L_G       0x22
#define OUTX_H_G       0x23
#define OUTY_L_G       0x24
#define OUTY_H_G       0x25
#define OUTZ_L_G       0x26
#define OUTZ_H_G       0x27
#define OUTX_L_XL      0x28
#define OUTX_H_XL      0x29
#define OUTY_L_XL      0x2A
#define OUTY_H_XL      0x2B
#define OUTZ_L_XL      0x2C
#define OUTZ_H_XL      0x2D

/* Expected WHO_AM_I value for LSM6DSR */
#define LSM6DSR_WHO_AM_I 0x6A

/* CTRL1_XL: ODR_XL=104Hz (0b1000), FS_XL=±2g (0b00) -> 0x80 */
#define CTRL1_XL_VAL 0x80
/* CTRL2_G: ODR_G=104Hz (0b1000), FS_G=±250dps (0b00) -> 0x80 */
#define CTRL2_G_VAL  0x80

/* Fall detection thresholds */
#define FALL_ACCEL_THRESHOLD 0.2f  /* g */
#define IMPACT_ACCEL_THRESHOLD 2.5f /* g */
#define IMPACT_TIME_WINDOW 1.0     /* seconds */

/* Scaling factors for ±2g accel and ±250dps gyro */
#define ACCEL_SCALE 0.061f  /* mg/LSB -> g/LSB */
#define GYRO_SCALE  8.75f   /* mdps/LSB -> dps/LSB */

/* Global variables */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* Structure to hold sensor data */
typedef struct {
    float accel_x, accel_y, accel_z;
    float gyro_x, gyro_y, gyro_z;
} sensor_data_t;

/* Function prototypes */
static int init_lsm6dsr(void);
static int read_sensor_data(sensor_data_t *data);
static void log_data(const sensor_data_t *data);
static void signal_handler(int signal);
static void cleanup(void);
static void detect_fall(const sensor_data_t *data);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* Initialize the LSM6DSR sensor */
static int init_lsm6dsr(void) {
    /* Verify sensor identity */
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != LSM6DSR_WHO_AM_I) {
        fprintf(stderr, "WHO_AM_I mismatch: expected 0x%02X, got 0x%02X\n",
                LSM6DSR_WHO_AM_I, who_am_i);
        return -1;
    }

    /* Configure accelerometer: ±2g, 104 Hz */
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, CTRL1_XL_VAL) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    /* Configure gyroscope: ±250 dps, 104 Hz */
    if (i2cWriteByteData(i2c_handle, CTRL2_G, CTRL2_G_VAL) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

/* Read accelerometer and gyroscope data from the LSM6DSR */
static int read_sensor_data(sensor_data_t *data) {
    char buffer[12];
    int16_t raw_xl, raw_yl, raw_zl, raw_xg, raw_yg, raw_zg;

    /* Read 12 bytes of accelerometer and gyroscope data (6 bytes each) */
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12) != 12) {
        fprintf(stderr, "Error reading sensor data block\n");
        return -1;
    }

    /* Combine high and low bytes for gyroscope (little-endian) */
    raw_xg = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_yg = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_zg = (int16_t)((buffer[5] << 8) | buffer[4]);

    /* Combine high and low bytes for accelerometer (little-endian) */
    raw_xl = (int16_t)((buffer[7] << 8) | buffer[6]);
    raw_yl = (int16_t)((buffer[9] << 8) | buffer[8]);
    raw_zl = (int16_t)((buffer[11] << 8) | buffer[10]);

    /* Convert raw data to g and dps */
    data->accel_x = (float)raw_xl * ACCEL_SCALE;
    data->accel_y = (float)raw_yl * ACCEL_SCALE;
    data->accel_z = (float)raw_zl * ACCEL_SCALE;
    data->gyro_x  = (float)raw_xg * GYRO_SCALE;
    data->gyro_y  = (float)raw_yg * GYRO_SCALE;
    data->gyro_z  = (float)raw_zg * GYRO_SCALE;

    return 0;
}

/* Log sensor data to a CSV file */
static void log_data(const sensor_data_t *data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;

    fprintf(log_file, "%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            timestamp,
            data->accel_x, data->accel_y, data->accel_z,
            data->gyro_x, data->gyro_y, data->gyro_z);
    fflush(log_file);
}

/* Detect a fall based on acceleration magnitude */
static void detect_fall(const sensor_data_t *data) {
    static double impact_start_time = 0.0;
    static bool impact_detected = false;
    static enum { IDLE, FREEFALL, IMPACT } fall_state = IDLE;
    struct timespec ts;
    double current_time;

    clock_gettime(CLOCK_REALTIME, &ts);
    current_time = (double)ts.tv_sec + (double)ts.tv_nsec / 1e9;

    float accel_magnitude = sqrtf(data->accel_x * data->accel_x +
                                  data->accel_y * data->accel_y +
                                  data->accel_z * data->accel_z);

    switch (fall_state) {
        case IDLE:
            if (accel_magnitude < FALL_ACCEL_THRESHOLD) {
                fall_state = FREEFALL;
                impact_detected = false;
                printf("Freefall detected!\n");
            }
            break;

        case FREEFALL:
            if (accel_magnitude > IMPACT_ACCEL_THRESHOLD) {
                impact_start_time = current_time;
                impact_detected = true;
            } else if (impact_detected &&
                       (current_time - impact_start_time) > IMPACT_TIME_WINDOW) {
                fall_state = IDLE;
                impact_detected = false;
            }
            break;

        case IMPACT:
            if (accel_magnitude < FALL_ACCEL_THRESHOLD) {
                fall_state = FREEFALL;
                impact_detected = false;
                printf("Freefall detected!\n");
            } else {
                fall_state = IDLE;
                impact_detected = false;
            }
            break;
    }
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 */
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the LSM6DSR sensor */
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "LSM6DSR initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open the log file */
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if the file is newly created */
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");
        fflush(log_file);
    }

    /* Set up signal handling for Ctrl+C and termination */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    sensor_data_t sensor_data;

    /* Main loop */
    while (program_running) {
        /* Read sensor data */
        if (read_sensor_data(&sensor_data) == 0) {
            /* Log the data */
            log_data(&sensor_data);

            /* Detect a fall */
            detect_fall(&sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        /* Delay for 10 ms (100 Hz sampling rate) */
        gpioDelay(10000);
    }

    /* Clean up and exit */
    cleanup();
    return EXIT_SUCCESS;
}

