/*
 * ADIS16266 Gyroscope Logger for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   ADIS16266 CS  -> GPIO8  (SPI0 CE0, BCM 8)
 *   ADIS16266 SCLK-> GPIO11 (SPI0 SCLK, BCM 11)
 *   ADIS16266 DOUT-> GPIO9  (SPI0 MISO, BCM 9)
 *   ADIS16266 DIN -> GPIO10 (SPI0 MOSI, BCM 10)
 *   ADIS16266 VDD -> 3.3 V
 *   ADIS16266 GND -> GND
 *
 * SPI: channel 0, mode 3 (CPOL=1, CPHA=1), 1 MHz, 2-byte transfers.
 *
 * Build: gcc -O2 -Wall -o gyro_log gyro_log.c -lpigpio -lrt
 * Run:   sudo ./gyro_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADIS16266 register definitions ---- */
#define ADIS16266_REG_GLOB_CMD  0x02
#define ADIS16266_REG_XGYRO_OUT 0x04
#define ADIS16266_REG_YGYRO_OUT 0x06
#define ADIS16266_REG_ZGYRO_OUT 0x08
#define ADIS16266_REG_SMPL_PRD  0x36
#define ADIS16266_REG_SENS_AVG  0x38
#define ADIS16266_REG_DIAG_STAT 0x3A
#define ADIS16266_REG_WHO_AM_I  0x56

#define ADIS16266_WHO_AM_I_VAL  0x06

/* ---- SPI / pigpio configuration ---- */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000          /* 1 MHz */
#define SPI_FLAGS   0x0003           /* mode 3: CPOL=1, CPHA=1 */

/* ---- Sampling ---- */
#define SAMPLE_PERIOD_US 10000       /* 10 ms */

/* ---- Scale factor (deg/sec/LSB) ---- */
#define GYRO_SCALE_FACTOR 0.0305f

/* ---- Globals for cleanup ---- */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16266                           */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int adis16266_read_register(uint8_t reg, int16_t *value)
{
    char tx[2];
    char rx[2];

    /* Bit 7 = 1 -> read command */
    tx[0] = (char)(reg | 0x80);
    tx[1] = 0x00;

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read transfer failed for register 0x%02X\n", reg);
        return -1;
    }

    /* Data is returned MSB-first in the next clock cycle */
    *value = (int16_t)(((uint8_t)rx[0] << 8) | (uint8_t)rx[1]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit value to an ADIS16266 register                       */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int adis16266_write_register(uint8_t reg, uint16_t value)
{
    char tx[2];
    char rx[2];

    /* Bit 7 = 0 -> write command */
    tx[0] = (char)(reg & 0x7F);
    tx[1] = (char)(value & 0xFF);

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI write transfer failed for register 0x%02X\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Verify device identity                                              */
/* ------------------------------------------------------------------ */
static int adis16266_verify(void)
{
    int16_t who_am_i = 0;

    if (adis16266_read_register(ADIS16266_REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }

    if ((who_am_i & 0x0F) != ADIS16266_WHO_AM_I_VAL) {
        fprintf(stderr,
                "WHO_AM_I mismatch: got 0x%04X, expected 0x%04X\n",
                (unsigned)(who_am_i & 0x0F),
                ADIS16266_WHO_AM_I_VAL);
        return -1;
    }

    printf("ADIS16266 verified (WHO_AM_I = 0x%04X)\n",
           (unsigned)(who_am_i & 0x0F));
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the ADIS16266                                            */
/* ------------------------------------------------------------------ */
static int adis16266_init(void)
{
    /*
     * Reset the device by writing 0x0000 to GLOB_CMD.
     * A short delay lets the reset complete before further config.
     */
    if (adis16266_write_register(ADIS16266_REG_GLOB_CMD, 0x0000) != 0) {
        fprintf(stderr, "Failed to reset ADIS16266\n");
        return -1;
    }
    gpioDelay(100000);  /* 100 ms */

    /*
     * Configure sample period: 1000 SPS (0x03E8)
     * SMPL_PRD = 0x03E8 / 256 = 15.23 SPS
     */
    if (adis16266_write_register(ADIS16266_REG_SMPL_PRD, 0x03E8) != 0) {
        fprintf(stderr, "Failed to set sample period\n");
        return -1;
    }

    /*
     * Configure sensor averaging: 8 samples (0x0008)
     */
    if (adis16266_write_register(ADIS16266_REG_SENS_AVG, 0x0008) != 0) {
        fprintf(stderr, "Failed to set sensor averaging\n");
        return -1;
    }

    /*
     * Clear any stale diagnostic status.
     */
    int16_t diag = 0;
    if (adis16266_read_register(ADIS16266_REG_DIAG_STAT, &diag) == 0) {
        (void)adis16266_write_register(ADIS16266_REG_DIAG_STAT, (uint16_t)diag);
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read angular rate (degrees/sec) for a given axis                    */
/* ------------------------------------------------------------------ */
static int adis16266_read_angular_rate(uint8_t reg, float *rate)
{
    int16_t raw = 0;

    if (adis16266_read_register(reg, &raw) != 0) {
        return -1;
    }

    *rate = (float)raw * GYRO_SCALE_FACTOR;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped gyroscope reading to the CSV log               */
/* ------------------------------------------------------------------ */
static void log_data(float x_rate, float y_rate, float z_rate)
{
    struct timespec ts;
    struct tm tm_info;
    char timestamp[32];

    clock_gettime(CLOCK_REALTIME, &ts);
    localtime_r(&ts.tv_sec, &tm_info);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(log_file, "%s.%03ld,%.4f,%.4f,%.4f\n",
            timestamp, ts.tv_nsec / 1000000, x_rate, y_rate, z_rate);
    fflush(log_file);
}

/* ------------------------------------------------------------------ */
/* Cleanup resources                                                   */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    float x_rate, y_rate, z_rate;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0, mode 3, 1 MHz */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (channel %d, %d Hz): %d\n",
                SPI_CHANNEL, SPI_SPEED, spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Verify device identity */
    if (adis16266_verify() != 0) {
        fprintf(stderr, "ADIS16266 not detected or not responding\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Initialize the gyroscope */
    if (adis16266_init() != 0) {
        fprintf(stderr, "ADIS16266 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file once */
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        perror("Failed to open gyro_log.csv");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X_Rate,Y_Rate,Z_Rate\n");
        fflush(log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Logging gyroscope data to gyro_log.csv (Ctrl+C to stop)...\n");

    /* Main sampling loop */
    while (!terminate) {
        if (adis16266_read_angular_rate(ADIS16266_REG_XGYRO_OUT, &x_rate) != 0 ||
            adis16266_read_angular_rate(ADIS16266_REG_YGYRO_OUT, &y_rate) != 0 ||
            adis16266_read_angular_rate(ADIS16266_REG_ZGYRO_OUT, &z_rate) != 0) {
            fprintf(stderr, "Error reading gyroscope data, retrying...\n");
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        log_data(x_rate, y_rate, z_rate);
        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

