#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

/* L3G4200D I2C address (SA0 tied to VDD) */
#define L3G4200D_ADDR 0x69

/* L3G4200D register addresses */
#define L3G4200D_WHO_AM_I 0x0F
#define L3G4200D_CTRL_REG1 0x20
#define L3G4200D_CTRL_REG4 0x23
#define L3G4200D_OUT_X_L 0x28

/* Expected WHO_AM_I value */
#define L3G4200D_WHO_AM_I_VAL 0xD3

/* Sensitivity: 8.75 mdps/LSB => 1/114.285 deg/s/LSB */
#define L3G4200D_SENSITIVITY 114.285f

/* CTRL_REG1: ODR=100Hz (0x77), all axes enabled */
#define CTRL_REG1_VAL 0x77

/* CTRL_REG4: full-scale 250 dps (0x00), block data update enabled */
#define CTRL_REG4_VAL 0x00

/* Sampling interval in microseconds */
#define SAMPLE_INTERVAL_US 10000

/* Global resources for signal handler */
static int i2c_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    terminate = 1;
}

/* Write a byte to a register with retry */
static int write_register(int handle, uint8_t reg, uint8_t value) {
    int retries = 3;
    int result;
    while (retries > 0) {
        result = i2cWriteByteData(handle, reg, value);
        if (result == 0) {
            return 0;
        }
        fprintf(stderr, "I2C write error (reg 0x%02X, val 0x%02X): %s. Retrying...\n",
                reg, value, strerror(errno));
        gpioDelay(1000);
        retries--;
    }
    fprintf(stderr, "I2C write failed after retries (reg 0x%02X, val 0x%02X).\n", reg, value);
    return -1;
}

/* Read a block of bytes from a register */
static int read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len) {
    int result = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (result != (int)len) {
        fprintf(stderr, "I2C block read error (reg 0x%02X, len %u): got %d, %s\n",
                reg, len, result, strerror(errno));
        return -1;
    }
    return 0;
}

/* Initialize the L3G4200D gyroscope */
static int init_gyro(int handle) {
    uint8_t who_am_i;

    /* Verify sensor identity */
    if (read_block(handle, L3G4200D_WHO_AM_I, &who_am_i, 1) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != L3G4200D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who_am_i, L3G4200D_WHO_AM_I_VAL);
        return -1;
    }

    /* Configure CTRL_REG1: ODR=100Hz, all axes enabled */
    if (write_register(handle, L3G4200D_CTRL_REG1, CTRL_REG1_VAL) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG1.\n");
        return -1;
    }

    /* Configure CTRL_REG4: full-scale 250 dps, block data update */
    if (write_register(handle, L3G4200D_CTRL_REG4, CTRL_REG4_VAL) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG4.\n");
        return -1;
    }

    return 0;
}

/* Read raw angular velocity data from the gyroscope */
static int read_gyro_data(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buf[6];

    if (read_block(handle, L3G4200D_OUT_X_L | 0x80, buf, 6) != 0) {
        return -1;
    }

    *x = (int16_t)((buf[1] << 8) | buf[0]);
    *y = (int16_t)((buf[3] << 8) | buf[2]);
    *z = (int16_t)((buf[5] << 8) | buf[4]);

    return 0;
}

/* Convert raw data to degrees per second */
static void convert_data(int16_t x, int16_t y, int16_t z, float *x_dps, float *y_dps, float *z_dps) {
    *x_dps = (float)x / L3G4200D_SENSITIVITY;
    *y_dps = (float)y / L3G4200D_SENSITIVITY;
    *z_dps = (float)z / L3G4200D_SENSITIVITY;
}

/* Log data to a CSV file */
static void log_data(FILE *fp, float x_dps, float y_dps, float z_dps) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(fp, "%ld.%09ld,%.6f,%.6f,%.6f\n",
            (long)ts.tv_sec, ts.tv_nsec, x_dps, y_dps, z_dps);
    fflush(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 */
    i2c_handle = i2cOpen(1, L3G4200D_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %s\n",
                L3G4200D_ADDR, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the gyroscope */
    if (init_gyro(i2c_handle) != 0) {
        fprintf(stderr, "Gyroscope initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

