#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_GPIO 17
#define LOG_FILE_NAME     "flame_events.log"
#define POLL_INTERVAL_US  500000  /* 500 ms */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly.            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped flame event line to the log file and flush.     */
/* Returns 0 on success, -1 on failure.                               */
/* ------------------------------------------------------------------ */
static int log_flame_event(int flame_detected)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S",
                 &timeinfo) == 0) {
        fprintf(stderr, "strftime failed\n");
        return -1;
    }

    if (fprintf(g_log_file, "%s – Flame detected: %s\n",
                timestamp, flame_detected ? "YES" : "NO") < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(g_log_file) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int ret;

    /* --- Initialize pigpio ------------------------------------------ */
    ret = gpioInitialise();
    if (ret < 0) {
        fprintf(stderr, "pigpio initialisation failed (code %d)\n", ret);
        return EXIT_FAILURE;
    }

    /* --- Open log file in append mode -------------------------------- */
    g_log_file = fopen(LOG_FILE_NAME, "a");
    if (g_log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE_NAME, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO17 as input with internal pull-up ------------ */
    ret = gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    if (ret != 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d (code %d)\n",
                FLAME_SENSOR_GPIO, ret);
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    ret = gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP);
    if (ret != 0) {
        fprintf(stderr, "gpioSetPullUpDown failed for GPIO %d (code %d)\n",
                FLAME_SENSOR_GPIO, ret);
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install SIGINT handler for graceful shutdown ---------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        fclose(g_log_file);
        g_log_file = NULL;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started on GPIO%d. "
           "Press Ctrl+C to exit.\n", FLAME_SENSOR_GPIO);

    /* --- Main polling loop ------------------------------------------- */
    while (g_running) {
        int level = gpioRead(FLAME_SENSOR_GPIO);

        if (level == PI_BAD_GPIO) {
            fprintf(stderr, "gpioRead error on GPIO %d (PI_BAD_GPIO)\n",
                    FLAME_SENSOR_GPIO);
            log_flame_event(0);  /* log the error as a NO event */
        } else {
            int flame_detected = (level == 0);  /* active-LOW */

            if (log_flame_event(flame_detected) != 0) {
                fprintf(stderr, "Logging failed; continuing.\n");
            }

            if (flame_detected) {
                printf("FLAME DETECTED!\n");
                fflush(stdout);
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* --- Clean shutdown ---------------------------------------------- */
    printf("\nShutting down...\n");

    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
    return EXIT_SUCCESS;
}

