#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define D7S_ADDR       0x00          /* placeholder — replace with actual address */
#define SAMPLE_PERIOD  100000        /* 100 ms in microseconds */
#define LOG_FILE       "vibration_log.csv"

/*
 * Omron D7S‑0001 I2C register map (placeholder values — confirm against
 * the actual datasheet for your specific revision).
 *
 * Register 0x00: X-axis acceleration (16-bit, two's complement, LSB first)
 * Register 0x02: Y-axis acceleration (16-bit, two's complement, LSB first)
 * Register 0x04: Z-axis acceleration (16-bit, two's complement, LSB first)
 *
 * A read that returns 0xFFFF indicates the sensor is absent or not
 * responding on the bus.
 */
#define REG_X  0x00
#define REG_Y  0x02
#define REG_Z  0x04

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        if (n < 0)
            fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                    reg, strerror(errno));
        else
            fprintf(stderr, "I2C read (reg 0x%02X) short read: %zd bytes\n",
                    reg, n);
        return -1;
    }

    /* Sensor-absent / not-responding sentinel */
    if (buf[0] == 0xFF && buf[1] == 0xFF) {
        fprintf(stderr, "Sensor absent or not responding (reg 0x%02X)\n", reg);
        return -1;
    }

    /* Little-endian 16-bit two's complement */
    *out = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_sample(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return -1;
    }

    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- I2C setup ------------------------------------------------- */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                D7S_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- Log file -------------------------------------------------- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

