}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];

    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }

    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        if (n < 0)
            fprintf(stderr, "I2C read (reg 0x%02X) failed: %s\n",
                    reg, strerror(errno));
        else
            fprintf(stderr, "I2C read (reg 0x%02X) short read: %zd bytes\n",
                    reg, n);
        return -1;
    }

    /* Sensor-absent / not-responding sentinel */
    if (buf[0] == 0xFF && buf[1] == 0xFF) {
        fprintf(stderr, "Sensor absent or not responding (reg 0x%02X)\n", reg);
        return -1;
    }

    /* Little-endian 16-bit two's complement */
    *out = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    return 0;
}

/* ------------------------------------------------------------------ */
/* CSV logging                                                         */
/* ------------------------------------------------------------------ */
static int log_sample(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_utc;
    if (gmtime_r(&now, &tm_utc) == NULL) {
        fprintf(stderr, "gmtime_r() failed\n");
        return -1;
    }

    char ts[32];
    if (strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%SZ", &tm_utc) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }

    if (fprintf(fp, "%s,%d,%d,%d\n", ts, x, y, z) < 0) {
        fprintf(stderr, "fprintf() to log failed: %s\n", strerror(errno));
        return -1;
