#include <unistd.h>
#include <gpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define LOG_FILE "conveyor_log.txt"
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int log_sensor_data(FILE *fp, int sensor1_value, int sensor2_value) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
        perror("clock_gettime");
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);

    long milliseconds = ts.tv_nsec / 1000000;

    if (fprintf(fp, "%s.%03ld, Sensor1: %d, Sensor2: %d\n",
                timestamp, milliseconds, sensor1_value, sensor2_value) < 0) {
        perror("fprintf");
        return -1;
    }

    if (fflush(fp) == EOF) {
        perror("fflush");
        return -1;
    }

    return 0;
}

int main(void) {
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    FILE *log_file = NULL;
    int ret = EXIT_FAILURE;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (!line1) {
        perror("gpiod_chip_get_line(SENSOR1_PIN)");
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (!line2) {
        perror("gpiod_chip_get_line(SENSOR2_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line1, "conveyor_monitor",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags(SENSOR1_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_input_flags(line2, "conveyor_monitor",
                                       GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        perror("gpiod_line_request_input_flags(SENSOR2_PIN)");
        goto cleanup;
    }

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("fopen(" LOG_FILE ")");
        goto cleanup;
    }

    printf("Monitoring conveyor sensors on GPIO%d and GPIO%d. Press Ctrl+C to exit.\n",
           SENSOR1_PIN, SENSOR2_PIN);

    while (program_running) {
        int val1 = gpiod_line_get_value(line1);
        if (val1 < 0) {
            perror("gpiod_line_get_value(SENSOR1_PIN)");
            break;
        }

        int val2 = gpiod_line_get_value(line2);
        if (val2 < 0) {
            perror("gpiod_line_get_value(SENSOR2_PIN)");
            break;
        }

        if (log_sensor_data(log_file, val1, val2) < 0) {
            break;
        }

        if (val1 == 1 && val2 == 1) {
            printf("Conveyor halted!\n");
        }

        usleep(POLL_INTERVAL_US);
    }

    ret = EXIT_SUCCESS;

cleanup:
    if (log_file) {
        fclose(log_file);
    }
    if (line1) {
        gpiod_line_release(line1);
    }
    if (line2) {
        gpiod_line_release(line2);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("Program terminated gracefully.\n");
    }
    return ret;
}

