#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <errno.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define MMA8452Q_ADDR  0x1D

#define REG_STATUS     0x00
#define REG_OUT_X_MSB  0x01
#define REG_WHO_AM_I   0x0D
#define REG_XYZ_DATA_CFG 0x0E
#define REG_CTRL_REG1  0x2A
#define REG_CTRL_REG2  0x2B

#define WHO_AM_I_VAL   0x2A
#define TILT_THRESHOLD 45.0
#define LOG_FILE       "fall_log.txt"
#define LOOP_DELAY_US  10000

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        fprintf(stderr, "I2C block read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int init_mma8452q(int fd)
{
    uint8_t who_am_i = 0;
    if (i2c_read_reg8(fd, REG_WHO_AM_I, &who_am_i) != 0)
        return -1;
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n", who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    /* Standby mode: clear ACTIVE bit in CTRL_REG1 */
    if (i2c_write_reg8(fd, REG_CTRL_REG1, 0x00) != 0)
        return -1;

    /* Data rate = 100 Hz (DR=001), no F_READ bit set */
    if (i2c_write_reg8(fd, REG_CTRL_REG1, 0x01) != 0)
        return -1;

    /* Full-scale range = +/-2g (FS=00) */
    if (i2c_write_reg8(fd, REG_XYZ_DATA_CFG, 0x00) != 0)
        return -1;

    /* Active mode: set ACTIVE bit in CTRL_REG1 */
    if (i2c_write_reg8(fd, REG_CTRL_REG1, 0x01) != 0)
        return -1;

    return 0;
}

static int read_accel(int fd, int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t buf[6];
    if (i2c_read_block(fd, REG_OUT_X_MSB, buf, 6) != 0)
        return -1;

    *x = (int16_t)((buf[0] << 8) | buf[1]) >> 4;
    *y = (int16_t)((buf[2] << 8) | buf[3]) >> 4;
    *z = (int16_t)((buf[4] << 8) | buf[5]) >> 4;
    return 0;
}

static double calc_tilt(int16_t x, int16_t y, int16_t z)
{
    double xg = (double)x / 4096.0;
    double yg = (double)y / 4096.0;
    double zg = (double)z / 4096.0;
    double tilt = atan2(sqrt(xg * xg + yg * yg), zg) * 180.0 / M_PI;
    return tilt;
}

static void log_fall(int16_t x, int16_t y, int16_t z)
{
    time_t now = time(NULL);
    struct tm tm_info;
    char ts[32];

    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm_info);

    fprintf(g_log_fp, "%s, X=%d, Y=%d, Z=%d\n", ts, x, y, z);
    fflush(g_log_fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MMA8452Q_ADDR) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n", MMA8452Q_ADDR, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    if (init_mma8452q(g_i2c_fd) != 0) {
        fprintf(stderr, "MMA8452Q initialization failed\n");
        close(g_i2c_fd);
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        return 1;
    }

    printf("Monitoring tilt (threshold %.1f deg)... Press Ctrl+C to exit.\n", TILT_THRESHOLD);

