#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LIS3MDL_ADDR   0x1E
#define LOG_FILE       "magnetic_log.txt"
#define SAMPLE_HZ      10
#define SAMPLE_US      (1000000 / SAMPLE_HZ)
#define METAL_THRESH   800.0f
#define MAX_INIT_RETRIES 3

/* LIS3MDL registers */
#define LIS3MDL_WHO_AM_I   0x0F
#define LIS3MDL_CTRL_REG1  0x20
#define LIS3MDL_CTRL_REG2  0x21
#define LIS3MDL_CTRL_REG3  0x22
#define LIS3MDL_CTRL_REG4  0x23
#define LIS3MDL_OUT_X_L    0x28
#define LIS3MDL_OUT_X_H    0x29
#define LIS3MDL_OUT_Y_L    0x2A
#define LIS3MDL_OUT_Y_H    0x2B
#define LIS3MDL_OUT_Z_L    0x2C
#define LIS3MDL_OUT_Z_H    0x2D

/* Calibration constants (adjust after calibration) */
static const float x_offset = 0.0f;
static const float y_offset = 0.0f;
static const float z_offset = 0.0f;
static const float x_scale  = 1.0f;
static const float y_scale  = 1.0f;
static const float z_scale  = 1.0f;

/* ±4 gauss sensitivity: 0.146 mG per LSB */
static const float LIS3MDL_SENSITIVITY = 0.146f;

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log   = NULL;

static void sig_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg8: write");
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg8: write");
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        perror("i2c_read_reg8: read");
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *val)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg16: write");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("i2c_read_reg16: read");
        return -1;
    }
    *val = (int16_t)((uint16_t)buf[0] | ((uint16_t)buf[1] << 8));
    return 0;
}

static int init_lis3mdl(int fd)
{
    uint8_t who;
    if (i2c_read_reg8(fd, LIS3MDL_WHO_AM_I, &who) != 0)
        return -1;
    if (who != 0x3D) {
        fprintf(stderr, "LIS3MDL WHO_AM_I mismatch: 0x%02X (expected 0x3D)\n", who);
        return -1;
    }

    /* CTRL_REG1: temp enable, OM high performance, DO 10 Hz */
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG1, 0x70) != 0)
        return -1;
    /* CTRL_REG2: FS ±4 gauss */
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG2, 0x00) != 0)
        return -1;
    /* CTRL_REG3: continuous conversion mode */
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG3, 0x00) != 0)
        return -1;
    /* CTRL_REG4: Z-axis high performance */
    if (i2c_write_reg8(fd, LIS3MDL_CTRL_REG4, 0x0C) != 0)
        return -1;

    return 0;
}

static int read_magnetometer(int fd, float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;

    if (i2c_read_reg16(fd, LIS3MDL_OUT_X_L, &raw_x) != 0) return -1;
    if (i2c_read_reg16(fd, LIS3MDL_OUT_Y_L, &raw_y) != 0) return -1;
    if (i2c_read_reg16(fd, LIS3MDL_OUT_Z_L, &raw_z) != 0) return -1;

    *x = ((float)raw_x - x_offset) * x_scale * LIS3MDL_SENSITIVITY;
    *y = ((float)raw_y - y_offset) * y_scale * LIS3MDL_SENSITIVITY;
    *z = ((float)raw_z - z_offset) * z_scale * LIS3MDL_SENSITIVITY;
    return 0;
}

static void log_data(FILE *fp, float x, float y, float z)
{
    fprintf(fp, "%.2f,%.2f,%.2f\n", x, y, z);
    fflush(fp);
}

static void check_metal_detection(float x, float y, float z)
{
    float magnitude = sqrtf(x * x + y * y + z * z);
    if (magnitude > METAL_THRESH) {
        fprintf(stderr, "Metal Detected! Magnitude: %.2f mG\n", magnitude);
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LIS3MDL_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    int init_ok = 0;
    for (int attempt = 0; attempt < MAX_INIT_RETRIES; attempt++) {
        if (init_lis3mdl(g_i2c_fd) == 0) {
            init_ok = 1;
            break;
        }
        fprintf(stderr, "LIS3MDL init failed (attempt %d/%d)\n", attempt + 1, MAX_INIT_RETRIES);
        usleep(100000);
    }
    if (!init_ok) {
        fprintf(stderr, "LIS3MDL initialization failed after %d attempts\n", MAX_INIT_RETRIES);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen " LOG_FILE);
        close(g_i2c_fd);
        return EXIT_FAILURE;
    }

    printf("LIS3MDL initialized. Logging to %s at %d Hz. Press Ctrl+C to stop.\n",
           LOG_FILE, SAMPLE_HZ);

    while (g_running) {
        float x, y, z;
        if (read_magnetometer(g_i2c_fd, &x, &y, &z) != 0) {
            fprintf(stderr, "Read error; re-initializing sensor...\n");
            if (init_lis3mdl(g_i2c_fd) != 0) {
                fprintf(stderr, "Re-init failed; retrying next cycle.\n");
            }
            usleep(SAMPLE_US);
            continue;
        }

        log_data(g_log, x, y, z);
        check_metal_detection(x, y, z);

        usleep(SAMPLE_US);
    }

    printf("\nShutting down cleanly...\n");
    if (g_log)   fclose(g_log);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return EXIT_SUCCESS;
}

