#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_SPEED 1000000
#define SPI_MODE 0
#define SPI_BITS 8

#define ADXL354B_REG_PARTID 0x02
#define ADXL354B_REG_STATUS 0x04
#define ADXL354B_REG_XDATA_L 0x08
#define ADXL354B_REG_XDATA_H 0x09
#define ADXL354B_REG_XDATA_U 0x0A
#define ADXL354B_REG_YDATA_L 0x0B
#define ADXL354B_REG_YDATA_H 0x0C
#define ADXL354B_REG_YDATA_U 0x0D
#define ADXL354B_REG_ZDATA_L 0x0E
#define ADXL354B_REG_ZDATA_H 0x0F
#define ADXL354B_REG_ZDATA_U 0x10
#define ADXL354B_REG_RESET 0x1F
#define ADXL354B_REG_POWER_CTL 0x2D

#define ADXL354B_PARTID 0xAD
#define ADXL354B_RESET_KEY 0x52
#define ADXL354B_POWER_CTL_RUN 0x02
#define ADXL354B_STATUS_STABLE 0x01

static volatile sig_atomic_t running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len) {
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx,
        .rx_buf = (unsigned long)rx,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS,
        .delay_usecs = 0,
        .cs_change = 0,
    };
    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        perror("SPI transfer failed");
        return -1;
    }
    return 0;
}

static int spi_write_reg(uint8_t reg, uint8_t value) {
    uint8_t tx[2] = { (uint8_t)(reg & 0x7F), value };
    uint8_t rx[2] = {0};
    return spi_transfer(tx, rx, 2);
}

static int spi_read_reg(uint8_t reg, uint8_t *value) {
    uint8_t tx[3] = { (uint8_t)(reg | 0x80), 0x00, 0x00 };
    uint8_t rx[3] = {0};
    if (spi_transfer(tx, rx, 3) < 0) return -1;
    *value = rx[2];
    return 0;
}

static int spi_read_regs(uint8_t reg, uint8_t *buf, size_t len) {
    uint8_t tx[32] = {0};
    uint8_t rx[32] = {0};
    if (len > 30) return -1;
    tx[0] = (uint8_t)(reg | 0xC0);
    if (spi_transfer(tx, rx, len + 1) < 0) return -1;
    memcpy(buf, rx + 1, len);
    return 0;
}

static int adxl354b_reset(void) {
    if (spi_write_reg(ADXL354B_REG_RESET, ADXL354B_RESET_KEY) < 0) return -1;
    usleep(1000);
    uint8_t pctl = 0;
    if (spi_read_reg(ADXL354B_REG_POWER_CTL, &pctl) < 0) return -1;
    pctl &= ~ADXL354B_POWER_CTL_RUN;
    if (spi_write_reg(ADXL354B_REG_POWER_CTL, pctl) < 0) return -1;
    uint8_t status = 0;
    int retries = 0;
    while (retries < 100) {
        if (spi_read_reg(ADXL354B_REG_STATUS, &status) < 0) return -1;
        if (status & ADXL354B_STATUS_STABLE) break;
        usleep(1000);
        retries++;
    }
    if (retries >= 100) {
        fprintf(stderr, "ADXL354B did not become stable\n");
        return -1;
    }
    pctl |= ADXL354B_POWER_CTL_RUN;
    if (spi_write_reg(ADXL354B_REG_POWER_CTL, pctl) < 0) return -1;
    return 0;
}

static int adxl354b_verify(void) {
    uint8_t partid = 0;
    if (spi_read_reg(ADXL354B_REG_PARTID, &partid) < 0) return -1;
    if (partid != ADXL354B_PARTID) {
        fprintf(stderr, "ADXL354B not detected (PARTID=0x%02X, expected 0x%02X)\n", partid, ADXL354B_PARTID);
        return -1;
    }
    return 0;
}

static int read_acceleration(int32_t *x, int32_t *y, int32_t *z) {
    uint8_t buf[6];
    if (spi_read_regs(ADXL354B_REG_XDATA_L, buf, 6) < 0) return -1;
    int32_t raw_x = (int32_t)((uint32_t)buf[2] << 16 | (uint32_t)buf[1] << 8 | buf[0]);
    int32_t raw_y = (int32_t)((uint32_t)buf[5] << 16 | (uint32_t)buf[4] << 8 | buf[3]);
    int32_t raw_z = (int32_t)((uint32_t)buf[8] << 16 | (uint32_t)buf[7] << 8 | buf[6]);
    *x = raw_x; *y = raw_y; *z = raw_z;
    return 0;
}

static void log_data(int32_t x, int32_t y, int32_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d\n", timestamp, x, y, z);
    fflush(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction failed");
        return 1;
    }

    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Failed to open SPI device");
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Failed to set SPI mode");
        close(spi_fd);
        return 1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Failed to set SPI bits per word");
        close(spi_fd);
        return 1;
    }

    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Failed to set SPI speed");
        close(spi_fd);
        return 1;
    }

    if (adxl354b_reset() < 0) {
        fprintf(stderr, "ADXL354B reset failed\n");
        close(spi_fd);
        return 1;
    }

    if (adxl354b_verify() < 0) {
        fprintf(stderr, "ADXL354B verification failed\n");
        close(spi_fd);
        return 1;
    }

    log_file = fopen("vibration_log.txt", "a");
    if (!log_file) {
        perror("Failed to open log file");
        close(spi_fd);
        return 1;
    }

    printf("ADXL354B initialized. Logging to vibration_log.txt\n");

    int32_t x, y, z;
    int retry_count = 0;
    const int max_retries = 5;

    while (running) {
        if (read_acceleration(&x, &y, &z) == 0) {
            log_data(x, y, z);
            retry_count = 0;
        } else {
            retry_count++;
            fprintf(stderr, "SPI read error (attempt %d/%d)\n", retry_count, max_retries);
            if (retry_count >= max_retries) {
                fprintf(stderr, "Max retries reached, attempting reset\n");
                if (adxl354b_reset() < 0) {
                    fprintf(stderr, "Reset failed, exiting\n");
                    break;
                }
                retry_count = 0;
            }
        }
        usleep(100000);
    }

    printf("\nShutting down...\n");
    if (log_file) fclose(log_file);
    if (spi_fd >= 0) close(spi_fd);
    return 0;
}

