#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ADIS16362 Register Addresses (8-bit, MSB set for read) */
#define ADIS16362_XGYRO_OUT  0x04
#define ADIS16362_YGYRO_OUT  0x06
#define ADIS16362_ZGYRO_OUT  0x08
#define ADIS16362_XACCEL_OUT 0x0A
#define ADIS16362_YACCEL_OUT 0x0C
#define ADIS16362_ZACCEL_OUT 0x0E

/* Scaling factors from ADIS16362 datasheet */
#define GYRO_SCALE  0.05f   /* deg/sec per LSB */
#define ACCEL_SCALE 0.0025f /* g per LSB */

/* SPI Configuration */
#define SPI_CHANNEL 0
#define SPI_BAUD    1000000 /* 1 MHz */
#define SPI_FLAGS   0x0003  /* Mode 3: active-high clock, active-low CE */

/* Sampling */
#define SAMPLE_DELAY_US 10000 /* 10 ms -> ~100 Hz */

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

/* Read a 16-bit register from the ADIS16362 via SPI.
 * The ADIS16362 requires the address byte with the MSB set for a read.
 * A dummy byte (0x00) is clocked in to clock out the 16-bit data.
 * Returns 0 on success, -1 on SPI transfer failure. */
static int read_register(uint8_t address, int16_t *value) {
    char tx_buf[2];
    char rx_buf[2];

    /* MSB set indicates read, address in lower 7 bits */
    tx_buf[0] = (char)(address | 0x80);
    tx_buf[1] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X\n", address);
        return -1;
    }

    /* Data is returned in the second 16-bit transfer */
    tx_buf[0] = 0x00;
    tx_buf[1] = 0x00;

    if (spiXfer(spi_handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI read data transfer failed for register 0x%02X\n", address);
        return -1;
    }

    *value = (int16_t)(((uint8_t)rx_buf[0] << 8) | (uint8_t)rx_buf[1]);
    return 0;
}

/* Read all IMU data; returns 0 on success, -1 on any read failure */
static int read_imu_data(float *x_gyro, float *y_gyro, float *z_gyro,
                         float *x_accel, float *y_accel, float *z_accel) {
    int16_t raw_xgyro, raw_ygyro, raw_zgyro;
    int16_t raw_xaccel, raw_yaccel, raw_zaccel;

    if (read_register(ADIS16362_XGYRO_OUT, &raw_xgyro) != 0) return -1;
    if (read_register(ADIS16362_YGYRO_OUT, &raw_ygyro) != 0) return -1;
    if (read_register(ADIS16362_ZGYRO_OUT, &raw_zgyro) != 0) return -1;
    if (read_register(ADIS16362_XACCEL_OUT, &raw_xaccel) != 0) return -1;
    if (read_register(ADIS16362_YACCEL_OUT, &raw_yaccel) != 0) return -1;
    if (read_register(ADIS16362_ZACCEL_OUT, &raw_zaccel) != 0) return -1;

    *x_gyro  = (float)raw_xgyro  * GYRO_SCALE;
    *y_gyro  = (float)raw_ygyro  * GYRO_SCALE;
    *z_gyro  = (float)raw_zgyro  * GYRO_SCALE;
    *x_accel = (float)raw_xaccel * ACCEL_SCALE;
    *y_accel = (float)raw_yaccel * ACCEL_SCALE;
    *z_accel = (float)raw_zaccel * ACCEL_SCALE;

    return 0;
}

/* Log a timestamped IMU reading to the CSV file */
static void log_data(FILE *fp, float x_gyro, float y_gyro, float z_gyro,
                     float x_accel, float y_accel, float z_accel) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    fprintf(fp, "%ld.%09ld,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n",
            (long)ts.tv_sec, ts.tv_nsec,
            x_gyro, y_gyro, z_gyro,
            x_accel, y_accel, z_accel);
    fflush(fp);
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open SPI channel 0, 1 MHz, Mode 3 */
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed (handle=%d)\n", spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open imu_log.csv\n");
        spiClose(spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(log_file, 0, SEEK_END);
    if (ftell(log_file) == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
        fflush(log_file);
    }

    /* Register signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("IMU data logging started. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (program_running) {
        float x_gyro, y_gyro, z_gyro;
        float x_accel, y_accel, z_accel;

        if (read_imu_data(&x_gyro, &y_gyro, &z_gyro,
                          &x_accel, &y_accel, &z_accel) == 0) {
            log_data(log_file, x_gyro, y_gyro, z_gyro,
                     x_accel, y_accel, z_accel);
        } else {
            fprintf(stderr, "Failed to read IMU data, skipping sample\n");
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fflush(log_file);
        fclose(log_file);
    }
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

