/*
 * KY-032 IR obstacle-avoidance sensor monitor for Raspberry Pi 3 Model B+
 *
 * Wiring:
 *   Sensor 1 OUT -> GPIO17 (physical pin 11)
 *   Sensor 2 OUT -> GPIO27 (physical pin 13)
 *   VCC         -> 3.3 V (physical pin 1)
 *   GND         -> GND  (physical pin 9)
 *
 * The KY-032 module has an active-low output: 0 = obstacle detected,
 * 1 = path clear.
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o ky032_monitor ky032_monitor.c -lgpiod
 *
 * Run:
 *   ./ky032_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define SENSOR1_PIN 17
#define SENSOR2_PIN 27
#define POLL_INTERVAL_MS 100

static volatile sig_atomic_t g_running = 1;

static void sigint_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

static void print_timestamp(void)
{
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return;
    }
    struct tm tm_info;
    if (localtime_r(&now, &tm_info) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        return;
    }
    char buf[32];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return;
    }
    printf("[%s] ", buf);
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line1 = NULL;
    struct gpiod_line *line2 = NULL;
    int ret = EXIT_FAILURE;

    /* Install SIGINT handler for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open the default gpiochip (gpiochip0 on RPi 3 B+) */
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line1 = gpiod_chip_get_line(chip, SENSOR1_PIN);
    if (line1 == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                SENSOR1_PIN, strerror(errno));
        goto cleanup;
    }

    line2 = gpiod_chip_get_line(chip, SENSOR2_PIN);
    if (line2 == NULL) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n",
                SENSOR2_PIN, strerror(errno));
        goto cleanup;
    }

    /* Request both lines as inputs */
    if (gpiod_line_request_input(line1, "ky032-monitor") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n",
                SENSOR1_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_input(line2, "ky032-monitor") < 0) {
        fprintf(stderr, "Failed to request GPIO line %d as input: %s\n",
                SENSOR2_PIN, strerror(errno));
        goto cleanup;
    }

    printf("KY-032 IR obstacle-avoidance monitor started.\n");
    printf("  Sensor 1: GPIO%d\n  Sensor 2: GPIO%d\n", SENSOR1_PIN, SENSOR2_PIN);
    printf("  Poll interval: %d ms. Press Ctrl+C to exit.\n\n", POLL_INTERVAL_MS);

    while (g_running) {
        int val1 = gpiod_line_get_value(line1);
        int val2 = gpiod_line_get_value(line2);

        if (val1 < 0 || val2 < 0) {
            fprintf(stderr, "Error reading GPIO lines: %s\n", strerror(errno));
            goto cleanup;
        }

        print_timestamp();
        printf("Sensor 1: %s | Sensor 2: %s\n",
               val1 == 0 ? "Obstacle detected" : "Path clear",
               val2 == 0 ? "Obstacle detected" : "Path clear");
        fflush(stdout);

        /* Sleep for POLL_INTERVAL_MS, but wake early on signal */
        struct timespec ts = {
            .tv_sec  = POLL_INTERVAL_MS / 1000,
            .tv_nsec = (POLL_INTERVAL_MS % 1000) * 1000000L
        };
        while (nanosleep(&ts, &ts) == -1 && errno == EINTR && g_running) {
            /* Retry if interrupted by signal, but keep checking g_running */
        }
    }

    printf("\nExiting gracefully...\n");
    ret = EXIT_SUCCESS;

cleanup:
    /* Release lines and close chip on every exit path */
    if (line1 != NULL)
        gpiod_line_release(line1);
    if (line2 != NULL)
        gpiod_line_release(line2);
    if (chip != NULL)
        gpiod_chip_close(chip);

    return ret;
}

