/*
 * ADIS16266 Gyroscope Reader for Raspberry Pi 4 Model B
 *
 * Wiring:
 *   ADIS16266 VCC  -> 3.3V (Pin 1)
 *   ADIS16266 GND  -> GND  (Pin 9)
 *   ADIS16266 SCLK -> GPIO11 (SPI0 SCLK, BCM 11)
 *   ADIS16266 DOUT -> GPIO9  (SPI0 MISO, BCM 9)
 *   ADIS16266 DIN  -> GPIO10 (SPI0 MOSI, BCM 10)
 *   ADIS16266 CS   -> GPIO8  (SPI0 CE0,  BCM 8)
 *
 * Build: gcc -O2 -Wall -o adis16266 adis16266.c -lm
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <math.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000U   /* 1 MHz */
#define SPI_BITS        8
#define SPI_MODE        SPI_MODE_3
#define SAMPLE_PERIOD_US 100000U   /* 100 ms */

/* ADIS16266 Register Addresses (MSB = 1 for read) */
#define REG_XGYRO_OUT  0x04
#define REG_YGYRO_OUT  0x06
#define REG_ZGYRO_OUT  0x08

/* Scale factor: 0.02 deg/sec per LSB (from datasheet) */
#define GYRO_SCALE_FACTOR 0.02f

static volatile sig_atomic_t g_running = 1;
static int g_spi_fd = -1;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit register from the ADIS16266 via SPI.
 *
 * Protocol (two 8-bit transfers):
 *   TX[0] = address | 0x80   (MSB = 1 for read)
 *   TX[1] = 0x00             (dummy, clocks out data)
 *   RX[0] = don't care
 *   RX[1] = register value (MSB first)
 *
 * Returns 0 on success, -1 on error.
 */
static int read_register(uint8_t address, int16_t *out)
{
    uint8_t tx[2] = { (uint8_t)(address | 0x80), 0x00 };
