    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = 2;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr) < 0) {
        fprintf(stderr, "SPI transfer failed for register 0x%02X: %s\n",
                address, strerror(errno));
        return -1;
    }

    /* rx[0] is undefined (clocked during address phase), rx[1] is data */
    *out = (int16_t)((rx[1] << 8) | rx[0]);
    return 0;
}

/* ------------------------------------------------------------------ */
static int init_spi(void)
{
    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        return -1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        goto fail;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        goto fail;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        goto fail;
    }

    return 0;

fail:
    close(g_spi_fd);
    g_spi_fd = -1;
    return -1;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register SIGINT handler: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (init_spi() < 0) {
        return EXIT_FAILURE;
    }

    printf("ADIS16266 Gyroscope Reader\n");
    printf("SPI device: %s | Mode %d | %u Hz | %d bits\n",
           SPI_DEVICE, SPI_MODE, SPI_SPEED_HZ, SPI_BITS);
    printf("Press Ctrl+C to exit.\n\n");

    while (g_running) {
        int16_t raw_x = 0, raw_y = 0, raw_z = 0;
        bool err = false;

        if (read_register(REG_XGYRO_OUT, &raw_x) < 0) err = true;
        if (read_register(REG_YGYRO_OUT, &raw_y) < 0) err = true;
        if (read_register(REG_ZGYRO_OUT, &raw_z) < 0) err = true;

        if (err) {
            fprintf(stderr, "SPI read error — sensor absent or bus fault.\n");
            break;
        }

        float x = (float)raw_x * GYRO_SCALE_FACTOR;
        float y = (float)raw_y * GYRO_SCALE_FACTOR;
        float z = (float)raw_z * GYRO_SCALE_FACTOR;

        printf("X: %+.2f deg/s  Y: %+.2f deg/s  Z: %+.2f deg/s\n", x, y, z);
        fflush(stdout);

        usleep(SAMPLE_PERIOD_US);
    }

    cleanup();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
