#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LSM6DSR I2C address (SA0 tied to GND on Adafruit breakout) */
#define LSM6DSR_ADDR 0x6B

/* LSM6DSR register addresses */
#define WHO_AM_I   0x0F
#define CTRL1_XL   0x10
#define CTRL2_G    0x11
#define OUTX_L_G   0x22
#define OUTX_H_G   0x23
#define OUTY_L_G   0x24
#define OUTY_H_G   0x25
#define OUTZ_L_G   0x26
#define OUTZ_H_G   0x27
#define OUTX_L_XL  0x28
#define OUTX_H_XL  0x29
#define OUTY_L_XL  0x2A
#define OUTY_H_XL  0x2B
#define OUTZ_L_XL  0x2C
#define OUTZ_H_XL  0x2D

#define WHO_AM_I_VAL 0x6C

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int16_t combine(uint8_t lo, uint8_t hi)
{
    return (int16_t)((uint16_t)hi << 8 | (uint16_t)lo);
}

static int read_reg(int handle, uint8_t reg, uint8_t *val)
{
    int rc = i2cReadByteData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed at reg 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    *val = (uint8_t)rc;
    return 0;
}

static int write_reg(int handle, uint8_t reg, uint8_t val)
{
    int rc = i2cWriteByteData(handle, reg, val);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed at reg 0x%02X (pigpio rc=%d)\n", reg, rc);
        return -1;
    }
    return 0;
}

static int read_burst(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc != (int)len) {
        fprintf(stderr, "I2C burst read failed at reg 0x%02X (pigpio rc=%d, expected %u)\n",
                reg, rc, len);
        return -1;
    }
    return 0;
}

static int init_lsm6dsr(int handle)
{
    uint8_t who_am_i = 0;
    if (read_reg(handle, WHO_AM_I, &who_am_i) != 0)
        return -1;
    if (who_am_i != WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                who_am_i, WHO_AM_I_VAL);
        return -1;
    }

    /* Accelerometer: 1.66 kHz ODR, +/- 2g FS */
    if (write_reg(handle, CTRL1_XL, 0x80) != 0)
        return -1;
    /* Gyroscope: 1.66 kHz ODR, 245 dps FS */
    if (write_reg(handle, CTRL2_G, 0x80) != 0)
        return -1;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    g_i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen failed (rc=%d)\n", g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (init_lsm6dsr(g_i2c_handle) != 0) {
        fprintf(stderr, "LSM6DSR initialization failed\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (g_running) {
        uint8_t g_buf[6];
        uint8_t xl_buf[6];

        if (read_burst(g_i2c_handle, OUTX_L_G, g_buf, 6) != 0)
            break;
        if (read_burst(g_i2c_handle, OUTX_L_XL, xl_buf, 6) != 0)
            break;

        int16_t gx = combine(g_buf[0], g_buf[1]);
        int16_t gy = combine(g_buf[2], g_buf[3]);
        int16_t gz = combine(g_buf[4], g_buf[5]);
        int16_t ax = combine(xl_buf[0], xl_buf[1]);
        int16_t ay = combine(xl_buf[2], xl_buf[3]);
        int16_t az = combine(xl_buf[4], xl_buf[5]);

        printf("%d,%d,%d,%d,%d,%d\n", ax, ay, az, gx, gy, gz);
        fflush(stdout);

        /* 100 ms delay (microseconds) */
        gpioDelay(100000);
    }

    if (g_i2c_handle >= 0)
        i2cClose(g_i2c_handle);
    gpioTerminate();
    return EXIT_SUCCESS;
}

