/*
 * FXOS8700 accelerometer + magnetometer reader for Raspberry Pi 4 Model B.
 *
 * Wiring:
 *   FXOS8700 SDA  -> GPIO2 (BCM 2, physical pin 3)
 *   FXOS8700 SCL  -> GPIO3 (BCM 3, physical pin 5)
 *   FXOS8700 VDD  -> 3.3 V
 *   FXOS8700 GND  -> GND
 *
 * Build:
 *   gcc -O2 -Wall -o fxos8700 fxos8700.c -lpigpio -lrt
 * Run:
 *   sudo ./fxos8700
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- FXOS8700 register map (subset) ---- */
#define FXOS8700_ADDR        0x1F   /* SA0 tied to GND on Adafruit breakout */
#define FXOS8700_WHOAMI      0x0D
#define FXOS8700_WHOAMI_VAL  0xC7
#define FXOS8700_CTRL_REG1   0x2A
#define FXOS8700_CTRL_REG2   0x2B
#define FXOS8700_M_CTRL_REG1 0x5B
#define FXOS8700_M_CTRL_REG2 0x5C
#define FXOS8700_OUT_X_MSB   0x01   /* 14-bit accel X MSB (0x01..0x06) + 16-bit mag X MSB (0x07..0x08) */

/* CTRL_REG1 bits */
#define CTRL_ACTIVE          0x01
#define CTRL_F_READ          0x02   /* Free-run mode */

/* M_CTRL_REG1 bits */
#define M_CTRL_HMS           0x01   /* Hyper-True mode */

/* ---- Globals for signal-safe cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to a register; returns 0 on success, -1 on error. */
static int reg_write(int handle, uint8_t reg, uint8_t value)
{
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, pigpio_error(i2cWriteByteData(handle, reg, value)));
        return -1;
    }
    return 0;
}

/* Read a single byte from a register; returns 0 on success, -1 on error. */
static int reg_read(int handle, uint8_t reg, uint8_t *out)
{
    int v = i2cReadByteData(handle, reg);
    if (v < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, pigpio_error(v));
        return -1;
    }
    *out = (uint8_t)v;
    return 0;
}

/* Read a block of bytes starting at a register; returns 0 on success, -1 on error. */
static int reg_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int n = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, len %u): %s\n",
                reg, len, pigpio_error(n));
        return -1;
    }
    if ((uint32_t)n != len) {
        fprintf(stderr, "I2C block read short: got %d of %u bytes\n", n, len);
        return -1;
    }
    return 0;
}

/* Initialize the FXOS8700: verify device ID, configure accelerometer + magnetometer. */
static int fxos8700_init(int handle)
{
    uint8_t whoami = 0;

    if (reg_read(handle, FXOS8700_WHOAMI, &whoami) != 0)
        return -1;

