/* Write a single byte to a register; returns 0 on success, -1 on error. */
static int reg_write(int handle, uint8_t reg, uint8_t value)
{
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "I2C write failed (reg 0x%02X, val 0x%02X): %s\n",
                reg, value, pigpio_error(i2cWriteByteData(handle, reg, value)));
        return -1;
    }
    return 0;
}

/* Read a single byte from a register; returns 0 on success, -1 on error. */
static int reg_read(int handle, uint8_t reg, uint8_t *out)
{
    int v = i2cReadByteData(handle, reg);
    if (v < 0) {
        fprintf(stderr, "I2C read failed (reg 0x%02X): %s\n",
                reg, pigpio_error(v));
        return -1;
    }
    *out = (uint8_t)v;
    return 0;
}

/* Read a block of bytes starting at a register; returns 0 on success, -1 on error. */
static int reg_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int n = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (n < 0) {
        fprintf(stderr, "I2C block read failed (reg 0x%02X, len %u): %s\n",
                reg, len, pigpio_error(n));
        return -1;
    }
    if ((uint32_t)n != len) {
        fprintf(stderr, "I2C block read short: got %d of %u bytes\n", n, len);
        return -1;
    }
    return 0;
}

