#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define ADXL345_ADDRESS 0x53
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATA_FORMAT 0x31
#define TILT_THRESHOLD 30.0
#define LOG_FILE "/var/log/tilt_events.log"
#define SAMPLE_INTERVAL_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_adxl345(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(handle, ADXL345_DATAX0, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "I2C read error: expected 6 bytes, got %d\n", result);
        return -1;
    }
    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);
    return 0;
}

static double calculate_tilt_angle(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 256.0;
    double y_g = (double)y / 256.0;
    double z_g = (double)z / 256.0;
    double tilt_x = atan2(y_g, sqrt(x_g * x_g + z_g * z_g)) * 180.0 / M_PI;
    double tilt_y = atan2(-x_g, sqrt(y_g * y_g + z_g * z_g)) * 180.0 / M_PI;
    return fabs(tilt_x) > fabs(tilt_y) ? fabs(tilt_x) : fabs(tilt_y);
}

static void log_tilt_event(double angle) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("Error opening log file");
        return;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d - Tilt angle: %.2f degrees\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, angle);
    fclose(fp);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    int handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(handle, ADXL345_DATA_FORMAT, 0x08) < 0) {
        fprintf(stderr, "Failed to set DATA_FORMAT register\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    if (i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Failed to set POWER_CTL register\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    printf("Tilt monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int16_t x, y, z;
        if (read_adxl345(handle, &x, &y, &z) != 0) {
            fprintf(stderr, "Read failed, retrying...\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double angle = calculate_tilt_angle(x, y, z);
        if (angle > TILT_THRESHOLD) {
            log_tilt_event(angle);
        }

        gpioDelay(SAMPLE_INTERVAL_US);
    }

    i2cWriteByteData(handle, ADXL345_POWER_CTL, 0x00);
    i2cClose(handle);
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return 0;
}

