#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SENSOR_PIN 17
#define WINDOW_SECONDS 5
#define SAMPLE_INTERVAL_US 1000
#define PAUSE_SECONDS 1

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int parse_threshold(int argc, char *argv[], int *threshold) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s <threshold>\n", argv[0]);
        return -1;
    }

    char *endptr = NULL;
    long val = strtol(argv[1], &endptr, 10);

    if (endptr == argv[1] || *endptr != '\0') {
        fprintf(stderr, "Error: threshold must be an integer.\n");
        return -1;
    }

    if (val <= 0) {
        fprintf(stderr, "Error: threshold must be a positive integer.\n");
        return -1;
    }

    *threshold = (int)val;
    return 0;
}

static int read_sensor(int pin) {
    int level = gpioRead(pin);
    if (level < 0) {
        fprintf(stderr, "Error: gpioRead failed on pin %d (rc=%d)\n", pin, level);
        return -1;
    }
    return level;
}

static void log_status(int high_count, int threshold) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (high_count > threshold) {
        printf("%s ALERT: %d high readings (threshold: %d)\n", timestamp, high_count, threshold);
    } else {
        printf("%s Status: %d high readings (threshold: %d)\n", timestamp, high_count, threshold);
    }
    fflush(stdout);
}

int main(int argc, char *argv[]) {
    int threshold = 0;

    if (parse_threshold(argc, argv, &threshold) != 0) {
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: gpioSetMode failed on pin %d\n", SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Monitoring KY-038 sound sensor on GPIO%d for %d seconds/window. Threshold: %d\n",
           SENSOR_PIN, WINDOW_SECONDS, threshold);
    fflush(stdout);

    while (g_running) {
        int high_count = 0;
        int elapsed = 0;

        while (elapsed < WINDOW_SECONDS && g_running) {
            int level = read_sensor(SENSOR_PIN);
