/*
 * door_access.c — Raspberry Pi 4 Model B
 *
 * Controls two 12 V electromagnetic door locks via TIP120-drive 5 V
 * active-HIGH relay modules on BCM GPIO17 (Door A) and BCM GPIO27
 * (Door B).  A HIGH on the relay de-energizes it, unlocking the door
 * for 5 s.  The program generates a random 6-digit security code,
 * prompts the user for input, logs a timestamped entry on a CSV file
 * when the codes match, and locks the doors on SIGINT/SIGTERM.
 *
 * Build:  gcc -Wall -o door_access door_access.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define DOOR_A_PIN  17
#define DOOR_B_PIN  27
#define UNLOCK_SEC  5
#define LOG_FILE    "access_log.txt"
#define CODE_MIN    100000
#define CODE_MAX    999999

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void sig_handler(int signo)
{
    (void)signo;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int generate_security_code(void)
{
    return (rand() % (CODE_MAX - CODE_MIN + 1)) + CODE_MIN;
}

/* ------------------------------------------------------------------ */
static int unlock_door(struct gpiod_line *line, int door_number)
{
    if (gpiod_line_set_value(line, 1) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d HIGH (Door %d): %s\n",
                door_number, door_number, strerror(errno));
        return -1;
    }

    printf("Door %d unlocked for %d seconds.\n", door_number, UNLOCK_SEC);
    sleep(UNLOCK_SEC);

    if (gpiod_line_set_value(line, 0) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d LOW (Door %d): %s\n",
                door_number, door_number, strerror(errno));
        return -1;
    }
    printf("Door %d locked.\n", door_number);
    return 0;
}

/* ------------------------------------------------------------------ */
static int log_access(int security_code)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open %s: %s\n", LOG_FILE, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "Error: time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "Error: localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%06d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, security_code) < 0) {
        fprintf(stderr, "Error: writing to %s failed: %s\n",
                LOG_FILE, strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error: closing %s failed: %s\n",
                LOG_FILE, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(struct gpiod_chip *chip,
                    struct gpiod_line *line_a,
                    struct gpiod_line *line_b)
{
    if (line_a != NULL) {
        gpiod_line_set_value(line_a, 0);   /* ensure doors are locked */
        gpiod_line_release(line_a);
    }
    if (line_b != NULL) {
        gpiod_line_set_value(line_b, 0);
        gpiod_line_release(line_b);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line_a = NULL;
    struct gpiod_line *line_b = NULL;
    int ret = EXIT_FAILURE;

    srand((unsigned int)time(NULL));

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (chip == NULL) {
        chip = gpiod_chip_open_by_label("pinctrl-bcm2711");
    }
    if (chip == NULL) {
        chip = gpiod_chip_open_by_number(0);
    }
    if (chip == NULL) {
        fprintf(stderr, "Error: cannot open GPIO chip: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    line_a = gpiod_chip_get_line(chip, DOOR_A_PIN);
    if (line_a == NULL) {
        fprintf(stderr, "Error: cannot get GPIO%d: %s\n", DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }

    line_b = gpiod_chip_get_line(chip, DOOR_B_PIN);
    if (line_b == NULL) {
        fprintf(stderr, "Error: cannot get GPIO%d: %s\n", DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line_a, "door_access", 0) < 0) {
        fprintf(stderr, "Error: cannot request GPIO%d as output: %s\n",
                DOOR_A_PIN, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line_b, "door_access", 0) < 0) {
        fprintf(stderr, "Error: cannot request GPIO%d as output: %s\n",
                DOOR_B_PIN, strerror(errno));
        goto cleanup;
    }

    printf("Door access control system started.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        int security_code = generate_security_code();
        printf("Security Code: %d\n", security_code);
        printf("Enter security code: ");
        fflush(stdout);

        int entered_code = 0;
        if (scanf("%d", &entered_code) != 1) {
            int c;
            while ((c = getchar()) != '\n' && c != EOF) {
                /* discard invalid input */
            }
            fprintf(stderr, "Invalid input. Please enter a 6-digit number.\n");
            continue;
        }

        if (entered_code == security_code) {
            printf("Access granted.\n");
            if (unlock_door(line_a, 1) != 0 || unlock_door(line_b, 2) != 0) {
                fprintf(stderr, "Error unlocking doors.\n");
            }
            if (log_access(security_code) != 0) {
                fprintf(stderr, "Error logging access.\n");
            }
        } else {
            printf("Access denied.\n");
        }
    }

    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;

cleanup:
    cleanup(chip, line_a, line_b);
    return ret;
}

