#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define BH1750_ADDR 0x23
#define BH1750_POWER_ON 0x01
#define BH1750_RESET 0x07
#define BH1750_CONT_HIGH_RES_MODE 0x10
#define BH1750_CONVERSION_TIME_MS 180
#define LOG_FILE "light_log.txt"
#define SAMPLE_INTERVAL_S 5

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int bh1750_init(int handle) {
    if (i2cWriteByte(handle, BH1750_POWER_ON) < 0) {
        fprintf(stderr, "Error: Failed to power on BH1750\n");
        return -1;
    }
    if (i2cWriteByte(handle, BH1750_RESET) < 0) {
        fprintf(stderr, "Error: Failed to reset BH1750\n");
        return -1;
    }
    if (i2cWriteByte(handle, BH1750_CONT_HIGH_RES_MODE) < 0) {
        fprintf(stderr, "Error: Failed to set measurement mode\n");
        return -1;
    }
    return 0;
}

static int bh1750_read_lux(int handle, float *lux) {
    char buf[2];
    int bytes_read = i2cReadDevice(handle, buf, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error: Failed to read from BH1750 (read %d bytes)\n", bytes_read);
        return -1;
    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    int handle = i2cOpen(1, BH1750_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X (handle %d)\n", BH1750_ADDR, handle);
        gpioTerminate();
        return 1;
    }

    if (bh1750_init(handle) != 0) {
        fprintf(stderr, "Error: BH1750 initialization failed. Check wiring and sensor presence.\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    printf("BH1750 initialized. Logging to %s every %d seconds. Press Ctrl+C to exit.\n", LOG_FILE, SAMPLE_INTERVAL_S);

    while (running) {
        float lux;
        if (bh1750_read_lux(handle, &lux) == 0) {
            if (log_data(lux) != 0) {
                fprintf(stderr, "Warning: Failed to log data\n");
            } else {
                printf("Lux: %.2f\n", lux);
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed. Retrying next cycle.\n");
        }
        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_S, 0);
    }

    printf("\nExiting gracefully...\n");
    i2cClose(handle);
    gpioTerminate();
    return 0;
}

