    }
    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux = (float)raw / 1.2f;
    return 0;
}

static int log_data(float lux) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s\n", LOG_FILE);
        return -1;
    }
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);
    fclose(fp);
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return 1;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    int handle = i2cOpen(1, BH1750_ADDR, 0);
    if (handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus 1 at address 0x%02X (handle %d)\n", BH1750_ADDR, handle);
        gpioTerminate();
        return 1;
    }

    if (bh1750_init(handle) != 0) {
        fprintf(stderr, "Error: BH1750 initialization failed. Check wiring and sensor presence.\n");
        i2cClose(handle);
        gpioTerminate();
        return 1;
    }

    printf("BH1750 initialized. Logging to %s every %d seconds. Press Ctrl+C to exit.\n", LOG_FILE, SAMPLE_INTERVAL_S);

    while (running) {
        float lux;
        if (bh1750_read_lux(handle, &lux) == 0) {
            if (log_data(lux) != 0) {
                fprintf(stderr, "Warning: Failed to log data\n");
            } else {
                printf("Lux: %.2f\n", lux);
            }
        } else {
            fprintf(stderr, "Warning: Sensor read failed. Retrying next cycle.\n");
        }
        gpioSleep(PI_TIME_RELATIVE, SAMPLE_INTERVAL_S, 0);
    }

    printf("\nExiting gracefully...\n");
    i2cClose(handle);
    gpioTerminate();
    return 0;
}

