static int mpr121_read_touch_data(uint16_t *touch_data) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, 0x00, buf, 2) != 2) {
        fprintf(stderr, "I2C read failed: %s\n", strerror(errno));
        return -1;
    }
    *touch_data = (uint16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

static int calculate_frequency(uint16_t touch_data) {
    int base_freq = 220;
    int freq_range = 55;
    float touch_value = (float)touch_data / 4095.0f;
    int frequency = base_freq + (int)(touch_value * freq_range);
    if (frequency < base_freq) frequency = base_freq;
    if (frequency > base_freq + freq_range) frequency = base_freq + freq_range;
    return frequency;
}

static void play_tone(int frequency, int duration_ms) {
    if (gpioSetPWMfrequency(PWM_PIN, frequency) < 0) {
        fprintf(stderr, "Failed to set PWM frequency: %s\n", strerror(errno));
        return;
    }
    if (gpioPWM(PWM_PIN, PWM_RANGE / 2) < 0) {
        fprintf(stderr, "Failed to start PWM: %s\n", strerror(errno));
        return;
    }
    gpioDelay(duration_ms * 1000);
    if (gpioPWM(PWM_PIN, 0) < 0) {
        fprintf(stderr, "Failed to stop PWM: %s\n", strerror(errno));
    }
}

static void log_frequency(int frequency) {
    FILE *fp = fopen("frequency_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening frequency_log.txt: %s\n", strerror(errno));
        return;
    }
    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);
    fprintf(fp, "%s, Frequency: %d Hz\n", timestamp, frequency);
    fclose(fp);
}

static int authenticate_message(const char *message) {
    const char *prefix = "MOTION_DETECTED:";
    size_t prefix_len = strlen(prefix);
    if (strncmp(message, prefix, prefix_len) != 0) {
        return 0;
    }
    const char *secret = SHARED_SECRET;
    size_t secret_len = strlen(secret);
    if (strlen(message) < prefix_len + secret_len + 1) {
        return 0;
    }
    if (strncmp(message + prefix_len, secret, secret_len) == 0) {
        return 1;
    }
    return 0;
}

static void cleanup(void) {
    if (i2c_handle >= 0) {
        mpr121_write(0x80, 0x00);
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (client_fd >= 0) {
        close(client_fd);
        client_fd = -1;
    }
    if (server_fd >= 0) {
        close(server_fd);
        server_fd = -1;
    }
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();
}

