#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <math.h>
#include <fcntl.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS          "/dev/i2c-1"
#define LSM303_ADDR      0x1E          /* SA0 tied to VDD  */
#define LSM303_MAG_REG   0x08          /* first data register */
#define MAG_DATA_LEN     6             /* X/Y/Z axes, 16-bit each */
#define LED_GPIO         17            /* BCM 17 */
#define PWM_RANGE        255
#define PWM_FREQ         1000          /* Hz */
#define SAMPLE_PERIOD_US 100000        /* 100 ms */
#define LOG_FILE         "magnetometer.log"

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int      g_i2c_fd = -1;
static FILE    *g_log_fp = NULL;

/* ------------------------------------------------------------------ */
static void log_msg(const char *msg)
{
    if (!g_log_fp) return;
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    fprintf(g_log_fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, msg);
    fflush(g_log_fp);
}

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Read MAG_DATA_LEN bytes starting at LSM303_MAG_REG.
 * Returns 0 on success, -1 on error. */
static int read_mag(int fd, int16_t out[3])
{
    uint8_t reg = LSM303_MAG_REG;
    uint8_t buf[MAG_DATA_LEN];

    /* Write the register pointer */
    if (write(fd, &reg, 1) != 1) {
        log_msg("I2C write (reg pointer) failed");
        return -1;
    }

    /* Read 6 bytes: X_H, X_L, Y_H, Y_L, Z_H, Z_L */
    ssize_t n = read(fd, buf, MAG_DATA_LEN);
    if (n != MAG_DATA_LEN) {
        char m[128];
        snprintf(m, sizeof m, "I2C read failed (got %zd of %d)", n, MAG_DATA_LEN);
        log_msg(m);
        return -1;
    }

    out[0] = (int16_t)((buf[0] << 8) | buf[1]);  /* X */
    out[1] = (int16_t)((buf[2] << 8) | buf[3]);  /* Y */
    out[2] = (int16_t)((buf[4] << 8) | buf[5]);  /* Z */
    return 0;
}

/* ------------------------------------------------------------------ */
static void set_led_pwm(int16_t x, int16_t y, int16_t z)
{
    /* Magnitude of Z-axis field, scaled to PWM range */
    double mag = sqrt((double)x * x + (double)y * y + (double)z * z);
    int val = (int)(mag * (PWM_RANGE / 4096.0));
    if (val < 0)          val = 0;
    if (val > PWM_RANGE)  val = PWM_RANGE;

    if (gpioPWM(LED_GPIO, val) < 0)
