    if (gpioSetMode(LED_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed for GPIO %d\n", LED_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMrange(LED_GPIO, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPWMfrequency(LED_GPIO, PWM_FREQ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
