    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", I2C_BUS, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        fprintf(stderr, "ioctl I2C_SLAVE 0x%02X failed: %s\n",
                LSM303_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- Log file ---- */
    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }
    log_msg("Program started");

    /* ---- Signals ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof sa);
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    /* ---- Main loop ---- */
    while (g_running) {
        int16_t mag[3];

        if (read_mag(g_i2c_fd, mag) == 0) {
            set_led_pwm(mag[0], mag[1], mag[2]);
        }
        /* On error the LED stays at its last value; error already logged. */

        gpioDelay(SAMPLE_PERIOD_US);
