#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define HMC5883L_ADDR 0x1E
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_STATUS 0x09
#define HMC5883L_ID_A 0x0A
#define HMC5883L_ID_B 0x0B
#define HMC5883L_ID_C 0x0C

#define NUM_SAMPLES 100
#define SAMPLE_DELAY_US 500000

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

typedef struct {
    int16_t x[NUM_SAMPLES];
    int16_t y[NUM_SAMPLES];
    int16_t z[NUM_SAMPLES];
    int count;
} MagHistory;

static MagHistory mag_history;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int write_register(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing register 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int read_register(uint8_t reg) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int read_block(uint8_t reg, uint8_t *buf, uint32_t len) {
    int rc = i2cReadI2CBlockData(i2c_handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "Error reading block from 0x%02X: %d\n", reg, rc);
    }
    return rc;
}

static int initialize_hmc5883l(void) {
    int id_a = read_register(HMC5883L_ID_A);
    int id_b = read_register(HMC5883L_ID_B);
    int id_c = read_register(HMC5883L_ID_C);

    if (id_a < 0 || id_b < 0 || id_c < 0) {
        return -1;
    }

    if ((id_a != 'H') || (id_b != '4') || (id_c != '3')) {
        fprintf(stderr, "Invalid HMC5883L ID: %c%c%c\n", (char)id_a, (char)id_b, (char)id_c);
        return -1;
    }

    if (write_register(HMC5883L_CONFIG_A, 0x70) < 0) return -1;
    if (write_register(HMC5883L_CONFIG_B, 0x20) < 0) return -1;
    if (write_register(HMC5883L_MODE, 0x00) < 0) return -1;

    return 0;
}

static int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];
    if (read_block(HMC5883L_DATA_X_MSB, data, 6) < 0) {
        return -1;
    }

    *x = (int16_t)((data[0] << 8) | data[1]);
    *z = (int16_t)((data[2] << 8) | data[3]);
    *y = (int16_t)((data[4] << 8) | data[5]);

    return 0;
}

static void update_mag_history(int16_t x, int16_t y, int16_t z) {
    int index = mag_history.count % NUM_SAMPLES;
    mag_history.x[index] = x;
    mag_history.y[index] = y;
    mag_history.z[index] = z;
    if (mag_history.count < NUM_SAMPLES) {
        mag_history.count++;
    }
}

static void calculate_offsets(int16_t *x_offset, int16_t *y_offset, int16_t *z_offset) {
    if (mag_history.count == 0) {
        *x_offset = 0;
        *y_offset = 0;
        *z_offset = 0;
        return;
    }

    int64_t x_sum = 0, y_sum = 0, z_sum = 0;
    for (int i = 0; i < mag_history.count; i++) {
        x_sum += mag_history.x[i];
        y_sum += mag_history.y[i];
        z_sum += mag_history.z[i];
    }

    *x_offset = (int16_t)(x_sum / mag_history.count);
    *y_offset = (int16_t)(y_sum / mag_history.count);
    *z_offset = (int16_t)(z_sum / mag_history.count);
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n", HMC5883L_ADDR, i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (initialize_hmc5883l() < 0) {
        fprintf(stderr, "HMC5883L initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    mag_history.count = 0;

    while (running) {
        int16_t x, y, z;
        if (read_magnetometer(&x, &y, &z) == 0) {
            update_mag_history(x, y, z);

            int16_t x_offset, y_offset, z_offset;
            calculate_offsets(&x_offset, &y_offset, &z_offset);

            int16_t x_corrected = x - x_offset;
            int16_t y_corrected = y - y_offset;
            int16_t z_corrected = z - z_offset;

            printf("X: %d, Y: %d, Z: %d\n", x_corrected, y_corrected, z_corrected);
            fflush(stdout);
        } else {
            fprintf(stderr, "Failed to read magnetometer data\n");
        }

        gpioDelay(SAMPLE_DELAY_US);
    }

    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

