 *
 * Reads tri-axial acceleration data over I2C at ~10 ms intervals, stores
 * samples in a 64-entry circular buffer, and dumps the last 10 samples
 * to stdout on a rising edge of the INT1 pin (BCM GPIO 23, physical pin 16).
 *
 * Build:  gcc -O2 -Wall -Wextra -o lsm303d_mon lsm303d_mon.c -lgpiod
 * Run:    ./lsm303d_mon
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <fcntl.h>
#include <unistd.h>
#include <time.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <gpiod.h>

/* ---- LSM303D constants (verified against datasheet) ---- */
#define LSM303D_ADDR        0x19
#define LSM303D_WHO_AM_I    0x0F
#define LSM303D_WHO_AM_I_VAL 0x49
#define LSM303D_CTRL_REG1   0x20
#define LSM303D_CTRL_REG4   0x23
#define LSM303D_INT1_CFG    0x30
#define LSM303D_INT1_THS    0x32
#define LSM303D_INT1_DURATION 0x33
#define LSM303D_INT1_SRC    0x34
#define LSM303D_OUT_X_L_A   0x28
#define LSM303D_OUT_X_H_A   0x29
#define LSM303D_OUT_Y_L_A   0x2A
#define LSM303D_OUT_Y_H_A   0x2B
#define LSM303D_OUT_Z_L_A   0x2C
#define LSM303D_OUT_Z_H_A   0x2D

#define I2C_BUS             "/dev/i2c-1"
#define GPIO_CHIP           "gpiochip4"   /* BCM GPIO 23 on Pi Zero W */
#define GPIO_LINE           23
#define BUFFER_SIZE         64
#define SAMPLE_PERIOD_US    10000        /* 10 ms */
#define SENSITIVITY_MG_LSB  0.061f       /* mg per LSB at +/- 2 g */
#define THRESHOLD_MG        2000.0f

/* ---- Data structures ---- */
typedef struct {
    int16_t x, y, z;
} accel_sample_t;

typedef struct {
    accel_sample_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* ---- Globals ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_line = NULL;

/* ---- Signal handler ---- */
static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- I2C helpers ---- */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val)
{
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val)
{
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, int16_t *out)
{
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read 16-bit from reg 0x%02X failed: %s\n",
                reg, strerror(errno));
        return -1;
    }
    *out = (int16_t)((buf[1] << 8) | buf[0]);
    return 0;
}

/* ---- Circular buffer ---- */
static void cb_init(circular_buffer_t *cb)
{
    cb->head  = 0;
    cb->count = 0;
}

static void cb_push(circular_buffer_t *cb, accel_sample_t s)
{
    cb->data[cb->head] = s;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE)
        cb->count++;
}

static void cb_dump_last_n(const circular_buffer_t *cb, int n)
{
    if (n > cb->count)
        n = cb->count;
    int start = (cb->head - n + BUFFER_SIZE) % BUFFER_SIZE;
    for (int i = 0; i < n; i++) {
        int idx = (start + i) % BUFFER_SIZE;
        printf("  [%3d] X=%6d Y=%6d Z=%6d\n",
               idx, cb->data[idx].x, cb->data[idx].y, cb->data[idx].z);
    }
}

/* ---- Timestamp ---- */
static void print_timestamp(void)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm;
    localtime_r(&ts.tv_sec, &tm);
    char buf[32];
    strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", &tm);
    printf("[%s.%03ld] ", buf, ts.tv_nsec / 1000000L);
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (g_line) {
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    if (g_i2c_fd >= 0) {
        /* Disable accelerometer: CTRL_REG1 = 0x00 */
        (void)i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1, 0x00);
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

/* ---- Main ---- */
int main(void)
{
    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Cannot open %s: %s\n", I2C_BUS, strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303D_ADDR) < 0) {
        fprintf(stderr, "Cannot set I2C slave address 0x%02X: %s\n",
                LSM303D_ADDR, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* Verify device identity */
    uint8_t whoami = 0;
    if (i2c_read_reg8(g_i2c_fd, LSM303D_WHO_AM_I, &whoami) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (whoami != LSM303D_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X\n",
                whoami, LSM303D_WHO_AM_I_VAL);
        cleanup();
        return EXIT_FAILURE;
    }
    printf("LSM303D detected (WHO_AM_I = 0x%02X)\n", whoami);

    /* Initialize accelerometer: 100 Hz, +/- 2 g, normal mode */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG1, 0x57) != 0) {
        fprintf(stderr, "Failed to configure CTRL_REG1\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Enable high-resolution mode (CTRL_REG4 bit 3 = 0x08) */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_CTRL_REG4, 0x08) != 0) {
        fprintf(stderr, "Failed to configure CTRL_REG4\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure interrupt: threshold 2000 mg, zero duration */
    uint8_t threshold = (uint8_t)(THRESHOLD_MG / SENSITIVITY_MG_LSB);
    if (i2c_write_reg8(g_i2c_fd, LSM303D_INT1_THS, threshold) != 0) {
        fprintf(stderr, "Failed to set INT1_THS\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (i2c_write_reg8(g_i2c_fd, LSM303D_INT1_DURATION, 0x00) != 0) {
        fprintf(stderr, "Failed to set INT1_DURATION\n");
        cleanup();
        return EXIT_FAILURE;
    }
    /* Enable X, Y, Z axes in INT1_CFG (bits 0-2) */
    if (i2c_write_reg8(g_i2c_fd, LSM303D_INT1_CFG, 0x07) != 0) {
        fprintf(stderr, "Failed to set INT1_CFG\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open GPIO chip and request INT1 line */
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP);
    if (!g_chip) {
        fprintf(stderr, "Cannot open %s: %s\n", GPIO_CHIP, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    g_line = gpiod_chip_get_line(g_chip, GPIO_LINE);
    if (!g_line) {
        fprintf(stderr, "Cannot get GPIO line %d: %s\n",
                GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_rising_edge_events(g_line, "lsm303d_mon") < 0) {
        fprintf(stderr, "Cannot request rising-edge events on GPIO %d: %s\n",
                GPIO_LINE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Monitoring started. Press Ctrl-C to exit.\n");

    circular_buffer_t cb;
    cb_init(&cb);

    while (g_running) {
        /* Poll for INT1 rising edge (non-blocking) */
        int ret = gpiod_line_event_wait(g_line, NULL);
        if (ret < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "GPIO event wait error: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) {
            /* No event; read one sample and continue */
            accel_sample_t s;
            if (i2c_read_reg16(g_i2c_fd, LSM303D_OUT_X_L_A, &s.x) != 0 ||
                i2c_read_reg16(g_i2c_fd, LSM303D_OUT_Y_L_A, &s.y) != 0 ||
                i2c_read_reg16(g_i2c_fd, LSM303D_OUT_Z_L_A, &s.z) != 0) {
                fprintf(stderr, "Warning: I2C read failed, skipping sample\n");
                usleep(SAMPLE_PERIOD_US);
                continue;
            }
            cb_push(&cb, s);
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        /* Event detected: drain it and dump last 10 samples */
        struct gpiod_line_event ev;
        if (gpiod_line_event_read(g_line, &ev) < 0) {
            fprintf(stderr, "GPIO event read error: %s\n", strerror(errno));
            break;
        }

        print_timestamp();
        printf("INT1 rising edge detected — last %d samples:\n",
               (cb.count < 10) ? cb.count : 10);
        cb_dump_last_n(&cb, 10);
        fflush(stdout);

        /* Clear interrupt source register */
        uint8_t src = 0;
        (void)i2c_read_reg8(g_i2c_fd, LSM303D_INT1_SRC, &src);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

