        return EXIT_FAILURE;
    }

    printf("Monitoring started. Press Ctrl-C to exit.\n");

    circular_buffer_t cb;
    cb_init(&cb);

    while (g_running) {
        /* Poll for INT1 rising edge (non-blocking) */
        int ret = gpiod_line_event_wait(g_line, NULL);
        if (ret < 0) {
            if (errno == EINTR)
                continue;
            fprintf(stderr, "GPIO event wait error: %s\n", strerror(errno));
            break;
        }
        if (ret == 0) {
            /* No event; read one sample and continue */
            accel_sample_t s;
            if (i2c_read_reg16(g_i2c_fd, LSM303D_OUT_X_L_A, &s.x) != 0 ||
                i2c_read_reg16(g_i2c_fd, LSM303D_OUT_Y_L_A, &s.y) != 0 ||
                i2c_read_reg16(g_i2c_fd, LSM303D_OUT_Z_L_A, &s.z) != 0) {
                fprintf(stderr, "Warning: I2C read failed, skipping sample\n");
                usleep(SAMPLE_PERIOD_US);
                continue;
            }
            cb_push(&cb, s);
            usleep(SAMPLE_PERIOD_US);
            continue;
        }

        /* Event detected: drain it and dump last 10 samples */
        struct gpiod_line_event ev;
        if (gpiod_line_event_read(g_line, &ev) < 0) {
            fprintf(stderr, "GPIO event read error: %s\n", strerror(errno));
            break;
        }

        print_timestamp();
        printf("INT1 rising edge detected — last %d samples:\n",
               (cb.count < 10) ? cb.count : 10);
        cb_dump_last_n(&cb, 10);
        fflush(stdout);

        /* Clear interrupt source register */
        uint8_t src = 0;
        (void)i2c_read_reg8(g_i2c_fd, LSM303D_INT1_SRC, &src);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

