#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <pigpio.h>

#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27
#define DELAY_MS       500

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int set_solenoid(int pin, int value)
{
    if (gpioWrite(pin, value) != 0) {
        fprintf(stderr, "gpioWrite(pin=%d, value=%d) failed: %s\n",
                pin, value, strerror(errno));
        return -1;
    }
    return 0;
}

static int sleep_ms(unsigned int ms)
{
    struct timespec req = {
        .tv_sec  = ms / 1000,
        .tv_nsec = (long)(ms % 1000) * 1000000L
    };
    struct timespec rem;

    while (nanosleep(&req, &rem) != 0) {
        if (errno != EINTR) {
            perror("nanosleep");
            return -1;
        }
        if (!g_running) {
            return -1;
        }
        req = rem;
    }
    return 0;
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (install_signal_handlers() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", SOLENOID_1_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(%d, PI_OUTPUT) failed\n", SOLENOID_2_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Start with both solenoids de-energized */
    if (set_solenoid(SOLENOID_1_PIN, 0) != 0 ||
        set_solenoid(SOLENOID_2_PIN, 0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int active_pin = SOLENOID_1_PIN;
    int inactive_pin = SOLENOID_2_PIN;

    while (g_running) {
        if (set_solenoid(active_pin, 1) != 0) {
            break;
        }
        if (set_solenoid(inactive_pin, 0) != 0) {
            break;
        }

        if (sleep_ms(DELAY_MS) != 0) {
            break;
        }

        if (!g_running) {
            break;
        }

        /* Swap active and inactive */
        int tmp = active_pin;
        active_pin = inactive_pin;
        inactive_pin = tmp;
    }

    /* Clean shutdown: de-energize both solenoids */
    (void)set_solenoid(SOLENOID_1_PIN, 0);
    (void)set_solenoid(SOLENOID_2_PIN, 0);

    gpioTerminate();
    return EXIT_SUCCESS;
}

