/*
 * Dual-factor door-lock authentication for Raspberry Pi 4 Model B.
 *
 * Two UART ports (/dev/serial0, /dev/serial1) at 9600 baud, 8N1.
 * Two active-HIGH relay modules on GPIO17 (BCM) and GPIO27 (BCM)
 * drive 12 V electromagnetic door locks.
 *
 * Build:  gcc -O2 -Wall -Wextra -o door_lock door_lock.c -lpigpio -lrt
 * Run:    sudo ./door_lock
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define UART0_PORT      "/dev/serial0"
#define UART1_PORT      "/dev/serial1"
#define BAUD_RATE       9600
#define GPIO_LOCK1      17
#define GPIO_LOCK2      27
#define EXPECTED_CODE   "123456"
#define CODE_LENGTH     6
#define UNLOCK_DURATION 2          /* seconds */
#define READ_TIMEOUT    5          /* seconds */
#define POLL_DELAY_US   100000     /* 100 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Constant-time string comparison (avoid timing side-channels)        */
/* ------------------------------------------------------------------ */
static int secure_compare(const char *a, const char *b, size_t len)
{
    unsigned int result = 0;
    for (size_t i = 0; i < len; i++)
        result |= (unsigned int)(unsigned char)a[i] ^ (unsigned char)b[i];
    return result == 0;
}

/* ------------------------------------------------------------------ */
/* Unlock both locks for UNLOCK_DURATION seconds                        */
/* ------------------------------------------------------------------ */
static void unlock_both_locks(void)
{
    if (gpioWrite(GPIO_LOCK1, 1) < 0)
        fprintf(stderr, "Error: failed to set GPIO%d HIGH\n", GPIO_LOCK1);
    if (gpioWrite(GPIO_LOCK2, 1) < 0)
        fprintf(stderr, "Error: failed to set GPIO%d HIGH\n", GPIO_LOCK2);

    /* Sleep in 100 ms slices so we can exit promptly on signal */
    for (int i = 0; i < UNLOCK_DURATION * 10 && g_running; i++)
        gpioDelay(POLL_DELAY_US);

    if (gpioWrite(GPIO_LOCK1, 0) < 0)
        fprintf(stderr, "Error: failed to set GPIO%d LOW\n", GPIO_LOCK1);
    if (gpioWrite(GPIO_LOCK2, 0) < 0)
        fprintf(stderr, "Error: failed to set GPIO%d LOW\n", GPIO_LOCK2);
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int  uart0 = -1, uart1 = -1;
    char code0[CODE_LENGTH + 1] = {0};
    char code1[CODE_LENGTH + 1] = {0};
    int  code0_len = 0, code1_len = 0;
    int  pigpio_initialized = 0;

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }
    pigpio_initialized = 1;

    /* ---- Configure relay GPIOs as outputs, locked (LOW) ---- */
    if (gpioSetMode(GPIO_LOCK1, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", GPIO_LOCK1);
        goto cleanup;
    }
    if (gpioSetMode(GPIO_LOCK2, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output\n", GPIO_LOCK2);
        goto cleanup;
    }
    if (gpioWrite(GPIO_LOCK1, 0) < 0 || gpioWrite(GPIO_LOCK2, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise relay GPIOs LOW\n");
        goto cleanup;
    }

    /* ---- Open UART ports ---- */
    uart0 = serOpen(UART0_PORT, BAUD_RATE, 0);
    if (uart0 < 0) {
        fprintf(stderr, "Error: cannot open %s (pigpio error %d)\n",
                UART0_PORT, uart0);
        goto cleanup;
    }

    uart1 = serOpen(UART1_PORT, BAUD_RATE, 0);
    if (uart1 < 0) {
        fprintf(stderr, "Error: cannot open %s (pigpio error %d)\n",
                UART1_PORT, uart1);
        goto cleanup;
    }

    printf("Dual-factor door-lock system started.\n");
    printf("  UART0: %s  UART1: %s  Baud: %d  Lock1: GPIO%d  Lock2: GPIO%d\n",
           UART0_PORT, UART1_PORT, BAUD_RATE, GPIO_LOCK1, GPIO_LOCK2);
    printf("Enter %d-digit codes on each port. Ctrl+C to exit.\n", CODE_LENGTH);

    /* ---- Main loop ---- */
    while (g_running) {
        /* --- Port 0 --- */
        int n0 = serDataAvailable(uart0);
        if (n0 < 0) {
            fprintf(stderr, "Error: serDataAvailable(uart0) failed\n");
            break;
        }
        if (n0 > 0) {
            char buf0[256];
            int  r0 = serRead(uart0, buf0, sizeof(buf0));
            if (r0 < 0) {
                fprintf(stderr, "Error: serRead(uart0) failed\n");
                break;
            }
            for (int i = 0; i < r0 && code0_len < CODE_LENGTH; i++) {
                char c = buf0[i];
                if (c >= '0' && c <= '9')
                    code0[code0_len++] = c;
                else
                    code0_len = 0;                 /* reset on non-digit */
            }
        }

        /* --- Port 1 --- */
        int n1 = serDataAvailable(uart1);
        if (n1 < 0) {
            fprintf(stderr, "Error: serDataAvailable(uart1) failed\n");
            break;
        }
        if (n1 > 0) {
            char buf1[256];
            int  r1 = serRead(uart1, buf1, sizeof(buf1));
            if (r1 < 0) {
                fprintf(stderr, "Error: serRead(uart1) failed\n");
                break;
            }
            for (int i = 0; i < r1 && code1_len < CODE_LENGTH; i++) {
                char c = buf1[i];
                if (c >= '0' && c <= '9')
                    code1[code1_len++] = c;
                else
                    code1_len = 0;                 /* reset on non-digit */
            }
        }

        /* --- Check for complete codes --- */
        if (code0_len == CODE_LENGTH && code1_len == CODE_LENGTH) {
            code0[CODE_LENGTH] = '\0';
            code1[CODE_LENGTH] = '\0';

            if (secure_compare(code0, code1, CODE_LENGTH) &&
                secure_compare(code0, EXPECTED_CODE, CODE_LENGTH)) {
                printf("Authentication successful. Unlocking both locks.\n");
                unlock_both_locks();
                code0_len = 0;
                code1_len = 0;
            } else {
                fprintf(stderr, "Authentication failed: codes do not match.\n");
                code0_len = 0;
                code1_len = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

cleanup:
    /* ---- Force relays LOW (locked) ---- */
    if (pigpio_initialized) {
        gpioWrite(GPIO_LOCK1, 0);
        gpioWrite(GPIO_LOCK2, 0);
        gpioTerminate();
    }

    /* ---- Close UARTs ---- */
    if (uart0 >= 0) serClose(uart0);
    if (uart1 >= 0) serClose(uart1);

    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

