#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <pigpio.h>

#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define RELAY_ON_TIME 300   /* seconds */
#define RELAY_OFF_TIME 60   /* seconds */
#define TIMER_INTERVAL 60   /* seconds */

#define NUM_RELAYS 4

static const int relay_pins[NUM_RELAYS] = {
    RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN
};

static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    program_running = 0;
}

static void log_message(int priority, const char *message)
{
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(priority, "%s: %s", timestamp, message);
}

static int set_relay_state(int pin, int state)
{
    if (gpioWrite(pin, state) != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Failed to write GPIO %d to state %d", pin, state);
        log_message(LOG_ERR, msg);
        return -1;
    }
    return 0;
}

static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpioSetMode(relay_pins[i], PI_OUTPUT) != 0) {
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Failed to set GPIO %d as output", relay_pins[i]);
            log_message(LOG_ERR, msg);
            gpioTerminate();
            return -1;
        }
        if (set_relay_state(relay_pins[i], 1) != 0) {
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void)
{
    for (int i = 0; i < NUM_RELAYS; i++) {
        set_relay_state(relay_pins[i], 1);
    }
    gpioTerminate();
}

static void timer_callback(void *user_data)
{
    (void)user_data;
    static int current_relay = 0;
    static int relay_active = 0;
    static time_t relay_start_time = 0;

    time_t now = time(NULL);

    if (relay_active) {
        if (difftime(now, relay_start_time) >= RELAY_ON_TIME) {
            set_relay_state(relay_pins[current_relay], 1);
            relay_active = 0;
            char msg[128];
            snprintf(msg, sizeof(msg),
                     "Relay %d (GPIO %d) deactivated",
                     current_relay + 1, relay_pins[current_relay]);
            log_message(LOG_INFO, msg);
        }
    } else {
        set_relay_state(relay_pins[current_relay], 0);
        relay_active = 1;
        relay_start_time = now;
        char msg[128];
        snprintf(msg, sizeof(msg),
                 "Relay %d (GPIO %d) activated",
                 current_relay + 1, relay_pins[current_relay]);
        log_message(LOG_INFO, msg);

        current_relay = (current_relay + 1) % NUM_RELAYS;
        if (current_relay == 0) {
            set_relay_state(relay_pins[NUM_RELAYS - 1], 1);
            log_message(LOG_INFO,
                        "All relays cycled; pausing for 60 s");
            gpioDelay(RELAY_OFF_TIME * 1000000);
            current_relay = 0;
        }
    }
}

int main(void)
{
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (initialize_gpio() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    log_message(LOG_INFO, "Irrigation system started");

    if (gpioSetTimerFuncEx(0, TIMER_INTERVAL * 1000, timer_callback, NULL) != 0) {
        log_message(LOG_ERR, "Failed to set timer function");
        cleanup_gpio();
        closelog();
        return EXIT_FAILURE;
    }

    while (program_running) {
        gpioDelay(1000000);
    }

    log_message(LOG_INFO, "Irrigation system shutting down");
    cleanup_gpio();
    closelog();
    return EXIT_SUCCESS;
}

