#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <errno.h>
#include <string.h>
#include <gpiod.h>

#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

#define NUM_RELAYS 4

static const int relay_pins[NUM_RELAYS] = {
    RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN
};

static const int relay_intervals[NUM_RELAYS] = {
    2, 3, 5, 7
};

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static long elapsed_ms(const struct timespec *start,
                       const struct timespec *end)
{
    long sec  = (long)(end->tv_sec  - start->tv_sec);
    long nsec = (long)(end->tv_nsec - start->tv_nsec);
    return sec * 1000L + nsec / 1000000L;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *lines[NUM_RELAYS];
    int lines_requested = 0;
    int i;
    int ret = EXIT_FAILURE;

    for (i = 0; i < NUM_RELAYS; i++)
        lines[i] = NULL;

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip0");
    if (chip == NULL) {
        perror("gpiod_chip_open_by_name");
        return EXIT_FAILURE;
    }

    for (i = 0; i < NUM_RELAYS; i++) {
        lines[i] = gpiod_chip_get_line(chip, relay_pins[i]);
        if (lines[i] == NULL) {
            fprintf(stderr, "gpiod_chip_get_line failed for pin %d: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
    }

    for (i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_request_output(lines[i], "relay-toggle", 0) < 0) {
            fprintf(stderr, "gpiod_line_request_output failed for pin %d: %s\n",
                    relay_pins[i], strerror(errno));
            goto cleanup;
        }
        lines_requested++;
    }

    printf("Relay control started. Press Ctrl+C to exit.\n");

    struct timespec start, end;
    int relay_states[NUM_RELAYS] = {0, 0, 0, 0};

    while (running) {
        clock_gettime(CLOCK_MONOTONIC, &start);

        for (i = 0; i < NUM_RELAYS; i++) {
            long elapsed = elapsed_ms(&start, &end);
            if (elapsed >= relay_intervals[i] * 1000L) {
                relay_states[i] = !relay_states[i];
                if (gpiod_line_set_value(lines[i], relay_states[i]) < 0) {
                    fprintf(stderr, "gpiod_line_set_value failed for pin %d: %s\n",
                            relay_pins[i], strerror(errno));
                    goto cleanup;
                }
                printf("Relay %d (GPIO%d) toggled to %d\n",
                       i + 1, relay_pins[i], relay_states[i]);
                clock_gettime(CLOCK_MONOTONIC, &start);
            }
        }

        clock_gettime(CLOCK_MONOTONIC, &end);
        struct timespec sleep_ts;
        sleep_ts.tv_sec  = 0;
        sleep_ts.tv_nsec = 100 * 1000 * 1000; /* 100 ms */
        nanosleep(&sleep_ts, NULL);
    }

    ret = EXIT_SUCCESS;

cleanup:
    for (i = 0; i < lines_requested; i++) {
        if (lines[i] != NULL) {
            gpiod_line_set_value(lines[i], 0);
            gpiod_line_release(lines[i]);
        }
    }
    if (chip != NULL)
        gpiod_chip_close(chip);

    if (ret == EXIT_SUCCESS)
        printf("\nCleanup complete. Exiting.\n");

    return ret;
}

