#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27
#define POLL_INTERVAL_US 100000  /* 100 ms */
#define RELAY_ACTIVE_US 3000000  /* 3 s  */
#define DEBOUNCE_US 500000       /* 0.5 s */
#define LOG_FILE "alarm_log.txt"

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static int log_event(const char *filename)
{
    FILE *fp = fopen(filename, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r() failed\n");
        fclose(fp);
        return -1;
    }

    char timestamp[64];
    if (strftime(timestamp, sizeof(timestamp),
                 "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - Sound detected on GPIO%d, relay activated on GPIO%d\n",
                timestamp, SOUND_SENSOR_PIN, RELAY_PIN) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        fprintf(stderr, "Error closing log file: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGINT handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install SIGTERM handler: %s\n",
                strerror(errno));
        return EXIT_FAILURE;
    }

    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure sound sensor pin as input */
    if (gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", SOUND_SENSOR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay pin as output and ensure it is OFF */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize relay state on GPIO%d\n",
                RELAY_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Sound sensor monitoring started on GPIO%d.\n", SOUND_SENSOR_PIN);
    printf("Relay control on GPIO%d. Press Ctrl+C to exit.\n", RELAY_PIN);

    uint32_t last_trigger_tick = 0;

    while (running) {
        int sound_detected = gpioRead(SOUND_SENSOR_PIN);
        if (sound_detected < 0) {
            fprintf(stderr, "Error reading GPIO%d\n", SOUND_SENSOR_PIN);
            break;
        }

        if (sound_detected == 1) {
            uint32_t now = gpioTick();
            if (now == 0) {
                fprintf(stderr, "gpioTick() returned 0\n");
                break;
            }

            /* Debounce: ignore triggers within DEBOUNCE_US of the last one */
            if (now - last_trigger_tick > DEBOUNCE_US) {
                printf("Sound detected! Activating relay for 3 seconds.\n");

                if (gpioWrite(RELAY_PIN, 1) != 0) {
                    fprintf(stderr, "Failed to activate relay on GPIO%d\n",
                            RELAY_PIN);
                    break;
                }

                if (log_event(LOG_FILE) != 0) {
                    fprintf(stderr, "Warning: failed to log event.\n");
                }

                /* Keep relay active for 3 seconds, checking for shutdown */
                uint32_t start = gpioTick();
                while (running && (gpioTick() - start) < RELAY_ACTIVE_US) {
                    gpioDelay(100000); /* 100 ms */
                }

                if (gpioWrite(RELAY_PIN, 0) != 0) {
                    fprintf(stderr, "Failed to deactivate relay on GPIO%d\n",
                            RELAY_PIN);
                    break;
                }

                last_trigger_tick = now;
            }
        }

        gpioDelay(POLL_INTERVAL_US);
    }

    /* Ensure relay is OFF on exit */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();

    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

