/*
 * co2_monitor.c — Read MH-Z19B CO2 sensor over UART on Raspberry Pi 3 B+
 *
 * Wiring:
 *   MH-Z19B TX  -> Pi RXD (GPIO15, BCM)
 *   MH-Z19B RX  -> Pi TXD (GPIO14, BCM)
 *   MH-Z19B VCC -> 5 V, GND -> GND
 *
 * Build:
 *   gcc -Wall -Wextra -o co2_monitor co2_monitor.c -lthe_driver_library -lrt
 *
 * Run:
 *   ./co2_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <termios.h>
#include <sys/select.h>

/* ---- Configuration ---- */
#define UART_DEVICE      "/dev/serial0"
#define BAUD_RATE        B9600
#define LOG_FILE         "co2_log.json"
#define ERROR_LOG_FILE   "co2_error.log"
#define SAMPLE_INTERVAL  5          /* seconds between readings */
#define READ_TIMEOUT_MS  1000       /* max wait for sensor response */
#define RESPONSE_LEN     9          /* MH-Z19B 9-byte response */
#define READ_RETRIES     3          /* retries per sample window */

/* MH-Z19B command sequence (9 bytes, no start/stop bytes) */
static const uint8_t read_cmd[9] = {
    0xFF, 0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79
};

/* ---- Globals for cleanup ---- */
static int  uart_fd   = -1;
static FILE *log_fp   = NULL;
static FILE *err_fp   = NULL;
static volatile sig_atomic_t stop_flag = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    stop_flag = 1;
}

/* ---- Timestamp helper ---- */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) == 0) {
        struct tm tm_info;
        localtime_r(&ts.tv_sec, &tm_info);
        strftime(buf, len, "%Y-%m-%dT%H:%M:%S", &tm_info);
        size_t pos = strlen(buf);
        snprintf(buf + pos, len - pos, ".%06ld", ts.tv_nsec / 1000);
    } else {
        snprintf(buf, len, "1970-01-01T00:00:00.000000");
    }
}

/* ---- Error logger ---- */
static void log_error(const char *msg)
{
    char ts[40];
    get_timestamp(ts, sizeof(ts));
    if (err_fp) {
        fprintf(err_fp, "%s: %s (errno=%d: %s)\n", ts, msg, errno, strerror(errno));
        fflush(err_fp);
    }
    fprintf(stderr, "%s: %s (errno=%d: %s)\n", ts, msg, errno, strerror(errno));
}

/* ---- UART init ---- */
static int init_uart(const char *device)
{
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd < 0) {
        log_error("open UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        log_error("tcgetattr");
        close(fd);
        return -1;
    }

    cfsetispeed(&tty, BAUD_RATE);
    cfsetospeed(&tty, BAUD_RATE);

    tty.c_cflag  = (tty.c_cflag & ~CSIZE) | CS8;
    tty.c_cflag |= (CLOCAL | CREAD);
    tty.c_cflag &= ~(PARENB | PARODD | CSTOPB | CRTSCTS);

    tty.c_iflag  = 0;
    tty.c_oflag  = 0;
    tty.c_lflag  = 0;

    tty.c_cc[VMIN]  = 0;
    tty.c_cc[VTIME] = 0;   /* non-blocking */

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        log_error("tcsetattr");
        close(fd);
        return -1;
    }

    tcflush(fd, TCIOFLUSH);
    return fd;
}

/* ---- Send command ---- */
static int send_command(int fd, const uint8_t *cmd, size_t len)
{
    ssize_t written = write(fd, cmd, len);
    if (written < 0) {
        log_error("write UART");
        return -1;
    }
    if ((size_t)written != len) {
        log_error("partial write UART");
        return -1;
    }
    tcdrain(fd);
    return 0;
}

/* ---- Read response with timeout ---- */
static int read_response(int fd, uint8_t *buf, size_t len, int timeout_ms)
{
    size_t total = 0;
    struct timeval tv = {
        .tv_sec  = timeout_ms / 1000,
        .tv_usec = (timeout_ms % 1000) * 1000
    };

    while (total < len) {
        fd_set rfds;
        FD_ZERO(&rfds);
        FD_SET(fd, &rfds);

        int rv = select(fd + 1, &rfds, NULL, NULL, &tv);
        if (rv < 0) {
            if (errno == EINTR) continue;
            log_error("select UART");
            return -1;
        }
        if (rv == 0) {
            log_error("UART read timeout");
            return -1;
        }

        ssize_t n = read(fd, buf + total, len - total);
        if (n < 0) {
            if (errno == EINTR) continue;
            log_error("read UART");
            return -1;
        }
        if (n == 0) {
            log_error("UART EOF");
            return -1;
        }
        total += (size_t)n;
    }
    return 0;
}

/* ---- Verify checksum ---- */
static int verify_checksum(const uint8_t *data, size_t len)
{
    uint8_t calc = 0;
    for (size_t i = 1; i < len - 1; i++)
        calc += data[i];
    calc = 0xFF - calc + 1;
    return (calc == data[len - 1]) ? 0 : -1;
}

/* ---- Parse ppm ---- */
static int parse_ppm(const uint8_t *data, int *ppm)
{
    *ppm = (data[2] << 8) | data[3];
    return 0;
}

/* ---- Log JSON ---- */
static int log_json(int ppm, int error)
{
    char ts[40];
    get_timestamp(ts, sizeof(ts));

    if (fprintf(log_fp,
                "{\"timestamp\":\"%s\",\"ppm\":%d,\"error\":%d}\n",
                ts, ppm, error) < 0) {
        log_error("fprintf log");
        return -1;
    }
    if (fflush(log_fp) != 0) {
        log_error("fflush log");
        return -1;
    }
    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (uart_fd >= 0) {
        close(uart_fd);
        uart_fd = -1;
    }
    if (log_fp) {
        fclose(log_fp);
        log_fp = NULL;
    }
    if (err_fp) {
        fclose(err_fp);
        err_fp = NULL;
    }
}

/* ---- Main ---- */
int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    uart_fd = init_uart(UART_DEVICE);
    if (uart_fd < 0) {
        return EXIT_FAILURE;
    }

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        log_error("fopen log");
        cleanup();
        return EXIT_FAILURE;
    }

    err_fp = fopen(ERROR_LOG_FILE, "a");
    if (!err_fp) {
        log_error("fopen error log");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("CO2 monitoring started on %s @ 9600 baud. Press Ctrl+C to stop.\n",
           UART_DEVICE);

    while (!stop_flag) {
        int ppm = -1;
        int error = 1;

        for (int attempt = 0; attempt < READ_RETRIES && !stop_flag; attempt++) {
            if (send_command(uart_fd, read_cmd, sizeof(read_cmd)) != 0) {
                log_error("send command");
                continue;
            }

            uint8_t resp[RESPONSE_LEN];
            if (read_response(uart_fd, resp, RESPONSE_LEN, READ_TIMEOUT_MS) != 0) {
                log_error("read response");
                continue;
            }

            if (verify_checksum(resp, RESPONSE_LEN) != 0) {
                log_error("checksum mismatch");
                continue;
            }

            if (parse_ppm(resp, &ppm) != 0) {
                log_error("parse ppm");
                continue;
            }

            error = 0;
            break;
        }

        if (log_json(ppm, error) != 0) {
            log_error("log_json");
        }

        if (error) {
            fprintf(stderr, "CO2 read failed after %d attempts.\n", READ_RETRIES);
        } else {
            printf("CO2: %d ppm\n", ppm);
        }

        for (int s = 0; s < SAMPLE_INTERVAL && !stop_flag; s++)
            sleep(1);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

