#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

#define HMC5883L_ADDR 0x1E
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Y_MSB 0x07

#define GPIO_PIN 17
#define BUFFER_SIZE 100
#define SAMPLE_INTERVAL_US 100000
#define HEADING_THRESHOLD 10.0
#define TARGET_HEADING 90.0

static volatile sig_atomic_t running = 1;

void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

typedef struct {
    float x;
    float y;
} magnetometer_data_t;

typedef struct {
    magnetometer_data_t data[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

static int i2c_handle = -1;
static circular_buffer_t buffer;

void buffer_init(circular_buffer_t *buf) {
    buf->head = 0;
    buf->count = 0;
}

void buffer_add(circular_buffer_t *buf, magnetometer_data_t data) {
    buf->data[buf->head] = data;
    buf->head = (buf->head + 1) % BUFFER_SIZE;
    if (buf->count < BUFFER_SIZE) {
        buf->count++;
    }
}

int hmc5883l_init(int handle) {
    if (i2cWriteByteData(handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to CONFIG_A\n");
        return -1;
    }
    if (i2cWriteByteData(handle, HMC5883L_CONFIG_B, 0x20) < 0) {
        fprintf(stderr, "Error writing to CONFIG_B\n");
        return -1;
    }
    if (i2cWriteByteData(handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to MODE\n");
        return -1;
    }
    return 0;
}

int read_magnetometer(int handle, magnetometer_data_t *data) {
    char raw_data[6];
    if (i2cReadI2CBlockData(handle, HMC5883L_DATA_X_MSB, raw_data, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }
    int16_t x = (raw_data[0] << 8) | raw_data[1];
    int16_t z = (raw_data[2] << 8) | raw_data[3];
    int16_t y = (raw_data[4] << 8) | raw_data[5];
    data->x = (float)x;
    data->y = (float)y;
    return 0;
}

float calculate_heading(magnetometer_data_t data) {
    float heading = atan2(data.y, data.x) * 180.0 / M_PI;
    if (heading < 0) {
        heading += 360.0;
    }
    return heading;
}

void apply_hard_iron_compensation(magnetometer_data_t *data) {
    data->x -= 100.0;
    data->y += 50.0;
}

void control_gpio(float heading) {
    int deviation = (heading > TARGET_HEADING) ? (int)(heading - TARGET_HEADING) : (int)(TARGET_HEADING - heading);
    if (deviation > HEADING_THRESHOLD) {
        gpioWrite(GPIO_PIN, 1);
    } else {
        gpioWrite(GPIO_PIN, 0);
    }
}

int main() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    if (hmc5883l_init(i2c_handle) < 0) {
        fprintf(stderr, "HMC5883L initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0);

    buffer_init(&buffer);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        magnetometer_data_t raw_data;
        if (read_magnetometer(i2c_handle, &raw_data) == 0) {
            apply_hard_iron_compensation(&raw_data);
            float heading = calculate_heading(raw_data);
            buffer_add(&buffer, raw_data);
            control_gpio(heading);
        } else {
            fprintf(stderr, "Retrying I2C read in 100ms...\n");
            gpioDelay(100000);
            continue;
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(GPIO_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

