#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define BH1750_ADDR             0x23
#define BH1750_CONT_HIGH_RES    0x10  /* 1 lux resolution, ~120 ms */
#define BH1750_MEASURE_MS       120   /* max conversion time */
#define LOG_FILE                "lighting_log.txt"

#define RED_PIN   17
#define GREEN_PIN 27
#define BLUE_PIN  22

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int bh1750_read_lux(int fd, float *lux_out)
{
    uint8_t buf[2];
    ssize_t n;

    /* Send measurement command (no register, just the command byte) */
    if (write(fd, &(uint8_t){BH1750_CONT_HIGH_RES}, 1) != 1) {
        fprintf(stderr, "BH1750: write command failed: %s\n", strerror(errno));
        return -1;
    }

    /* Wait for conversion to complete */
    gpioDelay(BH1750_MEASURE_MS * 1000);  /* microseconds */

    /* Read 2 bytes of result (MSB first) */
    n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "BH1750: read failed (got %zd bytes): %s\n",
                n, n < 0 ? strerror(errno) : "short read");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

static void control_lamps(float lux)
{
    if (lux < 50.0f) {
        gpioWrite(RED_PIN,   1);
        gpioWrite(GREEN_PIN, 0);
        gpioWrite(BLUE_PIN,  0);
    } else if (lux < 150.0f) {
        gpioWrite(RED_PIN,   0);
        gpioWrite(GREEN_PIN, 1);
        gpioWrite(BLUE_PIN,  0);
    } else if (lux < 300.0f) {
        gpioWrite(RED_PIN,   0);
        gpioWrite(GREEN_PIN, 0);
        gpioWrite(BLUE_PIN,  1);
    } else {
        gpioWrite(RED_PIN,   1);
        gpioWrite(GREEN_PIN, 1);
        gpioWrite(BLUE_PIN,  1);
    }
}

static void log_data(float lux)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[64];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    if (strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        return;
    }

    if (fprintf(g_log_fp, "%s, Lux: %.2f\n", ts, lux) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
    } else {
        fflush(g_log_fp);
    }
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    /* Ensure relays are off before terminating pigpio */
    gpioWrite(RED_PIN,   0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN,  0);
    gpioTerminate();
}

int main(void)
{
    /* --- pigpio init --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- GPIO setup --- */
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(BLUE_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);

    /* --- I2C setup --- */
    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
