#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_A_IN1 17
#define MOTOR_A_IN2 18
#define MOTOR_B_IN3 22
#define MOTOR_B_IN4 23

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define LOOP_DELAY_US 100000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_motor_direction(int in1, int in2, int in3, int in4, int forward) {
    if (gpioWrite(in1, forward ? 1 : 0) < 0) return -1;
    if (gpioWrite(in2, forward ? 1 : 0) < 0) return -1;
    if (gpioWrite(in3, forward ? 1 : 0) < 0) return -1;
    if (gpioWrite(in4, forward ? 1 : 0) < 0) return -1;
    return 0;
}

static int set_motor_speed(int in2, int in4, int speed) {
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;
    if (gpioPWM(in2, speed) < 0) return -1;
    if (gpioPWM(in4, speed) < 0) return -1;
    return 0;
}

static int control_motor(int in1, int in2, int in3, int in4, int distance) {
    int speed = (int)(((float)(100 - distance) / 100.0f) * 255.0f);
    if (speed < 0) speed = 0;
    if (speed > PWM_RANGE) speed = PWM_RANGE;

    int forward = (distance < 50);
    if (set_motor_direction(in1, in2, in3, in4, forward) < 0) return -1;
    if (set_motor_speed(in2, in4, speed) < 0) return -1;
    return 0;
}

static void stop_motor(int in1, int in2, int in3, int in4) {
    gpioWrite(in1, 0);
    gpioWrite(in2, 0);
    gpioWrite(in3, 0);
    gpioWrite(in4, 0);
    gpioPWM(in2, 0);
    gpioPWM(in4, 0);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <motor_a_distance_cm> <motor_b_distance_cm>\n", argv[0]);
        return EXIT_FAILURE;
    }

    int motor_a_distance = atoi(argv[1]);
    int motor_b_distance = atoi(argv[2]);

    if (motor_a_distance < 10 || motor_a_distance > 100 ||
        motor_b_distance < 10 || motor_b_distance > 100) {
        fprintf(stderr, "Error: Distance values must be between 10 and 100 cm.\n");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(MOTOR_A_IN1, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_A_IN2, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_IN3, PI_OUTPUT) < 0 ||
        gpioSetMode(MOTOR_B_IN4, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(MOTOR_A_IN2, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_IN4, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: Failed to set PWM frequency.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_A_IN2, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_IN4, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: Failed to set PWM range.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    while (running) {
        if (control_motor(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4, motor_a_distance) < 0) {
            fprintf(stderr, "Error: Failed to control motor.\n");
            break;
        }
        usleep(LOOP_DELAY_US);
    }

    stop_motor(MOTOR_A_IN1, MOTOR_A_IN2, MOTOR_B_IN3, MOTOR_B_IN4);
    gpioTerminate();
    return EXIT_SUCCESS;
}

