{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    int pins[] = {IN1, IN2, IN3, IN4, LOCK_BUTTON, UNLOCK_BUTTON};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: failed to set GPIO %d as output.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }

    /* Buttons: input with internal pull-up (active-low) */
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) != 0 ||
        gpioSetMode(UNLOCK_BUTTON, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set button GPIO as input.\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) != 0 ||
        gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) != 0) {
        fprintf(stderr, "Error: failed to set pull-up on buttons.\n");
        gpioTerminate();
        return -1;
    }

    /* Ensure coils start de-energized */
    stepper_off();
    return 0;
}

/* ---- Main -------------------------------------------------------------- */
int main(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Door control ready. Press LOCK (GPIO24) to lock, UNLOCK (GPIO23) to unlock.\n");
    printf("Press Ctrl+C to exit.\n");

    while (g_running) {
        if (gpioRead(LOCK_BUTTON) == 0) {
            printf("Locking door...\n");
            stepper_rotate(STEPS_PER_REV);
            if (g_running) {
                printf("Door locked.\n");
            }
            gpioDelay(DEBOUNCE_US);
        }

        if (gpioRead(UNLOCK_BUTTON) == 0) {
            printf("Unlocking door...\n");
            stepper_rotate(-STEPS_PER_REV);
            if (g_running) {
                printf("Door unlocked.\n");
            }
            gpioDelay(DEBOUNCE_US);
        }

        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* Clean shutdown */
    stepper_off();
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

