#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <linux/i2c.h>

#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_ACCEL_XOUT_H 0x3B
#define MPU6050_GYRO_XOUT_H 0x43

#define SERVO_PWM_CHIP 2
#define SERVO_PWM_CHANNEL 0
#define SERVO_PWM_EXPORT_PATH "/sys/class/pwm/pwmchip2/export"
#define SERVO_PWM_UNEXPORT_PATH "/sys/class/pwm/pwmchip2/unexport"
#define SERVO_PWM_PERIOD_PATH "/sys/class/pwm/pwmchip2/pwm0/period"
#define SERVO_PWM_DUTY_CYCLE_PATH "/sys/class/pwm/pwmchip2/pwm0/duty_cycle"
#define SERVO_PWM_ENABLE_PATH "/sys/class/pwm/pwmchip2/pwm0/enable"

#define LOG_FILE "solar_tracker.log"
#define I2C_BUS "/dev/i2c-1"

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

typedef struct {
    float pitch;
    float roll;
} TiltData;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2] = {reg, value};
    if (write(fd, buf, 2) != 2) {
        return -1;
    }
    return 0;
}

static int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, size_t len) {
    if (write(fd, &reg, 1) != 1) {
        return -1;
    }
    if (read(fd, buf, len) != (ssize_t)len) {
        return -1;
    }
    return 0;
}

static int init_i2c(void) {
    int fd = open(I2C_BUS, O_RDWR);
    if (fd < 0) {
        perror("Failed to open I2C bus");
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Failed to acquire I2C bus access");
        close(fd);
        return -1;
    }
    return fd;
}

static int init_mpu6050(int fd) {
    if (i2c_write_byte(fd, MPU6050_PWR_MGMT_1, 0x00) < 0) {
        perror("Failed to wake up MPU6050");
        return -1;
    }
    usleep(100000);
    return 0;
}

static int read_raw_data(int fd, int16_t *ax, int16_t *ay, int16_t *az, int16_t *gx, int16_t *gy, int16_t *gz) {
    uint8_t buf[14];
    if (i2c_read_bytes(fd, MPU6050_ACCEL_XOUT_H, buf, 14) < 0) {
        return -1;
    }
    *ax = (int16_t)((buf[0] << 8) | buf[1]);
    *ay = (int16_t)((buf[2] << 8) | buf[3]);
    *az = (int16_t)((buf[4] << 8) | buf[5]);
    *gx = (int16_t)((buf[8] << 8) | buf[9]);
    *gy = (int16_t)((buf[10] << 8) | buf[11]);
    *gz = (int16_t)((buf[12] << 8) | buf[13]);
    return 0;
}

static TiltData calculate_tilt(int16_t ax, int16_t ay, int16_t az) {
    TiltData tilt;
    float x = (float)ax;
    float y = (float)ay;
    float z = (float)az;
    tilt.pitch = atan2(y, sqrt(x * x + z * z)) * 180.0 / M_PI;
    tilt.roll = atan2(-x, z) * 180.0 / M_PI;
    return tilt;
}

static int set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;
    int duty_cycle = (int)((angle / 180.0) * 2000000);
    FILE *fp = fopen(SERVO_PWM_DUTY_CYCLE_PATH, "w");
    if (!fp) {
        perror("Failed to open duty_cycle file");
        return -1;
    }
    fprintf(fp, "%d", duty_cycle);
    fclose(fp);
    return 0;
}

static int log_data(TiltData tilt, int position) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, tilt.pitch, tilt.roll, position);
    fflush(log_file);
    return 0;
}

static int init_pwm(void) {
    FILE *fp = fopen(SERVO_PWM_EXPORT_PATH, "w");
    if (!fp) {
        if (errno != EBUSY) {
            perror("Failed to export PWM channel");
            return -1;
        }
    } else {
        fprintf(fp, "%d", SERVO_PWM_CHANNEL);
        fclose(fp);
    }
    usleep(100000);
    fp = fopen(SERVO_PWM_PERIOD_PATH, "w");
    if (!fp) {
        perror("Failed to set PWM period");
        return -1;
    }
    fprintf(fp, "2000000");
    fclose(fp);
    fp = fopen(SERVO_PWM_ENABLE_PATH, "w");
    if (!fp) {
        perror("Failed to enable PWM");
        return -1;
    }
    fprintf(fp, "1");
    fclose(fp);
    return 0;
}

static void cleanup(void) {
    if (i2c_fd >= 0) {
        close(i2c_fd);
        i2c_fd = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    FILE *fp = fopen(SERVO_PWM_UNEXPORT_PATH, "w");
    if (fp) {
        fprintf(fp, "%d", SERVO_PWM_CHANNEL);
        fclose(fp);
    }
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        perror("Failed to open log file");
        return 1;
    }

    i2c_fd = init_i2c();
    if (i2c_fd < 0) {
        cleanup();
        return 1;
    }

    if (init_mpu6050(i2c_fd) < 0) {
        fprintf(stderr, "MPU6050 initialization failed. Check wiring and address.\n");
        cleanup();
        return 1;
    }

    if (init_pwm() < 0) {
        fprintf(stderr, "PWM initialization failed.\n");
        cleanup();
        return 1;
    }

    int16_t ax, ay, az, gx, gy, gz;
    TiltData tilt;
    int position = 90;
    int retry_count = 0;
    const int max_retries = 5;

    while (running) {
        if (read_raw_data(i2c_fd, &ax, &ay, &az, &gx, &gy, &gz) == 0) {
            retry_count = 0;
            tilt = calculate_tilt(ax, ay, az);
            if (tilt.pitch > 10.0) {
                position += 1;
            } else if (tilt.pitch < -10.0) {
                position -= 1;
            }
            if (position < 0) position = 0;
            if (position > 180) position = 180;
            if (set_servo_angle(position) < 0) {
                fprintf(stderr, "Failed to set servo angle.\n");
            }
            log_data(tilt, position);
        } else {
            retry_count++;
            fprintf(stderr, "I2C read failed (attempt %d/%d).\n", retry_count, max_retries);
            if (retry_count >= max_retries) {
                fprintf(stderr, "Max retries reached. Exiting.\n");
                break;
            }
            usleep(100000 * (1 << retry_count));
        }
        usleep(100000);
    }

    cleanup();
    return 0;
}

