#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define NUM_RELAYS 4
#define FADE_DURATION 1800
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define SCHEDULE_FILE "lighting_schedule.txt"

static const int relay_pins[NUM_RELAYS] = {4, 17, 27, 22};
static volatile sig_atomic_t program_running = 1;

typedef struct {
    int relay_number;
    int state;
} RelayCommand;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int parse_schedule_line(const char *line, int *hour, int *min, int *sec, int *relay, int *state) {
    if (sscanf(line, "%d:%d:%d,%d,%d", hour, min, sec, relay, state) != 5) {
        return -1;
    }
    if (*hour < 0 || *hour > 23 || *min < 0 || *min > 59 || *sec < 0 || *sec > 59 ||
        *relay < 1 || *relay > NUM_RELAYS || (*state != 0 && *state != 1)) {
        return -1;
    }
    return 0;
}

static int read_schedule(const char *filename, RelayCommand *schedule, int max_entries) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Error opening schedule file '%s': %s\n", filename, strerror(errno));
        return -1;
    }

    char line[256];
    int count = 0;
    while (fgets(line, sizeof(line), fp) && count < max_entries) {
        int hour, min, sec, relay, state;
        if (parse_schedule_line(line, &hour, &min, &sec, &relay, &state) == 0) {
            schedule[count].relay_number = relay;
            schedule[count].state = state;
            count++;
        } else {
            fprintf(stderr, "Warning: Invalid schedule entry: %s", line);
        }
    }

    fclose(fp);
    return count;
}

static int set_relay_state(int relay_number, int state) {
    int pin = relay_pins[relay_number - 1];
    if (gpioSetMode(pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d mode: %s\n", pin, pigpio_error(gpioGetMode(pin)));
        return -1;
    }
    if (gpioWrite(pin, state) < 0) {
        fprintf(stderr, "Error writing to GPIO %d: %s\n", pin, pigpio_error(gpioWrite(pin, state)));
        return -1;
    }
    return 0;
}

static int set_relay_pwm(int relay_number, int duty_cycle) {
    int pin = relay_pins[relay_number - 1];
    if (gpioSetMode(pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error setting GPIO %d mode: %s\n", pin, pigpio_error(gpioGetMode(pin)));
        return -1;
    }
    if (gpioSetPWMfrequency(pin, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error setting PWM frequency on GPIO %d: %s\n", pin, pigpio_error(gpioGetPWMfrequency(pin)));
        return -1;
    }
    if (gpioSetPWMrange(pin, PWM_RANGE) < 0) {
        fprintf(stderr, "Error setting PWM range on GPIO %d: %s\n", pin, pigpio_error(gpioGetPWMrange(pin)));
        return -1;
    }
    if (gpioPWM(pin, duty_cycle) < 0) {
        fprintf(stderr, "Error setting PWM duty cycle on GPIO %d: %s\n", pin, pigpio_error(gpioPWM(pin, duty_cycle)));
        return -1;
    }
    return 0;
}

static int fade_relay(int relay_number, int target_state) {
    int step_delay_us = (1000000 / FADE_DURATION) / 100;
    if (step_delay_us < 1) step_delay_us = 1;

    for (int i = 0; i <= 100 && program_running; i++) {
        if (set_relay_pwm(relay_number, i) < 0) return -1;
        gpioDelay(step_delay_us);
    }

    if (set_relay_state(relay_number, target_state) < 0) return -1;

    for (int i = 100; i >= 0 && program_running; i--) {
        if (set_relay_pwm(relay_number, i) < 0) return -1;
        gpioDelay(step_delay_us);
    }

    if (set_relay_pwm(relay_number, 0) < 0) return -1;
    return 0;
}

static int get_current_time_seconds(void) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error getting current time: %s\n", strerror(errno));
        return -1;
    }
    struct tm *tm_info = localtime(&now);
    if (!tm_info) {
        fprintf(stderr, "Error converting time: %s\n", strerror(errno));
        return -1;
    }
    return tm_info->tm_hour * 3600 + tm_info->tm_min * 60 + tm_info->tm_sec;
}

static int find_next_schedule_entry(const RelayCommand *schedule, int num_entries, int current_time, int *next_index) {
    int closest_time_diff = 24 * 3600;
    int found = 0;

    for (int i = 0; i < num_entries; i++) {
        int schedule_time = schedule[i].relay_number * 3600 + schedule[i].state * 3600;
        int time_diff = schedule_time - current_time;
        if (time_diff < 0) time_diff += 24 * 3600;
        if (time_diff < closest_time_diff) {
            closest_time_diff = time_diff;
            *next_index = i;
            found = 1;
        }
    }
    return found;
}

