        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error installing signal handler: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    RelayCommand schedule[100];
    int num_schedule_entries = read_schedule(SCHEDULE_FILE, schedule, sizeof(schedule) / sizeof(schedule[0]));
    if (num_schedule_entries < 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Smart Home Lighting System started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int current_time = get_current_time_seconds();
        if (current_time < 0) {
            gpioDelay(1000000);
            continue;
        }

        int next_index = 0;
        if (find_next_schedule_entry(schedule, num_schedule_entries, current_time, &next_index)) {
            int target_relay = schedule[next_index].relay_number;
            int target_state = schedule[next_index].state;

            printf("Fading relay %d to state %d\n", target_relay, target_state);
            if (fade_relay(target_relay, target_state) < 0) {
                fprintf(stderr, "Error fading relay %d\n", target_relay);
            }
