/*
 * Rudimentary theremin for Raspberry Pi Zero W
 * HC-SR04 ultrasonic distance sensor  ->  PWM buzzer frequency
 *
 * Wiring (BCM numbering):
 *   GPIO23  -> HC-SR04 TRIG (3.3 V)
 *   GPIO24  -> HC-SR04 ECHO (3.3 V)
 *   GPIO18  -> Buzzer PWM input (3.3 V)
 *
 * Build:  gcc -O2 -Wall -o theremin theremin.c -lpigpio -lrt
 * Run:    sudo ./theremin
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN      23
#define ECHO_PIN         24
#define BUZZER_PIN       18

#define MIN_FREQUENCY    200   /* Hz  — below audible range */
#define MAX_FREQUENCY    2000  /* Hz  — above audible range */
#define MIN_DISTANCE_CM  2.0f  /* cm  — HC-SR04 minimum reliable range */
#define MAX_DISTANCE_CM  400.0f /* cm — HC-SR04 maximum reliable range */
#define SAMPLE_PERIOD_US 20000 /* 50 Hz main loop */
#define MEASURE_GAP_US   60000 /* 60 ms between measurements */
#define ECHO_TIMEOUT_US  30000 /* 30 ms timeout for echo pulse */
#define TRIGGER_PULSE_US 10    /* 10 µs trigger pulse */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Read distance from HC-SR04 in centimetres.
 * Returns >= 0 on success, -1.0 on timeout, -2.0 on GPIO error.
 */
static float read_distance_cm(void)
{
    uint32_t start_tick, end_tick, timeout_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -2.0f;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 1) failed\n");
        return -2.0f;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(TRIGGER, 0) failed\n");
        return -2.0f;
    }

    /* Wait for echo rising edge (timeout) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo rising edge\n");
            return -1.0f;
        }
    }
    start_tick = gpioTick();

    /* Wait for echo falling edge (timeout) */
    timeout_tick = gpioTick() + ECHO_TIMEOUT_US;
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - timeout_tick) >= 0) {
            fprintf(stderr, "Error: timeout waiting for echo falling edge\n");
            return -1.0f;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - start_tick;
    /* speed of sound 343 m/s = 0.0343 cm/µs; round trip = /2 */
    return (float)diff * 0.0343f / 2.0f;
}

static int set_buzzer_frequency(int freq_hz)
{
    if (freq_hz < MIN_FREQUENCY || freq_hz > MAX_FREQUENCY) {
        fprintf(stderr, "Error: frequency %d Hz out of range [%d, %d]\n",
                freq_hz, MIN_FREQUENCY, MAX_FREQUENCY);
        return -1;
    }
    if (gpioSetPWMfrequency(BUZZER_PIN, freq_hz) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed\n", freq_hz);
        return -1;
    }
    if (gpioPWM(BUZZER_PIN, 128) < 0) { /* 50 % duty cycle */
        fprintf(stderr, "Error: gpioPWM(%d) failed\n", freq_hz);
        return -1;
    }
    return 0;
}

static void silence_buzzer(void)
{
    gpioPWM(BUZZER_PIN, 0);
}

int main(void)
{
    /* Install signal handler for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(TRIGGER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(ECHO) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(BUZZER) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure known initial states */
    gpioWrite(TRIGGER_PIN, 0);
    gpioPWM(BUZZER_PIN, 0);

    printf("Theremin started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float distance = read_distance_cm();

        if (distance < 0.0f) {
            /* Sensor error or timeout — silence buzzer for safety */
            silence_buzzer();
            gpioDelay(MEASURE_GAP_US);
            continue;
        }

        if (distance < MIN_DISTANCE_CM || distance > MAX_DISTANCE_CM) {
            /* Out of sensor range — silence buzzer */
            silence_buzzer();
            gpioDelay(MEASURE_GAP_US);
            continue;
        }

        /* Map distance (cm) to frequency (Hz) */
        float freq = MIN_FREQUENCY +
                     (distance - MIN_DISTANCE_CM) *
                     (MAX_FREQUENCY - MIN_FREQUENCY) /
                     (MAX_DISTANCE_CM - MIN_DISTANCE_CM);

        if (set_buzzer_frequency((int)freq) != 0) {
            /* PWM error — keep buzzer off for safety */
            silence_buzzer();
        }

        gpioDelay(MEASURE_GAP_US);
    }

    /* Cleanup */
    silence_buzzer();
    gpioTerminate();
    printf("\nTheremin stopped.\n");
    return EXIT_SUCCESS;
}

