#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27
#define PWM_FREQ  1000
#define PWM_RANGE 255

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_led_color(int r, int g, int b) {
    if (gpioPWM(RED_PIN, r) < 0) {
        fprintf(stderr, "Error setting red PWM: %s\n", pigpio_error(gpioGetMode(RED_PIN)));
        return -1;
    }
    if (gpioPWM(GREEN_PIN, g) < 0) {
        fprintf(stderr, "Error setting green PWM: %s\n", pigpio_error(gpioGetMode(GREEN_PIN)));
        return -1;
    }
    if (gpioPWM(BLUE_PIN, b) < 0) {
        fprintf(stderr, "Error setting blue PWM: %s\n", pigpio_error(gpioGetMode(BLUE_PIN)));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    set_led_color(0, 0, 0);
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set RED_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GREEN_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BLUE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set BLUE_PIN mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RED_PIN, PWM_FREQ) < 0) {
