#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BUTTON_PIN 17
#define BUZZER_PIN 18
#define DEBOUNCE_US 50000  /* 50 ms */
#define PWM_DUTY 128        /* 50 % of 255 */

/* Melody: note frequency in Hz, duration in ms */
typedef struct {
    int frequency;
    int duration;
} Note;

static const Note melody[] = {
    {440, 500}, {494, 500}, {523, 500}, {587, 500},
    {659, 500}, {698, 500}, {784, 500}, {880, 500}
};
static const int melody_length =
    sizeof(melody) / sizeof(melody[0]);

static volatile sig_atomic_t running = 1;
static volatile sig_atomic_t button_pressed = 0;
static volatile uint32_t last_interrupt_tick = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/*
 * ISR: pigpio dispatches this on a dedicated thread, so we keep it
 * minimal and set a flag that the main loop checks.
 */
static void button_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;

    if (level != 0) {  /* only act on falling edge (active-low button) */
        return;
    }

    uint32_t elapsed = tick - last_interrupt_tick;
    if (elapsed < DEBOUNCE_US) {
        return;
    }
    last_interrupt_tick = tick;

    button_pressed = 1;
}

static int play_tone(int frequency, int duration_ms) {
    if (frequency <= 0) {
        fprintf(stderr, "Invalid frequency: %d\n", frequency);
        return -1;
    }
    if (duration_ms <= 0) {
        fprintf(stderr, "Invalid duration: %d\n", duration_ms);
        return -1;
    }

    if (gpioSetPWMfrequency(BUZZER_PIN, frequency) < 0) {
        fprintf(stderr, "Failed to set PWM frequency to %d Hz\n", frequency);
        return -1;
    }

    if (gpioPWM(BUZZER_PIN, PWM_DUTY) < 0) {
        fprintf(stderr, "Failed to start PWM on GPIO%d\n", BUZZER_PIN);
        return -1;
    }

    /*
     * gpioDelay is a busy-wait; for a production doorbell the
     * melody should be played asynchronously so the main loop can
     * respond to a second press to stop.  For this example we keep
     * it simple.
     */
    gpioDelay(duration_ms * 1000);

    if (gpioPWM(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Failed to stop PWM on GPIO%d\n", BUZZER_PIN);
        return -1;
    }
    return 0;
}

static int play_melody(void) {
    for (int i = 0; i < melody_length; i++) {
        if (!button_pressed) {
            if (play_tone(melody[i].frequency, melody[i].duration) < 0) {
                return -1;
            }
        } else {
            /* Second press: stop melody immediately */
            if (gpioPWM(BUZZER_PIN, 0) < 0) {
                fprintf(stderr, "Failed to stop PWM during melody\n");
                return -1;
            }
            button_pressed = 0;  /* reset for next press */
            return 0;
        }
    }
    button_pressed = 0;  /* reset for next press */
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUTTON_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on GPIO%d\n", BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", BUZZER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) < 0) {
        fprintf(stderr, "Failed to register ISR on GPIO%d\n", BUTTON_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Doorbell ready. Press the button (GPIO%d) to play the melody.\n",
           BUTTON_PIN);
    printf("Press Ctrl+C to exit.\n");

    while (running) {
        if (button_pressed) {
            button_pressed = 0;
            if (play_melody() < 0) {
                fprintf(stderr, "Melody playback error\n");
            }
        }
        gpioDelay(10000);  /* 10 ms poll interval */
    }

    /* Clean shutdown */
    gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, NULL, NULL);
    gpioPWM(BUZZER_PIN, 0);
    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

