#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 17
#define WINDOW_SIZE 5
#define ALERT_THRESHOLD 3
#define LOG_FILE "vibration_events.log"

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int get_iso8601_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm timeinfo;

    if (time(&rawtime) == (time_t)-1) {
        return -1;
    }
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        return -1;
    }
    if (strftime(buf, len, "%Y-%m-%dT%H:%M:%S%z", &timeinfo) == 0) {
        return -1;
    }
    return 0;
}

static void log_event(int value) {
    char timestamp[32];

    if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) != 0) {
        fprintf(stderr, "Error: failed to generate timestamp\n");
        return;
    }

    if (log_file != NULL) {
        if (fprintf(log_file, "%s GPIO%d=%d\n", timestamp, GPIO_PIN, value) < 0) {
            fprintf(stderr, "Error: fprintf to log file failed: %s\n", strerror(errno));
        } else {
            if (fflush(log_file) != 0) {
                fprintf(stderr, "Warning: fflush failed: %s\n", strerror(errno));
            }
        }
    } else {
        fprintf(stderr, "Error: log file is not open\n");
    }
}

static void check_earthquake_alert(int value) {
    static int window[WINDOW_SIZE];
    static int index = 0;
    static int count = 0;
    char timestamp[32];

    if (get_iso8601_timestamp(timestamp, sizeof(timestamp)) != 0) {
        fprintf(stderr, "Error: failed to generate timestamp for alert\n");
        return;
    }

    window[index] = value;
    index = (index + 1) % WINDOW_SIZE;
    if (count < WINDOW_SIZE) {
        count++;
    }

    int high_count = 0;
    for (int i = 0; i < count; i++) {
        if (window[i] == 1) {
            high_count++;
        }
    }

    if (high_count >= ALERT_THRESHOLD) {
        printf("%s EARTHQUAKE ALERT: %d HIGH events in window\n", timestamp, high_count);
        fflush(stdout);
    }
}

int main(int argc, char *argv[]) {
    int poll_timeout_ms = 1000;

    if (argc > 1) {
        long val = strtol(argv[1], NULL, 10);
        if (val > 0) {
            poll_timeout_ms = (int)val;
        } else {
            fprintf(stderr, "Warning: invalid poll timeout '%s', using default %d ms\n", argv[1], poll_timeout_ms);
        }
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(GPIO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input\n", GPIO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO%d\n", GPIO_PIN);
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n", LOG_FILE, strerror(errno));
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler: %s\n", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGTERM handler: %s\n", strerror(errno));
    }

    printf("Monitoring SW-420 vibration sensor on GPIO%d (poll timeout %d ms). Press Ctrl+C to exit.\n", GPIO_PIN, poll_timeout_ms);
    fflush(stdout);

    while (program_running) {
        int level = gpioRead(GPIO_PIN);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO%d\n", GPIO_PIN);
            break;
        }

        log_event(level);
        check_earthquake_alert(level);

        /*
         * gpioSetAlertFuncEx is the edge-triggered callback.  To poll
         * explicitly, we must call it three times (rising, falling, both).
         * Each call blocks for up to poll_timeout_ms, so the total wait
         * is bounded by poll_timeout_ms.
         */
        gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);
        gpioDelay(poll_timeout_ms * 1000);
        gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);
        gpioDelay(poll_timeout_ms * 1000);
        gpioSetAlertFuncEx(GPIO_PIN, NULL, NULL);
        gpioDelay(poll_timeout_ms * 1000);
    }

    if (log_file != NULL) {
        if (fclose(log_file) != 0) {
            fprintf(stderr, "Warning: fclose failed: %s\n", strerror(errno));
        }
        log_file = NULL;
    }

    gpioTerminate();
    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

