#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define LSM303_ADDR    0x1E
#define LSM303_REG_MAG_X_L 0x08
#define LSM303_REG_MAG_X_H 0x09
#define LSM303_REG_MAG_Y_L 0x0A
#define LSM303_REG_MAG_Y_H 0x0B
#define LSM303_REG_MAG_Z_L 0x0C
#define LSM303_REG_MAG_Z_H 0x0D

#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

#define CSV_FILE "mag_log.csv"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv = NULL;

static void sig_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int read_mag(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t xl, xh, yl, yh, zl, zh;
    if (i2c_read_reg8(fd, LSM303_REG_MAG_X_L, &xl) < 0) return -1;
    if (i2c_read_reg8(fd, LSM303_REG_MAG_X_H, &xh) < 0) return -1;
    if (i2c_read_reg8(fd, LSM303_REG_MAG_Y_L, &yl) < 0) return -1;
    if (i2c_read_reg8(fd, LSM303_REG_MAG_Y_H, &yh) < 0) return -1;
    if (i2c_read_reg8(fd, LSM303_REG_MAG_Z_L, &zl) < 0) return -1;
    if (i2c_read_reg8(fd, LSM303_REG_MAG_Z_H, &zh) < 0) return -1;
    *x = (int16_t)((xh << 8) | xl);
    *y = (int16_t)((yh << 8) | yl);
    *z = (int16_t)((zh << 8) | zl);
    return 0;
}

static void calibrate(int16_t x, int16_t y, int16_t z,
                      int16_t *cx, int16_t *cy, int16_t *cz) {
    *cx = x - X_OFFSET;
    *cy = y - Y_OFFSET;
    *cz = z - Z_OFFSET;
}

static float heading_deg(int16_t cx, int16_t cy) {
    float h = atan2f((float)cy, (float)cx) * 180.0f / (float)M_PI;
    if (h < 0.0f) h += 360.0f;
    return h;
}

static const char *compass_dir(float h) {
    if (h >= 22.5f && h < 67.5f) return "NE";
    if (h >= 67.5f && h < 112.5f) return "E";
    if (h >= 112.5f && h < 157.5f) return "SE";
    if (h >= 157.5f && h < 202.5f) return "S";
    if (h >= 202.5f && h < 247.5f) return "SW";
    if (h >= 247.5f && h < 292.5f) return "W";
    if (h >= 292.5f && h < 337.5f) return "NW";
    return "N";
}

static void log_sample(FILE *f, int16_t cx, int16_t cy, int16_t cz, float h) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(f, "%s, %d, %d, %d, %.2f\n", ts, cx, cy, cz, h);
    fflush(f);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sig_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open(" I2C_BUS ")");
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        perror("ioctl(I2C_SLAVE)");
        close(g_i2c_fd);
        return 1;
    }

    int file_exists = (access(CSV_FILE, F_OK) == 0);
    g_csv = fopen(CSV_FILE, "a");
    if (!g_csv) {
        perror("fopen(" CSV_FILE ")");
        close(g_i2c_fd);
        return 1;
    }
    if (!file_exists) {
        fprintf(g_csv, "Timestamp, Calibrated X, Calibrated Y, Calibrated Z, Heading\n");
        fflush(g_csv);
    }

    while (g_running) {
        int16_t rx, ry, rz;
        if (read_mag(g_i2c_fd, &rx, &ry, &rz) < 0) {
            fprintf(stderr, "I2C read error: %s\n", strerror(errno));
            sleep(1);
            continue;
        }

        int16_t cx, cy, cz;
        calibrate(rx, ry, rz, &cx, &cy, &cz);
        float h = heading_deg(cx, cy);
        const char *dir = compass_dir(h);

        log_sample(g_csv, cx, cy, cz, h);
        printf("Compass: %s  Heading: %.2f degrees\n", dir, h);

        sleep(1);
    }

    if (g_csv) fclose(g_csv);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    printf("\nExiting cleanly.\n");
    return 0;
}

