#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 200000  /* 200 ms in microseconds */
#define LOG_FILE "relay_log.json"

static volatile sig_atomic_t running = 1;
static volatile uint32_t last_touch_tick = 0;
static volatile int relay_state = 0;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

static void log_relay_state(int state)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r");
        fclose(fp);
        return;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm) == 0) {
        fprintf(stderr, "strftime failed\n");
        fclose(fp);
        return;
    }

    fprintf(fp, "{\"timestamp\":\"%s\",\"relay_state\":\"%s\"}\n",
            timestamp, state ? "ON" : "OFF");
    fclose(fp);
}

static void touch_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level != 1) {
        return;  /* Only act on rising edge (touch detected) */
    }

    uint32_t elapsed = tick - last_touch_tick;
    if (elapsed < DEBOUNCE_DELAY_US) {
        return;  /* Debounce: ignore touches within 200 ms */
    }
    last_touch_tick = tick;

    relay_state = !relay_state;
    if (gpioWrite(RELAY_PIN, relay_state) != 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN) failed\n");
        return;
    }

    log_relay_state(relay_state);
}

int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "gpioSetMode(TOUCH_SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "gpioSetPullUpDown(TOUCH_SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "gpioSetMode(RELAY_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN, 0) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    relay_state = 0;
    log_relay_state(relay_state);

    if (gpioSetAlertFunc(TOUCH_SENSOR_PIN, touch_callback) != 0) {
        fprintf(stderr, "gpioSetAlertFunc(TOUCH_SENSOR_PIN) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        gpioDelay(100000);  /* 100 ms sleep to reduce CPU usage */
    }

    /* Cleanup on exit */
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "gpioWrite(RELAY_PIN, 0) failed during cleanup\n");
    }
    relay_state = 0;
    log_relay_state(relay_state);
    gpioTerminate();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

