#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25
#define MOISTURE_THRESHOLD 30
#define IRRIGATION_DURATION 5
#define LOG_FILE "irrigation_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_relay(int pin, int state) {
    if (gpioWrite(pin, state) < 0) {
        fprintf(stderr, "Error: gpioWrite(%d, %d) failed\n", pin, state);
        return -1;
    }
    return 0;
}

static int log_event(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed\n");
        return -1;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return -1;
    }

    if (fprintf(log_file, "%s - Relay %d - Moisture Level: %d\n",
                timestamp, relay_number, moisture_level) < 0) {
        fprintf(stderr, "Error: fprintf to log file failed\n");
        return -1;
    }

    if (fflush(log_file) != 0) {
        fprintf(stderr, "Error: fflush failed\n");
        return -1;
    }

    return 0;
}

static void cleanup(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        gpioWrite(pins[i], 1);
        gpioSetMode(pins[i], PI_INPUT);
    }
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    const char *pin_names[] = {"RELAY1", "RELAY2", "RELAY3", "RELAY4"};

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) < 0) {
            fprintf(stderr, "Error: gpioSetMode(%s, PI_OUTPUT) failed\n", pin_names[i]);
            cleanup();
            return EXIT_FAILURE;
        }
        if (gpioWrite(pins[i], 1) < 0) {
            fprintf(stderr, "Error: gpioWrite(%s, 1) failed\n", pin_names[i]);
            cleanup();
            return EXIT_FAILURE;
        }
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    srand((unsigned int)time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGTERM) failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Smart Irrigation System started. Press Ctrl+C to exit.\n");

    while (running) {
        int moisture_level = rand() % 101;
        printf("Soil Moisture Level: %d\n", moisture_level);

        if (moisture_level < MOISTURE_THRESHOLD) {
            printf("Moisture level below threshold. Activating relays.\n");

            for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
                if (set_relay(pins[i], 0) != 0) {
                    fprintf(stderr, "Error: failed to activate relay %zu\n", i + 1);
                } else {
                    if (log_event((int)(i + 1), moisture_level) != 0) {
                        fprintf(stderr, "Error: failed to log event for relay %zu\n", i + 1);
                    }
                }

                if (i < sizeof(pins) / sizeof(pins[0]) - 1) {
                    sleep(1);
                }
            }

            sleep(IRRIGATION_DURATION);

            for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
                if (set_relay(pins[i], 1) != 0) {
                    fprintf(stderr, "Error: failed to deactivate relay %zu\n", i + 1);
                }
            }
        }

        if (running) {
            sleep(10);
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

