/*
 * Automated plant watering system for Raspberry Pi Zero W.
 *
 * Two SG90 servos:
 *   - Valve servo  : GPIO17 (BCM), physical pin 11
 *   - Nozzle servo : GPIO18 (BCM), physical pin 12
 *
 * Library: pigpio (or a compatible servo driver library).
 *
 * Build: gcc -Wall -Wextra -O2 -o watering watering.c -lpigpio -lrt
 * Run:   sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM numbering) ---- */
#define VALVE_SERVO_PIN  17
#define NOZZLE_SERVO_PIN 18

/* ---- Servo pulse-width limits (microseconds) ---- */
#define SERVO_MIN_PW  500   /* 0 degrees   */
#define SERVO_MAX_PW  2500  /* 180 degrees */
#define SERVO_STOP    0     /* stop sending pulses */

/* ---- Angle-to-pulse-width mapping for SG90 ---- */
#define VALVE_OPEN_PW  1500  /* ~90 degrees */
#define VALVE_CLOSE_PW 500   /* ~0 degrees  */

#define NOZZLE_0_PW    500
#define NOZZLE_45_PW   1000
#define NOZZLE_90_PW   1500
#define NOZZLE_135_PW  2000
#define NOZZLE_180_PW  2500

/* ---- Moisture thresholds ---- */
#define MOISTURE_THRESHOLD 50
#define MOISTURE_MIN       20
#define MOISTURE_MAX       100

/* ---- Timing constants ---- */
#define WATERING_CYCLE_DELAY_S  5
#define NOZZLE_STEP_DELAY_S     2
#define SPRAY_HOLD_S            5
#define SERVO_RETRY_COUNT       3
#define SERVO_RETRY_DELAY_MS    100
#define MOISTURE_CYCLE_DELAY_S  1

/* ---- Simulated moisture sequence ---- */
static const int moisture_sequence[] = {20, 40, 60, 80, 100};
static const int moisture_seq_len =
    (int)(sizeof(moisture_sequence) / sizeof(moisture_sequence[0]));
static int moisture_index = 0;

/* ---- Signal handling ---- */
static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ---- Utility: sleep that survives EINTR ---- */
static void sleep_interruptible(unsigned seconds)
{
    while (seconds > 0 && g_running) {
        seconds -= (unsigned)sleep(seconds);
    }
}

/* ---- Read simulated soil moisture ---- */
static int read_soil_moisture(void)
{
    int m = moisture_sequence[moisture_index];
    moisture_index = (moisture_index + 1) % moisture_seq_len;
    return m;
}

/*
 * Set a servo to a given pulse width.
 * Returns 0 on success, -1 on failure.
 */
static int set_servo(int pin, int pulse_width)
{
    for (int attempt = 0; attempt < SERVO_RETRY_COUNT; ++attempt) {
        if (gpioServo(pin, pulse_width) == 0) {
            return 0;
        }
        fprintf(stderr,
                "Warning: gpioServo(pin=%d, pw=%d) failed (attempt %d/%d)\n",
                pin, pulse_width, attempt + 1, SERVO_RETRY_COUNT);
        if (attempt < SERVO_RETRY_COUNT - 1) {
            gpioDelay(SERVO_RETRY_DELAY_MS * 1000);
        }
    }
    return -1;
}

/*
 * Stop a servo by sending zero pulse width.
 * Returns 0 on success, -1 on failure.
 */
static int stop_servo(int pin)
{
    return set_servo(pin, SERVO_STOP);
}

/*
 * Open the valve to ~90 degrees.
 * Returns 0 on success, -1 on failure.
 */
static int open_valve(void)
{
    if (set_servo(VALVE_SERVO_PIN, VALVE_OPEN_PW) != 0) {
        fprintf(stderr, "Error: failed to open valve servo\n");
        return -1;
    }
    gpioDelay(500 * 1000); /* 500 ms to reach position */
    return 0;
}

/*
 * Close the valve to ~0 degrees.
 * Returns 0 on success, -1 on failure.
 */
static int close_valve(void)
{
    if (set_servo(VALVE_SERVO_PIN, VALVE_CLOSE_PW) != 0) {
        fprintf(stderr, "Error: failed to close valve servo\n");
        return -1;
    }
    gpioDelay(500 * 1000); /* 500 ms to reach position */
    return 0;
}

/*
 * Move the nozzle through the five sweep angles.
 * Returns 0 on success, -1 if any step fails.
 */
static int sweep_nozzle(void)
{
    const int pw[] = {NOZZLE_0_PW, NOZZLE_45_PW, NOZZLE_90_PW,
                      NOZZLE_135_PW, NOZZLE_180_PW};
    const int n_steps = (int)(sizeof(pw) / sizeof(pw[0]));

    for (int i = 0; i < n_steps && g_running; ++i) {
        if (set_servo(NOZZLE_SERVO_PIN, pw[i]) != 0) {
            fprintf(stderr, "Error: nozzle step %d (pw=%d) failed\n", i, pw[i]);
            return -1;
        }
        gpioDelay(NOZZLE_STEP_DELAY_S * 1000000);
    }
    return 0;
}

/*
 * Perform a full watering cycle.
 * Returns 0 on success, -1 on unrecoverable error.
 */
static int water_plant(void)
{
    printf("Watering plant...\n");
    fflush(stdout);

    if (open_valve() != 0) {
        fprintf(stderr, "Error: valve open failed, aborting cycle\n");
        return -1;
    }

    if (sweep_nozzle() != 0) {
        fprintf(stderr, "Error: nozzle sweep failed, aborting cycle\n");
        (void)close_valve();
        return -1;
    }

    /* Hold the spray for the required duration */
    sleep_interruptible(SPRAY_HOLD_S);
    if (!g_running) {
        fprintf(stderr, "Warning: watering interrupted during spray hold\n");
    }

    if (close_valve() != 0) {
        fprintf(stderr, "Critical: failed to close valve\n");
        return -1;
    }

    printf("Watering complete.\n");
    fflush(stdout);
    return 0;
}

int main(void)
{
    /* ---- Initialize pigpio ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* ---- Install signal handlers ---- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Automated Plant Watering System started.\n");
    printf("Valve: GPIO%d, Nozzle: GPIO%d\n", VALVE_SERVO_PIN, NOZZLE_SERVO_PIN);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    /* ---- Main loop ---- */
    while (g_running) {
        int moisture = read_soil_moisture();
        printf("Soil moisture: %d%%\n", moisture);
        fflush(stdout);

        if (moisture < MOISTURE_THRESHOLD) {
            if (water_plant() != 0) {
                fprintf(stderr, "Error: watering cycle failed, exiting\n");
                break;
            }
        } else {
            printf("Moisture above threshold, skipping watering.\n");
            fflush(stdout);
        }

        sleep_interruptible(WATERING_CYCLE_DELAY_S);
    }

    /* ---- Graceful shutdown ---- */
    printf("\nShutting down...\n");
    fflush(stdout);

    /* Stop both servos before terminating */
    (void)stop_servo(VALVE_SERVO_PIN);
    (void)stop_servo(NOZZLE_SERVO_PIN);

    gpioTerminate();
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

