#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TRIGGER_PIN 17
#define ECHO_PIN    18

#define TRIGGER_PULSE_US  10
#define ECHO_TIMEOUT_US   50000   /* 50 ms */
#define SAMPLE_INTERVAL_S 1
#define MIN_CYCLE_DELAY_US 60000  /* 60 ms between measurements */

static volatile sig_atomic_t g_running = 1;
static FILE *g_log = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Measure distance in centimetres.
 * Returns >= 0 on success, -1 on timeout or GPIO error.
 */
static int measure_distance(void)
{
    uint32_t start_tick, end_tick;

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1;
    }
    gpioDelay(5);

    /* 10 µs trigger pulse */
    if (gpioWrite(TRIGGER_PIN, 1) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 1) failed\n");
        return -1;
    }
    gpioDelay(TRIGGER_PULSE_US);
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger, 0) failed\n");
        return -1;
    }

    /* Wait for echo rising edge (timeout) */
    start_tick = gpioTick();
    while (gpioRead(ECHO_PIN) == 0) {
        if ((int32_t)(gpioTick() - start_tick) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo rising-edge timeout\n");
            return -1;
        }
    }
    uint32_t echo_start = gpioTick();

    /* Wait for echo falling edge (timeout) */
    while (gpioRead(ECHO_PIN) == 1) {
        if ((int32_t)(gpioTick() - echo_start) > ECHO_TIMEOUT_US) {
            fprintf(stderr, "Error: echo falling-edge timeout\n");
            return -1;
        }
    }
    end_tick = gpioTick();

    uint32_t diff = end_tick - echo_start;
    /* speed of sound 343 m/s => 0.0343 cm/µs; distance = (diff / 2) * 0.0343 */
    return (int)((diff / 2.0) * 0.0343);
}

int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(trigger) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode(echo) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts low */
    if (gpioWrite(TRIGGER_PIN, 0) < 0) {
        fprintf(stderr, "Error: gpioWrite(trigger init) failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log = fopen("distance_log.txt", "a");
    if (g_log == NULL) {
        perror("fopen(distance_log.txt)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("HC-SR04 distance logger started. Press Ctrl+C to stop.\n");

    while (g_running) {
        int distance = measure_distance();

        if (distance >= 0) {
            fprintf(g_log, "%ld,%d\n", (long)time(NULL), distance);
            fflush(g_log);
            printf("Distance: %d cm\n", distance);
        } else {
            fprintf(g_log, "%ld,-1\n", (long)time(NULL));
            fflush(g_log);
            fprintf(stderr, "Error: measurement failed, wrote -1 to log\n");
        }

        /* Sleep SAMPLE_INTERVAL_S, but wake early on signal */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++) {
            gpioDelay(100000); /* 100 ms */
        }

        /* Ensure at least MIN_CYCLE_DELAY_US between measurements */
        gpioDelay(MIN_CYCLE_DELAY_US);
    }

    /* Clean shutdown */
    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

