#include <pigpio.h>

/* ---- Configuration ---- */
#define I2C_BUS              1
#define VL53L1X_ADDR         0x29          /* Default 7-bit I2C address */
#define RELAY_PIN            18            /* BCM GPIO18 */
#define DISTANCE_THRESHOLD   50            /* cm */
#define POLL_DELAY_US        100000        /* 100 ms */

/* ---- VL53L1X register addresses (16-bit, big-endian on bus) ---- */
#define VL53L1X_REG_SOFT_RESET       0x000B
#define VL53L1X_REG_SYSTEM_MODE      0x0001
#define VL53L1X_REG_RANGE_STATUS     0x0089
#define VL53L1X_REG_RESULT_DISTANCE  0x0096

#define VL53L1X_SOFT_RESET_VALUE     0x00
#define VL53L1X_SYSTEM_MODE_START    0x40
#define VL53L1X_RANGE_STATUS_READY   0x01

/* ---- Globals for cleanup ---- */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address followed by a single data byte.     */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int vl53l1x_write8(int handle, uint16_t reg, uint8_t value)
{
    char buf[3];
    buf[0] = (reg >> 8) & 0xFF;
    buf[1] = reg & 0xFF;
    buf[2] = (char)value;

    if (i2cWriteDevice(handle, buf, 3) != 3) {
        fprintf(stderr, "[ERROR] I2C write to reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Write a 16-bit register address, then read N bytes.                 */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int vl53l1x_read(int handle, uint16_t reg, uint8_t *data, int len)
{
    char addr[2];
    addr[0] = (reg >> 8) & 0xFF;
    addr[1] = reg & 0xFF;

    if (i2cWriteDevice(handle, addr, 2) != 2) {
        fprintf(stderr, "[ERROR] I2C write (addr) for reg 0x%04X failed\n", reg);
        return -1;
    }
    if (i2cReadDevice(handle, (char *)data, len) != len) {
        fprintf(stderr, "[ERROR] I2C read from reg 0x%04X failed\n", reg);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise the VL53L1X: soft reset, then start ranging.             */
/* Returns 0 on success, -1 on error.                                  */
/* ------------------------------------------------------------------ */
static int vl53l1x_init(int handle)
{
    /* Soft reset */
    if (vl53l1x_write8(handle, VL53L1X_REG_SOFT_RESET,
                       VL53L1X_SOFT_RESET_VALUE) != 0)
        return -1;
    gpioDelay(1000);  /* 1 ms settle */

    /* Start continuous ranging mode */
    if (vl53l1x_write8(handle, VL53L1X_REG_SYSTEM_MODE,
                       VL53L1X_SYSTEM_MODE_START) != 0)
        return -1;
    gpioDelay(1000);  /* 1 ms for first measurement */

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the current distance in cm.                                    */
/* Returns 0 on success and stores distance in *out_cm.                */
/* Returns -1 on I2C error, -2 if data not ready.                      */
/* ------------------------------------------------------------------ */
static int vl53l1x_read_distance(int handle, int *out_cm)
{
    uint8_t status = 0;
    uint8_t dist_buf[2] = {0};

    /* Poll range status until data is ready */
    for (int i = 0; i < 10; i++) {
        if (vl53l1x_read(handle, VL53L1X_REG_RANGE_STATUS, &status, 1) != 0)
            return -1;
        if (status & VL53L1X_RANGE_STATUS_READY)
            break;
        gpioDelay(5000);  /* 5 ms */
    }
    if (!(status & VL53L1X_RANGE_STATUS_READY))
        return -2;  /* timeout */

    /* Read 2-byte distance (big-endian) */
    if (vl53l1x_read(handle, VL53L1X_REG_RESULT_DISTANCE, dist_buf, 2) != 0)
        return -1;

    *out_cm = ((int)dist_buf[0] << 8) | dist_buf[1];
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "[FATAL] i2cOpen failed (handle=%d)\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise sensor */
    if (vl53l1x_init(i2c_handle) != 0) {
        fprintf(stderr, "[FATAL] VL53L1X initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure relay pin */
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0);

    /* Signal handling */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("VL53L1X distance monitor started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (!terminate) {
        int distance = 0;
        int rc = vl53l1x_read_distance(i2c_handle, &distance);

        if (rc == 0) {
            printf("Distance: %d cm\n", distance);
            gpioWrite(RELAY_PIN, distance <= DISTANCE_THRESHOLD ? 1 : 0);
        } else if (rc == -2) {
            fprintf(stderr, "[WARN] Sensor data not ready, retrying...\n");
        } else {
            fprintf(stderr, "[WARN] I2C read error, continuing...\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

