#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define MPU6050_REG_SMPLRT_DIV   0x19
#define MPU6050_REG_CONFIG       0x1A
#define MPU6050_REG_GYRO_CONFIG  0x1B
#define MPU6050_REG_ACCEL_CONFIG 0x1C
#define MPU6050_REG_PWR_MGMT_1   0x6B
#define MPU6050_REG_GYRO_XOUT_H  0x43

/* Sensitivity scale factor for default ±250 °/s range */
#define GYRO_SCALE 131.0f

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an 8-bit register */
static int i2c_write_reg8(int fd, uint8_t reg, uint8_t value)
{
    uint8_t buf[2] = { reg, value };
    ssize_t ret = write(fd, buf, sizeof(buf));
    if (ret != (ssize_t)sizeof(buf)) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s (ret=%zd)\n",
                reg, strerror(errno), ret);
        return -1;
    }
    return 0;
}

/* Read N bytes starting from an 8-bit register */
static int i2c_read_regs(int fd, uint8_t reg, uint8_t *buf, size_t len)
{
    ssize_t ret = write(fd, &reg, 1);
    if (ret != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s (ret=%zd)\n",
                reg, strerror(errno), ret);
        return -1;
    }

    ret = read(fd, buf, len);
    if (ret != (ssize_t)len) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s (ret=%zd)\n",
                reg, strerror(errno), ret);
        return -1;
    }
    return 0;
}

static int init_mpu6050(int fd)
{
    /* Wake up the MPU-6050 (clear SLEEP bit) */
    if (i2c_write_reg8(fd, MPU6050_REG_PWR_MGMT_1, 0x00) < 0)
        return -1;
    usleep(100000); /* 100 ms stabilization */

    /* Sample rate divider = 7 => 1 kHz / (1 + 7) = 125 Hz */
    if (i2c_write_reg8(fd, MPU6050_REG_SMPLRT_DIV, 0x07) < 0)
        return -1;

    /* DLPF_CFG = 3 => bandwidth 44 Hz, delay 4.9 ms */
    if (i2c_write_reg8(fd, MPU6050_REG_CONFIG, 0x03) < 0)
        return -1;

    /* Gyro full-scale range ±250 °/s (FS_SEL = 0) */
    if (i2c_write_reg8(fd, MPU6050_REG_GYRO_CONFIG, 0x00) < 0)
        return -1;

    /* Accel full-scale range ±2g (AFS_SEL = 0) */
    if (i2c_write_reg8(fd, MPU6050_REG_ACCEL_CONFIG, 0x00) < 0)
        return -1;

    return 0;
}

static int read_gyro_data(int fd, float *gx, float *gy, float *gz)
{
    uint8_t buf[6];

    if (i2c_read_regs(fd, MPU6050_REG_GYRO_XOUT_H, buf, sizeof(buf)) < 0)
        return -1;

    int16_t raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    int16_t raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    int16_t raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    *gx = (float)raw_x / GYRO_SCALE;
    *gy = (float)raw_y / GYRO_SCALE;
    *gz = (float)raw_z / GYRO_SCALE;

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open("/dev/i2c-1", O_RDWR);
    if (g_i2c_fd < 0) {
        fprintf(stderr, "Failed to open /dev/i2c-1: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address 0x%02X: %s\n",
                MPU6050_ADDR, strerror(errno));
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    if (init_mpu6050(g_i2c_fd) < 0) {
        fprintf(stderr, "MPU-6050 initialization failed (sensor absent or bus error).\n");
        close(g_i2c_fd);
        g_i2c_fd = -1;
        return EXIT_FAILURE;
    }

    printf("MPU-6050 initialized. Reading gyro data (Ctrl+C to exit)...\n");

    while (g_running) {
        float gx, gy, gz;

        if (read_gyro_data(g_i2c_fd, &gx, &gy, &gz) < 0) {
            fprintf(stderr, "Error reading gyro data. Retrying...\n");
            usleep(100000);
            continue;
        }

        printf("X: %.2f °/s, Y: %.2f °/s, Z: %.2f °/s\n", gx, gy, gz);
        usleep(100000); /* 100 ms */
    }

    printf("\nExiting cleanly...\n");
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
    return EXIT_SUCCESS;
}

