/*
 * Automated plant watering system for Raspberry Pi 4 Model B.
 *
 * Four 5 V relay modules are sequenced on BCM GPIO17, GPIO18, GPIO27, GPIO22.
 * Each relay is driven HIGH (inactive) at startup, then each is driven
 * LOW (active) for 5 s, then released HIGH (inactive).  This repeats once
 * every 24 h, with a full-cycle timestamp logged to watering_log.txt.
 *
 * Build:  gcc -O2 -Wall -Wextra -o watering watering.c -lgpiod
 * Run:    sudo ./watering
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

#define NUM_RELAYS      4
#define WATER_DURATION  5          /* seconds per relay activation */
#define CYCLE_PERIOD    86400      /* seconds between full cycles   */
#define POLL_INTERVAL   60         /* seconds between relay activations */
#define LOG_FILE        "watering_log.txt"

static const unsigned int relay_pins[NUM_RELAYS] = {17, 18, 27, 22};

static volatile sig_atomic_t g_running = 1;
static struct gpiod_chip  *g_chip  = NULL;
static struct gpiod_line *g_lines[NUM_RELAYS];

/* ------------------------------------------------------------------ */
static void handle_signal(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = handle_signal;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int log_timestamp(void)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("fopen(" LOG_FILE ")");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time()");
        fclose(fp);
        return -1;
    }

    struct tm tm;
    if (localtime_r(&t, &tm) == NULL) {
        perror("localtime_r()");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec) < 0) {
        perror("fprintf()");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) == EOF) {
        perror("fclose()");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int set_all_lines(int value)
{
    for (int i = 0; i < NUM_RELAYS; i++) {
        if (gpiod_line_set_value(g_lines[i], value) < 0) {
            fprintf(stderr, "gpiod_line_set_value(pin %u, %d) failed: %s\n",
                    relay_pins[i], value, strerror(errno));
            return -1;
        }
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static int activate_relay(int idx)
{
    printf("Activating relay %d (BCM GPIO%u) for %d s...\n",
           idx + 1, relay_pins[idx], WATER_DURATION);
    fflush(stdout);

    if (gpiod_line_set_value(g_lines[idx], 0) < 0) {   /* active-low */
        fprintf(stderr, "Failed to activate relay %d: %s\n",
                idx + 1, strerror(errno));
        return -1;
    }

    /* Sleep in 1 s increments so signals are caught promptly. */
    for (int s = 0; s < WATER_DURATION && g_running; s++)
        sleep(1);

    if (gpiod_line_set_value(g_lines[idx], 1) < 0) {
        fprintf(stderr, "Failed to deactivate relay %d: %s\n",
                idx + 1, strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure all relays are left inactive (HIGH) before releasing. */
    if (g_chip)
        set_all_lines(1);

    for (int i = 0; i < NUM_RELAYS; i++) {
        if (g_lines[i])
            gpiod_line_release(g_lines[i]);
        g_lines[i] = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    if (install_signal_handlers() != 0)
        return EXIT_FAILURE;

    /* Open the default gpiochip (gpiochip0 on Pi 4). */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        fprintf(stderr, "Failed to open gpiochip0: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* Request each relay line as an output, initial value HIGH (inactive). */
    for (int i = 0; i < NUM_RELAYS; i++) {
        g_lines[i] = gpiod_chip_get_line(g_chip, relay_pins[i]);
        if (!g_lines[i]) {
            fprintf(stderr, "Failed to get GPIO line %u: %s\n",
                    relay_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }

        if (gpiod_line_request_output(g_lines[i], "plant-watering", 1) < 0) {
            fprintf(stderr, "Failed to request GPIO%u as output: %s\n",
                    relay_pins[i], strerror(errno));
            cleanup();
            return EXIT_FAILURE;
        }
    }

    printf("Plant watering system started.  Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (g_running) {
        time_t cycle_start = time(NULL);
        if (cycle_start == (time_t)-1) {
            perror("time()");
            break;
        }

        printf("--- Watering cycle start (%ld) ---\n", (long)cycle_start);
        fflush(stdout);

        for (int i = 0; i < NUM_RELAYS && g_running; i++) {
            if (activate_relay(i) != 0) {
                fprintf(stderr, "Relay %d activation failed; aborting cycle.\n",
                        i + 1);
                set_all_lines(1);
                break;
            }
        }

        if (!g_running)
            break;

        /* Log the full-cycle timestamp. */
        if (log_timestamp() != 0)
            fprintf(stderr, "Warning: failed to log timestamp.\n");

        /* Sleep until the next full-cycle boundary, checking for signals. */
        time_t now;
        do {
            now = time(NULL);
            if (now == (time_t)-1) {
                perror("time()");
                break;
            }
            if (g_running)
                sleep(1);
        } while (g_running && (now - cycle_start) < CYCLE_PERIOD);
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

