#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

#define PWM_FREQUENCY 1000
#define PWM_RANGE 255
#define SUNRISE_DURATION_SEC 1800
#define STEP_DELAY_SEC 1

static volatile sig_atomic_t program_running = 1;
static FILE *log_file = NULL;

static void log_event(const char *message) {
    if (!log_file) return;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(log_file, "[%s] %s\n", timestamp, message);
    fflush(log_file);
}

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Failed to set GPIO %d as output\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQUENCY) < 0) {
            fprintf(stderr, "Failed to set PWM frequency on GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) < 0) {
            fprintf(stderr, "Failed to set PWM range on GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Failed to initialize PWM to 0 on GPIO %d\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void set_relay_intensity(int pin, int intensity) {
    if (intensity < 0) intensity = 0;
    if (intensity > PWM_RANGE) intensity = PWM_RANGE;
    if (gpioPWM(pin, intensity) != 0) {
        char msg[128];
        snprintf(msg, sizeof(msg), "Failed to set PWM on GPIO %d to %d", pin, intensity);
        log_event(msg);
    }
}

static void cleanup_gpio(void) {
    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    for (size_t i = 0; i < sizeof(pins) / sizeof(pins[0]); i++) {
        gpioPWM(pins[i], 0);
    }
    gpioTerminate();
}

int main(void) {
    log_file = fopen("smart_lighting.log", "a");
    if (!log_file) {
        perror("Error opening log file");
        return EXIT_FAILURE;
    }

    log_event("Smart lighting sunrise program started");

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("Failed to set signal handlers");
        log_event("Failed to set signal handlers");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        log_event("GPIO initialization failed, exiting");
        fclose(log_file);
        return EXIT_FAILURE;
    }

    log_event("GPIO initialized successfully");

    int pins[] = {RELAY1_PIN, RELAY2_PIN, RELAY3_PIN, RELAY4_PIN};
    int num_pins = (int)(sizeof(pins) / sizeof(pins[0]));

    for (int i = 0; i <= SUNRISE_DURATION_SEC && program_running; i++) {
        int intensity = (int)(((float)i / SUNRISE_DURATION_SEC) * PWM_RANGE);
        for (int j = 0; j < num_pins; j++) {
            set_relay_intensity(pins[j], intensity);
        }
        sleep(STEP_DELAY_SEC);
    }

    if (!program_running) {
        log_event("Program interrupted by signal");
    } else {
        log_event("Sunrise effect completed");
    }

    cleanup_gpio();
    log_event("GPIO cleanup complete");
    fclose(log_file);
    return EXIT_SUCCESS;
}

