#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43

/* LED GPIO pin (BCM) */
#define LED_PIN 17

/* Circular buffer size */
#define BUFFER_SIZE 100

/* Sampling period (microseconds) */
#define SAMPLE_PERIOD_US 50000

/* Threshold for angular velocity (degrees/second) */
#define THRESHOLD 250.0f

/* Maximum consecutive re-initialization attempts */
#define MAX_REINIT_ATTEMPTS 3

/* Structure to hold gyroscope data with timestamp */
typedef struct {
    struct timespec timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

/* Circular buffer structure */
typedef struct {
    gyro_data_t buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

/* Global variables */
static int i2c_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int init_mpu6050(void);
static int read_gyro_data(float *x, float *y, float *z);
static void add_to_buffer(float x, float y, float z);
static void check_threshold(float x, float y, float z);
static void signal_handler(int signal);
static void cleanup(void);

/* Initialize the MPU-6050 */
static int init_mpu6050(void) {
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050.\n");
        return -1;
    }
    /* Allow time for the sensor to stabilize after waking up */
    gpioDelay(100000); /* 100 ms */
    return 0;
}

/* Read raw gyroscope data and convert to degrees/second */
static int read_gyro_data(float *x, float *y, float *z) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    /* Read 6 bytes starting from GYRO_XOUT_H */
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data.\n");
        return -1;
    }

    /* Combine high and low bytes (big-endian) */
    raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    /* Convert to degrees/second (131 LSB/deg/s) */
    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;

    return 0;
}

/* Add data to the circular buffer */
static void add_to_buffer(float x, float y, float z) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);

    gyro_buffer.buffer[gyro_buffer.head].timestamp = ts;
    gyro_buffer.buffer[gyro_buffer.head].x = x;
    gyro_buffer.buffer[gyro_buffer.head].y = y;
    gyro_buffer.buffer[gyro_buffer.head].z = z;

    gyro_buffer.head = (gyro_buffer.head + 1) % BUFFER_SIZE;
    if (gyro_buffer.count < BUFFER_SIZE) {
        gyro_buffer.count++;
    }
}

/* Check if the angular velocity exceeds the threshold */
static void check_threshold(float x, float y, float z) {
    if (fabsf(x) > THRESHOLD || fabsf(y) > THRESHOLD || fabsf(z) > THRESHOLD) {
        gpioWrite(LED_PIN, 1); /* Turn LED on */
    } else {
        gpioWrite(LED_PIN, 0); /* Turn LED off */
    }
}

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(LED_PIN, 0); /* Turn LED off */
    gpioTerminate();
}

int main(void) {
    float x, y, z;
    int reinit_attempts = 0;

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    /* Set LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0); /* Ensure LED is initially off */

    /* Initialize I2C */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device (handle=%d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed.\n");
        cleanup();
        return 1;
    }

    /* Initialize circular buffer */
    gyro_buffer.head = 0;
    gyro_buffer.count = 0;

    /* Set up signal handlers */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    /* Main loop */
    while (program_running) {
        /* Read gyroscope data */
        if (read_gyro_data(&x, &y, &z) == 0) {
            /* Add data to buffer */
            add_to_buffer(x, y, z);

            /* Check threshold */
            check_threshold(x, y, z);

            /* Reset re-initialization counter on success */
            reinit_attempts = 0;
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data.\n");

            /* Attempt to re-initialize I2C */
            i2cClose(i2c_handle);
            i2c_handle = -1;
            gpioDelay(1000000); /* Wait 1 second before re-initialization */

            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not re-open I2C device (handle=%d).\n", i2c_handle);
                reinit_attempts++;
                if (reinit_attempts >= MAX_REINIT_ATTEMPTS) {
                    fprintf(stderr, "Error: Max re-initialization attempts reached. Exiting.\n");
                    break;
                }
            } else {
                if (init_mpu6050() < 0) {
                    fprintf(stderr, "Error: MPU-6050 re-initialisation failed.\n");
                    reinit_attempts++;
                    if (reinit_attempts >= MAX_REINIT_ATTEMPTS) {
                        fprintf(stderr, "Error: Max re-initialization attempts reached. Exiting.\n");
                        break;
                    }
                } else {
                    reinit_attempts = 0;
                }
            }
        }

        /* Delay for the sampling period */
        gpioDelay(SAMPLE_PERIOD_US);
    }

    /* Cleanup */
    cleanup();

    return 0;
}

