#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>

#define SPI_DEVICE      "/dev/spidev0.0"
#define SPI_SPEED_HZ    1000000
#define SPI_MODE        SPI_MODE_0
#define SPI_BITS        8
#define CS_GPIO_CHIP    "/dev/gpiochip0"
#define CS_GPIO_LINE    8
#define LOG_FILE        "gyro_log.txt"
#define SAMPLE_DELAY_MS 10
#define MAX_RETRIES     3

/* MPU-9250 register addresses */
#define GYRO_XOUT_H     0x43
#define GYRO_YOUT_H     0x45
#define GYRO_ZOUT_H     0x47
#define PWR_MGMT_1      0x6B
#define WHO_AM_I        0x75

static volatile sig_atomic_t g_running = 1;
static int  g_spi_fd   = -1;
static FILE *g_log_fp  = NULL;
static struct gpiod_line *g_cs_line = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int spi_transfer(uint8_t *tx, uint8_t *rx, size_t len)
{
    struct spi_ioc_transfer tr;
    memset(&tr, 0, sizeof(tr));
    tr.tx_buf        = (unsigned long)tx;
    tr.rx_buf        = (unsigned long)rx;
    tr.len           = len;
    tr.speed_hz      = SPI_SPEED_HZ;
    tr.bits_per_word = SPI_BITS;
    tr.delay_usecs   = 0;
    tr.cs_change     = 0;

    if (gpiod_line_set_value(g_cs_line, 0) < 0) {
        fprintf(stderr, "Failed to assert CS line: %s\n", strerror(errno));
        return -1;
    }

    int ret = ioctl(g_spi_fd, SPI_IOC_MESSAGE(1), &tr);

    if (gpiod_line_set_value(g_cs_line, 1) < 0) {
        fprintf(stderr, "Failed to de-assert CS line: %s\n", strerror(errno));
        return -1;
    }

    if (ret < 1) {
        fprintf(stderr, "SPI transfer failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_gyro_data(int16_t *x, int16_t *y, int16_t *z)
{
    uint8_t tx[7] = { 0x80 | GYRO_XOUT_H, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00 };
    uint8_t rx[7] = { 0 };

    for (int attempt = 0; attempt < MAX_RETRIES; attempt++) {
        if (spi_transfer(tx, rx, sizeof(tx)) == 0) {
            *x = (int16_t)((rx[1] << 8) | rx[2]);
            *y = (int16_t)((rx[3] << 8) | rx[4]);
            *z = (int16_t)((rx[5] << 8) | rx[6]);
            return 0;
        }
        usleep(1000);
    }
    return -1;
}

static int log_data(FILE *fp, int16_t x, int16_t y, int16_t z)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        fprintf(stderr, "clock_gettime failed: %s\n", strerror(errno));
        return -1;
    }

    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);

    char timestamp[40];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info);
    snprintf(timestamp + strlen(timestamp),
             sizeof(timestamp) - strlen(timestamp),
             ".%09ld", ts.tv_nsec);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "fprintf to log failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_log_fp) {
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_cs_line) {
        gpiod_line_release(g_cs_line);
        g_cs_line = NULL;
    }
    if (g_spi_fd >= 0) {
        close(g_spi_fd);
        g_spi_fd = -1;
    }
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return 1;
    }

    g_spi_fd = open(SPI_DEVICE, O_RDWR);
    if (g_spi_fd < 0) {
        fprintf(stderr, "Failed to open %s: %s\n", SPI_DEVICE, strerror(errno));
        return 1;
    }

    uint8_t mode = SPI_MODE;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Failed to set SPI mode: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint8_t bits = SPI_BITS;
    if (ioctl(g_spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Failed to set SPI bits per word: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    uint32_t speed = SPI_SPEED_HZ;
    if (ioctl(g_spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Failed to set SPI max speed: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    struct gpiod_chip *chip = gpiod_chip_open(CS_GPIO_CHIP);
    if (!chip) {
        fprintf(stderr, "Failed to open %s: %s\n", CS_GPIO_CHIP, strerror(errno));
        cleanup();
        return 1;
    }

    g_cs_line = gpiod_chip_get_line(chip, CS_GPIO_LINE);
    if (!g_cs_line) {
        fprintf(stderr, "Failed to get GPIO line %d: %s\n", CS_GPIO_LINE, strerror(errno));
        gpiod_chip_close(chip);
        cleanup();
        return 1;
    }

    if (gpiod_line_request_output(g_cs_line, "mpu9250-cs", 1) < 0) {
        fprintf(stderr, "Failed to request CS line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        cleanup();
        return 1;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (!g_log_fp) {
        fprintf(stderr, "Failed to open %s: %s\n", LOG_FILE, strerror(errno));
        gpiod_chip_close(chip);
        cleanup();
        return 1;
    }

    /* Verify device identity */
    uint8_t whoami_tx[2] = { 0x80 | WHO_AM_I, 0x00 };
    uint8_t whoami_rx[2] = { 0 };
    if (spi_transfer(whoami_tx, whoami_rx, sizeof(whoami_tx)) != 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        cleanup();
        return 1;
    }
    if (whoami_rx[1] != 0x71) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x71\n", whoami_rx[1]);
        cleanup();
        return 1;
    }

    /* Wake up MPU-9250 (clear sleep bit) */
    uint8_t pwr_tx[2] = { 0x80 | PWR_MGMT_1, 0x00 };
    uint8_t pwr_rx[2] = { 0 };
    if (spi_transfer(pwr_tx, pwr_rx, sizeof(pwr_tx)) != 0) {
        fprintf(stderr, "Failed to wake up MPU-9250\n");
        cleanup();
        return 1;
    }
    usleep(100000);

    printf("MPU-9250 logging to %s. Press Ctrl+C to stop.\n", LOG_FILE);

    while (g_running) {
        int16_t x, y, z;
        if (read_gyro_data(&x, &y, &z) == 0) {
            if (log_data(g_log_fp, x, y, z) != 0) {
                fprintf(stderr, "Logging failed, continuing...\n");
            }
        } else {
            fprintf(stderr, "Gyro read failed after %d retries, continuing...\n", MAX_RETRIES);
        }
        usleep(SAMPLE_DELAY_MS * 1000);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return 0;
}

