#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define SPI_CHANNEL 0
#define SPI_SPEED 3900000
#define SPI_MODE 0
#define GYRO_THRESHOLD 200.0f
#define LED_GPIO 17
#define BUFFER_SIZE 64
#define SAMPLE_DELAY_US 100000

#define MPU6050_ADDR 0x68
#define MPU6050_PWR_MGMT_1 0x6B
#define MPU6050_GYRO_XOUT_H 0x43

typedef struct {
    struct timespec timestamp;
    float x, y, z;
} gyro_data_t;

static gyro_data_t gyro_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int spi_handle = -1;
static volatile sig_atomic_t program_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    program_running = 0;
}

static int init_spi(void) {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, (1 << 8) | SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

static int init_mpu6050(void) {
    char buf[2] = {MPU6050_PWR_MGMT_1, 0x00};
    if (spiWrite(spi_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to PWR_MGMT_1\n");
        return -1;
    }
    gpioDelay(100000);
    return 0;
}

static int read_gyro_data(float *x, float *y, float *z) {
    char tx[7] = {MPU6050_GYRO_XOUT_H, 0, 0, 0, 0, 0, 0};
    char rx[7] = {0};

    if (spiXfer(spi_handle, tx, rx, 7) != 7) {
        fprintf(stderr, "Error during SPI transfer\n");
        return -1;
    }

    int16_t raw_x = (int16_t)((rx[1] << 8) | rx[2]);
    int16_t raw_y = (int16_t)((rx[3] << 8) | rx[4]);
    int16_t raw_z = (int16_t)((rx[5] << 8) | rx[6]);

    *x = (float)raw_x / 131.0f;
    *y = (float)raw_y / 131.0f;
    *z = (float)raw_z / 131.0f;

    return 0;
}

static void add_to_buffer(float x, float y, float z) {
    clock_gettime(CLOCK_REALTIME, &gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

static bool check_threshold(float x, float y, float z) {
    return (fabsf(x) > GYRO_THRESHOLD || fabsf(y) > GYRO_THRESHOLD || fabsf(z) > GYRO_THRESHOLD);
}

static void blink_led(void) {
    gpioWrite(LED_GPIO, 1);
    gpioDelay(500000);
    gpioWrite(LED_GPIO, 0);
    gpioDelay(500000);
}

static void print_buffer(void) {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int idx = (buffer_index + i) % BUFFER_SIZE;
        printf("%ld.%09ld,%.2f,%.2f,%.2f\n",
               gyro_buffer[idx].timestamp.tv_sec,
               gyro_buffer[idx].timestamp.tv_nsec,
               gyro_buffer[idx].x,
               gyro_buffer[idx].y,
               gyro_buffer[idx].z);
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    if (init_mpu6050() != 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioWrite(LED_GPIO, 0);

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    float x, y, z;
    while (program_running) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            add_to_buffer(x, y, z);
            if (check_threshold(x, y, z)) {
                blink_led();
            }
        } else {
            fprintf(stderr, "Failed to read gyro data\n");
        }
        gpioDelay(SAMPLE_DELAY_US);
    }

    print_buffer();

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioWrite(LED_GPIO, 0);
    gpioTerminate();

    return 0;
}

