#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

/* LED GPIO pin (BCM numbering) */
#define LED_PIN 21

/* Tilt threshold in degrees */
#define TILT_THRESHOLD 45.0

/* Global variables for cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* Signal handler for Ctrl+C */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Function to initialize the MPU-6050 */
static int init_mpu6050(int handle) {
    /* Wake up the MPU-6050 (clear sleep bit) */
    if (i2cWriteByteData(handle, PWR_MGMT_1, 0x00) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }
    return 0;
}

/* Function to read raw accelerometer data */
static int read_raw_accel(int handle, int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];

    if (i2cReadI2CBlockData(handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data\n");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

/* Function to calculate roll and pitch angles */
static void calculate_tilt(int16_t x, int16_t y, int16_t z, float *roll, float *pitch) {
    float x_f = (float)x;
    float y_f = (float)y;
    float z_f = (float)z;

    *roll  = atan2f(y_f, z_f) * 180.0f / M_PI;
    *pitch = atan2f(-x_f, sqrtf(y_f * y_f + z_f * z_f)) * 180.0f / M_PI;
}

/* Function to log tilt data to a file */
static void log_tilt_data(float roll, float pitch) {
    FILE *fp = fopen("tilt_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open tilt_log.txt for appending\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d,%.2f,%.2f\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, roll, pitch);

    fclose(fp);
}

/* Function to control the LED */
static void control_led(float roll, float pitch) {
    if (fabsf(roll) > TILT_THRESHOLD || fabsf(pitch) > TILT_THRESHOLD) {
        gpioWrite(LED_PIN, 1);
    } else {
        gpioWrite(LED_PIN, 0);
    }
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 */
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus 1 at address 0x%02X\n", MPU6050_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 */
    if (init_mpu6050(i2c_handle) < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set LED pin as output */
    gpioSetMode(LED_PIN, PI_OUTPUT);
    gpioWrite(LED_PIN, 0);

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    int16_t accel_x, accel_y, accel_z;
    float roll, pitch;

    /* Main loop */
    while (program_running) {
        if (read_raw_accel(i2c_handle, &accel_x, &accel_y, &accel_z) == 0) {
            calculate_tilt(accel_x, accel_y, accel_z, &roll, &pitch);
            printf("Roll: %.2f, Pitch: %.2f\n", roll, pitch);
            log_tilt_data(roll, pitch);
            control_led(roll, pitch);
        } else {
            fprintf(stderr, "Warning: Failed to read sensor data, continuing...\n");
        }

        gpioDelay(100000); /* 100 ms delay (microseconds) */
    }

    /* Cleanup */
    gpioWrite(LED_PIN, 0);
    i2cClose(i2c_handle);
    gpioTerminate();

    return EXIT_SUCCESS;
}

