#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define SI1145_ADDR 0x60
#define I2C_BUS "/dev/i2c-1"
#define LED_GPIO 17
#define PROXIMITY_THRESHOLD 100
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define SAMPLE_INTERVAL_MS 100

#define SI1145_REG_PART_ID 0x00
#define SI1145_REG_HW_KEY 0x07
#define SI1145_REG_MEAS_RATE0 0x08
#define SI1145_REG_ALS_RATE0 0x09
#define SI1145_REG_PS_RATE0 0x0A
#define SI1145_REG_ALS_VIS_DATA0 0x22
#define SI1145_REG_PS1_DATA0 0x26
#define SI1145_REG_COMMAND 0x30
#define SI1145_REG_RESPONSE 0x20

#define SI1145_CMD_RESET 0x01
#define SI1145_CMD_ALS_FORCE 0x06
#define SI1145_CMD_PS_FORCE 0x05
#define SI1145_CMD_PSALS_FORCE 0x07

static volatile sig_atomic_t running = 1;
static int i2c_fd = -1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C write to reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        fprintf(stderr, "I2C read from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "I2C write (reg select 0x%02X) failed: %s\n", reg, strerror(errno));
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        fprintf(stderr, "I2C read16 from reg 0x%02X failed: %s\n", reg, strerror(errno));
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int si1145_wait_response(int fd) {
    uint8_t resp;
    for (int i = 0; i < 10; i++) {
        if (i2c_read_reg8(fd, SI1145_REG_RESPONSE, &resp) != 0) return -1;
        if ((resp & 0x0F) != 0x0F) return 0;
        usleep(1000);
    }
    fprintf(stderr, "Si1145 response timeout\n");
    return -1;
}

static int si1145_init(int fd) {
    uint8_t part_id;
    if (i2c_read_reg8(fd, SI1145_REG_PART_ID, &part_id) != 0) return -1;
    if (part_id != 0x45) {
        fprintf(stderr, "Unexpected Si1145 part ID: 0x%02X\n", part_id);
        return -1;
    }
    if (i2c_write_reg8(fd, SI1145_REG_COMMAND, SI1145_CMD_RESET) != 0) return -1;
    usleep(10000);
    if (i2c_write_reg8(fd, SI1145_REG_HW_KEY, 0x17) != 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_MEAS_RATE0, 0x00) != 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_ALS_RATE0, 0x00) != 0) return -1;
    if (i2c_write_reg8(fd, SI1145_REG_PS_RATE0, 0x00) != 0) return -1;
    return 0;
}

