/*
 * ADXRS290 dual-axis gyroscope SPI reader for Raspberry Pi Zero W
 *
 * Wiring:
 *   ADXRS290 CS  -> GPIO8  (BCM)
 *   ADXRS290 SCLK-> GPIO11 (BCM)
 *   ADXRS290 DOUT-> GPIO9  (BCM)
 *   ADXRS290 DIN -> GPIO10 (BCM)
 *   ADXRS290 VDD -> 3.3 V
 *   ADXRS290 GND -> GND
 *
 * SPI channel 0, 1 MHz, mode 0 (CPOL=0, CPHA=0).
 *
 * Build: gcc -O2 -Wall -o gyro gyro.c -lpigpio -lrt
 * Run:   sudo ./gyro
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- ADXRS290 register definitions (from datasheet) ---- */
#define ADXRS290_REG_TEMP_H   0x02
#define ADXRS290_REG_TEMP_L   0x03
#define ADXRS290_REG_RATE_X_H 0x04
#define ADXRS290_REG_RATE_X_L 0x05
#define ADXRS290_REG_RATE_Y_H 0x06
#define ADXRS290_REG_RATE_Y_L 0x07
#define ADXRS290_REG_DIAG_STAT 0x08
#define ADXRS290_REG_PID       0x09
#define ADXRS290_REG_SN_H      0x0A
#define ADXRS290_REG_SN_L      0x0B

/* Read-bit for SPI transfers (datasheet: read = 1, write = 0) */
#define ADXRS290_READ_BIT 0x80

/* SPI configuration */
#define SPI_CHANNEL 0
#define SPI_SPEED   1000000  /* 1 MHz */
#define SPI_FLAGS   0        /* mode 0, active-low CE */

/* Sampling */
#define SAMPLE_PERIOD_US 10000  /* 10 ms -> ~100 Hz */
#define MAX_REINIT_ATTEMPTS 3

/* Globals for cleanup */
static int spi_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* SPI transfer helper                                                 */
/* ------------------------------------------------------------------ */
static int spi_transfer(uint8_t *tx, uint8_t *rx, int len)
{
    int ret = spiXfer(spi_handle, (char *)tx, (char *)rx, len);
    if (ret != len) {
        fprintf(stderr, "SPI transfer failed (returned %d, expected %d)\n",
                ret, len);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single 16-bit register (big-endian on ADXRS290)              */
/* ------------------------------------------------------------------ */
static int read_register(uint8_t reg, int16_t *out)
{
    uint8_t tx[2] = { (uint8_t)(reg | ADXRS290_READ_BIT), 0x00 };
    uint8_t rx[2] = { 0, 0 };

    if (spi_transfer(tx, rx, 2) != 0)
        return -1;

    /* rx[0] is the echoed command byte; rx[1] is the data byte */
    *out = (int16_t)((rx[1] << 8) | rx[0]);
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialise SPI                                                      */
/* ------------------------------------------------------------------ */
static int init_spi(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }

    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log one sample to CSV                                               */
/* ------------------------------------------------------------------ */
static int log_sample(int16_t rate_x, int16_t rate_y)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }

    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1.0e9;

    if (fprintf(fp, "%.6f,%d,%d\n", timestamp, rate_x, rate_y) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(fp) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    if (fp != NULL) {
        fflush(fp);
        fclose(fp);
        fp = NULL;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialise pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open CSV file */
    fp = fopen("gyro_data.csv", "w");
    if (fp == NULL) {
        perror("fopen");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header */
    if (fprintf(fp, "timestamp,rate_x,rate_y\n") < 0) {
        perror("fprintf header");
        fclose(fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (fflush(fp) != 0) {
        perror("fflush header");
        fclose(fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialise SPI */
    if (init_spi() != 0) {
        fclose(fp);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXRS290 gyro data logging started. Press Ctrl-C to stop.\n");

    int reinit_attempts = 0;

    while (!terminate) {
        int16_t rate_x = 0, rate_y = 0;

        if (read_register(ADXRS290_REG_RATE_X_H, &rate_x) != 0 ||
            read_register(ADXRS290_REG_RATE_Y_H, &rate_y) != 0) {
            fprintf(stderr, "SPI read error; re-initialising SPI...\n");
            reinit_attempts++;
            if (reinit_attempts >= MAX_REINIT_ATTEMPTS) {
                fprintf(stderr, "Max re-init attempts reached. Exiting.\n");
                break;
            }
            if (init_spi() != 0) {
                fprintf(stderr, "SPI re-init failed.\n");
                break;
            }
            continue;
        }

        reinit_attempts = 0;

        if (log_sample(rate_x, rate_y) != 0) {
            fprintf(stderr, "Logging failed. Exiting.\n");
            break;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

