    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("ADXRS290 gyro data logging started. Press Ctrl-C to stop.\n");

    int reinit_attempts = 0;

    while (!terminate) {
        int16_t rate_x = 0, rate_y = 0;

        if (read_register(ADXRS290_REG_RATE_X_H, &rate_x) != 0 ||
            read_register(ADXRS290_REG_RATE_Y_H, &rate_y) != 0) {
