            continue;
        }

        reinit_attempts = 0;

        if (log_sample(rate_x, rate_y) != 0) {
            fprintf(stderr, "Logging failed. Exiting.\n");
            break;
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

