/*
 * ADXRS290 dual-axis MEMS gyroscope reader for Raspberry Pi Zero W.
 *
 * SPI0: CE0=GPIO8, SCLK=GPIO11, MOSI=GPIO10, MISO=GPIO9
 * LED:  GPIO17 (BCM)
 *
 * Reads angular rate on X-axis (register 0x02, read bit 7 set) and
 * stores timestamped samples in a thread-safe circular buffer.
 * Lights the warning LED when the rate exceeds 20.0 deg/s.
 *
 * Build: gcc -O2 -Wall -o gyro_monitor gyro_monitor.c -lpigpio -lrt
 * Run:   sudo ./gyro_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <time.h>
#include <pthread.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define SPI_CHANNEL      0          /* SPI0 CE0 (BCM GPIO8) */
#define SPI_SPEED        1000000    /* 1 MHz */
#define SPI_FLAGS        0          /* mode 0, active-low CE */

#define LED_PIN          17         /* BCM GPIO17 */
#define THRESHOLD        20.0f      /* deg/s */

#define BUFFER_SIZE      100
#define SAMPLE_PERIOD_US 10000      /* 10 ms */

/* ADXRS290 register addresses (8-bit, MSB = 1 for read) */
#define REG_TEMP        0x06
#define REG_X_RATE      0x02
#define REG_Y_RATE      0x04
#define REG_Z_RATE      0x08
#define REG_XGYRO_OFF   0x0A
#define REG_YGYRO_OFF   0x0C
#define REG_ZGYRO_OFF   0x0E
#define REG_DIAG_STAT   0x00

/* ----------------------------- Data types ------------------------------- */
typedef struct {
    struct timespec timestamp;
    float           rate;          /* deg/s */
} gyro_data_t;

typedef struct {
    gyro_data_t data[BUFFER_SIZE];
    int         head;
    int         count;
    pthread_mutex_t mutex;
} circular_buffer_t;

/* ----------------------------- Globals ---------------------------------- */
static int               spi_handle = -1;
static circular_buffer_t gyro_buffer;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  init_spi(void);
static int  read_gyro_rate(float *rate_out);
static void add_to_buffer(const gyro_data_t *sample);
static void *buffer_thread(void *arg);
static void signal_handler(int sig);
static void cleanup(void);

/* ----------------------------- SPI init ---------------------------------- */
static int init_spi(void)
{
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "spiOpen failed: %s\n", pigpio_error(spi_handle));
        return -1;
    }
    return 0;
}

/*
 * Read a 16-bit register from the ADXRS290.
 *
 * Protocol (datasheet):
 *   TX: [reg_addr | 0x80, 0x00]   (MSB=1 -> read)
 *   RX: [don't care, data MSB]
 *   TX: [0x00, 0x00]              (dummy to clock out LSB)
 *   RX: [data LSB, don't care]
 *
 * Returns 0 on success, -1 on SPI transfer failure.
 */
static int read_register(uint8_t reg, uint16_t *value)
{
    char tx[2] = { (char)(reg | 0x80), 0x00 };
    char rx[2] = { 0, 0 };

    if (spiXfer(spi_handle, tx, rx, 2) != 2) {
        fprintf(stderr, "SPI read (reg 0x%02X) failed\n", reg);
        return -1;
    }

    /* rx[0] = don't care, rx[1] = data MSB */
    uint16_t raw = ((uint16_t)(uint8_t)rx[1] << 8) | (uint8_t)rx[0];

    /* ADXRS290: 16-bit two's complement, left-justified in 16 bits */
    if (raw & 0x8000) {
        raw |= 0xFFFF0000;          /* sign-extend */
    }
    *value = raw;
    return 0;
}

/*
 * Read X-axis angular rate.
 * Conversion: raw / 32768.0 * 250.0 = deg/s
 * (datasheet: 14-bit two's complement, full-scale ±250 deg/s)
 */
static int read_gyro_rate(float *rate_out)
{
    uint16_t raw;
    if (read_register(REG_X_RATE, &raw) != 0)
        return -1;

    int16_t signed_raw = (int16_t)raw;
    *rate_out = (float)signed_raw / 32768.0f * 250.0f;
    return 0;
}

/* ----------------------------- Circular buffer --------------------------- */
static void add_to_buffer(const gyro_data_t *sample)
{
    pthread_mutex_lock(&gyro_buffer.mutex);
    gyro_buffer.data[gyro_buffer.head] = *sample;
    gyro_buffer.head = (gyro_buffer.head + 1) % BUFFER_SIZE;
    if (gyro_buffer.count < BUFFER_SIZE)
        gyro_buffer.count++;
    pthread_mutex_unlock(&gyro_buffer.mutex);
}

static void *buffer_thread(void *arg)
{
    (void)arg;
    while (!terminate) {
        float rate;
        if (read_gyro_rate(&rate) == 0) {
            gyro_data_t sample;
            clock_gettime(CLOCK_MONOTONIC, &sample.timestamp);
            sample.rate = rate;
            add_to_buffer(&sample);
        } else {
            fprintf(stderr, "Failed to read gyro rate\n");
        }
        gpioDelay(SAMPLE_PERIOD_US);
    }
    return NULL;
}

/* ----------------------------- Signal / cleanup -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static void cleanup(void)
{
    if (spi_handle >= 0) {
        spiClose(spi_handle);
        spi_handle = -1;
    }
    gpioWrite(LED_PIN, 0);
    gpioTerminate();
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (init_spi() != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gpioWrite(LED_PIN, 0);

    if (pthread_mutex_init(&gyro_buffer.mutex, NULL) != 0) {
        fprintf(stderr, "Mutex init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }
    gyro_buffer.head  = 0;
    gyro_buffer.count = 0;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    pthread_t buf_tid;
    if (pthread_create(&buf_tid, NULL, buffer_thread, NULL) != 0) {
        perror("pthread_create");
        cleanup();
        return EXIT_FAILURE;
    }

    bool led_on = false;
    while (!terminate) {
        float rate;
        if (read_gyro_rate(&rate) == 0) {
            if (rate > THRESHOLD) {
                if (!led_on) {
                    gpioWrite(LED_PIN, 1);
                    led_on = true;
                }
            } else {
                if (led_on) {
                    gpioWrite(LED_PIN, 0);
                    led_on = false;
                }
            }
        }
        gpioDelay(100000); /* 100 ms */
    }

    pthread_join(buf_tid, NULL);
    pthread_mutex_destroy(&gyro_buffer.mutex);
    cleanup();
    return EXIT_SUCCESS;
}

