    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    pthread_t buf_tid;
    if (pthread_create(&buf_tid, NULL, buffer_thread, NULL) != 0) {
        perror("pthread_create");
        cleanup();
        return EXIT_FAILURE;
    }

    bool led_on = false;
    while (!terminate) {
        float rate;
        if (read_gyro_rate(&rate) == 0) {
            if (rate > THRESHOLD) {
                if (!led_on) {
                    gpioWrite(LED_PIN, 1);
                    led_on = true;
                }
            } else {
                if (led_on) {
                    gpioWrite(LED_PIN, 0);
                    led_on = false;
                }
            }
        }
        gpioDelay(100000); /* 100 ms */
    }

    pthread_join(buf_tid, NULL);
    pthread_mutex_destroy(&gyro_buffer.mutex);
    cleanup();
    return EXIT_SUCCESS;
}

