/*
 * Smart Sunset Simulator — Raspberry Pi Zero W
 *
 * Three dimmable lamps on BCM GPIO17, GPIO18, GPIO27 (hardware PWM-capable).
 * Fades each lamp sequentially from 100 % to 0 % over a user-defined
 * duration (1–3600 seconds) at 100 Hz, then exits.
 *
 * Build:  gcc -O2 -Wall -Wextra -o sunset sunset.c -lpigpio -lrt
 * Run:    sudo ./sunset <duration_seconds>
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LAMP1_PIN 17
#define LAMP2_PIN 18
#define LAMP3_PIN 27

#define PWM_FREQ_HZ   100          /* 100 Hz — smooth, visible dimming */
#define PWM_RANGE     255          /* duty-cycle range 0–255 */
#define MAX_DURATION  3600         /* seconds */

static volatile sig_atomic_t g_terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_terminate = 1;
}

static void install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0)
        perror("warning: sigaction(SIGINT)");
    if (sigaction(SIGTERM, &sa, NULL) != 0)
        perror("warning: sigaction(SIGTERM)");
}

/* ------------------------------------------------------------------ */
/* GPIO setup                                                          */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return -1;
    }

    const int pins[3] = { LAMP1_PIN, LAMP2_PIN, LAMP3_PIN };
    for (int i = 0; i < 3; i++) {
        if (gpioSetMode(pins[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: gpioSetMode(%d) failed.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMfrequency(pins[i], PWM_FREQ_HZ) < 0) {
            fprintf(stderr, "Error: gpioSetPWMfrequency(%d) failed.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        if (gpioSetPWMrange(pins[i], PWM_RANGE) != 0) {
            fprintf(stderr, "Error: gpioSetPWMrange(%d) failed.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
        /* Start with lamp off */
        if (gpioPWM(pins[i], 0) != 0) {
            fprintf(stderr, "Error: gpioPWM(%d, 0) initial off failed.\n", pins[i]);
            gpioTerminate();
            return -1;
        }
    }
    return 0;
}

static void cleanup_gpio(void)
{
    const int pins[3] = { LAMP1_PIN, LAMP2_PIN, LAMP3_PIN };
    for (int i = 0; i < 3; i++)
        gpioPWM(pins[i], 0);   /* best-effort lamp-off */
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Lamp control                                                        */
/* ------------------------------------------------------------------ */
static void set_lamp_brightness(int pin, int brightness)
{
    if (brightness < 0)   brightness = 0;
    if (brightness > 255) brightness = 255;
    gpioPWM(pin, brightness);
}

static void fade_lamp(int pin, int duration_ms)
{
    const int step_ms = 10;          /* 10 ms per step */
    const int num_steps = duration_ms / step_ms;
    if (num_steps <= 0) return;

    for (int step = 0; step <= num_steps && !g_terminate; step++) {
        int brightness = (int)(((float)step / num_steps) * PWM_RANGE);
        set_lamp_brightness(pin, brightness);
        gpioDelay(step_ms * 1000);   /* microseconds */
    }
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <duration_seconds>\n", argv[0]);
        fprintf(stderr, "  duration: 1–%d seconds\n", MAX_DURATION);
        return EXIT_FAILURE;
    }

    char *endptr = NULL;
    long duration = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0' || duration < 1 || duration > MAX_DURATION) {
        fprintf(stderr, "Error: duration must be an integer between 1 and %d.\n", MAX_DURATION);
        return EXIT_FAILURE;
    }

    install_signal_handlers();

    if (initialize_gpio() != 0)
        return EXIT_FAILURE;

    printf("Smart Sunset Simulator started.\n");
    printf("  Lamps : GPIO%d, GPIO%d, GPIO%d\n", LAMP1_PIN, LAMP2_PIN, LAMP3_PIN);
    printf("  PWM   : %d Hz, range 0–%d\n", PWM_FREQ_HZ, PWM_RANGE);
    printf("  Total fade duration: %ld s\n", duration);
    printf("Press Ctrl+C to abort early.\n\n");

    const int pins[3] = { LAMP1_PIN, LAMP2_PIN, LAMP3_PIN };
    const char *labels[3] = { "Lamp 1", "Lamp 2", "Lamp 3" };

    for (int i = 0; i < 3 && !g_terminate; i++) {
        printf("%s fading in %ld s...\n", labels[i], duration);
        fflush(stdout);
        fade_lamp(pins[i], (int)duration * 1000);
        if (g_terminate) {
            printf("\nInterrupted by signal — aborting.\n");
            break;
        }
        printf("%s fade complete.\n", labels[i]);
    }

    cleanup_gpio();
    printf("All lamps off. Goodbye.\n");
    return EXIT_SUCCESS;
}

