    if (i2cWriteByteData(i2c_handle, MPR121_MHDF, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NHDF, 0x05) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NCLF, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_FDLF, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NHDT, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, MPR121_NCLT, 0x00) < 0) return -1;
