#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23
#define LOG_FILE "flame_log.txt"
#define READ_INTERVAL_US 50000
#define CONSECUTIVE_READS 3

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int log_event(const char *message) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "time() failed: %s\n", strerror(errno));
        return -1;
    }
    struct tm *tstruct = localtime(&now);
    if (tstruct == NULL) {
        fprintf(stderr, "localtime() failed\n");
        return -1;
    }
    char buf[80];
    if (strftime(buf, sizeof(buf), "%Y-%m-%d %H:%M:%S", tstruct) == 0) {
        fprintf(stderr, "strftime() failed\n");
        return -1;
    }
    if (fprintf(log_file, "%s: %s\n", buf, message) < 0) {
        fprintf(stderr, "fprintf() failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "fflush() failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int read_flame_sensor(int pin) {
    int value = gpioRead(pin);
    if (value < 0) {
        fprintf(stderr, "gpioRead(%d) failed: %s\n", pin, pigpio_error(value));
        return -1;
    }
    return value;
}

static int control_output(int pin, int level) {
    int result = gpioWrite(pin, level);
    if (result < 0) {
        fprintf(stderr, "gpioWrite(%d, %d) failed: %s\n", pin, level, pigpio_error(result));
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set flame sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set buzzer pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LED_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LED pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set pull-up on flame sensor pin\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    int flame_detected = 0;

    while (running) {
        int low_count = 0;
        int error_flag = 0;

        for (int i = 0; i < CONSECUTIVE_READS; i++) {
            if (!running) break;
            int sensor_value = read_flame_sensor(FLAME_SENSOR_PIN);
            if (sensor_value < 0) {
                error_flag = 1;
                break;
            }
            if (sensor_value == 0) {
                low_count++;
            }
            if (i < CONSECUTIVE_READS - 1) {
                gpioDelay(READ_INTERVAL_US);
            }
        }

        if (error_flag) {
            fprintf(stderr, "Sensor read error encountered. Continuing...\n");
            gpioDelay(READ_INTERVAL_US);
            continue;
        }

        if (low_count == CONSECUTIVE_READS && !flame_detected) {
            flame_detected = 1;
            printf("Flame Detected!\n");
            if (log_event("Flame Detected") != 0) {
                fprintf(stderr, "Failed to log flame detection event\n");
            }
            if (control_output(BUZZER_PIN, 1) != 0 || control_output(LED_PIN, 1) != 0) {
                fprintf(stderr, "Failed to activate buzzer or LED\n");
            }
        } else if (low_count < CONSECUTIVE_READS && flame_detected) {
            flame_detected = 0;
            printf("Flame cleared.\n");
            if (control_output(BUZZER_PIN, 0) != 0 || control_output(LED_PIN, 0) != 0) {
                fprintf(stderr, "Failed to deactivate buzzer or LED\n");
            }
        }

        gpioDelay(READ_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    control_output(BUZZER_PIN, 0);
    control_output(LED_PIN, 0);
    cleanup();
    return EXIT_SUCCESS;
}

