#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23
#define MOTOR_A_ENABLE 24
#define MOTOR_B_ENABLE 25

#define PWM_RANGE 255
#define PWM_FREQ 1000
#define LOOP_DELAY_US 50000
#define OBSTACLE_THRESHOLD_CM 20.0f
#define REVERSE_SPEED 128

#define KP 1.0f
#define KI 0.01f
#define KD 0.1f

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static float integral = 0.0f;
static float previous_error = 0.0f;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static float simulate_tilt_error(void) {
    return ((float)rand() / (float)RAND_MAX) * 20.0f - 10.0f;
}

static float simulate_ultrasonic_distance(void) {
    return ((float)rand() / (float)RAND_MAX) * 398.0f + 2.0f;
}

static void set_motor_speed(int motor, int speed) {
    int fwd_pin, bwd_pin, en_pin;
    if (motor == 0) {
        fwd_pin = MOTOR_A_FORWARD;
        bwd_pin = MOTOR_A_BACKWARD;
        en_pin = MOTOR_A_ENABLE;
    } else if (motor == 1) {
        fwd_pin = MOTOR_B_FORWARD;
        bwd_pin = MOTOR_B_BACKWARD;
        en_pin = MOTOR_B_ENABLE;
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor);
        return;
    }

    if (speed > 0) {
        gpioWrite(fwd_pin, 1);
        gpioWrite(bwd_pin, 0);
        gpioPWM(en_pin, speed);
    } else if (speed < 0) {
        gpioWrite(fwd_pin, 0);
        gpioWrite(bwd_pin, 1);
        gpioPWM(en_pin, -speed);
    } else {
        gpioWrite(fwd_pin, 0);
        gpioWrite(bwd_pin, 0);
        gpioPWM(en_pin, 0);
    }
}

static void stop_motors(void) {
    set_motor_speed(0, 0);
    set_motor_speed(1, 0);
}

static int calculate_pid(float error) {
    integral += error;
    float derivative = error - previous_error;
    float output = KP * error + KI * integral + KD * derivative;
    previous_error = error;
    return (int)output;
}

static void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR_B_ENABLE, PI_OUTPUT);

    gpioSetPWMrange(MOTOR_A_ENABLE, PWM_RANGE);
    gpioSetPWMrange(MOTOR_B_ENABLE, PWM_RANGE);
    gpioSetPWMfrequency(MOTOR_A_ENABLE, PWM_FREQ);
    gpioSetPWMfrequency(MOTOR_B_ENABLE, PWM_FREQ);

    log_file = fopen("balance_log.txt", "w");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    fprintf(log_file, "timestamp,tilt_error,distance,motor_a_speed,motor_b_speed\n");

    srand(time(NULL));

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);

    while (running) {
        float tilt_error = simulate_tilt_error();
        float distance = simulate_ultrasonic_distance();

        int pid_output = calculate_pid(tilt_error);
        int motor_a_speed = pid_output;
        int motor_b_speed = pid_output;

        if (distance < OBSTACLE_THRESHOLD_CM) {
            motor_a_speed = -REVERSE_SPEED;
            motor_b_speed = -REVERSE_SPEED;
        }

        if (motor_a_speed > PWM_RANGE) motor_a_speed = PWM_RANGE;
        if (motor_a_speed < -PWM_RANGE) motor_a_speed = -PWM_RANGE;
        if (motor_b_speed > PWM_RANGE) motor_b_speed = PWM_RANGE;
        if (motor_b_speed < -PWM_RANGE) motor_b_speed = -PWM_RANGE;

        set_motor_speed(0, motor_a_speed);
        set_motor_speed(1, motor_b_speed);

        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        gpioDelay(LOOP_DELAY_US);
    }

    stop_motors();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    return 0;
}

