/*
 * TTP223 Capacitive Touch Sensor -> Relay Toggle
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: TTP223 on GPIO4  (BCM 4, physical pin 7)
 * Relay:  5 V relay on GPIO17 (BCM 17, physical pin 11)
 *
 * Behavior:
 *   - Polls GPIO4 for a rising edge (touch detected).
 *   - Toggles GPIO17 each time a touch is confirmed.
 *   - Debounce: 50 ms post-detection.
 *   - Relay is active-high (energized when GPIO17 is HIGH).
 *   - Handles SIGINT/SIGTERM for graceful shutdown.
 *
 * Build:  gcc -Wall -Wextra -O2 -o touch_relay touch_relay.c -lpigpio -lrt
 * Run:    sudo ./touch_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <stdbool.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN        17
#define DEBOUNCE_US      50000   /* 50 ms */
#define POLL_US          10000   /* 10 ms */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Initialize pigpio and configure GPIO pins                           */
/* ------------------------------------------------------------------ */
static int initialize_gpio(void)
{
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    /* Sensor pin: input with internal pull-down so the line is defined
     * when the sensor is disconnected. */
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as input.\n",
                TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Error: failed to set pull-down on GPIO%d.\n",
                TOUCH_SENSOR_PIN);
        gpioTerminate();
        return -1;
    }

    /* Relay pin: output, initial state LOW (relay de-energized). */
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO%d as output.\n",
                RELAY_PIN);
        gpioTerminate();
        return -1;
    }
    if (gpioWrite(RELAY_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize GPIO%d LOW.\n",
                RELAY_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read the touch sensor (returns 1 = touched, 0 = not touched)        */
/* ------------------------------------------------------------------ */
static int read_touch_sensor(void)
{
    int level = gpioRead(TOUCH_SENSOR_PIN);
    if (level < 0) {
        fprintf(stderr, "Warning: gpioRead failed on GPIO%d.\n",
                TOUCH_SENSOR_PIN);
        return 0;  /* Treat read failure as no touch to avoid spurious toggles */
    }
    return (level == 1) ? 1 : 0;
}

/* ------------------------------------------------------------------ */
/* Toggle the relay state                                             */
/* ------------------------------------------------------------------ */
static int toggle_relay(void)
{
    int current = gpioRead(RELAY_PIN);
    if (current < 0) {
        fprintf(stderr, "Warning: gpioRead failed on GPIO%d.\n",
                RELAY_PIN);
        return -1;
    }

    int new_state = (current == 0) ? 1 : 0;
    if (gpioWrite(RELAY_PIN, new_state) < 0) {
        fprintf(stderr, "Error: gpioWrite failed on GPIO%d.\n",
                RELAY_PIN);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — always safe to call                               */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    /* Ensure relay is de-energized before terminating. */
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    printf("Touch sensor relay control started.\n");
    printf("  Sensor: GPIO%d (BCM)\n", TOUCH_SENSOR_PIN);
    printf("  Relay:  GPIO%d (BCM, active-high)\n", RELAY_PIN);
    printf("Press Ctrl-C to exit.\n");

    int last_touch_state = 0;

    while (g_running) {
        int touch_detected = read_touch_sensor();

        /* Detect rising edge: 0 -> 1 transition */
        if (touch_detected && !last_touch_state) {
            if (toggle_relay() == 0) {
                printf("Touch detected — relay toggled.\n");
            } else {
                fprintf(stderr, "Error: relay toggle failed.\n");
