/*
 * Mood light for Raspberry Pi 3 Model B+
 * Captures 8 kHz mono audio via ALSA, computes RMS amplitude, and maps it
 * to a common-cathode RGB LED (R=GPIO17, G=GPIO18, B=GPIO27) using software
 * PWM via the pigpio driver library.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o mood_light mood_light.c -lpigpio -lasound -lm
 * Run:
 *   sudo ./mood_light [sensitivity]
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>

#ifdef ALSA_AVAILABLE
#include <alsa/asoundlib.h>
#endif
#include <pigpio.h>

#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

#define PERIOD_SIZE 1024
#define SAMPLE_RATE 8000
#define PWM_RANGE   255
#define PWM_FREQ    1000  /* Hz */

#define DEFAULT_SENSITIVITY 1.0

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Software PWM via pigpio (duty-cycle 0..255)                         */
/* ------------------------------------------------------------------ */
static int pwm_write(unsigned pin, int duty)
{
    if (duty < 0) duty = 0;
    if (duty > PWM_RANGE) duty = PWM_RANGE;
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "gpioPWM failed on pin %u: %s\n", pin, pigpio_error(gpioGetMode(pin)));
        return -1;
    }
    return 0;
}

static int pwm_init(unsigned pin)
{
    if (gpioSetMode(pin, PI_OUTPUT) < 0) {
        fprintf(stderr, "gpioSetMode failed on pin %u: %s\n", pin, pigpio_error(gpioGetMode(pin)));
        return -1;
    }
    if (gpioSetPWMfrequency(pin, PWM_FREQ) < 0) {
        fprintf(stderr, "gpioSetPWMfrequency failed on pin %u\n", pin);
        return -1;
    }
    if (gpioSetPWMrange(pin, PWM_RANGE) < 0) {
        fprintf(stderr, "gpioSetPWMrange failed on pin %u\n", pin);
        return -1;
    }
    return pwm_write(pin, 0);
}

/* ------------------------------------------------------------------ */
/* Audio capture via ALSA                                              */
/* ------------------------------------------------------------------ */
#ifdef ALSA_AVAILABLE
static int alsa_init(snd_pcm_t **handle)
{
    int err;

    err = snd_pcm_open(handle, "default", SND_PCM_STREAM_CAPTURE, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_open failed: %s\n", snd_strerror(err));
        return -1;
    }

    snd_pcm_hw_params_t *hw_params;
    snd_pcm_hw_params_alloca(&hw_params);

    err = snd_pcm_hw_params_any(*handle, hw_params);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_any failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_hw_params_set_access(*handle, hw_params, SND_PCM_ACCESS_RW_INTERLEAVED);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_access failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_hw_params_set_format(*handle, hw_params, SND_PCM_FORMAT_S16_LE);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_format failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_hw_params_set_channels(*handle, hw_params, 1);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_channels failed: %s\n", snd_strerror(err));
        goto fail;
    }

    unsigned int rate = SAMPLE_RATE;
    err = snd_pcm_hw_params_set_rate_near(*handle, hw_params, &rate, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_rate_near failed: %s\n", snd_strerror(err));
        goto fail;
    }
    if (rate != SAMPLE_RATE) {
        fprintf(stderr, "Warning: requested %u Hz, got %u Hz\n", SAMPLE_RATE, rate);
    }

    err = snd_pcm_hw_params_set_period_size_near(*handle, hw_params, &(snd_pcm_uframes_t){PERIOD_SIZE}, 0);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params_set_period_size_near failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_hw_params(*handle, hw_params);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_hw_params failed: %s\n", snd_strerror(err));
        goto fail;
    }

    err = snd_pcm_prepare(*handle);
    if (err < 0) {
        fprintf(stderr, "snd_pcm_prepare failed: %s\n", snd_strerror(err));
        goto fail;
    }

    return 0;

fail:
    snd_pcm_close(*handle);
    *handle = NULL;
    return -1;
}

static int alsa_read(snd_pcm_t *handle, short *buffer, int frames)
{
    int err = snd_pcm_readi(handle, buffer, frames);
    if (err == -EPIPE) {
        fprintf(stderr, "ALSA underrun (EPIPE), re-initialising...\n");
        snd_pcm_prepare(handle);
        return -1;
    } else if (err < 0) {
        if (err == -ESTRPIPE) {
            fprintf(stderr, "ALSA suspended (ESTRPIPE), resuming...\n");
            while (err == -ESTRPIPE) {
                err = snd_pcm_resume(handle);
                if (err < 0) {
                    err = snd_pcm_prepare(handle);
                    if (err < 0) {
                        fprintf(stderr, "snd_pcm_resume/prepare failed: %s\n", snd_strerror(err));
                        return -1;
                    }
                }
            }
            return alsa_read(handle, buffer, frames);
        }
        fprintf(stderr, "snd_pcm_readi failed: %s\n", snd_strerror(err));
        return -1;
    }
    return err;
}

static double calculate_rms(const short *buffer, int frames)
{
    double sum_sq = 0.0;
    for (int i = 0; i < frames; i++) {
        double s = (double)buffer[i];
        sum_sq += s * s;
    }
    return sqrt(sum_sq / frames);
}
#else
/* ------------------------------------------------------------------ */
/* Simulated audio input (sine wave) when ALSA is unavailable          */
/* ------------------------------------------------------------------ */
static int alsa_init(snd_pcm_t **handle)
{
    (void)handle;
    return 0;
}

static int alsa_read(snd_pcm_t *handle, short *buffer, int frames)
{
    (void)handle;
    static double phase = 0.0;
    double freq = 440.0;
    for (int i = 0; i < frames; i++) {
        buffer[i] = (short)(32767.0 * sin(2.0 * M_PI * freq * phase / SAMPLE_RATE));
        phase += 1.0;
    }
    return frames;
}

static double calculate_rms(const short *buffer, int frames)
{
    double sum_sq = 0.0;
    for (int i = 0; i < frames; i++) {
        double s = (double)buffer[i];
        sum_sq += s * s;
    }
    return sqrt(sum_sq / frames);
}
#endif

/* ------------------------------------------------------------------ */
/* Map RMS amplitude to RGB color                                      */
/* ------------------------------------------------------------------ */
static void map_amplitude_to_color(double amplitude, double sensitivity,
                                   int *red, int *green, int *blue)
{
    double scaled = amplitude * sensitivity;
    if (scaled < 0.0) scaled = 0.0;
    if (scaled > 1.0) scaled = 1.0;

    /* Non-linear mapping: loud -> red, soft -> blue */
    double r = pow(scaled, 2.0);
    double g = pow(scaled, 0.5);
    double b = pow(scaled, 4.0);

    *red   = (int)(r * 255.0);
    *green = (int)(g * 255.0);
    *blue  = (int)(b * 255.0);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(snd_pcm_t *handle)
{
    if (handle) {
        snd_pcm_drain(handle);
        snd_pcm_close(handle);
    }
    gpioTerminate();
}

int main(int argc, char *argv[])
{
    double sensitivity = DEFAULT_SENSITIVITY;
    if (argc > 1) {
        char *endptr = NULL;
        errno = 0;
        double v = strtod(argv[1], &endptr);
        if (errno != 0 || endptr == argv[1] || *endptr != '\0' || v <= 0.0) {
            fprintf(stderr, "Invalid sensitivity '%s'; using default %.2f\n", argv[1], DEFAULT_SENSITIVITY);
        } else {
            sensitivity = v;
        }
    }
    printf("Sensitivity: %.2f\n", sensitivity);

    /* ---- pigpio init ---- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (pwm_init(RED_PIN) < 0 ||
        pwm_init(GREEN_PIN) < 0 ||
        pwm_init(BLUE_PIN) < 0) {
        fprintf(stderr, "PWM initialisation failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* ---- ALSA init ---- */
    snd_pcm_t *handle = NULL;
    if (alsa_init(&handle) < 0) {
        fprintf(stderr, "ALSA initialisation failed; running with simulated audio\n");
    }

    /* ---- Signal handlers ---- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        cleanup(handle);
        return EXIT_FAILURE;
    }

    short *buffer = malloc(PERIOD_SIZE * sizeof(short));
    if (!buffer) {
        perror("malloc");
        cleanup(handle);
        return EXIT_FAILURE;
    }

    printf("Capturing audio... (Ctrl+C to exit)\n");

    while (g_running) {
        int frames = alsa_read(handle, buffer, PERIOD_SIZE);
        if (frames < 0) {
            if (!g_running) break;
            gpioDelay(10000); /* 10 ms back-off */
            continue;
        }

        double amplitude = calculate_rms(buffer, frames);

        int red, green, blue;
        map_amplitude_to_color(amplitude, sensitivity, &red, &green, &blue);

        if (pwm_write(RED_PIN, red) < 0 ||
            pwm_write(GREEN_PIN, green) < 0 ||
            pwm_write(BLUE_PIN, blue) < 0) {
            fprintf(stderr, "PWM write failed; continuing\n");
        }

        gpioDelay(10000); /* 10 ms */
    }

    /* ---- Cleanup ---- */
    free(buffer);
    pwm_write(RED_PIN, 0);
    pwm_write(GREEN_PIN, 0);
    pwm_write(BLUE_PIN, 0);
    cleanup(handle);

    printf("\nExiting cleanly.\n");
    return EXIT_SUCCESS;
}

