#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* TCS34725 I2C address (7-bit) */
#define TCS34725_ADDRESS 0x29

/* TCS34725 register addresses */
#define TCS34725_ENABLE  0x80
#define TCS34725_ATIME   0x81
#define TCS34725_ID      0x12
#define TCS34725_CDATA   0x14
#define TCS34725_RDATA   0x16
#define TCS34725_GDATA   0x18
#define TCS34725_BDATA   0x1A

/* Enable register bits */
#define TCS34725_ENABLE_PON  0x01
#define TCS34725_ENABLE_AEN  0x02

/* Integration time: 154 ms (0xFF) */
#define TCS34725_ATIME_154MS 0xFF

/* Expected device ID */
#define TCS34725_ID_VALUE 0x44

/* Global resources for signal handler cleanup */
static int i2c_handle = -1;
static FILE *fp = NULL;
static volatile sig_atomic_t running = 1;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Write a byte to a TCS34725 register; returns 0 on success, -1 on error */
static int tcs34725_write_byte(int handle, uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "Error writing 0x%02X to register 0x%02X: %d\n", value, reg, rc);
        return -1;
    }
    return 0;
}

/* Read a 16-bit little-endian word from a TCS34725 register; returns 0 on success, -1 on error */
static int tcs34725_read_word(int handle, uint8_t reg, uint16_t *value) {
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %d\n", reg, rc);
        return -1;
    }
    /* pigpio returns data as (high_byte << 8) | low_byte */
    *value = (uint16_t)rc;
    return 0;
}

/* Initialize the TCS34725 sensor; returns 0 on success, -1 on error */
static int tcs34725_init(int handle) {
    uint16_t id = 0;

    /* Power on */
    if (tcs34725_write_byte(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON) != 0) {
        return -1;
    }
    gpioDelay(3000); /* 3 ms power-on delay */

    /* Read device ID to verify sensor presence */
    if (tcs34725_read_word(handle, TCS34725_ID, &id) != 0) {
        return -1;
    }
    if ((id & 0xFF) != TCS34725_ID_VALUE) {
        fprintf(stderr, "Unexpected device ID: 0x%02X (expected 0x%02X)\n", id & 0xFF, TCS34725_ID_VALUE);
        return -1;
    }

    /* Set integration time to 154 ms */
    if (tcs34725_write_byte(handle, TCS34725_ATIME, TCS34725_ATIME_154MS) != 0) {
        return -1;
    }

    /* Enable RGBC ADC */
    if (tcs34725_write_byte(handle, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) != 0) {
        return -1;
    }

    return 0;
}

/* Read calibrated color values from the TCS34725 */
static int tcs34725_read_color(int handle, uint16_t *clear, uint16_t *red, uint16_t *green, uint16_t *blue) {
    if (tcs34725_read_word(handle, TCS34725_CDATA, clear) != 0) return -1;
    if (tcs34725_read_word(handle, TCS34725_RDATA, red)   != 0) return -1;
    if (tcs34725_read_word(handle, TCS34725_GDATA, green) != 0) return -1;
    if (tcs34725_read_word(handle, TCS34725_BDATA, blue)  != 0) return -1;
    return 0;
}

/* Log color data to a CSV file */
static int log_color_data(FILE *file, uint16_t clear, uint16_t red, uint16_t green, uint16_t blue) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        fprintf(stderr, "Error getting current time\n");
        return -1;
    }
    if (fprintf(file, "%ld,%u,%u,%u,%u\n", (long)now, clear, red, green, blue) < 0) {
        fprintf(stderr, "Error writing to CSV file\n");
        return -1;
    }
    if (fflush(file) != 0) {
        fprintf(stderr, "Error flushing CSV file\n");
        return -1;
    }
    return 0;
}

int main(void) {
    /* Register signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 at the TCS34725 address */
    i2c_handle = i2cOpen(1, TCS34725_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at address 0x%02X: %d\n", TCS34725_ADDRESS, i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Initialize the sensor */
    if (tcs34725_init(i2c_handle) != 0) {
        fprintf(stderr, "TCS34725 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Open CSV file for logging */
    fp = fopen("color_data.csv", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening color_data.csv for writing\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Write header if file is empty */
    fseek(fp, 0, SEEK_END);
    if (ftell(fp) == 0) {
        fprintf(fp, "timestamp,clear,red,green,blue\n");
        fflush(fp);
    }

    /* Main sampling loop */
    while (running) {
        uint16_t clear, red, green, blue;

        if (tcs34725_read_color(i2c_handle, &clear, &red, &green, &blue) == 0) {
            if (log_color_data(fp, clear, red, green, blue) != 0) {
                fprintf(stderr, "Error logging color data\n");
            }
        } else {
            fprintf(stderr, "Error reading color data; logging zeros\n");
            if (log_color_data(fp, 0, 0, 0, 0) != 0) {
                fprintf(stderr, "Error logging zeros\n");
            }
        }

        /* Wait 500 ms (pigpio uses microseconds) */
        gpioDelay(500000);
    }

    /* Cleanup */
    fprintf(stderr, "\nShutting down...\n");
    if (fp != NULL) {
        fclose(fp);
    }
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();

    return 0;
}

