#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

#define SUNRISE_DURATION    3600   /* seconds */
#define DAYTIME_DURATION    21600  /* seconds */
#define SUNSET_DURATION     3600   /* seconds */
#define NIGHTTIME_DURATION  52800  /* seconds */

#define PWM_FREQ 1000
#define PWM_RANGE 1000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int safe_write(unsigned pin, int level) {
    if (gpioWrite(pin, level) < 0) {
        fprintf(stderr, "Error: gpioWrite(%u, %d) failed\n", pin, level);
        return -1;
    }
    return 0;
}

static int safe_pwm(unsigned pin, int duty) {
    if (gpioPWM(pin, duty) < 0) {
        fprintf(stderr, "Error: gpioPWM(%u, %d) failed\n", pin, duty);
        return -1;
    }
    return 0;
}

static void all_off(void) {
    safe_write(RELAY1_PIN, 1);
    safe_write(RELAY2_PIN, 1);
    safe_write(RELAY3_PIN, 1);
    safe_write(RELAY4_PIN, 1);
}

static void sunrise_phase(int duration) {
    int step = 1000;
    int elapsed = 0;
    while (running && elapsed < duration) {
        int duty = (elapsed * 1000) / duration;
        if (duty > 1000) duty = 1000;
        if (safe_pwm(RELAY1_PIN, duty) < 0 ||
            safe_pwm(RELAY2_PIN, duty) < 0 ||
            safe_pwm(RELAY3_PIN, duty) < 0 ||
            safe_pwm(RELAY4_PIN, duty) < 0) {
            break;
        }
        sleep(1);
        elapsed += step;
    }
}

static void sunset_phase(int duration) {
    int step = 1000;
    int elapsed = 0;
    while (running && elapsed < duration) {
        int duty = 1000 - ((elapsed * 1000) / duration);
        if (duty < 0) duty = 0;
        if (safe_pwm(RELAY1_PIN, duty) < 0 ||
            safe_pwm(RELAY2_PIN, duty) < 0 ||
            safe_pwm(RELAY3_PIN, duty) < 0 ||
            safe_pwm(RELAY4_PIN, duty) < 0) {
            break;
        }
        sleep(1);
        elapsed += step;
    }
}

static void nighttime_phase(int duration) {
    int step = 1000;
    int elapsed = 0;
    while (running && elapsed < duration) {
        if (safe_write(RELAY1_PIN, 1) < 0 ||
            safe_write(RELAY2_PIN, 1) < 0 ||
            safe_write(RELAY3_PIN, 1) < 0 ||
            safe_write(RELAY4_PIN, 1) < 0) {
            break;
        }
        sleep(1);
        elapsed += step;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(RELAY2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(RELAY3_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(RELAY4_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RELAY1_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(RELAY2_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(RELAY3_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(RELAY4_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR ||
        signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: signal handler setup failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        sunrise_phase(SUNRISE_DURATION);
        if (!running) break;
        nighttime_phase(DAYTIME_DURATION);
        if (!running) break;
        sunset_phase(SUNSET_DURATION);
        if (!running) break;
        nighttime_phase(NIGHTTIME_DURATION);
    }

    all_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

