static void nighttime_phase(int duration) {
    int step = 1000;
    int elapsed = 0;
    while (running && elapsed < duration) {
        if (safe_write(RELAY1_PIN, 1) < 0 ||
            safe_write(RELAY2_PIN, 1) < 0 ||
            safe_write(RELAY3_PIN, 1) < 0 ||
            safe_write(RELAY4_PIN, 1) < 0) {
            break;
        }
        sleep(1);
        elapsed += step;
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY1_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(RELAY2_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(RELAY3_PIN, PI_OUTPUT) < 0 ||
        gpioSetMode(RELAY4_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQ) < 0 ||
        gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQ) < 0) {
        fprintf(stderr, "Error: gpioSetPWMfrequency failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(RELAY1_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(RELAY2_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(RELAY3_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(RELAY4_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: gpioSetPWMrange failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (signal(SIGINT, signal_handler) == SIG_ERR ||
        signal(SIGTERM, signal_handler) == SIG_ERR) {
        fprintf(stderr, "Error: signal handler setup failed\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    while (running) {
        sunrise_phase(SUNRISE_DURATION);
        if (!running) break;
        nighttime_phase(DAYTIME_DURATION);
        if (!running) break;
        sunset_phase(SUNSET_DURATION);
        if (!running) break;
        nighttime_phase(NIGHTTIME_DURATION);
    }

    all_off();
    gpioTerminate();
    return EXIT_SUCCESS;
}

