#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define MOTION_SENSOR_GPIO 17
#define DEBOUNCE_DELAY_MS 200
#define VIDEO_DURATION_SEC 5
#define VIDEO_DIR "/home/pi/videos/"
#define LOG_FILE "/home/pi/logs/motion_log.txt"
#define TIMESTAMP_LEN 32
#define FILENAME_LEN 128

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }
    gpioSetMode(MOTION_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(MOTION_SENSOR_GPIO, PI_PUD_UP);
    return 0;
}

static int get_timestamp(char *buf, size_t len) {
    time_t rawtime;
    struct tm *timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed.\n");
        return -1;
    }
    if (strftime(buf, len, "%Y%m%d_%H%M%S", timeinfo) == 0) {
        fprintf(stderr, "Error: strftime() failed.\n");
        return -1;
    }
    return 0;
}

static int capture_video(const char *filename) {
    char command[512];
    int ret = snprintf(command, sizeof(command),
        "raspivid -o %s -t %d -w 640 -h 480 -fps 30",
        filename, VIDEO_DURATION_SEC * 1000);
    if (ret < 0 || (size_t)ret >= sizeof(command)) {
        fprintf(stderr, "Error: command buffer too small.\n");
        return -1;
    }
    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error: system() failed: %s\n", strerror(errno));
        return -1;
    }
    if (!WIFEXITED(status) || WEXITSTATUS(status) != 0) {
        fprintf(stderr, "Error: raspivid exited with status %d\n", status);
        return -1;
    }
    return 0;
}

static int log_motion_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: log file not open.\n");
        return -1;
    }
    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error: writing to log file failed.\n");
        return -1;
    }
    if (fflush(log_file) != 0) {
        fprintf(stderr, "Warning: fflush failed on log file.\n");
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Error: sigaction(SIGINT) failed: %s\n", strerror(errno));
        return 1;
    }

    if (init_gpio() != 0) {
        return 1;
    }

    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s': %s\n",
            LOG_FILE, strerror(errno));
        gpioTerminate();
        return 1;
    }

    printf("Motion detection started on GPIO %d. Press Ctrl+C to exit.\n",
        MOTION_SENSOR_GPIO);

    uint32_t last_trigger_tick = 0;

    while (running) {
        int level = gpioRead(MOTION_SENSOR_GPIO);
        if (level < 0) {
            fprintf(stderr, "Error: gpioRead failed on GPIO %d.\n",
                MOTION_SENSOR_GPIO);
            break;
        }

        if (level == 0) {
            uint32_t now = gpioTick();
            uint32_t elapsed = now - last_trigger_tick;
            if (last_trigger_tick == 0 || elapsed >= (DEBOUNCE_DELAY_MS * 1000)) {
                char timestamp[TIMESTAMP_LEN];
                char filename[FILENAME_LEN];

                if (get_timestamp(timestamp, sizeof(timestamp)) != 0) {
                    fprintf(stderr, "Error: failed to get timestamp.\n");
                } else {
                    if (snprintf(filename, sizeof(filename),
                            "%s%s.h264", VIDEO_DIR, timestamp) >=
                        (int)sizeof(filename)) {
                        fprintf(stderr, "Error: filename buffer too small.\n");
                    } else {
                        printf("Motion detected at %s, capturing video...\n",
                            timestamp);
                        if (capture_video(filename) == 0) {
                            if (log_motion_event(timestamp) != 0) {
                                fprintf(stderr,
                                    "Warning: failed to log motion event.\n");
                            }
                        } else {
                            fprintf(stderr,
                                "Error: video capture failed for %s\n",
                                filename);
                        }
                    }
                }
                last_trigger_tick = now;
            }
        }
        gpioDelay(50000);
    }

    printf("\nShutting down...\n");
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
    return 0;
}

