#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* MPU-6050 I2C address (AD0 tied to GND) */
#define MPU6050_ADDR 0x68

/* MPU-6050 registers */
#define PWR_MGMT_1   0x6B
#define PWR_MGMT_2   0x6C
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43

/* Sensitivity scale factor for ±250 °/s range */
#define GYRO_SCALE 131.0f

/* Sampling interval in microseconds (10 ms = 100 Hz) */
#define SAMPLE_INTERVAL_US 10000

/* Max retries for re-initialization */
#define MAX_RETRIES 3

/* Global state for signal handler */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can clean up                */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a byte to an MPU-6050 register; returns 0 on success, -1 err  */
/* ------------------------------------------------------------------ */
static int mpu_write_reg(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "i2cWriteByteData(reg=0x%02X, val=0x%02X) failed: %d\n",
                reg, value, rc);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a 16-bit big-endian word from an MPU-6050 register; returns 0  */
/* on success, -1 on error                                            */
/* ------------------------------------------------------------------ */
static int mpu_read_word(int handle, uint8_t reg, int16_t *out)
{
    int rc = i2cReadWordData(handle, reg);
    if (rc < 0) {
        fprintf(stderr, "i2cReadWordData(reg=0x%02X) failed: %d\n", reg, rc);
        return -1;
    }
    /* pigpio returns data as (high_byte << 8) | low_byte */
    *out = (int16_t)rc;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Initialize the MPU-6050: wake, set gyro range, verify communication */
/* ------------------------------------------------------------------ */
static int mpu_init(int handle)
{
    /* Wake up: clear SLEEP bit (bit 6) in PWR_MGMT_1 */
    if (mpu_write_reg(handle, PWR_MGMT_1, 0x00) != 0)
        return -1;
    gpioDelay(1000); /* 1 ms settle */

    /* Set gyro range to ±250 °/s (FS_SEL = 0) */
    if (mpu_write_reg(handle, GYRO_CONFIG, 0x00) != 0)
        return -1;

    /* Verify by reading back GYRO_CONFIG */
    int cfg = i2cReadByteData(handle, GYRO_CONFIG);
    if (cfg < 0) {
        fprintf(stderr, "Failed to read back GYRO_CONFIG: %d\n", cfg);
        return -1;
    }
    if (cfg != 0x00) {
        fprintf(stderr, "GYRO_CONFIG mismatch: read 0x%02X, expected 0x00\n", cfg);
        return -1;
    }

    /* Read one sample to confirm the sensor is responding */
    int16_t x, y, z;
    if (mpu_read_word(handle, GYRO_XOUT_H, &x) != 0 ||
        mpu_read_word(handle, GYRO_XOUT_H + 2, &y) != 0 ||
        mpu_read_word(handle, GYRO_XOUT_H + 4, &z) != 0) {
        fprintf(stderr, "MPU-6050 not responding on I2C bus 1, addr 0x%02X\n",
                MPU6050_ADDR);
        return -1;
    }

    return 0;
}

/* ------------------------------------------------------------------ */
/* Read angular velocity in °/s; returns 0 on success, -1 on error     */
/* ------------------------------------------------------------------ */
static int read_gyro_data(int handle, float *x, float *y, float *z)
{
    int16_t raw_x, raw_y, raw_z;

    if (mpu_read_word(handle, GYRO_XOUT_H, &raw_x) != 0) return -1;
    if (mpu_read_word(handle, GYRO_XOUT_H + 2, &raw_y) != 0) return -1;
    if (mpu_read_word(handle, GYRO_XOUT_H + 4, &raw_z) != 0) return -1;

    *x = (float)raw_x / GYRO_SCALE;
    *y = (float)raw_y / GYRO_SCALE;
    *z = (float)raw_z / GYRO_SCALE;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Append a timestamped sample to the CSV log file                     */
/* ------------------------------------------------------------------ */
static void log_data(FILE *fp, float x, float y, float z)
{
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    double timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1.0e9;
    fprintf(fp, "%.3f,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper — safe to call multiple times                        */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at MPU-6050 address */
    g_i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=1, addr=0x%02X) failed: %d\n",
                MPU6050_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPU-6050 with retries */
    int init_ok = 0;
    for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
        if (mpu_init(g_i2c_handle) == 0) {
            init_ok = 1;
            break;
        }
        fprintf(stderr, "MPU-6050 init attempt %d/%d failed\n",
                attempt, MAX_RETRIES);
        if (attempt < MAX_RETRIES)
            gpioDelay(100000); /* 100 ms between retries */
    }
    if (!init_ok) {
        fprintf(stderr, "MPU-6050 initialization failed after %d attempts\n",
                MAX_RETRIES);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen("gyro_log.csv", "a");
    if (g_log_file == NULL) {
        perror("fopen(gyro_log.csv)");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log_file, 0, SEEK_END);
    if (ftell(g_log_file) == 0) {
        fprintf(g_log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
        fflush(g_log_file);
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPU-6050 logging to gyro_log.csv at 100 Hz. Press Ctrl+C to stop.\n");

    /* Main sampling loop */
    while (g_running) {
        float x, y, z;
        if (read_gyro_data(g_i2c_handle, &x, &y, &z) == 0) {
            log_data(g_log_file, x, y, z);
        } else {
            fprintf(stderr, "Gyro read error — attempting re-initialization...\n");
            int reinit_ok = 0;
            for (int attempt = 1; attempt <= MAX_RETRIES; ++attempt) {
                if (mpu_init(g_i2c_handle) == 0) {
                    reinit_ok = 1;
                    break;
                }
                fprintf(stderr, "Re-init attempt %d/%d failed\n",
                        attempt, MAX_RETRIES);
                if (attempt < MAX_RETRIES)
                    gpioDelay(100000);
            }
            if (!reinit_ok) {
                fprintf(stderr, "Re-initialization failed — continuing to retry.\n");
            }
        }
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down cleanly...\n");
    cleanup();
    return EXIT_SUCCESS;
}

