#include <math.h>
#include <pigpio.h>

/* ---- ADXL345 constants (from datasheet) ---- */
#define ADXL345_ADDR          0x53          /* default I2C address (ALT ADDRESS tied high) */
#define ADXL345_REG_DEVID     0x00          /* device ID register */
#define ADXL345_REG_POWER_CTL 0x2D          /* power-saving features control */
#define ADXL345_REG_DATAX0    0x32          /* first of 6 data registers */
#define ADXL345_REG_BW_RATE   0x2C          /* data rate / power control */
#define ADXL345_REG_DATA_FORMAT 0x31       /* data format register */
#define ADXL345_DEVID_VALUE   0xE5          /* expected device ID */

/* ---- Application constants ---- */
#define I2C_BUS              1
#define ALARM_GPIO           27
#define FREEFALL_THRESHOLD   0.2f          /* g */
#define FREEFALL_DURATION    0.5           /* seconds */
#define SAMPLE_PERIOD_US     100000        /* 100 ms */
#define ALARM_HOLD_US        5000000       /* 5 s */
#define LOG_FILE             "freefall.log"

/* ---- Globals for cleanup ---- */
static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* I2C helpers                                                         */
/* ------------------------------------------------------------------ */
static int i2c_write_byte(int handle, uint8_t reg, uint8_t value)
{
    int rc = i2cWriteByteData(handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "[I2C] write 0x%02X <- 0x%02X failed (rc=%d)\n",
                reg, value, rc);
    }
    return rc;
}

static int i2c_read_block(int handle, uint8_t reg, uint8_t *buf, uint32_t len)
{
    int rc = i2cReadI2CBlockData(handle, reg, (char *)buf, len);
    if (rc < 0) {
        fprintf(stderr, "[I2C] read block 0x%02X (%u bytes) failed (rc=%d)\n",
                reg, len, rc);
    }
    return rc;
}

/* ------------------------------------------------------------------ */
/* ADXL345 driver                                                      */
/* ------------------------------------------------------------------ */
static int adxl345_init(int handle)
{
    uint8_t devid = 0;

    /* Verify device identity */
    if (i2cReadByteData(handle, ADXL345_REG_DEVID) < 0) {
        fprintf(stderr, "[ADXL345] cannot read DEVID register\n");
        return -1;
    }
    devid = (uint8_t)i2cReadByteData(handle, ADXL345_REG_DEVID);
    if (devid != ADXL345_DEVID_VALUE) {
        fprintf(stderr, "[ADXL345] unexpected DEVID 0x%02X (expected 0x%02X)\n",
                devid, ADXL345_DEVID_VALUE);
        return -1;
    }

    /* Standby -> configure -> measure */
    if (i2c_write_byte(handle, ADXL345_REG_POWER_CTL, 0x00) < 0)
        return -1;
    if (i2c_write_byte(handle, ADXL345_REG_DATA_FORMAT, 0x00) < 0)
        return -1;
    if (i2c_write_byte(handle, ADXL345_REG_BW_RATE, 0x0A) < 0)
        return -1;
    if (i2c_write_byte(handle, ADXL345_REG_POWER_CTL, 0x08) < 0)
        return -1;

    return 0;
}

static int adxl345_read_xyz(int handle, float *x, float *y, float *z)
{
    uint8_t raw[6];

    if (i2c_read_block(handle, ADXL345_REG_DATAX0, raw, sizeof(raw)) < 0)
        return -1;

    int16_t rx = (int16_t)((raw[1] << 8) | raw[0]);
    int16_t ry = (int16_t)((raw[3] << 8) | raw[2]);
    int16_t rz = (int16_t)((raw[5] << 8) | raw[4]);

    /* 4 mg/LSB default scale factor (0x00 DATA_FORMAT, full resolution off) */
    *x = (float)rx * 0.004f;
    *y = (float)ry * 0.004f;
    *z = (float)rz * 0.004f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Free-fall detection                                                 */
/* ------------------------------------------------------------------ */
static bool is_freefall(float x, float y, float z)
{
    return (fabsf(x) < FREEFALL_THRESHOLD &&
            fabsf(y) < FREEFALL_THRESHOLD &&
            fabsf(z) < FREEFALL_THRESHOLD);
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_freefall(float x, float y, float z)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[LOG] fopen");
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d,%.3f,%.3f,%.3f\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    } else {
        fprintf(fp, "<unknown-time>,%.3f,%.3f,%.3f\n", x, y, z);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Alarm control                                                       */
/* ------------------------------------------------------------------ */
static void alarm_on(void)
{
    if (gpioWrite(ALARM_GPIO, 1) < 0)
        fprintf(stderr, "[GPIO] failed to set alarm high\n");
}

static void alarm_off(void)
{
    if (gpioWrite(ALARM_GPIO, 0) < 0)
        fprintf(stderr, "[GPIO] failed to set alarm low\n");
}

/* ------------------------------------------------------------------ */
/* Cleanup                                                             */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    alarm_off();
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Configure alarm GPIO */
    if (gpioSetMode(ALARM_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", ALARM_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    alarm_off();

    /* Open I2C bus */
    g_i2c_handle = i2cOpen(I2C_BUS, ADXL345_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, ADXL345_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (adxl345_init(g_i2c_handle) < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Signal handling */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Free-fall detection started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float x, y, z;

        if (adxl345_read_xyz(g_i2c_handle, &x, &y, &z) < 0) {
            /* I2C error: back off and retry */
            gpioDelay(SAMPLE_PERIOD_US);
            continue;
        }

        if (is_freefall(x, y, z)) {
            /* Second reading after 0.5 s to confirm */
            gpioDelay((uint32_t)(FREEFALL_DURATION * 1e6));
            if (!g_running)
                break;

            if (adxl345_read_xyz(g_i2c_handle, &x, &y, &z) < 0) {
                gpioDelay(SAMPLE_PERIOD_US);
                continue;
            }

            if (is_freefall(x, y, z)) {
                printf("Free-fall detected! (x=%.3f g, y=%.3f g, z=%.3f g)\n",
                       x, y, z);
                log_freefall(x, y, z);
                alarm_on();

                /* Hold alarm for 5 s, checking for shutdown */
                uint32_t elapsed = 0;
                while (g_running && elapsed < ALARM_HOLD_US) {
                    gpioDelay(100000);
                    elapsed += 100000;
                }
                alarm_off();
            }
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    cleanup();
    printf("Exiting cleanly.\n");
    return EXIT_SUCCESS;
}

