/*
 * HC-SR04 ultrasonic distance measurement on Raspberry Pi Zero W.
 *
 * Wiring:
 *   TRIG -> GPIO4  (BCM)
 *   ECHO -> GPIO18 (BCM)
 *   VCC  -> 5 V, GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o hcsr04_log hcsr04_log.c -lpigpio -lpthread -lrt
 * Run:
 *   sudo ./hcsr04_log
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define TRIGGER_PIN      4
#define ECHO_PIN         18

#define TRIGGER_PULSE_US 10          /* HC-SR04 trigger pulse width */
#define CYCLE_DELAY_US   200000      /* 200 ms between measurements */
#define ECHO_TIMEOUT_US  100000      /* 100 ms echo timeout */
#define MAX_PULSE_US     23200       /* ~4 m max range (round-trip) */
#define SPEED_OF_SOUND   0.0343      /* cm/us at 20 C */

#define LOG_FILE_NAME    "distance_log.txt"

/* ------------------------------------------------------------------ */
/* Shared state (protected by mutex)                                  */
/* ------------------------------------------------------------------ */
static volatile uint32_t g_rise_tick = 0;
static volatile uint32_t g_fall_tick = 0;
static volatile bool     g_echo_seen = false;
static volatile bool     g_echo_timeout = false;

static pthread_mutex_t g_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE           *g_log   = NULL;
static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Helpers                                                             */
/* ------------------------------------------------------------------ */

/*
 * Monotonic microsecond tick.
 * 32-bit counter wraps every ~71.6 minutes; acceptable for this
 * application where we only need relative timing.
 */
static inline uint32_t tick_us(void)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0) {
        return 0;
    }
    return (uint32_t)(ts.tv_sec * 1000000UL + ts.tv_nsec / 1000UL);
}

static void trigger_pulse(void)
{
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(TRIGGER_PULSE_US);
    gpioWrite(TRIGGER_PIN, 0);
}

/*
 * pigpio alert callback signature.
 * gpio: pin number
 * level: 0 = falling, 1 = rising, 2 = watchdog timeout
 * tick: 32-bit microsecond counter (wraps every ~71.6 min)
 */
static void echo_callback(int gpio, int level, uint32_t tick)
{
    (void)gpio;

    if (level == 1) {
        /* Rising edge: echo pulse starts */
        pthread_mutex_lock(&g_mutex);
        g_rise_tick = tick;
        g_echo_seen = false;
        g_echo_timeout = false;
        pthread_mutex_unlock(&g_mutex);
    } else if (level == 0) {
        /* Falling edge: echo pulse ends */
        pthread_mutex_lock(&g_mutex);
        g_fall_tick = tick;
        g_echo_seen = true;
        pthread_mutex_unlock(&g_mutex);
    }
    /* level == 2 (watchdog) is ignored here */
}

static float calculate_distance_cm(uint32_t pulse_us)
{
    return (float)pulse_us * SPEED_OF_SOUND / 2.0f;
}

static void log_reading(float distance_cm)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        return;
    }
    long long ts_ns = (long long)ts.tv_sec * 1000000000LL + ts.tv_nsec;
    fprintf(g_log, "%lld,%.2f\n", ts_ns, distance_cm);
    fflush(g_log);
}

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* --- Configure GPIO pins --- */
    if (gpioSetMode(TRIGGER_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: cannot set TRIGGER_PIN %d as output.\n", TRIGGER_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(ECHO_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: cannot set ECHO_PIN %d as input.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure trigger starts LOW */
    gpioWrite(TRIGGER_PIN, 0);
    gpioDelay(50000);  /* 50 ms settle */

    /* --- Register alert callback for echo pin --- */
    if (gpioSetAlertFunc(ECHO_PIN, echo_callback) != 0) {
        fprintf(stderr, "Error: cannot register alert callback on ECHO_PIN %d.\n", ECHO_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Open log file --- */
    g_log = fopen(LOG_FILE_NAME, "a");
    if (g_log == NULL) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE_NAME);
        gpioSetAlertFunc(ECHO_PIN, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Write CSV header if file is empty */
    fseek(g_log, 0, SEEK_END);
    if (ftell(g_log) == 0) {
        fprintf(g_log, "timestamp_ns,distance_cm\n");
        fflush(g_log);
    }

    /* --- Install signal handler --- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: could not install SIGINT handler.\n");
    }

    printf("HC-SR04 logging started. TRIG=GPIO%d, ECHO=GPIO%d. Press Ctrl+C to stop.\n",
           TRIGGER_PIN, ECHO_PIN);

    /* --- Main measurement loop --- */
    while (g_running) {
        uint32_t start_tick = tick_us();

        /* Reset shared state before triggering */
        pthread_mutex_lock(&g_mutex);
        g_echo_seen = false;
        g_echo_timeout = false;
        pthread_mutex_unlock(&g_mutex);

        trigger_pulse();

        /*
         * Wait for echo with timeout.
         * Poll every 1 ms for up to ECHO_TIMEOUT_US.
         */
        uint32_t elapsed = 0;
        bool got_echo = false;
        while (elapsed < ECHO_TIMEOUT_US) {
            gpioDelay(1000);
            elapsed = tick_us() - start_tick;

            pthread_mutex_lock(&g_mutex);
            got_echo = g_echo_seen;
            bool timed_out = g_echo_timeout;
            pthread_mutex_unlock(&g_mutex);

            if (got_echo) {
                break;
            }
            if (timed_out) {
                break;
            }
        }

        if (!got_echo) {
            fprintf(stderr, "Warning: echo timeout (no falling edge within %d us).\n",
                    ECHO_TIMEOUT_US);
            continue;
        }

        /* --- Compute pulse width --- */
        uint32_t pulse_us;
        pthread_mutex_lock(&g_mutex);
        pulse_us = g_fall_tick - g_rise_tick;
        pthread_mutex_unlock(&g_mutex);

        /* --- Validate pulse width --- */
        if (pulse_us == 0 || pulse_us > MAX_PULSE_US) {
            fprintf(stderr, "Warning: invalid pulse width %u us (max %d us).\n",
                    pulse_us, MAX_PULSE_US);
            continue;
        }

        /* --- Log valid reading --- */
        float distance_cm = calculate_distance_cm(pulse_us);
        log_reading(distance_cm);
        printf("Distance: %.2f cm  (pulse: %u us)\n", distance_cm, pulse_us);

        /* --- Wait before next measurement --- */
        gpioDelay(CYCLE_DELAY_US);
    }

    /* --- Cleanup --- */
    printf("\nShutting down...\n");
    gpioSetAlertFunc(ECHO_PIN, NULL);
    gpioWrite(TRIGGER_PIN, 0);
    gpioTerminate();

    if (g_log != NULL) {
        fclose(g_log);
        g_log = NULL;
    }

    pthread_mutex_destroy(&g_mutex);
    printf("Cleanup complete.\n");
    return EXIT_SUCCESS;
}

