/*
 * LIS3DH Impact Detector for Raspberry Pi 5
 *
 * Reads the Adafruit LIS3DH accelerometer on I2C bus 1 (address 0x19),
 * detects free-fall (acceleration < 0.2 g) and impact (acceleration > 1.5 g),
 * and sounds a buzzer on GPIO17 for 1 second when an impact is detected.
 *
 * Build: gcc -O2 -Wall -o impact impact.c -lpigpio -lrt -lm
 * Run:   sudo ./impact [freefall_g] [impact_g]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- LIS3DH constants (from datasheet) ---- */
#define LIS3DH_ADDR        0x19
#define LIS3DH_REG_CTRL1   0x20
#define LIS3DH_REG_CTRL4   0x23
#define LIS3DH_REG_OUT_X_L 0x28
#define LIS3DH_REG_WHO_AM_I 0x0F
#define LIS3DH_WHO_AM_I_VAL 0x33

/* ---- Default thresholds (in g) ---- */
#define DEFAULT_FREEFALL_G  0.2f
#define DEFAULT_IMPACT_G    1.5f

/* ---- Buzzer GPIO (BCM) ---- */
#define BUZZER_GPIO 17

/* ---- I2C bus ---- */
#define I2C_BUS 1

/* ---- Retry parameters ---- */
#define I2C_RETRIES 3
#define I2C_RETRY_DELAY_US 10000  /* 10 ms */

/* ---- Globals for cleanup ---- */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ---- I2C helpers with retry ---- */
static int i2c_write_reg(uint8_t reg, uint8_t value)
{
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        int rc = i2cWriteByteData(i2c_handle, reg, value);
        if (rc == 0)
            return 0;
        fprintf(stderr, "I2C write reg 0x%02X failed (attempt %d/%d): %d\n",
                reg, attempt + 1, I2C_RETRIES, rc);
        gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

static int i2c_read_reg(uint8_t reg, uint8_t *value)
{
    for (int attempt = 0; attempt < I2C_RETRIES; attempt++) {
        int rc = i2cReadByteData(i2c_handle, reg);
        if (rc >= 0) {
            *value = (uint8_t)rc;
            return 0;
        }
        fprintf(stderr, "I2C read reg 0x%02X failed (attempt %d/%d): %d\n",
                reg, attempt + 1, I2C_RETRIES, rc);
        gpioDelay(I2C_RETRY_DELAY_US);
    }
    return -1;
}

/* ---- LIS3DH initialization ---- */
static int lis3dh_init(void)
{
    uint8_t who_am_i = 0;

    /* Verify device identity */
    if (i2c_read_reg(LIS3DH_REG_WHO_AM_I, &who_am_i) != 0) {
        fprintf(stderr, "Cannot read WHO_AM_I register.\n");
        return -1;
    }
    if (who_am_i != LIS3DH_WHO_AM_I_VAL) {
        fprintf(stderr, "WHO_AM_I mismatch: got 0x%02X, expected 0x%02X.\n",
                who_am_i, LIS3DH_WHO_AM_I_VAL);
        return -1;
    }

    /* CTRL_REG1: 0x57 = 0b01010111
     *   ODR=100 Hz (010), LPen=0, Zen=1, Yen=1, Xen=1 */
    if (i2c_write_reg(LIS3DH_REG_CTRL1, 0x57) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG1.\n");
        return -1;
    }

    /* CTRL_REG4: 0x08 = 0b00001000
     *   BDU=1, FS=00 (±2 g), HR=0 */
    if (i2c_write_reg(LIS3DH_REG_CTRL4, 0x08) != 0) {
        fprintf(stderr, "Failed to write CTRL_REG4.\n");
        return -1;
    }

    return 0;
}

/* ---- Read acceleration (in g) ---- */
static int read_acceleration(float *x, float *y, float *z)
{
    uint8_t xl, xh, yl, yh, zl, zh;

    if (i2c_read_reg(LIS3DH_REG_OUT_X_L | 0x80, &xl) != 0) return -1;
    if (i2c_read_reg(LIS3DH_REG_OUT_X_L + 1, &xh) != 0) return -1;
    if (i2c_read_reg(LIS3DH_REG_OUT_X_L + 2, &yl) != 0) return -1;
    if (i2c_read_reg(LIS3DH_REG_OUT_X_L + 3, &yh) != 0) return -1;
    if (i2c_read_reg(LIS3DH_REG_OUT_X_L + 4, &zl) != 0) return -1;
    if (i2c_read_reg(LIS3DH_REG_OUT_X_L + 5, &zh) != 0) return -1;

    int16_t raw_x = (int16_t)((xh << 8) | xl);
    int16_t raw_y = (int16_t)((yh << 8) | yl);
    int16_t raw_z = (int16_t)((zh << 8) | zl);

    /* ±2 g full-scale range: 1 g = 16384 LSB */
    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;

    return 0;
}

/* ---- Cleanup ---- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioWrite(BUZZER_GPIO, 0);
    gpioTerminate();
}

int main(int argc, char *argv[])
{
    float freefall_g = DEFAULT_FREEFALL_G;
    float impact_g   = DEFAULT_IMPACT_G;

    if (argc > 1) {
        freefall_g = (float)atof(argv[1]);
        if (freefall_g <= 0.0f) {
            fprintf(stderr, "Invalid free-fall threshold: %s\n", argv[1]);
            return EXIT_FAILURE;
        }
    }
    if (argc > 2) {
        impact_g = (float)atof(argv[2]);
        if (impact_g <= 0.0f) {
            fprintf(stderr, "Invalid impact threshold: %s\n", argv[2]);
            return EXIT_FAILURE;
        }
    }

    printf("LIS3DH Impact Detector\n");
    printf("Free-fall threshold: %.2f g\n", freefall_g);
    printf("Impact threshold: %.2f g\n", impact_g);
    printf("Buzzer on GPIO%d\n", BUZZER_GPIO);

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n",
                I2C_BUS, LIS3DH_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize sensor */
    if (lis3dh_init() != 0) {
        fprintf(stderr, "LIS3DH initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure buzzer GPIO */
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0);

    /* Register signal handler */
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Monitoring for impacts... (Ctrl+C to exit)\n");

    bool in_freefall = false;

    while (!terminate) {
        float x, y, z;

        if (read_acceleration(&x, &y, &z) != 0) {
            fprintf(stderr, "I2C read error; retrying...\n");
            gpioDelay(100000);  /* 100 ms backoff */
            continue;
        }

        float magnitude = sqrtf(x * x + y * y + z * z);

        if (magnitude < freefall_g) {
            in_freefall = true;
        } else if (in_freefall && magnitude > impact_g) {
            printf("Impact detected! Magnitude: %.3f g\n", magnitude);
            gpioWrite(BUZZER_GPIO, 1);
            gpioDelay(1000000);  /* 1 s */
            gpioWrite(BUZZER_GPIO, 0);
            in_freefall = false;
        }

        gpioDelay(10000);  /* 10 ms polling interval */
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

