#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* LIS3DH register addresses */
#define LIS3DH_REG_CTRL1      0x20
#define LIS3DH_REG_CTRL4      0x23
#define LIS3DH_REG_OUT_X_L    0x28
#define LIS3DH_REG_WHO_AM_I   0x0F

/* Expected chip ID */
#define LIS3DH_WHO_AM_I_VAL   0x33

/* CTRL1: ODR=100Hz (0b1000), LPen=0, Zen=1, Yen=1, Xen=1 -> 0x57 */
#define LIS3DH_CTRL1_VAL      0x57

/* CTRL4: FS=00 (±2g), HR=1, ST=0 -> 0x08 */
#define LIS3DH_CTRL4_VAL      0x08

/* Sensitivity for ±2g, HR mode: 1 mg/LSB = 0.001 g/LSB */
#define LIS3DH_SENSITIVITY    0.001f

/* Defaults */
#define DEFAULT_I2C_ADDR      0x19
#define DEFAULT_THRESHOLD     2.0f
#define LOG_FILE              "/var/log/high_acceleration.log"
#define SAMPLE_PERIOD_US      100000  /* 100 ms -> 10 Hz */

/* Globals for cleanup */
static int i2c_handle = -1;
static volatile sig_atomic_t terminate = 0;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ------------------------------------------------------------------ */
/* Write a single byte to a register; returns 0 on success, -1 on fail */
/* ------------------------------------------------------------------ */
static int write_reg(uint8_t reg, uint8_t val)
{
    if (i2cWriteByteData(i2c_handle, reg, val) < 0) {
        fprintf(stderr, "Error: I2C write failed (reg=0x%02X, val=0x%02X)\n",
                reg, val);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read a single byte from a register; returns byte or -1 on fail      */
/* ------------------------------------------------------------------ */
static int read_reg(uint8_t reg)
{
    int v = i2cReadByteData(i2c_handle, reg);
    if (v < 0) {
        fprintf(stderr, "Error: I2C read failed (reg=0x%02X)\n", reg);
        return -1;
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* Verify sensor identity                                              */
/* ------------------------------------------------------------------ */
static int verify_sensor(void)
{
    int id = read_reg(LIS3DH_REG_WHO_AM_I);
    if (id < 0) {
        fprintf(stderr, "Error: Cannot read WHO_AM_I register\n");
        return -1;
    }
    if (id != LIS3DH_WHO_AM_I_VAL) {
        fprintf(stderr,
                "Error: WHO_AM_I mismatch (got 0x%02X, expected 0x%02X)\n",
                id, LIS3DH_WHO_AM_I_VAL);
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configure LIS3DH: ±2g, HR, 100 Hz                                   */
/* ------------------------------------------------------------------ */
static int configure_lis3dh(void)
{
    if (write_reg(LIS3DH_REG_CTRL1, LIS3DH_CTRL1_VAL) < 0)
        return -1;
    if (write_reg(LIS3DH_REG_CTRL4, LIS3DH_CTRL4_VAL) < 0)
        return -1;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Read acceleration (X/Y/Z) in g; returns 0 on success, -1 on fail    */
/* ------------------------------------------------------------------ */
static int read_acceleration(float *x, float *y, float *z)
{
    int xl = read_reg(LIS3DH_REG_OUT_X_L);
    int xh = read_reg(LIS3DH_REG_OUT_X_L + 1);
    int yl = read_reg(LIS3DH_REG_OUT_X_L + 2);
    int yh = read_reg(LIS3DH_REG_OUT_X_L + 3);
    int zl = read_reg(LIS3DH_REG_OUT_X_L + 4);
    int zh = read_reg(LIS3DH_REG_OUT_X_L + 5);

    if (xl < 0 || xh < 0 || yl < 0 || yh < 0 || zl < 0 || zh < 0)
        return -1;

    /* 12-bit left-justified: shift right 4 to get 12-bit value */
    int16_t raw_x = (int16_t)((xh << 8) | xl) >> 4;
    int16_t raw_y = (int16_t)((yh << 8) | yl) >> 4;
    int16_t raw_z = (int16_t)((zh << 8) | zl) >> 4;

    *x = (float)raw_x * LIS3DH_SENSITIVITY;
    *y = (float)raw_y * LIS3DH_SENSITIVITY;
    *z = (float)raw_z * LIS3DH_SENSITIVITY;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Log acceleration event                                              */
/* ------------------------------------------------------------------ */
static void log_acceleration(float x, float y, float z)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error: Cannot open log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d, X: %.3f g, Y: %.3f g, Z: %.3f g\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, x, y, z);
    }
    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(int argc, char *argv[])
{
    int i2c_address = DEFAULT_I2C_ADDR;
    float threshold = DEFAULT_THRESHOLD;
    int opt;

    while ((opt = getopt(argc, argv, "a:t:")) != -1) {
        switch (opt) {
        case 'a':
            i2c_address = (int)strtol(optarg, NULL, 16);
            if (i2c_address < 0x03 || i2c_address > 0x77) {
                fprintf(stderr,
                        "Error: I2C address 0x%02X out of valid range (0x03-0x77)\n",
                        i2c_address);
                return 1;
            }
            break;
        case 't':
            threshold = strtof(optarg, NULL);
            if (threshold <= 0.0f) {
                fprintf(stderr, "Error: Threshold must be positive (> 0)\n");
                return 1;
            }
            break;
        default:
            fprintf(stderr,
                    "Usage: %s [-a i2c_address_hex] [-t threshold_g]\n",
                    argv[0]);
            return 1;
        }
    }

    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    /* Open I2C bus 1 (default on Raspberry Pi 5) */
    i2c_handle = i2cOpen(1, i2c_address, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (addr=0x%02X, handle=%d)\n",
                i2c_address, i2c_handle);
        gpioTerminate();
        return 1;
    }

    /* Verify sensor identity */
    if (verify_sensor() < 0) {
        fprintf(stderr, "Error: LIS3DH not detected at address 0x%02X\n",
                i2c_address);
        cleanup();
        return 1;
    }

    /* Configure sensor */
    if (configure_lis3dh() < 0) {
        fprintf(stderr, "Error: LIS3DH configuration failed\n");
        cleanup();
        return 1;
    }

    /* Install signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return 1;
    }

    printf("Monitoring acceleration (threshold=%.2f g, addr=0x%02X)...\n",
           threshold, i2c_address);

    while (!terminate) {
        float x, y, z;

        if (read_acceleration(&x, &y, &z) == 0) {
            if (fabsf(x) > threshold || fabsf(y) > threshold ||
                fabsf(z) > threshold) {
                printf("Threshold exceeded! Shutting down...\n");
                log_acceleration(x, y, z);
                cleanup();
                system("sudo shutdown -h now");
                return 0;
            }
        } else {
            fprintf(stderr, "Warning: Sensor read error, skipping sample\n");
        }

        gpioDelay(SAMPLE_PERIOD_US);
    }

    printf("Exiting gracefully...\n");
    cleanup();
    return 0;
}

