#define LEFT_SENSOR_PIN  4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_PIN        22

#define BUFFER_SIZE 5
#define POLL_DELAY_US 10000
#define ALERT_DURATION_US 2000000
#define NO_LINE_THRESHOLD 5

typedef struct {
    int left;
    int center;
    int right;
} sensor_data_t;

static sensor_data_t sensor_buffer[BUFFER_SIZE];
static int buffer_index = 0;
static int buffer_count = 0;

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void add_to_buffer(int left, int center, int right) {
    sensor_buffer[buffer_index].left   = left;
    sensor_buffer[buffer_index].center = center;
    sensor_buffer[buffer_index].right  = right;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) buffer_count++;
}

static void print_buffer(void) {
    printf("Circular Buffer Contents:\n");
    for (int i = 0; i < buffer_count; i++) {
        int idx = (buffer_index - buffer_count + i + BUFFER_SIZE) % BUFFER_SIZE;
        printf("  [%d] L:%d C:%d R:%d\n", i,
               sensor_buffer[idx].left,
               sensor_buffer[idx].center,
               sensor_buffer[idx].right);
    }
}

static void motor_forward(void) {
    printf("Moving forward\n");
}

static void motor_left(void) {
    printf("Turning left\n");
}

static void motor_right(void) {
    printf("Turning right\n");
}

static void motor_stop(void) {
    printf("Stopping\n");
}

static void trigger_alert(void) {
    printf("ALERT: Center sensor no line for %d consecutive readings\n",
           NO_LINE_THRESHOLD);
    if (gpioWrite(ALERT_PIN, 1) < 0) {
        fprintf(stderr, "Failed to set alert pin HIGH\n");
        return;
    }
    gpioDelay(ALERT_DURATION_US);
    if (gpioWrite(ALERT_PIN, 0) < 0) {
        fprintf(stderr, "Failed to set alert pin LOW\n");
    }
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT) < 0 ||
        gpioSetMode(ALERT_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO modes\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(ALERT_PIN, 0) < 0) {
        fprintf(stderr, "Failed to initialize alert pin LOW\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Failed to register signal handler\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int no_line_count = 0;

    while (running) {
        int left   = gpioRead(LEFT_SENSOR_PIN);
        int center = gpioRead(CENTER_SENSOR_PIN);
        int right  = gpioRead(RIGHT_SENSOR_PIN);

        if (left < 0 || center < 0 || right < 0) {
            fprintf(stderr, "Sensor read error (L:%d C:%d R:%d)\n",
                    left, center, right);
            gpioDelay(POLL_DELAY_US);
            continue;
        }

        add_to_buffer(left, center, right);

        if (center == 1) {
            no_line_count++;
            if (no_line_count >= NO_LINE_THRESHOLD) {
                trigger_alert();
                no_line_count = 0;
            }
        } else {
            no_line_count = 0;
        }

        if (left == 0 && center == 0 && right == 0) {
            motor_stop();
        } else if (left == 0) {
            motor_left();
        } else if (right == 0) {
            motor_right();
        } else {
            motor_forward();
        }

        gpioDelay(POLL_DELAY_US);
    }

    motor_stop();
    gpioWrite(ALERT_PIN, 0);
    gpioTerminate();
    print_buffer();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

