#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <pigpio.h>

/* Si7210 I2C address (7-bit) */
#define SI7210_ADDR 0x30

/* Si7210 register addresses */
#define SI7210_REG_DEVICE_CONFIG 0x00
#define SI7210_REG_MAG_DATA_MSB  0x01
#define SI7210_REG_MAG_DATA_LSB  0x02
#define SI7210_REG_MAG_DATA_XLSB 0x03

/* GPIO pin for relay control (BCM numbering) */
#define RELAY_GPIO 17

/* Magnetic field threshold in mT */
#define MAGNETIC_THRESHOLD 5.0f

/* Sampling interval in microseconds (100 ms) */
#define SAMPLE_INTERVAL_US 100000

/* I2C bus on Raspberry Pi 4 */
#define I2C_BUS 1

/* Global variables */
static int i2c_handle = -1;
static volatile sig_atomic_t program_running = 1;

/* Function prototypes */
static int init_si7210(void);
static int read_magnetic_field(float *magnetic_field);
static void control_relay(int state);
static void log_event(const char *message);
static void signal_handler(int signal);
static void cleanup(void);

/* Signal handler for graceful shutdown */
static void signal_handler(int signal) {
    (void)signal;
    program_running = 0;
}

/* Cleanup resources */
static void cleanup(void) {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    control_relay(0); /* Deactivate relay */
    gpioTerminate();
}

/* Initialize the Si7210 sensor */
static int init_si7210(void) {
    /*
     * Configure Si7210 for continuous magnetic field measurement.
     * Device Config register (0x00):
     *   Bit 0: 0 = continuous mode
     *   Bit 1: 0 = normal range
     *   Bit 2: 0 = no averaging
     *   Bits 3-7: reserved
     * Value 0x00 is the default; writing 0x00 is safe.
     */
    if (i2cWriteByteData(i2c_handle, SI7210_REG_DEVICE_CONFIG, 0x00) < 0) {
        log_event("Error: Failed to write device configuration register.");
        return -1;
    }

    /* Allow sensor to stabilize after configuration */
    gpioDelay(10000); /* 10 ms */

    return 0;
}

/* Read magnetic field data from the Si7210 sensor */
static int read_magnetic_field(float *magnetic_field) {
    char buffer[3];
    int16_t raw_data;
    int32_t raw_data_extended;

    /* Read 3 bytes of magnetic field data starting from MSB register */
    if (i2cReadI2CBlockData(i2c_handle, SI7210_REG_MAG_DATA_MSB, buffer, 3) != 3) {
        log_event("Error: Failed to read magnetic field data.");
        return -1;
    }

    /* Combine the data into a 24-bit signed integer */
    raw_data = (int16_t)((buffer[0] << 8) | buffer[1]);
    raw_data_extended = (int32_t)((raw_data << 8) | buffer[2]);

    /* Convert raw data to magnetic field in mT */
    /*
     * Si7210 outputs a 24-bit signed magnetic field value.
     * The full-scale range is ±800 mT (16-bit).
     * The 24-bit value is left-justified in a 32-bit integer.
     * We shift right by 8 to get the 16-bit signed value.
     */
    *magnetic_field = (float)(raw_data_extended >> 8) / 10.0f;

    return 0;
}

/* Control the relay */
static void control_relay(int state) {
    gpioWrite(RELAY_GPIO, state);
}

/* Log events to a file */
static void log_event(const char *message) {
    FILE *fp = fopen("magnetic_events.txt", "a");
    if (fp == NULL) {
        perror("Error opening magnetic_events.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%04d-%02d-%02d %02d:%02d:%02d: %s\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
            tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO pin mode for relay control */
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    control_relay(0); /* Ensure relay is initially deactivated */

    /* Open I2C connection to Si7210 sensor */
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize the Si7210 sensor */
    if (init_si7210() != 0) {
        fprintf(stderr, "Si7210 initialization failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Set up signal handler for Ctrl+C */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        cleanup();
        return EXIT_FAILURE;
    }

    float magnetic_field;
    int relay_state = 0;
    int timeout_count = 0;
    const int timeout_limit = 50;

    /* Main loop */
    while (program_running) {
        /* Read magnetic field data */
        if (read_magnetic_field(&magnetic_field) == 0) {
            timeout_count = 0; /* Reset timeout on successful read */

            /* Check if magnetic field exceeds threshold */
            if (magnetic_field > MAGNETIC_THRESHOLD) {
                if (relay_state == 0) {
                    control_relay(1); /* Activate relay */
                    relay_state = 1;
                    log_event("Relay activated");
                }
            } else {
                if (relay_state == 1) {
                    control_relay(0); /* Deactivate relay */
                    relay_state = 0;
                    log_event("Relay deactivated");
                }
            }

            /* Log magnetic field data */
            char log_message[128];
            snprintf(log_message, sizeof(log_message),
                     "Magnetic field: %.2f mT, Relay state: %s",
                     magnetic_field, relay_state ? "ON" : "OFF");
            log_event(log_message);
        } else {
            /* On read failure, deactivate relay and retry */
            control_relay(0);
            relay_state = 0;
            log_event("Sensor read failed, relay deactivated");
        }

        /* Delay for 100 milliseconds */
        gpioDelay(SAMPLE_INTERVAL_US);

        /* Timeout check: if the sensor register does not clear after 50 cycles, skip this cycle */
        timeout_count++;
        if (timeout_count >= timeout_limit) {
            log_event("Timeout: Sensor register did not respond. Skipping cycle.");
            timeout_count = 0; /* Reset to avoid infinite loop */
        }
    }

    /* Cleanup and exit */
    log_event("Program terminated");
    cleanup();
    return EXIT_SUCCESS;
}

