    if (!str) return;
    size_t len = strlen(str);
    while (len > 0 && (str[len - 1] == ' ' || str[len - 1] == '\t' || str[len - 1] == '\r' || str[len - 1] == '\n')) {
        str[--len] = '\0';
    }
}

static int handle_command(const char *command) {
    trim_trailing_whitespace((char *)command);
    if (strcmp(command, "ON") == 0) {
