/*
 * Raspberry Pi Zero W – Dual SLF3S-1300F liquid-flow monitor with relay control.
 *
 * Hardware:
 *   - 2x Sensirion SLF3S-1300F (40 ml/min) on I2C bus 1
 *     (addresses 0x61 and 0x62)
 *   - Safety relay on GPIO 18 (BCM), active-high
 *
 * Build:
 *   gcc -Wall -Wextra -O2 -o flow_monitor flow_monitor.c -lpigpio -lrt
 *
 * Run:
 *   sudo ./flow_monitor
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

#include <pigpio.h>

/* ----------------------------- Constants ------------------------------- */

#define I2C_BUS              1
#define SENSOR1_ADDR         0x61
#define SENSOR2_ADDR         0x62
#define RELAY_GPIO           18          /* BCM pin */

#define FLOW_THRESHOLD_ML_MIN 5.0f
#define POLL_DELAY_US        100000      /* 100 ms */
#define LOG_FILE             "flow_log.txt"

/* SLF3S-1300F start-measurement command (two bytes, no data byte) */
#define CMD_START_MEAS_MSB   0x36
#define CMD_START_MEAS_LSB   0x08

/* --------------------------- Global state ------------------------------ */

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle1 = -1;
static int  g_i2c_handle2 = -1;
static bool g_relay_state = false;

/* ------------------------- Function prototypes ------------------------- */

static void signal_handler(int sig);
static void cleanup(void);
static uint8_t crc8(const uint8_t *data, int len);
static int  init_sensor(int handle);
static int  read_flow_rate(int handle, float *flow_out);
static void control_relay(float flow1, float flow2);
static void log_flow_rates(float flow1, float flow2);

/* ------------------------------ Signal handler ------------------------- */

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Cleanup -------------------------------- */

static void cleanup(void)
{
    if (g_relay_state) {
        gpioWrite(RELAY_GPIO, 0);
        g_relay_state = false;
    }

    if (g_i2c_handle1 >= 0) {
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
    }
    if (g_i2c_handle2 >= 0) {
        i2cClose(g_i2c_handle2);
        g_i2c_handle2 = -1;
    }

    gpioTerminate();
}

/* ------------------------------- CRC-8 ---------------------------------- */

/* Sensirion CRC-8: polynomial 0x31, init 0xFF, no final XOR */
static uint8_t crc8(const uint8_t *data, int len)
{
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int b = 0; b < 8; b++) {
            if (crc & 0x80)
                crc = (uint8_t)((crc << 1) ^ 0x31);
            else
                crc = (uint8_t)(crc << 1);
        }
    }
    return crc;
}

/* --------------------------- Sensor init -------------------------------- */

static int init_sensor(int handle)
{
    uint8_t cmd[2] = { CMD_START_MEAS_MSB, CMD_START_MEAS_LSB };
    int rc = i2cWriteDevice(handle, (char *)cmd, 2);
    if (rc != 0) {
        fprintf(stderr, "[ERROR] i2cWriteDevice failed on handle %d (rc=%d)\n",
                handle, rc);
        return -1;
    }
    return 0;
}

/* ----------------------- Read flow rate --------------------------------- */

/*
 * SLF3S-1300F read: 3 bytes = [MSB, LSB, CRC].
 * Flow rate = (MSB << 8 | LSB) / 100  ml/min.
 */
static int read_flow_rate(int handle, float *flow_out)
{
    uint8_t buf[3];
    int rc = i2cReadDevice(handle, (char *)buf, 3);
    if (rc != 3) {
        fprintf(stderr, "[WARN] i2cReadDevice returned %d (expected 3)\n", rc);
        return -1;
    }

    if (crc8(buf, 2) != buf[2]) {
        fprintf(stderr, "[WARN] CRC mismatch on handle %d\n", handle);
        return -1;
    }

    uint16_t raw = (uint16_t)((buf[0] << 8) | buf[1]);
    *flow_out = (float)raw / 100.0f;
    return 0;
}

/* --------------------------- Relay control ------------------------------ */

static void control_relay(float flow1, float flow2)
{
    bool below = (flow1 < FLOW_THRESHOLD_ML_MIN) ||
                 (flow2 < FLOW_THRESHOLD_ML_MIN);

    if (below && !g_relay_state) {
        if (gpioWrite(RELAY_GPIO, 1) == 0) {
            g_relay_state = true;
            printf("[INFO] Relay energized (flow below %.1f ml/min)\n",
                   FLOW_THRESHOLD_ML_MIN);
        } else {
            fprintf(stderr, "[ERROR] gpioWrite(1) failed on GPIO %d\n",
                    RELAY_GPIO);
        }
    } else if (!below && g_relay_state) {
        if (gpioWrite(RELAY_GPIO, 0) == 0) {
            g_relay_state = false;
            printf("[INFO] Relay de-energized (flow above %.1f ml/min)\n",
                   FLOW_THRESHOLD_ML_MIN);
        } else {
            fprintf(stderr, "[ERROR] gpioWrite(0) failed on GPIO %d\n",
                    RELAY_GPIO);
        }
    }
}

/* --------------------------- Log flow rates ----------------------------- */

static void log_flow_rates(float flow1, float flow2)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("[WARN] clock_gettime");
        return;
    }

    struct tm tm_local;
    localtime_r(&ts.tv_sec, &tm_local);

    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_local);

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return;
    }

    fprintf(fp, "%s.%03ld,%.2f,%.2f\n",
            tbuf, ts.tv_nsec / 1000000L, flow1, flow2);
    fflush(fp);
    fclose(fp);
}

/* --------------------------------- main --------------------------------- */

int main(void)
{
    /* --- pigpio init -------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* --- relay GPIO setup -------------------------------------------- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n",
                RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);
    g_relay_state = false;

    /* --- open I2C handles -------------------------------------------- */
    g_i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_handle1 < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SENSOR1_ADDR, g_i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_handle2 < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SENSOR2_ADDR, g_i2c_handle2);
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- start measurement ------------------------------------------- */
    if (init_sensor(g_i2c_handle1) != 0 || init_sensor(g_i2c_handle2) != 0) {
        fprintf(stderr, "[FATAL] Sensor init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- signals ----------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Monitoring started (threshold %.1f ml/min). Ctrl+C to exit.\n",
           FLOW_THRESHOLD_ML_MIN);

    /* --- main loop --------------------------------------------------- */
    while (g_running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int   ok1 = read_flow_rate(g_i2c_handle1, &flow1);
        int   ok2 = read_flow_rate(g_i2c_handle2, &flow2);

        if (ok1 == 0 && ok2 == 0) {
            log_flow_rates(flow1, flow2);
            control_relay(flow1, flow2);
        } else {
            if (ok1 != 0)
                fprintf(stderr, "[WARN] Sensor 1 read failed\n");
            if (ok2 != 0)
                fprintf(stderr, "[WARN] Sensor 2 read failed\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- graceful shutdown ------------------------------------------ */
    printf("\n[INFO] Shutting down...\n");
    cleanup();
    printf("[INFO] Done.\n");
    return EXIT_SUCCESS;
}

