                    RELAY_GPIO);
        }
    } else if (!below && g_relay_state) {
        if (gpioWrite(RELAY_GPIO, 0) == 0) {
            g_relay_state = false;
            printf("[INFO] Relay de-energized (flow above %.1f ml/min)\n",
                   FLOW_THRESHOLD_ML_MIN);
        } else {
            fprintf(stderr, "[ERROR] gpioWrite(0) failed on GPIO %d\n",
                    RELAY_GPIO);
        }
    }
}

/* --------------------------- Log flow rates ----------------------------- */

static void log_flow_rates(float flow1, float flow2)
{
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("[WARN] clock_gettime");
        return;
    }

    struct tm tm_local;
    localtime_r(&ts.tv_sec, &tm_local);

    char tbuf[32];
    strftime(tbuf, sizeof(tbuf), "%Y-%m-%d %H:%M:%S", &tm_local);

    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        perror("[ERROR] fopen(" LOG_FILE ")");
        return;
    }

    fprintf(fp, "%s.%03ld,%.2f,%.2f\n",
            tbuf, ts.tv_nsec / 1000000L, flow1, flow2);
    fflush(fp);
    fclose(fp);
}

/* --------------------------------- main --------------------------------- */

int main(void)
{
    /* --- pigpio init -------------------------------------------------- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "[FATAL] gpioInitialise failed\n");
        return EXIT_FAILURE;
    }

    /* --- relay GPIO setup -------------------------------------------- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "[FATAL] gpioSetMode(%d, PI_OUTPUT) failed\n",
                RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);
    g_relay_state = false;

    /* --- open I2C handles -------------------------------------------- */
    g_i2c_handle1 = i2cOpen(I2C_BUS, SENSOR1_ADDR, 0);
    if (g_i2c_handle1 < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SENSOR1_ADDR, g_i2c_handle1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_i2c_handle2 = i2cOpen(I2C_BUS, SENSOR2_ADDR, 0);
    if (g_i2c_handle2 < 0) {
        fprintf(stderr, "[FATAL] i2cOpen(bus=%d, addr=0x%02X) failed: %d\n",
                I2C_BUS, SENSOR2_ADDR, g_i2c_handle2);
        i2cClose(g_i2c_handle1);
        g_i2c_handle1 = -1;
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- start measurement ------------------------------------------- */
    if (init_sensor(g_i2c_handle1) != 0 || init_sensor(g_i2c_handle2) != 0) {
        fprintf(stderr, "[FATAL] Sensor init failed\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* --- signals ----------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("[INFO] Monitoring started (threshold %.1f ml/min). Ctrl+C to exit.\n",
           FLOW_THRESHOLD_ML_MIN);

    /* --- main loop --------------------------------------------------- */
    while (g_running) {
        float flow1 = 0.0f, flow2 = 0.0f;
        int   ok1 = read_flow_rate(g_i2c_handle1, &flow1);
        int   ok2 = read_flow_rate(g_i2c_handle2, &flow2);

        if (ok1 == 0 && ok2 == 0) {
            log_flow_rates(flow1, flow2);
            control_relay(flow1, flow2);
        } else {
            if (ok1 != 0)
                fprintf(stderr, "[WARN] Sensor 1 read failed\n");
            if (ok2 != 0)
                fprintf(stderr, "[WARN] Sensor 2 read failed\n");
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- graceful shutdown ------------------------------------------ */
    printf("\n[INFO] Shutting down...\n");
    cleanup();
    printf("[INFO] Done.\n");
    return EXIT_SUCCESS;
}

