#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN   22
#define MOTOR_IN1_PIN   23
#define MOTOR_IN2_PIN   24
#define POLL_INTERVAL_US 200000   /* 200 ms */
#define MOTOR_RUN_US    5000000   /* 5 s   */
#define CONFIRM_POLLS   3         /* dry for 3 × 200 ms = 600 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/*
 * Safely drive a GPIO pin and log the result.
 * Returns 0 on success, -1 on failure.
 */
static int safe_write(unsigned pin, unsigned level)
{
    if (gpioWrite(pin, level) < 0) {
        syslog(LOG_ERR, "gpioWrite(pin=%u, level=%u) failed", pin, level);
        return -1;
    }
    return 0;
}

/*
 * Stop the motor: ENA low, both inputs low.
 */
static void motor_stop(void)
{
    safe_write(MOTOR_ENA_PIN, 0);
    safe_write(MOTOR_IN1_PIN, 0);
    safe_write(MOTOR_IN2_PIN, 0);
}

/*
 * Run the window close sequence: ENA high, IN1 high, IN2 low,
 * hold for MOTOR_RUN_US, then stop.
 */
static void close_window(void)
{
    syslog(LOG_INFO, "Closing window...");

    if (safe_write(MOTOR_ENA_PIN, 1) < 0) {
        syslog(LOG_ERR, "Failed to enable motor");
        return;
    }
    if (safe_write(MOTOR_IN1_PIN, 1) < 0) {
        syslog(LOG_ERR, "Failed to set IN1 high");
        motor_stop();
        return;
    }
    if (safe_write(MOTOR_IN2_PIN, 0) < 0) {
        syslog(LOG_ERR, "Failed to set IN2 low");
        motor_stop();
        return;
    }

    /*
     * gpioDelay is a pigpio microsecond delay that is not a busy-wait.
     * It returns the actual delay (may be slightly less than requested).
     */
    int elapsed = gpioDelay(MOTOR_RUN_US);
    if (elapsed < 0) {
        syslog(LOG_ERR, "gpioDelay(%d) failed", MOTOR_RUN_US);
    }

    motor_stop();
    syslog(LOG_INFO, "Window close sequence complete.");
}

int main(void)
{
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    /*
     * Register signal handlers for graceful shutdown.
     * SIGINT  (Ctrl+C) and SIGTERM (kill) are caught.
     */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGINT) failed");
        closelog();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction(SIGTERM) failed");
        closelog();
        return EXIT_FAILURE;
    }

    /*
     * Initialize pigpio.
     */
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        closelog();
        return EXIT_FAILURE;
    }

    /*
     * Configure rain sensor pin as input with pull-up.
     * The Seeed Rain Sensor v1.0 DO pin is open-collector-style:
     *   DO = 0 ⇒ rain detected (window closed)
     *   DO = 1 ⇒ dry (window open)
     */
    if (gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(RAIN_SENSOR_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(RAIN_SENSOR_PIN, PI_PUD_UP) < 0) {
        syslog(LOG_ERR, "gpioSetPullUpDown(RAIN_SENSOR_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /*
     * Configure motor control pins as outputs.
     */
    if (gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(MOTOR_ENA_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(MOTOR_IN1_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT) < 0) {
        syslog(LOG_ERR, "gpioSetMode(MOTOR_IN2_PIN) failed");
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    /*
     * Ensure the motor is stopped at startup.
     */
    motor_stop();

    syslog(LOG_INFO, "Rain sensor monitoring started (GPIO %d). "
                    "Motor ENA=GPIO%d, IN1=GPIO%d, IN2=GPIO%d.",
           RAIN_SENSOR_PIN, MOTOR_ENA_PIN, MOTOR_IN1_PIN, MOTOR_IN2_PIN);

    int last_state = gpioRead(RAIN_SENSOR_PIN);
    if (last_state < 0) {
        syslog(LOG_ERR, "Initial gpioRead(RAIN_SENSOR_PIN) failed");
        motor_stop();
        gpioTerminate();
        closelog();
        return EXIT_FAILURE;
    }

    int dry_count = 0;

    /*
     * Main polling loop.
     */
    while (g_running) {
        int current_state = gpioRead(RAIN_SENSOR_PIN);
        if (current_state < 0) {
            syslog(LOG_ERR, "gpioRead(RAIN_SENSOR_PIN) failed");
            usleep(POLL_INTERVAL_US);
            continue;
        }

        /*
         * Detect rising edge: dry (1) -> wet (0).
         * Only act on the first edge of a dry period.
         */
        if (current_state == 0 && last_state == 1) {
            syslog(LOG_INFO, "Rain detected (DO=0).");
            close_window();
            dry_count = 0;
        } else if (current_state == 1) {
            dry_count++;
        }

        last_state = current_state;
        usleep(POLL_INTERVAL_US);
    }

    /*
     * Graceful shutdown: stop the motor and release pigpio.
     */
    syslog(LOG_INFO, "Shutting down...");
    motor_stop();
    gpioTerminate();
    closelog();
    return EXIT_SUCCESS;
}

