#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO_PIN      18
#define LOCK_BUTTON    21
#define UNLOCK_BUTTON  22

#define LOCK_PULSE_US   2000   /* 2 ms  -> ~135 deg (typical hobby servo) */
#define UNLOCK_PULSE_US 1000   /* 1 ms  -> ~45  deg */
#define STOP_PULSE_US   0      /* stop sending pulses */
#define POLL_DELAY_US   20000  /* 20 ms */
#define DEBOUNCE_US     50000  /* 50 ms */

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int set_servo_pulse(int pulse_us)
{
    int rc = gpioServo(SERVO_PIN, pulse_us);
    if (rc < 0) {
        fprintf(stderr, "gpioServo failed (pin=%d, pulse=%d us): %s\n",
                SERVO_PIN, pulse_us, pigpio_error(rc));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    /* Stop servo pulses and release the line. */
    (void)gpioServo(SERVO_PIN, STOP_PULSE_US);
    gpioTerminate();
}

int main(void)
{
    /* --- Initialize pigpio --- */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* --- Configure button pins as inputs with pull-ups --- */
    if (gpioSetMode(LOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set LOCK_BUTTON mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(UNLOCK_BUTTON, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set UNLOCK_BUTTON mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(LOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set LOCK_BUTTON pull-up\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetPullUpDown(UNLOCK_BUTTON, PI_PUD_UP) < 0) {
        fprintf(stderr, "Failed to set UNLOCK_BUTTON pull-up\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- Install signal handlers for graceful shutdown --- */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Door lock control started.\n");
    printf("  Servo : GPIO %d (BCM)\n", SERVO_PIN);
    printf("  Lock  : GPIO %d (BCM, active-low, pull-up)\n", LOCK_BUTTON);
    printf("  Unlock: GPIO %d (BCM, active-low, pull-up)\n", UNLOCK_BUTTON);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        /* Lock button pressed (active-low) */
        if (gpioRead(LOCK_BUTTON) == 0) {
            if (set_servo_pulse(LOCK_PULSE_US) == 0) {
                printf("Door locked.\n");
            }
            /* Debounce: wait for button release, then wait a bit more. */
            while (g_running && gpioRead(LOCK_BUTTON) == 0) {
                gpioDelay(POLL_DELAY_US);
            }
            gpioDelay(DEBOUNCE_US);
        }

        /* Unlock button pressed (active-low) */
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            if (set_servo_pulse(UNLOCK_PULSE_US) == 0) {
                printf("Door unlocked.\n");
            }
            /* Debounce */
            while (g_running && gpioRead(UNLOCK_BUTTON) == 0) {
                gpioDelay(POLL_DELAY_US);
            }
            gpioDelay(DEBOUNCE_US);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Door lock control stopped.\n");
    return EXIT_SUCCESS;
}

