    printf("  Lock  : GPIO %d (BCM, active-low, pull-up)\n", LOCK_BUTTON);
    printf("  Unlock: GPIO %d (BCM, active-low, pull-up)\n", UNLOCK_BUTTON);
    printf("Press Ctrl+C to exit.\n");

    /* --- Main polling loop --- */
    while (g_running) {
        /* Lock button pressed (active-low) */
        if (gpioRead(LOCK_BUTTON) == 0) {
            if (set_servo_pulse(LOCK_PULSE_US) == 0) {
                printf("Door locked.\n");
            }
            /* Debounce: wait for button release, then wait a bit more. */
            while (g_running && gpioRead(LOCK_BUTTON) == 0) {
                gpioDelay(POLL_DELAY_US);
            }
            gpioDelay(DEBOUNCE_US);
        }

        /* Unlock button pressed (active-low) */
        if (gpioRead(UNLOCK_BUTTON) == 0) {
            if (set_servo_pulse(UNLOCK_PULSE_US) == 0) {
                printf("Door unlocked.\n");
            }
            /* Debounce */
            while (g_running && gpioRead(UNLOCK_BUTTON) == 0) {
                gpioDelay(POLL_DELAY_US);
            }
            gpioDelay(DEBOUNCE_US);
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* --- Graceful shutdown --- */
    printf("\nShutting down...\n");
    cleanup();
    printf("Door lock control stopped.\n");
    return EXIT_SUCCESS;
}

