#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_PIN 4
#define FAN_PIN 17
#define LOG_FILE "security_log.txt"
#define POLL_INTERVAL_US 100000
#define FAN_ON_DURATION_S 60

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int log_event(const char *event_type, double duration) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    if (t == (time_t)-1) {
        perror("time() failed");
        fclose(fp);
        return -1;
    }

    struct tm tm_info;
    if (localtime_r(&t, &tm_info) == NULL) {
        perror("localtime_r() failed");
        fclose(fp);
        return -1;
    }

    char timestamp[32];
    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "strftime() failed\n");
        fclose(fp);
        return -1;
    }

    if (fprintf(fp, "%s - %s - Duration: %.2f seconds\n", timestamp, event_type, duration) < 0) {
        perror("fprintf() failed");
        fclose(fp);
        return -1;
    }

    if (fclose(fp) != 0) {
        perror("fclose() failed");
        return -1;
    }

    return 0;
}

static int control_fan(int state) {
    if (gpioWrite(FAN_PIN, state) != 0) {
        fprintf(stderr, "Failed to write to fan pin %d\n", FAN_PIN);
        return -1;
    }
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set PIR pin %d as input\n", PIR_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FAN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set fan pin %d as output\n", FAN_PIN);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (control_fan(0) != 0) {
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT) failed");
        control_fan(0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM) failed");
        control_fan(0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Security system started. Monitoring PIR on GPIO %d, fan on GPIO %d.\n", PIR_PIN, FAN_PIN);
    printf("Press Ctrl+C to exit.\n");

    int last_pir_state = 0;

    while (g_running) {
        int pir_state = gpioRead(PIR_PIN);
        if (pir_state < 0) {
            fprintf(stderr, "Failed to read PIR pin %d\n", PIR_PIN);
            break;
        }

        if (pir_state == 1 && last_pir_state == 0) {
            printf("Motion detected! Activating floodlight for %d seconds.\n", FAN_ON_DURATION_S);

            if (control_fan(1) != 0) {
                break;
            }

            time_t start_time = time(NULL);
            if (start_time == (time_t)-1) {
                perror("time() failed");
                control_fan(0);
                break;
            }

            while (g_running) {
                time_t current_time = time(NULL);
                if (current_time == (time_t)-1) {
                    perror("time() failed");
                    control_fan(0);
                    break;
                }

                double elapsed = difftime(current_time, start_time);
                if (elapsed >= FAN_ON_DURATION_S) {
                    break;
                }

                gpioDelay(POLL_INTERVAL_US);
            }

            if (control_fan(0) != 0) {
                break;
            }

            time_t end_time = time(NULL);
            if (end_time == (time_t)-1) {
                perror("time() failed");
                break;
            }

            double duration = difftime(end_time, start_time);
            if (log_event("Deactivation", duration) != 0) {
                fprintf(stderr, "Failed to log deactivation event.\n");
            }
        }

        last_pir_state = pir_state;
        gpioDelay(POLL_INTERVAL_US);
    }

    control_fan(0);
    gpioTerminate();
    printf("Security system stopped.\n");
    return EXIT_SUCCESS;
}

