/*
 * MPR121 Capacitive Touch Relay Toggle for Raspberry Pi 5
 *
 * Wiring:
 *   MPR121 SDA -> GPIO2 (I2C1 SDA)
 *   MPR121 SCL -> GPIO3 (I2C1 SCL)
 *   MPR121 ADDR -> GND (I2C address 0x5A)
 *   Relay IN   -> GPIO17 (BCM)
 *
 * Build: gcc -Wall -O2 -o mpr121_relay mpr121_relay.c -lpigpio -lrt
 * Run:   sudo ./mpr121_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS        1
#define MPR121_ADDR    0x5A
#define RELAY_GPIO     17

/* MPR121 Register Map */
#define MPR121_TOUCHSTATUS_L  0x00
#define MPR121_TOUCHSTATUS_H  0x01
#define MPR121_ECR            0x5E
#define MPR121_CONFIG1        0x5B
#define MPR121_CONFIG2        0x5C
#define MPR121_MHD_R          0x2B
#define MPR121_NHD_R          0x2C
#define MPR121_NCL_R          0x2D
#define MPR121_FDL_R          0x2E
#define MPR121_DEBOUNCE       0x5B
#define MPR121_AUTO_CONFIG0   0x7B
#define MPR121_AUTO_CONFIG1   0x7C
#define MPR121_USL            0x7D
#define MPR121_LSL            0x7E
#define MPR121_TL             0x7F

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

/* Write a single byte to an MPR121 register; returns 0 on success, -1 on error. */
static int mpr121_write_reg(int handle, uint8_t reg, uint8_t value) {
    if (i2cWriteByteData(handle, reg, value) < 0) {
        fprintf(stderr, "Error: I2C write failed (reg=0x%02X, val=0x%02X)\n", reg, value);
        return -1;
    }
    return 0;
}

/* Read a single byte from an MPR121 register; returns byte value (0-255) or -1 on error. */
static int mpr121_read_reg(int handle, uint8_t reg) {
    int v = i2cReadByteData(handle, reg);
    if (v < 0) {
        fprintf(stderr, "Error: I2C read failed (reg=0x%02X)\n", reg);
        return -1;
    }
    return v;
}

/* Initialize the MPR121 with documented filter/sample values. */
static int mpr121_init(int handle) {
    /* Soft reset: write 0x63 to ECR */
    if (mpr121_write_reg(handle, MPR121_ECR, 0x63) < 0) return -1;
    gpioDelay(1000); /* 1 ms settle */

    /* Baseline filtering – recommended values from datasheet */
    if (mpr121_write_reg(handle, MPR121_MHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NHD_R, 0x01) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_NCL_R, 0x00) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_FDL_R, 0x00) < 0) return -1;

    /* Debounce: 3 samples for touch, 3 for release */
    if (mpr121_write_reg(handle, MPR121_DEBOUNCE, 0x33) < 0) return -1;

    /* Auto-config: enable, 4 samples, 0.5 µA charge current */
    if (mpr121_write_reg(handle, MPR121_AUTO_CONFIG0, 0x0B) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_AUTO_CONFIG1, 0x00) < 0) return -1;

    /* Upper/lower/target limits for auto-config */
    if (mpr121_write_reg(handle, MPR121_USL, 200) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_LSL, 130) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_TL, 180) < 0) return -1;

    /* FFI=6 samples, SFI=4 samples, ESI=4 ms */
    if (mpr121_write_reg(handle, MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write_reg(handle, MPR121_CONFIG2, 0x20) < 0) return -1;

    /* Enable 12 electrodes, baseline tracking, no ESI override */
    if (mpr121_write_reg(handle, MPR121_ECR, 0x8C) < 0) return -1;

    return 0;
}

/* Read the 12-bit touch status for electrode 0. */
static int mpr121_read_e0(int handle) {
    int lo = mpr121_read_reg(handle, MPR121_TOUCHSTATUS_L);
    if (lo < 0) return -1;
    return (lo >> 0) & 0x01;
}

int main(void) {
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus 1 at address 0x5A */
    g_i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus %d at addr 0x%02X (err=%d)\n",
                I2C_BUS, MPR121_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init(g_i2c_handle) < 0) {
        fprintf(stderr, "Error: MPR121 initialization failed (sensor absent or bus error)\n");
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", RELAY_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0); /* Ensure relay starts OFF */

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 relay toggle ready. Touch electrode 0 to toggle relay. Ctrl+C to exit.\n");

    bool relay_state = false;
    bool e0_touched = false;

    while (g_running) {
        int touch = mpr121_read_e0(g_i2c_handle);
        if (touch < 0) {
            fprintf(stderr, "Warning: I2C read error, retrying...\n");
            gpioDelay(100000); /* 100 ms backoff */
            continue;
        }

        if (touch && !e0_touched) {
            /* Debounce: wait 200 ms, then re-read to confirm */
            gpioDelay(200000);
            int confirm = mpr121_read_e0(g_i2c_handle);
            if (confirm > 0) {
                relay_state = !relay_state;
                gpioWrite(RELAY_GPIO, relay_state ? 1 : 0);
                printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
            }
        }

        e0_touched = (touch != 0);
        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

