        fprintf(stderr, "Error: Failed to set GPIO %d as output\n", RELAY_GPIO);
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0); /* Ensure relay starts OFF */

    /* Install signal handlers */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 relay toggle ready. Touch electrode 0 to toggle relay. Ctrl+C to exit.\n");

    bool relay_state = false;
    bool e0_touched = false;

    while (g_running) {
        int touch = mpr121_read_e0(g_i2c_handle);
        if (touch < 0) {
            fprintf(stderr, "Warning: I2C read error, retrying...\n");
            gpioDelay(100000); /* 100 ms backoff */
            continue;
        }

        if (touch && !e0_touched) {
            /* Debounce: wait 200 ms, then re-read to confirm */
            gpioDelay(200000);
            int confirm = mpr121_read_e0(g_i2c_handle);
            if (confirm > 0) {
                relay_state = !relay_state;
                gpioWrite(RELAY_GPIO, relay_state ? 1 : 0);
                printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
            }
        }

        e0_touched = (touch != 0);
        gpioDelay(10000); /* 10 ms poll interval */
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    gpioWrite(RELAY_GPIO, 0);
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
    }
    gpioTerminate();
    return EXIT_SUCCESS;
}

