#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <errno.h>
#include <stdarg.h>
#include <pigpio.h>

#define SERVO_PIN 17
#define PIR_PIN 4
#define PORT 5000
#define LOG_FILE "security.log"
#define PWM_FREQ 50
#define PWM_RANGE 2000000  /* 2,000,000 us = 20 ms period (50 Hz) */
#define MIN_PULSE_WIDTH 1000  /* 1 ms */
#define MAX_PULSE_WIDTH 2000  /* 2 ms */

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static FILE *log_fp = NULL;

static void log_message(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(LOG_INFO, format, args);
    va_end(args);

    if (log_fp) {
        time_t t = time(NULL);
        struct tm tm;
        if (localtime_r(&t, &tm)) {
            fprintf(log_fp, "[%04d-%02d-%02d %02d:%02d:%02d] ",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                    tm.tm_hour, tm.tm_min, tm.tm_sec);
            vfprintf(log_fp, format, args);
            fputc('\n', log_fp);
            fflush(log_fp);
        }
    }
}

static void log_error(const char *format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(LOG_ERR, format, args);
    va_end(args);

    if (log_fp) {
        time_t t = time(NULL);
        struct tm tm;
        if (localtime_r(&t, &tm)) {
            fprintf(log_fp, "[%04d-%02d-%02d %02d:%02d:%02d] ERROR: ",
                    tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                    tm.tm_hour, tm.tm_min, tm.tm_sec);
            vfprintf(log_fp, format, args);
            fputc('\n', log_fp);
            fflush(log_fp);
        }
    }
}

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        log_error("pigpio initialisation failed");
        return -1;
    }

    if (gpioSetMode(SERVO_PIN, PI_OUTPUT) != 0) {
        log_error("Failed to set servo pin %d as output", SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        log_error("Failed to set PIR pin %d as input", PIR_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMfrequency(SERVO_PIN, PWM_FREQ) != 0) {
        log_error("Failed to set PWM frequency on pin %d", SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(SERVO_PIN, PWM_RANGE) != 0) {
        log_error("Failed to set PWM range on pin %d", SERVO_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void set_servo_angle(int angle) {
    if (angle < 0) angle = 0;
    if (angle > 180) angle = 180;

    int pulse_width = MIN_PULSE_WIDTH +
        (int)((long)angle * (MAX_PULSE_WIDTH - MIN_PULSE_WIDTH) / 180);

    if (gpioServo(SERVO_PIN, pulse_width) != 0) {
        log_error("Failed to set servo pulse width to %d us", pulse_width);
    } else {
        log_message("Servo set to angle %d (pulse %d us)", angle, pulse_width);
    }
}

static int read_pir_sensor(void) {
    int value = gpioRead(PIR_PIN);
    if (value < 0) {
        log_error("Failed to read PIR sensor on pin %d", PIR_PIN);
        return -1;
    }
    return value;
}

static void handle_client(int client_socket) {
    char buffer[1024];
    ssize_t bytes_received;

    while ((bytes_received = recv(client_socket, buffer, sizeof(buffer) - 1, 0)) > 0) {
        buffer[bytes_received] = '\0';
        buffer[strcspn(buffer, "\r\n")] = '\0';

        log_message("Received command: %s", buffer);

        if (strcmp(buffer, "PIR") == 0) {
            int pir_value = read_pir_sensor();
            if (pir_value >= 0) {
                char response[64];
                snprintf(response, sizeof(response), "PIR:%d", pir_value);
                if (send(client_socket, response, strlen(response), 0) < 0) {
                    log_error("send() failed: %s", strerror(errno));
                }
            } else {
                const char *err = "PIR:ERROR";
                if (send(client_socket, err, strlen(err), 0) < 0) {
                    log_error("send() failed: %s", strerror(errno));
                }
            }
        } else {
            int angle;
            if (sscanf(buffer, "servo %d", &angle) == 1) {
                set_servo_angle(angle);
            } else {
                const char *err = "Invalid command";
                if (send(client_socket, err, strlen(err), 0) < 0) {
                    log_error("send() failed: %s", strerror(errno));
                }
            }
        }
    }

    if (bytes_received < 0) {
        log_error("recv() failed: %s", strerror(errno));
    }

    close(client_socket);
    log_message("Client disconnected");
}

int main(void) {
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    log_fp = fopen(LOG_FILE, "a");
    if (!log_fp) {
        syslog(LOG_ERR, "Failed to open log file %s: %s", LOG_FILE, strerror(errno));
        closelog();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        log_error("sigaction(SIGINT) failed: %s", strerror(errno));
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("sigaction(SIGTERM) failed: %s", strerror(errno));
    }

    if (init_gpio() != 0) {
        log_error("GPIO initialization failed, exiting");
        fclose(log_fp);
        closelog();
        return 1;
    }

    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        log_error("socket() failed: %s", strerror(errno));
        gpioTerminate();
        fclose(log_fp);
        closelog();
        return 1;
    }

    int opt = 1;
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
        log_error("setsockopt() failed: %s", strerror(errno));
        close(server_fd);
        gpioTerminate();
        fclose(log_fp);
        closelog();
        return 1;
    }

    struct sockaddr_in address;
    memset(&address, 0, sizeof(address));
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_error("bind() failed: %s", strerror(errno));
        close(server_fd);
        gpioTerminate();
        fclose(log_fp);
        closelog();
        return 1;
    }

    if (listen(server_fd, 3) < 0) {
        log_error("listen() failed: %s", strerror(errno));
        close(server_fd);
        gpioTerminate();
        fclose(log_fp);
        closelog();
        return 1;
    }

    log_message("Server listening on port %d", PORT);

    while (running) {
        struct sockaddr_in client_addr;
        socklen_t client_len = sizeof(client_addr);
        int client_socket = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);

        if (client_socket < 0) {
            if (running && errno != EINTR) {
                log_error("accept() failed: %s", strerror(errno));
            }
            continue;
        }

        log_message("Client connected from %s:%d",
                    inet_ntoa(client_addr.sin_addr),
                    ntohs(client_addr.sin_port));

        handle_client(client_socket);
    }

    log_message("Shutting down...");

    if (server_fd >= 0) {
        close(server_fd);
    }
    gpioTerminate();
    if (log_fp) {
        fclose(log_fp);
    }
    closelog();

    return 0;
}

