#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define BH1750_ADDR             0x23
#define BH1750_CONT_HIGH_RES    0x10  /* One-Time High-Resolution (1 lux, ~120 ms) */
#define BH1750_MEASURE_MS       120   /* Max conversion time for high-res mode */
#define SAMPLE_INTERVAL_S       2
#define LUX_THRESHOLD           150.0f
#define RELAY_GPIO              23
#define LOG_FILE                "grow_log.txt"

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_handle = -1;
static FILE *g_log_file  = NULL;

/* ------------------------------------------------------------------ */
/* Signal handler — set flag so main loop can exit cleanly            */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Write a timestamped line to the log file                            */
/* ------------------------------------------------------------------ */
static void log_line(const char *msg)
{
    if (!g_log_file)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s %s\n", ts, msg);
    fflush(g_log_file);
}

/* ------------------------------------------------------------------ */
/* Trigger a one-shot measurement and read the 2-byte result           */
/* ------------------------------------------------------------------ */
static int read_bh1750(float *lux_out)
{
    char cmd = BH1750_CONT_HIGH_RES;
    char buf[2];

    /* Send the one-time measurement command */
    if (i2cWriteDevice(g_i2c_handle, &cmd, 1) != 0) {
        log_line("ERROR: I2C write failed (sensor may be absent or bus error)");
        return -1;
    }

    /* Wait for the conversion to complete */
    gpioDelay(BH1750_MEASURE_MS * 1000);  /* microseconds */

    /* Read the 2-byte result */
    if (i2cReadDevice(g_i2c_handle, buf, 2) != 2) {
        log_line("ERROR: I2C read failed (sensor may be absent or bus error)");
        return -1;
    }

    uint16_t raw = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    *lux_out = (float)raw / 1.2f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Control the relay and log the reading                               */
/* ------------------------------------------------------------------ */
static void control_relay(float lux)
{
    int target = (lux < LUX_THRESHOLD) ? 1 : 0;
    int current = gpioRead(RELAY_GPIO);

    if (target != current) {
        if (gpioWrite(RELAY_GPIO, target) == 0) {
            log_line(target ? "Relay ON" : "Relay OFF");
        } else {
            log_line("ERROR: Failed to write relay GPIO");
        }
    }

    char msg[128];
    snprintf(msg, sizeof(msg), "Lux: %.2f, Relay: %s",
             lux, target ? "ON" : "OFF");
    log_line(msg);
}

/* ------------------------------------------------------------------ */
/* Cleanup — release all resources                                     */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    /* Ensure relay is off before terminating pigpio */
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- relay GPIO setup ------------------------------------------- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);  /* start with relay OFF */

    /* --- I2C open --------------------------------------------------- */
    g_i2c_handle = i2cOpen(1, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus 1 at addr 0x%02X: %d\n",
                BH1750_ADDR, g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- log file --------------------------------------------------- */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        i2cClose(g_i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signals ---------------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT,  &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_line("Program started");

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        float lux;
        if (read_bh1750(&lux) == 0) {
            control_relay(lux);
        } else {
            log_line("WARN: Sensor read failed, will retry next cycle");
        }

        /* Sleep in 100 ms slices so signals are caught promptly */
        for (int i = 0; i < SAMPLE_INTERVAL_S * 10 && g_running; i++)
