/*
 * Weight monitoring with TAL220B load cell + HX711 amplifier on Raspberry Pi 3 B+.
 *
 * Wiring:
 *   HX711 DOUT  -> GPIO23 (physical pin 16)
 *   HX711 SCK   -> GPIO24 (physical pin 18)
 *   Solenoid    -> GPIO25 (physical pin 22) via appropriate driver/MOSFET
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o weight_monitor weight_monitor.c -lgpiod -lm
 *
 * Run:
 *   sudo ./weight_monitor [--threshold <grams>] [--scale <factor>] [--duration <ms>]
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <errno.h>
#include <math.h>
#include <getopt.h>
#include <gpiod.h>

#define HX711_DOUT_PIN  23
#define HX711_SCK_PIN   24
#define SOLENOID_PIN    25

#define HX711_TIMEOUT_US 1000000   /* 1 s timeout waiting for DOUT low */
#define HX711_SETTLE_US  1         /* power-up settle time */
#define HX711_READ_RETRIES 3
#define HX711_READ_AVG 5
#define POLL_INTERVAL_US 500000    /* 500 ms */
#define SOLENOID_PULSE_US 200000   /* 200 ms */
#define TARE_SAMPLES 10

static volatile sig_atomic_t g_running = 1;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_dout = NULL;
static struct gpiod_line *g_sck = NULL;
static struct gpiod_line *g_solenoid = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int hx711_read_raw(int32_t *out)
{
    struct timespec ts_start, ts_now;
    long elapsed_us;

    /* Wait for DOUT to go LOW (data ready). */
    clock_gettime(CLOCK_MONOTONIC, &ts_start);
    for (;;) {
        int val = gpiod_line_get_value(g_dout);
        if (val < 0) {
            syslog(LOG_ERR, "gpiod_line_get_value(DOUT) failed: %s", strerror(errno));
            return -1;
        }
        if (val == 0)
            break;
        clock_gettime(CLOCK_MONOTONIC, &ts_now);
        elapsed_us = (ts_now.tv_sec - ts_start.tv_sec) * 1000000L
                   + (ts_now.tv_nsec - ts_start.tv_nsec) / 1000L;
        if (elapsed_us > HX711_TIMEOUT_US) {
            syslog(LOG_ERR, "HX711 timeout: DOUT stuck HIGH");
            return -1;
        }
    }

    uint32_t data = 0;
    for (int i = 0; i < 24; i++) {
        if (gpiod_line_set_value(g_sck, 1) < 0) {
            syslog(LOG_ERR, "gpiod_line_set_value(SCK high) failed: %s", strerror(errno));
            return -1;
        }
        data <<= 1;
        int bit = gpiod_line_get_value(g_dout);
        if (bit < 0) {
            syslog(LOG_ERR, "gpiod_line_get_value(DOUT) failed: %s", strerror(errno));
            return -1;
        }
        if (bit)
            data |= 1U;
        if (gpiod_line_set_value(g_sck, 0) < 0) {
            syslog(LOG_ERR, "gpiod_line_set_value(SCK low) failed: %s", strerror(errno));
            return -1;
        }
    }

    /* 25th pulse: Channel A, Gain 128 */
    if (gpiod_line_set_value(g_sck, 1) < 0) {
        syslog(LOG_ERR, "gpiod_line_set_value(SCK high) failed: %s", strerror(errno));
        return -1;
    }
    if (gpiod_line_set_value(g_sck, 0) < 0) {
        syslog(LOG_ERR, "gpiod_line_set_value(SCK low) failed: %s", strerror(errno));
        return -1;
    }

    /* Sign-extend 24-bit two's complement to 32-bit */
    if (data & 0x800000U)
        data |= 0xFF000000U;

    *out = (int32_t)data;
    return 0;
}

static int hx711_read_averaged(int32_t *out)
{
    long sum = 0;
    int ok = 0;

    for (int i = 0; i < HX711_READ_AVG; i++) {
        int32_t raw;
        if (hx711_read_raw(&raw) == 0) {
            sum += raw;
            ok++;
        } else {
            syslog(LOG_ERR, "HX711 read failed (attempt %d/%d)", i + 1, HX711_READ_AVG);
        }
    }

    if (ok == 0) {
        syslog(LOG_ERR, "HX711: all %d reads failed", HX711_READ_AVG);
        return -1;
    }

    *out = (int32_t)(sum / ok);
    return 0;
}

static int hx711_tare(int32_t *offset_out)
{
    long sum = 0;
    int ok = 0;

    syslog(LOG_INFO, "Taring HX711 (%d samples)...", TARE_SAMPLES);
    for (int i = 0; i < TARE_SAMPLES; i++) {
        int32_t raw;
        if (hx711_read_raw(&raw) == 0) {
            sum += raw;
            ok++;
        } else {
            syslog(LOG_ERR, "Tare read %d failed", i + 1);
        }
        usleep(10000); /* 10 ms between samples */
    }

    if (ok == 0) {
        syslog(LOG_ERR, "Tare: all %d reads failed", TARE_SAMPLES);
        return -1;
    }

    *offset_out = (int32_t)(sum / ok);
    syslog(LOG_INFO, "Tare complete. Offset = %d", *offset_out);
    return 0;
}

static int solenoid_pulse(void)
{
    if (gpiod_line_set_value(g_solenoid, 1) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid HIGH: %s", strerror(errno));
        return -1;
    }
    usleep(SOLENOID_PULSE_US);
    if (gpiod_line_set_value(g_solenoid, 0) < 0) {
        syslog(LOG_ERR, "Failed to set solenoid LOW: %s", strerror(errno));
        return -1;
    }
    return 0;
}

static void cleanup(void)
{
    if (g_solenoid) {
        gpiod_line_set_value(g_solenoid, 0);
        gpiod_line_release(g_solenoid);
        g_solenoid = NULL;
    }
    if (g_sck) {
        gpiod_line_set_value(g_sck, 0);
        gpiod_line_release(g_sck);
        g_sck = NULL;
    }
    if (g_dout) {
        gpiod_line_release(g_dout);
        g_dout = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
    closelog();
}

int main(int argc, char *argv[])
{
    int threshold = 1000;   /* grams */
    float scale_factor = 1.0f;
    int solenoid_duration = 200; /* ms */

    int opt;
    while ((opt = getopt(argc, argv, "t:s:d:")) != -1) {
        switch (opt) {
        case 't':
            threshold = atoi(optarg);
            if (threshold <= 0) {
                fprintf(stderr, "Threshold must be positive\n");
                return EXIT_FAILURE;
            }
            break;
        case 's':
            scale_factor = strtof(optarg, NULL);
            if (scale_factor <= 0.0f) {
                fprintf(stderr, "Scale factor must be positive\n");
                return EXIT_FAILURE;
            }
            break;
        case 'd':
            solenoid_duration = atoi(optarg);
            if (solenoid_duration <= 0) {
                fprintf(stderr, "Duration must be positive\n");
                return EXIT_FAILURE;
            }
            break;
        default:
            fprintf(stderr, "Usage: %s [-t threshold_grams] [-s scale_factor] [-d solenoid_ms]\n", argv[0]);
            return EXIT_FAILURE;
        }
    }

    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);
    syslog(LOG_INFO, "Starting weight monitor (threshold=%d g, scale=%.2f, solenoid=%d ms)",
           threshold, scale_factor, solenoid_duration);

    /* Open default GPIO chip (gpiochip0 on Pi 3 B+) */
    g_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!g_chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    g_dout = gpiod_chip_get_line(g_chip, HX711_DOUT_PIN);
    g_sck  = gpiod_chip_get_line(g_chip, HX711_SCK_PIN);
    g_solenoid = gpiod_chip_get_line(g_chip, SOLENOID_PIN);
    if (!g_dout || !g_sck || !g_solenoid) {
        syslog(LOG_ERR, "gpiod_chip_get_line failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    if (gpiod_line_request_input(g_dout, "hx711_dout") < 0) {
        syslog(LOG_ERR, "request_input(DOUT) failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(g_sck, "hx711_sck", 0) < 0) {
        syslog(LOG_ERR, "request_output(SCK) failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }
    if (gpiod_line_request_output(g_solenoid, "solenoid", 0) < 0) {
        syslog(LOG_ERR, "request_output(SOLENOID) failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    /* HX711 power-up / settle */
    usleep(HX711_SETTLE_US);

    int32_t offset = 0;
    if (hx711_tare(&offset) != 0) {
        syslog(LOG_ERR, "Tare failed; aborting");
        cleanup();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Entering main loop (poll every %d ms)", POLL_INTERVAL_US / 1000);

    while (g_running) {
        int32_t raw;
        if (hx711_read_averaged(&raw) != 0) {
            syslog(LOG_ERR, "Weight read failed; retrying next cycle");
            usleep(POLL_INTERVAL_US);
            continue;
        }

        int32_t weight_raw = raw - offset;
        float weight_g = (float)weight_raw / scale_factor;

        syslog(LOG_INFO, "Weight: %.2f g (raw=%d, offset=%d)", weight_g, weight_raw, offset);

        if (weight_g > threshold) {
            syslog(LOG_INFO, "Threshold exceeded (%.2f > %d g); activating solenoid",
                   weight_g, threshold);
            if (solenoid_pulse() != 0) {
                syslog(LOG_ERR, "Solenoid pulse failed");
            }
        }

        usleep(POLL_INTERVAL_US);
    }

    syslog(LOG_INFO, "Shutting down gracefully");
    cleanup();
    return EXIT_SUCCESS;
}

