/*
 * relay_controller.c — MQTT-controlled relay on Raspberry Pi 4 Model B
 *
 * Build:  gcc -O2 -Wall -Wextra -o relay_controller relay_controller.c -lmosquitto -lgpiod
 * Run:    sudo ./relay_controller
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <syslog.h>
#include <errno.h>
#include <stdbool.h>
#include <mosquitto.h>
#include <gpiod.h>

#define MQTT_BROKER_ADDRESS "localhost"
#define MQTT_BROKER_PORT    1883
#define MQTT_CLIENT_ID      "relay_controller_1"
#define MQTT_TOPIC          "home/lights/control"
#define MQTT_KEEPALIVE_SEC  60

#define GPIO_CHIP_NAME      "gpiochip4"   /* BCM GPIO bank on Pi 4/5 */
#define GPIO_LINE_OFFSET    17            /* BCM 17 = physical pin 11 */

static volatile sig_atomic_t g_running = 1;
static struct mosquitto *g_mosq = NULL;
static struct gpiod_chip *g_chip = NULL;
static struct gpiod_line *g_line = NULL;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int gpio_init(void)
{
    g_chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!g_chip) {
        syslog(LOG_ERR, "gpiod_chip_open_by_name(%s) failed: %s",
               GPIO_CHIP_NAME, strerror(errno));
        return -1;
    }

    g_line = gpiod_chip_get_line(g_chip, GPIO_LINE_OFFSET);
    if (!g_line) {
        syslog(LOG_ERR, "gpiod_chip_get_line(%d) failed: %s",
               GPIO_LINE_OFFSET, strerror(errno));
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    if (gpiod_line_request_output(g_line, "mqtt_relay", 0) < 0) {
        syslog(LOG_ERR, "gpiod_line_request_output failed: %s",
               strerror(errno));
        g_line = NULL;
        gpiod_chip_close(g_chip);
        g_chip = NULL;
        return -1;
    }

    syslog(LOG_INFO, "GPIO %d initialized as output, relay OFF",
           GPIO_LINE_OFFSET);
    return 0;
}

static void gpio_set(int value)
{
    if (gpiod_line_set_value(g_line, value) < 0) {
        syslog(LOG_ERR, "gpiod_line_set_value(%d) failed: %s",
               value, strerror(errno));
    } else {
        syslog(LOG_INFO, "Relay %s", value ? "ON" : "OFF");
    }
}

static void gpio_cleanup(void)
{
    if (g_line) {
        gpiod_line_set_value(g_line, 0);   /* ensure relay is OFF */
        gpiod_line_release(g_line);
        g_line = NULL;
    }
    if (g_chip) {
        gpiod_chip_close(g_chip);
        g_chip = NULL;
    }
}

/* ------------------------------------------------------------------ */
/* MQTT callbacks                                                      */
/* ------------------------------------------------------------------ */
static void on_connect(struct mosquitto *mosq, void *userdata, int result)
{
    (void)userdata;
    if (result == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Connected to MQTT broker %s:%d",
               MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT);
        if (mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0) != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "Failed to subscribe to %s", MQTT_TOPIC);
        }
    } else {
        syslog(LOG_ERR, "MQTT connect error: %s",
               mosquitto_strerror(result));
    }
}

static void on_disconnect(struct mosquitto *mosq, void *userdata, int rc)
{
    (void)mosq;
    (void)userdata;
    if (rc == MOSQ_ERR_SUCCESS) {
        syslog(LOG_INFO, "Disconnected from MQTT broker");
    } else {
        syslog(LOG_ERR, "Unexpected MQTT disconnect: %s",
               mosquitto_strerror(rc));
    }
}

static void on_subscribe(struct mosquitto *mosq, void *userdata,
                         int mid, int qos_count, const int *granted_qos)
{
    (void)mosq;
    (void)userdata;
    (void)mid;
    (void)qos_count;
    (void)granted_qos;
    syslog(LOG_INFO, "Subscribed to %s", MQTT_TOPIC);
}

static void on_message(struct mosquitto *mosq, void *userdata,
                       const struct mosquitto_message *message)
{
    (void)mosq;
    (void)userdata;

    if (!message || !message->payload || message->payloadlen <= 0) {
        syslog(LOG_ERR, "Empty MQTT message on %s", message->topic);
        return;
    }

    /* NUL-terminate the payload for safe string comparison */
    char payload[32];
    int len = message->payloadlen;
    if (len >= (int)sizeof(payload)) {
        len = (int)sizeof(payload) - 1;
    }
    memcpy(payload, message->payload, (size_t)len);
    payload[len] = '\0';

    syslog(LOG_INFO, "Received on %s: %s", message->topic, payload);

    if (strcmp(payload, "ON") == 0) {
        gpio_set(1);
    } else if (strcmp(payload, "OFF") == 0) {
        gpio_set(0);
    } else {
        syslog(LOG_ERR, "Invalid payload '%s' on %s", payload, message->topic);
    }
}

/* ------------------------------------------------------------------ */
/* MQTT helpers                                                        */
/* ------------------------------------------------------------------ */
static int mqtt_init(void)
{
    mosquitto_lib_init();

    g_mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!g_mosq) {
        syslog(LOG_ERR, "mosquitto_new failed: %s", strerror(errno));
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_connect_callback_set(g_mosq, on_connect);
    mosquitto_disconnect_callback_set(g_mosq, on_disconnect);
    mosquitto_subscribe_callback_set(g_mosq, on_subscribe);
    mosquitto_message_callback_set(g_mosq, on_message);

    int rc = mosquitto_connect(g_mosq, MQTT_BROKER_ADDRESS,
                               MQTT_BROKER_PORT, MQTT_KEEPALIVE_SEC);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "mosquitto_connect failed: %s",
               mosquitto_strerror(rc));
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
        mosquitto_lib_cleanup();
        return -1;
    }

    syslog(LOG_INFO, "MQTT client initialized (client ID: %s)",
           MQTT_CLIENT_ID);
    return 0;
}

static void mqtt_cleanup(void)
{
    if (g_mosq) {
        mosquitto_disconnect(g_mosq);
        mosquitto_destroy(g_mosq);
        g_mosq = NULL;
    }
    mosquitto_lib_cleanup();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    openlog("mqtt_relay", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 ||
        sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "sigaction failed: %s", strerror(errno));
        closelog();
        return EXIT_FAILURE;
    }

    if (gpio_init() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    if (mqtt_init() != 0) {
        gpio_cleanup();
        closelog();
        return EXIT_FAILURE;
    }

    syslog(LOG_INFO, "Starting MQTT loop");
    while (g_running) {
        int rc = mosquitto_loop(g_mosq, 1000, 1);
        if (rc != MOSQ_ERR_SUCCESS) {
            syslog(LOG_ERR, "mosquitto_loop error: %s",
                   mosquitto_strerror(rc));
            sleep(5);
            if (g_running) {
                syslog(LOG_INFO, "Attempting reconnection...");
                if (mosquitto_reconnect(g_mosq) != MOSQ_ERR_SUCCESS) {
                    syslog(LOG_ERR, "Reconnect failed, retrying in 5 s");
                }
            }
        }
    }

    syslog(LOG_INFO, "Shutting down");
    mqtt_cleanup();
    gpio_cleanup();
    closelog();
    return EXIT_SUCCESS;
}

