#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

#define SERVO1_PULSE 1000
#define SERVO2_PULSE 1500
#define SERVO3_PULSE 2000
#define SERVO4_PULSE 500
#define SERVO5_PULSE 2500

#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500
#define HOLD_SECONDS 3

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int set_servo_pulse(int pin, int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: pulse width %d out of range [%d, %d] for pin %d\n",
                pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH, pin);
        return -1;
    }
    if (gpioServo(pin, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d\n", pin);
        return -1;
    }
    return 0;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    int pins[] = {SERVO1_PIN, SERVO2_PIN, SERVO3_PIN, SERVO4_PIN, SERVO5_PIN};
    int pulses[] = {SERVO1_PULSE, SERVO2_PULSE, SERVO3_PULSE, SERVO4_PULSE, SERVO5_PULSE};
    const int num_servos = sizeof(pins) / sizeof(pins[0]);

    for (int i = 0; i < num_servos && running; i++) {
        if (set_servo_pulse(pins[i], pulses[i]) != 0) {
            fprintf(stderr, "Error: failed to set pulse for servo on pin %d\n", pins[i]);
            gpioTerminate();
            return EXIT_FAILURE;
        }
        printf("Servo on pin %d set to %d us\n", pins[i], pulses[i]);
    }

    if (!running) {
        goto cleanup;
    }

    for (int i = 0; i < HOLD_SECONDS && running; i++) {
        sleep(1);
    }

cleanup:
    for (int i = 0; i < num_servos; i++) {
        gpioServo(pins[i], 0);
    }
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

