    }

    for (int i = 0; i < HOLD_SECONDS && running; i++) {
        sleep(1);
    }

cleanup:
    for (int i = 0; i < num_servos; i++) {
        gpioServo(pins[i], 0);
    }
    gpioTerminate();
    printf("Program terminated cleanly.\n");
    return EXIT_SUCCESS;
}

