/*
 * Closed-loop DC motor speed control for a Raspberry Pi 3 Model B+
 * using two DRV8833 H-bridge drivers and quadrature encoders.
 *
 * Wiring (BCM numbering):
 *   Motor A: IN1 -> GPIO17 (PWM), IN2 -> GPIO18 (direction)
 *   Motor B: IN3 -> GPIO22 (PWM), IN4 -> GPIO23 (direction)
 *   Encoder A: CHA -> GPIO4, CHB -> GPIO5
 *   Encoder B: CHA -> GPIO6, CHB -> GPIO12
 *
 * Build: gcc -O2 -Wall -o motor_control motor_control.c -lpigpio -lrt
 * Run:   sudo ./motor_control
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ---- Pin assignments (BCM) ---- */
#define MOTOR_A_PWM_PIN    17
#define MOTOR_A_DIR_PIN    18
#define MOTOR_B_PWM_PIN    22
#define MOTOR_B_DIR_PIN    23

#define ENCODER_A_CHA_PIN  4
#define ENCODER_A_CHB_PIN  5
#define ENCODER_B_CHA_PIN  6
#define ENCODER_B_CHB_PIN  12

/* ---- Control parameters ---- */
#define TARGET_RPM        50.0f
#define KP                2.0f
#define KI                0.001f
#define PWM_FREQUENCY     10000   /* 10 kHz */
#define PWM_RANGE         255
#define TICKS_PER_REV     64      /* Encoder ticks per motor revolution */
#define LOOP_DELAY_US     100000  /* 100 ms */
#define STALL_TIMEOUT_S   2.0

/* ---- Derived constants ---- */
#define RPM_PER_TICK      (60.0f / (float)TICKS_PER_REV)
#define TICK_PER_RPM      (1.0f / RPM_PER_TICK)
#define INTEGRAL_LIMIT    100.0f

/* ---- Global state ---- */
static volatile int32_t encoder_a_ticks = 0;
static volatile int32_t encoder_b_ticks = 0;
static volatile uint32_t last_tick_time = 0;
static volatile bool stall_flag = false;

static volatile sig_atomic_t running = 1;

/* ---- Function prototypes ---- */
static void signal_handler(int sig);
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata);
static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata);
static void set_motor_a(int pwm, bool forward);
static void set_motor_b(int pwm, bool forward);
static void stop_motors(void);
static void clamp(float *value, float min, float max);

/* ---- Signal handler ---- */
static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- Encoder ISRs (rising edge) ---- */
static void encoder_a_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        int b = gpioRead(ENCODER_A_CHB_PIN);
        if (b == 1) {
            encoder_a_ticks++;
        } else {
            encoder_a_ticks--;
        }
        last_tick_time = tick;
    }
}

static void encoder_b_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;
    if (level == 1) {
        int b = gpioRead(ENCODER_B_CHB_PIN);
        if (b == 1) {
            encoder_b_ticks++;
        } else {
            encoder_b_ticks--;
        }
        last_tick_time = tick;
    }
}

/* ---- Motor control helpers ---- */
static void set_motor_a(int pwm, bool forward)
{
    if (pwm < 0) pwm = 0;
    if (pwm > PWM_RANGE) pwm = PWM_RANGE;
    gpioPWM(MOTOR_A_PWM_PIN, pwm);
    gpioWrite(MOTOR_A_DIR_PIN, forward ? 1 : 0);
}

static void set_motor_b(int pwm, bool forward)
{
    if (pwm < 0) pwm = 0;
    if (pwm > PWM_RANGE) pwm = PWM_RANGE;
    gpioPWM(MOTOR_B_PWM_PIN, pwm);
    gpioWrite(MOTOR_B_DIR_PIN, forward ? 1 : 0);
}

static void stop_motors(void)
{
    set_motor_a(0, false);
    set_motor_b(0, false);
}

static void clamp(float *value, float min, float max)
{
    if (*value < min) *value = min;
    if (*value > max) *value = max;
}

/* ---- Main ---- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure motor control pins */
    if (gpioSetMode(MOTOR_A_PWM_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_A_DIR_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_PWM_PIN, PI_OUTPUT) != 0 ||
        gpioSetMode(MOTOR_B_DIR_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set motor pin modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Configure encoder pins */
    if (gpioSetMode(ENCODER_A_CHA_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_A_CHB_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_CHA_PIN, PI_INPUT) != 0 ||
        gpioSetMode(ENCODER_B_CHB_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set encoder pin modes.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Set PWM frequency and range */
    if (gpioSetPWMfrequency(MOTOR_A_PWM_PIN, PWM_FREQUENCY) < 0 ||
        gpioSetPWMfrequency(MOTOR_B_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetPWMrange(MOTOR_A_PWM_PIN, PWM_RANGE) < 0 ||
        gpioSetPWMrange(MOTOR_B_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Register ISRs */
    if (gpioSetISRFuncEx(ENCODER_A_CHA_PIN, RISING_EDGE, 0, encoder_a_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register encoder A ISR.\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetISRFuncEx(ENCODER_B_CHA_PIN, RISING_EDGE, 0, encoder_b_isr, NULL) != 0) {
        fprintf(stderr, "Error: failed to register encoder B ISR.\n");
        gpioSetISRFuncEx(ENCODER_A_CHA_PIN, RISING_EDGE, 0, NULL, NULL);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize motor outputs to safe state */
    stop_motors();

    /* Install signal handler */
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }

    /* Control loop state */
    float integral_a = 0.0f;
    float integral_b = 0.0f;
    uint32_t last_tick = gpioTick();
    last_tick_time = last_tick;

    printf("Motor control started. Target RPM: %.1f\n", TARGET_RPM);
    printf("Press Ctrl+C to stop.\n");

    while (running) {
        uint32_t now = gpioTick();
        float dt = (float)(now - last_tick) / 1000000.0f;
        last_tick = now;

        /* Read encoder ticks atomically */
        int32_t ticks_a = encoder_a_ticks;
        int32_t ticks_b = encoder_b_ticks;

        /* Stall detection */
        if (dt > 0.0f) {
            uint32_t since_last = now - last_tick_time;
            if (since_last > (uint32_t)(STALL_TIMEOUT_S * 1000000.0f)) {
                if (!stall_flag) {
                    fprintf(stderr, "Warning: encoder stall detected (no ticks for %.1f s).\n",
                            STALL_TIMEOUT_S);
                    stall_flag = true;
                }
            } else {
                stall_flag = false;
            }
        }

        /* Reset encoder counters */
        encoder_a_ticks = 0;
        encoder_b_ticks = 0;

        /* Compute RPM from ticks */
        float rpm_a = (float)ticks_a / TICKS_PER_REV / dt * 60.0f;
        float rpm_b = (float)ticks_b / TICKS_PER_REV / dt * 60.0f;

        /* PI control */
        float error_a = TARGET_RPM - rpm_a;
        float error_b = TARGET_RPM - rpm_b;

        integral_a += error_a * dt;
        integral_b += error_b * dt;
        clamp(&integral_a, -INTEGRAL_LIMIT, INTEGRAL_LIMIT);
        clamp(&integral_b, -INTEGRAL_LIMIT, INTEGRAL_LIMIT);

        float pwm_a = (KP * error_a + KI * integral_a);
        float pwm_b = (KP * error_b + KI * integral_b);

        clamp(&pwm_a, 0.0f, (float)PWM_RANGE);
        clamp(&pwm_b, 0.0f, (float)PWM_RANGE);

        /* Drive motors (forward direction) */
        set_motor_a((int)pwm_a, true);
        set_motor_b((int)pwm_b, true);

        /* Print status */
        printf("RPM: A=%.1f B=%.1f  PWM: A=%d B=%d  integral: A=%.2f B=%.2f\n",
               rpm_a, rpm_b, (int)pwm_a, (int)pwm_b, integral_a, integral_b);

        gpioDelay(LOOP_DELAY_US);
    }

    /* Clean shutdown */
    printf("\nShutting down...\n");
    stop_motors();
    gpioSetISRFuncEx(ENCODER_A_CHA_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioSetISRFuncEx(ENCODER_B_CHA_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioTerminate();
    printf("Done.\n");
    return EXIT_SUCCESS;
}

