#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define BH1750_ADDR             0x23
#define BH1750_CONT_HIGH_RES    0x10
#define BH1750_MEASUREMENT_MS   180
#define GPIO_RELAY              17
#define LUX_THRESHOLD_LOW       50
#define LUX_THRESHOLD_HIGH      200
#define POLL_INTERVAL_S         5
#define LOG_FILE                "chicken_coop_log.txt"

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;
static FILE *g_log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int init_bh1750(int handle) {
    if (i2cWriteByte(handle, BH1750_CONT_HIGH_RES) < 0) {
        return -1;
    }
    return 0;
}

static int read_bh1750(int handle, uint16_t *lux_out) {
    char buf[2];
    int bytes = i2cReadDevice(handle, buf, 2);
    if (bytes != 2) {
        return -1;
    }
    *lux_out = ((uint16_t)(uint8_t)buf[0] << 8) | (uint8_t)buf[1];
    return 0;
}

static void control_relay(int state) {
    if (gpioWrite(GPIO_RELAY, state) < 0) {
        fprintf(stderr, "Error: failed to write GPIO %d\n", GPIO_RELAY);
    }
}

static void log_data(uint16_t lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    fprintf(g_log_file, "%s: Lux = %u, Relay = %s\n",
            timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(g_log_file);
}

static void cleanup(void) {
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
