#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_US 50000
#define LOOP_DELAY_US 10000

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", &timeinfo);

    printf("[%s] Relay is now %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

int main(void) {
    int relay_state = 0;
    int last_touch_state = 0;
    int init_result;

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("Failed to register SIGINT handler");
        return EXIT_FAILURE;
    }

    init_result = gpioInitialise();
    if (init_result < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", init_result);
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set touch sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialize relay to OFF state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Touch-toggle relay started. Touch GPIO%d to toggle GPIO%d. Ctrl+C to exit.\n",
           TOUCH_SENSOR_PIN, RELAY_PIN);
    fflush(stdout);

    while (running) {
        int touch_state = gpioRead(TOUCH_SENSOR_PIN);
        if (touch_state < 0) {
            fprintf(stderr, "Error reading touch sensor on GPIO%d\n", TOUCH_SENSOR_PIN);
            break;
        }

        if (touch_state == 1 && last_touch_state == 0) {
            gpioDelay(DEBOUNCE_DELAY_US);

            int post_debounce_state = gpioRead(TOUCH_SENSOR_PIN);
            if (post_debounce_state < 0) {
                fprintf(stderr, "Error reading touch sensor during debounce on GPIO%d\n", TOUCH_SENSOR_PIN);
                break;
            }

            if (post_debounce_state == 1) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Failed to write relay state to GPIO%d\n", RELAY_PIN);
                    break;
                }
                log_relay_state(relay_state);
            }
        }

        last_touch_state = touch_state;
        gpioDelay(LOOP_DELAY_US);
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Warning: failed to turn relay OFF on exit\n");
    }
    gpioTerminate();
    printf("\nExiting gracefully.\n");
    return EXIT_SUCCESS;
}

