#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <pigpio.h>

#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN    27

#define FLOW_THRESHOLD_HIGH  5.0f
#define FLOW_THRESHOLD_LOW   4.5f

#define DEBOUNCE_TIMEOUT_US  1000000
#define SAMPLE_INTERVAL_US   1000000

static volatile sig_atomic_t g_running = 1;
static volatile uint32_t     g_pulse_count = 0;
static pthread_mutex_t       g_pulse_mutex = PTHREAD_MUTEX_INITIALIZER;
static FILE                 *g_log_file    = NULL;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void log_event(const char *msg)
{
    if (!g_log_file)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);

    fprintf(g_log_file, "%s: %s\n", ts, msg);
    fflush(g_log_file);
}

static void flow_isr(int gpio, int level, uint32_t tick, void *userdata)
{
    (void)gpio;
    (void)userdata;

    static uint32_t last_tick = 0;
    uint32_t diff = tick - last_tick;

    if (level == 1 && diff > DEBOUNCE_TIMEOUT_US) {
        pthread_mutex_lock(&g_pulse_mutex);
        g_pulse_count++;
        pthread_mutex_unlock(&g_pulse_mutex);
        last_tick = tick;
    }
}

static float calculate_flow_rate(uint32_t pulses)
{
    static uint32_t last_pulses = 0;
    uint32_t delta = pulses - last_pulses;
    last_pulses = pulses;

    float lpm = (float)delta * 60.0f / 1000.0f;
    return lpm;
}

static int control_solenoid(float flow_rate)
{
    static int solenoid_state = 1;

    if (flow_rate > FLOW_THRESHOLD_HIGH && solenoid_state == 1) {
        if (gpioWrite(SOLENOID_PIN, 0) == 0) {
            solenoid_state = 0;
            log_event("Solenoid closed (flow exceeded threshold)");
            return 0;
        }
        log_event("ERROR: Failed to close solenoid");
        return -1;
    }

    if (flow_rate < FLOW_THRESHOLD_LOW && solenoid_state == 0) {
        if (gpioWrite(SOLENOID_PIN, 1) == 0) {
            solenoid_state = 1;
            log_event("Solenoid opened (flow below threshold)");
            return 0;
        }
        log_event("ERROR: Failed to open solenoid");
        return -1;
    }

    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set flow sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(SOLENOID_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set solenoid pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(SOLENOID_PIN, 1) != 0) {
        fprintf(stderr, "Failed to initialize solenoid to open state\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, flow_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for flow sensor\n");
        gpioWrite(SOLENOID_PIN, 1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    g_log_file = fopen("water_flow.log", "a");
    if (!g_log_file) {
        perror("Error opening log file");
        gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, NULL, NULL);
        gpioWrite(SOLENOID_PIN, 1);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Program started");

    while (g_running) {
        gpioDelay(SAMPLE_INTERVAL_US);

        uint32_t pulses;
        pthread_mutex_lock(&g_pulse_mutex);
        pulses = g_pulse_count;
        g_pulse_count = 0;
        pthread_mutex_unlock(&g_pulse_mutex);

        float flow_rate = calculate_flow_rate(pulses);

        char msg[128];
        snprintf(msg, sizeof(msg), "Flow rate: %.2f LPM", flow_rate);
        log_event(msg);

        if (control_solenoid(flow_rate) != 0) {
            log_event("ERROR: Solenoid control failed");
        }
    }

    log_event("Shutting down");

    gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioWrite(SOLENOID_PIN, 1);
    gpioTerminate();

    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    pthread_mutex_destroy(&g_pulse_mutex);

    return EXIT_SUCCESS;
}

