    gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, NULL, NULL);
    gpioWrite(SOLENOID_PIN, 1);
    gpioTerminate();

    if (g_log_file) {
        fclose(g_log_file);
        g_log_file = NULL;
    }

    pthread_mutex_destroy(&g_pulse_mutex);

    return EXIT_SUCCESS;
}

