#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <jansson.h>

#define HX711_DATA_PIN 23
#define HX711_SCK_PIN 24
#define SERVO_PIN 18
#define PORT 12345
#define BUFFER_SIZE 1024
#define LOG_FILE "dispensing_log.json"
#define CONFIG_FILE "config.ini"
#define DEFAULT_CALIBRATION_FACTOR 100.0
#define DEFAULT_KNOWN_WEIGHT 100.0
#define DEFAULT_TARGET_WEIGHT 150.0
#define DEFAULT_MIN_PULSE_WIDTH 1000
#define DEFAULT_MAX_PULSE_WIDTH 2000
#define HX711_TIMEOUT 1000
#define DISPENSE_DELAY_US 1000000

static volatile sig_atomic_t running = 1;
static int server_fd = -1;
static int client_fd = -1;
static double calibration_factor = DEFAULT_CALIBRATION_FACTOR;
static double known_weight = DEFAULT_KNOWN_WEIGHT;
static double target_weight = DEFAULT_TARGET_WEIGHT;
static int min_pulse_width = DEFAULT_MIN_PULSE_WIDTH;
static int max_pulse_width = DEFAULT_MAX_PULSE_WIDTH;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_config(void) {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (!fp) {
        fprintf(stderr, "Warning: Could not open config file '%s': %s. Using defaults.\n",
                CONFIG_FILE, strerror(errno));
        return -1;
    }
    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        char *name = strtok(line, "=\n");
        char *value = strtok(NULL, "=\n");
        if (!name || !value) continue;
        if (strcmp(name, "calibration_factor") == 0) calibration_factor = atof(value);
        else if (strcmp(name, "known_weight") == 0) known_weight = atof(value);
        else if (strcmp(name, "target_weight") == 0) target_weight = atof(value);
        else if (strcmp(name, "min_pulse_width") == 0) min_pulse_width = atoi(value);
        else if (strcmp(name, "max_pulse_width") == 0) max_pulse_width = atoi(value);
    }
    fclose(fp);
    return 0;
}

static int log_event(const char *target, const char *actual, const char *error) {
    json_t *root = json_object();
    if (!root) return -1;
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    json_object_set_new(root, "timestamp", json_string(ts));
    json_object_set_new(root, "target_weight", json_real(target ? atof(target) : 0.0));
    json_object_set_new(root, "actual_weight", json_real(actual ? atof(actual) : 0.0));
    if (error) json_object_set_new(root, "error", json_string(error));
    char *str = json_dumps(root, JSON_INDENT(4));
    if (!str) { json_decref(root); return -1; }
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) { free(str); json_decref(root); return -1; }
    fprintf(fp, "%s\n", str);
    fclose(fp);
    free(str);
    json_decref(root);
    return 0;
}

static int hx711_read_raw(void) {
    int data = 0;
    int i;
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1);
        data <<= 1;
        if (gpioRead(HX711_DATA_PIN)) data |= 1;
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1);
    }
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1);
    if (data & 0x800000) data |= 0xFF000000;
    return data;
}

static double read_weight(void) {
    int raw = hx711_read_raw();
    if (raw == 0x7FFFFFFF) {
        fprintf(stderr, "Error: HX711 timeout (sensor not ready or disconnected).\n");
        return -1.0;
    }
    return (double)raw / calibration_factor;
}

static int set_servo_pulse(int pulse_width) {
    if (pulse_width < 500 || pulse_width > 2500) {
        fprintf(stderr, "Error: Invalid pulse width %d (must be 500-2500).\n", pulse_width);
        return -1;
    }
    if (gpioServo(SERVO_PIN, pulse_width) < 0) {
        fprintf(stderr, "Error: gpioServo failed for pin %d.\n", SERVO_PIN);
        return -1;
    }
    return 0;
}

static int dispense_ingredient(double target) {
    double pulse_width = min_pulse_width + (target / target_weight) * (max_pulse_width - min_pulse_width);
    if (pulse_width < min_pulse_width) pulse_width = min_pulse_width;
    if (pulse_width > max_pulse_width) pulse_width = max_pulse_width;
    if (set_servo_pulse((int)pulse_width) != 0) return -1;
    gpioDelay(DISPENSE_DELAY_US);
    return 0;
}

static int handle_client(int sock) {
    char buffer[BUFFER_SIZE];
    ssize_t n = recv(sock, buffer, BUFFER_SIZE - 1, 0);
    if (n <= 0) {
        if (n < 0) perror("recv");
        return -1;
    }
    buffer[n] = '\0';
    char *endptr;
    double target = strtod(buffer, &endptr);
    if (endptr == buffer) {
        fprintf(stderr, "Error: Invalid target weight received: '%s'\n", buffer);
        const char *err = "Invalid target weight";
        send(sock, err, strlen(err), 0);
        log_event(buffer, NULL, err);
        return -1;
    }
    if (dispense_ingredient(target) != 0) {
        const char *err = "Dispense failed";
        send(sock, err, strlen(err), 0);
        log_event(buffer, NULL, err);
        return -1;
    }
    double actual = read_weight();
    if (actual < 0) {
        const char *err = "Weight read failed";
        send(sock, err, strlen(err), 0);
        log_event(buffer, NULL, err);
        return -1;
    }
    char resp[BUFFER_SIZE];
    snprintf(resp, sizeof(resp), "%.2f", actual);
    send(sock, resp, strlen(resp), 0);
    log_event(buffer, resp, NULL);
    return 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }
    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    read_config();
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) { perror("socket"); gpioTerminate(); return 1; }
    int opt = 1;
    setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt));
    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = INADDR_ANY;
    addr.sin_port = htons(PORT);
    if (bind(server_fd, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind"); close(server_fd); gpioTerminate(); return 1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen"); close(server_fd); gpioTerminate(); return 1;
    }
    printf("Listening on 127.0.0.1:%d...\n", PORT);
    while (running) {
        struct sockaddr_in caddr;
        socklen_t clen = sizeof(caddr);
        client_fd = accept(server_fd, (struct sockaddr *)&caddr, &clen);
        if (client_fd < 0) {
            if (running && errno != EINTR) perror("accept");
            continue;
        }
        printf("Connection from %s:%d\n", inet_ntoa(caddr.sin_addr), ntohs(caddr.sin_port));
        handle_client(client_fd);
        close(client_fd);
        client_fd = -1;
    }
    if (client_fd >= 0) close(client_fd);
    if (server_fd >= 0) close(server_fd);
    gpioServo(SERVO_PIN, 0);
    gpioTerminate();
    printf("Shutdown complete.\n");
    return 0;
}

