#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define DEFAULT_DEBOUNCE_MS 50

static volatile sig_atomic_t running = 1;
static int debounce_ms = DEFAULT_DEBOUNCE_MS;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_relay_state(int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s Relay: %s\n", timestamp, state ? "ON" : "OFF");
    fflush(stdout);
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set touch sensor pin mode\n");
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set relay pin mode\n");
        gpioTerminate();
        return -1;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize relay to OFF\n");
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
}

static int read_touch_sensor(void) {
    return gpioRead(TOUCH_SENSOR_PIN);
}

static int control_relay(int state) {
    if (gpioWrite(RELAY_PIN, state) != 0) {
        fprintf(stderr, "Error: failed to write relay pin\n");
        return -1;
    }
    return 0;
}

int main(int argc, char *argv[]) {
    int opt;

    while ((opt = getopt(argc, argv, "d:")) != -1) {
        switch (opt) {
            case 'd':
                debounce_ms = atoi(optarg);
                if (debounce_ms <= 0) {
                    fprintf(stderr, "Error: debounce interval must be positive\n");
                    return 1;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-d debounce_ms]\n", argv[0]);
                return 1;
        }
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    int relay_state = 0;
    int last_touch_state = 0;
    int stable_state = 0;
    int debounce_count = 0;

    printf("Touch sensor relay controller started. Debounce: %d ms\n", debounce_ms);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        int touch_state = read_touch_sensor();
        if (touch_state < 0) {
            fprintf(stderr, "Error: failed to read touch sensor\n");
            break;
        }

        if (touch_state != stable_state) {
            debounce_count++;
            if (debounce_count >= (debounce_ms / 10)) {
                stable_state = touch_state;
                debounce_count = 0;
            }
        } else {
            debounce_count = 0;
        }

        if (stable_state == 1 && last_touch_state == 0) {
            relay_state = !relay_state;
            if (control_relay(relay_state) != 0) {
                break;
            }
            log_relay_state(relay_state);
        }

        last_touch_state = stable_state;
        gpioDelay(10000);
    }

    cleanup_gpio();
    printf("\nExiting cleanly.\n");
    return 0;
}

