        perror("sigaction(SIGINT)");
        return 1;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return 1;
    }

    if (initialize_gpio() != 0) {
        return 1;
    }

    int relay_state = 0;
    int last_touch_state = 0;
    int stable_state = 0;
    int debounce_count = 0;

    printf("Touch sensor relay controller started. Debounce: %d ms\n", debounce_ms);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        int touch_state = read_touch_sensor();
        if (touch_state < 0) {
            fprintf(stderr, "Error: failed to read touch sensor\n");
            break;
        }

        if (touch_state != stable_state) {
            debounce_count++;
            if (debounce_count >= (debounce_ms / 10)) {
                stable_state = touch_state;
                debounce_count = 0;
            }
        } else {
            debounce_count = 0;
        }

        if (stable_state == 1 && last_touch_state == 0) {
            relay_state = !relay_state;
            if (control_relay(relay_state) != 0) {
                break;
            }
            log_relay_state(relay_state);
        }

        last_touch_state = stable_state;
        gpioDelay(10000);
    }

    cleanup_gpio();
    printf("\nExiting cleanly.\n");
    return 0;
}

