    if (set_servo_angle(angle) != 0) {
        cleanup_gpio();
        restore_terminal();
        return 1;
    }
    printf("Servo angle: %d degrees\n", angle);
    printf("Press '+' to increase angle, '-' to decrease, 'q' to quit.\n");
    fflush(stdout);

    while (running) {
        int c = getchar();
        if (c == 'q') {
            break;
        } else if (c == '+') {
            angle += STEP_ANGLE;
