/*
 * Conveyor-belt RPM monitor using an A3144 Hall-effect sensor.
 *
 * Board:  Raspberry Pi 3 Model B+
 * Sensor: A3144 Hall-effect module (two-pole magnet on motor shaft)
 * Wiring: Sensor VCC -> 3V3 (pin 1), Sensor GND -> GND (pin 9),
 *         Sensor OUT -> GPIO17 (pin 11, BCM 17), internal pull-up enabled.
 *
 * Build:  gcc -O2 -Wall -Wextra -o motor_rpm motor_rpm.c -lgpiod -lrt
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <gpiod.h>

#define GPIO_CHIP_NAME      "gpiochip0"
#define GPIO_LINE_OFFSET    17          /* BCM 17, physical pin 11 */
#define DEBOUNCE_NS         2000000     /* 2 ms debounce window */
#define SAMPLE_INTERVAL_S   5           /* seconds between log entries */
#define LOG_FILE_NAME       "motor_rpm.log"

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Return a heap-allocated ISO-8601 timestamp string, or NULL on error. */
static char *get_timestamp(void)
{
    time_t rawtime;
    struct tm tm_info;
    char *buf = malloc(32);

    if (!buf) {
        fprintf(stderr, "get_timestamp: malloc failed: %s\n", strerror(errno));
        return NULL;
    }

    if (time(&rawtime) == (time_t)-1) {
        fprintf(stderr, "get_timestamp: time() failed: %s\n", strerror(errno));
        free(buf);
        return NULL;
    }

    if (localtime_r(&rawtime, &tm_info) == NULL) {
        fprintf(stderr, "get_timestamp: localtime_r() failed\n");
        free(buf);
        return NULL;
    }

    if (strftime(buf, 32, "%Y-%m-%dT%H:%M:%S", &tm_info) == 0) {
        fprintf(stderr, "get_timestamp: strftime() failed\n");
        free(buf);
        return NULL;
    }

    return buf;
}

/* ------------------------------------------------------------------ */
/* Append one CSV line: "timestamp,rpm\n" and flush immediately.        */
static int log_rpm(FILE *fp, const char *timestamp, double rpm)
{
    if (fprintf(fp, "%s,%.2f\n", timestamp, rpm) < 0) {
        fprintf(stderr, "log_rpm: fprintf failed: %s\n", strerror(errno));
        return -1;
    }
    if (fflush(fp) != 0) {
        fprintf(stderr, "log_rpm: fflush failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    FILE *log_fp = NULL;
    struct timespec last_event = {0, 0};
    struct timespec now;
    long long pulse_count = 0;
    int ret = EXIT_FAILURE;

    /* ---- Signal handling ------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        fprintf(stderr, "sigaction(SIGTERM) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Open GPIO chip -------------------------------------------- */
    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (!chip) {
        fprintf(stderr, "gpiod_chip_open_by_name(%s) failed: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    /* ---- Get GPIO line --------------------------------------------- */
    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (!line) {
        fprintf(stderr, "gpiod_chip_get_line(%d) failed: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup_chip;
    }

    /* ---- Request rising-edge events with internal pull-up ---------- */
    if (gpiod_line_request_rising_edge_events_flags(line,
            "motor_rpm_monitor",
            GPIOD_LINE_REQUEST_FLAG_BIAS_PULL_UP) < 0) {
        fprintf(stderr, "gpiod_line_request_rising_edge_events_flags failed: %s\n",
                strerror(errno));
        goto cleanup_chip;
    }

    /* ---- Open log file --------------------------------------------- */
    log_fp = fopen(LOG_FILE_NAME, "a");
    if (!log_fp) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE_NAME, strerror(errno));
        goto cleanup_line;
    }

    printf("Monitoring conveyor-belt RPM on GPIO%d (BCM). Press Ctrl+C to exit.\n",
           GPIO_LINE_OFFSET);

    /* ---- Main loop ------------------------------------------------- */
    while (g_running) {
        struct timespec timeout = {1, 0};   /* 1 s poll window */
        int ev = gpiod_line_event_wait(line, &timeout);

        if (ev < 0) {
            if (errno == EINTR) {
                continue;                 /* signal interrupted — re-check g_running */
            }
            fprintf(stderr, "gpiod_line_event_wait failed: %s\n", strerror(errno));
            goto cleanup_all;
        }

        if (ev == 0) {
            continue;                     /* timeout, no event — loop back */
        }

        /* Event detected — read it to confirm and clear the queue. */
        struct gpiod_line_event event;
        if (gpiod_line_event_read(line, &event) < 0) {
            fprintf(stderr, "gpiod_line_event_read failed: %s\n", strerror(errno));
            goto cleanup_all;
        }

        /* Debounce: ignore events within DEBOUNCE_NS of the last one. */
        clock_gettime(CLOCK_MONOTONIC, &now);
        long long elapsed_ns =
            (long long)(now.tv_sec - last_event.tv_sec) * 1000000000LL +
            (now.tv_nsec - last_event.tv_nsec);

        if (elapsed_ns < DEBOUNCE_NS) {
            continue;
        }
        last_event = now;

        pulse_count++;
    }

    /* ---- Graceful shutdown ---------------------------------------- */
    printf("\nShutting down...\n");
    ret = EXIT_SUCCESS;
    goto cleanup_all;

cleanup_all:
    if (log_fp) {
        fclose(log_fp);
    }
cleanup_line:
    if (line) {
        gpiod_line_release(line);
    }
cleanup_chip:
    if (chip) {
        gpiod_chip_close(chip);
    }
    return ret;
}

