#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17
#define POLL_DELAY_US 50000
#define FORCE_OFF_TIMEOUT_S 10

static volatile sig_atomic_t running = 1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set touch sensor pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set relay pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Failed to initialise relay to OFF\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        fprintf(stderr, "Failed to install signal handlers\n");
        gpioWrite(RELAY_PIN, 0);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    int relay_state = 0;
    int last_touch = 0;
    uint32_t touch_start_tick = 0;
    int force_off_active = 0;

    while (running) {
        int touch = gpioRead(TOUCH_SENSOR_PIN);
        if (touch < 0) {
            fprintf(stderr, "Error reading touch sensor\n");
            break;
        }

        if (touch && !last_touch) {
            if (!force_off_active) {
                relay_state = !relay_state;
                if (gpioWrite(RELAY_PIN, relay_state) != 0) {
                    fprintf(stderr, "Error writing to relay\n");
                    break;
                }
                touch_start_tick = gpioTick();
            }
        }

        if (touch) {
            if (!force_off_active) {
                uint32_t elapsed = gpioTick() - touch_start_tick;
                if (elapsed >= FORCE_OFF_TIMEOUT_S * 1000000) {
                    if (gpioWrite(RELAY_PIN, 0) != 0) {
                        fprintf(stderr, "Error forcing relay OFF\n");
                        break;
                    }
                    relay_state = 0;
                    force_off_active = 1;
                }
            }
        } else {
            force_off_active = 0;
        }

        last_touch = touch;
        usleep(POLL_DELAY_US);
    }

    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();
    return EXIT_SUCCESS;
}

