#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <errno.h>
#include <pigpio.h>

#define VALVE_PWM_PIN      18
#define VALVE_ENABLE_PIN   23
#define FLOW_SENSOR_PIN    24

#define PWM_FREQUENCY      1000
#define PWM_RANGE          255
#define SAMPLE_INTERVAL_US 100000
#define DEBOUNCE_US        1000

static volatile sig_atomic_t g_running = 1;
static volatile sig_atomic_t g_pulse_count = 0;
static FILE *g_log_file = NULL;
static double g_target_flow_rate = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void flow_isr(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio; (void)level; (void)tick; (void)userdata;
    g_pulse_count++;
}

static int init_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(VALVE_PWM_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", VALVE_PWM_PIN);
        return -1;
    }
    if (gpioSetMode(VALVE_ENABLE_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", VALVE_ENABLE_PIN);
        return -1;
    }
    if (gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as input.\n", FLOW_SENSOR_PIN);
        return -1;
    }

    if (gpioSetPullUpDown(FLOW_SENSOR_PIN, PI_PUD_DOWN) < 0) {
        fprintf(stderr, "Warning: failed to set pull-down on GPIO %d.\n", FLOW_SENSOR_PIN);
    }

    if (gpioSetPWMfrequency(VALVE_PWM_PIN, PWM_FREQUENCY) < 0) {
        fprintf(stderr, "Error: failed to set PWM frequency on GPIO %d.\n", VALVE_PWM_PIN);
        return -1;
    }
    if (gpioSetPWMrange(VALVE_PWM_PIN, PWM_RANGE) < 0) {
        fprintf(stderr, "Error: failed to set PWM range on GPIO %d.\n", VALVE_PWM_PIN);
        return -1;
    }

    if (gpioWrite(VALVE_ENABLE_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to drive GPIO %d high.\n", VALVE_ENABLE_PIN);
        return -1;
    }
    if (gpioPWM(VALVE_PWM_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialize PWM on GPIO %d.\n", VALVE_PWM_PIN);
        return -1;
    }

    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, DEBOUNCE_US, flow_isr, NULL) < 0) {
        fprintf(stderr, "Error: failed to register ISR on GPIO %d.\n", FLOW_SENSOR_PIN);
        return -1;
    }

    return 0;
}

static double calculate_flow_rate(int pulses, double interval_sec) {
    if (interval_sec <= 0.0) return 0.0;
    return (double)pulses / interval_sec;
}

static int set_valve_position(int position) {
    if (position < 0 || position > PWM_RANGE) {
        fprintf(stderr, "Error: invalid valve position %d (must be 0-%d).\n", position, PWM_RANGE);
        return -1;
    }
    if (gpioPWM(VALVE_PWM_PIN, position) < 0) {
        fprintf(stderr, "Error: failed to set PWM duty cycle to %d.\n", position);
        return -1;
    }
    return 0;
}

static int log_data(double flow_rate, int valve_position) {
    struct timespec ts;
    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        perror("clock_gettime");
        return -1;
    }
    long timestamp_ms = (long)(ts.tv_sec * 1000L + ts.tv_nsec / 1000000L);

    if (fprintf(g_log_file, "%ld,%.2f,%d\n", timestamp_ms, flow_rate, valve_position) < 0) {
        perror("fprintf");
        return -1;
    }
    if (fflush(g_log_file) != 0) {
        perror("fflush");
        return -1;
    }
    return 0;
}

static void cleanup(void) {
    if (g_log_file != NULL) {
        fclose(g_log_file);
        g_log_file = NULL;
    }
    gpioPWM(VALVE_PWM_PIN, 0);
    gpioWrite(VALVE_ENABLE_PIN, 0);
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                g_target_flow_rate = atof(optarg);
                if (g_target_flow_rate < 0.0) {
                    fprintf(stderr, "Error: target flow rate must be non-negative.\n");
                    return EXIT_FAILURE;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s -t <target_flow_rate_L_min>\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    if (g_target_flow_rate == 0.0) {
        fprintf(stderr, "Error: target flow rate (-t) is required.\n");
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        return EXIT_FAILURE;
    }

    if (init_gpio() != 0) {
        return EXIT_FAILURE;
    }

    g_log_file = fopen("flow_log.csv", "a");
    if (g_log_file == NULL) {
        perror("fopen(flow_log.csv)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (fprintf(g_log_file, "# target_flow_rate=%.2f\n", g_target_flow_rate) < 0) {
        perror("fprintf(header)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (fflush(g_log_file) != 0) {
        perror("fflush(header)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Flow control started. Target flow rate: %.2f L/min\n", g_target_flow_rate);
    printf("Press Ctrl+C to exit.\n");

    struct timespec start_ts, now_ts;
    clock_gettime(CLOCK_MONOTONIC, &start_ts);

    while (g_running) {
        int pulses = g_pulse_count;
        g_pulse_count = 0;

        clock_gettime(CLOCK_MONOTONIC, &now_ts);
        double elapsed = (double)(now_ts.tv_sec - start_ts.tv_sec) +
                         (double)(now_ts.tv_nsec - start_ts.tv_nsec) / 1e9;
        start_ts = now_ts;

        double flow_rate = calculate_flow_rate(pulses, elapsed);

        double error = g_target_flow_rate - flow_rate;
        int valve_position = (int)(error * 1.0);

        if (valve_position < 0) valve_position = 0;
        if (valve_position > PWM_RANGE) valve_position = PWM_RANGE;

        if (set_valve_position(valve_position) != 0) {
            fprintf(stderr, "Warning: failed to set valve position.\n");
        }

        if (log_data(flow_rate, valve_position) != 0) {
            fprintf(stderr, "Warning: failed to log data.\n");
        }

        printf("Flow: %.2f L/min, Valve: %d\n", flow_rate, valve_position);

        usleep(SAMPLE_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    cleanup();
    printf("Program terminated.\n");
    return EXIT_SUCCESS;
}

