/*
 * Two-factor door access control for Raspberry Pi 3 Model B+
 *
 * Hardware:
 *   - YLI YM-180 electromagnetic lock actuators on GPIO 17 (Lock 1) and GPIO 27 (Lock 2)
 *   - RFID reader on SPI channel 0 at 100 kHz
 *   - Button on GPIO 22 (active-low, internal pull-up, 50 ms debounce)
 *
 * Behavior:
 *   1. Polls the RFID reader in a non-blocking loop.
 *   2. Verifies a 10-byte valid tag (the documented value).
 *   3. Requires a button press before disengaging both locks for 5 s,
 *      then re-engaging them.
 *   4. Logs every access attempt to /var/log/door_access.log.
 *   5. Handles SPI read failures and all-zero response as "no tag".
 *   6. Installs SIGINT/SIGTERM handler for graceful shutdown.
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o door_access door_access.c -lpigpio -lrt
 * Run:
 *   sudo ./door_access
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define LOCK_1_GPIO          17
#define LOCK_2_GPIO          27
#define BUTTON_GPIO          22

#define SPI_CHANNEL          0
#define SPI_SPEED            100000          /* 100 kHz */
#define SPI_FLAGS            0               /* Mode 0, active-low CS */

#define LOG_FILE             "/var/log/door_access.log"

/* YM-180: HIGH = engaged (lock closed), LOW = disengaged (lock open) */
#define LOCK_ENGAGED         1
#define LOCK_DISENGAGED      0

/* Debounce: 50 ms in microseconds */
#define DEBOUNCE_US          50000

/* Lock hold time: 5 seconds in microseconds */
#define LOCK_HOLD_US         5000000

/* Valid 10-byte RFID tag (documented value) */
static const uint8_t VALID_TAG[10] = {
    0x01, 0x02, 0x03, 0x04, 0x05,
    0x06, 0x07, 0x08, 0x09, 0x0A
};

/* ------------------------------- Globals --------------------------------- */
static volatile sig_atomic_t g_running = 1;
static int      g_spi_handle = -1;
static FILE    *g_log_file   = NULL;

/* --------------------------- Function prototypes -------------------------- */
static void signal_handler(int sig);
static void log_event(const char *event);
static int  read_rfid_tag(uint8_t *tag, size_t len);
static int  is_valid_tag(const uint8_t *tag, size_t len);
static int  button_pressed(void);
static void engage_locks(void);
static void disengage_locks(void);
static void cleanup(void);

/* ------------------------------- Signal handler -------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------- Logging --------------------------------- */
static void log_event(const char *event)
{
    if (!g_log_file)
        return;

    time_t now = time(NULL);
    struct tm tm_buf;
    struct tm *t = localtime_r(&now, &tm_buf);
    char ts[32];

    if (t)
        strftime(ts, sizeof(ts), "%Y-%m-%dT%H:%M:%S", t);
    else
        snprintf(ts, sizeof(ts), "UNKNOWN");

    fprintf(g_log_file, "%s %s\n", ts, event);
    fflush(g_log_file);
}

/* --------------------------- RFID read (non-blocking) --------------------- */
/*
 * Reads up to `len` bytes from the RFID reader.
 * Returns  1 on success (tag data copied to `tag`).
 * Returns  0 on no tag present (all-zero response).
 * Returns -1 on SPI error.
 */
static int read_rfid_tag(uint8_t *tag, size_t len)
{
    if (!tag || len == 0)
        return -1;

    char rx[32];
    int  bytes;

    /*
     * pigpio's spiXfer() returns the number of bytes transferred, or a
     * negative value on error.  We call it up to 4 times to give the
     * reader time to respond.
     */
    for (int attempt = 0; attempt < 4; attempt++) {
        bytes = spiXfer(g_spi_handle, (char *)tag, rx, (int)len);
        if (bytes > 0)
            break;
        if (bytes < 0) {
            log_event("SPI read error");
            return -1;
        }
        gpioDelay(1000); /* 1 ms back-off before retry */
    }

    if (bytes <= 0) {
        log_event("RFID read failed after retries");
        return -1;
    }

    /* All-zero response means no tag is currently present */
    int all_zero = 1;
    for (int i = 0; i < bytes; i++) {
        if (tag[i] != 0) {
            all_zero = 0;
            break;
        }
    }
    if (all_zero)
        return 0;

    return 1;
}

/* --------------------------- Tag validation ------------------------------ */
static int is_valid_tag(const uint8_t *tag, size_t len)
{
    if (!tag || len != sizeof(VALID_TAG))
        return 0;
    return memcmp(tag, VALID_TAG, len) == 0;
}

/* ----------------------------- Button press ------------------------------ */
static int button_pressed(void)
{
    static uint32_t last_tick = 0;
    uint32_t now = gpioTick();

    if (gpioRead(BUTTON_GPIO) == 0) {
        if ((now - last_tick) > DEBOUNCE_US) {
            last_tick = now;
            return 1;
        }
    }
    return 0;
}

/* ------------------------------ Lock control ----------------------------- */
static void engage_locks(void)
{
    gpioWrite(LOCK_1_GPIO, LOCK_ENGAGED);
    gpioWrite(LOCK_2_GPIO, LOCK_ENGAGED);
    log_event("Locks engaged");
}

static void disengage_locks(void)
{
    gpioWrite(LOCK_1_GPIO, LOCK_DISENGAGED);
    gpioWrite(LOCK_2_GPIO, LOCK_DISENGAGED);
    log_event("Locks disengaged");
}

/* ------------------------------- Cleanup --------------------------------- */
static void cleanup(void)
{
    /* Force locks to engaged state (closed) */
    if (g_spi_handle >= 0) {
        gpioWrite(LOCK_1_GPIO, LOCK_ENGAGED);
        gpioWrite(LOCK_2_GPIO, LOCK_ENGAGED);
        spiClose(g_spi_handle);
        g_spi_handle = -1;
    }

    if (g_log_file) {
        log_event("Program terminated");
        fclose(g_log_file);
        g_log_file = NULL;
    }

    gpioTerminate();
}

/* --------------------------------- Main ---------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Configure lock GPIOs as outputs, initially engaged (closed) */
    gpioSetMode(LOCK_1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK_2_GPIO, PI_OUTPUT);
    gpioWrite(LOCK_1_GPIO, LOCK_ENGAGED);
    gpioWrite(LOCK_2_GPIO, LOCK_ENGAGED);

    /* Configure button GPIO as input with internal pull-up */
    gpioSetMode(BUTTON_GPIO, PI_INPUT);
    gpioSetPullUpDown(BUTTON_GPIO, PI_PUD_UP);

    /* Open SPI channel 0 at 100 kHz, mode 0 */
    g_spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, SPI_FLAGS);
    if (g_spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (handle=%d).\n", g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    g_log_file = fopen(LOG_FILE, "a");
    if (!g_log_file) {
        fprintf(stderr, "Error: cannot open log file '%s'.\n", LOG_FILE);
        spiClose(g_spi_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    log_event("Program started");
    printf("Door access control system started. Press Ctrl+C to exit.\n");

    uint8_t tag[32];

    while (g_running) {
        int rc = read_rfid_tag(tag, sizeof(tag));

        if (rc == 1) {
            if (is_valid_tag(tag, sizeof(VALID_TAG))) {
                log_event("Valid tag detected");
                printf("Valid tag detected. Waiting for button press...\n");

                while (g_running && !button_pressed())
                    gpioDelay(10000); /* 10 ms poll */

                if (!g_running)
                    break;

                log_event("Button pressed");
                printf("Button pressed. Disengaging locks for 5 seconds...\n");

                disengage_locks();
                gpioDelay(LOCK_HOLD_US);
                engage_locks();

                log_event("Access granted");
                printf("Access granted.\n");
            } else {
                log_event("Invalid tag detected");
                printf("Invalid tag detected.\n");
            }
        } else if (rc == 0) {
            /* No tag present — not an error, just wait */
            gpioDelay(100000); /* 100 ms */
        } else {
            /* SPI error already logged in read_rfid_tag */
            gpioDelay(500000); /* 500 ms back-off on error */
        }
    }

    cleanup();
    return EXIT_SUCCESS;
}

