#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

#define MOTOR1_ENA 23
#define MOTOR1_IN1 24
#define MOTOR1_IN2 25
#define MOTOR2_ENB 12
#define MOTOR2_IN3 16
#define MOTOR2_IN4 20

#define ENCODER1_A 5
#define ENCODER1_B 6
#define ENCODER2_A 26
#define ENCODER2_B 19

#define TARGET_SPEED 60.0
#define KP 0.5
#define KI 0.01
#define KD 0.1
#define PWM_FREQUENCY 100
#define PWM_PERIOD_US (1000000 / PWM_FREQUENCY)
#define SAMPLE_TIME_MS 100
#define SAMPLE_TIME_S (SAMPLE_TIME_MS / 1000.0)

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *motor_lines[6] = {NULL};
static struct gpiod_line *encoder_lines[4] = {NULL};
static pthread_mutex_t encoder_mutex1 = PTHREAD_MUTEX_INITIALIZER;
static pthread_mutex_t encoder_mutex2 = PTHREAD_MUTEX_INITIALIZER;
static int encoder1_count = 0;
static int encoder2_count = 0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_data(float speed1, float speed2, float p, float i, float d, float pid_output) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f,%.2f,%.2f\n",
            timestamp, speed1, speed2, p, i, d, pid_output);
    fflush(log_file);
}

static void set_motor_direction(int motor, int direction) {
    struct gpiod_line *in1, *in2;
    if (motor == 1) {
        in1 = motor_lines[0];
        in2 = motor_lines[1];
    } else {
        in1 = motor_lines[2];
        in2 = motor_lines[3];
    }
    if (direction == 1) {
        gpiod_line_set_value(in1, 1);
        gpiod_line_set_value(in2, 0);
    } else if (direction == -1) {
        gpiod_line_set_value(in1, 0);
        gpiod_line_set_value(in2, 1);
    } else {
        gpiod_line_set_value(in1, 0);
        gpiod_line_set_value(in2, 0);
    }
}

static void set_motor_speed(int motor, float speed) {
    struct gpiod_line *ena;
    if (motor == 1) ena = motor_lines[0];
    else ena = motor_lines[2];

    if (speed < 0) speed = 0;
    if (speed > 100) speed = 100;

    int duty_cycle = (int)(speed * PWM_PERIOD_US / 100.0);
    int on_time = duty_cycle;
    int off_time = PWM_PERIOD_US - duty_cycle;

    if (on_time > 0) {
        gpiod_line_set_value(ena, 1);
        usleep(on_time);
    }
    if (off_time > 0) {
        gpiod_line_set_value(ena, 0);
        usleep(off_time);
    }
}

static float calculate_pid(float current_speed, float target_speed,
                           float *integral, float *previous_error) {
    float error = target_speed - current_speed;
    *integral += error * SAMPLE_TIME_S;
    float derivative = (error - *previous_error) / SAMPLE_TIME_S;
    float output = KP * error + KI * (*integral) + KD * derivative;
    *previous_error = error;
    return output;
}

static void *encoder_thread1(void *arg) {
    (void)arg;
    int last_a = 0, last_b = 0;
    while (running) {
        int a = gpiod_line_get_value(encoder_lines[0]);
        int b = gpiod_line_get_value(encoder_lines[1]);
        if (a < 0 || b < 0) {
            fprintf(stderr, "Error reading encoder 1: %s\n", strerror(errno));
            usleep(10000);
            continue;
        }
        if (a != last_a) {
            pthread_mutex_lock(&encoder_mutex1);
            if (a == b) encoder1_count++;
            else encoder1_count--;
            pthread_mutex_unlock(&encoder_mutex1);
            last_a = a;
        }
        usleep(1000);
    }
    return NULL;
}

static void *encoder_thread2(void *arg) {
    (void)arg;
    int last_a = 0, last_b = 0;
    while (running) {
        int a = gpiod_line_get_value(encoder_lines[2]);
        int b = gpiod_line_get_value(encoder_lines[3]);
        if (a < 0 || b < 0) {
            fprintf(stderr, "Error reading encoder 2: %s\n", strerror(errno));
            usleep(10000);
            continue;
        }
        if (a != last_a) {
            pthread_mutex_lock(&encoder_mutex2);
            if (a == b) encoder2_count++;
            else encoder2_count--;
            pthread_mutex_unlock(&encoder_mutex2);
            last_a = a;
        }
        usleep(1000);
    }
    return NULL;
}

static float calculate_speed(int encoder_count, float sample_time) {
    float rotations = (float)encoder_count / 4.0;
    return (rotations / sample_time) * 60.0;
}

static void cleanup(void) {
    for (int i = 0; i < 6; i++) {
        if (motor_lines[i]) {
            gpiod_line_set_value(motor_lines[i], 0);
            gpiod_line_release(motor_lines[i]);
        }
    }
    for (int i = 0; i < 4; i++) {
        if (encoder_lines[i]) gpiod_line_release(encoder_lines[i]);
    }
    if (chip) gpiod_chip_close(chip);
    if (log_file) fclose(log_file);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction");
        return 1;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name");
        return 1;
    }

    int motor_pins[6] = {MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2, MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4};
    for (int i = 0; i < 6; i++) {
        motor_lines[i] = gpiod_chip_get_line(chip, motor_pins[i]);
        if (!motor_lines[i]) {
            fprintf(stderr, "Failed to get motor line %d: %s\n", motor_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_output(motor_lines[i], "motor", 0) < 0) {
            fprintf(stderr, "Failed to request motor line %d as output: %s\n", motor_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    int encoder_pins[4] = {ENCODER1_A, ENCODER1_B, ENCODER2_A, ENCODER2_B};
    for (int i = 0; i < 4; i++) {
        encoder_lines[i] = gpiod_chip_get_line(chip, encoder_pins[i]);
        if (!encoder_lines[i]) {
            fprintf(stderr, "Failed to get encoder line %d: %s\n", encoder_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
        if (gpiod_line_request_both_edges_events(encoder_lines[i], "encoder") < 0) {
            fprintf(stderr, "Failed to request encoder line %d for events: %s\n", encoder_pins[i], strerror(errno));
            cleanup();
            return 1;
        }
    }

    log_file = fopen("motor_log.csv", "a");
    if (!log_file) {
        perror("fopen");
        cleanup();
        return 1;
    }
    fprintf(log_file, "Timestamp,Speed1,RPM,Speed2,RPM,P,I,D,PID_Output\n");
    fflush(log_file);

    pthread_t enc1_thread, enc2_thread;
    if (pthread_create(&enc1_thread, NULL, encoder_thread1, NULL) != 0 ||
        pthread_create(&enc2_thread, NULL, encoder_thread2, NULL) != 0) {
        perror("pthread_create");
        cleanup();
        return 1;
    }

    float integral1 = 0, integral2 = 0;
    float prev_error1 = 0, prev_error2 = 0;

    while (running) {
        int count1, count2;
        pthread_mutex_lock(&encoder_mutex1);
        count1 = encoder1_count;
        encoder1_count = 0;
        pthread_mutex_unlock(&encoder_mutex1);

        pthread_mutex_lock(&encoder_mutex2);
        count2 = encoder2_count;
        encoder2_count = 0;
        pthread_mutex_unlock(&encoder_mutex2);

        float speed1 = calculate_speed(count1, SAMPLE_TIME_S);
        float speed2 = calculate_speed(count2, SAMPLE_TIME_S);

        float pid1 = calculate_pid(speed1, TARGET_SPEED, &integral1, &prev_error1);
        float pid2 = calculate_pid(speed2, TARGET_SPEED, &integral2, &prev_error2);

        float duty1 = pid1;
        float duty2 = pid2;

        if (duty1 > 100) duty1 = 100;
        if (duty1 < -100) duty1 = -100;
        if (duty2 > 100) duty2 = 100;
        if (duty2 < -100) duty2 = -100;

        set_motor_direction(1, (duty1 >= 0) ? 1 : -1);
        set_motor_speed(1, (duty1 >= 0) ? duty1 : -duty1);

        set_motor_direction(2, (duty2 >= 0) ? 1 : -1);
        set_motor_speed(2, (duty2 >= 0) ? duty2 : -duty2);

        log_data(speed1, speed2, KP * (TARGET_SPEED - speed1),
                 KI * integral1, KD * ((TARGET_SPEED - speed1) - prev_error1) / SAMPLE_TIME_S, pid1);

        usleep(SAMPLE_TIME_MS * 1000);
    }

    pthread_join(enc1_thread, NULL);
    pthread_join(enc2_thread, NULL);
    cleanup();
    return 0;
}

