/*
 * MPR121 Capacitive Touch Sensor -> Relay Control
 * Board:  Raspberry Pi 3 Model B+
 * Bus:    I2C bus 1 (GPIO2=SDA, GPIO3=SCL)
 * Sensor: MPR121 at address 0x5A (ADDR pin tied to GND)
 * Relay:  GPIO 17 (BCM)
 *
 * Build:  gcc -O2 -Wall -o mpr121_relay mpr121_relay.c -lpigpio -lrt
 * Run:    sudo ./mpr121_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

/* ----------------------------- Configuration ----------------------------- */
#define I2C_BUS             1
#define MPR121_ADDR         0x5A
#define RELAY_GPIO          17
#define LOG_FILE            "relay_log.txt"
#define POLL_DELAY_US       50000   /* 50 ms */

/* MPR121 Register Map */
#define MPR121_TOUCHSTATUS  0x00
#define MPR121_ECR          0x5E
#define MPR121_SOFTRESET    0x80

/* ----------------------------- Globals ----------------------------------- */
static int      i2c_handle = -1;
static FILE    *log_file   = NULL;
static volatile sig_atomic_t terminate = 0;

/* ----------------------------- Prototypes -------------------------------- */
static int  mpr121_init(void);
static int  mpr121_read_touch(uint16_t *touch_status);
static void relay_set(int state);
static void log_event(int state);
static void cleanup(void);
static void signal_handler(int sig);

/* ----------------------------- MPR121 Init ------------------------------- */
static int mpr121_init(void)
{
    /* Soft reset: write 0x63 to register 0x80 */
    if (i2cWriteByteData(i2c_handle, MPR121_SOFTRESET, 0x63) < 0) {
        fprintf(stderr, "Error: MPR121 soft reset failed (sensor absent or bus error).\n");
        return -1;
    }
    gpioDelay(1000);  /* 1 ms settle after reset */

    /* Baseline filtering – rising/falling (MHD, NHD, NCL, FDL) */
    if (i2cWriteByteData(i2c_handle, 0x2B, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x2C, 0x01) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x2D, 0x00) < 0) return -1;
    if (i2cWriteByteData(i2c_handle, 0x2E, 0x00) < 0) return -1;

    /* Touch / release thresholds for all 12 electrodes */
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x0F) < 0) return -1; /* touch threshold */
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x0A) < 0) return -1; /* release threshold */
    }

    /* Enable 12 electrodes, baseline tracking, run mode (ECR = 0x8F) */
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x8F) < 0) {
        fprintf(stderr, "Error: Failed to write ECR (run mode).\n");
        return -1;
    }

    gpioDelay(1000);  /* 1 ms settle after configuration */
    return 0;
}

/* ----------------------------- Read Touch Status ------------------------- */
static int mpr121_read_touch(uint16_t *touch_status)
{
    char buf[2];

    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status from MPR121.\n");
        return -1;
    }

    *touch_status = ((uint16_t)(uint8_t)buf[1] << 8) | (uint8_t)buf[0];
    return 0;
}

/* ----------------------------- Relay Control ----------------------------- */
static void relay_set(int state)
{
    if (gpioWrite(RELAY_GPIO, state) < 0) {
        fprintf(stderr, "Warning: gpioWrite failed for relay GPIO %d.\n", RELAY_GPIO);
    }
}

/* ----------------------------- Logging ----------------------------------- */
static void log_event(int state)
{
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    localtime_r(&rawtime, &timeinfo);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo);

    if (log_file) {
        fprintf(log_file, "%s - Relay: %s\n", timestamp, state ? "ON" : "OFF");
        fflush(log_file);
    } else {
        fprintf(stderr, "Error: Log file not open.\n");
    }
}

/* ----------------------------- Cleanup ----------------------------------- */
static void cleanup(void)
{
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
        i2c_handle = -1;
    }
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

/* ----------------------------- Signal Handler ---------------------------- */
static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

/* ----------------------------- Main -------------------------------------- */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return EXIT_FAILURE;
    }

    /* Open I2C bus */
    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: i2cOpen failed (bus %d, addr 0x%02X).\n", I2C_BUS, MPR121_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Initialize MPR121 */
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialization failed.\n");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Configure relay GPIO */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: gpioSetMode failed for GPIO %d.\n", RELAY_GPIO);
        cleanup();
        return EXIT_FAILURE;
    }
    relay_set(0);  /* Ensure relay starts OFF */

    /* Open log file */
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error: Cannot open log file '%s'.\n", LOG_FILE);
        cleanup();
        return EXIT_FAILURE;
    }

    /* Register signal handler */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("MPR121 relay control running. Press Ctrl+C to exit.\n");

    int last_relay_state = -1;  /* Force initial log */

    while (!terminate) {
        uint16_t touch_status = 0;

        if (mpr121_read_touch(&touch_status) == 0) {
            int relay_state = (touch_status != 0) ? 1 : 0;

            if (relay_state != last_relay_state) {
                relay_set(relay_state);
                log_event(relay_state);
                last_relay_state = relay_state;
            }
        } else {
            /* Sensor read error – ensure relay is OFF for safety */
            if (last_relay_state != 0) {
                relay_set(0);
                log_event(0);
                last_relay_state = 0;
            }
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Graceful shutdown */
    relay_set(0);
    log_event(0);
    cleanup();
    printf("Shutdown complete.\n");
    return EXIT_SUCCESS;
}

