/*
 * MPR121 Capacitive Touch Sensor - Relay Toggle
 * Board: Raspberry Pi Zero W
 * I2C Bus: 1 (SDA=GPIO2, SCL=GPIO3)
 * Relay: GPIO17 (BCM)
 *
 * Compile: gcc -o mpr121_relay mpr121_relay.c -lpigpio -lrt
 * Run: sudo ./mpr121_relay
 */

#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define I2C_BUS 1
#define MPR121_ADDR 0x5A
#define RELAY_GPIO 17

#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELE0_T_THRESH 0x41
#define MPR121_ELE0_R_THRESH 0x42
#define MPR121_MHD_RISE 0x2B
#define MPR121_NHD_RISE 0x2C
#define MPR121_NCL_RISE 0x2D
#define MPR121_FDL_RISE 0x2E
#define MPR121_MHD_FALL 0x2F
#define MPR121_NHD_FALL 0x30
#define MPR121_NCL_FALL 0x31
#define MPR121_FDL_FALL 0x32
#define MPR121_NHD_FILT 0x33
#define MPR121_NCL_FILT 0x34
#define MPR121_FDL_FILT 0x35
#define MPR121_E0TTH 0x41
#define MPR121_E0RTH 0x42
#define MPR121_DEBOUNCE 0x5B
#define MPR121_CONFIG1 0x5C
#define MPR121_CONFIG2 0x5D
#define MPR121_ECR 0x5E

static volatile sig_atomic_t running = 1;
static int i2c_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int mpr121_write(uint8_t reg, uint8_t value) {
    int rc = i2cWriteByteData(i2c_handle, reg, value);
    if (rc < 0) {
        fprintf(stderr, "I2C write failed (reg=0x%02X, val=0x%02X): %d\n", reg, value, rc);
    }
    return rc;
}

static int mpr121_read(uint8_t reg) {
    int rc = i2cReadByteData(i2c_handle, reg);
    if (rc < 0) {
        fprintf(stderr, "I2C read failed (reg=0x%02X): %d\n", reg, rc);
    }
    return rc;
}

static int mpr121_init(void) {
    if (mpr121_write(MPR121_ECR, 0x00) < 0) return -1;
    gpioDelay(1000);

    if (mpr121_write(MPR121_MHD_RISE, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHD_RISE, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCL_RISE, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDL_RISE, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_MHD_FALL, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NHD_FALL, 0x01) < 0) return -1;
    if (mpr121_write(MPR121_NCL_FALL, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDL_FALL, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_NHD_FILT, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_NCL_FILT, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_FDL_FILT, 0x00) < 0) return -1;

    for (int i = 0; i < 12; i++) {
        if (mpr121_write(MPR121_E0TTH + (i * 2), 0x0F) < 0) return -1;
        if (mpr121_write(MPR121_E0RTH + (i * 2), 0x0A) < 0) return -1;
    }

    if (mpr121_write(MPR121_DEBOUNCE, 0x00) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG1, 0x10) < 0) return -1;
    if (mpr121_write(MPR121_CONFIG2, 0x20) < 0) return -1;
    if (mpr121_write(MPR121_ECR, 0x8F) < 0) return -1;

    gpioDelay(100000);
    return 0;
}

static int mpr121_read_touch_status(void) {
    int low = mpr121_read(MPR121_TOUCHSTATUS_L);
    if (low < 0) return -1;
    int high = mpr121_read(MPR121_TOUCHSTATUS_H);
    if (high < 0) return -1;
    return (high << 8) | low;
}

int main(void) {
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    i2c_handle = i2cOpen(I2C_BUS, MPR121_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus %d at address 0x%02X: %d\n", I2C_BUS, MPR121_ADDR, i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (mpr121_init() < 0) {
        fprintf(stderr, "MPR121 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RELAY_GPIO);
        i2cClose(i2c_handle);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    int relay_state = 0;

    while (running) {
        int touch_status = mpr121_read_touch_status();
        if (touch_status < 0) {
            fprintf(stderr, "Error reading touch status, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        if (touch_status > 0) {
            relay_state = !relay_state;
            if (gpioWrite(RELAY_GPIO, relay_state) < 0) {
                fprintf(stderr, "Failed to write to relay GPIO %d\n", RELAY_GPIO);
            } else {
                printf("Relay toggled to state: %d\n", relay_state);
            }
        }

        gpioDelay(100000);
    }

    gpioWrite(RELAY_GPIO, 0);
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

