#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <unistd.h>
#include <pigpio.h>

#define PIR_PIN 17
#define RELAY_PIN 18
#define UNLOCK_DURATION_MS 500
#define RATE_LIMIT_MS 2000
#define POLL_INTERVAL_US 50000

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void log_event(const char *event_type) {
    if (!log_file) return;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    struct tm tm_info;
    localtime_r(&ts.tv_sec, &tm_info);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm_info);
    long ms = ts.tv_nsec / 1000000;
    fprintf(log_file, "%s.%03ld: %s\n", timestamp, ms, event_type);
    fflush(log_file);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return 1;
    }

    if (gpioSetMode(PIR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Error: failed to set PIR pin %d as input.\n", PIR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetPullUpDown(PIR_PIN, PI_PUD_DOWN) != 0) {
        fprintf(stderr, "Error: failed to set pull-down on PIR pin %d.\n", PIR_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(RELAY_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set relay pin %d as output.\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioWrite(RELAY_PIN, 0) != 0) {
        fprintf(stderr, "Error: failed to initialize relay pin %d to off.\n", RELAY_PIN);
        gpioTerminate();
        return 1;
    }

    log_file = fopen("door_events.log", "a");
    if (!log_file) {
        fprintf(stderr, "Error: failed to open log file door_events.log.\n");
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to install SIGINT handler.\n");
    }

    printf("Door strike controller started. PIR=GPIO%d, Relay=GPIO%d\n", PIR_PIN, RELAY_PIN);
    printf("Press Ctrl+C to exit.\n");

    int last_pir = 0;
    uint32_t last_unlock_tick = 0;
    uint32_t last_motion_tick = 0;

    while (running) {
        int pir_val = gpioRead(PIR_PIN);
        if (pir_val < 0) {
            fprintf(stderr, "Error: failed to read PIR pin %d.\n", PIR_PIN);
            break;
        }

        uint32_t now = gpioTick();

        if (pir_val == 1 && last_pir == 0) {
            if (last_motion_tick == 0 || (now - last_motion_tick) >= (RATE_LIMIT_MS * 1000)) {
                log_event("Motion Detected");
                printf("Motion detected!\n");

                if (gpioWrite(RELAY_PIN, 1) != 0) {
                    fprintf(stderr, "Error: failed to activate relay.\n");
                } else {
                    log_event("Door Unlocked");
                    printf("Door unlocked for %d ms.\n", UNLOCK_DURATION_MS);
                    last_unlock_tick = now;
                    gpioDelay(UNLOCK_DURATION_MS * 1000);
                    if (gpioWrite(RELAY_PIN, 0) != 0) {
                        fprintf(stderr, "Error: failed to deactivate relay.\n");
                    }
                    log_event("Door Locked");
                    printf("Door locked.\n");
                }
                last_motion_tick = now;
            } else {
                log_event("Motion Rate Limited");
                printf("Motion rate limited.\n");
            }
        }

        if (last_unlock_tick != 0 && (now - last_unlock_tick) >= (UNLOCK_DURATION_MS * 1000)) {
            if (gpioWrite(RELAY_PIN, 0) != 0) {
                fprintf(stderr, "Error: failed to ensure relay is off.\n");
            }
            last_unlock_tick = 0;
        }

        last_pir = pir_val;
        gpioDelay(POLL_INTERVAL_US);
    }

    printf("\nShutting down...\n");
    gpioWrite(RELAY_PIN, 0);
    if (log_file) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
    printf("Cleanup complete.\n");
    return 0;
}

