#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define MOTOR_1_PIN 17
#define MOTOR_2_PIN 27
#define PWM_RANGE 255
#define MIN_STEPS 5
#define MAX_STEPS 15
#define MIN_DUTY 0
#define MAX_DUTY 255
#define MIN_DURATION_MS 50
#define MAX_DURATION_MS 200

typedef struct {
    int motor1_duty;
    int motor2_duty;
    int duration_ms;
} HapticStep;

typedef struct {
    HapticStep *steps;
    int num_steps;
} HapticPattern;

static volatile sig_atomic_t shutdown_flag = 0;

static void signal_handler(int sig) {
    (void)sig;
    shutdown_flag = 1;
}

static int initialize_gpio(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialization failed.\n");
        return -1;
    }

    if (gpioSetMode(MOTOR_1_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR_1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetMode(MOTOR_2_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error: failed to set GPIO %d as output.\n", MOTOR_2_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(MOTOR_1_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range for GPIO %d.\n", MOTOR_1_PIN);
        gpioTerminate();
        return -1;
    }

    if (gpioSetPWMrange(MOTOR_2_PIN, PWM_RANGE) != 0) {
        fprintf(stderr, "Error: failed to set PWM range for GPIO %d.\n", MOTOR_2_PIN);
        gpioTerminate();
        return -1;
    }

    return 0;
}

static void cleanup_gpio(void) {
    gpioPWM(MOTOR_1_PIN, 0);
    gpioPWM(MOTOR_2_PIN, 0);
    gpioTerminate();
}

static HapticPattern generate_random_pattern(void) {
    HapticPattern pattern;
    pattern.num_steps = (rand() % (MAX_STEPS - MIN_STEPS + 1)) + MIN_STEPS;
    pattern.steps = (HapticStep *)malloc((size_t)pattern.num_steps * sizeof(HapticStep));

    if (pattern.steps == NULL) {
        fprintf(stderr, "Error: memory allocation failed for pattern steps.\n");
        pattern.num_steps = 0;
        return pattern;
    }

    for (int i = 0; i < pattern.num_steps; i++) {
        pattern.steps[i].motor1_duty = rand() % (MAX_DUTY - MIN_DUTY + 1) + MIN_DUTY;
        pattern.steps[i].motor2_duty = rand() % (MAX_DUTY - MIN_DUTY + 1) + MIN_DUTY;
        pattern.steps[i].duration_ms = (rand() % (MAX_DURATION_MS - MIN_DURATION_MS + 1)) + MIN_DURATION_MS;
    }

    return pattern;
}

static void play_pattern(const HapticPattern *pattern) {
    for (int i = 0; i < pattern->num_steps; i++) {
        if (shutdown_flag) {
            break;
        }

        if (gpioPWM(MOTOR_1_PIN, pattern->steps[i].motor1_duty) != 0) {
            fprintf(stderr, "Warning: failed to set PWM on GPIO %d.\n", MOTOR_1_PIN);
        }

        if (gpioPWM(MOTOR_2_PIN, pattern->steps[i].motor2_duty) != 0) {
            fprintf(stderr, "Warning: failed to set PWM on GPIO %d.\n", MOTOR_2_PIN);
        }

        gpioDelay((unsigned)pattern->steps[i].duration_ms * 1000);
    }
}

static void free_pattern(HapticPattern *pattern) {
    if (pattern != NULL && pattern->steps != NULL) {
        free(pattern->steps);
        pattern->steps = NULL;
        pattern->num_steps = 0;
    }
}

int main(void) {
    srand((unsigned int)time(NULL));

    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        fprintf(stderr, "Warning: failed to register SIGINT handler.\n");
    }

    printf("Haptic feedback generator started. Press Ctrl+C to exit.\n");

    while (!shutdown_flag) {
        HapticPattern pattern = generate_random_pattern();

        if (pattern.num_steps == 0) {
            fprintf(stderr, "Error: pattern generation failed, retrying...\n");
            gpioDelay(100000);
            continue;
        }

        play_pattern(&pattern);
        free_pattern(&pattern);
    }

    cleanup_gpio();
    printf("\nShutdown complete.\n");
    return EXIT_SUCCESS;
}

