#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "weight_log.txt"

#define HX711_TIMEOUT_US 500000
#define SAMPLE_INTERVAL_US 500000
#define CALIBRATION_SAMPLES 100
#define WEIGHT_THRESHOLD 10.0

static volatile sig_atomic_t running = 1;
static double scale_factor = 1.0;
static double offset = 0.0;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_hx711(int data_pin, int clock_pin) {
    int value = 0;
    int i;

    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    for (i = 0; i < 24; i++) {
        gpioWrite(clock_pin, 1);
        gpioDelay(1);
        value = value << 1;
        if (gpioRead(data_pin)) {
            value++;
        }
        gpioWrite(clock_pin, 0);
        gpioDelay(1);
    }

    gpioWrite(clock_pin, 1);
    gpioDelay(1);
    gpioWrite(clock_pin, 0);
    gpioDelay(1);

    if (value & 0x800000) {
        value |= ~0xffffff;
    }

    return value;
}

static double get_weight(int data_pin, int clock_pin, double scale, double off) {
    int raw = read_hx711(data_pin, clock_pin);
    return (double)(raw - off) / scale;
}

static int calibrate_hx711(int data_pin, int clock_pin, double *scale, double *off) {
    double sum = 0.0;
    int valid = 0;

    printf("Calibrating HX711 (remove all weight)...\n");
    gpioDelay(2000000);

    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int raw = read_hx711(data_pin, clock_pin);
        if (raw == -1) {
            fprintf(stderr, "HX711 timeout during calibration.\n");
            return -1;
        }
        sum += raw;
        gpioDelay(10000);
    }

    *off = sum / CALIBRATION_SAMPLES;
    printf("Offset: %.2f\n", *off);

    printf("Place known weight on load cell...\n");
    gpioDelay(2000000);

    sum = 0.0;
    valid = 0;
    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        int raw = read_hx711(data_pin, clock_pin);
        if (raw == -1) {
            fprintf(stderr, "HX711 timeout during calibration.\n");
            return -1;
        }
        sum += raw;
        gpioDelay(10000);
    }

    double known_weight_raw = sum / CALIBRATION_SAMPLES;
    double known_weight = 100.0;

    *scale = (known_weight_raw - *off) / known_weight;
    printf("Scale factor: %.6f\n", *scale);

    return 0;
}

static int load_calibration(const char *filename, double *scale, double *off) {
    FILE *fp = fopen(filename, "r");
    if (!fp) {
        fprintf(stderr, "Calibration file not found. Using defaults.\n");
        return -1;
    }

    if (fscanf(fp, "%lf %lf", scale, off) != 2) {
        fprintf(stderr, "Invalid calibration file format. Using defaults.\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    printf("Loaded calibration: scale=%.6f, offset=%.2f\n", *scale, *off);
    return 0;
}

static int save_calibration(const char *filename, double scale, double off) {
    FILE *fp = fopen(filename, "w");
    if (!fp) {
        fprintf(stderr, "Error opening calibration file for writing.\n");
        return -1;
    }
    fprintf(fp, "%.6f %.2f\n", scale, off);
    fclose(fp);
    return 0;
}

static void log_weight(double weight) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file.\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Weight: %.2f kg\n", timestamp, weight);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0);

    if (load_calibration(CALIBRATION_FILE, &scale_factor, &offset) != 0) {
        if (calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &scale_factor, &offset) != 0) {
            fprintf(stderr, "Calibration failed. Exiting.\n");
            gpioTerminate();
            return 1;
        }
        save_calibration(CALIBRATION_FILE, scale_factor, offset);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting weight monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        int raw = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw == -1) {
            fprintf(stderr, "HX711 timeout. Skipping iteration.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double weight = get_weight(HX711_DATA_PIN, HX711_CLOCK_PIN, scale_factor, offset);
        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            gpioWrite(SOLENOID_PIN, 1);
            printf("Solenoid engaged!\n");
        } else {
            gpioWrite(SOLENOID_PIN, 0);
        }

        log_weight(weight);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Exiting cleanly.\n");
    return 0;
}

