    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Weight: %.2f kg\n", timestamp, weight);
    fclose(fp);
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed.\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0);

    if (load_calibration(CALIBRATION_FILE, &scale_factor, &offset) != 0) {
        if (calibrate_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN, &scale_factor, &offset) != 0) {
            fprintf(stderr, "Calibration failed. Exiting.\n");
            gpioTerminate();
            return 1;
        }
        save_calibration(CALIBRATION_FILE, scale_factor, offset);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGINT, &sa, NULL);

    printf("Starting weight monitoring. Press Ctrl+C to exit.\n");

    while (running) {
        int raw = read_hx711(HX711_DATA_PIN, HX711_CLOCK_PIN);
        if (raw == -1) {
            fprintf(stderr, "HX711 timeout. Skipping iteration.\n");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        double weight = get_weight(HX711_DATA_PIN, HX711_CLOCK_PIN, scale_factor, offset);
        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            gpioWrite(SOLENOID_PIN, 1);
            printf("Solenoid engaged!\n");
        } else {
            gpioWrite(SOLENOID_PIN, 0);
        }

        log_weight(weight);
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    gpioWrite(SOLENOID_PIN, 0);
    gpioTerminate();
    printf("Exiting cleanly.\n");
    return 0;
}

