/*
 * Ingredient Stock Monitor for Raspberry Pi 4 Model B
 *
 * Hardware:
 *   - TAL220B load cell (analog output) -> HX711 10 kg module
 *   - HX711 data line (DT)  -> GPIO23 (BCM)
 *   - HX711 clock line (SCK) -> GPIO24 (BCM)
 *   - Solenoid lock control -> GPIO17 (BCM)
 *
 * Behavior:
 *   - Reads weight every 1 second.
 *   - If weight < 100 g, activates solenoid lock for 5 s.
 *   - Logs all events (weight, lock activation, errors) to stock_events.txt.
 *   - Handles SIGINT/SIGTERM for graceful shutdown.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <pigpio.h>

#define HX711_DT_PIN    23
#define HX711_SCK_PIN   24
#define LOCK_PIN        17

#define WEIGHT_THRESHOLD_G  100.0f
#define LOCK_DURATION_SEC   5
#define LOG_FILE            "stock_events.txt"
#define SAMPLE_INTERVAL_US  1000000  /* 1 second */
#define HX711_TIMEOUT_US    1000000  /* 1 s timeout for data-ready */

static volatile sig_atomic_t g_running = 1;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Logging                                                             */
/* ------------------------------------------------------------------ */
static void log_event(const char *message)
{
    FILE *fp = fopen(LOG_FILE, "a");
    if (!fp) {
        fprintf(stderr, "Error opening log file '%s': %s\n",
                LOG_FILE, strerror(errno));
        return;
    }

    time_t t = time(NULL);
    struct tm tm;
    if (localtime_r(&t, &tm)) {
        fprintf(fp, "[%04d-%02d-%02d %02d:%02d:%02d] %s\n",
                tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday,
                tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    } else {
        fprintf(fp, "[timestamp error] %s\n", message);
    }

    fclose(fp);
}

/* ------------------------------------------------------------------ */
/* HX711 bit-banged read                                               */
/* ------------------------------------------------------------------ */
/*
 * Returns 0 on success and stores the 24-bit signed value in *out.
 * Returns -1 on timeout or GPIO error.
 */
static int hx711_read(int32_t *out)
{
    if (!out) {
        return -1;
    }

    /* Ensure SCK is low before starting */
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
        log_event("HX711: failed to set SCK low");
        return -1;
    }

    /* Wait for DT to go low (data ready) */
    uint32_t waited = 0;
    while (gpioRead(HX711_DT_PIN) == 1) {
        if (waited >= HX711_TIMEOUT_US) {
            log_event("HX711: timeout waiting for data-ready (DT stuck high)");
            return -1;
        }
        gpioDelay(100);  /* 100 us granularity */
        waited += 100;
    }

    /* Read 24 data bits, MSB first */
    int32_t value = 0;
    for (int i = 0; i < 24; i++) {
        if (gpioWrite(HX711_SCK_PIN, 1) < 0) {
            log_event("HX711: failed to set SCK high");
            return -1;
        }
        gpioDelay(1);  /* >0.2 us high pulse */

        value <<= 1;
        if (gpioRead(HX711_DT_PIN) == 1) {
            value |= 1;
        }

        if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
            log_event("HX711: failed to set SCK low");
            return -1;
        }
        gpioDelay(1);  /* >0.2 us low pulse */
    }

    /* 25th pulse: channel A gain 128, no sleep */
    if (gpioWrite(HX711_SCK_PIN, 1) < 0) {
        log_event("HX711: failed to set SCK high (25th pulse)");
        return -1;
    }
    gpioDelay(1);
    if (gpioWrite(HX711_SCK_PIN, 0) < 0) {
        log_event("HX711: failed to set SCK low (25th pulse)");
        return -1;
    }
    gpioDelay(1);

    /* Convert 24-bit two's complement to 32-bit signed */
    if (value & 0x800000) {
        value |= 0xFF000000;  /* sign-extend */
    }

    *out = value;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Solenoid control                                                    */
/* ------------------------------------------------------------------ */
static int solenoid_lock(int activate)
{
    if (gpioWrite(LOCK_PIN, activate ? 1 : 0) < 0) {
        log_event("Failed to write solenoid GPIO");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* Initialize pigpio */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialization failed\n");
        return EXIT_FAILURE;
    }

    /* Configure GPIO pins */
    if (gpioSetMode(HX711_DT_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Failed to set DT pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(HX711_SCK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set SCK pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (gpioSetMode(LOCK_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set LOCK pin mode\n");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure SCK is low and solenoid is off */
    gpioWrite(HX711_SCK_PIN, 0);
    gpioWrite(LOCK_PIN, 0);

    /* Install signal handlers */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction(SIGINT)");
        gpioTerminate();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction(SIGTERM)");
        gpioTerminate();
        return EXIT_FAILURE;
    }

    log_event("Stock monitor started");

    while (g_running) {
        int32_t raw;
        if (hx711_read(&raw) < 0) {
            log_event("HX711 read error");
            gpioDelay(SAMPLE_INTERVAL_US);
            continue;
        }

        /*
         * Convert raw ADC value to grams.
         * Calibration: 1000000 raw counts = 1000 g (full-scale span).
         * Adjust SCALE_FACTOR for your specific load cell/gain setting.
         */
        const float SCALE_FACTOR = 1000.0f / 1000000.0f;
        float weight_g = (float)raw * SCALE_FACTOR;

        char msg[128];
        snprintf(msg, sizeof(msg), "Weight: %.2f g (raw: %d)", weight_g, raw);
        log_event(msg);

        if (weight_g < WEIGHT_THRESHOLD_G) {
            log_event("Weight below threshold, activating solenoid lock");
            if (solenoid_lock(1) == 0) {
                /*
                 * Sleep in 100 ms chunks so we can respond to signals
                 * promptly during the lock-hold window.
                 */
                for (int i = 0; i < LOCK_DURATION_SEC * 10 && g_running; i++) {
                    gpioDelay(100000);  /* 100 ms */
                }
                solenoid_lock(0);
                log_event("Solenoid lock deactivated");
            } else {
                log_event("Failed to deactivate solenoid lock");
            }
        }

        /* Wait for the remainder of the 1-second interval */
        gpioDelay(SAMPLE_INTERVAL_US);
    }

    /* Graceful shutdown */
    solenoid_lock(0);
    log_event("Stock monitor stopped");
    gpioTerminate();

    return EXIT_SUCCESS;
}

