#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <pigpio.h>

#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define WEIGHT_THRESHOLD 5.0
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"
#define HX711_TIMEOUT_US 100000
#define HX711_SETTLE_US 10000
#define HX711_CLOCK_HALF_US 1
#define SOLENOID_LOCK_TIME 5
#define CALIBRATION_SAMPLES 10

static volatile sig_atomic_t running = 1;
static double calibration_factor = 0.0;
static FILE *log_file = NULL;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int hx711_read_raw(int32_t *out) {
    if (out == NULL) return -1;

    uint32_t start = gpioTick();
    while (gpioRead(HX711_DATA_PIN) == 1) {
        if ((gpioTick() - start) > HX711_TIMEOUT_US) {
            return -1;
        }
    }

    int32_t value = 0;
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(HX711_CLOCK_HALF_US);
        value = (value << 1) | (gpioRead(HX711_DATA_PIN) & 1);
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(HX711_CLOCK_HALF_US);
    }

    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(HX711_CLOCK_HALF_US);
    value ^= 0x800000;
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(HX711_CLOCK_HALF_US);

    *out = value;
    return 0;
}

static double read_weight(void) {
    int32_t raw;
    if (hx711_read_raw(&raw) != 0) {
        return -1.0;
    }
    return (double)raw / calibration_factor;
}

static int calibrate_sensor(double known_weight) {
    int32_t raw;
    double sum = 0.0;
    int valid = 0;

    printf("Calibrating sensor... Please place %.2f kg on the load cell.\n", known_weight);
    gpioDelay(HX711_SETTLE_US);

    for (int i = 0; i < CALIBRATION_SAMPLES; i++) {
        if (hx711_read_raw(&raw) == 0) {
            sum += (double)raw;
            valid++;
        }
        gpioDelay(100000);
    }

    if (valid == 0) {
        fprintf(stderr, "Calibration failed: no valid readings.\n");
        return -1;
    }

    double avg_raw = sum / valid;
    calibration_factor = avg_raw / known_weight;

    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error writing calibration factor to file: %s\n", strerror(errno));
        return -1;
    }
    fprintf(fp, "%.6f\n", calibration_factor);
    fclose(fp);

    printf("Calibration complete. Factor: %.6f\n", calibration_factor);
    return 0;
}

static int load_calibration(void) {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Calibration file not found. Run calibration first.\n");
        return -1;
    }
    if (fscanf(fp, "%lf", &calibration_factor) != 1) {
        fprintf(stderr, "Error reading calibration factor.\n");
        fclose(fp);
        return -1;
    }
    fclose(fp);
    printf("Calibration factor loaded: %.6f\n", calibration_factor);
    return 0;
}

static void log_event(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
            return;
        }
    }

    fprintf(log_file, "%s Weight: %.2f kg\n", timestamp, weight);
    fflush(log_file);
}

static void unlock_solenoid(void) {
    printf("Unlocking solenoid...\n");
    gpioWrite(SOLENOID_PIN, 0);
}

static void cleanup(void) {
    unlock_solenoid();
    if (log_file != NULL) {
        fclose(log_file);
        log_file = NULL;
    }
    gpioTerminate();
}

int main(void) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    if (load_calibration() != 0) {
        double known_weight;
        printf("Enter known weight in kg: ");
        if (scanf("%lf", &known_weight) != 1 || known_weight <= 0.0) {
            fprintf(stderr, "Invalid weight input.\n");
            cleanup();
            return 1;
        }
        if (calibrate_sensor(known_weight) != 0) {
            cleanup();
            return 1;
        }
    }

    printf("Starting weight monitoring...\n");

    while (running) {
        double weight = read_weight();
        if (weight < 0.0) {
            fprintf(stderr, "HX711 read timeout or error.\n");
            gpioDelay(1000000);
            continue;
        }

        printf("Weight: %.2f kg\n", weight);

        if (weight > WEIGHT_THRESHOLD) {
            printf("Weight threshold exceeded! Locking solenoid.\n");
            gpioWrite(SOLENOID_PIN, 1);
            log_event(weight);
            gpioDelay(SOLENOID_LOCK_TIME * 1000000);
            unlock_solenoid();
        }

        gpioDelay(100000);
    }

    cleanup();
    return 0;
}

