#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

#define PIR_PIN 17
#define BUZZER_PIN 18
#define BUZZER_DURATION_US 2000000  /* 2 seconds in microseconds */
#define POLL_DELAY_US 100000        /* 100 ms between polls */
#define LOG_FILE "motion_log.txt"

static volatile sig_atomic_t running = 1;
static FILE *log_file = NULL;

/* Signal handler for graceful shutdown */
static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

/* Log a motion event with a timestamp to the log file */
static void log_motion(void) {
    time_t rawtime;
    struct tm timeinfo;
    char timestamp[32];

    time(&rawtime);
    if (localtime_r(&rawtime, &timeinfo) == NULL) {
        fprintf(stderr, "Error: localtime_r failed: %s\n", strerror(errno));
        return;
    }

    if (strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &timeinfo) == 0) {
        fprintf(stderr, "Error: strftime failed\n");
        return;
    }

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error: failed to write to log file: %s\n", strerror(errno));
    } else {
        fflush(log_file);
    }
}

/* Activate the buzzer for the specified duration */
static void activate_buzzer(void) {
    if (gpioWrite(BUZZER_PIN, 1) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin HIGH: %s\n", strerror(errno));
        return;
    }
    gpioDelay(BUZZER_DURATION_US);
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin LOW: %s\n", strerror(errno));
    }
}

int main(void) {
    /* Initialize pigpio library */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* Set GPIO modes */
    if (gpioSetMode(PIR_PIN, PI_INPUT) < 0) {
        fprintf(stderr, "Error: failed to set PIR pin mode: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (gpioSetMode(BUZZER_PIN, PI_OUTPUT) < 0) {
        fprintf(stderr, "Error: failed to set buzzer pin mode: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Ensure buzzer is off initially */
    if (gpioWrite(BUZZER_PIN, 0) < 0) {
        fprintf(stderr, "Error: failed to initialise buzzer state: %s\n", strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Open log file in append mode */
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: failed to open log file '%s': %s\n", LOG_FILE, strerror(errno));
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* Install signal handlers for graceful shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGINT handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    if (sigaction(SIGTERM, &sa, NULL) < 0) {
        fprintf(stderr, "Error: failed to install SIGTERM handler: %s\n", strerror(errno));
        fclose(log_file);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    /* Main loop */
    while (running) {
        int pir_value = gpioRead(PIR_PIN);
        if (pir_value < 0) {
            fprintf(stderr, "Error: failed to read PIR pin: %s\n", strerror(errno));
            break;
        }

        if (pir_value == 1) {
            printf("Motion detected!\n");
            log_motion();
            activate_buzzer();
        }

        gpioDelay(POLL_DELAY_US);
    }

    /* Cleanup */
    printf("\nShutting down...\n");
    gpioWrite(BUZZER_PIN, 0);
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    return EXIT_SUCCESS;
}

