/*
 * Timed watering system for Raspberry Pi 3 Model B+
 *
 * Controls a Parker Hannifin Series 9 General Purpose Miniature Solenoid
 * Valve (12 V, 1.6 W) via an external N-channel MOSFET or relay module
 * connected to GPIO18 (BCM).
 *
 * Wiring:
 *   Valve IN  -> MOSFET gate (or relay IN)
 *   Valve VCC -> 12 V supply
 *   Valve GND -> GND
 *   MOSFET gate -> GPIO18 (BCM)
 *   MOSFET VCC -> 3.3 V (or gate drive voltage)
 *   MOSFET GND -> GND
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o watering watering.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define CONFIG_FILE      "watering.conf"
#define GPIO_CHIP_NAME   "gpiochip0"
#define GPIO_LINE_OFFSET 18          /* BCM 18 */
#define MIN_DURATION     1           /* seconds */
#define MAX_DURATION     3600        /* seconds */

static volatile sig_atomic_t g_interrupted = 0;

/* ------------------------------------------------------------------ */
/* Signal handling                                                     */
/* ------------------------------------------------------------------ */
static void signal_handler(int signum)
{
    (void)signum;
    g_interrupted = 1;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

/* ------------------------------------------------------------------ */
/* Configuration                                                       */
/* ------------------------------------------------------------------ */
static int read_configuration(const char *filename, int *duration)
{
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error: cannot open config file '%s': %s\n",
                filename, strerror(errno));
        return -1;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        if (feof(fp)) {
            fprintf(stderr, "Error: config file '%s' is empty\n", filename);
        } else {
            fprintf(stderr, "Error: reading config file '%s': %s\n",
                    filename, strerror(errno));
        }
        fclose(fp);
        return -1;
    }

    fclose(fp);

    /* Strip trailing newline / carriage return */
    line[strcspn(line, "\r\n")] = '\0';

    /* Parse: duration=<seconds> */
    char *key = strtok(line, "=");
    char *value = strtok(NULL, "=");

    if (key == NULL || value == NULL) {
        fprintf(stderr, "Error: malformed config line (expected 'key=value'): '%s'\n",
                line);
        return -1;
    }

    if (strcmp(key, "duration") != 0) {
        fprintf(stderr, "Error: unknown config key '%s' (expected 'duration')\n", key);
        return -1;
    }

    char *endptr = NULL;
    errno = 0;
    long dur = strtol(value, &endptr, 10);
    if (errno != 0 || endptr == value || *endptr != '\0') {
        fprintf(stderr, "Error: invalid duration value '%s' (must be an integer)\n",
                value);
        return -1;
    }

    if (dur < MIN_DURATION || dur > MAX_DURATION) {
        fprintf(stderr, "Error: duration %ld out of range [%d, %d] seconds\n",
                dur, MIN_DURATION, MAX_DURATION);
        return -1;
    }

    *duration = (int)dur;
    return 0;
}

/* ------------------------------------------------------------------ */
/* GPIO helpers                                                        */
/* ------------------------------------------------------------------ */
static int set_valve(struct gpiod_line *line, int on)
{
    int ret = gpiod_line_set_value(line, on ? 1 : 0);
    if (ret < 0) {
        fprintf(stderr, "Error: gpiod_line_set_value(%d) failed: %s\n",
                on ? 1 : 0, strerror(errno));
        return -1;
    }
    printf("Valve %s\n", on ? "ON" : "OFF");
    fflush(stdout);
    return 0;
}

/*
 * Interruptible sleep that wakes early if a signal arrives.
 * Returns 0 on full completion, -1 if interrupted.
 */
static int interruptible_sleep(unsigned int seconds)
{
    unsigned int remaining = seconds;
    while (remaining > 0 && !g_interrupted) {
        remaining = sleep(remaining);
    }
    return g_interrupted ? -1 : 0;
}

/* ------------------------------------------------------------------ */
/* Main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    int duration = 0;
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    if (read_configuration(CONFIG_FILE, &duration) != 0) {
        return EXIT_FAILURE;
    }

    printf("Watering duration: %d seconds\n", duration);
    fflush(stdout);

    chip = gpiod_chip_open_by_name(GPIO_CHIP_NAME);
    if (chip == NULL) {
        fprintf(stderr, "Error: gpiod_chip_open_by_name('%s') failed: %s\n",
                GPIO_CHIP_NAME, strerror(errno));
        return EXIT_FAILURE;
    }

    line = gpiod_chip_get_line(chip, GPIO_LINE_OFFSET);
    if (line == NULL) {
        fprintf(stderr, "Error: gpiod_chip_get_line(%d) failed: %s\n",
                GPIO_LINE_OFFSET, strerror(errno));
        goto cleanup;
    }

    if (gpiod_line_request_output(line, "watering-system", 0) < 0) {
        fprintf(stderr, "Error: gpiod_line_request_output failed: %s\n",
                strerror(errno));
        goto cleanup;
    }

    /* Ensure valve starts OFF */
    if (set_valve(line, 0) != 0) {
        goto cleanup;
    }

    printf("Watering started...\n");
    fflush(stdout);

    if (interruptible_sleep((unsigned int)duration) != 0) {
        printf("Watering interrupted by signal.\n");
        fflush(stdout);
    }

    if (set_valve(line, 0) != 0) {
        goto cleanup;
    }

    printf("Watering complete.\n");
    fflush(stdout);
    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure valve is left OFF on every exit path */
    if (line != NULL) {
        gpiod_line_set_value(line, 0);
        gpiod_line_release(line);
    }
    if (chip != NULL) {
        gpiod_chip_close(chip);
    }
    return ret;
}

