#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

/* Sensor GPIO pins (BCM numbering) */
#define SENSOR_LEFT   4
#define SENSOR_MIDDLE 17
#define SENSOR_RIGHT  27

/* Motor PWM pins (BCM numbering) */
#define MOTOR_LEFT_FORWARD  22
#define MOTOR_LEFT_BACKWARD 23
#define MOTOR_RIGHT_FORWARD 24
#define MOTOR_RIGHT_BACKWARD 25

/* PWM frequency (Hz) */
#define PWM_FREQUENCY 1000

/* Base speed (0-255) */
#define BASE_SPEED 150

/* Sampling interval (microseconds) */
#define SAMPLE_INTERVAL_US 10000

/* Global flag for graceful shutdown */
static volatile sig_atomic_t running = 1;

/* Log file pointer */
static FILE *log_file = NULL;

/* Function prototypes */
static int initialize_gpio(void);
static int read_sensors(int *left, int *middle, int *right);
