#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

#define I2C_BUS        1
#define BH1750_ADDR    0x23
#define RELAY_GPIO     23
#define LUX_THRESHOLD  150.0f
#define LOG_FILE       "grow_log.txt"
#define MEASURE_DELAY  180000  /* microseconds (180 ms) */
#define POLL_DELAY     500000  /* microseconds (500 ms) */

static volatile sig_atomic_t g_running = 1;
static int g_i2c_handle = -1;

/* ------------------------------------------------------------------ */
/* Signal handler                                                      */
/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
/* Millisecond-precision timestamp                                    */
/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    struct timespec ts;
    struct tm tm_info;

    if (clock_gettime(CLOCK_REALTIME, &ts) != 0) {
        snprintf(buf, len, "TIMESTAMP_ERROR");
        return;
    }

    localtime_r(&ts.tv_sec, &tm_info);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tm_info);
    size_t used = strlen(buf);
    snprintf(buf + used, len - used, ".%03ld", ts.tv_nsec / 1000000);
}

/* ------------------------------------------------------------------ */
/* Log a message to the log file                                       */
/* ------------------------------------------------------------------ */
static void log_message(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp) {
        fprintf(fp, "%s %s\n", ts, msg);
        fclose(fp);
    } else {
        perror("fopen(log)");
    }
}

/* ------------------------------------------------------------------ */
/* Read illuminance from BH1750                                        */
/* Returns 0 on success (stores lux in *out), -1 on error.             */
/* ------------------------------------------------------------------ */
static int read_bh1750(float *out)
{
    uint8_t buf[2];
    ssize_t n;

    /* Send one-byte command: 0x10 = continuous high-resolution mode */
    if (i2cWriteByte(g_i2c_handle, 0x10) < 0) {
        log_message("BH1750: failed to send measurement command");
        return -1;
    }

    /* Wait for conversion to complete (180 ms max) */
    gpioDelay(MEASURE_DELAY);

    /* Read 2 bytes of raw data */
    n = i2cReadDevice(g_i2c_handle, (char *)buf, 2);
    if (n != 2) {
        log_message("BH1750: failed to read 2 bytes from sensor");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *out = (float)raw / 1.2f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Control the relay                                                   */
/* ------------------------------------------------------------------ */
static void control_relay(int on)
{
    if (gpioWrite(RELAY_GPIO, on ? 1 : 0) < 0) {
        log_message("GPIO: failed to write relay state");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- relay GPIO setup ------------------------------------------- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    /* --- I2C open --------------------------------------------------- */
    char i2c_dev[32];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);

    g_i2c_handle = i2cOpen(i2c_dev, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device %s at addr 0x%02X\n",
                i2c_dev, BH1750_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Grow lamp controller started.  I2C bus %d, sensor 0x%02X, relay GPIO%d.\n",
           I2C_BUS, BH1750_ADDR, RELAY_GPIO);
    printf("Threshold: %.1f lux.  Press Ctrl+C to exit.\n", LUX_THRESHOLD);

    int relay_state = 0;

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        float lux;

        if (read_bh1750(&lux) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Lux: %.2f", lux);
            log_message(msg);

            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(1);
                relay_state = 1;
                log_message("Relay ON");
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(0);
                relay_state = 0;
                log_message("Relay OFF");
            }
        } else {
            log_message("Sensor read error; continuing");
        }

        gpioDelay(POLL_DELAY);
    }

    /* --- graceful shutdown ------------------------------------------ */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

