    if (i2cWriteByte(g_i2c_handle, 0x10) < 0) {
        log_message("BH1750: failed to send measurement command");
        return -1;
    }

    /* Wait for conversion to complete (180 ms max) */
    gpioDelay(MEASURE_DELAY);

    /* Read 2 bytes of raw data */
    n = i2cReadDevice(g_i2c_handle, (char *)buf, 2);
    if (n != 2) {
        log_message("BH1750: failed to read 2 bytes from sensor");
        return -1;
    }

    uint16_t raw = ((uint16_t)buf[0] << 8) | buf[1];
    *out = (float)raw / 1.2f;
    return 0;
}

/* ------------------------------------------------------------------ */
/* Control the relay                                                   */
/* ------------------------------------------------------------------ */
static void control_relay(int on)
{
    if (gpioWrite(RELAY_GPIO, on ? 1 : 0) < 0) {
        log_message("GPIO: failed to write relay state");
    }
}

/* ------------------------------------------------------------------ */
/* Cleanup helper                                                      */
/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_i2c_handle >= 0) {
        i2cClose(g_i2c_handle);
        g_i2c_handle = -1;
    }
    gpioWrite(RELAY_GPIO, 0);
    gpioTerminate();
}

/* ------------------------------------------------------------------ */
/* main                                                                */
/* ------------------------------------------------------------------ */
int main(void)
{
    /* --- pigpio init ------------------------------------------------ */
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return EXIT_FAILURE;
    }

    /* --- relay GPIO setup ------------------------------------------- */
    if (gpioSetMode(RELAY_GPIO, PI_OUTPUT) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", RELAY_GPIO);
        gpioTerminate();
        return EXIT_FAILURE;
    }
    gpioWrite(RELAY_GPIO, 0);

    /* --- I2C open --------------------------------------------------- */
    char i2c_dev[32];
    snprintf(i2c_dev, sizeof(i2c_dev), "/dev/i2c-%d", I2C_BUS);

    g_i2c_handle = i2cOpen(i2c_dev, BH1750_ADDR, 0);
    if (g_i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device %s at addr 0x%02X\n",
                i2c_dev, BH1750_ADDR);
        gpioTerminate();
        return EXIT_FAILURE;
    }

    /* --- signal handling -------------------------------------------- */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
        cleanup();
        return EXIT_FAILURE;
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Grow lamp controller started.  I2C bus %d, sensor 0x%02X, relay GPIO%d.\n",
           I2C_BUS, BH1750_ADDR, RELAY_GPIO);
    printf("Threshold: %.1f lux.  Press Ctrl+C to exit.\n", LUX_THRESHOLD);

    int relay_state = 0;

    /* --- main loop -------------------------------------------------- */
    while (g_running) {
        float lux;

        if (read_bh1750(&lux) == 0) {
            char msg[128];
            snprintf(msg, sizeof(msg), "Lux: %.2f", lux);
            log_message(msg);

            if (lux < LUX_THRESHOLD && relay_state == 0) {
                control_relay(1);
                relay_state = 1;
                log_message("Relay ON");
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                control_relay(0);
                relay_state = 0;
                log_message("Relay OFF");
            }
        } else {
            log_message("Sensor read error; continuing");
        }

        gpioDelay(POLL_DELAY);
    }

    /* --- graceful shutdown ------------------------------------------ */
    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

