/*
 * Haptic feedback system for Raspberry Pi 4 Model B
 * Pulses two Precision Microdrives 310-101 vibration motors sequentially.
 *
 * Wiring (external driver circuit recommended):
 *   Motor 1 driver -> GPIO17 (BCM)
 *   Motor 2 driver -> GPIO27 (BCM)
 *   Motor 1 driver VCC -> 3.3 V (or external 5 V supply)
 *   Motor 2 driver VCC -> 3.3 V (or external 5 V supply)
 *   Motor 1 driver GND -> GND
 *   Motor 2 driver GND -> GND
 *   Motor 1 driver IN  -> GPIO17
 *   Motor 2 driver IN  -> GPIO27
 *
 * The Precision Microdrives 310-101 require 3 V at 60 mA typical.
 * An external driver circuit (e.g., NPN transistor + flyback diode)
 * is required to safely drive the motors from the GPIO pins.
 *
 * Build: gcc -Wall -Wextra -O2 -o haptic_feedback haptic_feedback.c -lgpiod
 */

#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <gpiod.h>

#define MOTOR1_PIN 17
#define MOTOR2_PIN 27
#define MOTOR1_PULSE_MS 200
#define MOTOR2_PULSE_MS 300
#define CONSUMER "haptic_feedback"

static volatile sig_atomic_t g_running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static int install_signal_handlers(void)
{
    struct sigaction sa;
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) == -1) {
        perror("sigaction(SIGINT)");
        return -1;
    }
    if (sigaction(SIGTERM, &sa, NULL) == -1) {
        perror("sigaction(SIGTERM)");
        return -1;
    }
    return 0;
}

static int pulse_motor(struct gpiod_line *line, int duration_ms)
{
    if (gpiod_line_set_value(line, 1) < 0) {
        perror("gpiod_line_set_value(1)");
        return -1;
    }
    usleep(duration_ms * 1000);
    if (gpiod_line_set_value(line, 0) < 0) {
        perror("gpiod_line_set_value(0)");
        return -1;
    }
    return 0;
}

int main(void)
{
    struct gpiod_chip *chip = NULL;
    struct gpiod_line *motor1_line = NULL;
    struct gpiod_line *motor2_line = NULL;
    int ret = EXIT_FAILURE;

    if (install_signal_handlers() != 0) {
        return EXIT_FAILURE;
    }

    chip = gpiod_chip_open_by_name("gpiochip4");
    if (!chip) {
        perror("gpiod_chip_open_by_name(\"gpiochip4\")");
        return EXIT_FAILURE;
    }

    motor1_line = gpiod_chip_get_line(chip, MOTOR1_PIN);
    if (!motor1_line) {
        perror("gpiod_chip_get_line(MOTOR1_PIN)");
        goto cleanup;
    }

    motor2_line = gpiod_chip_get_line(chip, MOTOR2_PIN);
    if (!motor2_line) {
        perror("gpiod_chip_get_line(MOTOR2_PIN)");
        goto cleanup;
    }

    if (gpiod_line_request_output(motor1_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(motor1_line)");
        goto cleanup;
    }

    if (gpiod_line_request_output(motor2_line, CONSUMER, 0) < 0) {
        perror("gpiod_line_request_output(motor2_line)");
        goto cleanup;
    }

    printf("Haptic feedback system started. Press Ctrl+C to exit.\n");

    while (g_running) {
        if (pulse_motor(motor1_line, MOTOR1_PULSE_MS) < 0) {
            goto cleanup;
        }
        if (!g_running) {
            break;
        }
        if (pulse_motor(motor2_line, MOTOR2_PULSE_MS) < 0) {
            goto cleanup;
        }
    }

    ret = EXIT_SUCCESS;

cleanup:
    /* Ensure motors are stopped before releasing lines */
    if (motor1_line) {
        gpiod_line_set_value(motor1_line, 0);
        gpiod_line_release(motor1_line);
    }
    if (motor2_line) {
        gpiod_line_set_value(motor2_line, 0);
        gpiod_line_release(motor2_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }

    if (ret == EXIT_SUCCESS) {
        printf("\nHaptic feedback system stopped.\n");
    }
    return ret;
}

