/*
 * sound_alarm.c — Raspberry Pi 5 sound-triggered alarm
 *
 * Build:  gcc -O2 -Wall -Wextra -o sound_alarm sound_alarm.c -lzmq -lrt
 *
 * Usage:  ./sound_alarm sound_sensor   (polls LM393 on GPIO17, publishes to 5555)
 *         ./sound_alarm alarm_node     (subscribes to 5555, lights LED on GPIO27)
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <fcntl.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <zmq.h>

#define GPIO_CHIP_NAME  "/dev/gpiochip0"
#define GPIO_SOUND_PIN  17
#define GPIO_ALARM_PIN  27
#define ZMQ_PORT        5555
#define POLL_INTERVAL_US 10000   /* 10 ms */
#define ALARM_DURATION_S  1

/* ---- GPIO memory-map helpers (BCM numbering) ---- */

typedef struct {
    volatile unsigned int *reg;
    unsigned int offset;
} gpio_reg_t;

static volatile unsigned int *gpio_map = NULL;
static int gpio_fd = -1;

static void gpio_unmap(void)
{
    if (gpio_map && gpio_fd >= 0) {
        munmap((void *)gpio_map, 4096);
        gpio_map = NULL;
        close(gpio_fd);
        gpio_fd = -1;
    }
}

static int gpio_setup_output(unsigned int pin)
{
    /* Write 1 to the pin to ensure it starts HIGH (alarm off) */
    if (gpio_write(pin, 1) < 0)
        return -1;

    /* Set pin as output */
    if (gpio_set_mode(pin, 1) < 0)
        return -1;

    return 0;
}

static int gpio_setup_input(unsigned int pin)
{
    /* Set pin as input */
    if (gpio_set_mode(pin, 0) < 0)
        return -1;

    return 0;
}

static int gpio_set_mode(unsigned int pin, int output)
{
    gpio_reg_t reg;
    unsigned int val;

    reg.reg = gpio_map + (pin / 10);
    reg.offset = (pin % 10) * 3;

    val = *(reg.reg + reg.offset / 32);
    if (output)
        val |= (1u << (reg.offset % 32));
    else
        val &= ~(1u << (reg.offset % 32));
    *(reg.reg + reg.offset / 32) = val;

    return 0;
}

static int gpio_write(unsigned int pin, int value)
{
    gpio_reg_t reg;
    unsigned int val;

    reg.reg = gpio_map + (pin / 10 + 7);   /* ODATA reg for pin */
    reg.offset = (pin % 10) * 3;

    val = *(reg.reg + reg.offset / 32);
    if (value)
        val |= (1u << (reg.offset % 32));
    else
        val &= ~(1u << (reg.offset % 32));
    *(reg.reg + reg.offset / 32) = val;

    return 0;
}

static int gpio_read(unsigned int pin)
{
    gpio_reg_t reg;
    unsigned int val;

    reg.reg = gpio_map + (pin / 10 + 14);  /* IDATA reg for pin */
    reg.offset = (pin % 10) * 3;

    val = *(reg.reg + reg.offset / 32);
    return (val >> (reg.offset % 32)) & 1;
}

static int gpio_init(void)
{
    int fd;
    struct stat st;

    fd = open(GPIO_CHIP_NAME, O_RDWR | O_SYNC);
    if (fd < 0) {
        perror("open(" GPIO_CHIP_NAME ")");
        return -1;
    }

    if (fstat(fd, &st) < 0) {
        perror("fstat");
        close(fd);
        return -1;
    }

    if (st.st_size < 4096) {
        fprintf(stderr, "GPIO chip too small (%ld bytes)\n", st.st_size);
        close(fd);
        return -1;
    }

    gpio_map = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_SHARED, fd, 0);
    if (gpio_map == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return -1;
    }

    gpio_fd = fd;
    return 0;
}

/* ---- ZeroMQ helpers ---- */

static void *zmq_ctx = NULL;
static void *zmq_sock = NULL;

static int zmq_init(void)
{
    zmq_ctx = zmq_ctx_new();
    if (!zmq_ctx) {
        perror("zmq_ctx_new");
        return -1;
    }
    return 0;
}

