{
    zmq_sock = zmq_socket(zmq_ctx, ZMQ_PUB);
    if (!zmq_sock) {
        perror("zmq_socket(PUB)");
        return -1;
    }

    if (zmq_bind(zmq_sock, "tcp://*:5555") != 0) {
        perror("zmq_bind");
        zmq_close(zmq_sock);
        zmq_sock = NULL;
        return -1;
    }
    return 0;
}

static int zmq_connect(void)
{
    zmq_sock = zmq_socket(zmq_ctx, ZMQ_SUB);
    if (!zmq_sock) {
        perror("zmq_socket(SUB)");
        return -1;
    }

    if (zmq_setsockopt(zmq_sock, ZMQ_SUBSCRIBE, "SOUND_ALERTS", 12) != 0) {
        perror("zmq_setsockopt(SUBSCRIBE)");
        zmq_close(zmq_sock);
        zmq_sock = NULL;
        return -1;
    }

    if (zmq_connect(zmq_sock, "tcp://localhost:5555") != 0) {
        perror("zmq_connect");
        zmq_close(zmq_sock);
        zmq_sock = NULL;
        return -1;
    }
    return 0;
}

static void zmq_send_alert(void)
{
    char msg[64];
    int n;

    n = snprintf(msg, sizeof(msg), "SOUND_ALERTS: Sound detected on GPIO%d",
                 GPIO_SOUND_PIN);
    if (n < 0 || (size_t)n >= sizeof(msg)) {
        fprintf(stderr, "Message truncated\n");
        return;
    }

    if (zmq_send(zmq_sock, msg, n, 0) < 0)
        perror("zmq_send");
}

static void zmq_receive_alert(void)
{
    char buf[256];
    zmq_msg_t msg;

    if (zmq_msg_init(&msg) != 0) {
        perror("zmq_msg_init");
        return;
    }

    if (zmq_msg_recv(&msg, zmq_sock, 0) < 0) {
        if (zmq_errno() == ETERM)
            fprintf(stderr, "zmq_msg_recv interrupted\n");
        else
            perror("zmq_msg_recv");
        zmq_msg_close(&msg);
        return;
    }

    if (zmq_msg_size(&msg) > 0) {
        memcpy(buf, zmq_msg_data(&msg), zmq_msg_size(&msg));
        buf[zmq_msg_size(&msg)] = '\0';
        printf("Received: %s\n", buf);
    }

    zmq_msg_close(&msg);
}

