static volatile sig_atomic_t running = 1;

static void signal_handler(int sig)
{
    (void)sig;
    running = 0;
}

/* ---- Cleanup ---- */

static void cleanup(void)
{
    if (zmq_sock) {
        zmq_close(zmq_sock);
        zmq_sock = NULL;
    }
    if (zmq_ctx) {
        zmq_ctx_destroy(zmq_ctx);
        zmq_ctx = NULL;
    }
    gpio_unmap();
}

/* ---- Modes ---- */

static void sound_sensor_mode(void)
{
    if (gpio_setup_input(GPIO_SOUND_PIN) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", GPIO_SOUND_PIN);
        return;
    }

    if (zmq_bind() < 0)
        return;

    printf("Sound sensor mode: polling LM393 on GPIO%d every %d ms\n",
           GPIO_SOUND_PIN, POLL_INTERVAL_US / 1000);

    while (running) {
        int val = gpio_read(GPIO_SOUND_PIN);
        if (val < 0) {
            fprintf(stderr, "GPIO read error on pin %d\n", GPIO_SOUND_PIN);
            break;
        }

        /* LM393 digital output is active-low: 0 => sound detected */
        if (val == 0) {
            printf("Sound detected!\n");
            zmq_send_alert();
        }

        usleep(POLL_INTERVAL_US);
    }
}

static void alarm_node_mode(void)
{
    if (gpio_setup_output(GPIO_ALARM_PIN) < 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", GPIO_ALARM_PIN);
        return;
    }

    if (zmq_connect() < 0)
        return;

    printf("Alarm node mode: subscribed to tcp://localhost:%d\n", ZMQ_PORT);

    while (running) {
