static int gpio_setup_output(unsigned int pin)
{
    /* Write 1 to the pin to ensure it starts HIGH (alarm off) */
    if (gpio_write(pin, 1) < 0)
        return -1;

    /* Set pin as output */
    if (gpio_set_mode(pin, 1) < 0)
        return -1;

    return 0;
}

static int gpio_setup_input(unsigned int pin)
{
    /* Set pin as input */
    if (gpio_set_mode(pin, 0) < 0)
        return -1;

    return 0;
}

static int gpio_set_mode(unsigned int pin, int output)
{
    gpio_reg_t reg;
    unsigned int val;

    reg.reg = gpio_map + (pin / 10);
    reg.offset = (pin % 10) * 3;

    val = *(reg.reg + reg.offset / 32);
    if (output)
        val |= (1u << (reg.offset % 32));
    else
        val &= ~(1u << (reg.offset % 32));
    *(reg.reg + reg.offset / 32) = val;

    return 0;
}

static int gpio_write(unsigned int pin, int value)
{
    gpio_reg_t reg;
    unsigned int val;

    reg.reg = gpio_map + (pin / 10 + 7);   /* ODATA reg for pin */
    reg.offset = (pin % 10) * 3;

    val = *(reg.reg + reg.offset / 32);
    if (value)
        val |= (1u << (reg.offset % 32));
    else
        val &= ~(1u << (reg.offset % 32));
    *(reg.reg + reg.offset / 32) = val;

    return 0;
}

static int gpio_read(unsigned int pin)
{
    gpio_reg_t reg;
    unsigned int val;

    reg.reg = gpio_map + (pin / 10 + 14);  /* IDATA reg for pin */
    reg.offset = (pin % 10) * 3;

    val = *(reg.reg + reg.offset / 32);
