#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <errno.h>
#include <time.h>
#include <pigpio.h>
#include <mosquitto.h>

#define IR_GPIO 17
#define MQTT_HOST "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define MAX_PULSES 100
#define NEC_HDR_MARK 9000
#define NEC_HDR_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560
#define NEC_TOLERANCE 200

static volatile sig_atomic_t running = 1;
static struct mosquitto *mosq = NULL;
static int pulse_count = 0;
static uint32_t pulses[MAX_PULSES];

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static void ir_callback(int gpio, int level, uint32_t tick, void *userdata) {
    (void)gpio;
    (void)userdata;
    if (level == 0) {
        if (pulse_count < MAX_PULSES) {
            pulses[pulse_count++] = tick;
        } else {
            syslog(LOG_ERR, "Pulse buffer overflow, resetting");
            pulse_count = 0;
        }
    }
}

static int in_range(uint32_t val, uint32_t target, uint32_t tol) {
    return (val >= target - tol) && (val <= target + tol);
}

static int decode_nec(uint32_t *command) {
    if (pulse_count < 68) return -1;

    if (!in_range(pulses[0], NEC_HDR_MARK, NEC_TOLERANCE) ||
        !in_range(pulses[1], NEC_HDR_SPACE, NEC_TOLERANCE)) {
        return -1;
    }

    uint32_t addr = 0, addr_inv = 0, cmd = 0, cmd_inv = 0;

    for (int i = 0; i < 32; i++) {
        int idx = 2 + (i * 2);
        if (idx + 1 >= pulse_count) return -1;
        if (!in_range(pulses[idx], NEC_BIT_MARK, NEC_TOLERANCE)) return -1;
        if (in_range(pulses[idx + 1], NEC_ONE_SPACE, NEC_TOLERANCE)) {
            if (i < 16) addr |= (1 << i);
            else addr_inv |= (1 << (i - 16));
        } else if (in_range(pulses[idx + 1], NEC_ZERO_SPACE, NEC_TOLERANCE)) {
            if (i < 16) cmd |= (1 << i);
            else cmd_inv |= (1 << (i - 16));
        } else {
            return -1;
        }
    }

    if ((uint8_t)(addr ^ addr_inv) != 0) return -1;
    if ((uint8_t)(cmd ^ cmd_inv) != 0) return -1;

    *command = cmd;
    return 0;
}

static void publish_mqtt(uint32_t command) {
    char payload[64];
    snprintf(payload, sizeof(payload), "{\"command\": %u}", command);
    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC,
                               (int)strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT publish failed: %s", mosquitto_strerror(rc));
    } else {
        syslog(LOG_INFO, "Published to MQTT: %s", payload);
    }
}

int main(void) {
    openlog("ir_decoder", LOG_PID | LOG_CONS, LOG_USER);

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set signal handlers: %s", strerror(errno));
        closelog();
        return 1;
    }

    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialization failed");
        closelog();
        return 1;
    }

    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP);

    if (gpioSetAlertFuncEx(IR_GPIO, ir_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set alert function on GPIO %d", IR_GPIO);
        gpioTerminate();
        closelog();
        return 1;
    }

    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "MQTT client creation failed");
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    int rc = mosquitto_connect(mosq, MQTT_HOST, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT connect failed: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosq = NULL;
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    rc = mosquitto_loop_start(mosq);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "MQTT loop start failed: %s", mosquitto_strerror(rc));
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
        mosq = NULL;
        gpioTerminate();
        mosquitto_lib_cleanup();
        closelog();
        return 1;
    }

    syslog(LOG_INFO, "IR decoder started on GPIO %d, MQTT %s:%d", IR_GPIO, MQTT_HOST, MQTT_PORT);

    while (running) {
        if (pulse_count >= 68) {
            uint32_t command;
            if (decode_nec(&command) == 0) {
                syslog(LOG_INFO, "Decoded NEC command: %u", command);
                publish_mqtt(command);
                pulse_count = 0;
            } else {
                syslog(LOG_WARNING, "NEC decode failed, resetting");
                pulse_count = 0;
            }
        }
        gpioDelay(10000);
    }

    syslog(LOG_INFO, "Shutting down...");
    gpioSetAlertFuncEx(IR_GPIO, NULL, NULL);
    gpioTerminate();

    if (mosq) {
        mosquitto_loop_stop(mosq, false);
        mosquitto_disconnect(mosq);
        mosquitto_destroy(mosq);
    }
    mosquitto_lib_cleanup();
    closelog();
    return 0;
}

