#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <math.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define NUM_SENSORS    4
#define BH1750_ADDR    0x23
#define BH1750_PWR_ON  0x01
#define BH1750_RESET   0x07
#define BH1750_CONT_H  0x10  /* continuous high-resolution mode */
#define CONV_TIME_MS   180
#define LOOP_DELAY_MS  1000
#define MCAST_ADDR     "239.255.255.250"
#define MCAST_PORT     5005
#define MAX_PAYLOAD    256

static volatile sig_atomic_t terminate = 0;

static void signal_handler(int sig)
{
    (void)sig;
    terminate = 1;
}

static int i2c_write_byte(int fd, unsigned char cmd)
{
    if (write(fd, &cmd, 1) != 1) {
        fprintf(stderr, "I2C write failed: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

static int i2c_read_word(int fd, unsigned short *out)
{
    unsigned char buf[2];
    ssize_t n = read(fd, buf, 2);
    if (n != 2) {
        fprintf(stderr, "I2C read failed (got %zd bytes): %s\n", n, strerror(errno));
        return -1;
    }
    *out = (unsigned short)((buf[0] << 8) | buf[1]);
    return 0;
}

static int bh1750_read_lux(int fd, float *lux_out)
{
    if (i2c_write_byte(fd, BH1750_RESET) < 0)
        return -1;
    if (i2c_write_byte(fd, BH1750_PWR_ON) < 0)
        return -1;
    if (i2c_write_byte(fd, BH1750_CONT_H) < 0)
        return -1;

    usleep(CONV_TIME_MS * 1000);

    unsigned short raw;
    if (i2c_read_word(fd, &raw) < 0)
        return -1;

    *lux_out = (float)raw / 1.2f;
    return 0;
}

static int send_udp_multicast(float lux_values[NUM_SENSORS])
{
    int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sockfd < 0) {
        perror("socket");
        return -1;
    }

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MCAST_ADDR);
    addr.sin_port = htons(MCAST_PORT);

    char payload[MAX_PAYLOAD];
    int len = 0;
    for (int i = 0; i < NUM_SENSORS; i++) {
        int n = snprintf(payload + len, MAX_PAYLOAD - len, "%d,%.1f", i + 1, lux_values[i]);
        if (n < 0 || n >= MAX_PAYLOAD - len) {
            fprintf(stderr, "Payload buffer overflow\n");
            close(sockfd);
            return -1;
        }
        len += n;
        if (i < NUM_SENSORS - 1) {
            if (len + 1 >= MAX_PAYLOAD) {
                fprintf(stderr, "Payload buffer overflow\n");
                close(sockfd);
                return -1;
            }
            payload[len++] = ';';
        }
    }

    if (sendto(sockfd, payload, len, 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("sendto");
        close(sockfd);
        return -1;
    }

    close(sockfd);
    return 0;
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0 || sigaction(SIGTERM, &sa, NULL) < 0) {
        perror("sigaction");
        return EXIT_FAILURE;
    }

    int i2c_fds[NUM_SENSORS];
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_fds[i] = open(I2C_BUS, O_RDWR);
        if (i2c_fds[i] < 0) {
            fprintf(stderr, "Failed to open %s: %s\n", I2C_BUS, strerror(errno));
            for (int j = 0; j < i; j++)
                close(i2c_fds[j]);
            return EXIT_FAILURE;
        }
        if (ioctl(i2c_fds[i], I2C_SLAVE, BH1750_ADDR) < 0) {
            fprintf(stderr, "Failed to set I2C slave 0x%02X: %s\n", BH1750_ADDR, strerror(errno));
            close(i2c_fds[i]);
            for (int j = 0; j < i; j++)
                close(i2c_fds[j]);
            return EXIT_FAILURE;
        }
    }

    while (!terminate) {
        float lux_values[NUM_SENSORS];
        for (int i = 0; i < NUM_SENSORS; i++) {
            if (bh1750_read_lux(i2c_fds[i], &lux_values[i]) < 0) {
                fprintf(stderr, "Sensor %d read failed; inserting NaN\n", i + 1);
                lux_values[i] = NAN;
            }
        }

        if (send_udp_multicast(lux_values) < 0)
            fprintf(stderr, "UDP multicast send failed\n");

        usleep(LOOP_DELAY_MS * 1000);
    }

    for (int i = 0; i < NUM_SENSORS; i++)
        close(i2c_fds[i]);

    return EXIT_SUCCESS;
}

