#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <signal.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define I2C_BUS        "/dev/i2c-1"
#define AWM7300V_ADDR  0x28
#define LOG_FILE       "airflow_log.txt"
#define MAX_RETRIES    3
#define RETRY_DELAY_MS 100
#define SAMPLE_PERIOD  1

static volatile sig_atomic_t g_running = 1;
static int  g_i2c_fd = -1;
static FILE *g_log_fp = NULL;

static void sigint_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

static void cleanup(void)
{
    if (g_log_fp != NULL) {
        fflush(g_log_fp);
        fclose(g_log_fp);
        g_log_fp = NULL;
    }
    if (g_i2c_fd >= 0) {
        close(g_i2c_fd);
        g_i2c_fd = -1;
    }
}

static int i2c_open(const char *bus, uint8_t addr)
{
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "open(%s) failed: %s\n", bus, strerror(errno));
        return -1;
    }
    if (ioctl(fd, I2C_SLAVE, addr) < 0) {
        fprintf(stderr, "ioctl(I2C_SLAVE, 0x%02X) failed: %s\n",
                addr, strerror(errno));
        close(fd);
        return -1;
    }
    return fd;
}

static int read_flow_rate(int fd, float *out_slpm)
{
    uint8_t buf[2];
    ssize_t n;
    int attempt;

    for (attempt = 0; attempt < MAX_RETRIES; attempt++) {
        /*
         * A zero-length write generates a start condition on the bus,
         * then a repeated-start (no stop) so the sensor can clock out
         * its 14-bit flow data.  We then read two bytes.
         */
        n = write(fd, buf, 0);
        if (n < 0) {
            if (errno == EIO) {
                fprintf(stderr, "I2C bus error (attempt %d/%d): %s\n",
                        attempt + 1, MAX_RETRIES, strerror(errno));
            } else {
                fprintf(stderr, "I2C write error (attempt %d/%d): %s\n",
                        attempt + 1, MAX_RETRIES, strerror(errno));
            }
            if (attempt < MAX_RETRIES - 1)
                usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        n = read(fd, buf, 2);
        if (n < 0) {
            if (errno == EIO) {
                fprintf(stderr, "I2C bus error (attempt %d/%d): %s\n",
                        attempt + 1, MAX_RETRIES, strerror(errno));
            } else {
                fprintf(stderr, "I2C read error (attempt %d/%d): %s\n",
                        attempt + 1, MAX_RETRIES, strerror(errno));
            }
            if (attempt < MAX_RETRIES - 1)
                usleep(RETRY_DELAY_MS * 1000);
            continue;
        }
        if (n != 2) {
            fprintf(stderr, "Short read: got %zd of 2 bytes (attempt %d/%d)\n",
                    n, attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1)
                usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        /*
         * AWM7300V flow data: 14-bit signed, two's complement,
         * left-justified in 16 bits.  Mask off the two unused LSBs.
         */
        int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
        raw >>= 2;
        *out_slpm = (float)raw;
        return 0;
    }

    return -1;
}

static void log_flow_rate(FILE *fp, float slpm)
{
    time_t t = time(NULL);
    struct tm tm;
    char ts[32];

    if (localtime_r(&t, &tm) == NULL) {
        fprintf(stderr, "localtime_r failed: %s\n", strerror(errno));
        return;
    }
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);
    fprintf(fp, "%s, %.2f SLPM\n", ts, slpm);
    fflush(fp);
}

int main(void)
{
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        fprintf(stderr, "sigaction(SIGINT) failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_i2c_fd = i2c_open(I2C_BUS, AWM7300V_ADDR);
    if (g_i2c_fd < 0) {
        if (errno == ENXIO)
            fprintf(stderr, "No I2C device at address 0x%02X on %s\n",
                    AWM7300V_ADDR, I2C_BUS);
        else
            fprintf(stderr, "I2C open failed: %s\n", strerror(errno));
        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float slpm;
        if (read_flow_rate(g_i2c_fd, &slpm) == 0) {
            log_flow_rate(g_log_fp, slpm);
            printf("Flow rate: %.2f SLPM\n", slpm);
        } else {
            fprintf(stderr, "Failed to read flow rate after %d retries.\n",
                    MAX_RETRIES);
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

