        if (n != 2) {
            fprintf(stderr, "Short read: got %zd of 2 bytes (attempt %d/%d)\n",
                    n, attempt + 1, MAX_RETRIES);
            if (attempt < MAX_RETRIES - 1)
                usleep(RETRY_DELAY_MS * 1000);
            continue;
        }

        /*
         * AWM7300V flow data: 14-bit signed, two's complement,
         * left-justified in 16 bits.  Mask off the two unused LSBs.
         */
        int16_t raw = (int16_t)((buf[0] << 8) | buf[1]);
        raw >>= 2;
        *out_slpm = (float)raw;
        return 0;
    }

    return -1;
}

static void log_flow_rate(FILE *fp, float slpm)
