        return EXIT_FAILURE;
    }

    g_log_fp = fopen(LOG_FILE, "a");
    if (g_log_fp == NULL) {
        fprintf(stderr, "fopen(%s) failed: %s\n", LOG_FILE, strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    printf("Airflow monitoring started. Press Ctrl+C to exit.\n");

    while (g_running) {
        float slpm;
        if (read_flow_rate(g_i2c_fd, &slpm) == 0) {
            log_flow_rate(g_log_fp, slpm);
            printf("Flow rate: %.2f SLPM\n", slpm);
        } else {
            fprintf(stderr, "Failed to read flow rate after %d retries.\n",
                    MAX_RETRIES);
        }
        sleep(SAMPLE_PERIOD);
    }

    printf("\nExiting gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

