#define AS7341_ENABLE  0x80
#define AS7341_CFG0    0x70
#define AS7341_CFG1    0x71
#define AS7341_CFG2    0x72
#define AS7341_CFG3    0x73
#define AS7341_CFG4    0x74
#define AS7341_CFG5    0x75
#define AS7341_CFG6    0x76
#define AS7341_CFG7    0x77
#define AS7341_CFG8    0x78
#define AS7341_CFG9    0x79
#define AS7341_CFG10   0x7A
#define AS7341_CFG12   0x7C
#define AS7341_ID      0x92
#define AS7341_STATUS  0x93
#define AS7341_A0DATAL 0x94
#define AS7341_A0DATAH 0x95
#define AS7341_A1DATAL 0x96
#define AS7341_A1DATAH 0x97
#define AS7341_A2DATAL 0x98
#define AS7341_A2DATAH 0x99
#define AS7341_A3DATAL 0x9A
#define AS7341_A3DATAH 0x9B
#define AS7341_A4DATAL 0x9C
#define AS7341_A4DATAH 0x9D
#define AS7341_A5DATAL 0x9E
#define AS7341_A5DATAH 0x9F
#define AS7341_A6DATAL 0xA0
#define AS7341_A6DATAH 0xA1
#define AS7341_A7DATAL 0xA2
#define AS7341_A7DATAH 0xA3
#define AS7341_A8DATAL 0xA4
#define AS7341_A8DATAH 0xA5
#define AS7341_A9DATAL 0xA6
#define AS7341_A9DATAH 0xA7
#define AS7341_A10DATAL 0xA8
#define AS7341_A10DATAH 0xA9

#define AS7341_ID_VAL  0x41
#define ENABLE_PON     0x01
#define ENABLE_SP_EN   0x02
#define STATUS_AVALID  0x01

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_log = NULL;

static void sigint_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = { reg, val };
    if (write(fd, buf, 2) != 2) {
        perror("i2c_write_reg8: write");
        return -1;
    }
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg8: write");
        return -1;
    }
    if (read(fd, val, 1) != 1) {
        perror("i2c_read_reg8: read");
        return -1;
    }
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg, uint16_t *val) {
    uint8_t buf[2];
    if (write(fd, &reg, 1) != 1) {
        perror("i2c_read_reg16: write");
        return -1;
    }
    if (read(fd, buf, 2) != 2) {
        perror("i2c_read_reg16: read");
        return -1;
    }
    *val = (uint16_t)buf[0] | ((uint16_t)buf[1] << 8);
    return 0;
}

static int as7341_init(int fd) {
    uint8_t id = 0;
    if (i2c_read_reg8(fd, AS7341_ID, &id) < 0) {
        fprintf(stderr, "Error: cannot read AS7341 ID register.\n");
        return -1;
    }
    if (id != AS7341_ID_VAL) {
        fprintf(stderr, "Error: AS7341 ID mismatch (got 0x%02X, expected 0x%02X).\n",
                id, AS7341_ID_VAL);
        return -1;
    }

    if (i2c_write_reg8(fd, AS7341_ENABLE, ENABLE_PON) < 0) return -1;
    usleep(10000);

    if (i2c_write_reg8(fd, AS7341_CFG0, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_CFG1, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_CFG2, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_CFG3, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_CFG4, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_CFG5, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_CFG6, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_CFG7, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_CFG8, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_CFG9, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_CFG10, 0x00) < 0) return -1;
    if (i2c_write_reg8(fd, AS7341_CFG12, 0x00) < 0) return -1;

    if (i2c_write_reg8(fd, AS7341_ENABLE, ENABLE_PON | ENABLE_SP_EN) < 0) return -1;
    usleep(10000);

    return 0;
}

static int as7341_read_spectral(int fd, uint16_t *ch) {
    uint8_t status = 0;
    int retries = 20;

    while (retries-- > 0) {
        if (i2c_read_reg8(fd, AS7341_STATUS, &status) < 0) return -1;
        if (status & STATUS_AVALID) break;
        usleep(5000);
    }
    if (retries < 0) {
        fprintf(stderr, "Error: AS7341 data not valid.\n");
        return -1;
    }

    if (i2c_read_reg16(fd, AS7341_A0DATAL, &ch[0]) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_A1DATAL, &ch[1]) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_A2DATAL, &ch[2]) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_A3DATAL, &ch[3]) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_A4DATAL, &ch[4]) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_A5DATAL, &ch[5]) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_A6DATAL, &ch[6]) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_A7DATAL, &ch[7]) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_A8DATAL, &ch[8]) < 0) return -1;
    if (i2c_read_reg16(fd, AS7341_A9DATAL, &ch[9]) < 0) return -1;

    return 0;
}

static float calculate_lux(const uint16_t *ch) {
    float f1 = (float)ch[0];
    float f2 = (float)ch[1];
    float f3 = (float)ch[2];
    float f4 = (float)ch[3];
    float f5 = (float)ch[4];
    float f6 = (float)ch[5];
    float f7 = (float)ch[6];
    float f8 = (float)ch[7];
    float clear = (float)ch[8];
    float nir = (float)ch[9];

    float lux = (f1 + f2 + f3 + f4 + f5 + f6 + f7 + f8 + clear + nir) / 10.0f;
    return lux;
}

static void log_data(FILE *fp, const uint16_t *ch, float lux) {
    time_t t = time(NULL);
    struct tm tm;
    localtime_r(&t, &tm);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            ts, ch[0], ch[1], ch[2], ch[3], ch[4], ch[5],
            ch[6], ch[7], ch[8], ch[9], lux);
    fflush(fp);
}

int main(void) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = sigint_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) < 0) {
        perror("sigaction");
        return 1;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        perror("open " I2C_BUS);
        return 1;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, AS7341_ADDR) < 0) {
        perror("ioctl I2C_SLAVE");
        close(g_i2c_fd);
        return 1;
    }

    if (as7341_init(g_i2c_fd) < 0) {
        fprintf(stderr, "AS7341 initialization failed.\n");
        close(g_i2c_fd);
        return 1;
    }

    g_log = fopen(LOG_FILE, "a");
    if (!g_log) {
        perror("fopen " LOG_FILE);
        close(g_i2c_fd);
        return 1;
    }

    fseek(g_log, 0, SEEK_END);
    if (ftell(g_log) == 0) {
        fprintf(g_log, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
        fflush(g_log);
    }

    uint16_t ch[10];
    int consecutive_errors = 0;

    while (g_running) {
        if (as7341_read_spectral(g_i2c_fd, ch) == 0) {
            consecutive_errors = 0;
            float lux = calculate_lux(ch);
            log_data(g_log, ch, lux);
            printf("Lux: %.2f\n", lux);
        } else {
            consecutive_errors++;
            fprintf(stderr, "Read error (%d consecutive).\n", consecutive_errors);
            if (consecutive_errors >= 10) {
                fprintf(stderr, "Too many consecutive errors; aborting.\n");
                break;
            }
        }
        sleep(SAMPLE_PERIOD);
    }

    if (g_log) fclose(g_log);
    if (g_i2c_fd >= 0) close(g_i2c_fd);
    return 0;
}

