#include <fcntl.h>
#include <errno.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

#define D7S_I2C_ADDR_DEFAULT 0x1D
#define D7S_REG_X_LSB        0x08
#define D7S_REG_X_MSB        0x09
#define D7S_REG_Y_LSB        0x0A
#define D7S_REG_Y_MSB        0x0B
#define D7S_REG_Z_LSB        0x0C
#define D7S_REG_Z_MSB        0x0D
#define D7S_REG_PRODUCT_ID   0x0F
#define D7S_PRODUCT_ID_VAL   0x01

#define I2C_BUS "/dev/i2c-1"
#define DEFAULT_FILENAME "seismic_data.csv"
#define DEFAULT_INTERVAL 1
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

static volatile sig_atomic_t g_running = 1;
static int g_i2c_fd = -1;
static FILE *g_csv_fp = NULL;
static FILE *g_err_fp = NULL;
static char g_filename[256] = DEFAULT_FILENAME;
static int g_interval = DEFAULT_INTERVAL;
static int g_i2c_addr = D7S_I2C_ADDR_DEFAULT;

static void signal_handler(int sig) {
    (void)sig;
    g_running = 0;
}

static void log_error(const char *msg) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char ts[32];
    strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
    if (g_err_fp) {
        fprintf(g_err_fp, "%s: %s (errno: %d - %s)\n", ts, msg, errno, strerror(errno));
        fflush(g_err_fp);
    }
    fprintf(stderr, "%s: %s (errno: %d - %s)\n", ts, msg, errno, strerror(errno));
}

static int i2c_write_reg8(int fd, uint8_t reg, uint8_t val) {
    uint8_t buf[2] = {reg, val};
    if (write(fd, buf, 2) != 2) return -1;
    return 0;
}

static int i2c_read_reg8(int fd, uint8_t reg, uint8_t *val) {
    if (write(fd, &reg, 1) != 1) return -1;
    if (read(fd, val, 1) != 1) return -1;
    return 0;
}

static int i2c_read_reg16(int fd, uint8_t reg_lsb, int16_t *out) {
    uint8_t lsb, msb;
    if (i2c_read_reg8(fd, reg_lsb, &lsb) < 0) return -1;
    if (i2c_read_reg8(fd, reg_lsb + 1, &msb) < 0) return -1;
    *out = (int16_t)((msb << 8) | lsb);
    return 0;
}

static int init_sensor(int fd) {
    uint8_t id;
    if (i2c_read_reg8(fd, D7S_REG_PRODUCT_ID, &id) < 0) {
        log_error("Failed to read product ID - sensor may be absent or bus error");
        return -1;
    }
    if (id != D7S_PRODUCT_ID_VAL) {
        fprintf(stderr, "Unexpected product ID: 0x%02X (expected 0x%02X)\n", id, D7S_PRODUCT_ID_VAL);
        return -1;
    }
    return 0;
}

static int read_acceleration(int fd, float *x, float *y, float *z) {
    int16_t raw_x, raw_y, raw_z;
    if (i2c_read_reg16(fd, D7S_REG_X_LSB, &raw_x) < 0) return -1;
    if (i2c_read_reg16(fd, D7S_REG_Y_LSB, &raw_y) < 0) return -1;
    if (i2c_read_reg16(fd, D7S_REG_Z_LSB, &raw_z) < 0) return -1;
    *x = (float)raw_x / 100.0f;
    *y = (float)raw_y / 100.0f;
    *z = (float)raw_z / 100.0f;
    return 0;
}

static void cleanup(void) {
    if (g_csv_fp) { fflush(g_csv_fp); fclose(g_csv_fp); g_csv_fp = NULL; }
    if (g_err_fp) { fflush(g_err_fp); fclose(g_err_fp); g_err_fp = NULL; }
    if (g_i2c_fd >= 0) { close(g_i2c_fd); g_i2c_fd = -1; }
}

int main(int argc, char *argv[]) {
    int opt;
    while ((opt = getopt(argc, argv, "a:i:f:h")) != -1) {
        switch (opt) {
            case 'a': g_i2c_addr = (int)strtol(optarg, NULL, 0); break;
            case 'i': g_interval = atoi(optarg); break;
            case 'f': strncpy(g_filename, optarg, sizeof(g_filename) - 1); g_filename[sizeof(g_filename) - 1] = '\0'; break;
            case 'h':
            default:
                fprintf(stderr, "Usage: %s [-a i2c_addr] [-i interval_s] [-f filename]\n", argv[0]);
                return EXIT_FAILURE;
        }
    }

    g_err_fp = fopen("seismic_error.log", "a");
    if (!g_err_fp) {
        perror("Failed to open error log");
        return EXIT_FAILURE;
    }

    g_i2c_fd = open(I2C_BUS, O_RDWR);
    if (g_i2c_fd < 0) {
        log_error("Failed to open I2C bus");
        cleanup();
        return EXIT_FAILURE;
    }

    if (ioctl(g_i2c_fd, I2C_SLAVE, g_i2c_addr) < 0) {
        log_error("Failed to set I2C slave address");
        cleanup();
        return EXIT_FAILURE;
    }

    if (init_sensor(g_i2c_fd) < 0) {
        log_error("Sensor initialization failed");
        cleanup();
        return EXIT_FAILURE;
    }

    g_csv_fp = fopen(g_filename, "a");
    if (!g_csv_fp) {
        log_error("Failed to open CSV file");
        cleanup();
        return EXIT_FAILURE;
    }

    fseek(g_csv_fp, 0, SEEK_END);
    if (ftell(g_csv_fp) == 0) {
        fprintf(g_csv_fp, "timestamp,x_g,y_g,z_g\n");
        fflush(g_csv_fp);
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    sigaction(SIGINT, &sa, NULL);
    sigaction(SIGTERM, &sa, NULL);

    printf("Logging seismic data to %s at interval %d s (I2C addr 0x%02X)...\n", g_filename, g_interval, g_i2c_addr);

    while (g_running) {
        float x, y, z;
        int ok = 0;
        for (int attempt = 0; attempt < MAX_RETRIES && g_running; attempt++) {
            if (read_acceleration(g_i2c_fd, &x, &y, &z) == 0) { ok = 1; break; }
            log_error("I2C read failed, retrying...");
            usleep(RETRY_DELAY_MS * 1000);
        }
        if (!ok) {
            log_error("Max retries reached, skipping sample");
            sleep(g_interval);
            continue;
        }

        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char ts[32];
        strftime(ts, sizeof(ts), "%Y-%m-%d %H:%M:%S", t);
        fprintf(g_csv_fp, "%s,%.3f,%.3f,%.3f\n", ts, x, y, z);
        fflush(g_csv_fp);
        sleep(g_interval);
    }

    printf("\nShutting down gracefully...\n");
    cleanup();
    return EXIT_SUCCESS;
}

