/*
 * AWR1642 mmWave radar UART reader for Raspberry Pi 3 Model B+
 *
 * Reads the documented 8-byte little-endian magic word, validates TLV
 * payloads, extracts range (m) and velocity (m/s) for every detected
 * object, and appends rows to radar_data.csv.
 *
 * Wiring:
 *   AWR1642 UART_TX  -> Pi GPIO15 (RXD, pin 10)
 *   AWR1642 UART_RX  -> Pi GPIO14 (TXD, pin  8)
 *   AWR1642 GND      -> Pi GND
 *   AWR1642 VIO      -> 3.3 V (or 1.8 V per datasheet)
 *
 * Build:
 *   gcc -O2 -Wall -Wextra -o radar radar.c -lm
 *
 * Run:
 *   ./radar
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <math.h>

#include "mmw_sdk.h"

#define UART_DEVICE      "/dev/ttyS0"
#define BAUD_RATE        921600
#define CSV_FILENAME     "radar_data.csv"
#define READ_BUF_SIZE    4096
#define FRAME_BUF_SIZE   8192
#define MAGIC_WORD       0x02040306ULL  /* AWR1642 little-endian magic word */
#define TLV_HEADER_SIZE  8
#define TLV_TYPE_DETECTED_POINTS 1
#define TLV_TYPE_RANGE_PROFILE   2
#define TLV_TYPE_AZIMUTH_HEAT_MAP 3
#define TLV_TYPE_RANGE_DOPPLER   4
#define TLV_TYPE_STATS           5
#define TLV_TYPE_NOISE_PROFILE   6
#define TLV_TYPE_AZIMUTH_STATS   7
#define TLV_TYPE_TARGET_LIST     8

/* AWR1642 SDK TLV structures (packed, little-endian) */
#pragma pack(push, 1)
typedef struct {
    uint32_t type;
    uint32_t length;
} tlv_header_t;

typedef struct {
    uint16_t num_detected_obj;
    uint16_t xyz_q_format;
} detected_points_header_t;

typedef struct {
    uint16_t range_idx;
    uint16_t doppler_idx;
    uint16_t peak_val;
    uint16_t x;
    uint16_t y;
    uint16_t z;
    uint16_t velocity;
} detected_point_t;
#pragma pack(pop)

static volatile sig_atomic_t g_running = 1;
static int  g_uart_handle = -1;
static FILE *g_csv_file   = NULL;

/* ------------------------------------------------------------------ */
static void signal_handler(int sig)
{
    (void)sig;
    g_running = 0;
}

/* ------------------------------------------------------------------ */
static void cleanup(void)
{
    if (g_uart_handle >= 0) {
        mmw_sdk_uart_close(g_uart_handle);
        g_uart_handle = -1;
    }
    if (g_csv_file) {
        fflush(g_csv_file);
        fclose(g_csv_file);
        g_csv_file = NULL;
    }
}

/* ------------------------------------------------------------------ */
static void get_timestamp(char *buf, size_t len)
{
    time_t now = time(NULL);
    struct tm tmv;
    localtime_r(&now, &tmv);
    strftime(buf, len, "%Y-%m-%d %H:%M:%S", &tmv);
}

/* ------------------------------------------------------------------ */
static void log_error(const char *msg)
{
    char ts[32];
    get_timestamp(ts, sizeof(ts));
    fprintf(stderr, "[%s] ERROR: %s (errno=%d: %s)\n",
            ts, msg, errno, strerror(errno));
}

/* ------------------------------------------------------------------ */
/*
 * Scan buf for the 8-byte magic word.  Returns the index of the first
 * byte of the magic word, or -1 if not found.
 */
static int find_magic_word(const uint8_t *buf, size_t len)
{
    if (len < 8)
        return -1;
    for (size_t i = 0; i + 8 <= len; i++) {
        uint64_t word = 0;
        for (int b = 0; b < 8; b++)
            word |= (uint64_t)buf[i + b] << (b * 8);
        if (word == MAGIC_WORD)
            return (int)i;
    }
    return -1;
}

/* ------------------------------------------------------------------ */
/*
 * Parse a complete frame starting at frame_start.
 * frame_start points to the 8-byte magic word.
 * frame_len  is the total number of bytes in the frame.
 */
static void parse_frame(const uint8_t *frame_start, size_t frame_len)
{
    if (frame_len < 8) {
        log_error("Frame too short for header");
        return;
    }

    /* Frame header (little-endian): magic(8) + version(4) + total_packet_len(4)
     * + platform(4) + frame_number(4) + time_cpt(4) + num_detected_obj(4)
     * + num_tlv(4) + sub_frame_num(4)
     */
    const uint8_t *hdr = frame_start;
    uint32_t total_packet_len = 0;
    uint32_t num_detected_obj = 0;
    uint32_t num_tlv          = 0;

    memcpy(&total_packet_len, hdr + 8, 4);
    memcpy(&num_detected_obj, hdr + 20, 4);
    memcpy(&num_tlv,          hdr + 28, 4);

    if (total_packet_len < 8 || total_packet_len > FRAME_BUF_SIZE) {
        log_error("Invalid total_packet_len");
        return;
    }
    if (total_packet_len > frame_len) {
        log_error("Frame truncated");
        return;
    }

    const uint8_t *tlv_start = frame_start + 8 + 24;  /* after header + platform */
    size_t tlv_remaining = total_packet_len - 8 - 24;

    for (uint32_t t = 0; t < num_tlv && tlv_remaining >= TLV_HEADER_SIZE; t++) {
        tlv_header_t tlv;
        memcpy(&tlv, tlv_start, TLV_HEADER_SIZE);

        if (tlv.length > tlv_remaining - TLV_HEADER_SIZE) {
            log_error("TLV length exceeds frame");
            break;
        }

        const uint8_t *payload = tlv_start + TLV_HEADER_SIZE;

        if (tlv.type == TLV_TYPE_DETECTED_POINTS) {
            if (tlv.length < sizeof(detected_points_header_t)) {
                log_error("Detected points TLV too short");
            } else {
                detected_points_header_t hdr;
                memcpy(&hdr, payload, sizeof(hdr));
                uint16_t num_obj = hdr.num_detected_obj;
                uint16_t q_fmt   = hdr.xyz_q_format;
                size_t expected  = sizeof(hdr) + (size_t)num_obj * sizeof(detected_point_t);

                if (tlv.length < expected) {
                    log_error("Detected points TLV payload too short");
                } else {
                    const detected_point_t *pts =
                        (const detected_point_t *)(payload + sizeof(hdr));
                    for (uint16_t i = 0; i < num_obj; i++) {
                        float range_m = (float)pts[i].range_idx / 100.0f;
                        float vel_mps = (float)pts[i].velocity / 100.0f;
                        char ts[32];
                        get_timestamp(ts, sizeof(ts));
                        fprintf(g_csv_file, "%s,%u,%.2f,%.2f\n",
                                ts, i, range_m, vel_mps);
                    }
                    fflush(g_csv_file);
                }
            }
        }
        /* Other TLV types (range profile, heat map, etc.) are skipped */

        tlv_start += TLV_HEADER_SIZE + tlv.length;
        tlv_remaining -= TLV_HEADER_SIZE + tlv.length;
    }
}

/* ------------------------------------------------------------------ */
int main(void)
{
    /* Install signal handlers for clean shutdown */
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGINT, &sa, NULL) != 0 || sigaction(SIGTERM, &sa, NULL) != 0) {
        log_error("sigaction failed");
        return EXIT_FAILURE;
    }

    /* Open CSV file in append mode */
    g_csv_file = fopen(CSV_FILENAME, "a");
    if (!g_csv_file) {
        log_error("Failed to open CSV file");
        return EXIT_FAILURE;
    }
    fprintf(g_csv_file, "# AWR1642 radar data\n");
    fprintf(g_csv_file, "# timestamp,object_index,range_m,velocity_mps\n");
    fflush(g_csv_file);

    /* Initialize SDK (required for UART) */
    if (mmw_sdk_init() != 0) {
        log_error("mmw_sdk_init failed");
        cleanup();
        return EXIT_FAILURE;
    }

    /* Open UART */
    g_uart_handle = mmw_sdk_uart_open(UART_DEVICE, BAUD_RATE);
    if (g_uart_handle < 0) {
        log_error("mmw_sdk_uart_open failed");
        cleanup();
        return EXIT_FAILURE;
    }

    uint8_t read_buf[READ_BUF_SIZE];
    uint8_t frame_buf[FRAME_BUF_SIZE];
    size_t  frame_len = 0;

    printf("Radar data acquisition started. Press Ctrl+C to stop.\n");

    while (g_running) {
        ssize_t n = mmw_sdk_uart_read(g_uart_handle, read_buf, sizeof(read_buf));
        if (n < 0) {
            log_error("mmw_sdk_uart_read failed");
            break;
        }
        if (n == 0) {
            /* No data available right now; brief sleep to avoid busy-loop */
            usleep(10000);
            continue;
        }

        /* Append to frame buffer */
        if (frame_len + (size_t)n > FRAME_BUF_SIZE) {
            /* Overflow: discard current frame and resync */
            log_error("Frame buffer overflow, resyncing");
            frame_len = 0;
        }
        memcpy(frame_buf + frame_len, read_buf, (size_t)n);
        frame_len += (size_t)n;

        /* Try to find magic word and parse complete frames */
        while (g_running && frame_len >= 8) {
            int mw_idx = find_magic_word(frame_buf, frame_len);
            if (mw_idx < 0) {
                /* No magic word found; keep last 7 bytes in case
                 * the magic word spans reads */
                if (frame_len > 7) {
                    memmove(frame_buf, frame_buf + frame_len - 7, 7);
                    frame_len = 7;
                }
                break;
            }

            /* Discard bytes before magic word */
            if (mw_idx > 0) {
                memmove(frame_buf, frame_buf + mw_idx, frame_len - (size_t)mw_idx);
                frame_len -= (size_t)mw_idx;
            }

            /* Need at least the 8-byte magic + 24-byte header to know
             * total_packet_len */
            if (frame_len < 8 + 24)
                break;

            uint32_t total_packet_len = 0;
            memcpy(&total_packet_len, frame_buf + 8, 4);

            if (total_packet_len < 8 || total_packet_len > FRAME_BUF_SIZE) {
                log_error("Invalid total_packet_len, resyncing");
                /* Discard magic word and resync */
                memmove(frame_buf, frame_buf + 8, frame_len - 8);
                frame_len -= 8;
                continue;
            }

            if (frame_len < total_packet_len) {
                /* Incomplete frame; wait for more data */
                break;
            }

            /* Complete frame available */
            parse_frame(frame_buf, total_packet_len);

            /* Remove parsed frame from buffer */
            memmove(frame_buf, frame_buf + total_packet_len,
                    frame_len - total_packet_len);
            frame_len -= total_packet_len;
        }
    }

    printf("\nShutting down...\n");
    cleanup();
    return EXIT_SUCCESS;
}

