#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define LEFT_SENSOR_PIN  4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN  27

#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE 115200

static volatile sig_atomic_t running = 1;
static int uart_handle = -1;

static void signal_handler(int sig) {
    (void)sig;
    running = 0;
}

static int read_sensor(int pin) {
    return gpioRead(pin);
}

static void log_sensor_data(int left, int middle, int right) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    if (timeinfo == NULL) {
        fprintf(stderr, "Error: localtime() failed\n");
        return;
    }

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s - Left: %d, Middle: %d, Right: %d\n", timestamp, left, middle, right);
    fflush(stdout);
}

static int send_emergency_stop(void) {
    const char *message = "EMERGENCY STOP!\n";
    int result = serWrite(uart_handle, message, strlen(message));
    if (result < 0) {
        fprintf(stderr, "Error: Failed to write to UART (pigpio error %d)\n", result);
        return -1;
    }
    return 0;
}

int main(void) {
    int left, middle, right;

    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);

    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0);
    if (uart_handle < 0) {
        fprintf(stderr, "Error: Failed to open UART %s (pigpio error %d)\n", UART_DEVICE, uart_handle);
        gpioTerminate();
        return 1;
    }

    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;

    if (sigaction(SIGINT, &sa, NULL) != 0) {
        perror("sigaction(SIGINT)");
    }
    if (sigaction(SIGTERM, &sa, NULL) != 0) {
        perror("sigaction(SIGTERM)");
    }

    printf("KY-033 3-Way Tracking Sensor Monitor\n");
    printf("Left=GPIO4, Middle=GPIO17, Right=GPIO27\n");
    printf("UART: %s @ %d baud\n", UART_DEVICE, BAUD_RATE);
    printf("Press Ctrl+C to exit.\n");
    fflush(stdout);

    while (running) {
        left = read_sensor(LEFT_SENSOR_PIN);
        middle = read_sensor(MIDDLE_SENSOR_PIN);
        right = read_sensor(RIGHT_SENSOR_PIN);

        log_sensor_data(left, middle, right);

        if (left == 0 && middle == 0 && right == 0) {
            if (send_emergency_stop() != 0) {
                fprintf(stderr, "Warning: Emergency stop message could not be sent\n");
            }
        }

        gpioDelay(100000);
    }

    printf("\nShutting down...\n");

    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    gpioTerminate();

    return 0;
}

